INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-charla-informal','es-1','es-1-people','שיחת היכרות','Charla informal','לשאול שאלות ולהציג אדם באמצעות משפטי תיאור.','workbook','[{"he":"שאלות","target":"Preguntas"},{"he":"משפטי תיאור","target":"ser · estar · gustar"}]','["שאלות","ser ו־estar"]','{"rules":["מילות שאלה נושאות תמיד סימן הטעמה: ¿Cómo? ¿Dónde? ¿Cuándo? ¿Por qué? ¿De dónde?","משתמשים ב־ser לזהות ולמאפיינים וב־estar למצב ולמיקום. זו אינה חלוקה מוחלטת בין קבוע לזמני.","עם שם עצם יחיד או שם פועל משתמשים ב־gusta, ועם שם עצם ברבים ב־gustan."],"examples":["¿Dónde vives? Vivo en Haifa.","Soy profesor. Estoy en casa.","Me gusta leer. Me gustan los libros.","¿De dónde eres? Soy de Israel. ¿Por qué estudias español?"],"tips":["בספרדית ההטעמה קובעת משמעות. במילות שאלה הסימן מעל האות מסמן גם את ההטעמה וגם שזו שאלה: ¿Cómo? לעומת como."],"mistakes":[{"text":"בהווה פשוט הפועל הספרדי נושא את סימון הגוף. אין להוסיף לפניו ser: Yo trabajo. הפועל gustar מתאים את עצמו לדבר שאוהבים, ולא לאדם.","pairs":[{"bad":"Yo soy trabajo","good":"Yo trabajo"},{"bad":"Me gusta los libros","good":"Me gustan los libros"}]}]}','[{"term":"adivinar","he":"לנחש"},{"term":"al extranjero","he":"לחוץ לארץ"},{"term":"amar / gustar","he":"לאהוב / לחבב"},{"term":"amigo","he":"חבר"},{"term":"animales","he":"בעלי חיים"},{"term":"bailar","he":"לרקוד"},{"term":"cada día","he":"כל יום"},{"term":"casado","he":"נשוי"},{"term":"comida","he":"אוכל / אוכל או ארוחה"},{"term":"cómo","he":"איך"},{"term":"compañero","he":"עמית / בן זוג לפעילות"},{"term":"conocer","he":"להכיר / לפגוש לראשונה"},{"term":"cuál","he":"איזה"},{"term":"cuándo","he":"מתי"},{"term":"cuántos","he":"כמה"},{"term":"de dónde","he":"מאיפה"},{"term":"decir","he":"לומר"},{"term":"deporte","he":"ספורט"},{"term":"doctor","he":"רופא"},{"term":"dónde","he":"איפה"},{"term":"dos veces por semana","he":"פעמיים בשבוע"},{"term":"él","he":"הוא"},{"term":"ella","he":"היא"},{"term":"ellas","he":"הן"},{"term":"ellos","he":"הם"},{"term":"en una relación","he":"במערכת יחסים"},{"term":"estar","he":"להיות במצב או במקום / להיות"},{"term":"estudiar","he":"ללמוד"},{"term":"famoso","he":"מפורסם"},{"term":"favorito","he":"מועדף / אהוב"},{"term":"fútbol","he":"כדורגל"},{"term":"hablar","he":"לדבר"},{"term":"hacer","he":"לעשות"},{"term":"hermana","he":"אחות"},{"term":"hermano","he":"אח"},{"term":"hermanos y hermanas","he":"אחים ואחיות"},{"term":"hija","he":"בת"},{"term":"hijo","he":"בן"},{"term":"hijos","he":"ילדים / בנים"},{"term":"hockey","he":"הוקי"},{"term":"hola","he":"שלום"},{"term":"hombre","he":"גבר"},{"term":"importante","he":"חשוב"},{"term":"ir","he":"ללכת / ללכת / לנסוע"},{"term":"leer","he":"לקרוא"},{"term":"libro","he":"ספר / סֵפֶר"},{"term":"llamarse","he":"להיקרא בשם"},{"term":"lugar","he":"מקום"},{"term":"madre","he":"אם / אמא"},{"term":"niños","he":"ילדים"},{"term":"no","he":"לא"},{"term":"nombre","he":"שם"},{"term":"nosotras","he":"אנחנו בנקבה"},{"term":"nosotros","he":"אנחנו בזכר או בקבוצה מעורבת"},{"term":"país","he":"מדינה / ארץ / מדינה"},{"term":"pasatiempo","he":"תחביב"},{"term":"perro","he":"כלב"},{"term":"persona","he":"אדם"},{"term":"playa","he":"חוף / חוף ים / חוֹף"},{"term":"por qué","he":"למה"},{"term":"porque","he":"מפני ש־"},{"term":"preguntar","he":"לשאול"},{"term":"probar","he":"לנסות / לטעום"},{"term":"profesor","he":"מורה"},{"term":"qué","he":"מה"},{"term":"quién","he":"מי"},{"term":"restaurante","he":"מסעדה"},{"term":"sábado","he":"שבת"},{"term":"semana","he":"שבוע"},{"term":"ser","he":"להיות"},{"term":"sí","he":"כן"},{"term":"soltero","he":"רווק"},{"term":"tener","he":"יש ל־ / להיות בעל"},{"term":"tiempo libre","he":"זמן פנוי"},{"term":"todos los días","he":"בכל יום / כל יום"},{"term":"trabajar","he":"לעבוד"},{"term":"tú","he":"אתה / את"},{"term":"usted","he":"אתה / את בפנייה רשמית"},{"term":"ustedes","he":"אתם / אתן"},{"term":"viajar","he":"לטייל / לנסוע"},{"term":"vivir","he":"לגור / לחיות"},{"term":"vosotras","he":"אתן בשימוש בספרד"},{"term":"vosotros","he":"אתם בשימוש בספרד"},{"term":"yo","he":"אני"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/1053409868/small-talk-basic-spanish-flash-cards/"}]','published','workbook L1 unit 01',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-charla-informal-01','es1-charla-informal','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"שם ___","input":"text"},{"prompt":"לגור ___","input":"text"},{"prompt":"לעבוד ___","input":"text"},{"prompt":"זמן פנוי ___","input":"text"}]}','{"items":[{"display":"nombre","answers":["nombre"]},{"display":"vivir","answers":["vivir"]},{"display":"trabajar","answers":["trabajar"]},{"display":"tiempo libre","answers":["tiempo libre"]}],"policy":{"accents":"lenient"}}','published','L1-U01-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-charla-informal-02','es1-charla-informal','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"¿___ te llamas?","input":"choice","options":["Cómo","Dónde"]},{"prompt":"¿___ trabajas? En una escuela.","input":"choice","options":["Dónde","Quién"]},{"prompt":"Yo ___ de Israel.","input":"choice","options":["soy","estoy"]},{"prompt":"Ana ___ en casa ahora.","input":"choice","options":["es","está"]},{"prompt":"Me ___ viajar.","input":"choice","options":["gusta","gustan"]},{"prompt":"A Luis le ___ los animales.","input":"choice","options":["gusta","gustan"]},{"prompt":"¿___ eres? Soy de Israel.","input":"choice","options":["De dónde","Dónde"]},{"prompt":"¿___ estudias español? Porque me gusta viajar.","input":"choice","options":["Por qué","Cuándo"]}]}','{"items":[{"display":"Cómo","choice":0},{"display":"Dónde","choice":0},{"display":"soy","choice":0},{"display":"está","choice":1},{"display":"gusta","choice":0},{"display":"gustan","choice":1},{"display":"De dónde","choice":0},{"display":"Por qué","choice":0}],"policy":{"accents":"strict"}}','published','L1-U01-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-charla-informal-03','es1-charla-informal','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"Yo soy trabajo en una escuela.","input":"sentence"},{"prompt":"Me gusta los libros.","input":"sentence"},{"prompt":"Soy en casa hoy.","input":"sentence"},{"prompt":"¿Donde vives?","input":"sentence"}]}','{"items":[{"display":"Yo trabajo en una escuela.","answers":["Yo trabajo en una escuela."]},{"display":"Me gustan los libros.","answers":["Me gustan los libros."]},{"display":"Estoy en casa hoy.","answers":["Estoy en casa hoy."]},{"display":"¿Dónde vives?","answers":["¿Dónde vives?"]}],"policy":{"accents":"strict"}}','published','L1-U01-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-charla-informal-04','es1-charla-informal','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"Yo vivo en Haifa. → Ella…","input":"sentence"},{"prompt":"Soy profesor. → שלילה","input":"sentence"},{"prompt":"Me llamo Ana. → שאלה הפותחת ב־Cómo","input":"sentence"}]}','{"items":[{"display":"Ella vive en Haifa.","answers":["Ella vive en Haifa."]},{"display":"No soy profesor.","answers":["No soy profesor."]},{"display":"¿Cómo te llamas?","answers":["¿Cómo te llamas?"]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U01-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-charla-informal-05','es1-charla-informal','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"אני גר בתל אביב.","input":"sentence"},{"prompt":"איך קוראים לך?","input":"sentence"},{"prompt":"אני אוהב לקרוא ולטייל.","input":"sentence"},{"prompt":"היא לא מורה, היא רופאה.","input":"sentence"}]}','{"items":[{"display":"Vivo en Tel Aviv.","answers":["Vivo en Tel Aviv."]},{"display":"¿Cómo te llamas?","answers":["¿Cómo te llamas?"]},{"display":"Me gusta leer y viajar.","answers":["Me gusta leer y viajar."]},{"display":"Ella no es profesora, es doctora.","answers":["Ella no es profesora, es doctora."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U01-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-charla-informal-06','es1-charla-informal','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿De dónde es Clara?","input":"sentence"},{"prompt":"¿Dónde trabaja Clara?","input":"sentence"},{"prompt":"¿Qué le gusta hacer?","input":"sentence"}],"text":"Me llamo Clara. Soy de Argentina y vivo en Haifa. Trabajo en una escuela.\nEstoy en casa hoy. Me gusta leer y me gustan los animales.\nMi hermano se llama Leo. Él vive en Tel Aviv y trabaja en un restaurante."}','{"items":[{"display":"Es de Argentina.","answers":["Es de Argentina."]},{"display":"Trabaja en una escuela.","answers":["Trabaja en una escuela."]},{"display":"Le gusta leer.","answers":["Le gusta leer."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U01-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-charla-informal-07','es1-charla-informal','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Dónde vives?\n¿Qué te gusta hacer en tu tiempo libre?\n¿Quién es una persona importante para ti?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U01-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-charla-informal-08','es1-charla-informal','open','writing','כתיבה','כתבו פרופיל להיכרות של 5 משפטים: שם, מוצא, מקום מגורים, עיסוק ותחביב. הוסיפו שתי שאלות שהייתם שואלים אדם חדש.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Me llamo Noa. Soy de Israel. Vivo en Haifa. Trabajo en una escuela. Me gusta bailar. ¿Dónde vives? ¿Qué te gusta hacer?"],"criteria":""}','published','L1-U01-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-charla-informal-09','es1-charla-informal','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"Yo ___ en casa.","input":"choice","options":["soy","estoy"]},{"prompt":"Me gustan los ___.","input":"choice","options":["libro","libros"]}]}','{"items":[{"display":"estoy","choice":1},{"display":"libros","choice":1}],"policy":{"accents":"strict"}}','published','L1-U01-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-charla-informal-10','es1-charla-informal','open','speaking','אתגר לבחירה','הציגו אדם אחר בשלושה משפטים בגוף שלישי. לאחר מכן הקליטו את עצמכם מציגים אותו בלי לקרוא.','self','{"prompt":"","brief":"","note":"משימה פתוחה לבחירה: אין מפתח. אפשר להביא את הניסוח לשיעור."}','{"models":[],"criteria":""}','published','L1-U01-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-charla-informal-11','es1-charla-informal','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["qué","bailar","niños","ir","en una relación","deporte","hermana","nombre"],"right":[{"id":"A","text":"במערכת יחסים"},{"id":"B","text":"ללכת"},{"id":"C","text":"אחות"},{"id":"D","text":"מה"},{"id":"E","text":"ילדים"},{"id":"F","text":"ספורט"},{"id":"G","text":"לרקוד"},{"id":"H","text":"שם"}]}','{"pairs":["D","G","E","B","A","F","C","H"],"policy":{"accents":"lenient"}}','published','L1-U01-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-charla-informal-12','es1-charla-informal','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"Mi ___ es Lucía.","input":"bank"},{"prompt":"Yo ___ en Madrid.","input":"bank"},{"prompt":"Soy ___; no estoy casada.","input":"bank"},{"prompt":"Mi ___ se llama Pablo. Somos hijos de Ana.","input":"bank"},{"prompt":"En mi tiempo libre me gusta ___ libros.","input":"bank"},{"prompt":"¿De ___ eres? Soy de Israel.","input":"bank"}],"wordbank":["nombre","leer","dónde","hermano","soltera","vivo"]}','{"items":[{"display":"nombre","answers":["nombre"]},{"display":"vivo","answers":["vivo"]},{"display":"soltera","answers":["soltera"]},{"display":"hermano","answers":["hermano"]},{"display":"leer","answers":["leer"]},{"display":"dónde","answers":["dónde"]}],"policy":{"accents":"strict"}}','published','L1-U01-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-charla-informal-13','es1-charla-informal','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"Vivo en Madrid.","cue":"él","input":"sentence"},{"prompt":"Me gusta leer.","cue":"ella","input":"sentence"},{"prompt":"Soy profesor.","cue":"nosotros","input":"sentence"},{"prompt":"Estoy en casa.","cue":"tú","input":"sentence"}]}','{"items":[{"display":"Él vive en Madrid.","answers":["Él vive en Madrid."]},{"display":"A ella le gusta leer.","answers":["A ella le gusta leer."]},{"display":"Nosotros somos profesores.","answers":["Nosotros somos profesores."]},{"display":"Tú estás en casa.","answers":["Tú estás en casa."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U01-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-charla-informal-14','es1-charla-informal','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"Me llamo Luis. ¿De dónde eres, Ana?"},{"id":"B","text":"Soy de España. ¿Dónde vives ahora?"},{"id":"C","text":"Soy de Israel. ¿Y tú?"},{"id":"D","text":"Hola, soy Ana. ¿Cómo te llamas?"},{"id":"E","text":"Vivo en Haifa."}]}','{"order":["D","A","C","B","E"],"policy":{"accents":"strict"}}','published','L1-U01-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-charla-informal-15','es1-charla-informal','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Dónde vive Lucía?","input":"sentence"},{"prompt":"¿En qué trabaja Lucía?","input":"sentence"},{"prompt":"¿Cuántos hijos tiene Pablo?","input":"sentence"},{"prompt":"¿Qué le gusta hacer a Inés?","input":"sentence"}],"text":"Me llamo Lucía y vivo en Madrid. Soy profesora y estoy soltera. Mi hermano Pablo tiene dos hijos. Él trabaja en una escuela. Los sábados leo con mi amiga Inés. A mí me gusta viajar y a Inés le gusta bailar. A las dos nos gustan los libros y los animales."}','{"items":[{"display":"Vive en Madrid.","answers":["Vive en Madrid."]},{"display":"Es profesora.","answers":["Es profesora."]},{"display":"Tiene dos hijos.","answers":["Tiene dos hijos."]},{"display":"Le gusta bailar.","answers":["Le gusta bailar."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U01-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-charla-informal-16','es1-charla-informal','open','writing','כותבים לחיים','כתבו הצגה עצמית והציגו גם אדם קרוב. ציינו שם, מקום מגורים, עיסוק ותחביבים. שלבו לפחות שאלה אחת ומשפט אחד עם gusta או gustan.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Me llamo Daniel y vivo en Haifa. Soy profesor y trabajo en una escuela. En mi tiempo libre me gusta leer libros. Mi hermana se llama Sara y vive en Madrid. A ella le gustan los animales y le gusta viajar. ¿Qué te gusta hacer en tu tiempo libre?"],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U01-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-familia','es-1','es-1-people','משפחה','Familia','להשתמש בכינויי שייכות ולמסור גיל ותאריך.','workbook','[{"he":"שייכות","target":"Posesivos"},{"he":"תאריכים ומספרים","target":"tener + años"}]','["שייכות","תאריכים"]','{"rules":["כינוי השייכות בא לפני שם העצם ומתאים לדבר השייך, לא לבעלים: mi / mis, ו־nuestro משתנה גם במין.","לגיל משתמשים ב־tener ולא ב־ser.","בתאריך כותבים יום, אחר כך de, ואז החודש. שמות החודשים נכתבים באות קטנה."],"examples":["mi hermana / mis hermanas","nuestro padre / nuestra madre","Tiene veinte años. Su cumpleaños es el quince de mayo.","veinte · treinta · cuarenta · cincuenta"],"tips":["cumpleaños נשאר זהה ביחיד וברבים. אומרים un cumpleaños וגם dos cumpleaños."],"mistakes":[{"text":"בעברית השייכות באה אחרי שם העצם (\"אמא שלי\") ובספרדית לפניו. בנוסף, הכינוי מתאים לדבר השייך ולא למי שמחזיק בו, ולכן אומרים nuestra madre גם כשמדובר בגברים.","pairs":[{"bad":"la madre mi","good":"mi madre"},{"bad":"Mi padre es cuarenta años","good":"Mi padre tiene cuarenta años"}]}]}','[{"term":"a mí","he":"לי, להדגשה כגון a mí me gusta"},{"term":"abril","he":"אפריל"},{"term":"abuela","he":"סבתא"},{"term":"abuelo","he":"סבא"},{"term":"abuelos","he":"סבים"},{"term":"agosto","he":"אוגוסט"},{"term":"almorzar","he":"לאכול ארוחת צהריים"},{"term":"año","he":"שנה"},{"term":"antes","he":"לפני"},{"term":"árbol genealógico","he":"עץ משפחה"},{"term":"auto","he":"מכונית"},{"term":"autobús","he":"אוטובוס"},{"term":"avión","he":"מטוס"},{"term":"barco","he":"סירה / אונייה"},{"term":"café","he":"בית קפה / קפה / קפה / קָפֶה"},{"term":"catorce","he":"ארבע עשרה"},{"term":"celebrar","he":"לחגוג"},{"term":"cien","he":"מאה"},{"term":"cinco","he":"חמש"},{"term":"cincuenta","he":"חמישים"},{"term":"comer","he":"לאכול / לֶאֱכוֹל"},{"term":"cronograma","he":"לוח זמנים"},{"term":"cuarenta","he":"ארבעים"},{"term":"cuatro","he":"ארבע"},{"term":"cumpleaños","he":"יום הולדת"},{"term":"cuñada","he":"גיסה"},{"term":"cuñado","he":"גיס"},{"term":"después","he":"אחרי / אחר כך"},{"term":"destino","he":"יעד"},{"term":"día festivo","he":"חג"},{"term":"diciembre","he":"דצמבר"},{"term":"diecinueve","he":"תשע עשרה"},{"term":"dieciocho","he":"שמונה עשרה"},{"term":"dieciséis","he":"שש עשרה"},{"term":"diecisiete","he":"שבע עשרה"},{"term":"diez","he":"עשר"},{"term":"doce","he":"שתים עשרה"},{"term":"domingo","he":"יום ראשון / רִאשׁוֹן (יוֹם)"},{"term":"dos","he":"שתיים"},{"term":"enero","he":"ינואר"},{"term":"esposa","he":"אישה נשואה / רעיה / רעיה"},{"term":"esposo","he":"בעל"},{"term":"familia","he":"משפחה"},{"term":"favorito","he":"מועדף / אהוב"},{"term":"febrero","he":"פברואר"},{"term":"fecha","he":"תאריך"},{"term":"hablar","he":"לדבר"},{"term":"hermana","he":"אחות"},{"term":"hermano","he":"אח"},{"term":"hija","he":"בת"},{"term":"hijo","he":"בן"},{"term":"hogar","he":"בית / בית רגשי"},{"term":"jueves","he":"יום חמישי"},{"term":"julio","he":"יולי"},{"term":"junio","he":"יוני"},{"term":"llamarse","he":"להיקרא בשם"},{"term":"lunes","he":"יום שני"},{"term":"madre","he":"אם / אמא"},{"term":"mamá","he":"אמא"},{"term":"martes","he":"יום שלישי"},{"term":"marzo","he":"מרץ"},{"term":"mayo","he":"מאי"},{"term":"mes","he":"חודש"},{"term":"mi","he":"שלי"},{"term":"miércoles","he":"יום רביעי"},{"term":"mis","he":"שלי לפני שם ברבים / שלי (רבים)"},{"term":"museo","he":"מוזיאון"},{"term":"noventa","he":"תשעים"},{"term":"noviembre","he":"נובמבר"},{"term":"nuestra","he":"שלנו לפני שם בנקבה / שלנו (נקבה)"},{"term":"nuestras","he":"שלנו לפני שם בנקבה רבות"},{"term":"nuestro","he":"שלנו לפני שם בזכר / שלנו"},{"term":"nuestros","he":"שלנו לפני שם בזכר רבים"},{"term":"nueve","he":"תשע"},{"term":"ochenta","he":"שמונים"},{"term":"ocho","he":"שמונה"},{"term":"octubre","he":"אוקטובר"},{"term":"once","he":"אחת עשרה"},{"term":"padre","he":"אבא"},{"term":"padres","he":"הורים"},{"term":"papá","he":"אבא"},{"term":"persona","he":"אדם"},{"term":"preparar","he":"להכין"},{"term":"prima","he":"בת דודה"},{"term":"primo","he":"בן דוד"},{"term":"quince","he":"חמש עשרה"},{"term":"recorrido","he":"סיור"},{"term":"reunirse","he":"להיפגש"},{"term":"río","he":"נהר"},{"term":"sábado","he":"שבת"},{"term":"seis","he":"שש"},{"term":"septiembre","he":"ספטמבר"},{"term":"sesenta","he":"שישים"},{"term":"setenta","he":"שבעים"},{"term":"siete","he":"שבע"},{"term":"sobrina","he":"אחיינית"},{"term":"sobrino","he":"אחיין"},{"term":"su","he":"שלו / שלה / שלו / שלה / שלהם / שלו/שלה/שלהם"},{"term":"suegra","he":"חמות"},{"term":"suegro","he":"חם"},{"term":"sus","he":"שלו / שלה / שלהם לפני שם ברבים / שלהם/שלה"},{"term":"tomar","he":"לקחת / לנסוע בתחבורה"},{"term":"trece","he":"שלוש עשרה"},{"term":"treinta","he":"שלושים"},{"term":"treinta y uno","he":"שלושים ואחת"},{"term":"tres","he":"שלוש"},{"term":"tu","he":"שלך"},{"term":"tus","he":"שלך לפני שם ברבים / שלך (רבים)"},{"term":"uno","he":"אחד / אחת"},{"term":"veinte","he":"עשרים"},{"term":"veinticinco","he":"עשרים וחמש"},{"term":"veinticuatro","he":"עשרים וארבע"},{"term":"veintidós","he":"עשרים ושתיים"},{"term":"veintinueve","he":"עשרים ותשע"},{"term":"veintiocho","he":"עשרים ושמונה"},{"term":"veintiséis","he":"עשרים ושש"},{"term":"veintisiete","he":"עשרים ושבע"},{"term":"veintitrés","he":"עשרים ושלוש"},{"term":"veintiuno","he":"עשרים ואחת"},{"term":"viajar","he":"לטייל / לנסוע"},{"term":"viaje","he":"נסיעה / טיול"},{"term":"viajero","he":"נוסע / מטייל / מטייל"},{"term":"viernes","he":"יום שישי"},{"term":"visita","he":"ביקור"},{"term":"visitar","he":"לבקר"},{"term":"volver","he":"לחזור"},{"term":"vuestra","he":"שלכם לפני שם בנקבה"},{"term":"vuestras","he":"שלכם לפני שם בנקבה רבות"},{"term":"vuestro","he":"שלכם בשימוש בספרד"},{"term":"vuestros","he":"שלכם לפני שם בזכר רבים"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/919800327/basic-spanish-family-flash-cards/"}]','published','workbook L1 unit 02',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-familia-01','es1-familia','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"אבא ___","input":"text"},{"prompt":"אמא ___","input":"text"},{"prompt":"אחות ___","input":"text"},{"prompt":"בן דוד ___","input":"text"}]}','{"items":[{"display":"padre","answers":["padre"]},{"display":"madre","answers":["madre"]},{"display":"hermana","answers":["hermana"]},{"display":"primo","answers":["primo"]}],"policy":{"accents":"lenient"}}','published','L1-U02-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-familia-02','es1-familia','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"Yo tengo dos hermanos. Son ___ hermanos.","input":"choice","options":["mi","mis"]},{"prompt":"Ana tiene una hermana. Es ___ hermana.","input":"choice","options":["su","sus"]},{"prompt":"Somos hermanos. Es ___ madre.","input":"choice","options":["nuestro","nuestra"]},{"prompt":"El cumpleaños es el cinco ___ junio.","input":"choice","options":["de","en"]},{"prompt":"Mi padre ___ cuarenta años.","input":"choice","options":["es","tiene"]},{"prompt":"Mis primas ___ en Madrid.","input":"choice","options":["vive","viven"]},{"prompt":"Es ___ familia.","input":"choice","options":["nuestro","nuestra"]},{"prompt":"16 → כתבו במילים","input":"text"}]}','{"items":[{"display":"mis","choice":1},{"display":"su","choice":0},{"display":"nuestra","choice":1},{"display":"de","choice":0},{"display":"tiene","choice":1},{"display":"viven","choice":1},{"display":"nuestra","choice":1},{"display":"dieciséis","answers":["dieciséis"]}],"policy":{"accents":"strict"}}','published','L1-U02-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-familia-03','es1-familia','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"La hermana mi se llama Ana.","input":"sentence"},{"prompt":"Mi padre es cuarenta años.","input":"sentence"},{"prompt":"Su cumpleaños es el quince de Mayo.","input":"sentence"},{"prompt":"Nuestro madre vive en Haifa.","input":"sentence"}]}','{"items":[{"display":"Mi hermana se llama Ana.","answers":["Mi hermana se llama Ana."]},{"display":"Mi padre tiene cuarenta años.","answers":["Mi padre tiene cuarenta años."]},{"display":"Su cumpleaños es el quince de mayo.","answers":["Su cumpleaños es el quince de mayo."]},{"display":"Nuestra madre vive en Haifa.","answers":["Nuestra madre vive en Haifa."]}],"policy":{"accents":"strict"}}','published','L1-U02-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-familia-04','es1-familia','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"mi primo → רבים","input":"sentence"},{"prompt":"nuestro hermano → נקבה יחידה","input":"sentence"},{"prompt":"23 de marzo → היום במילים","input":"sentence"}]}','{"items":[{"display":"mis primos","answers":["mis primos"]},{"display":"nuestra hermana","answers":["nuestra hermana"]},{"display":"veintitrés de marzo","answers":["veintitrés de marzo"]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U02-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-familia-05','es1-familia','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"אמא שלי גרה בחיפה.","input":"sentence"},{"prompt":"בת כמה האחות שלך?","input":"sentence"},{"prompt":"יום ההולדת שלו הוא בשלושה במאי.","input":"sentence"},{"prompt":"המשפחה שלנו קטנה.","input":"sentence"}]}','{"items":[{"display":"Mi madre vive en Haifa.","answers":["Mi madre vive en Haifa."]},{"display":"¿Cuántos años tiene tu hermana?","answers":["¿Cuántos años tiene tu hermana?"]},{"display":"Su cumpleaños es el tres de mayo.","answers":["Su cumpleaños es el tres de mayo."]},{"display":"Nuestra familia es pequeña.","answers":["Nuestra familia es pequeña."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U02-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-familia-06','es1-familia','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿Cómo se llama la madre de Mateo?","input":"sentence"},{"prompt":"¿Cuándo es su cumpleaños?","input":"sentence"},{"prompt":"¿Cuántas hermanas tiene Mateo?","input":"sentence"}],"text":"Soy Mateo. Mi madre se llama Elena y tiene cuarenta y cinco años.\nSu cumpleaños es el doce de abril. Mi padre se llama Pablo.\nTengo dos hermanas: Julia y Sara. Nuestras abuelas viven en Madrid.\nEn julio visitamos a nuestra familia."}','{"items":[{"display":"Se llama Elena.","answers":["Se llama Elena."]},{"display":"Es el doce de abril.","answers":["Es el doce de abril."]},{"display":"Tiene dos hermanas.","answers":["Tiene dos hermanas."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U02-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-familia-07','es1-familia','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Cómo se llama una persona de tu familia?\n¿Cuántos años tiene?\n¿Cuándo es su cumpleaños?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U02-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-familia-08','es1-familia','open','writing','כתיבה','כתבו 5 משפטים על המשפחה או על משפחה דמיונית: שני אנשים, גיל אחד, תאריך יום הולדת אחד ושלושה כינויי שייכות לפחות.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Mi hermana se llama Sara. Tiene veinte años. Su cumpleaños es el tres de mayo. Mis padres viven en Haifa. Nuestra familia es pequeña."],"criteria":""}','published','L1-U02-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-familia-09','es1-familia','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"Ella ___ de Argentina.","input":"choice","options":["es","está"]},{"prompt":"¿___ te llamas?","input":"choice","options":["Cómo","Qué"]}]}','{"items":[{"display":"es","choice":0},{"display":"Cómo","choice":0}],"policy":{"accents":"strict"}}','published','L1-U02-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-familia-10','es1-familia','open','speaking','אתגר לבחירה','הכינו לוח של שלושה ימי הולדת בחודשים שונים. כתבו את התאריכים במילים וסדרו אותם לפי סדר החודשים בשנה.','self','{"prompt":"","brief":"","note":"משימה פתוחה לבחירה: אין מפתח. אפשר להביא את הניסוח לשיעור."}','{"models":[],"criteria":""}','published','L1-U02-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-familia-11','es1-familia','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["sobrino","padre","persona","viajar","familia","avión","mes","hermana"],"right":[{"id":"A","text":"מטוס"},{"id":"B","text":"אחיין"},{"id":"C","text":"אחות"},{"id":"D","text":"אדם"},{"id":"E","text":"לטייל / לנסוע"},{"id":"F","text":"חודש"},{"id":"G","text":"משפחה"},{"id":"H","text":"אבא"}]}','{"pairs":["B","H","D","E","G","A","F","C"],"policy":{"accents":"lenient"}}','published','L1-U02-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-familia-12','es1-familia','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"El padre de mi madre es mi ___.","input":"bank"},{"prompt":"Mi hermano tiene una hija; ella es mi ___.","input":"bank"},{"prompt":"El mes después de junio es ___.","input":"bank"},{"prompt":"El 21 se escribe ___.","input":"bank"},{"prompt":"Mi padre y mi madre son mis ___.","input":"bank"},{"prompt":"Para organizar las fechas del viaje, preparo un ___.","input":"bank"}],"wordbank":["cronograma","abuelo","sobrina","veintiuno","julio","padres"]}','{"items":[{"display":"abuelo","answers":["abuelo"]},{"display":"sobrina","answers":["sobrina"]},{"display":"julio","answers":["julio"]},{"display":"veintiuno","answers":["veintiuno"]},{"display":"padres","answers":["padres"]},{"display":"cronograma","answers":["cronograma"]}],"policy":{"accents":"strict"}}','published','L1-U02-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-familia-13','es1-familia','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"Mi hermano vive aquí.","cue":"רבים","input":"sentence"},{"prompt":"Tu prima viaja en autobús.","cue":"רבים","input":"sentence"},{"prompt":"Nuestro hijo tiene diez años.","cue":"נקבה","input":"sentence"},{"prompt":"Su abuelo vive aquí.","cue":"נקבה","input":"sentence"}]}','{"items":[{"display":"Mis hermanos viven aquí.","answers":["Mis hermanos viven aquí."]},{"display":"Tus primas viajan en autobús.","answers":["Tus primas viajan en autobús."]},{"display":"Nuestra hija tiene diez años.","answers":["Nuestra hija tiene diez años."]},{"display":"Su abuela vive aquí.","answers":["Su abuela vive aquí."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U02-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-familia-14','es1-familia','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"Sí, con toda la familia."},{"id":"B","text":"El veinte de julio. ¿Viene Diego?"},{"id":"C","text":"¿Cuándo visitamos a los abuelos?"},{"id":"D","text":"Entonces, ¿celebramos su cumpleaños el veintiuno?"},{"id":"E","text":"Sí. Su cumpleaños es al día siguiente."}]}','{"order":["C","B","E","D","A"],"policy":{"accents":"strict"}}','published','L1-U02-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-familia-15','es1-familia','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Cuándo visita la familia a los abuelos?","input":"sentence"},{"prompt":"¿Cómo viaja la familia?","input":"sentence"},{"prompt":"¿De quién es el cumpleaños?","input":"sentence"},{"prompt":"¿Qué hace la familia el veintidós?","input":"sentence"}],"text":"Mi familia visita a mis abuelos el veinte de julio. Viajamos en autobús porque su casa está en otra ciudad. Mi hermano Diego cumple años el veintiuno de julio. Mi padre prepara el viaje y mi madre organiza el cronograma. El veintidós visitamos un museo con nuestros primos y después volvemos a casa."}','{"items":[{"display":"El veinte de julio.","answers":["El veinte de julio."]},{"display":"En autobús.","answers":["En autobús."]},{"display":"De Diego.","answers":["De Diego."]},{"display":"Visita un museo con sus primos y después vuelve a casa.","answers":["Visita un museo con sus primos y después vuelve a casa."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U02-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-familia-16','es1-familia','open','writing','כותבים לחיים','תכננו ביקור משפחתי. ציינו שני תאריכים במילים, שלושה קשרי משפחה ואמצעי תחבורה. השתמשו לפחות בשלוש צורות שייכות שונות.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Mi familia visita a mis abuelos el veinte de julio. Viajamos en autobús con nuestro primo. Su cumpleaños es el veintiuno de julio. Mi madre prepara la comida y mi padre organiza el cronograma. Nuestra visita termina el veintidós de julio. Después volvemos a casa con nuestros hermanos."],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U02-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-amistades','es-1','es-1-people','חברויות','Amistades','לתאר חברים ולספר על הפעולות שלהם בהווה.','workbook','[{"he":"תארים","target":"Adjetivos"},{"he":"פעלים בהווה","target":"presente simple"}]','["תארים","הווה"]','{"rules":["התואר מתאים במין ובמספר לשם העצם שהוא מתאר: creativa · creativas.","הפועל בהווה משתנה לפי הגוף. בגוף שלישי יחיד הפועל מסתיים ב־a בפעלי ar וב־e בפעלי er או ir: trabaja · come · vive.","השלילה no מופיעה מיד לפני הפועל, בלי פועל עזר."],"examples":["Mi amiga es creativa. Mis amigas son creativas.","Yo trabajo. Ella trabaja. Nosotros trabajamos.","Mi amigo no vive aquí."],"tips":["בספרדית התואר בא בדרך כלל אחרי שם העצם, הפוך מאנגלית וקרוב לעברית: una amiga creativa ולא una creativa amiga."],"mistakes":[{"text":"בעברית התואר כבר נושא את המין, ולכן קל לשכוח שגם בספרדית הוא משתנה: amiga creativa. ובנוסף, אין פועל עזר לפני הפועל: מי שמוסיף es לפני פועל מתרגם מאנגלית, לא מספרדית.","pairs":[{"bad":"Mi amiga es creativo","good":"Mi amiga es creativa"},{"bad":"Ella no es trabaja","good":"Ella no trabaja"}]}]}','[{"term":"a veces","he":"לפעמים"},{"term":"alto","he":"גבוה"},{"term":"amable","he":"אדיב"},{"term":"amigo","he":"חבר"},{"term":"amistad","he":"חברות"},{"term":"ayudar","he":"לעזור"},{"term":"bailar","he":"לרקוד"},{"term":"bajo","he":"נמוך"},{"term":"beber","he":"לשתות / לִשְׁתּוֹת"},{"term":"celebrar","he":"לחגוג"},{"term":"chisme","he":"רכילות"},{"term":"cine","he":"קולנוע"},{"term":"cocinar","he":"לבשל"},{"term":"comer","he":"לאכול / לֶאֱכוֹל"},{"term":"compartir","he":"לשתף"},{"term":"comprensivo","he":"מבין ומתחשב"},{"term":"confiar","he":"לבטוח"},{"term":"costumbre","he":"הרגל"},{"term":"creativo","he":"יצירתי"},{"term":"dibujar","he":"לצייר"},{"term":"diferente de mí","he":"שונה ממני"},{"term":"divertido","he":"מהנה / מצחיק"},{"term":"domingo","he":"יום ראשון / רִאשׁוֹן (יוֹם)"},{"term":"egoísta","he":"אנוכי"},{"term":"empezar","he":"להתחיל"},{"term":"escuchar música","he":"להאזין למוזיקה"},{"term":"especial","he":"מיוחד"},{"term":"estudiar","he":"ללמוד"},{"term":"estudioso","he":"שקדן"},{"term":"fin de semana","he":"סוף שבוע"},{"term":"generoso","he":"נדיב"},{"term":"grosero","he":"גס רוח"},{"term":"hacer deporte","he":"לעשות ספורט"},{"term":"honesto","he":"ישר / הגון"},{"term":"hora","he":"שעה"},{"term":"igual que yo","he":"כמוני"},{"term":"inteligente","he":"חכם"},{"term":"invitar","he":"להזמין"},{"term":"jueves","he":"יום חמישי"},{"term":"jugar","he":"לשחק"},{"term":"leal","he":"נאמן"},{"term":"leer","he":"לקרוא"},{"term":"lunes","he":"יום שני"},{"term":"martes","he":"יום שלישי"},{"term":"mejor amigo","he":"החבר הטוב ביותר"},{"term":"miércoles","he":"יום רביעי"},{"term":"normalmente","he":"בדרך כלל"},{"term":"nunca","he":"אף פעם לא"},{"term":"pasar tiempo","he":"לבלות זמן"},{"term":"personalidad","he":"אופי"},{"term":"playa","he":"חוף / חוף ים / חוֹף"},{"term":"por la mañana","he":"בבוקר"},{"term":"por la noche","he":"בלילה"},{"term":"preferir","he":"להעדיף"},{"term":"proyecto","he":"פרויקט"},{"term":"recuerdo","he":"זיכרון"},{"term":"recuerdo de viaje","he":"זיכרון מטיול"},{"term":"ruidoso","he":"רועש"},{"term":"sábado","he":"שבת"},{"term":"salir","he":"לצאת"},{"term":"secreto","he":"סוד"},{"term":"serie","he":"סדרה"},{"term":"servicial","he":"נכון לעזור"},{"term":"siempre","he":"תמיד"},{"term":"simpático","he":"נחמד"},{"term":"terminar","he":"לסיים"},{"term":"tímido","he":"ביישן"},{"term":"trabajador","he":"חרוץ"},{"term":"trabajar","he":"לעבוד"},{"term":"tranquilo","he":"רגוע / שקט / רגוע / שקט או רגוע"},{"term":"ver películas","he":"לראות סרטים"},{"term":"viajar","he":"לטייל / לנסוע"},{"term":"viernes","he":"יום שישי"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1060083398/amistades-flash-cards/?i=1b52po&x=1jqt"}]','published','workbook L1 unit 03',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-amistades-01','es1-amistades','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"חבר ___","input":"text"},{"prompt":"חברות ___","input":"text"},{"prompt":"נחמד ___","input":"text"},{"prompt":"יצירתי ___","input":"text"}]}','{"items":[{"display":"amigo","answers":["amigo"]},{"display":"amistad","answers":["amistad"]},{"display":"simpático","answers":["simpático"]},{"display":"creativo","answers":["creativo"]}],"policy":{"accents":"lenient"}}','published','L1-U03-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-amistades-02','es1-amistades','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"Mis amigas ___ simpáticas.","input":"choice","options":["es","son"]},{"prompt":"Ana es ___.","input":"choice","options":["creativo","creativa"]},{"prompt":"Luis ___ en Haifa.","hint":"vivir","input":"text"},{"prompt":"Yo ___ a mis amigos.","hint":"ayudar","input":"text"},{"prompt":"Nosotros ___ música.","hint":"escuchar","input":"text"},{"prompt":"Ella ___ trabaja los sábados: trabaja de lunes a viernes.","input":"choice","options":["no","también"]},{"prompt":"Mis amigos son ___.","input":"choice","options":["creativo","creativos"]},{"prompt":"Ella ___ su tiempo con nosotros.","hint":"compartir","input":"text"}]}','{"items":[{"display":"son","choice":1},{"display":"creativa","choice":1},{"display":"vive","answers":["vive"]},{"display":"ayudo","answers":["ayudo"]},{"display":"escuchamos","answers":["escuchamos"]},{"display":"no","choice":0},{"display":"creativos","choice":1},{"display":"comparte","answers":["comparte"]}],"policy":{"accents":"strict"}}','published','L1-U03-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-amistades-03','es1-amistades','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"Mi amiga es creativo.","input":"sentence"},{"prompt":"Ella trabajas en una tienda.","input":"sentence"},{"prompt":"Mis amigos es simpáticos.","input":"sentence"},{"prompt":"Ella no es trabaja los domingos.","input":"sentence"}]}','{"items":[{"display":"Mi amiga es creativa.","answers":["Mi amiga es creativa."]},{"display":"Ella trabaja en una tienda.","answers":["Ella trabaja en una tienda."]},{"display":"Mis amigos son simpáticos.","answers":["Mis amigos son simpáticos."]},{"display":"Ella no trabaja los domingos.","answers":["Ella no trabaja los domingos."]}],"policy":{"accents":"strict"}}','published','L1-U03-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-amistades-04','es1-amistades','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"Mi amigo es tranquilo. → רבים","input":"sentence"},{"prompt":"Yo comparto mi comida. → Ella…","input":"sentence"},{"prompt":"Ella trabaja los domingos. → שלילה","input":"sentence"}]}','{"items":[{"display":"Mis amigos son tranquilos.","answers":["Mis amigos son tranquilos."]},{"display":"Ella comparte su comida.","answers":["Ella comparte su comida.","Ella comparte mi comida"]},{"display":"Ella no trabaja los domingos.","answers":["Ella no trabaja los domingos."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U03-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-amistades-05','es1-amistades','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"החברה שלי נחמדה ויצירתית.","input":"sentence"},{"prompt":"הוא לא גר בחיפה.","input":"sentence"},{"prompt":"אנחנו מאזינים למוזיקה בימי שישי.","input":"sentence"},{"prompt":"אני עוזר לחברים שלי.","input":"sentence"}]}','{"items":[{"display":"Mi amiga es simpática y creativa.","answers":["Mi amiga es simpática y creativa."]},{"display":"Él no vive en Haifa.","answers":["Él no vive en Haifa."]},{"display":"Escuchamos música los viernes.","answers":["Escuchamos música los viernes."]},{"display":"Ayudo a mis amigos.","answers":["Ayudo a mis amigos."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U03-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-amistades-06','es1-amistades','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿Cómo es Irene?","input":"sentence"},{"prompt":"¿Dónde trabaja Irene?","input":"sentence"},{"prompt":"¿Qué hacen los viernes?","input":"sentence"}],"text":"Mi amiga Irene es simpática y creativa. Trabaja en una tienda y dibuja en su tiempo libre.\nYo trabajo en una escuela. Los viernes escuchamos música y cocinamos juntos.\nIrene no come carne. Mi amigo Leo también viene: él cocina muy bien."}','{"items":[{"display":"Es simpática y creativa.","answers":["Es simpática y creativa."]},{"display":"Trabaja en una tienda.","answers":["Trabaja en una tienda."]},{"display":"Escuchan música y cocinan juntos.","answers":["Escuchan música y cocinan juntos."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U03-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-amistades-07','es1-amistades','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Cómo es tu mejor amigo o amiga?\n¿Dónde trabaja o estudia?\n¿Qué hacen juntos?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U03-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-amistades-08','es1-amistades','open','writing','כתיבה','כתבו 5 או 6 משפטים על חבר או חברה: שני תיאורים, שתי פעולות, דבר משותף לכם והבדל אחד. השתמשו גם ב־no או ב־pero.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Mi amiga Dana es simpática y tranquila. Trabaja en una escuela. Lee mucho. Escuchamos música juntos. A los dos nos gusta bailar, pero ella no juega al fútbol."],"criteria":""}','published','L1-U03-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-amistades-09','es1-amistades','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"Ana tiene dos hermanos. Son ___ hermanos.","input":"choice","options":["su","sus"]},{"prompt":"A Ana le ___ leer.","input":"choice","options":["gusta","gustan"]}]}','{"items":[{"display":"sus","choice":1},{"display":"gusta","choice":0}],"policy":{"accents":"strict"}}','published','L1-U03-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-amistades-10','es1-amistades','open','speaking','אתגר לבחירה','כתבו שני משפטים על עצמכם והעבירו אותם לגוף שלישי כאילו חבר מציג אתכם. שנו גם את כינויי השייכות כשצריך.','self','{"prompt":"","brief":"","note":"משימה פתוחה לבחירה: אין מפתח. אפשר להביא את הניסוח לשיעור."}','{"models":[],"criteria":""}','published','L1-U03-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-amistades-11','es1-amistades','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["invitar","ruidoso","cocinar","tranquilo","celebrar","leer","inteligente","creativo"],"right":[{"id":"A","text":"לקרוא"},{"id":"B","text":"חכם"},{"id":"C","text":"לחגוג"},{"id":"D","text":"רגוע"},{"id":"E","text":"יצירתי"},{"id":"F","text":"להזמין"},{"id":"G","text":"רועש"},{"id":"H","text":"לבשל"}]}','{"pairs":["F","G","H","D","C","A","B","E"],"policy":{"accents":"lenient"}}','published','L1-U03-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-amistades-12','es1-amistades','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"Clara inventa dibujos nuevos; es muy ___.","input":"bank"},{"prompt":"Eva trabaja mucho; es muy ___.","input":"bank"},{"prompt":"Puedo contarle un secreto: ella es ___.","input":"bank"},{"prompt":"Un buen amigo está dispuesto a ___ cuando tengo un problema.","input":"bank"},{"prompt":"Los viernes nosotros ___ la cena juntos.","input":"bank"},{"prompt":"Clara y Eva tienen un ___ de su viaje a Perú.","input":"bank"}],"wordbank":["cocinamos","recuerdo","trabajadora","creativa","ayudar","leal"]}','{"items":[{"display":"creativa","answers":["creativa"]},{"display":"trabajadora","answers":["trabajadora"]},{"display":"leal","answers":["leal"]},{"display":"ayudar","answers":["ayudar"]},{"display":"cocinamos","answers":["cocinamos"]},{"display":"recuerdo","answers":["recuerdo"]}],"policy":{"accents":"strict"}}','published','L1-U03-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-amistades-13','es1-amistades','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"Mi amigo es creativo.","cue":"רבים","input":"sentence"},{"prompt":"Ella trabaja los lunes.","cue":"nosotros","input":"sentence"},{"prompt":"Yo leo por la noche.","cue":"él","input":"sentence"},{"prompt":"Mi amiga es egoísta.","cue":"שלילה","input":"sentence"}]}','{"items":[{"display":"Mis amigos son creativos.","answers":["Mis amigos son creativos."]},{"display":"Nosotros trabajamos los lunes.","answers":["Nosotros trabajamos los lunes."]},{"display":"Él lee por la noche.","answers":["Él lee por la noche."]},{"display":"Mi amiga no es egoísta.","answers":["Mi amiga no es egoísta."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U03-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-amistades-14','es1-amistades','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"¿Qué hacen juntas los viernes?"},{"id":"B","text":"Es trabajadora y leal. Siempre me ayuda."},{"id":"C","text":"¿Cómo es tu amiga Eva?"},{"id":"D","text":"Cocinamos en mi casa. ¿Quieres venir este viernes?"},{"id":"E","text":"Sí, gracias. Me gusta cocinar."}]}','{"order":["C","B","A","D","E"],"policy":{"accents":"strict"}}','published','L1-U03-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-amistades-15','es1-amistades','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Por qué es creativa Clara?","input":"sentence"},{"prompt":"¿Cuándo cocinan juntas?","input":"sentence"},{"prompt":"¿Qué prefiere hacer Eva los sábados?","input":"sentence"},{"prompt":"¿Qué comparten las amigas?","input":"sentence"}],"text":"Clara es creativa: dibuja recuerdos de sus viajes. Su amiga Eva es trabajadora y siempre ayuda con los proyectos. Las dos cocinan juntas los viernes. Clara baila los sábados, pero Eva prefiere leer en casa. Son diferentes, pero comparten sus secretos y confían la una en la otra. Para ellas, la amistad es importante."}','{"items":[{"display":"Porque dibuja recuerdos de sus viajes.","answers":["Porque dibuja recuerdos de sus viajes."]},{"display":"Los viernes.","answers":["Los viernes."]},{"display":"Prefiere leer en casa.","answers":["Prefiere leer en casa."]},{"display":"Sus secretos.","answers":["Sus secretos."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U03-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-amistades-16','es1-amistades','open','writing','כותבים לחיים','תארו חבר או חברה. כתבו שלוש תכונות, שתי פעילויות משותפות ודבר אחד שבו אתם שונים. שלבו שתי מילות תדירות.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Mi amigo Pablo es amable, leal y creativo. Siempre ayuda a sus amigos con sus proyectos. Los viernes cocinamos juntos y escuchamos música. A veces hacemos deporte en el parque. Él baila los sábados, pero yo prefiero leer. Somos diferentes, pero compartimos recuerdos y confiamos el uno en el otro."],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U03-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-profesiones','es-1','es-1-daily','מקצועות','Profesiones','לתאר פעולות בעבודה ולהשתמש במספרים בהקשר מקצועי.','workbook','[{"he":"פעלים בהווה","target":"presente simple"},{"he":"מספרים","target":"querer + infinitivo"}]','["הווה","מספרים"]','{"rules":["הפועל בהווה מותאם לגוף ולסיומת שלו: -ar · -er · -ir.","אחרי quiero · necesito · puedo תמיד בא שם פועל, בלי הטיה.","במספרים 31 עד 99 מוסיפים y בין העשרות ליחידות. 100 הוא cien, ולפני המשך מספר משתמשים ב־ciento."],"examples":["Yo vendo. Ella vende. Nosotros vendemos.","Quiero trabajar. Necesito estudiar.","treinta y dos · cien · ciento veinte · doscientos"],"tips":["אומרים cien euros לבד, אבל ciento veinte כשממשיכים במספר. אותו כלל תקף גם ל־ciento cincuenta."],"mistakes":[{"text":"בעברית אומרים \"אני רוצה לעבוד\" עם שם פועל, ובדיוק כך זה בספרדית. הטעות היא להטות את שני הפעלים. ובמספרים, ה־y בין העשרות ליחידות אינה אופציונלית.","pairs":[{"bad":"quiero trabajo","good":"quiero trabajar"},{"bad":"treinta cinco","good":"treinta y cinco"}]}]}','[{"term":"ahorrar","he":"לחסוך"},{"term":"ahorros","he":"חסכונות"},{"term":"alquiler","he":"שכר דירה"},{"term":"arreglar / reparar","he":"לתקן"},{"term":"atender","he":"לטפל בלקוח / לשרת"},{"term":"ayudar","he":"לעזור"},{"term":"cajero / cajera","he":"קופאי / קופאית"},{"term":"catorce","he":"ארבע עשרה"},{"term":"cien","he":"מאה"},{"term":"cinco","he":"חמש"},{"term":"cincuenta","he":"חמישים"},{"term":"cliente","he":"לקוח"},{"term":"coche","he":"מכונית"},{"term":"cocinar","he":"לבשל"},{"term":"comprar","he":"לקנות"},{"term":"computadora","he":"מחשב"},{"term":"conducir","he":"לנהוג"},{"term":"cuarenta","he":"ארבעים"},{"term":"cuatro","he":"ארבע"},{"term":"cuatrocientos","he":"ארבע מאות"},{"term":"descanso","he":"הפסקה"},{"term":"día","he":"יום"},{"term":"diecinueve","he":"תשע עשרה"},{"term":"dieciocho","he":"שמונה עשרה"},{"term":"dieciséis","he":"שש עשרה"},{"term":"diecisiete","he":"שבע עשרה"},{"term":"diez","he":"עשר"},{"term":"doce","he":"שתים עשרה"},{"term":"doctor / doctora","he":"רופא / רופאה"},{"term":"doctora","he":"רופאה"},{"term":"dos","he":"שתיים"},{"term":"doscientos","he":"מאתיים"},{"term":"empezar","he":"להתחיל"},{"term":"enseñar","he":"ללמד"},{"term":"entrevista de trabajo","he":"ריאיון עבודה"},{"term":"equipo","he":"צוות"},{"term":"escribir","he":"לכתוב"},{"term":"escuela","he":"בית ספר"},{"term":"experiencia","he":"ניסיון"},{"term":"gastar","he":"להוציא כסף / להוציא"},{"term":"gastos","he":"הוצאות"},{"term":"gato","he":"חתול"},{"term":"gente","he":"אנשים"},{"term":"horas","he":"שעות"},{"term":"hospital","he":"בית חולים"},{"term":"ingeniero / ingeniera","he":"מהנדס / מהנדסת"},{"term":"limpieza","he":"ניקיון"},{"term":"llegar a tiempo","he":"להגיע בזמן"},{"term":"llevar uniforme","he":"ללבוש מדים"},{"term":"lugar de trabajo","he":"מקום עבודה"},{"term":"maestro","he":"מורה"},{"term":"maestro / maestra","he":"מורה"},{"term":"mes","he":"חודש"},{"term":"mesero / mesera","he":"מלצר / מלצרית"},{"term":"mil","he":"אלף"},{"term":"necesitar","he":"להזדקק"},{"term":"negocio / empresa","he":"עסק"},{"term":"novecientos","he":"תשע מאות"},{"term":"noventa","he":"תשעים"},{"term":"nueve","he":"תשע"},{"term":"ochenta","he":"שמונים"},{"term":"ocho","he":"שמונה"},{"term":"ochocientos","he":"שמונה מאות"},{"term":"oficial de policía","he":"שוטר / שוטרת"},{"term":"once","he":"אחת עשרה"},{"term":"país","he":"מדינה / ארץ / מדינה"},{"term":"panadería","he":"מאפייה"},{"term":"panadero","he":"אופה"},{"term":"periodista","he":"עיתונאי / עיתונאית"},{"term":"perro","he":"כלב"},{"term":"piloto","he":"טייס"},{"term":"pintar","he":"לצייר / לצבוע / לצייר"},{"term":"pintor / pintora","he":"צייר / ציירת"},{"term":"poder","he":"להיות מסוגל"},{"term":"presupuesto","he":"תקציב"},{"term":"profesión","he":"מקצוע"},{"term":"profesor","he":"מורה"},{"term":"querer","he":"לרצות"},{"term":"quince","he":"חמש עשרה"},{"term":"quinientos","he":"חמש מאות"},{"term":"recepcionista","he":"פקיד קבלה"},{"term":"responsabilidad","he":"אחריות"},{"term":"restaurante","he":"מסעדה"},{"term":"seis","he":"שש"},{"term":"seiscientos","he":"שש מאות"},{"term":"semana","he":"שבוע"},{"term":"servir","he":"לשרת / להגיש"},{"term":"sesenta","he":"שישים"},{"term":"setecientos","he":"שבע מאות"},{"term":"setenta","he":"שבעים"},{"term":"siete","he":"שבע"},{"term":"sitio de construcción","he":"אתר בנייה"},{"term":"sueldo / salario","he":"משכורת"},{"term":"trabajadores","he":"עובדים"},{"term":"trece","he":"שלוש עשרה"},{"term":"treinta","he":"שלושים"},{"term":"treinta y uno","he":"שלושים ואחת"},{"term":"tres","he":"שלוש"},{"term":"trescientos","he":"שלוש מאות"},{"term":"uno","he":"אחד / אחת"},{"term":"veinte","he":"עשרים"},{"term":"veinticinco","he":"עשרים וחמש"},{"term":"veinticuatro","he":"עשרים וארבע"},{"term":"veintidós","he":"עשרים ושתיים"},{"term":"veintinueve","he":"עשרים ותשע"},{"term":"veintiocho","he":"עשרים ושמונה"},{"term":"veintiséis","he":"עשרים ושש"},{"term":"veintisiete","he":"עשרים ושבע"},{"term":"veintitrés","he":"עשרים ושלוש"},{"term":"veintiuno","he":"עשרים ואחת"},{"term":"vender","he":"למכור"},{"term":"veterinario","he":"וטרינר"},{"term":"viajar","he":"לטייל / לנסוע"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/1053516339/professions-basic-spanish-flash-cards/?new"}]','published','workbook L1 unit 04',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-profesiones-01','es1-profesiones','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"מורה ___","input":"text"},{"prompt":"רופאה ___","input":"text"},{"prompt":"למכור ___","input":"text"},{"prompt":"לבשל ___","input":"text"}]}','{"items":[{"display":"maestro","answers":["maestro"]},{"display":"doctora","answers":["doctora"]},{"display":"vender","answers":["vender"]},{"display":"cocinar","answers":["cocinar"]}],"policy":{"accents":"lenient"}}','published','L1-U04-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-profesiones-02','es1-profesiones','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"Yo ___ en una escuela.","hint":"trabajar","input":"text"},{"prompt":"Ella ___ comida.","hint":"vender","input":"text"},{"prompt":"Nosotros ___ correos.","hint":"escribir","input":"text"},{"prompt":"Quiero ___ en un hospital.","input":"choice","options":["trabajo","trabajar"]},{"prompt":"35 horas → המספר במילים","input":"text"},{"prompt":"120 euros → המספר במילים","input":"text"},{"prompt":"Ella no ___ los sábados.","hint":"trabajar","input":"text"},{"prompt":"100 euros → המספר במילים","input":"text"}]}','{"items":[{"display":"trabajo","answers":["trabajo"]},{"display":"vende","answers":["vende"]},{"display":"escribimos","answers":["escribimos"]},{"display":"trabajar","choice":1},{"display":"treinta y cinco horas","answers":["treinta y cinco horas"]},{"display":"ciento veinte euros","answers":["ciento veinte euros"]},{"display":"trabaja","answers":["trabaja"]},{"display":"cien euros","answers":["cien euros"]}],"policy":{"accents":"strict"}}','published','L1-U04-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-profesiones-03','es1-profesiones','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"Yo quiero trabajo en un hospital.","input":"sentence"},{"prompt":"Ella vendo pan en la panadería.","input":"sentence"},{"prompt":"Trabajo treinta cinco horas por semana.","input":"sentence"},{"prompt":"Nosotros escribe correos.","input":"sentence"}]}','{"items":[{"display":"Yo quiero trabajar en un hospital.","answers":["Yo quiero trabajar en un hospital."]},{"display":"Ella vende pan en la panadería.","answers":["Ella vende pan en la panadería."]},{"display":"Trabajo treinta y cinco horas por semana.","answers":["Trabajo treinta y cinco horas por semana."]},{"display":"Nosotros escribimos correos.","answers":["Nosotros escribimos correos."]}],"policy":{"accents":"strict"}}','published','L1-U04-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-profesiones-04','es1-profesiones','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"Yo cocino en un restaurante. → Nosotros…","input":"sentence"},{"prompt":"Ella escribe correos. → שלילה","input":"sentence"},{"prompt":"200 euros → המספר במילים","input":"sentence"}]}','{"items":[{"display":"Nosotros cocinamos en un restaurante.","answers":["Nosotros cocinamos en un restaurante."]},{"display":"Ella no escribe correos.","answers":["Ella no escribe correos."]},{"display":"doscientos euros","answers":["doscientos euros"]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U04-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-profesiones-05','es1-profesiones','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"אני עובד בבית ספר.","input":"sentence"},{"prompt":"היא מוכרת לחם.","input":"sentence"},{"prompt":"אני רוצה לעבוד בבית חולים.","input":"sentence"},{"prompt":"אני עובד ארבעים שעות בשבוע.","input":"sentence"}]}','{"items":[{"display":"Trabajo en una escuela.","answers":["Trabajo en una escuela."]},{"display":"Ella vende pan.","answers":["Ella vende pan."]},{"display":"Quiero trabajar en un hospital.","answers":["Quiero trabajar en un hospital."]},{"display":"Trabajo cuarenta horas por semana.","answers":["Trabajo cuarenta horas por semana."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U04-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-profesiones-06','es1-profesiones','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿Cuántas horas trabaja Diego por semana?","input":"sentence"},{"prompt":"¿Dónde trabaja Luz?","input":"sentence"},{"prompt":"¿Cuál es su presupuesto para material?","input":"sentence"}],"text":"Me llamo Diego y soy maestro. Trabajo cinco días por semana y seis horas por día.\nEnseño español y escribo actividades. Mi amiga Luz trabaja en una panadería.\nElla vende pan y habla con los clientes. Su presupuesto para material es de cien euros al mes."}','{"items":[{"display":"Trabaja treinta horas por semana.","answers":["Trabaja treinta horas por semana.","seis horas por día, cinco días por semana"]},{"display":"Trabaja en una panadería.","answers":["Trabaja en una panadería."]},{"display":"Es de cien euros al mes.","answers":["Es de cien euros al mes."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U04-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-profesiones-07','es1-profesiones','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Dónde trabajas o dónde quieres trabajar?\n¿Qué haces en ese trabajo?\n¿Cuántas horas trabajas o estudias por semana?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U04-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-profesiones-08','es1-profesiones','open','writing','כתיבה','כתבו הצגה לראיון עבודה אמיתי או דמיוני של 5 משפטים. כללו מקצוע, מקום, שתי פעולות ומספר אחד במילים. הוסיפו משפט עם quiero או puedo ושם פועל.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Soy cocinero. Trabajo en un restaurante. Cocino y hablo con los clientes. Trabajo treinta horas por semana. Quiero aprender español."],"criteria":""}','published','L1-U04-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-profesiones-09','es1-profesiones','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"Mis amigos ___ simpáticos.","input":"choice","options":["es","son"]},{"prompt":"15 de mayo → היום במילים","input":"text"}]}','{"items":[{"display":"son","choice":1},{"display":"quince de mayo","answers":["quince de mayo"]}],"policy":{"accents":"strict"}}','published','L1-U04-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-profesiones-10','es1-profesiones','open','production','אתגר לבחירה','בנו תקציב ציוד דמיוני: שלושה פריטים במחירים 40, 25 ו־35 אירו. כתבו את המחירים ואת הסכום במילים.','self','{"prompt":"","brief":""}','{"models":["cuarenta, veinticinco, treinta y cinco; הסכום cien euros"],"criteria":""}','published','L1-U04-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-profesiones-11','es1-profesiones','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["hospital","escuela","sitio de construcción","vender","lugar de trabajo","arreglar / reparar","periodista","restaurante"],"right":[{"id":"A","text":"מסעדה"},{"id":"B","text":"עיתונאי / עיתונאית"},{"id":"C","text":"בית חולים"},{"id":"D","text":"בית ספר"},{"id":"E","text":"למכור"},{"id":"F","text":"אתר בנייה"},{"id":"G","text":"מקום עבודה"},{"id":"H","text":"לתקן"}]}','{"pairs":["C","D","F","E","G","H","B","A"],"policy":{"accents":"lenient"}}','published','L1-U04-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-profesiones-12','es1-profesiones','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"El ___ prepara pan.","input":"bank"},{"prompt":"La ___ cobra a los clientes.","input":"bank"},{"prompt":"Una médica trabaja en un ___.","input":"bank"},{"prompt":"Pago seiscientos euros de ___ por el local.","input":"bank"},{"prompt":"Para controlar los gastos, preparo un ___.","input":"bank"},{"prompt":"El dinero que guardo para el futuro son mis ___.","input":"bank"}],"wordbank":["alquiler","hospital","cajera","panadero","presupuesto","ahorros"]}','{"items":[{"display":"panadero","answers":["panadero"]},{"display":"cajera","answers":["cajera"]},{"display":"hospital","answers":["hospital"]},{"display":"alquiler","answers":["alquiler"]},{"display":"presupuesto","answers":["presupuesto"]},{"display":"ahorros","answers":["ahorros"]}],"policy":{"accents":"strict"}}','published','L1-U04-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-profesiones-13','es1-profesiones','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"Yo enseño español.","cue":"ella","input":"sentence"},{"prompt":"El cajero trabaja veinte horas.","cue":"רבים","input":"sentence"},{"prompt":"Nosotros vendemos pan.","cue":"yo","input":"sentence"},{"prompt":"Tú escribes noticias.","cue":"él","input":"sentence"}]}','{"items":[{"display":"Ella enseña español.","answers":["Ella enseña español."]},{"display":"Los cajeros trabajan veinte horas.","answers":["Los cajeros trabajan veinte horas."]},{"display":"Yo vendo pan.","answers":["Yo vendo pan."]},{"display":"Él escribe noticias.","answers":["Él escribe noticias."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U04-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-profesiones-14','es1-profesiones','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"¿Qué experiencia tienes?"},{"id":"B","text":"Soy cajero y atiendo a los clientes."},{"id":"C","text":"Puedo trabajar veinte horas."},{"id":"D","text":"¿Cuántas horas puedes trabajar por semana?"},{"id":"E","text":"Hola, quiero trabajar en su panadería."}]}','{"order":["E","A","B","D","C"],"policy":{"accents":"strict"}}','published','L1-U04-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-profesiones-15','es1-profesiones','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Cuántos trabajadores se mencionan en la panadería?","input":"sentence"},{"prompt":"¿Cuántas horas trabaja la cajera por semana?","input":"sentence"},{"prompt":"¿Cuánto cuesta el alquiler al mes?","input":"sentence"},{"prompt":"¿Cuánto ahorra María cada mes?","input":"sentence"}],"text":"María tiene una panadería. En su negocio trabajan dos panaderos y una cajera. La cajera trabaja veinte horas por semana y atiende a los clientes. El alquiler del local cuesta seiscientos euros al mes. María prepara un presupuesto y guarda cien euros de ahorros cada mes. Le gusta trabajar en equipo y vender pan fresco."}','{"items":[{"display":"Tres: dos panaderos y una cajera.","answers":["Tres: dos panaderos y una cajera."]},{"display":"Veinte horas.","answers":["Veinte horas."]},{"display":"Seiscientos euros.","answers":["Seiscientos euros."]},{"display":"Cien euros.","answers":["Cien euros."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U04-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-profesiones-16','es1-profesiones','open','writing','כותבים לחיים','הציגו עסק קטן שהייתם רוצים לנהל. ציינו שני מקצועות, פעולות העובדים, מספר שעות, שכר דירה וחיסכון מתוכנן. כתבו את הסכומים במילים.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Mi negocio es una panadería. Necesito dos panaderos y una cajera. Los panaderos preparan el pan y la cajera atiende a los clientes. La cajera trabaja veinte horas por semana. Pago seiscientos euros de alquiler al mes y preparo un presupuesto. Guardo cien euros de ahorros cada mes."],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U04-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-nos-reunimos','es-1','es-1-daily','קובעים להיפגש','¿Nos reunimos?','לקבוע יום ושעה ולהשתמש במילות יחס בסיסיות.','workbook','[{"he":"ימים ושעות","target":"días y horas"},{"he":"מילות יחס","target":"a · en · con"}]','["ימים ושעות","מילות יחס"]','{"rules":["לשעה משתמשים ב־a la una / a las dos, ולמיקום ב־en, לחברה ב־con וליעד ב־a.","el lunes מציין יום מסוים ו־los lunes מציין הרגל שבועי. אין מילת יחס לפני היום.","a ו־el מתחברים ל־al."],"examples":["Nos vemos el lunes a las seis.","Estoy en el parque con Ana.","Voy al cine los sábados."],"tips":["mañana הוא גם בוקר וגם מחר. ההקשר מבדיל: por la mañana לעומת hasta mañana."],"mistakes":[{"text":"בעברית אומרים \"ביום שישי\" עם מילת יחס, ובספרדית היום כבר נושא אותה בתוך el. וכשמדובר בשעה אחת, הכול עובר ליחיד: a la una.","pairs":[{"bad":"Nos vemos en viernes","good":"Nos vemos el viernes"},{"bad":"a las una","good":"a la una"}]}]}','[{"term":"a las","he":"בשעה לפי שעות ברבים"},{"term":"abril","he":"אפריל"},{"term":"abrir","he":"לפתוח"},{"term":"agosto","he":"אוגוסט"},{"term":"al mediodía","he":"בצהריים"},{"term":"año","he":"שנה"},{"term":"antes de","he":"לפני"},{"term":"banco","he":"בנק / ספסל"},{"term":"biblioteca","he":"ספרייה"},{"term":"cafetería","he":"בית קפה"},{"term":"catorce","he":"ארבע עשרה"},{"term":"cenar","he":"לאכול ארוחת ערב"},{"term":"centro comercial","he":"קניון"},{"term":"cerrar","he":"לסגור"},{"term":"cien","he":"מאה"},{"term":"cinco","he":"חמש"},{"term":"cincuenta","he":"חמישים"},{"term":"cocinar","he":"לבשל"},{"term":"comer","he":"לאכול / לֶאֱכוֹל"},{"term":"comprar","he":"לקנות"},{"term":"con","he":"עם"},{"term":"conducir","he":"לנהוג"},{"term":"conocer","he":"להכיר / לפגוש לראשונה"},{"term":"correos electrónicos","he":"הודעות דואר אלקטרוני"},{"term":"cuarenta","he":"ארבעים"},{"term":"cuatro","he":"ארבע"},{"term":"cumpleaños","he":"יום הולדת"},{"term":"desde","he":"מ־"},{"term":"despertar","he":"להעיר / להתעורר"},{"term":"despertarse","he":"להתעורר"},{"term":"después de","he":"אחרי"},{"term":"día","he":"יום"},{"term":"diciembre","he":"דצמבר"},{"term":"diecinueve","he":"תשע עשרה"},{"term":"dieciocho","he":"שמונה עשרה"},{"term":"dieciséis","he":"שש עשרה"},{"term":"diecisiete","he":"שבע עשרה"},{"term":"diez","he":"עשר"},{"term":"divertirse","he":"ליהנות / לבלות"},{"term":"doce","he":"שתים עשרה"},{"term":"domingo","he":"יום ראשון / רִאשׁוֹן (יוֹם)"},{"term":"dormir","he":"לישון / לִישׁוֹן"},{"term":"dos","he":"שתיים"},{"term":"durante","he":"במהלך"},{"term":"ejercicio","he":"תרגיל / פעילות גופנית"},{"term":"en","he":"ב־ / ב..."},{"term":"encontrarse","he":"להיפגש"},{"term":"encontrarse con amigos","he":"להיפגש עם חברים"},{"term":"enero","he":"ינואר"},{"term":"escuchar","he":"להקשיב / להאזין"},{"term":"esperar","he":"לחכות"},{"term":"estudiar","he":"ללמוד"},{"term":"favorito","he":"מועדף / אהוב"},{"term":"febrero","he":"פברואר"},{"term":"fecha","he":"תאריך"},{"term":"gimnasio","he":"חדר כושר"},{"term":"hacer ejercicio","he":"להתאמן / לעשות פעילות גופנית"},{"term":"hasta","he":"עד"},{"term":"hora","he":"שעה"},{"term":"ir","he":"ללכת / ללכת / לנסוע"},{"term":"ir de compras","he":"לקנות / ללכת לקניות"},{"term":"jueves","he":"יום חמישי"},{"term":"jugar","he":"לשחק"},{"term":"julio","he":"יולי"},{"term":"junio","he":"יוני"},{"term":"leer","he":"לקרוא"},{"term":"libre","he":"פנוי"},{"term":"limpiar","he":"לנקות"},{"term":"lunes","he":"יום שני"},{"term":"mañana","he":"בוקר / מחר"},{"term":"martes","he":"יום שלישי"},{"term":"marzo","he":"מרץ"},{"term":"mayo","he":"מאי"},{"term":"medianoche","he":"חצות"},{"term":"mediodía","he":"צהריים"},{"term":"mes","he":"חודש"},{"term":"miércoles","he":"יום רביעי"},{"term":"mirar","he":"להסתכל / לצפות / לצפות / להסתכל"},{"term":"noventa","he":"תשעים"},{"term":"noviembre","he":"נובמבר"},{"term":"nueve","he":"תשע"},{"term":"ochenta","he":"שמונים"},{"term":"ocho","he":"שמונה"},{"term":"octubre","he":"אוקטובר"},{"term":"once","he":"אחת עשרה"},{"term":"poder","he":"להיות מסוגל"},{"term":"por la mañana","he":"בבוקר"},{"term":"por la noche","he":"בלילה"},{"term":"por la tarde","he":"אחרי הצהריים"},{"term":"próximo","he":"הבא"},{"term":"quince","he":"חמש עשרה"},{"term":"reunión","he":"פגישה"},{"term":"reunirse con amigos","he":"להיפגש עם חברים"},{"term":"sábado","he":"שבת"},{"term":"seis","he":"שש"},{"term":"semana","he":"שבוע"},{"term":"septiembre","he":"ספטמבר"},{"term":"sesenta","he":"שישים"},{"term":"setenta","he":"שבעים"},{"term":"siete","he":"שבע"},{"term":"sobre","he":"על"},{"term":"supermercado","he":"סופרמרקט"},{"term":"tarde","he":"מאוחר / ערב / אחר הצהריים"},{"term":"temprano","he":"מוקדם"},{"term":"terminar","he":"לסיים"},{"term":"trabajar","he":"לעבוד"},{"term":"trece","he":"שלוש עשרה"},{"term":"treinta","he":"שלושים"},{"term":"treinta y uno","he":"שלושים ואחת"},{"term":"tres","he":"שלוש"},{"term":"uno","he":"אחד / אחת"},{"term":"veinte","he":"עשרים"},{"term":"veinticinco","he":"עשרים וחמש"},{"term":"veinticuatro","he":"עשרים וארבע"},{"term":"veintidós","he":"עשרים ושתיים"},{"term":"veintinueve","he":"עשרים ותשע"},{"term":"veintiocho","he":"עשרים ושמונה"},{"term":"veintiséis","he":"עשרים ושש"},{"term":"veintisiete","he":"עשרים ושבע"},{"term":"veintitrés","he":"עשרים ושלוש"},{"term":"veintiuno","he":"עשרים ואחת"},{"term":"ver","he":"לראות"},{"term":"viernes","he":"יום שישי"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/876190603/basic-spanish-lets-meet-flash-cards/"}]','published','workbook L1 unit 05',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-nos-reunimos-01','es1-nos-reunimos','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"שבוע ___","input":"text"},{"prompt":"יום ___","input":"text"},{"prompt":"בוקר ___","input":"text"},{"prompt":"צהריים ___","input":"text"}]}','{"items":[{"display":"semana","answers":["semana"]},{"display":"día","answers":["día"]},{"display":"mañana","answers":["mañana"]},{"display":"mediodía","answers":["mediodía"]}],"policy":{"accents":"lenient"}}','published','L1-U05-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-nos-reunimos-02','es1-nos-reunimos','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"La clase es ___ las ocho.","input":"choice","options":["a","en"]},{"prompt":"Estoy ___ casa.","input":"choice","options":["a","en"]},{"prompt":"Voy ___ mi amiga.","input":"choice","options":["con","de"]},{"prompt":"Voy ___ parque.","input":"choice","options":["al","en"]},{"prompt":"___ lunes voy al gimnasio. Es mi rutina semanal.","input":"choice","options":["El","Los"]},{"prompt":"La reunión es a ___ una.","input":"choice","options":["la","las"]},{"prompt":"Nos vemos ___ viernes a las seis.","input":"choice","options":["el","los"]},{"prompt":"Estudio español ___ casa.","input":"choice","options":["en","a"]}]}','{"items":[{"display":"a","choice":0},{"display":"en","choice":1},{"display":"con","choice":0},{"display":"al","choice":0},{"display":"Los","choice":1},{"display":"la","choice":0},{"display":"el","choice":0},{"display":"en","choice":0}],"policy":{"accents":"strict"}}','published','L1-U05-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-nos-reunimos-03','es1-nos-reunimos','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"Voy a el cine con mi hermana.","input":"sentence"},{"prompt":"La clase es en las ocho.","input":"sentence"},{"prompt":"Nos vemos en viernes.","input":"sentence"},{"prompt":"La reunión es a las una.","input":"sentence"}]}','{"items":[{"display":"Voy al cine con mi hermana.","answers":["Voy al cine con mi hermana."]},{"display":"La clase es a las ocho.","answers":["La clase es a las ocho."]},{"display":"Nos vemos el viernes.","answers":["Nos vemos el viernes."]},{"display":"La reunión es a la una.","answers":["La reunión es a la una."]}],"policy":{"accents":"strict"}}','published','L1-U05-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-nos-reunimos-04','es1-nos-reunimos','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"Nos vemos / viernes / 18:00 → כתבו משפט עם el ועם a las","input":"sentence"},{"prompt":"Voy a el cine. → תקנו","input":"sentence"},{"prompt":"Todos los sábados estudio. → התחילו ב־Los sábados","input":"sentence"}]}','{"items":[{"display":"Nos vemos el viernes a las seis de la tarde.","answers":["Nos vemos el viernes a las seis de la tarde.","a las seis"]},{"display":"Voy al cine.","answers":["Voy al cine."]},{"display":"Los sábados estudio.","answers":["Los sábados estudio."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U05-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-nos-reunimos-05','es1-nos-reunimos','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"נתראה ביום שני בשש.","input":"sentence"},{"prompt":"אני בפארק עם אנה.","input":"sentence"},{"prompt":"אני הולך לקולנוע בימי שבת.","input":"sentence"},{"prompt":"הפגישה היא באחת.","input":"sentence"}]}','{"items":[{"display":"Nos vemos el lunes a las seis.","answers":["Nos vemos el lunes a las seis."]},{"display":"Estoy en el parque con Ana.","answers":["Estoy en el parque con Ana."]},{"display":"Voy al cine los sábados.","answers":["Voy al cine los sábados."]},{"display":"La reunión es a la una.","answers":["La reunión es a la una."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U05-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-nos-reunimos-06','es1-nos-reunimos','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿Qué día se ven al final?","input":"sentence"},{"prompt":"¿A qué hora?","input":"sentence"},{"prompt":"¿Con quién va Ana?","input":"sentence"}],"text":"Ana: ¿Nos vemos el jueves a las cinco en el parque?\nLeo: El jueves trabajo. ¿El viernes a las seis?\nAna: Sí. Voy con mi hermana.\nLeo: Perfecto. Estoy en el parque a las seis.\nAna: ¡Hasta el viernes!"}','{"items":[{"display":"Se ven el viernes.","answers":["Se ven el viernes."]},{"display":"A las seis.","answers":["A las seis."]},{"display":"Va con su hermana.","answers":["Va con su hermana."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U05-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-nos-reunimos-07','es1-nos-reunimos','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Qué días estudias español?\n¿Dónde te encuentras con tus amigos?\n¿A qué hora puedes ver a un amigo esta semana?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U05-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-nos-reunimos-08','es1-nos-reunimos','open','writing','כתיבה','כתבו התכתבות של 6 שורות לקביעת פגישה. הציעו יום, שעה ומקום; הצד השני מציע שינוי; סיימו באישור ברור של הפרטים.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["A: ¿Nos vemos el martes? B: Sí, ¿a qué hora? A: A las cinco en el parque. B: ¿A las seis? A: Sí, a las seis en el parque. B: ¡Perfecto!"],"criteria":""}','published','L1-U05-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-nos-reunimos-09','es1-nos-reunimos','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"42 → כתבו במילים","input":"text"},{"prompt":"Es ___ hermana. (שלי, יחידה)","input":"text"}]}','{"items":[{"display":"cuarenta y dos","answers":["cuarenta y dos"]},{"display":"mi","answers":["mi"]}],"policy":{"accents":"strict"}}','published','L1-U05-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-nos-reunimos-10','es1-nos-reunimos','open','speaking','אתגר לבחירה','הוסיפו להתכתבות אי הבנה אחת לגבי המקום. שאלו שאלה שמבהירה את המקום ואשרו אותו מחדש.','self','{"prompt":"","brief":"","note":"משימה פתוחה לבחירה: אין מפתח. אפשר להביא את הניסוח לשיעור."}','{"models":[],"criteria":""}','published','L1-U05-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-nos-reunimos-11','es1-nos-reunimos','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["limpiar","mañana","mediodía","día","fecha","comer","mes","dormir"],"right":[{"id":"A","text":"בוקר"},{"id":"B","text":"צהריים"},{"id":"C","text":"לנקות"},{"id":"D","text":"יום"},{"id":"E","text":"חודש"},{"id":"F","text":"לישון"},{"id":"G","text":"לאכול"},{"id":"H","text":"תאריך"}]}','{"pairs":["C","A","B","D","H","G","E","F"],"policy":{"accents":"lenient"}}','published','L1-U05-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-nos-reunimos-12','es1-nos-reunimos','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"El día después del jueves es ___.","input":"bank"},{"prompt":"El mes después de abril es ___.","input":"bank"},{"prompt":"Nos encontramos a las cinco en la ___.","input":"bank"},{"prompt":"Estudio por la ___ y trabajo por la tarde.","input":"bank"},{"prompt":"Como a las doce, al ___.","input":"bank"},{"prompt":"Leo mis ___ en la computadora.","input":"bank"}],"wordbank":["cafetería","mañana","correos electrónicos","mediodía","viernes","mayo"]}','{"items":[{"display":"viernes","answers":["viernes"]},{"display":"mayo","answers":["mayo"]},{"display":"cafetería","answers":["cafetería"]},{"display":"mañana","answers":["mañana"]},{"display":"mediodía","answers":["mediodía"]},{"display":"correos electrónicos","answers":["correos electrónicos"]}],"policy":{"accents":"strict"}}','published','L1-U05-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-nos-reunimos-13','es1-nos-reunimos','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"Me reúno con Ana el lunes.","cue":"nosotros","input":"sentence"},{"prompt":"Trabajo por la mañana.","cue":"ella","input":"sentence"},{"prompt":"Él puede el viernes.","cue":"שלילה","input":"sentence"},{"prompt":"Nos encontramos a las cinco.","cue":"tú","input":"sentence"}]}','{"items":[{"display":"Nos reunimos con Ana el lunes.","answers":["Nos reunimos con Ana el lunes."]},{"display":"Ella trabaja por la mañana.","answers":["Ella trabaja por la mañana."]},{"display":"Él no puede el viernes.","answers":["Él no puede el viernes."]},{"display":"Te encuentras a las cinco.","answers":["Te encuentras a las cinco."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U05-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-nos-reunimos-14','es1-nos-reunimos','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"No, trabajo hasta las cuatro."},{"id":"B","text":"¿Puedes reunirte el viernes a las tres?"},{"id":"C","text":"Entonces, ¿a las cinco en la cafetería?"},{"id":"D","text":"La cafetería que está al lado de la biblioteca."},{"id":"E","text":"Sí, a las cinco está bien. ¿Qué cafetería?"}]}','{"order":["B","A","C","E","D"],"policy":{"accents":"strict"}}','published','L1-U05-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-nos-reunimos-15','es1-nos-reunimos','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Cuándo estudia Daniel?","input":"sentence"},{"prompt":"¿Qué día está libre después del mediodía?","input":"sentence"},{"prompt":"¿Por qué no puede Ana a las tres?","input":"sentence"},{"prompt":"¿A qué hora se encuentran?","input":"sentence"}],"text":"Daniel estudia por la mañana y trabaja por la tarde de lunes a jueves. El viernes está libre después del mediodía. Quiere reunirse con Ana a las tres, pero ella trabaja hasta las cuatro. Al final, los dos se encuentran a las cinco en una cafetería. Está al lado de la biblioteca y cierra a las ocho."}','{"items":[{"display":"Por la mañana.","answers":["Por la mañana."]},{"display":"El viernes.","answers":["El viernes."]},{"display":"Porque trabaja hasta las cuatro.","answers":["Porque trabaja hasta las cuatro."]},{"display":"A las cinco.","answers":["A las cinco."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U05-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-nos-reunimos-16','es1-nos-reunimos','open','writing','כותבים לחיים','כתבו הודעה לתיאום פגישה. ציינו יום, שעה ומקום, הסבירו מתי אינכם פנויים והציעו זמן חלופי. שלבו en, a las ו־con.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Hola, Ana. Quiero reunirme contigo el viernes a las tres en la biblioteca. Por la mañana estudio español y después como con mi hermano. Si no puedes a las tres, estoy libre a las cinco. Podemos encontrarnos en la cafetería al lado de la biblioteca. La cafetería cierra a las ocho. ¿Qué hora prefieres?"],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U05-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-rutina','es-1','es-1-daily','שגרה','Rutina','לתאר שגרה עם פעלים חוזרים ולהוסיף זמן ותדירות.','workbook','[{"he":"פעלים חוזרים","target":"verbos reflexivos"},{"he":"תדירות","target":"siempre · a veces · nunca"}]','["פעלים חוזרים","תדירות"]','{"rules":["בפעלים כמו levantarse הכינוי משתנה לפי הגוף ובא לפני הפועל.","בחלק מהפעלים יש גם שינוי בגזע: me despierto · me visto · me acuesto.","לשלילה כותבים no לפני הכינוי, לא אחריו."],"examples":["Yo me levanto. Tú te levantas. Ella se levanta.","Nosotros nos levantamos. Ellos se levantan.","No me ducho por la noche. Me acuesto a las once."],"tips":["nunca בא לפני הכינוי ולא דורש no נוסף: אומרים nunca me levanto tarde, לא no nunca me levanto."],"mistakes":[{"text":"בעברית הפועל החוזר הוא מילה אחת (\"מתקלח\"), ולכן קל לשכוח את הכינוי או להשאיר אותו קפוא ב־se. הכינוי משתנה עם הגוף, וה־no תמיד לפניו.","pairs":[{"bad":"Nosotros se levantamos","good":"Nosotros nos levantamos"},{"bad":"Me no acuesto","good":"No me acuesto"}]}]}','[{"term":"a menudo","he":"לעיתים קרובות"},{"term":"a veces","he":"לפעמים"},{"term":"acostarse","he":"ללכת לישון / לשכב / ללכת לישון"},{"term":"antes de","he":"לפני"},{"term":"café","he":"בית קפה / קפה / קפה / קָפֶה"},{"term":"casi nunca","he":"כמעט אף פעם"},{"term":"casi siempre","he":"כמעט תמיד"},{"term":"catorce","he":"ארבע עשרה"},{"term":"cenar","he":"לאכול ארוחת ערב"},{"term":"cepillarse (los dientes / el pelo)","he":"לצחצח שיניים / להבריש שיער"},{"term":"cepillarse el pelo","he":"להבריש שיער"},{"term":"cepillarse los dientes","he":"לצחצח שיניים"},{"term":"cien","he":"מאה"},{"term":"cinco","he":"חמש"},{"term":"cincuenta","he":"חמישים"},{"term":"cine","he":"קולנוע"},{"term":"comer / almorzar","he":"לאכול / לאכול צהריים"},{"term":"cuarenta","he":"ארבעים"},{"term":"cuarto","he":"רבע"},{"term":"cuatro","he":"ארבע"},{"term":"de vez en cuando","he":"מדי פעם"},{"term":"desayunar","he":"לאכול ארוחת בוקר"},{"term":"desayuno","he":"ארוחת בוקר / אני אוכל ארוחת בוקר"},{"term":"descansar","he":"לנוח / לָנוּחַ"},{"term":"despertarse","he":"להתעורר"},{"term":"después de","he":"אחרי"},{"term":"diecinueve","he":"תשע עשרה"},{"term":"dieciocho","he":"שמונה עשרה"},{"term":"dieciséis","he":"שש עשרה"},{"term":"diecisiete","he":"שבע עשרה"},{"term":"dientes","he":"שיניים"},{"term":"diez","he":"עשר"},{"term":"diferencia","he":"הבדל"},{"term":"doce","he":"שתים עשרה"},{"term":"domingo","he":"יום ראשון / רִאשׁוֹן (יוֹם)"},{"term":"dormir","he":"לישון / לִישׁוֹן"},{"term":"dormirse","he":"להירדם"},{"term":"dos","he":"שתיים"},{"term":"ducharse","he":"להתקלח"},{"term":"el fin de semana","he":"בסוף השבוע"},{"term":"en común","he":"במשותף"},{"term":"escuchar música","he":"להאזין למוזיקה"},{"term":"escuela","he":"בית ספר"},{"term":"estudiar","he":"ללמוד"},{"term":"fin de semana","he":"סוף שבוע"},{"term":"fútbol","he":"כדורגל"},{"term":"hábito","he":"הרגל"},{"term":"hacer ejercicio","he":"להתאמן / לעשות פעילות גופנית"},{"term":"hermano","he":"אח"},{"term":"hora (¿a qué hora…?)","he":"שעה (באיזו שעה...?)"},{"term":"ir","he":"ללכת / ללכת / לנסוע"},{"term":"jueves","he":"יום חמישי"},{"term":"jugar","he":"לשחק"},{"term":"lavarse","he":"לשטוף (את עצמו)"},{"term":"leer","he":"לקרוא"},{"term":"levantarse","he":"לקום"},{"term":"lunes","he":"יום שני"},{"term":"mañana","he":"בוקר / מחר"},{"term":"manos","he":"ידיים"},{"term":"martes","he":"יום שלישי"},{"term":"media","he":"חצי"},{"term":"miércoles","he":"יום רביעי"},{"term":"mirar (la televisión / series)","he":"לראות (טלוויזיה / סדרות)"},{"term":"noche","he":"לילה"},{"term":"normalmente","he":"בדרך כלל"},{"term":"noventa","he":"תשעים"},{"term":"nueve","he":"תשע"},{"term":"nunca","he":"אף פעם לא"},{"term":"ochenta","he":"שמונים"},{"term":"ocho","he":"שמונה"},{"term":"once","he":"אחת עשרה"},{"term":"pelo","he":"שיער"},{"term":"por la mañana","he":"בבוקר"},{"term":"por la noche","he":"בלילה"},{"term":"por la tarde","he":"אחרי הצהריים"},{"term":"quince","he":"חמש עשרה"},{"term":"rutina","he":"שגרה"},{"term":"sábado","he":"שבת"},{"term":"seis","he":"שש"},{"term":"sesenta","he":"שישים"},{"term":"setenta","he":"שבעים"},{"term":"siempre","he":"תמיד"},{"term":"siete","he":"שבע"},{"term":"similitud","he":"דמיון"},{"term":"tarde","he":"מאוחר / ערב / אחר הצהריים"},{"term":"tarde (parte del día)","he":"אחרי הצהריים / ערב מוקדם"},{"term":"temprano","he":"מוקדם"},{"term":"todos los días","he":"בכל יום / כל יום"},{"term":"trabajar","he":"לעבוד"},{"term":"trece","he":"שלוש עשרה"},{"term":"treinta","he":"שלושים"},{"term":"treinta y uno","he":"שלושים ואחת"},{"term":"tres","he":"שלוש"},{"term":"universidad","he":"אוניברסיטה"},{"term":"uno","he":"אחד / אחת"},{"term":"veinte","he":"עשרים"},{"term":"veinticinco","he":"עשרים וחמש"},{"term":"veinticuatro","he":"עשרים וארבע"},{"term":"veintidós","he":"עשרים ושתיים"},{"term":"veintinueve","he":"עשרים ותשע"},{"term":"veintiocho","he":"עשרים ושמונה"},{"term":"veintiséis","he":"עשרים ושש"},{"term":"veintisiete","he":"עשרים ושבע"},{"term":"veintitrés","he":"עשרים ושלוש"},{"term":"veintiuno","he":"עשרים ואחת"},{"term":"vestirse","he":"להתלבש"},{"term":"viernes","he":"יום שישי"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/1063826487/espanol-basico-rutina-flash-cards/?new"}]','published','workbook L1 unit 06',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-rutina-01','es1-rutina','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"להתעורר ___","input":"text"},{"prompt":"לקום ___","input":"text"},{"prompt":"להתקלח ___","input":"text"},{"prompt":"להתלבש ___","input":"text"}]}','{"items":[{"display":"despertarse","answers":["despertarse"]},{"display":"levantarse","answers":["levantarse"]},{"display":"ducharse","answers":["ducharse"]},{"display":"vestirse","answers":["vestirse"]}],"policy":{"accents":"lenient"}}','published','L1-U06-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-rutina-02','es1-rutina','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"Yo ___ levanto a las siete.","input":"choice","options":["me","se"]},{"prompt":"Ana ___ ducha por la mañana.","input":"choice","options":["te","se"]},{"prompt":"Nosotros ___ levantamos temprano.","input":"choice","options":["nos","se"]},{"prompt":"Yo me ___ a las once.","input":"choice","options":["acuesto","acuesta"]},{"prompt":"Desayuno ___ las ocho.","input":"choice","options":["a","en"]},{"prompt":"Ellos ___ despiertan a las seis.","input":"choice","options":["me","se"]},{"prompt":"___ me levanto a las siete.","cue":"תמיד","input":"choice","options":["Siempre","Nunca"]},{"prompt":"___ me acuesto a las doce.","cue":"לפעמים","input":"choice","options":["A veces","Todos los días"]}]}','{"items":[{"display":"me","choice":0},{"display":"se","choice":1},{"display":"nos","choice":0},{"display":"acuesto","choice":0},{"display":"a","choice":0},{"display":"se","choice":1},{"display":"Siempre","choice":0},{"display":"A veces","choice":0}],"policy":{"accents":"strict"}}','published','L1-U06-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-rutina-03','es1-rutina','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"Yo levanto a las siete.","input":"sentence"},{"prompt":"Ana se ducho por la mañana.","input":"sentence"},{"prompt":"Nosotros se levantamos temprano.","input":"sentence"},{"prompt":"Me no acuesto a las once.","input":"sentence"}]}','{"items":[{"display":"Yo me levanto a las siete.","answers":["Yo me levanto a las siete."]},{"display":"Ana se ducha por la mañana.","answers":["Ana se ducha por la mañana."]},{"display":"Nosotros nos levantamos temprano.","answers":["Nosotros nos levantamos temprano."]},{"display":"No me acuesto a las once.","answers":["No me acuesto a las once."]}],"policy":{"accents":"strict"}}','published','L1-U06-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-rutina-04','es1-rutina','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"Yo me ducho por la mañana. → Ella…","input":"sentence"},{"prompt":"Me levanto a las seis. → שלילה","input":"sentence"},{"prompt":"Ella se levanta a las ocho. → Nosotros…","input":"sentence"}]}','{"items":[{"display":"Ella se ducha por la mañana.","answers":["Ella se ducha por la mañana."]},{"display":"No me levanto a las seis.","answers":["No me levanto a las seis."]},{"display":"Nosotros nos levantamos a las ocho.","answers":["Nosotros nos levantamos a las ocho."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U06-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-rutina-05','es1-rutina','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"אני קם בשבע.","input":"sentence"},{"prompt":"היא מתקלחת בבוקר.","input":"sentence"},{"prompt":"אנחנו הולכים לישון באחת עשרה.","input":"sentence"},{"prompt":"אני אף פעם לא אוכל ארוחת בוקר בשמונה.","input":"sentence"}]}','{"items":[{"display":"Me levanto a las siete.","answers":["Me levanto a las siete."]},{"display":"Ella se ducha por la mañana.","answers":["Ella se ducha por la mañana."]},{"display":"Nos acostamos a las once.","answers":["Nos acostamos a las once."]},{"display":"Nunca desayuno a las ocho.","answers":["Nunca desayuno a las ocho."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U06-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-rutina-06','es1-rutina','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿A qué hora se levanta Julia los lunes?","input":"sentence"},{"prompt":"¿Qué hace por la tarde?","input":"sentence"},{"prompt":"¿Se levanta a las siete los sábados?","input":"sentence"}],"text":"Soy Julia. Los lunes me despierto a las siete y me levanto a las siete y diez.\nMe ducho y desayuno a las ocho. Trabajo en casa. Por la tarde estudio español.\nNormalmente me acuesto a las once. Los sábados me levanto a las nueve."}','{"items":[{"display":"Se levanta a las siete y diez.","answers":["Se levanta a las siete y diez."]},{"display":"Estudia español.","answers":["Estudia español."]},{"display":"No, se levanta a las nueve.","answers":["No, se levanta a las nueve.","No, los sábados se levanta a las nueve"]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U06-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-rutina-07','es1-rutina','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿A qué hora te levantas?\n¿Qué haces antes del desayuno?\n¿Qué haces normalmente por la noche?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U06-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-rutina-08','es1-rutina','open','writing','כתיבה','כתבו יומן שגרה של 6 משפטים: שלוש פעולות עם כינוי חוזר, שתי שעות וביטוי תדירות אחד. הוסיפו הבדל בין יום חול לסוף השבוע.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Me despierto a las siete. Me levanto a las siete y diez. Me ducho por la mañana. Desayuno a las ocho. Siempre estudio por la tarde. Los sábados me levanto a las nueve."],"criteria":""}','published','L1-U06-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-rutina-09','es1-rutina','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"Voy ___ cine.","input":"choice","options":["a el","al"]},{"prompt":"Ella ___ música.","hint":"escuchar","input":"text"}]}','{"items":[{"display":"al","choice":1},{"display":"escucha","answers":["escucha"]}],"policy":{"accents":"strict"}}','published','L1-U06-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-rutina-10','es1-rutina','open','speaking','אתגר לבחירה','תארו את השגרה שלכם בשלושה משפטים ואז כתבו אותה מנקודת מבט של אדם אחר: הוא או היא מציגים אתכם.','self','{"prompt":"","brief":"","note":"משימה פתוחה לבחירה: אין מפתח. אפשר להביא את הניסוח לשיעור."}','{"models":[],"criteria":""}','published','L1-U06-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-rutina-11','es1-rutina','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["dormirse","por la tarde","despertarse","comer / almorzar","ducharse","cenar","descansar","lavarse"],"right":[{"id":"A","text":"אחרי הצהריים"},{"id":"B","text":"להירדם"},{"id":"C","text":"לאכול ארוחת ערב"},{"id":"D","text":"להתקלח"},{"id":"E","text":"לאכול / לאכול צהריים"},{"id":"F","text":"להתעורר"},{"id":"G","text":"לשטוף (את עצמו)"},{"id":"H","text":"לנוח"}]}','{"pairs":["B","A","F","E","D","C","H","G"],"policy":{"accents":"lenient"}}','published','L1-U06-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-rutina-12','es1-rutina','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"Por la mañana me ___ a las seis.","input":"bank"},{"prompt":"Después me ___ los dientes.","input":"bank"},{"prompt":"A las siete ___ pan y café.","input":"bank"},{"prompt":"Me lavo las ___ antes de comer.","input":"bank"},{"prompt":"El martes viene después del ___.","input":"bank"},{"prompt":"Por la noche me ___ a las diez.","input":"bank"}],"wordbank":["cepillo","manos","lunes","desayuno","despierto","acuesto"]}','{"items":[{"display":"despierto","answers":["despierto"]},{"display":"cepillo","answers":["cepillo"]},{"display":"desayuno","answers":["desayuno"]},{"display":"manos","answers":["manos"]},{"display":"lunes","answers":["lunes"]},{"display":"acuesto","answers":["acuesto"]}],"policy":{"accents":"strict"}}','published','L1-U06-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-rutina-13','es1-rutina','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"Me levanto a las siete.","cue":"ella","input":"sentence"},{"prompt":"Nos duchamos por la mañana.","cue":"yo","input":"sentence"},{"prompt":"Él se acuesta temprano.","cue":"ellos","input":"sentence"},{"prompt":"Te cepillas los dientes.","cue":"nosotros","input":"sentence"}]}','{"items":[{"display":"Ella se levanta a las siete.","answers":["Ella se levanta a las siete."]},{"display":"Me ducho por la mañana.","answers":["Me ducho por la mañana."]},{"display":"Ellos se acuestan temprano.","answers":["Ellos se acuestan temprano."]},{"display":"Nos cepillamos los dientes.","answers":["Nos cepillamos los dientes."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U06-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-rutina-14','es1-rutina','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"Yo a las siete. ¿Desayunas en casa?"},{"id":"B","text":"¿A qué hora te despiertas normalmente?"},{"id":"C","text":"No, yo desayuno en el trabajo."},{"id":"D","text":"Sí, después de ducharme. ¿Tú también?"},{"id":"E","text":"A las seis y media. ¿Y tú?"}]}','{"order":["B","E","A","D","C"],"policy":{"accents":"strict"}}','published','L1-U06-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-rutina-15','es1-rutina','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿A qué hora se despierta Paula?","input":"sentence"},{"prompt":"¿Qué hace antes de salir? Escribe dos acciones.","input":"sentence"},{"prompt":"¿Desayuna su hermano en casa?","input":"sentence"},{"prompt":"¿A qué hora se acuesta Paula normalmente?","input":"sentence"}],"text":"Paula se despierta a las seis y media. Se ducha, desayuna y se cepilla los dientes antes de salir. Su hermano se levanta a las siete y nunca desayuna en casa. Los dos trabajan por la mañana. Por la tarde, Paula a veces lee o hace ejercicio. Normalmente se acuesta a las diez y media."}','{"items":[{"display":"A las seis y media.","answers":["A las seis y media."]},{"display":"Se ducha, desayuna y se cepilla los dientes.","note":"מספיקות שתי פעולות","answers":["Se ducha, desayuna y se cepilla los dientes."]},{"display":"No, nunca desayuna en casa.","answers":["No, nunca desayuna en casa."]},{"display":"A las diez y media.","answers":["A las diez y media."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U06-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-rutina-16','es1-rutina','open','writing','כותבים לחיים','השוו את השגרה שלכם לשגרה של אדם קרוב. השתמשו בארבעה פעלים חוזרים, בשתי שעות ובשתי מילות תדירות.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Normalmente me despierto a las seis y media. Me ducho y me cepillo los dientes antes del desayuno. Mi hermano se levanta a las siete y nunca desayuna en casa. Por la tarde, a veces hago ejercicio. Yo me acuesto a las diez y media. Mi hermano se acuesta más tarde porque trabaja por la noche."],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U06-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-mi-hogar','es-1','es-1-daily','הבית שלי','Mi hogar','לתאר בית באמצעות hay ו־ser או estar ולספר מה עושים בו.','workbook','[{"he":"hay","target":"ser / estar"},{"he":"תיאור חדרים","target":"פעלים בהווה"}]','["hay","ser ו־estar"]','{"rules":["hay אומר שקיים משהו, ואינו משתנה ביחיד וברבים.","estar מציין מיקום של דבר מזוהה או מצב שלו, ו־ser משמש לתיאור מאפיינים.","אחרי שמתארים את החדר אפשר להוסיף פועל בהווה כדי לומר מה עושים בו."],"examples":["Hay dos sillas. No hay televisión.","La mesa está en la cocina. La cocina es pequeña.","Leo en la sala de estar."],"tips":["hay נשאר זהה תמיד: אומרים hay una silla וגם hay dos sillas, אף פעם לא hayn."],"mistakes":[{"text":"בעברית \"יש\" ו\"נמצא\" מתחלפים בקלות, ובספרדית זו הבחנה קבועה: hay לדבר חדש שמציגים, está למיקום של דבר שכבר ידוע, ו־es לתיאור קבוע.","pairs":[{"bad":"En mi casa están dos dormitorios","good":"En mi casa hay dos dormitorios"},{"bad":"La mesa es en la cocina","good":"La mesa está en la cocina"}]}]}','[{"term":"acogedor","he":"נעים ומזמין"},{"term":"alacena","he":"ארון מטבח"},{"term":"almohada","he":"כרית"},{"term":"amplio","he":"רחב / מרווח"},{"term":"antiguo","he":"ישן / עתיק"},{"term":"árboles","he":"עצים"},{"term":"armario","he":"ארון"},{"term":"banco","he":"בנק / ספסל"},{"term":"bañera","he":"אמבטיה"},{"term":"baño","he":"חדר רחצה / שירותים"},{"term":"barbacoa","he":"מנגל"},{"term":"brillante","he":"מבריק"},{"term":"cálido","he":"חמים / חם"},{"term":"cama","he":"מיטה / מִטָּה"},{"term":"casa","he":"בית פיזי / בית / בַּיִת"},{"term":"cepillo de dientes","he":"מברשת שיניים"},{"term":"cocina","he":"מטבח"},{"term":"cocinar","he":"לבשל"},{"term":"colorido","he":"צבעוני"},{"term":"columpio","he":"נדנדה"},{"term":"comedor","he":"חדר אוכל"},{"term":"cómodo","he":"נוח"},{"term":"cortinas","he":"וילונות"},{"term":"cuarto de lavado","he":"חדר כביסה"},{"term":"desayuno","he":"ארוחת בוקר / אני אוכל ארוחת בוקר"},{"term":"descansar","he":"לנוח / לָנוּחַ"},{"term":"desordenado","he":"מבולגן"},{"term":"dormir","he":"לישון / לִישׁוֹן"},{"term":"dormitorio","he":"חדר שינה"},{"term":"ducha","he":"מקלחת"},{"term":"elegante","he":"אלגנטי"},{"term":"espacioso","he":"מרווח"},{"term":"espejo","he":"מראה"},{"term":"estar","he":"להיות במצב או במקום / להיות"},{"term":"estufa","he":"כיריים / תנור חימום לפי ההקשר"},{"term":"flores","he":"פרחים"},{"term":"formal","he":"רשמי"},{"term":"fregadero","he":"כיור מטבח"},{"term":"fresco","he":"קריר / טרי"},{"term":"frío","he":"קר"},{"term":"garaje","he":"מוסך / חניה מקורה"},{"term":"grande","he":"גדול"},{"term":"habitación","he":"חדר"},{"term":"hago la cama","he":"אני מסדר את המיטה"},{"term":"hay","he":"יש"},{"term":"heladera","he":"מקרר"},{"term":"hermoso","he":"יפה"},{"term":"hierba","he":"דשא"},{"term":"hogar","he":"בית / בית רגשי"},{"term":"horno","he":"תנור"},{"term":"inodoro","he":"אסלה"},{"term":"jabón","he":"סבון"},{"term":"jardín/patio trasero","he":"גן / חצר אחורית"},{"term":"lámpara","he":"מנורה"},{"term":"lavabo","he":"כיור"},{"term":"licuadora","he":"בלנדר"},{"term":"limpiar","he":"לנקות"},{"term":"limpio","he":"נקי"},{"term":"luminoso","he":"מואר"},{"term":"manta","he":"שמיכה"},{"term":"me cepillo los dientes","he":"אני מצחצח שיניים"},{"term":"me levanto","he":"אני קם"},{"term":"mesa","he":"שולחן"},{"term":"mesa de noche","he":"שידת לילה"},{"term":"microondas","he":"מיקרוגל"},{"term":"moderno","he":"מודרני"},{"term":"mojado","he":"רטוב"},{"term":"oficina","he":"משרד"},{"term":"ordenado","he":"מסודר"},{"term":"organizado","he":"מאורגן"},{"term":"pacífico","he":"שלֵו"},{"term":"pequeño","he":"קטן"},{"term":"platos","he":"צלחות"},{"term":"privado","he":"פרטי"},{"term":"relajante","he":"מרגיע"},{"term":"relajarse","he":"להירגע"},{"term":"sala de estar","he":"סלון"},{"term":"salón","he":"סלון"},{"term":"ser","he":"להיות"},{"term":"servilletas","he":"מפיות"},{"term":"silla","he":"כיסא / כִּסֵּא"},{"term":"sillas","he":"כיסאות"},{"term":"sillón","he":"כורסה"},{"term":"sofá","he":"ספה"},{"term":"soleado","he":"שמשי"},{"term":"televisión","he":"טלוויזיה"},{"term":"toalla","he":"מגבת"},{"term":"tranquilo","he":"רגוע / שקט / רגוע / שקט או רגוע"},{"term":"valla","he":"גדר"},{"term":"vaso","he":"כוס"},{"term":"vasos","he":"כוסות"},{"term":"velas","he":"נרות"},{"term":"vender","he":"למכור"},{"term":"ventana","he":"חלון"},{"term":"verde","he":"ירוק"},{"term":"vivir","he":"לגור / לחיות"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/1025125959/my-home-basic-spanish-flash-cards/?funnelUUID=12e27fe6-be24-43a2-9fa3-860e32164f48"}]','published','workbook L1 unit 07',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-mi-hogar-01','es1-mi-hogar','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"מטבח ___","input":"text"},{"prompt":"חדר שינה ___","input":"text"},{"prompt":"סלון ___","input":"text"},{"prompt":"שולחן ___","input":"text"}]}','{"items":[{"display":"cocina","answers":["cocina"]},{"display":"dormitorio","answers":["dormitorio"]},{"display":"sala de estar","answers":["sala de estar"]},{"display":"mesa","answers":["mesa"]}],"policy":{"accents":"lenient"}}','published','L1-U07-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-mi-hogar-02','es1-mi-hogar','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"En mi casa ___ dos dormitorios.","input":"choice","options":["hay","están"]},{"prompt":"La mesa ___ en la cocina.","input":"choice","options":["es","está"]},{"prompt":"Mi sala de estar ___ grande.","input":"choice","options":["es","hay"]},{"prompt":"No ___ balcón.","input":"choice","options":["hay","es"]},{"prompt":"Yo ___ en la cocina.","hint":"cocinar","input":"text"},{"prompt":"Nosotros ___ en la sala de estar.","hint":"comer","input":"text"},{"prompt":"En la cocina ___ una ventana.","input":"choice","options":["hay","está"]},{"prompt":"Las sillas ___ cómodas.","input":"choice","options":["es","son"]}]}','{"items":[{"display":"hay","choice":0},{"display":"está","choice":1},{"display":"es","choice":0},{"display":"hay","choice":0},{"display":"cocino","answers":["cocino"]},{"display":"comemos","answers":["comemos"]},{"display":"hay","choice":0},{"display":"son","choice":1}],"policy":{"accents":"strict"}}','published','L1-U07-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-mi-hogar-03','es1-mi-hogar','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"En mi casa están dos dormitorios.","input":"sentence"},{"prompt":"La mesa es en la cocina.","input":"sentence"},{"prompt":"Hay una televisión pequeño.","input":"sentence"},{"prompt":"Mi cocina está pequeña.","input":"sentence"}]}','{"items":[{"display":"En mi casa hay dos dormitorios.","answers":["En mi casa hay dos dormitorios."]},{"display":"La mesa está en la cocina.","answers":["La mesa está en la cocina."]},{"display":"Hay una televisión pequeña.","answers":["Hay una televisión pequeña."]},{"display":"Mi cocina es pequeña.","answers":["Mi cocina es pequeña."]}],"policy":{"accents":"strict"}}','published','L1-U07-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-mi-hogar-04','es1-mi-hogar','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"Hay una silla. → החליפו ב־tres","input":"sentence"},{"prompt":"Yo limpio el dormitorio. → Ella…","input":"sentence"},{"prompt":"La cocina es grande. → שלילה","input":"sentence"}]}','{"items":[{"display":"Hay tres sillas.","answers":["Hay tres sillas."]},{"display":"Ella limpia el dormitorio.","answers":["Ella limpia el dormitorio."]},{"display":"La cocina no es grande.","answers":["La cocina no es grande."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U07-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-mi-hogar-05','es1-mi-hogar','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"במטבח יש שולחן ושני כיסאות.","input":"sentence"},{"prompt":"חדר השינה שלי קטן ונוח.","input":"sentence"},{"prompt":"השולחן נמצא ליד החלון.","input":"sentence"},{"prompt":"אני מנקה את הסלון בימי שישי.","input":"sentence"}]}','{"items":[{"display":"En la cocina hay una mesa y dos sillas.","answers":["En la cocina hay una mesa y dos sillas."]},{"display":"Mi dormitorio es pequeño y cómodo.","answers":["Mi dormitorio es pequeño y cómodo."]},{"display":"La mesa está al lado de la ventana.","answers":["La mesa está al lado de la ventana."]},{"display":"Limpio la sala de estar los viernes.","answers":["Limpio la sala de estar los viernes."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U07-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-mi-hogar-06','es1-mi-hogar','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿Hay balcón?","input":"sentence"},{"prompt":"¿Dónde está la mesa?","input":"sentence"},{"prompt":"¿Qué hace la hermana en el dormitorio?","input":"sentence"}],"text":"Mi casa es pequeña, pero cómoda. Hay un dormitorio, una cocina y una sala de estar.\nNo hay balcón. En la sala de estar hay una mesa y dos sillas.\nLa mesa está al lado de la ventana. Leo en la sala de estar y cocino en la cocina.\nMi hermana estudia en el dormitorio."}','{"items":[{"display":"No, no hay balcón.","answers":["No, no hay balcón."]},{"display":"Está al lado de la ventana.","answers":["Está al lado de la ventana."]},{"display":"Estudia.","answers":["Estudia."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U07-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-mi-hogar-07','es1-mi-hogar','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Qué hay en tu habitación favorita?\n¿Cómo es esa habitación?\n¿Qué haces allí?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U07-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-mi-hogar-08','es1-mi-hogar','open','writing','כתיבה','כתבו תיאור של חדר בשישה משפטים. כללו שני משפטי hay, משפט עם estar, תיאור עם ser ושתי פעולות שאתם עושים בחדר.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Mi sala de estar es cómoda. Hay una mesa. Hay dos sillas. La mesa está cerca de la ventana. Leo en la sala de estar. También escucho música allí."],"criteria":""}','published','L1-U07-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-mi-hogar-09','es1-mi-hogar','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"Ella ___ levanta a las ocho.","input":"choice","options":["me","se"]},{"prompt":"___ casa es pequeña. (שלנו, נקבה יחידה)","input":"text"}]}','{"items":[{"display":"se","choice":1},{"display":"Nuestra","answers":["Nuestra"]}],"policy":{"accents":"strict"}}','published','L1-U07-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-mi-hogar-10','es1-mi-hogar','open','speaking','אתגר לבחירה','כתבו תיאור של בית דמיוני בלי לומר שזה בית: ארבעה רמזים על תכולה ופעולות. בקשו מאדם אחר לנחש.','self','{"prompt":"","brief":"","note":"משימה פתוחה לבחירה: אין מפתח. אפשר להביא את הניסוח לשיעור."}','{"models":[],"criteria":""}','published','L1-U07-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-mi-hogar-11','es1-mi-hogar','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["horno","cama","servilletas","hago la cama","sala de estar","televisión","velas","vaso"],"right":[{"id":"A","text":"אני מסדר את המיטה"},{"id":"B","text":"נרות"},{"id":"C","text":"כוס"},{"id":"D","text":"טלוויזיה"},{"id":"E","text":"מפיות"},{"id":"F","text":"תנור"},{"id":"G","text":"סלון"},{"id":"H","text":"מיטה"}]}','{"pairs":["F","H","E","A","G","D","B","C"],"policy":{"accents":"lenient"}}','published','L1-U07-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-mi-hogar-12','es1-mi-hogar','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"Guardo los platos en la ___.","input":"bank"},{"prompt":"Caliento la comida en el ___.","input":"bank"},{"prompt":"En el jardín hay una ___ de madera alrededor de las flores.","input":"bank"},{"prompt":"El niño juega en el ___.","input":"bank"},{"prompt":"Me seco las manos con una ___.","input":"bank"},{"prompt":"La sala tiene muchas ventanas; es muy ___.","input":"bank"}],"wordbank":["microondas","luminosa","columpio","valla","alacena","toalla"]}','{"items":[{"display":"alacena","answers":["alacena"]},{"display":"microondas","answers":["microondas"]},{"display":"valla","answers":["valla"]},{"display":"columpio","answers":["columpio"]},{"display":"toalla","answers":["toalla"]},{"display":"luminosa","answers":["luminosa"]}],"policy":{"accents":"strict"}}','published','L1-U07-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-mi-hogar-13','es1-mi-hogar','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"La cocina es pequeña.","cue":"רבים","input":"sentence"},{"prompt":"El dormitorio está ordenado.","cue":"רבים","input":"sentence"},{"prompt":"Yo limpio el baño.","cue":"nosotros","input":"sentence"},{"prompt":"Hay una silla en la cocina.","cue":"dos","input":"sentence"}]}','{"items":[{"display":"Las cocinas son pequeñas.","answers":["Las cocinas son pequeñas."]},{"display":"Los dormitorios están ordenados.","answers":["Los dormitorios están ordenados."]},{"display":"Nosotros limpiamos el baño.","answers":["Nosotros limpiamos el baño."]},{"display":"Hay dos sillas en la cocina.","answers":["Hay dos sillas en la cocina."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U07-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-mi-hogar-14','es1-mi-hogar','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"¿Cuál es tu habitación favorita?"},{"id":"B","text":"La sala de estar. Es muy acogedora."},{"id":"C","text":"Sí, y después quiero ver el jardín."},{"id":"D","text":"¿Qué hay en la sala?"},{"id":"E","text":"Hay un sofá y dos sillones. ¿Quieres verla?"}]}','{"order":["A","B","D","E","C"],"policy":{"accents":"strict"}}','published','L1-U07-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-mi-hogar-15','es1-mi-hogar','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Cómo es la cocina?","input":"sentence"},{"prompt":"¿Dónde está la manta?","input":"sentence"},{"prompt":"¿Qué hay en el jardín? Escribe dos cosas.","input":"sentence"},{"prompt":"¿Cuándo limpia Óscar la casa?","input":"sentence"}],"text":"La cocina de Óscar es pequeña y luminosa. Tiene un horno, un fregadero y una alacena. En la sala hay un sofá con una manta y dos sillones cómodos. Su jardín tiene flores, una valla y un columpio. Los domingos Óscar limpia la casa por la mañana y descansa en el jardín por la tarde."}','{"items":[{"display":"Es pequeña y luminosa.","answers":["Es pequeña y luminosa."]},{"display":"En el sofá.","answers":["En el sofá."]},{"display":"Flores, una valla y un columpio.","note":"מספיקים שני פריטים","answers":["Flores, una valla y un columpio."]},{"display":"Los domingos por la mañana.","answers":["Los domingos por la mañana."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U07-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-mi-hogar-16','es1-mi-hogar','open','writing','כותבים לחיים','תארו בית אמיתי או דמיוני. כללו שלושה חללים, שישה חפצים, שלושה שמות תואר ושתי פעולות שעושים בבית. השתמשו ב־hay, ser ו־estar.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Mi cocina es pequeña y luminosa. Hay un horno, un fregadero y una alacena, y cocino allí todos los días. La sala de estar es acogedora y tiene un sofá y dos sillones. Una manta está en el sofá. El jardín tiene flores y una valla verde. Los domingos limpio la casa y descanso en el jardín."],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U07-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-servicios-esenciales','es-1','es-1-daily','שירותים בשכונה','Servicios esenciales','לתאר מיקום של שירותים ולהסביר דרך.','workbook','[{"he":"מילות מקום","target":"al lado de · entre"},{"he":"הוראות דרך","target":"del · al"}]','["מיקום","הוראות דרך"]','{"rules":["מילות מקום מקשרות בין שני מקומות: al lado de · enfrente de · entre.","de ו־el מתחברים ל־del, בדיוק כמו a ו־el שהופכים ל־al.","הוראות הדרך נלמדות כאן כביטויים מוכנים. שתי הצורות נכונות: sigue recto = camina derecho · gira = dobla."],"examples":["El banco está al lado del parque.","La escuela está entre el banco y el museo.","Camina dos cuadras. Gira a la derecha. Sigue recto."],"tips":["cuadra היא המילה הנפוצה באמריקה הלטינית לקטע רחוב בין שתי פינות. בספרד אומרים manzana."],"mistakes":[{"text":"בעברית אין חיבור בין מילת יחס לתווית, ולכן de el ו־a el נשמעים תקינים לאוזן ישראלית. בספרדית הם תמיד מתכווצים. וזכרו: מיקום תמיד עם estar, לא ser.","pairs":[{"bad":"al lado de el parque","good":"al lado del parque"},{"bad":"La biblioteca es enfrente","good":"La biblioteca está enfrente"}]}]}','[{"term":"a pie","he":"ברגל"},{"term":"aeropuerto","he":"שדה תעופה"},{"term":"al final de","he":"בסוף"},{"term":"al lado de","he":"ליד"},{"term":"autobús","he":"אוטובוס"},{"term":"banco","he":"בנק / ספסל"},{"term":"barrio","he":"שכונה"},{"term":"biblioteca","he":"ספרייה"},{"term":"calle","he":"רחוב"},{"term":"caminar","he":"ללכת / לָלֶכֶת"},{"term":"casa","he":"בית פיזי / בית / בַּיִת"},{"term":"centro comercial","he":"קניון"},{"term":"centro de turismo","he":"מרכז מידע לתיירים"},{"term":"cerca de","he":"קרוב ל־ / קרוב ל"},{"term":"cine","he":"קולנוע"},{"term":"ciudad","he":"עיר"},{"term":"cruzar","he":"לחצות"},{"term":"cuadra","he":"מקטע רחוב בין שני צמתים"},{"term":"delante de","he":"לפני / בחזית של"},{"term":"dentista","he":"רופא שיניים"},{"term":"derecha","he":"ימינה / ימין"},{"term":"derecho","he":"ישר"},{"term":"desde","he":"מ־"},{"term":"detrás de","he":"מאחורי"},{"term":"dirección","he":"כיוון"},{"term":"doblar","he":"לפנות"},{"term":"edificio","he":"בניין"},{"term":"enfrente de","he":"ממול / מול"},{"term":"entre","he":"בין"},{"term":"escuela","he":"בית ספר"},{"term":"esquina","he":"פינה"},{"term":"estación","he":"תחנה / עונה"},{"term":"estación de bomberos","he":"תחנת כיבוי אש"},{"term":"estación de policía","he":"תחנת משטרה"},{"term":"este","he":"מזרח"},{"term":"farmacia","he":"בית מרקחת"},{"term":"florista","he":"מוכר פרחים / חנות פרחים במפה"},{"term":"frente a","he":"מול"},{"term":"girar","he":"לפנות"},{"term":"hasta","he":"עד"},{"term":"hospital","he":"בית חולים"},{"term":"hotel","he":"מלון"},{"term":"iglesia","he":"כנסייה"},{"term":"importante","he":"חשוב"},{"term":"izquierda","he":"שמאלה / שמאל"},{"term":"lavandería","he":"מכבסה"},{"term":"lejos de","he":"רחוק מ־ / רחוק מ"},{"term":"llegar","he":"להגיע"},{"term":"luego","he":"לאחר מכן"},{"term":"lugar","he":"מקום"},{"term":"museo","he":"מוזיאון"},{"term":"norte","he":"צפון"},{"term":"oeste","he":"מערב"},{"term":"panadería","he":"מאפייה"},{"term":"parada de autobús","he":"תחנת אוטובוס"},{"term":"parque","he":"פארק / פָּארְק"},{"term":"recomendar","he":"להמליץ"},{"term":"recto","he":"ישר"},{"term":"restaurante","he":"מסעדה"},{"term":"salgo","he":"אני יוצא"},{"term":"salir","he":"לצאת"},{"term":"seguir","he":"להמשיך"},{"term":"servicio","he":"שירות"},{"term":"supermercado","he":"סופרמרקט"},{"term":"sur","he":"דרום"},{"term":"teatro","he":"תיאטרון"},{"term":"trabajo","he":"עבודה"},{"term":"transporte","he":"תחבורה"},{"term":"veterinario","he":"וטרינר"},{"term":"zoológico","he":"גן חיות"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/998281436/esencial-services-basic-spanish-flash-cards/?new"}]','published','workbook L1 unit 08',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-servicios-esenciales-01','es1-servicios-esenciales','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"בנק ___","input":"text"},{"prompt":"ספרייה ___","input":"text"},{"prompt":"סופרמרקט ___","input":"text"},{"prompt":"תחנת אוטובוס ___","input":"text"}]}','{"items":[{"display":"banco","answers":["banco"]},{"display":"biblioteca","answers":["biblioteca"]},{"display":"supermercado","answers":["supermercado"]},{"display":"parada de autobús","answers":["parada de autobús"]}],"policy":{"accents":"lenient"}}','published','L1-U08-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-servicios-esenciales-02','es1-servicios-esenciales','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"El banco está al lado ___ parque.","input":"choice","options":["de el","del"]},{"prompt":"La escuela está ___ el banco y el museo.","input":"choice","options":["entre","con"]},{"prompt":"El museo está enfrente ___ la biblioteca.","input":"choice","options":["de","a"]},{"prompt":"___ dos cuadras.","input":"choice","options":["Camina","Caminar"]},{"prompt":"Gira a la ___.","input":"choice","options":["derecha","recto"]},{"prompt":"El banco ___ cerca.","input":"choice","options":["es","está"]},{"prompt":"La parada de autobús está ___ de la escuela.","input":"choice","options":["detrás","entre"]},{"prompt":"Voy ___ supermercado a pie.","input":"choice","options":["al","a el"]}]}','{"items":[{"display":"del","choice":1},{"display":"entre","choice":0},{"display":"de","choice":0},{"display":"Camina","choice":0},{"display":"derecha","choice":0},{"display":"está","choice":1},{"display":"detrás","choice":0},{"display":"al","choice":0}],"policy":{"accents":"strict"}}','published','L1-U08-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-servicios-esenciales-03','es1-servicios-esenciales','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"El banco está al lado de el parque.","input":"sentence"},{"prompt":"La biblioteca es enfrente de la escuela.","input":"sentence"},{"prompt":"Camina dos cuadras y gira la derecha.","input":"sentence"},{"prompt":"La escuela está entre el banco con el museo.","input":"sentence"}]}','{"items":[{"display":"El banco está al lado del parque.","answers":["El banco está al lado del parque."]},{"display":"La biblioteca está enfrente de la escuela.","answers":["La biblioteca está enfrente de la escuela."]},{"display":"Camina dos cuadras y gira a la derecha.","answers":["Camina dos cuadras y gira a la derecha."]},{"display":"La escuela está entre el banco y el museo.","answers":["La escuela está entre el banco y el museo."]}],"policy":{"accents":"strict"}}','published','L1-U08-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-servicios-esenciales-04','es1-servicios-esenciales','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"El banco está al lado de el museo. → תקנו","input":"sentence"},{"prompt":"La escuela está cerca. → שלילה","input":"sentence"},{"prompt":"camina / dos cuadras / y / gira / a la izquierda → סדרו","input":"sentence"}]}','{"items":[{"display":"El banco está al lado del museo.","answers":["El banco está al lado del museo."]},{"display":"La escuela no está cerca.","answers":["La escuela no está cerca."]},{"display":"Camina dos cuadras y gira a la izquierda.","answers":["Camina dos cuadras y gira a la izquierda."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U08-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-servicios-esenciales-05','es1-servicios-esenciales','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"הבנק נמצא ליד הפארק.","input":"sentence"},{"prompt":"הסופרמרקט מול בית הספר.","input":"sentence"},{"prompt":"לך ישר שני בלוקים.","input":"sentence"},{"prompt":"תפנה שמאלה בפינה.","input":"sentence"}]}','{"items":[{"display":"El banco está al lado del parque.","answers":["El banco está al lado del parque."]},{"display":"El supermercado está enfrente de la escuela.","answers":["El supermercado está enfrente de la escuela."]},{"display":"Sigue recto dos cuadras.","answers":["Sigue recto dos cuadras."]},{"display":"Gira a la izquierda en la esquina.","answers":["Gira a la izquierda en la esquina."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U08-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-servicios-esenciales-06','es1-servicios-esenciales','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿Qué hay entre el banco y la escuela?","input":"sentence"},{"prompt":"¿Dónde está el supermercado?","input":"sentence"},{"prompt":"¿Giras a la derecha o a la izquierda para ir a la biblioteca?","input":"sentence"}],"text":"En mi barrio hay una biblioteca entre el banco y la escuela.\nEl supermercado está enfrente de la escuela.\nPara ir de mi casa a la biblioteca, camina dos cuadras y gira a la derecha.\nLa biblioteca está al lado del banco. La parada de autobús está detrás de la escuela."}','{"items":[{"display":"Hay una biblioteca.","answers":["Hay una biblioteca."]},{"display":"Está enfrente de la escuela.","answers":["Está enfrente de la escuela."]},{"display":"A la derecha.","answers":["A la derecha."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U08-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-servicios-esenciales-07','es1-servicios-esenciales','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Qué servicios hay cerca de tu casa?\n¿Dónde está el supermercado?\n¿Cómo llegas allí a pie?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U08-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-servicios-esenciales-08','es1-servicios-esenciales','open','writing','כתיבה','בחרו נקודת מוצא ויעד בשכונה אמיתית או דמיונית. כתבו 3 הוראות דרך ושני משפטי מיקום. ציינו במפורש מאיפה מתחילים ולאן מגיעים.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["De mi casa al banco: camina una cuadra. Gira a la derecha. Sigue recto. El banco está al lado de la biblioteca. Está cerca del parque."],"criteria":""}','published','L1-U08-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-servicios-esenciales-09','es1-servicios-esenciales','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"En mi casa ___ dos ventanas.","input":"choice","options":["hay","está"]},{"prompt":"Voy ___ banco.","input":"choice","options":["al","en"]}]}','{"items":[{"display":"hay","choice":0},{"display":"al","choice":0}],"policy":{"accents":"strict"}}','published','L1-U08-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-servicios-esenciales-10','es1-servicios-esenciales','open','speaking','אתגר לבחירה','ציירו תרשים לפי טקסט הקריאה. הוסיפו שירות אחד ותארו את מיקומו בשני משפטים. מותר להשאיר מקום שאינו מוגדר בטקסט לבחירתכם.','self','{"prompt":"","brief":"","note":"משימה פתוחה לבחירה: אין מפתח. אפשר להביא את הניסוח לשיעור."}','{"models":[],"criteria":""}','published','L1-U08-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-servicios-esenciales-11','es1-servicios-esenciales','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["izquierda","enfrente de","salgo","parque","al lado de","caminar","supermercado","a pie"],"right":[{"id":"A","text":"סופרמרקט"},{"id":"B","text":"שמאלה"},{"id":"C","text":"ממול"},{"id":"D","text":"ברגל"},{"id":"E","text":"פארק"},{"id":"F","text":"אני יוצא"},{"id":"G","text":"ליד"},{"id":"H","text":"ללכת"}]}','{"pairs":["B","C","F","E","G","H","A","D"],"policy":{"accents":"lenient"}}','published','L1-U08-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-servicios-esenciales-12','es1-servicios-esenciales','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"Para sacar dinero voy al ___.","input":"bank"},{"prompt":"Para comprar medicinas voy a la ___.","input":"bank"},{"prompt":"Leo y estudio en la ___.","input":"bank"},{"prompt":"Espero el autobús en la ___.","input":"bank"},{"prompt":"La calle termina en una ___ con otra calle.","input":"bank"},{"prompt":"No tomo el autobús: voy ___.","input":"bank"}],"wordbank":["parada","a pie","biblioteca","farmacia","banco","esquina"]}','{"items":[{"display":"banco","answers":["banco"]},{"display":"farmacia","answers":["farmacia"]},{"display":"biblioteca","answers":["biblioteca"]},{"display":"parada","answers":["parada"]},{"display":"esquina","answers":["esquina"]},{"display":"a pie","answers":["a pie"]}],"policy":{"accents":"strict"}}','published','L1-U08-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-servicios-esenciales-13','es1-servicios-esenciales','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"La farmacia está al lado del banco.","cue":"רבים: בתי מרקחת","input":"sentence"},{"prompt":"Yo salgo de casa.","cue":"nosotros","input":"sentence"},{"prompt":"Camino dos cuadras.","cue":"ella","input":"sentence"},{"prompt":"El museo está cerca.","cue":"שלילה","input":"sentence"}]}','{"items":[{"display":"Las farmacias están al lado del banco.","answers":["Las farmacias están al lado del banco."]},{"display":"Nosotros salimos de casa.","answers":["Nosotros salimos de casa."]},{"display":"Ella camina dos cuadras.","answers":["Ella camina dos cuadras."]},{"display":"El museo no está cerca.","answers":["El museo no está cerca."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U08-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-servicios-esenciales-14','es1-servicios-esenciales','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"Sí, y enfrente del parque."},{"id":"B","text":"Camina dos cuadras y gira a la derecha."},{"id":"C","text":"¿Está al lado del supermercado?"},{"id":"D","text":"Muchas gracias. Voy a pie."},{"id":"E","text":"Perdona, ¿cómo llego a la biblioteca?"}]}','{"order":["E","B","C","A","D"],"policy":{"accents":"strict"}}','published','L1-U08-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-servicios-esenciales-15','es1-servicios-esenciales','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Qué está enfrente del parque?","input":"sentence"},{"prompt":"¿Dónde está el banco?","input":"sentence"},{"prompt":"¿Cuántas cuadras camina la persona antes de girar?","input":"sentence"},{"prompt":"¿Por qué prefiere ir a pie?","input":"sentence"}],"text":"En mi barrio, la biblioteca está enfrente del parque. El supermercado está al lado de la biblioteca y el banco está detrás del supermercado. Para llegar desde mi casa, camino dos cuadras y giro a la derecha. La parada de autobús está en la esquina del parque. Prefiero ir a pie porque todo está cerca."}','{"items":[{"display":"La biblioteca.","answers":["La biblioteca."]},{"display":"Detrás del supermercado.","answers":["Detrás del supermercado."]},{"display":"Dos cuadras.","answers":["Dos cuadras."]},{"display":"Porque todo está cerca.","answers":["Porque todo está cerca."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U08-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-servicios-esenciales-16','es1-servicios-esenciales','open','writing','כותבים לחיים','כתבו הוראות הגעה מהבית למקום בשכונה. הזכירו שלושה שירותים, שלושה ביטויי מקום ושתי פעולות של תנועה. אפשר להמציא את מפת השכונה.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["En mi barrio hay una biblioteca, un banco y un supermercado. La biblioteca está enfrente del parque. El banco está al lado de la biblioteca y el supermercado está detrás del banco. Salgo de mi casa y camino dos cuadras. Después giro a la derecha y llego a la biblioteca. Voy a pie porque está cerca."],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U08-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-viajes','es-1','es-1-out','טיולים','Viajes','לשאול שאלות לקראת נסיעה ולבקש או לתת הוראות דרך.','workbook','[{"he":"מילות שאלה","target":"¿Adónde? ¿Con quién?"},{"he":"הוראות דרך","target":"¿Cómo llego a…?"}]','["שאלות","הוראות דרך"]','{"rules":["¿Adónde? שואל על יעד, ¿Dónde? על מיקום ו־¿Cómo? על אופן או דרך.","לשאלת ליווי משתמשים ב־¿Con quién?, והתשובה נפתחת ב־con.","כדי לבקש דרך: ¿Cómo llego a…?, ומשיבים בביטויי הדרך מהשיעור."],"examples":["¿Adónde viajas? A Madrid.","¿Con quién viajas? Con mi familia.","¿Cómo llego al hotel? Sigue recto y gira a la izquierda."],"tips":["vacaciones היא מילה ברבים תמיד: אומרים unas vacaciones largas, לא una vacación."],"mistakes":[{"text":"בעברית \"איפה\" ו\"לאן\" נבדלות, אבל בתרגום מהיר שוכחים את ¿Adónde?. ושימו לב לזוג המבלבל: derecha היא ימינה, ואילו ישר זה recto או derecho.","pairs":[{"bad":"¿Dónde viajas? A Madrid","good":"¿Adónde viajas? A Madrid"},{"bad":"Sigue derecha","good":"Sigue recto"}]}]}','[{"term":"a la derecha","he":"ימינה"},{"term":"a la izquierda","he":"שמאלה"},{"term":"actividades","he":"פעילויות"},{"term":"adónde","he":"לאן"},{"term":"agencia","he":"סוכנות נסיעות"},{"term":"agente","he":"סוכן"},{"term":"al lado de","he":"ליד"},{"term":"amigos","he":"חברים"},{"term":"atracción","he":"אטרקציה"},{"term":"autobús","he":"אוטובוס"},{"term":"avión","he":"מטוס"},{"term":"banco","he":"בנק / ספסל"},{"term":"beber","he":"לשתות / לִשְׁתּוֹת"},{"term":"billete","he":"כרטיס נסיעה"},{"term":"boleto","he":"כרטיס נסיעה"},{"term":"cálido","he":"חמים / חם"},{"term":"cámara","he":"מצלמה"},{"term":"caminar","he":"ללכת / לָלֶכֶת"},{"term":"cerca de","he":"קרוב ל־ / קרוב ל"},{"term":"ciudad","he":"עיר"},{"term":"clima","he":"מזג אוויר"},{"term":"comer","he":"לאכול / לֶאֱכוֹל"},{"term":"comida","he":"אוכל / אוכל או ארוחה"},{"term":"cómo","he":"איך"},{"term":"comprar","he":"לקנות"},{"term":"con quién","he":"עם מי"},{"term":"cuadras","he":"מקטעי רחוב בין צמתים"},{"term":"cuándo","he":"מתי"},{"term":"derecha","he":"ימינה / ימין"},{"term":"destino","he":"יעד"},{"term":"direcciones","he":"הוראות דרך"},{"term":"doblar","he":"לפנות"},{"term":"dónde","he":"איפה"},{"term":"dormir","he":"לישון / לִישׁוֹן"},{"term":"empacar","he":"לארוז"},{"term":"enfrente de","he":"ממול / מול"},{"term":"época","he":"תקופה"},{"term":"estación","he":"תחנה / עונה"},{"term":"explorar","he":"לחקור"},{"term":"familia","he":"משפחה"},{"term":"frío","he":"קר"},{"term":"gente","he":"אנשים"},{"term":"girar","he":"לפנות"},{"term":"hermana","he":"אחות"},{"term":"hospedarse","he":"להתארח / ללון"},{"term":"hotel","he":"מלון"},{"term":"izquierda","he":"שמאלה / שמאל"},{"term":"julio","he":"יולי"},{"term":"lejos de","he":"רחוק מ־ / רחוק מ"},{"term":"lugares","he":"מקומות"},{"term":"maleta","he":"מזוודה"},{"term":"mapa","he":"מפה"},{"term":"mar","he":"ים"},{"term":"museo","he":"מוזיאון"},{"term":"música","he":"מוזיקה / מוּזִיקָה"},{"term":"país","he":"מדינה / ארץ / מדינה"},{"term":"pasaporte","he":"דרכון"},{"term":"playa","he":"חוף / חוף ים / חוֹף"},{"term":"popular","he":"פופולרי"},{"term":"por la tarde","he":"אחרי הצהריים"},{"term":"por qué","he":"למה"},{"term":"preferir","he":"להעדיף"},{"term":"preguntar","he":"לשאול"},{"term":"preguntas","he":"שאלות"},{"term":"qué","he":"מה"},{"term":"recto","he":"ישר"},{"term":"responder","he":"לענות"},{"term":"respuestas","he":"תשובות"},{"term":"restaurante","he":"מסעדה"},{"term":"ropa","he":"בגדים"},{"term":"seguir","he":"להמשיך"},{"term":"solo","he":"לבד"},{"term":"souvenir","he":"מזכרת"},{"term":"tomar","he":"לקחת / לנסוע בתחבורה"},{"term":"transporte","he":"תחבורה"},{"term":"vacaciones","he":"חופשה"},{"term":"verano","he":"קיץ"},{"term":"viajar","he":"לטייל / לנסוע"},{"term":"viaje","he":"נסיעה / טיול"},{"term":"viajero","he":"נוסע / מטייל / מטייל"},{"term":"visitar","he":"לבקר"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1064751034/viajes-actualizado-flash-cards/?i=1b52po&x=1jqt"}]','published','workbook L1 unit 09',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-viajes-01','es1-viajes','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"טיול ___","input":"text"},{"prompt":"חופשה ___","input":"text"},{"prompt":"יעד ___","input":"text"},{"prompt":"מזוודה ___","input":"text"}]}','{"items":[{"display":"viaje","answers":["viaje"]},{"display":"vacaciones","answers":["vacaciones"]},{"display":"destino","answers":["destino"]},{"display":"maleta","answers":["maleta"]}],"policy":{"accents":"lenient"}}','published','L1-U09-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-viajes-02','es1-viajes','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"¿___ viajas? A Madrid.","input":"choice","options":["Adónde","Quién"]},{"prompt":"¿Con ___ viajas? Con Ana.","input":"choice","options":["qué","quién"]},{"prompt":"¿___ llego al hotel?","input":"choice","options":["Cómo","Cuánto"]},{"prompt":"El hotel está ___ la estación.","input":"choice","options":["cerca de","con"]},{"prompt":"Sigue ___.","input":"choice","options":["recto","derecha"]},{"prompt":"Viajo ___ avión.","input":"choice","options":["en","a"]},{"prompt":"¿___ está el hotel? Cerca de la estación.","input":"choice","options":["Dónde","Adónde"]},{"prompt":"Viajo ___ mi familia.","input":"choice","options":["con","en"]}]}','{"items":[{"display":"Adónde","choice":0},{"display":"quién","choice":1},{"display":"Cómo","choice":0},{"display":"cerca de","choice":0},{"display":"recto","choice":0},{"display":"en","choice":0},{"display":"Dónde","choice":0},{"display":"con","choice":0}],"policy":{"accents":"strict"}}','published','L1-U09-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-viajes-03','es1-viajes','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"¿Dónde viajas? A Madrid.","input":"sentence"},{"prompt":"Viajo en mi hermana.","input":"sentence"},{"prompt":"¿Cómo llego a el museo?","input":"sentence"},{"prompt":"Sigue derecha dos cuadras.","input":"sentence"}]}','{"items":[{"display":"¿Adónde viajas? A Madrid.","answers":["¿Adónde viajas? A Madrid."]},{"display":"Viajo con mi hermana.","answers":["Viajo con mi hermana."]},{"display":"¿Cómo llego al museo?","answers":["¿Cómo llego al museo?"]},{"display":"Sigue recto dos cuadras.","answers":["Sigue recto dos cuadras."]}],"policy":{"accents":"strict"}}','published','L1-U09-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-viajes-04','es1-viajes','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"Viajo con mi hermano. → שאלה עם Con quién","input":"sentence"},{"prompt":"Duermo en un hotel. → שאלה עם Dónde","input":"sentence"},{"prompt":"¿Dónde viajas? A Madrid. → תקנו את השאלה","input":"sentence"}]}','{"items":[{"display":"¿Con quién viajas?","answers":["¿Con quién viajas?"]},{"display":"¿Dónde duermes?","answers":["¿Dónde duermes?"]},{"display":"¿Adónde viajas?","answers":["¿Adónde viajas?"]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U09-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-viajes-05','es1-viajes','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"לאן אתה נוסע?","input":"sentence"},{"prompt":"אני נוסע עם המשפחה שלי.","input":"sentence"},{"prompt":"איך אני מגיע למלון?","input":"sentence"},{"prompt":"המלון נמצא ליד התחנה.","input":"sentence"}]}','{"items":[{"display":"¿Adónde viajas?","answers":["¿Adónde viajas?"]},{"display":"Viajo con mi familia.","answers":["Viajo con mi familia."]},{"display":"¿Cómo llego al hotel?","answers":["¿Cómo llego al hotel?"]},{"display":"El hotel está cerca de la estación.","answers":["El hotel está cerca de la estación."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U09-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-viajes-06','es1-viajes','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿Con quién viaja Lucía?","input":"sentence"},{"prompt":"¿Cómo viajan?","input":"sentence"},{"prompt":"¿Dónde está el museo?","input":"sentence"}],"text":"Lucía viaja a Valencia con su hermano. Viajan en tren y duermen en un hotel cerca de la estación.\nEn su maleta hay ropa y una cámara.\nLucía pregunta: «¿Cómo llego al museo?».\nUna mujer responde: «Sigue recto dos cuadras y gira a la izquierda. El museo está enfrente del parque»."}','{"items":[{"display":"Viaja con su hermano.","answers":["Viaja con su hermano."]},{"display":"Viajan en tren.","answers":["Viajan en tren."]},{"display":"Está enfrente del parque.","answers":["Está enfrente del parque."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U09-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-viajes-07','es1-viajes','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Adónde quieres viajar?\n¿Con quién viajas normalmente?\n¿Qué llevas en tu maleta?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U09-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-viajes-08','es1-viajes','open','writing','כתיבה','כתבו שיחה של 6 שורות בין תייר לעובד במלון. כללו שתי שאלות על מקומות, בקשת הוראות דרך ותשובה עם שתי הוראות.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["A: ¿Dónde está el museo? B: Está cerca del parque. A: ¿Cómo llego al museo? B: Camina dos cuadras y gira a la derecha. A: ¿Hay un restaurante cerca? B: Sí, al lado del museo."],"criteria":""}','published','L1-U09-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-viajes-09','es1-viajes','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"al lado de el banco → תקנו","input":"text"},{"prompt":"¿___ te llamas?","input":"choice","options":["Cómo","Dónde"]}]}','{"items":[{"display":"al lado del banco","answers":["al lado del banco"]},{"display":"Cómo","choice":0}],"policy":{"accents":"strict"}}','published','L1-U09-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-viajes-10','es1-viajes','open','speaking','אתגר לבחירה','הקליטו שיחת תייר של 45 שניות בשני תפקידים. לאחר ההאזנה בדקו ששאלה על מקום אכן מקבלת תשובה על מקום.','self','{"prompt":"","brief":"","note":"משימה פתוחה לבחירה: אין מפתח. אפשר להביא את הניסוח לשיעור."}','{"models":[],"criteria":""}','published','L1-U09-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-viajes-11','es1-viajes','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["beber","playa","explorar","actividades","direcciones","ciudad","cámara","amigos"],"right":[{"id":"A","text":"לשתות"},{"id":"B","text":"מצלמה"},{"id":"C","text":"פעילויות"},{"id":"D","text":"חוף"},{"id":"E","text":"עיר"},{"id":"F","text":"לחקור"},{"id":"G","text":"חברים"},{"id":"H","text":"הוראות דרך"}]}','{"pairs":["A","D","F","C","H","E","B","G"],"policy":{"accents":"lenient"}}','published','L1-U09-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-viajes-12','es1-viajes','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"Guardo la ropa en la ___.","input":"bank"},{"prompt":"Para encontrar las calles, miro el ___.","input":"bank"},{"prompt":"En vacaciones duermo en un ___.","input":"bank"},{"prompt":"Compro un pequeño ___ para recordar el viaje.","input":"bank"},{"prompt":"Para tomar fotos llevo una ___.","input":"bank"},{"prompt":"No giro: sigo ___.","input":"bank"}],"wordbank":["mapa","souvenir","hotel","maleta","recto","cámara"]}','{"items":[{"display":"maleta","answers":["maleta"]},{"display":"mapa","answers":["mapa"]},{"display":"hotel","answers":["hotel"]},{"display":"souvenir","answers":["souvenir"]},{"display":"cámara","answers":["cámara"]},{"display":"recto","answers":["recto"]}],"policy":{"accents":"strict"}}','published','L1-U09-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-viajes-13','es1-viajes','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"Viajo con mi hermana.","cue":"nosotros","input":"sentence"},{"prompt":"Yo empaco la maleta.","cue":"ella","input":"sentence"},{"prompt":"El hotel está cerca de la playa.","cue":"רבים","input":"sentence"},{"prompt":"Preguntamos por el museo.","cue":"yo","input":"sentence"}]}','{"items":[{"display":"Viajamos con nuestra hermana.","answers":["Viajamos con nuestra hermana."]},{"display":"Ella empaca la maleta.","answers":["Ella empaca la maleta."]},{"display":"Los hoteles están cerca de la playa.","answers":["Los hoteles están cerca de la playa."]},{"display":"Pregunto por el museo.","answers":["Pregunto por el museo."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U09-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-viajes-14','es1-viajes','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"¿Dónde está el museo?"},{"id":"B","text":"Sí, está enfrente del hotel, al lado del banco."},{"id":"C","text":"¿Está cerca del hotel?"},{"id":"D","text":"Gracias. Voy a visitarlo ahora."},{"id":"E","text":"Camina una cuadra y gira a la izquierda."}]}','{"order":["A","E","C","B","D"],"policy":{"accents":"strict"}}','published','L1-U09-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-viajes-15','es1-viajes','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Con quién viaja Sara?","input":"sentence"},{"prompt":"¿Cómo viajan?","input":"sentence"},{"prompt":"¿Qué empaca Sara? Escribe dos cosas.","input":"sentence"},{"prompt":"¿Hacia dónde giran para llegar al museo?","input":"sentence"}],"text":"Sara viaja a la playa con su hermana. Las dos van en autobús y duermen en un hotel cerca del mar. Sara empaca ropa, una cámara y un mapa. Por la mañana visitan el museo: caminan una cuadra y giran a la izquierda. Por la tarde compran un souvenir y comen en un restaurante."}','{"items":[{"display":"Con su hermana.","answers":["Con su hermana."]},{"display":"En autobús.","answers":["En autobús."]},{"display":"Ropa, una cámara y un mapa.","note":"מספיקים שני פריטים","answers":["Ropa, una cámara y un mapa."]},{"display":"A la izquierda.","answers":["A la izquierda."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U09-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-viajes-16','es1-viajes','open','writing','כותבים לחיים','תכננו יום טיול. ציינו יעד, תחבורה, מקום לינה ושלושה פריטים שתארזו. הוסיפו הוראות הגעה קצרות למקום אחד.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Viajo a la playa con mi familia y vamos en autobús. Dormimos en un hotel cerca del mar. Empaco ropa, una cámara y un mapa. Por la mañana visitamos un museo. Para llegar, caminamos una cuadra y giramos a la izquierda. Por la tarde compramos un souvenir y comemos en un restaurante."],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U09-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-comidas','es-1','es-1-leisure','אוכל','Comidas','לתאר הרגלי אכילה ולהשתמש בכינויי שייכות.','workbook','[{"he":"פעלים בהווה","target":"comer · beber"},{"he":"שייכות","target":"mi · su · nuestro"}]','["הווה","שייכות"]','{"rules":["פעלים כמו comer · beber · cocinar משתנים לפי הגוף.","כינוי השייכות מתאים לדבר השייך: mi comida / mis comidas, וכן nuestro pan / nuestra leche.","כדי לבקש אוכל בנימוס: Quiero… , por favor."],"examples":["Yo como. Ella come. Nosotros comemos.","Mi comida favorita es la pizza.","Nuestra comida está lista. Quiero agua, por favor."],"tips":["comida היא גם אוכל בכלל וגם ארוחה מסוימת. ולציון העדפה משתמשים בתווית: Me gusta la pizza."],"mistakes":[{"text":"בעברית \"האוכל שלנו\" אינו משנה דבר לפי מין, ובספרדית הכינוי והתואר שניהם מתיישרים לפי שם העצם: nuestro pan אבל nuestra leche. וכשיש גוף, הפועל חייב הטיה ולא נשאר בשם הפועל.","pairs":[{"bad":"Nosotros comer en casa","good":"Nosotros comemos en casa"},{"bad":"Nuestro leche","good":"Nuestra leche"}]}]}','[{"term":"abrir","he":"לפתוח"},{"term":"aceite","he":"שמן"},{"term":"agregar","he":"להוסיף"},{"term":"agua","he":"מים / מַיִם"},{"term":"aguapanela colombiana","he":"אגואפנלה קולומביאנית"},{"term":"almuerzo","he":"ארוחת צהריים"},{"term":"amargo","he":"מר"},{"term":"amigo","he":"חבר"},{"term":"arepas colombianas","he":"ארפס קולומביאניות"},{"term":"arroz con leche","he":"אורז בחלב"},{"term":"asado argentino","he":"אסאדו ארגנטינאי"},{"term":"banana","he":"בננה"},{"term":"bandeja paisa colombiana","he":"בנדחה פאיסה, מנה קולומביאנית"},{"term":"beber","he":"לשתות / לִשְׁתּוֹת"},{"term":"bebida","he":"משקה"},{"term":"bienvenido","he":"ברוך הבא"},{"term":"boda","he":"חתונה"},{"term":"buenas noches","he":"ערב טוב / לילה טוב"},{"term":"buenas tardes","he":"אחר צהריים טובים"},{"term":"buenos días","he":"בוקר טוב"},{"term":"caipirinha brasileña","he":"קוקטייל קאיפיריניה ברזילאי"},{"term":"camarero","he":"מלצר"},{"term":"canelazo ecuatoriano","he":"משקה קנלאסו מאקוודור"},{"term":"carne","he":"בשר"},{"term":"cena","he":"ארוחת ערב"},{"term":"cerrar","he":"לסגור"},{"term":"cerveza","he":"בירה"},{"term":"ceviche de ecuador","he":"סביצ׳ה מאקוודור"},{"term":"chocolate","he":"שוקולד / שׁוֹקוֹלָד"},{"term":"chocotorta","he":"צ׳וקוטורטה, עוגה ארגנטינאית"},{"term":"cliente","he":"לקוח"},{"term":"cocinar","he":"לבשל"},{"term":"colega","he":"עמית"},{"term":"comer","he":"לאכול / לֶאֱכוֹל"},{"term":"comida","he":"אוכל / אוכל או ארוחה"},{"term":"con","he":"עם"},{"term":"cortar","he":"לחתוך"},{"term":"coxinha brasileña","he":"קושיניה ברזילאית"},{"term":"cuchillo","he":"סכין"},{"term":"cuenta","he":"חשבון"},{"term":"delicioso","he":"טעים מאוד"},{"term":"desayuno","he":"ארוחת בוקר / אני אוכל ארוחת בוקר"},{"term":"después","he":"אחרי / אחר כך"},{"term":"dulce","he":"מתוק"},{"term":"dulce de leche","he":"ריבת חלב"},{"term":"efectivo","he":"מזומן"},{"term":"empanadas argentinas","he":"אמפנדס ארגנטינאיות"},{"term":"ensalada","he":"סלט"},{"term":"entrada","he":"מנה ראשונה / כרטיס כניסה"},{"term":"esposa","he":"אישה נשואה / רעיה / רעיה"},{"term":"esposo","he":"בעל"},{"term":"favorito","he":"מועדף / אהוב"},{"term":"feijoada brasileña","he":"פז׳ואדה ברזילאית"},{"term":"feo","he":"לא מוצלח / מכוער"},{"term":"fernet con coca","he":"פרנט עם קולה"},{"term":"finalmente","he":"לבסוף"},{"term":"fresco","he":"קריר / טרי"},{"term":"frío","he":"קר"},{"term":"fruta","he":"פרי"},{"term":"hamburguesa","he":"המבורגר"},{"term":"horchata mexicana","he":"משקה הורצ׳טה מקסיקני"},{"term":"hornado ecuatoriano","he":"הורנדו מאקוודור"},{"term":"ingrediente","he":"מרכיב"},{"term":"invitado","he":"אורח"},{"term":"lasaña","he":"לזניה"},{"term":"leche","he":"חלב"},{"term":"lechuga","he":"חסה"},{"term":"lomo saltado peruano","he":"לומו סלטדו פרואני"},{"term":"mantequilla","he":"חמאה"},{"term":"manzana","he":"תפוח"},{"term":"mate argentino","he":"מאטה ארגנטינאי"},{"term":"menú","he":"תפריט"},{"term":"mi","he":"שלי"},{"term":"mis","he":"שלי לפני שם ברבים / שלי (רבים)"},{"term":"mitad","he":"חצי"},{"term":"mousse de maracuyá","he":"מוס פסיפלורה"},{"term":"muchas gracias","he":"תודה רבה"},{"term":"naranja","he":"תפוז"},{"term":"nuestra","he":"שלנו לפני שם בנקבה / שלנו (נקבה)"},{"term":"nuestras","he":"שלנו לפני שם בנקבה רבות"},{"term":"nuestro","he":"שלנו לפני שם בזכר / שלנו"},{"term":"nuestros","he":"שלנו לפני שם בזכר רבים"},{"term":"ordenar","he":"להזמין"},{"term":"pabellón criollo venezolano","he":"פביון קריויו, מנה מוונצואלה"},{"term":"pagar","he":"לשלם"},{"term":"pan","he":"לחם"},{"term":"panadería","he":"מאפייה"},{"term":"pão de queijo brasileño","he":"לחמניות גבינה ברזילאיות, שם בפורטוגזית"},{"term":"pedir","he":"לבקש / להזמין / לבקש"},{"term":"pesado","he":"כבד"},{"term":"pescado","he":"דג למאכל"},{"term":"pisco sour peruano","he":"קוקטייל פיסקו סאוור פרואני"},{"term":"pizza","he":"פיצה"},{"term":"plato","he":"צלחת / מנה"},{"term":"plato principal","he":"מנה עיקרית"},{"term":"poner","he":"לשים"},{"term":"por la mitad","he":"לשניים / לחצי"},{"term":"postre","he":"קינוח"},{"term":"preparar","he":"להכין"},{"term":"primero","he":"ראשית / ראשון"},{"term":"queso","he":"גבינה"},{"term":"receta","he":"מתכון"},{"term":"restaurante","he":"מסעדה"},{"term":"rico","he":"טעים"},{"term":"sabor","he":"טעם"},{"term":"sal","he":"מלח"},{"term":"salado","he":"מלוח"},{"term":"sándwich","he":"סנדוויץ׳"},{"term":"seco","he":"יבש"},{"term":"servir","he":"לשרת / להגיש"},{"term":"sin","he":"בלי"},{"term":"socio","he":"שותף"},{"term":"su","he":"שלו / שלה / שלו / שלה / שלהם / שלו/שלה/שלהם"},{"term":"sus","he":"שלו / שלה / שלהם לפני שם ברבים / שלהם/שלה"},{"term":"sushi","he":"סושי"},{"term":"tacos mexicanos","he":"טאקו מקסיקניים"},{"term":"tarjeta","he":"כרטיס תשלום"},{"term":"tarjeta de crédito","he":"כרטיס אשראי"},{"term":"tequila mexicano","he":"טקילה מקסיקנית"},{"term":"tomate","he":"עגבנייה"},{"term":"torta de tres leches","he":"עוגת שלושת סוגי החלב"},{"term":"traer","he":"להביא"},{"term":"tu","he":"שלך"},{"term":"tus","he":"שלך לפני שם ברבים / שלך (רבים)"},{"term":"untar","he":"למרוח"},{"term":"vino","he":"יין"},{"term":"vino blanco","he":"יין לבן"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/856050542/basic-spanish-food-flash-cards/?new"}]','published','workbook L1 unit 10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-comidas-01','es1-comidas','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"אוכל או ארוחה ___","input":"text"},{"prompt":"ארוחת בוקר ___","input":"text"},{"prompt":"ארוחת צהריים ___","input":"text"},{"prompt":"ארוחת ערב ___","input":"text"}]}','{"items":[{"display":"comida","answers":["comida"]},{"display":"desayuno","answers":["desayuno"]},{"display":"almuerzo","answers":["almuerzo"]},{"display":"cena","answers":["cena"]}],"policy":{"accents":"lenient"}}','published','L1-U10-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-comidas-02','es1-comidas','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"Yo ___ pan en el desayuno.","hint":"comer","input":"text"},{"prompt":"Ella ___ agua.","hint":"beber","input":"text"},{"prompt":"Nosotros ___ en casa.","hint":"cocinar","input":"text"},{"prompt":"___ comida favorita es la pizza.","cue":"שלי","input":"choice","options":["Mi","Mis"]},{"prompt":"___ frutas favoritas son las manzanas.","cue":"שלו","input":"choice","options":["Su","Sus"]},{"prompt":"Es ___ leche.","cue":"שלנו","input":"choice","options":["nuestro","nuestra"]},{"prompt":"Mis hermanos ___ pasta.","hint":"comer","input":"text"},{"prompt":"___ padres cenan con nosotros.","cue":"שלנו","input":"choice","options":["Nuestro","Nuestros"]}]}','{"items":[{"display":"como","answers":["como"]},{"display":"bebe","answers":["bebe"]},{"display":"cocinamos","answers":["cocinamos"]},{"display":"Mi","choice":0},{"display":"Sus","choice":1},{"display":"nuestra","choice":1},{"display":"comen","answers":["comen"]},{"display":"Nuestros","choice":1}],"policy":{"accents":"strict"}}','published','L1-U10-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-comidas-03','es1-comidas','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"Mi comida favoritas es la pizza.","input":"sentence"},{"prompt":"Nosotros comer en casa.","input":"sentence"},{"prompt":"Su frutas favoritas son las manzanas.","input":"sentence"},{"prompt":"Nuestro leche está fría.","input":"sentence"}]}','{"items":[{"display":"Mi comida favorita es la pizza.","answers":["Mi comida favorita es la pizza."]},{"display":"Nosotros comemos en casa.","answers":["Nosotros comemos en casa."]},{"display":"Sus frutas favoritas son las manzanas.","answers":["Sus frutas favoritas son las manzanas."]},{"display":"Nuestra leche está fría.","answers":["Nuestra leche está fría."]}],"policy":{"accents":"strict"}}','published','L1-U10-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-comidas-04','es1-comidas','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"Yo como fruta. → Ellos…","input":"sentence"},{"prompt":"mi comida favorita → רבים","input":"sentence"},{"prompt":"Ella bebe café. → שלילה","input":"sentence"}]}','{"items":[{"display":"Ellos comen fruta.","answers":["Ellos comen fruta."]},{"display":"mis comidas favoritas","answers":["mis comidas favoritas"]},{"display":"Ella no bebe café.","answers":["Ella no bebe café."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U10-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-comidas-05','es1-comidas','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"אני אוכל לחם בארוחת בוקר.","input":"sentence"},{"prompt":"המאכל האהוב עליי הוא פיצה.","input":"sentence"},{"prompt":"אנחנו מבשלים בבית.","input":"sentence"},{"prompt":"ההורים שלנו אוכלים איתנו ארוחת ערב.","input":"sentence"}]}','{"items":[{"display":"Como pan en el desayuno.","answers":["Como pan en el desayuno."]},{"display":"Mi comida favorita es la pizza.","answers":["Mi comida favorita es la pizza."]},{"display":"Cocinamos en casa.","answers":["Cocinamos en casa."]},{"display":"Nuestros padres cenan con nosotros.","answers":["Nuestros padres cenan con nosotros."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U10-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-comidas-06','es1-comidas','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿Qué bebe Paula en el desayuno?","input":"sentence"},{"prompt":"¿Cuál es la comida favorita de Paula y su hermano?","input":"sentence"},{"prompt":"¿Quién cocina arroz?","input":"sentence"}],"text":"Soy Paula. En el desayuno como pan y bebo café con leche.\nMi hermano come fruta y bebe agua. Nuestra comida favorita es la pasta.\nAl mediodía comemos en casa. Por la noche mi hermano cocina arroz y yo preparo una ensalada.\nNuestros padres cenan con nosotros."}','{"items":[{"display":"Bebe café con leche.","answers":["Bebe café con leche."]},{"display":"Es la pasta.","answers":["Es la pasta."]},{"display":"Su hermano cocina arroz.","answers":["Su hermano cocina arroz."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U10-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-comidas-07','es1-comidas','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Qué comes en el desayuno?\n¿Cuál es tu comida favorita?\n¿Qué cocina una persona de tu familia?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U10-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-comidas-08','es1-comidas','open','writing','כתיבה','כתבו תפריט יומי אישי של 5 או 6 משפטים. תארו בוקר, צהריים וערב והוסיפו העדפה של אדם אחר. השתמשו בשלושה כינויי שייכות שונים.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Mi desayuno es sencillo. Como pan y bebo café. En el almuerzo como arroz. Mi hermana come pasta. Su comida favorita es la pizza. Nuestra cena es una ensalada."],"criteria":""}','published','L1-U10-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-comidas-09','es1-comidas','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"___ padres viven en Madrid. (שלנו)","input":"text"},{"prompt":"Nosotros ___ correos.","hint":"escribir","input":"text"}]}','{"items":[{"display":"Nuestros","answers":["Nuestros"]},{"display":"escribimos","answers":["escribimos"]}],"policy":{"accents":"strict"}}','published','L1-U10-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-comidas-10','es1-comidas','open','speaking','אתגר לבחירה','תכננו ארוחה לשני אנשים עם העדפות שונות. כתבו מה כל אחד אוכל ושותה ומה משותף להם, בלי להשתמש בזמן עתיד.','self','{"prompt":"","brief":"","note":"משימה פתוחה לבחירה: אין מפתח. אפשר להביא את הניסוח לשיעור."}','{"models":[],"criteria":""}','published','L1-U10-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-comidas-11','es1-comidas','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["naranja","efectivo","su","abrir","agregar","restaurante","banana","queso"],"right":[{"id":"A","text":"בננה"},{"id":"B","text":"לפתוח"},{"id":"C","text":"תפוז"},{"id":"D","text":"גבינה"},{"id":"E","text":"מזומן"},{"id":"F","text":"מסעדה"},{"id":"G","text":"להוסיף"},{"id":"H","text":"שלו / שלה / שלהם"}]}','{"pairs":["C","E","H","B","G","F","A","D"],"policy":{"accents":"lenient"}}','published','L1-U10-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-comidas-12','es1-comidas','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"Uso un cuchillo para ___ el tomate.","input":"bank"},{"prompt":"Voy a ___ mantequilla en el pan.","input":"bank"},{"prompt":"Antes de beber, necesito ___ la botella.","input":"bank"},{"prompt":"Quiero la hamburguesa ___ queso; no como queso.","input":"bank"},{"prompt":"No tengo efectivo; pago con ___.","input":"bank"},{"prompt":"Como una ensalada de ___.","input":"bank"}],"wordbank":["abrir","tarjeta","entrada","sin","cortar","untar"]}','{"items":[{"display":"cortar","answers":["cortar"]},{"display":"untar","answers":["untar"]},{"display":"abrir","answers":["abrir"]},{"display":"sin","answers":["sin"]},{"display":"tarjeta","answers":["tarjeta"]},{"display":"entrada","answers":["entrada"]}],"policy":{"accents":"strict"}}','published','L1-U10-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-comidas-13','es1-comidas','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"Mi sándwich tiene queso.","cue":"רבים","input":"sentence"},{"prompt":"Nuestro cliente paga con tarjeta.","cue":"נקבה","input":"sentence"},{"prompt":"Yo corto el pan.","cue":"nosotros","input":"sentence"},{"prompt":"Tú pones el tomate.","cue":"ella","input":"sentence"}]}','{"items":[{"display":"Mis sándwiches tienen queso.","answers":["Mis sándwiches tienen queso."]},{"display":"Nuestra clienta paga con tarjeta.","answers":["Nuestra clienta paga con tarjeta."]},{"display":"Nosotros cortamos el pan.","answers":["Nosotros cortamos el pan."]},{"display":"Ella pone el tomate.","answers":["Ella pone el tomate."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U10-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-comidas-14','es1-comidas','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"Muy bien. Una ensalada, una hamburguesa sin queso y agua."},{"id":"B","text":"Buenas tardes. ¿Qué quiere de entrada?"},{"id":"C","text":"Una ensalada, por favor."},{"id":"D","text":"Una hamburguesa sin queso y un vaso de agua."},{"id":"E","text":"¿Y de plato principal?"}]}','{"order":["B","C","E","D","A"],"policy":{"accents":"strict"}}','published','L1-U10-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-comidas-15','es1-comidas','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Quién cocina?","input":"sentence"},{"prompt":"¿Qué pide la clienta de entrada?","input":"sentence"},{"prompt":"¿Qué bebe su amigo?","input":"sentence"},{"prompt":"¿Cómo pagan?","input":"sentence"}],"text":"Elena cocina en un restaurante y Pablo sirve la comida. Una clienta pide una ensalada de entrada y una hamburguesa sin queso. Para beber, pide agua. Su amigo quiere una pizza y una copa de vino. Después de comer, los dos pagan con tarjeta. Elena prepara también sándwiches con pan, tomate y queso."}','{"items":[{"display":"Elena.","answers":["Elena."]},{"display":"Una ensalada.","answers":["Una ensalada."]},{"display":"Vino.","answers":["Vino."]},{"display":"Con tarjeta.","answers":["Con tarjeta."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U10-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-comidas-16','es1-comidas','open','writing','כותבים לחיים','כתבו מתכון פשוט לכריך, עם ארבעה מרכיבים ושלוש פעולות הכנה. הוסיפו משקה והשתמשו בשתי צורות שייכות שונות.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Mi sándwich tiene pan, queso, tomate y lechuga. Primero corto el pan y el tomate. Después pongo el queso sobre el pan. Agrego el tomate y la lechuga. Nuestro almuerzo está listo y bebemos agua. Mi hermano prefiere su sándwich sin queso."],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U10-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-moda-y-compras','es-1','es-1-leisure','אופנה וקניות','Moda y compras','לתאר בגדים ולהשתמש במספרים ובמחירים.','workbook','[{"he":"תארים","target":"concordancia"},{"he":"מספרים ומחירים","target":"¿Cuánto cuesta?"}]','["תארים","מחירים"]','{"rules":["התואר מתאים למין ולמספר של הבגד: la falda cómoda · los zapatos cómodos.","למחיר של פריט אחד שואלים ¿Cuánto cuesta?, ולפריטים ברבים ¿Cuánto cuestan?. הפועל מתאים למספר הפריטים ולא לגודל המחיר.","המספרים 16 עד 29 נכתבים במילה אחת; מ־31 מוסיפים y בין העשרות ליחידות."],"examples":["La falda es cómoda. Los zapatos son cómodos.","¿Cuánto cuesta el abrigo? Cuesta cincuenta euros.","dieciséis · veintidós · treinta y cinco"],"tips":["מ־16 עד 29 המספר הוא מילה אחת: dieciséis · veintidós. מ־31 חוזרת ה־y: treinta y cinco."],"mistakes":[{"text":"בעברית המחיר הוא שם עצם יחיד (\"מחיר\") ולכן מפתה לומר cuesta על כל פריט. הפועל מתאים למה שנקנה, לא לסכום: פריט אחד cuesta, כמה פריטים cuestan.","pairs":[{"bad":"¿Cuánto cuestan el vestido?","good":"¿Cuánto cuesta el vestido?"},{"bad":"La camiseta es cómodo","good":"La camiseta es cómoda"}]}]}','[{"term":"abrigo","he":"מעיל"},{"term":"accesorios","he":"אביזרים"},{"term":"ajustado/a","he":"צמוד"},{"term":"año","he":"שנה"},{"term":"área de espera","he":"אזור המתנה"},{"term":"asesor de moda","he":"יועץ אופנה"},{"term":"auriculares","he":"אוזניות"},{"term":"bolso","he":"תיק"},{"term":"botella","he":"בקבוק"},{"term":"cajero","he":"קופאי"},{"term":"calcetines","he":"גרביים"},{"term":"cálido/a","he":"חמים"},{"term":"camisa","he":"חולצה מכופתרת"},{"term":"camiseta","he":"חולצה קצרה"},{"term":"carrito","he":"עגלת קניות"},{"term":"casual","he":"יומיומי"},{"term":"catorce","he":"ארבע עשרה"},{"term":"centro comercial","he":"קניון"},{"term":"chaqueta","he":"ז׳קט"},{"term":"cien","he":"מאה"},{"term":"cinco","he":"חמש"},{"term":"cincuenta","he":"חמישים"},{"term":"colorido/a","he":"צבעוני"},{"term":"cómodo","he":"נוח"},{"term":"cómodo/a","he":"נוח / נוֹחַ / נוֹחָה"},{"term":"comprar","he":"לקנות"},{"term":"compras en línea","he":"קניות באינטרנט"},{"term":"con estilo","he":"בעל סגנון"},{"term":"costar","he":"לעלות במחיר"},{"term":"cuarenta","he":"ארבעים"},{"term":"cuatro","he":"ארבע"},{"term":"cumpleaños","he":"יום הולדת"},{"term":"descuento","he":"הנחה"},{"term":"diecinueve","he":"תשע עשרה"},{"term":"dieciocho","he":"שמונה עשרה"},{"term":"dieciséis","he":"שש עשרה"},{"term":"diecisiete","he":"שבע עשרה"},{"term":"diez","he":"עשר"},{"term":"doce","he":"שתים עשרה"},{"term":"dólar","he":"דולר"},{"term":"dos","he":"שתיים"},{"term":"elegante","he":"אלגנטי"},{"term":"entrar","he":"להיכנס"},{"term":"euro","he":"אירו"},{"term":"falda","he":"חצאית"},{"term":"fin de semana","he":"סוף שבוע"},{"term":"fino/a","he":"דק"},{"term":"formal","he":"רשמי"},{"term":"fresco/a","he":"קריר"},{"term":"gastar","he":"להוציא כסף / להוציא"},{"term":"grapadora","he":"שדכן"},{"term":"grueso/a","he":"עבה"},{"term":"gustar","he":"למצוא חן, למשל me gusta = אני אוהב"},{"term":"hombre","he":"גבר"},{"term":"ir","he":"ללכת / ללכת / לנסוע"},{"term":"ir de compras","he":"לקנות / ללכת לקניות"},{"term":"lápiz","he":"עיפרון"},{"term":"mes","he":"חודש"},{"term":"moderno/a","he":"מודרני"},{"term":"mujer","he":"אישה"},{"term":"noventa","he":"תשעים"},{"term":"nueve","he":"תשע"},{"term":"ochenta","he":"שמונים"},{"term":"ocho","he":"שמונה"},{"term":"once","he":"אחת עשרה"},{"term":"pagar","he":"לשלם"},{"term":"pantalón","he":"מכנסיים"},{"term":"pantalones cortos","he":"מכנסיים קצרים"},{"term":"par","he":"זוג"},{"term":"plátano","he":"בננה"},{"term":"playa","he":"חוף / חוף ים / חוֹף"},{"term":"precio","he":"מחיר"},{"term":"presupuesto","he":"תקציב"},{"term":"probador","he":"חדר הלבשה"},{"term":"probarse","he":"למדוד בגד"},{"term":"quedar","he":"להישאר"},{"term":"quince","he":"חמש עשרה"},{"term":"ratón","he":"עכבר מחשב"},{"term":"resaltador","he":"מרקר"},{"term":"reunión","he":"פגישה"},{"term":"rojo","he":"אדום"},{"term":"ropa","he":"בגדים"},{"term":"sección","he":"מחלקה"},{"term":"seis","he":"שש"},{"term":"semana","he":"שבוע"},{"term":"sencillo/a","he":"פשוט"},{"term":"sesenta","he":"שישים"},{"term":"setenta","he":"שבעים"},{"term":"siete","he":"שבע"},{"term":"suave","he":"רך / עדין / רך"},{"term":"suelto/a","he":"רפוי"},{"term":"talla","he":"מידה"},{"term":"teclado","he":"מקלדת"},{"term":"tener","he":"יש ל־ / להיות בעל"},{"term":"tienda","he":"חנות"},{"term":"total","he":"סך הכול"},{"term":"trabajo","he":"עבודה"},{"term":"trece","he":"שלוש עשרה"},{"term":"treinta","he":"שלושים"},{"term":"treinta y uno","he":"שלושים ואחת"},{"term":"tres","he":"שלוש"},{"term":"uno","he":"אחד / אחת"},{"term":"usar","he":"להשתמש / ללבוש / להשתמש"},{"term":"variedad","he":"מגוון"},{"term":"veinte","he":"עשרים"},{"term":"veinticinco","he":"עשרים וחמש"},{"term":"veinticuatro","he":"עשרים וארבע"},{"term":"veintidós","he":"עשרים ושתיים"},{"term":"veintinueve","he":"עשרים ותשע"},{"term":"veintiocho","he":"עשרים ושמונה"},{"term":"veintiséis","he":"עשרים ושש"},{"term":"veintisiete","he":"עשרים ושבע"},{"term":"veintitrés","he":"עשרים ושלוש"},{"term":"veintiuno","he":"עשרים ואחת"},{"term":"vendedor","he":"מוכר"},{"term":"vender","he":"למכור"},{"term":"vestido","he":"שמלה"},{"term":"vestir / ponerse","he":"ללבוש"},{"term":"zapatos","he":"נעליים"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1065967286/compras-y-moda-actualizado-flash-cards/"}]','published','workbook L1 unit 11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-moda-y-compras-01','es1-moda-y-compras','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"חולצה קצרה ___","input":"text"},{"prompt":"שמלה ___","input":"text"},{"prompt":"חצאית ___","input":"text"},{"prompt":"נעליים ___","input":"text"}]}','{"items":[{"display":"camiseta","answers":["camiseta"]},{"display":"vestido","answers":["vestido"]},{"display":"falda","answers":["falda"]},{"display":"zapatos","answers":["zapatos"]}],"policy":{"accents":"lenient"}}','published','L1-U11-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-moda-y-compras-02','es1-moda-y-compras','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"La camiseta es ___.","input":"choice","options":["cómodo","cómoda"]},{"prompt":"Los zapatos ___ elegantes.","input":"choice","options":["es","son"]},{"prompt":"¿Cuánto ___ el vestido?","input":"choice","options":["cuesta","cuestan"]},{"prompt":"Los zapatos ___ treinta euros.","input":"choice","options":["cuesta","cuestan"]},{"prompt":"22 → כתבו במילים","input":"text"},{"prompt":"57 → כתבו במילים","input":"text"},{"prompt":"El abrigo ___ cincuenta euros.","input":"choice","options":["cuesta","cuestan"]},{"prompt":"Las faldas son ___.","input":"choice","options":["elegante","elegantes"]}]}','{"items":[{"display":"cómoda","choice":1},{"display":"son","choice":1},{"display":"cuesta","choice":0},{"display":"cuestan","choice":1},{"display":"veintidós","answers":["veintidós"]},{"display":"cincuenta y siete","answers":["cincuenta y siete"]},{"display":"cuesta","choice":0},{"display":"elegantes","choice":1}],"policy":{"accents":"strict"}}','published','L1-U11-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-moda-y-compras-03','es1-moda-y-compras','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"La camiseta es cómodo.","input":"sentence"},{"prompt":"¿Cuánto cuestan el vestido?","input":"sentence"},{"prompt":"Los zapatos es elegantes.","input":"sentence"},{"prompt":"La falda cuesta treinta cinco euros.","input":"sentence"}]}','{"items":[{"display":"La camiseta es cómoda.","answers":["La camiseta es cómoda."]},{"display":"¿Cuánto cuesta el vestido?","answers":["¿Cuánto cuesta el vestido?"]},{"display":"Los zapatos son elegantes.","answers":["Los zapatos son elegantes."]},{"display":"La falda cuesta treinta y cinco euros.","answers":["La falda cuesta treinta y cinco euros."]}],"policy":{"accents":"strict"}}','published','L1-U11-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-moda-y-compras-04','es1-moda-y-compras','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"El zapato es cómodo. → רבים","input":"sentence"},{"prompt":"La falda cuesta 35 euros. → המספר במילים","input":"sentence"},{"prompt":"El abrigo es elegante. → שלילה","input":"sentence"}]}','{"items":[{"display":"Los zapatos son cómodos.","answers":["Los zapatos son cómodos."]},{"display":"La falda cuesta treinta y cinco euros.","answers":["La falda cuesta treinta y cinco euros."]},{"display":"El abrigo no es elegante.","answers":["El abrigo no es elegante."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U11-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-moda-y-compras-05','es1-moda-y-compras','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"החצאית נוחה.","input":"sentence"},{"prompt":"כמה עולה המעיל?","input":"sentence"},{"prompt":"הנעליים עולות ארבעים אירו.","input":"sentence"},{"prompt":"אני קונה חולצה לבנה.","input":"sentence"}]}','{"items":[{"display":"La falda es cómoda.","answers":["La falda es cómoda."]},{"display":"¿Cuánto cuesta el abrigo?","answers":["¿Cuánto cuesta el abrigo?"]},{"display":"Los zapatos cuestan cuarenta euros.","answers":["Los zapatos cuestan cuarenta euros."]},{"display":"Compro una camiseta blanca.","answers":["Compro una camiseta blanca."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U11-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-moda-y-compras-06','es1-moda-y-compras','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿Cuánto cuestan los zapatos?","input":"sentence"},{"prompt":"¿Cuánto paga Sara en total?","input":"sentence"},{"prompt":"¿Cuánto dinero tiene después de comprar?","input":"sentence"}],"text":"En la tienda Sol, una camiseta cuesta quince euros y una falda cuesta veinticinco euros.\nLos zapatos cuestan cuarenta euros. La camiseta es blanca y la falda es azul.\nSara tiene cincuenta euros. Compra una camiseta y una falda. No compra los zapatos."}','{"items":[{"display":"Cuestan cuarenta euros.","answers":["Cuestan cuarenta euros."]},{"display":"Paga cuarenta euros.","answers":["Paga cuarenta euros."]},{"display":"Tiene diez euros.","answers":["Tiene diez euros."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U11-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-moda-y-compras-07','es1-moda-y-compras','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Qué ropa usas para trabajar o estudiar?\n¿Qué color te gusta?\n¿Cuánto quieres gastar en una camiseta?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U11-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-moda-y-compras-08','es1-moda-y-compras','open','writing','כתיבה','כתבו רשימת קניות של שלושה בגדים עם מחיר במילים ותיאור לכל בגד. הוסיפו שני משפטים: מה אתם קונים ומה אינכם קונים, ומדוע.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Una camiseta blanca cuesta quince euros. Una falda azul cuesta veinticinco euros. Un abrigo cómodo cuesta cincuenta euros. Compro la camiseta y la falda. No compro el abrigo porque mi presupuesto es de cuarenta euros."],"criteria":""}','published','L1-U11-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-moda-y-compras-09','es1-moda-y-compras','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"100 euros → המספר במילים","input":"text"},{"prompt":"Mis amigas son ___.","input":"choice","options":["simpático","simpáticas"]}]}','{"items":[{"display":"cien euros","answers":["cien euros"]},{"display":"simpáticas","choice":1}],"policy":{"accents":"strict"}}','published','L1-U11-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-moda-y-compras-10','es1-moda-y-compras','open','production','אתגר לבחירה','יש לכם 60 אירו בחנות שבטקסט. מצאו שתי אפשרויות קנייה שונות שנכנסות לתקציב וכתבו את העלות של כל אחת. אין חובה להוציא את כל הסכום.','self','{"prompt":"","brief":""}','{"models":["חולצה וחצאית 40, חולצה ונעליים 55, חצאית בלבד 25. חצאית ונעליים 65 וחורגות מהתקציב."],"criteria":""}','published','L1-U11-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-moda-y-compras-11','es1-moda-y-compras','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["cómodo/a","falda","bolso","elegante","colorido/a","diecisiete","cincuenta","vestir / ponerse"],"right":[{"id":"A","text":"חצאית"},{"id":"B","text":"תיק"},{"id":"C","text":"חמישים"},{"id":"D","text":"אלגנטי"},{"id":"E","text":"ללבוש"},{"id":"F","text":"צבעוני"},{"id":"G","text":"נוח"},{"id":"H","text":"שבע עשרה"}]}','{"pairs":["G","A","B","D","F","H","C","E"],"policy":{"accents":"lenient"}}','published','L1-U11-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-moda-y-compras-12','es1-moda-y-compras','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"La camiseta es agradable al tacto: es ___.","input":"bank"},{"prompt":"El pantalón no está ajustado: es ___.","input":"bank"},{"prompt":"Para probarme la ropa entro en el ___.","input":"bank"},{"prompt":"Con un ___ pago menos.","input":"bank"},{"prompt":"Veinte más cuarenta son ___.","input":"bank"},{"prompt":"Compro la ropa en una ___ del centro comercial.","input":"bank"}],"wordbank":["suelto","tienda","suave","probador","descuento","sesenta"]}','{"items":[{"display":"suave","answers":["suave"]},{"display":"suelto","answers":["suelto"]},{"display":"probador","answers":["probador"]},{"display":"descuento","answers":["descuento"]},{"display":"sesenta","answers":["sesenta"]},{"display":"tienda","answers":["tienda"]}],"policy":{"accents":"strict"}}','published','L1-U11-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-moda-y-compras-13','es1-moda-y-compras','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"La camisa es cómoda.","cue":"רבים","input":"sentence"},{"prompt":"El abrigo es grueso.","cue":"רבים","input":"sentence"},{"prompt":"Yo gasto veinte euros.","cue":"ella","input":"sentence"},{"prompt":"Nosotros compramos ropa.","cue":"yo","input":"sentence"}]}','{"items":[{"display":"Las camisas son cómodas.","answers":["Las camisas son cómodas."]},{"display":"Los abrigos son gruesos.","answers":["Los abrigos son gruesos."]},{"display":"Ella gasta veinte euros.","answers":["Ella gasta veinte euros."]},{"display":"Yo compro ropa.","answers":["Yo compro ropa."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U11-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-moda-y-compras-14','es1-moda-y-compras','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"Veinte euros. Es suave y cómoda."},{"id":"B","text":"Gracias. Después quiero ver los pantalones."},{"id":"C","text":"¿Cuánto cuesta esta camiseta?"},{"id":"D","text":"¿Puedo probármela?"},{"id":"E","text":"Claro, el probador está a la derecha."}]}','{"order":["C","A","D","E","B"],"policy":{"accents":"strict"}}','published','L1-U11-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-moda-y-compras-15','es1-moda-y-compras','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Cuál es el presupuesto de Inés?","input":"sentence"},{"prompt":"¿Cuánto cuesta el bolso?","input":"sentence"},{"prompt":"¿Cuánto dinero le queda?","input":"sentence"},{"prompt":"¿Cómo es el pantalón?","input":"sentence"}],"text":"Inés tiene un presupuesto de cien euros. En una tienda compra una camiseta de veinte euros, un pantalón de cuarenta euros y un bolso de treinta euros. Gasta noventa euros en total y le quedan diez. La camiseta es suave y el pantalón es suelto. Antes de pagar, Inés se prueba la ropa en el probador."}','{"items":[{"display":"Cien euros.","answers":["Cien euros."]},{"display":"Treinta euros.","answers":["Treinta euros."]},{"display":"Diez euros.","answers":["Diez euros."]},{"display":"Es suelto.","answers":["Es suelto."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U11-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-moda-y-compras-16','es1-moda-y-compras','open','writing','כותבים לחיים','תכננו קנייה של שלושה פריטים בתקציב של מאה אירו. ציינו את המחיר של כל פריט במילים, שני תיאורים והסכום שנותר. ודאו שהחשבון מתאים.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Tengo un presupuesto de cien euros para comprar ropa. Compro una camiseta suave de veinte euros. También compro un pantalón suelto de cuarenta euros. El bolso cuesta treinta euros. Gasto noventa euros en total. Después de pagar en la tienda, me quedan diez euros."],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U11-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-tv-y-peliculas','es-1','es-1-leisure','סרטים וסדרות','TV y películas','לנסח שאלות ולהשתמש במילות יחס לתיאור צפייה וסצנה.','workbook','[{"he":"מילות שאלה","target":"¿Quién? ¿Por qué?"},{"he":"מילות יחס","target":"en · a · con"}]','["שאלות","מילות יחס"]','{"rules":["¿Quién? על אדם, ¿Dónde? על מקום, ¿Cuándo? על זמן ו־¿Por qué? על סיבה.","en למקום, לשנה ולחודש; a לשעה; con לאדם שצופים איתו.","כל שאלה נפתחת ב־¿ ונסגרת ב־?. זה לא קישוט, זה חלק מהכתיב."],"examples":["¿Dónde pasa la película? En Madrid.","Veo la serie a las ocho con mi hermana.","¿Por qué te gusta? Porque es divertida."],"tips":["en נכתב עם en לפני שם המקום, אבל a ליעד: Estoy en el cine לעומת Voy al cine."],"mistakes":[{"text":"בעברית ובאנגלית אין סימן שאלה פותח, ולכן הוא נשכח כמעט תמיד. ושימו לב לזוג por qué (שאלה, שתי מילים עם הטעמה) מול porque (תשובה, מילה אחת).","pairs":[{"bad":"Cómo se llama tu serie?","good":"¿Cómo se llama tu serie?"},{"bad":"por que es divertida","good":"porque es divertida"}]}]}','[{"term":"a","he":"אל / ל..."},{"term":"acción","he":"פעולה"},{"term":"actor","he":"שַׂחְקָן"},{"term":"actriz","he":"שַׂחְקָנִית"},{"term":"animación","he":"אנימציה"},{"term":"año","he":"שנה"},{"term":"autobús","he":"אוטובוס"},{"term":"bonito/a","he":"יפה"},{"term":"campo","he":"אזור כפרי"},{"term":"cantante","he":"זמר"},{"term":"casa","he":"בית פיזי / בית / בַּיִת"},{"term":"cine","he":"קולנוע"},{"term":"ciudad","he":"עיר"},{"term":"comedia","he":"קומדיה"},{"term":"comedia romántica","he":"קומדיה רומנטית"},{"term":"cómo","he":"איך"},{"term":"con","he":"עם"},{"term":"correr","he":"לרוץ"},{"term":"cuál","he":"איזה"},{"term":"cuándo","he":"מתי"},{"term":"debajo de","he":"מתחת ל־ / מתחת"},{"term":"detrás de","he":"מאחורי"},{"term":"director","he":"במאי"},{"term":"divertido/a","he":"מצחיק / מהנה"},{"term":"dónde","he":"איפה"},{"term":"drama","he":"דרמה"},{"term":"durar","he":"להימשך"},{"term":"emocionante","he":"מרגש"},{"term":"en","he":"ב־ / ב..."},{"term":"enero","he":"ינואר"},{"term":"episodio","he":"פרק"},{"term":"escena","he":"סצנה"},{"term":"esconderse","he":"להתחבא"},{"term":"escuela","he":"בית ספר"},{"term":"estar","he":"להיות במצב או במקום / להיות"},{"term":"estudiar","he":"ללמוד"},{"term":"favorito","he":"מועדף / אהוב"},{"term":"género","he":"סוגה"},{"term":"gustar","he":"למצוא חן, למשל me gusta = אני אוהב"},{"term":"hermana","he":"אחות"},{"term":"hombre","he":"גבר"},{"term":"hora","he":"שעה"},{"term":"interesante","he":"מעניין"},{"term":"invierno","he":"חורף"},{"term":"ir","he":"ללכת / ללכת / לנסוע"},{"term":"julio","he":"יולי"},{"term":"mañana","he":"בוקר / מחר"},{"term":"mar","he":"ים"},{"term":"mes","he":"חודש"},{"term":"mesa","he":"שולחן"},{"term":"mirar","he":"להסתכל / לצפות / לצפות / להסתכל"},{"term":"niña","he":"ילדה"},{"term":"noche","he":"לילה"},{"term":"padre","he":"אבא"},{"term":"país","he":"מדינה / ארץ / מדינה"},{"term":"pantalla","he":"מסך"},{"term":"parque","he":"פארק / פָּארְק"},{"term":"película","he":"סרט / סֶרֶט"},{"term":"personaje","he":"דמות"},{"term":"pez","he":"דג"},{"term":"playa","he":"חוף / חוף ים / חוֹף"},{"term":"por qué","he":"למה"},{"term":"preferir","he":"להעדיף"},{"term":"primero","he":"ראשית / ראשון"},{"term":"principal","he":"ראשי"},{"term":"profesor","he":"מורה"},{"term":"programa","he":"תוכנית"},{"term":"qué","he":"מה"},{"term":"quién","he":"מי"},{"term":"sala","he":"חדר / אולם"},{"term":"serie","he":"סדרה"},{"term":"serie (de televisión)","he":"סדרת טלוויזיה"},{"term":"silla","he":"כיסא / כִּסֵּא"},{"term":"sobre","he":"על"},{"term":"sofá","he":"ספה"},{"term":"tarde","he":"מאוחר / ערב / אחר הצהריים"},{"term":"tele","he":"טלוויזיה בשפה מדוברת"},{"term":"televisión","he":"טלוויזיה"},{"term":"terror","he":"אימה"},{"term":"trabajar","he":"לעבוד"},{"term":"triste","he":"עצוב"},{"term":"ver","he":"לראות"},{"term":"verano","he":"קיץ"},{"term":"vivir","he":"לגור / לחיות"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/854815389/basic-spanish-moviestv-flash-cards/?funnelUUID=8ae77ce5-43dd-4865-8dbe-a27e8f4ccd79"}]','published','workbook L1 unit 12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-tv-y-peliculas-01','es1-tv-y-peliculas','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"סרט ___","input":"text"},{"prompt":"סדרה ___","input":"text"},{"prompt":"פרק ___","input":"text"},{"prompt":"שחקן ___","input":"text"}]}','{"items":[{"display":"película","answers":["película"]},{"display":"serie","answers":["serie"]},{"display":"episodio","answers":["episodio"]},{"display":"actor","answers":["actor"]}],"policy":{"accents":"lenient"}}','published','L1-U12-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-tv-y-peliculas-02','es1-tv-y-peliculas','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"¿___ es tu actor favorito?","input":"choice","options":["Quién","Dónde"]},{"prompt":"¿___ ves la serie? En casa.","input":"choice","options":["Dónde","Quién"]},{"prompt":"Veo películas ___ mis amigos.","input":"choice","options":["con","de"]},{"prompt":"La historia pasa ___ julio.","input":"choice","options":["en","a"]},{"prompt":"La película empieza ___ las nueve.","input":"choice","options":["a","en"]},{"prompt":"¿___ te gusta? Porque es divertida.","input":"choice","options":["Por qué","Qué"]},{"prompt":"¿___ ves la serie? Los martes.","input":"choice","options":["Cuándo","Dónde"]},{"prompt":"La historia pasa ___ una ciudad pequeña.","input":"choice","options":["en","a"]}]}','{"items":[{"display":"Quién","choice":0},{"display":"Dónde","choice":0},{"display":"con","choice":0},{"display":"en","choice":0},{"display":"a","choice":0},{"display":"Por qué","choice":0},{"display":"Cuándo","choice":0},{"display":"en","choice":0}],"policy":{"accents":"strict"}}','published','L1-U12-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-tv-y-peliculas-03','es1-tv-y-peliculas','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"Veo la serie en las ocho.","input":"sentence"},{"prompt":"Cómo se llama tu serie favorita?","input":"sentence"},{"prompt":"Veo películas de mis amigos.","input":"sentence"},{"prompt":"Me gusta esta serie por que es divertida.","input":"sentence"}]}','{"items":[{"display":"Veo la serie a las ocho.","answers":["Veo la serie a las ocho."]},{"display":"¿Cómo se llama tu serie favorita?","answers":["¿Cómo se llama tu serie favorita?"]},{"display":"Veo películas con mis amigos.","answers":["Veo películas con mis amigos."]},{"display":"Me gusta esta serie porque es divertida.","answers":["Me gusta esta serie porque es divertida."]}],"policy":{"accents":"strict"}}','published','L1-U12-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-tv-y-peliculas-04','es1-tv-y-peliculas','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"Veo la serie en casa. → שאלה עם Dónde","input":"sentence"},{"prompt":"Veo películas con Ana. → שאלה עם Con quién","input":"sentence"},{"prompt":"Me gusta porque es interesante. → שאלה עם Por qué","input":"sentence"}]}','{"items":[{"display":"¿Dónde ves la serie?","answers":["¿Dónde ves la serie?"]},{"display":"¿Con quién ves películas?","answers":["¿Con quién ves películas?"]},{"display":"¿Por qué te gusta?","answers":["¿Por qué te gusta?"]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U12-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-tv-y-peliculas-05','es1-tv-y-peliculas','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"איפה אתה רואה סרטים?","input":"sentence"},{"prompt":"אני רואה את הסדרה בשמונה.","input":"sentence"},{"prompt":"אני רואה סרטים עם אחי.","input":"sentence"},{"prompt":"למה הסדרה מוצאת חן בעיניך?","input":"sentence"}]}','{"items":[{"display":"¿Dónde ves películas?","answers":["¿Dónde ves películas?"]},{"display":"Veo la serie a las ocho.","answers":["Veo la serie a las ocho."]},{"display":"Veo películas con mi hermano.","answers":["Veo películas con mi hermano."]},{"display":"¿Por qué te gusta la serie?","answers":["¿Por qué te gusta la serie?"]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U12-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-tv-y-peliculas-06','es1-tv-y-peliculas','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿Dónde pasa la historia?","input":"sentence"},{"prompt":"¿Quién es el personaje principal?","input":"sentence"},{"prompt":"¿Cuándo ve la serie?","input":"sentence"}],"text":"Mi serie favorita se llama La casa azul. Es una serie imaginaria.\nLa historia pasa en una ciudad pequeña. El personaje principal es una maestra.\nVive cerca de una escuela y trabaja allí.\nVeo un episodio los martes a las ocho con mi hermano. Me gusta porque es divertida."}','{"items":[{"display":"Pasa en una ciudad pequeña.","answers":["Pasa en una ciudad pequeña."]},{"display":"Es una maestra.","answers":["Es una maestra."]},{"display":"Los martes a las ocho.","answers":["Los martes a las ocho."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U12-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-tv-y-peliculas-07','es1-tv-y-peliculas','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Cuál es tu película o serie favorita?\n¿Con quién ves películas o series?\n¿Por qué te gusta?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U12-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-tv-y-peliculas-08','es1-tv-y-peliculas','open','writing','כתיבה','כתבו המלצה קצרה של 5 משפטים על סרט או סדרה אמיתיים או דמיוניים. כללו מקום, דמות וסיבה להמלצה. הוסיפו שתי שאלות לקורא.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Mi serie favorita es La casa azul. La historia pasa en una ciudad pequeña. El personaje principal es una maestra. Veo la serie con mi hermana. Me gusta porque es divertida. ¿Qué series te gustan? ¿Dónde ves películas?"],"criteria":""}','published','L1-U12-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-tv-y-peliculas-09','es1-tv-y-peliculas','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"La clase es ___ las seis.","input":"choice","options":["a","en"]},{"prompt":"La mesa ___ en la sala de estar.","input":"choice","options":["es","está"]}]}','{"items":[{"display":"a","choice":0},{"display":"está","choice":1}],"policy":{"accents":"strict"}}','published','L1-U12-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-tv-y-peliculas-10','es1-tv-y-peliculas','open','speaking','אתגר לבחירה','המציאו סצנה וכתבו שלושה רמזים על מיקום הדמויות והחפצים. בקשו מאדם אחר לצייר או לתאר אותה.','self','{"prompt":"","brief":"","note":"משימה פתוחה לבחירה: אין מפתח. אפשר להביא את הניסוח לשיעור."}','{"models":[],"criteria":""}','published','L1-U12-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-tv-y-peliculas-11','es1-tv-y-peliculas','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["noche","interesante","bonito/a","preferir","serie (de televisión)","triste","pantalla","verano"],"right":[{"id":"A","text":"יפה"},{"id":"B","text":"מסך"},{"id":"C","text":"להעדיף"},{"id":"D","text":"מעניין"},{"id":"E","text":"לילה"},{"id":"F","text":"סדרת טלוויזיה"},{"id":"G","text":"קיץ"},{"id":"H","text":"עצוב"}]}','{"pairs":["E","D","A","C","F","H","B","G"],"policy":{"accents":"lenient"}}','published','L1-U12-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-tv-y-peliculas-12','es1-tv-y-peliculas','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"Veo una ___ de diez episodios.","input":"bank"},{"prompt":"Mi ___ favorito trabaja en muchas películas.","input":"bank"},{"prompt":"La historia tiene un ___ que es profesor.","input":"bank"},{"prompt":"Una ___ me hace reír.","input":"bank"},{"prompt":"La película es ___ una familia de Madrid.","input":"bank"},{"prompt":"Veo la televisión ___ mi hermana.","input":"bank"}],"wordbank":["actor","comedia","serie","sobre","con","personaje"]}','{"items":[{"display":"serie","answers":["serie"]},{"display":"actor","answers":["actor"]},{"display":"personaje","answers":["personaje"]},{"display":"comedia","answers":["comedia"]},{"display":"sobre","answers":["sobre"]},{"display":"con","answers":["con"]}],"policy":{"accents":"strict"}}','published','L1-U12-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-tv-y-peliculas-13','es1-tv-y-peliculas','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"La película es interesante.","cue":"רבים","input":"sentence"},{"prompt":"Veo una serie por la noche.","cue":"él","input":"sentence"},{"prompt":"Mi hermana prefiere comedias.","cue":"רבים","input":"sentence"},{"prompt":"El personaje vive en Madrid.","cue":"רבים","input":"sentence"}]}','{"items":[{"display":"Las películas son interesantes.","answers":["Las películas son interesantes."]},{"display":"Él ve una serie por la noche.","answers":["Él ve una serie por la noche."]},{"display":"Mis hermanas prefieren comedias.","answers":["Mis hermanas prefieren comedias."]},{"display":"Los personajes viven en Madrid.","answers":["Los personajes viven en Madrid."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U12-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-tv-y-peliculas-14','es1-tv-y-peliculas','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"¿Por qué te gusta?"},{"id":"B","text":"Sí, esta noche en tu casa."},{"id":"C","text":"¿Qué serie recomiendas?"},{"id":"D","text":"Una comedia sobre una familia que vive cerca del mar."},{"id":"E","text":"Porque los personajes son divertidos. ¿Quieres verla conmigo?"}]}','{"order":["C","D","A","E","B"],"policy":{"accents":"strict"}}','published','L1-U12-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-tv-y-peliculas-15','es1-tv-y-peliculas','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Cuándo ve Leo la serie?","input":"sentence"},{"prompt":"¿A qué se dedica el personaje principal?","input":"sentence"},{"prompt":"¿Dónde hay escenas? Escribe dos lugares.","input":"sentence"},{"prompt":"¿Qué prefiere la hermana de Leo?","input":"sentence"}],"text":"Leo ve una serie por la noche con su hermana. El personaje principal es un profesor que vive cerca del mar. En el primer episodio visita una escuela nueva. Hay escenas en una casa y en un parque. A Leo le gusta la serie porque es divertida. Su hermana prefiere las películas de acción."}','{"items":[{"display":"Por la noche.","answers":["Por la noche."]},{"display":"Es profesor.","answers":["Es profesor."]},{"display":"En una casa y en un parque.","answers":["En una casa y en un parque."]},{"display":"Las películas de acción.","answers":["Las películas de acción."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U12-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-tv-y-peliculas-16','es1-tv-y-peliculas','open','writing','כותבים לחיים','המליצו על סרט או סדרה. ציינו סוגה, דמות, מקום, מתי ועם מי אתם צופים ושתי סיבות להמלצה. שלבו en, con ו־sobre.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Recomiendo una comedia sobre una familia que vive en Madrid. El personaje principal es una profesora. Hay escenas en una escuela y en un parque. Veo la serie por la noche con mi hermana. Me gusta porque los personajes son divertidos. También me gusta porque la historia es interesante."],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U12-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-diversion-y-juegos','es-1','es-1-leisure','פנאי ומשחקים','Diversión y juegos','לתאר פעילויות פנאי ולהשתמש בכינויי שייכות.','workbook','[{"he":"jugar","target":"פעלים בהווה"},{"he":"שייכות","target":"mi · nuestro"}]','["jugar","שייכות"]','{"rules":["ב־jugar יש שינוי בגזע ברוב הגופים, אבל לא ב־nosotros.","כינויי השייכות מתאימים לשם העצם שאחריהם: mi juego · mis juegos · nuestra actividad.","במשפט שלילי no מופיע לפני הפועל."],"examples":["Yo juego. Tú juegas. Ella juega. Nosotros jugamos. Ellos juegan.","Mi juego · mis juegos · nuestra actividad","No juego al fútbol."],"tips":["עם משחקי ספורט אומרים jugar a: jugar al fútbol. עם משחקי קופסה זה אפשרי גם בלי: jugamos dominó."],"mistakes":[{"text":"אחרי שלומדים juego מפתה להכליל את השינוי לכל הגופים. דווקא ב־nosotros הגזע חוזר ל־jugamos. ובכינוי השייכות, ההתאמה היא לשם העצם ולא לכמות הבעלים.","pairs":[{"bad":"Nosotros juegamos","good":"Nosotros jugamos"},{"bad":"Mi juegos","good":"Mis juegos"}]}]}','[{"term":"a veces","he":"לפעמים"},{"term":"actividad","he":"פעילות"},{"term":"almuerzo","he":"ארוחת צהריים"},{"term":"amiga","he":"חברה"},{"term":"amigo","he":"חבר"},{"term":"amigos","he":"חברים"},{"term":"aplaudir","he":"למחוא כפיים"},{"term":"bailar","he":"לרקוד"},{"term":"beber","he":"לשתות / לִשְׁתּוֹת"},{"term":"bolsa","he":"תיק / שקית"},{"term":"cabello","he":"שיער"},{"term":"caminar","he":"ללכת / לָלֶכֶת"},{"term":"cantar","he":"לשיר"},{"term":"casa","he":"בית פיזי / בית / בַּיִת"},{"term":"castaño","he":"חום ערמוני"},{"term":"cerrar","he":"לסגור"},{"term":"coche","he":"מכונית"},{"term":"cocinar","he":"לבשל"},{"term":"comer","he":"לאכול / לֶאֱכוֹל"},{"term":"computadora","he":"מחשב"},{"term":"correr","he":"לרוץ"},{"term":"corto","he":"קצר"},{"term":"decir","he":"לומר"},{"term":"deporte","he":"ספורט"},{"term":"dormir","he":"לישון / לִישׁוֹן"},{"term":"escuchar","he":"להקשיב / להאזין"},{"term":"estudiar","he":"ללמוד"},{"term":"familia","he":"משפחה"},{"term":"gato","he":"חתול"},{"term":"golpear","he":"להכות"},{"term":"hablar","he":"לדבר"},{"term":"hacer ejercicio","he":"להתאמן / לעשות פעילות גופנית"},{"term":"hermana","he":"אחות"},{"term":"hermano","he":"אח"},{"term":"juego","he":"משחק / מִשְׂחָק"},{"term":"juego de mesa","he":"משחק קופסה"},{"term":"jugar","he":"לשחק"},{"term":"largo","he":"ארוך"},{"term":"leer","he":"לקרוא"},{"term":"levantar","he":"להרים"},{"term":"limpiar","he":"לנקות"},{"term":"llover","he":"לרדת גשם"},{"term":"lluvioso","he":"גשום"},{"term":"los fines de semana","he":"בסופי השבוע"},{"term":"madre","he":"אם / אמא"},{"term":"mano derecha","he":"יד ימין"},{"term":"mascota","he":"חיית מחמד"},{"term":"mi","he":"שלי"},{"term":"mío","he":"שלי ככינוי עצמאי"},{"term":"mis","he":"שלי לפני שם ברבים / שלי (רבים)"},{"term":"mojarse","he":"להירטב"},{"term":"mover","he":"להזיז"},{"term":"nariz","he":"אף"},{"term":"niños","he":"ילדים"},{"term":"normalmente","he":"בדרך כלל"},{"term":"nuestra","he":"שלנו לפני שם בנקבה / שלנו (נקבה)"},{"term":"nuestras","he":"שלנו לפני שם בנקבה רבות"},{"term":"nuestro","he":"שלנו לפני שם בזכר / שלנו"},{"term":"nuestros","he":"שלנו לפני שם בזכר רבים"},{"term":"nunca","he":"אף פעם לא"},{"term":"ojos","he":"עיניים"},{"term":"padre","he":"אבא"},{"term":"parque","he":"פארק / פָּארְק"},{"term":"perro","he":"כלב"},{"term":"pie","he":"כף רגל"},{"term":"pies","he":"כפות רגליים"},{"term":"pregunta","he":"שאלה"},{"term":"profesor","he":"מורה"},{"term":"quedarse","he":"להישאר"},{"term":"regla","he":"כלל"},{"term":"respuesta","he":"תשובה"},{"term":"ropa","he":"בגדים"},{"term":"siempre","he":"תמיד"},{"term":"sol","he":"שמש"},{"term":"su","he":"שלו / שלה / שלו / שלה / שלהם / שלו/שלה/שלהם"},{"term":"suelo","he":"רצפה / קרקע"},{"term":"sus","he":"שלו / שלה / שלהם לפני שם ברבים / שלהם/שלה"},{"term":"tarjeta","he":"כרטיס תשלום"},{"term":"teléfono","he":"טלפון"},{"term":"televisión","he":"טלוויזיה"},{"term":"tocar","he":"לגעת/לנגן / לנגן / לָגַעַת"},{"term":"todos los días","he":"בכל יום / כל יום"},{"term":"trabajar","he":"לעבוד"},{"term":"tu","he":"שלך"},{"term":"turno","he":"תור"},{"term":"tus","he":"שלך לפני שם ברבים / שלך (רבים)"},{"term":"tuyo","he":"שלך ככינוי עצמאי"},{"term":"ver","he":"לראות"},{"term":"zapatos","he":"נעליים"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1067940546/diversion-y-juegos-actualizado-flash-cards/?funnelUUID=9bda9e4c-a85a-4a9a-ae70-e97e14e61a84"}]','published','workbook L1 unit 13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-diversion-y-juegos-01','es1-diversion-y-juegos','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"משחק ___","input":"text"},{"prompt":"לשחק ___","input":"text"},{"prompt":"לרקוד ___","input":"text"},{"prompt":"לשיר ___","input":"text"}]}','{"items":[{"display":"juego","answers":["juego"]},{"display":"jugar","answers":["jugar"]},{"display":"bailar","answers":["bailar"]},{"display":"cantar","answers":["cantar"]}],"policy":{"accents":"lenient"}}','published','L1-U13-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-diversion-y-juegos-02','es1-diversion-y-juegos','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"Yo ___ con mis amigos.","input":"choice","options":["juego","juega"]},{"prompt":"Nosotros ___ en casa.","input":"choice","options":["juegan","jugamos"]},{"prompt":"Ana ___ los viernes.","hint":"bailar","input":"text"},{"prompt":"Ellos ___ juntos.","hint":"cantar","input":"text"},{"prompt":"___ juegos son divertidos.","cue":"שלי","input":"choice","options":["Mi","Mis"]},{"prompt":"Es ___ actividad favorita.","cue":"שלנו","input":"choice","options":["nuestro","nuestra"]},{"prompt":"Ellos ___ al fútbol los domingos.","input":"choice","options":["juego","juegan"]},{"prompt":"Son ___ actividades favoritas.","cue":"שלנו","input":"choice","options":["nuestros","nuestras"]}]}','{"items":[{"display":"juego","choice":0},{"display":"jugamos","choice":1},{"display":"baila","answers":["baila"]},{"display":"cantan","answers":["cantan"]},{"display":"Mis","choice":1},{"display":"nuestra","choice":1},{"display":"juegan","choice":1},{"display":"nuestras","choice":1}],"policy":{"accents":"strict"}}','published','L1-U13-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-diversion-y-juegos-03','es1-diversion-y-juegos','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"Nosotros juegamos en casa.","input":"sentence"},{"prompt":"Yo juega con mis amigos.","input":"sentence"},{"prompt":"Mi juegos son divertidos.","input":"sentence"},{"prompt":"Es nuestro actividad favorita.","input":"sentence"}]}','{"items":[{"display":"Nosotros jugamos en casa.","answers":["Nosotros jugamos en casa."]},{"display":"Yo juego con mis amigos.","answers":["Yo juego con mis amigos."]},{"display":"Mis juegos son divertidos.","answers":["Mis juegos son divertidos."]},{"display":"Es nuestra actividad favorita.","answers":["Es nuestra actividad favorita."]}],"policy":{"accents":"strict"}}','published','L1-U13-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-diversion-y-juegos-04','es1-diversion-y-juegos','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"Yo juego en casa. → Ella…","input":"sentence"},{"prompt":"nuestro juego favorito → רבים","input":"sentence"},{"prompt":"Ellos cantan. → שלילה","input":"sentence"}]}','{"items":[{"display":"Ella juega en casa.","answers":["Ella juega en casa."]},{"display":"nuestros juegos favoritos","answers":["nuestros juegos favoritos"]},{"display":"Ellos no cantan.","answers":["Ellos no cantan."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U13-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-diversion-y-juegos-05','es1-diversion-y-juegos','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"אני משחק עם החברים שלי.","input":"sentence"},{"prompt":"אנחנו משחקים בבית בימי שבת.","input":"sentence"},{"prompt":"המשחק האהוב עליי הוא דומינו.","input":"sentence"},{"prompt":"הם לא רוקדים.","input":"sentence"}]}','{"items":[{"display":"Juego con mis amigos.","answers":["Juego con mis amigos."]},{"display":"Jugamos en casa los sábados.","answers":["Jugamos en casa los sábados."]},{"display":"Mi juego favorito es el dominó.","answers":["Mi juego favorito es el dominó."]},{"display":"Ellos no bailan.","answers":["Ellos no bailan."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U13-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-diversion-y-juegos-06','es1-diversion-y-juegos','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿Dónde juegan los sábados?","input":"sentence"},{"prompt":"¿Qué lleva Ana?","input":"sentence"},{"prompt":"¿Qué hace Daniel cuando sus amigos bailan?","input":"sentence"}],"text":"Los sábados Daniel y sus amigos juegan en casa. Su juego favorito es el dominó.\nAna lleva su juego de cartas. Primero juegan al dominó y después cantan y bailan.\nDaniel no baila: escucha música. Los domingos todos juegan al fútbol en el parque."}','{"items":[{"display":"Juegan en casa.","answers":["Juegan en casa."]},{"display":"Lleva su juego de cartas.","answers":["Lleva su juego de cartas."]},{"display":"Escucha música.","answers":["Escucha música."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U13-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-diversion-y-juegos-07','es1-diversion-y-juegos','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Cuál es tu juego o actividad favorita?\n¿Con quién juegas?\n¿Qué haces para divertirte en casa?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U13-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-diversion-y-juegos-08','es1-diversion-y-juegos','open','writing','כתיבה','כתבו הזמנה לערב משחקים בחמישה משפטים: זמן, מקום, שני משחקים או פעילויות ומי מביא מה. השתמשו בפעלים בהווה ובכינויי שייכות.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["El viernes jugamos en mi casa a las ocho. Mi juego favorito es el dominó. Ana lleva sus cartas. También escuchamos música. Nuestra noche es divertida."],"criteria":""}','published','L1-U13-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-diversion-y-juegos-09','es1-diversion-y-juegos','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"Nosotros ___ agua.","hint":"beber","input":"text"},{"prompt":"___ hermanos viven aquí.","cue":"שלו","input":"choice","options":["Su","Sus"]}]}','{"items":[{"display":"bebemos","answers":["bebemos"]},{"display":"Sus","choice":1}],"policy":{"accents":"strict"}}','published','L1-U13-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-diversion-y-juegos-10','es1-diversion-y-juegos','open','speaking','אתגר לבחירה','כתבו חידה בת ארבעה רמזים על משחק או פעילות. אל תכתבו את השם בתוך הרמזים; הוסיפו אותו בנפרד לבדיקה.','self','{"prompt":"","brief":"","note":"משימה פתוחה לבחירה: אין מפתח. אפשר להביא את הניסוח לשיעור."}','{"models":[],"criteria":""}','published','L1-U13-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-diversion-y-juegos-11','es1-diversion-y-juegos','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["correr","perro","madre","mis","tu","deporte","tocar","televisión"],"right":[{"id":"A","text":"כלב"},{"id":"B","text":"שלך"},{"id":"C","text":"לגעת/לנגן"},{"id":"D","text":"שלי (רבים)"},{"id":"E","text":"טלוויזיה"},{"id":"F","text":"אמא"},{"id":"G","text":"לרוץ"},{"id":"H","text":"ספורט"}]}','{"pairs":["G","A","F","D","B","H","C","E"],"policy":{"accents":"lenient"}}','published','L1-U13-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-diversion-y-juegos-12','es1-diversion-y-juegos','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"Cuando tengo el turno para hablar, ___ la mano.","input":"bank"},{"prompt":"Cuando termina el concierto, nosotros ___.","input":"bank"},{"prompt":"Mi hermana y yo tenemos un perro: es ___ perro.","input":"bank"},{"prompt":"Yo tengo dos gatos: son ___ gatos.","input":"bank"},{"prompt":"Cuando ___, jugamos dentro de casa.","input":"bank"},{"prompt":"No hables ahora: espera tu ___.","input":"bank"}],"wordbank":["aplaudimos","nuestro","levanto","turno","mis","llueve"]}','{"items":[{"display":"levanto","answers":["levanto"]},{"display":"aplaudimos","answers":["aplaudimos"]},{"display":"nuestro","answers":["nuestro"]},{"display":"mis","answers":["mis"]},{"display":"llueve","answers":["llueve"]},{"display":"turno","answers":["turno"]}],"policy":{"accents":"strict"}}','published','L1-U13-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-diversion-y-juegos-13','es1-diversion-y-juegos','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"Mi juego es divertido.","cue":"רבים","input":"sentence"},{"prompt":"Nuestra amiga juega al fútbol.","cue":"רבים","input":"sentence"},{"prompt":"Yo levanto la mano.","cue":"nosotros","input":"sentence"},{"prompt":"Él cierra los ojos.","cue":"ellos","input":"sentence"}]}','{"items":[{"display":"Mis juegos son divertidos.","answers":["Mis juegos son divertidos."]},{"display":"Nuestras amigas juegan al fútbol.","answers":["Nuestras amigas juegan al fútbol."]},{"display":"Nosotros levantamos la mano.","answers":["Nosotros levantamos la mano."]},{"display":"Ellos cierran los ojos.","answers":["Ellos cierran los ojos."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U13-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-diversion-y-juegos-14','es1-diversion-y-juegos','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"Mi hermana empieza y después tú."},{"id":"B","text":"Perfecto. Espero mi turno."},{"id":"C","text":"Podemos jugar a un juego de mesa."},{"id":"D","text":"Llueve. ¿Qué hacemos en casa?"},{"id":"E","text":"Buena idea. ¿Quién juega primero?"}]}','{"order":["D","C","E","A","B"],"policy":{"accents":"strict"}}','published','L1-U13-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-diversion-y-juegos-15','es1-diversion-y-juegos','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Con quién juega Pablo?","input":"sentence"},{"prompt":"¿Qué hacen cuando llueve?","input":"sentence"},{"prompt":"¿Qué hacen antes de hablar?","input":"sentence"},{"prompt":"¿Usan la computadora durante el juego?","input":"sentence"}],"text":"Los domingos Pablo juega con su hermana y sus amigos. Cuando llueve, juegan a un juego de mesa en casa. Cuando hace sol, van al parque con su perro. En casa hay una regla: levantan la mano para hablar y escuchan a los demás. Al terminar el juego, aplauden. No usan la computadora durante el juego."}','{"items":[{"display":"Con su hermana y sus amigos.","answers":["Con su hermana y sus amigos."]},{"display":"Juegan a un juego de mesa en casa.","answers":["Juegan a un juego de mesa en casa."]},{"display":"Levantan la mano.","answers":["Levantan la mano."]},{"display":"No.","answers":["No."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U13-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-diversion-y-juegos-16','es1-diversion-y-juegos','open','writing','כותבים לחיים','הסבירו משחק שאתם אוהבים. ציינו משתתפים, חפצים ושלוש פעולות. כתבו היכן משחקים כשגשום ושלבו שלוש צורות שייכות.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Mi juego favorito es un juego de mesa. Juego con mi hermana y nuestros amigos en casa cuando llueve. Usamos nuestras tarjetas y una mesa grande. Primero mi hermana lee una tarjeta y nosotros escuchamos. Después levantamos la mano y decimos la respuesta. Esperamos nuestro turno y aplaudimos al final."],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U13-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-musica','es-1','es-1-leisure','מוזיקה','Música','לשאול על העדפות מוזיקליות ולתאר הרגלים בהווה.','workbook','[{"he":"מילות שאלה","target":"gustar"},{"he":"פעלים בהווה","target":"querer + infinitivo"}]','["שאלות","gustar"]','{"rules":["בונים שאלה לפי המידע שרוצים לקבל, ומתאימים את הפועל לגוף.","אחרי quiero · puedo · necesito בא שם פועל.","gusta מתאים לשם פועל או לדבר יחיד, gustan לדברים ברבים."],"examples":["¿Qué música escuchas? Escucho pop.","Ella canta. Nosotros cantamos.","Quiero cantar. Me gustan estas canciones."],"tips":["לנגן בכלי זה tocar, ולשחק זה jugar. אותה מילה בעברית, שני פעלים בספרדית: toco la guitarra · juego al fútbol."],"mistakes":[{"text":"בעברית \"היא רוצה לשיר\" ו\"היא שרה\" נשמעים קרוב, ובספרדית רק הפועל הראשון מוטה והשני נשאר שם פועל. ועם aprender צריך גם a לפני שם הפועל.","pairs":[{"bad":"quiere canta","good":"quiere cantar"},{"bad":"aprender tocar","good":"aprender a tocar"}]}]}','[{"term":"adivinar","he":"לנחש"},{"term":"alegre","he":"שמח"},{"term":"aplicación","he":"יישומון"},{"term":"aprender","he":"ללמוד"},{"term":"atardecer","he":"שקיעה"},{"term":"bailar","he":"לרקוד"},{"term":"banda","he":"להקה"},{"term":"batería","he":"מערכת תופים"},{"term":"beber","he":"לשתות / לִשְׁתּוֹת"},{"term":"canción","he":"שיר"},{"term":"cantante","he":"זמר"},{"term":"cantar","he":"לשיר"},{"term":"comer","he":"לאכול / לֶאֱכוֹל"},{"term":"compartir","he":"לשתף"},{"term":"concierto","he":"קונצרט / הופעה / הופעה"},{"term":"corazón","he":"לב"},{"term":"coro","he":"מקהלה"},{"term":"cuándo","he":"מתי"},{"term":"disfrutar","he":"ליהנות"},{"term":"dónde","he":"איפה"},{"term":"empezar","he":"להתחיל"},{"term":"encontrar","he":"למצוא"},{"term":"ensayar","he":"לעשות חזרה"},{"term":"ensayo","he":"חזרה"},{"term":"entender","he":"להבין"},{"term":"entrada","he":"מנה ראשונה / כרטיס כניסה"},{"term":"escuchar","he":"להקשיב / להאזין"},{"term":"estudiar","he":"ללמוד"},{"term":"estudio","he":"אולפן"},{"term":"familia","he":"משפחה"},{"term":"gozar","he":"ליהנות"},{"term":"grupo","he":"להקה / קבוצה"},{"term":"guitarra","he":"גיטרה"},{"term":"gustar","he":"למצוא חן, למשל me gusta = אני אוהב"},{"term":"hablar","he":"לדבר"},{"term":"hermano","he":"אח"},{"term":"hora","he":"שעה"},{"term":"instrumento","he":"כלי נגינה"},{"term":"le gusta","he":"הוא/היא אוהב/ת"},{"term":"lento","he":"איטי"},{"term":"letra","he":"מילות שיר"},{"term":"limpiar","he":"לנקות"},{"term":"llorar","he":"לבכות"},{"term":"lluvia","he":"גשם"},{"term":"mar","he":"ים"},{"term":"me gusta","he":"אני אוהב/ת"},{"term":"miércoles","he":"יום רביעי"},{"term":"montaña","he":"הר"},{"term":"música","he":"מוזיקה / מוּזִיקָה"},{"term":"olvidar","he":"לשכוח"},{"term":"ordenador","he":"מחשב"},{"term":"orquesta","he":"תזמורת"},{"term":"pensar","he":"לחשוב"},{"term":"piano","he":"פסנתר"},{"term":"podcast","he":"פודקאסט"},{"term":"poema","he":"שיר ספרותי"},{"term":"por qué","he":"למה"},{"term":"preferir","he":"להעדיף"},{"term":"pregunta","he":"שאלה"},{"term":"qué","he":"מה"},{"term":"quién","he":"מי"},{"term":"radio","he":"רדיו"},{"term":"rápido","he":"מהיר"},{"term":"reír","he":"לצחוק"},{"term":"ritmo","he":"קצב"},{"term":"rock","he":"רוק"},{"term":"sábado","he":"שבת"},{"term":"sufrir","he":"לסבול"},{"term":"te gusta","he":"את/ה אוהב/ת"},{"term":"teléfono","he":"טלפון"},{"term":"tocar","he":"לגעת/לנגן / לנגן / לָגַעַת"},{"term":"tranquilo","he":"רגוע / שקט / רגוע / שקט או רגוע"},{"term":"vencer","he":"לנצח"},{"term":"vender","he":"למכור"},{"term":"viajar","he":"לטייל / לנסוע"},{"term":"vivir","he":"לגור / לחיות"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/994813811/music-basic-spanish-flash-cards/"}]','published','workbook L1 unit 14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-musica-01','es1-musica','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"שיר ___","input":"text"},{"prompt":"קצב ___","input":"text"},{"prompt":"להאזין ___","input":"text"},{"prompt":"לשיר ___","input":"text"}]}','{"items":[{"display":"canción","answers":["canción"]},{"display":"ritmo","answers":["ritmo"]},{"display":"escuchar","answers":["escuchar"]},{"display":"cantar","answers":["cantar"]}],"policy":{"accents":"lenient"}}','published','L1-U14-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-musica-02','es1-musica','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"Yo ___ música todos los días.","hint":"escuchar","input":"text"},{"prompt":"Ella ___ en casa.","hint":"cantar","input":"text"},{"prompt":"Nosotros ___ juntos.","hint":"bailar","input":"text"},{"prompt":"Quiero ___ español.","input":"choice","options":["estudio","estudiar"]},{"prompt":"Me ___ las canciones.","input":"choice","options":["gusta","gustan"]},{"prompt":"¿___ escuchas música? En casa.","input":"choice","options":["Dónde","Quién"]},{"prompt":"Ella no ___ entender la canción.","input":"choice","options":["puede","puedes"]},{"prompt":"¿___ escuchas música? Por la noche.","input":"choice","options":["Cuándo","Quién"]}]}','{"items":[{"display":"escucho","answers":["escucho"]},{"display":"canta","answers":["canta"]},{"display":"bailamos","answers":["bailamos"]},{"display":"estudiar","choice":1},{"display":"gustan","choice":1},{"display":"Dónde","choice":0},{"display":"puede","choice":0},{"display":"Cuándo","choice":0}],"policy":{"accents":"strict"}}','published','L1-U14-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-musica-03','es1-musica','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"Ella quiere canta en casa.","input":"sentence"},{"prompt":"Me gusta las canciones en español.","input":"sentence"},{"prompt":"Nosotros bailo juntos.","input":"sentence"},{"prompt":"Yo quiero aprender tocar la guitarra.","input":"sentence"}]}','{"items":[{"display":"Ella quiere cantar en casa.","answers":["Ella quiere cantar en casa."]},{"display":"Me gustan las canciones en español.","answers":["Me gustan las canciones en español."]},{"display":"Nosotros bailamos juntos.","answers":["Nosotros bailamos juntos."]},{"display":"Yo quiero aprender a tocar la guitarra.","answers":["Yo quiero aprender a tocar la guitarra."]}],"policy":{"accents":"strict"}}','published','L1-U14-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-musica-04','es1-musica','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"Escucho música por la noche. → שאלה עם Cuándo","input":"sentence"},{"prompt":"Yo canto en casa. → Nosotros…","input":"sentence"},{"prompt":"Ella quiere canta. → תקנו","input":"sentence"}]}','{"items":[{"display":"¿Cuándo escuchas música?","answers":["¿Cuándo escuchas música?"]},{"display":"Nosotros cantamos en casa.","answers":["Nosotros cantamos en casa."]},{"display":"Ella quiere cantar.","answers":["Ella quiere cantar."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U14-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-musica-05','es1-musica','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"אני מאזין למוזיקה כל יום.","input":"sentence"},{"prompt":"אני אוהב את השירים האלה.","input":"sentence"},{"prompt":"היא רוצה לשיר בספרדית.","input":"sentence"},{"prompt":"מתי אתה מאזין למוזיקה?","input":"sentence"}]}','{"items":[{"display":"Escucho música todos los días.","answers":["Escucho música todos los días."]},{"display":"Me gustan estas canciones.","answers":["Me gustan estas canciones."]},{"display":"Ella quiere cantar en español.","answers":["Ella quiere cantar en español."]},{"display":"¿Cuándo escuchas música?","answers":["¿Cuándo escuchas música?"]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U14-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-musica-06','es1-musica','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿Qué tipo de música le gusta a Rosa?","input":"sentence"},{"prompt":"¿Qué hace su hermano?","input":"sentence"},{"prompt":"¿Cuántas palabras estudia Rosa cada semana?","input":"sentence"}],"text":"Rosa escucha música todos los días. Le gusta el pop y también le gustan las canciones en español.\nCanta en casa y baila con sus amigas los viernes.\nSu hermano no canta, pero toca la guitarra.\nRosa quiere entender las canciones y estudia diez palabras cada semana."}','{"items":[{"display":"Le gusta el pop.","answers":["Le gusta el pop."]},{"display":"Toca la guitarra.","answers":["Toca la guitarra."]},{"display":"Estudia diez palabras.","answers":["Estudia diez palabras."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U14-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-musica-07','es1-musica','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Qué música escuchas?\n¿Cuándo escuchas música?\n¿Quieres cantar o tocar un instrumento?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U14-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-musica-08','es1-musica','open','writing','כתיבה','כתבו פסקה בת 5 משפטים על המוזיקה בחיים שלכם: מה, מתי, איפה ועם מי. הוסיפו משפט עם quiero ושתי שאלות לאדם אחר.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Escucho pop todos los días. Escucho música en casa por la noche. A veces canto con mi hermana. Me gustan las canciones en español. Quiero aprender a tocar la guitarra. ¿Qué música escuchas? ¿Cuándo cantas?"],"criteria":""}','published','L1-U14-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-musica-09','es1-musica','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"Me ___ bailar.","input":"choice","options":["gusta","gustan"]},{"prompt":"Nosotros ___ al fútbol.","hint":"jugar","input":"text"}]}','{"items":[{"display":"gusta","choice":0},{"display":"jugamos","answers":["jugamos"]}],"policy":{"accents":"strict"}}','published','L1-U14-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-musica-10','es1-musica','open','speaking','אתגר לבחירה','בחרו שיר בספרדית שאתם מכירים. רשמו שלוש מילים שאתם מזהים וכתבו לכל אחת משפט מקורי. אין צורך לתרגם את כל השיר.','self','{"prompt":"","brief":"","note":"משימה פתוחה לבחירה: אין מפתח. אפשר להביא את הניסוח לשיעור."}','{"models":[],"criteria":""}','published','L1-U14-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-musica-11','es1-musica','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["atardecer","entender","adivinar","comer","ritmo","estudiar","vender","gozar"],"right":[{"id":"A","text":"להבין"},{"id":"B","text":"שקיעה"},{"id":"C","text":"לאכול"},{"id":"D","text":"למכור"},{"id":"E","text":"ליהנות"},{"id":"F","text":"לנחש"},{"id":"G","text":"ללמוד"},{"id":"H","text":"קצב"}]}','{"pairs":["B","A","F","C","H","G","D","E"],"policy":{"accents":"lenient"}}','published','L1-U14-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-musica-12','es1-musica','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"Toco la ___; tiene cuerdas.","input":"bank"},{"prompt":"Canto con otras personas en un ___.","input":"bank"},{"prompt":"Antes del concierto tenemos un ___.","input":"bank"},{"prompt":"Leo la ___ para entender las palabras de la canción.","input":"bank"},{"prompt":"Para entrar en el concierto compro una ___.","input":"bank"},{"prompt":"¿___ canta? Mi hermano.","input":"bank"}],"wordbank":["entrada","ensayo","Quién","coro","letra","guitarra"]}','{"items":[{"display":"guitarra","answers":["guitarra"]},{"display":"coro","answers":["coro"]},{"display":"ensayo","answers":["ensayo"]},{"display":"letra","answers":["letra"]},{"display":"entrada","answers":["entrada"]},{"display":"Quién","answers":["Quién"]}],"policy":{"accents":"strict"}}','published','L1-U14-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-musica-13','es1-musica','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"Yo toco la guitarra.","cue":"ella","input":"sentence"},{"prompt":"Mi amigo canta en un coro.","cue":"רבים","input":"sentence"},{"prompt":"Nosotros escuchamos música.","cue":"yo","input":"sentence"},{"prompt":"Tú entiendes la canción.","cue":"ellos","input":"sentence"}]}','{"items":[{"display":"Ella toca la guitarra.","answers":["Ella toca la guitarra."]},{"display":"Mis amigos cantan en un coro.","answers":["Mis amigos cantan en un coro."]},{"display":"Yo escucho música.","answers":["Yo escucho música."]},{"display":"Ellos entienden la canción.","answers":["Ellos entienden la canción."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U14-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-musica-14','es1-musica','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"¿Dónde tocan?"},{"id":"B","text":"En el parque. Mi hermano toca la guitarra y yo canto."},{"id":"C","text":"¡Qué bien! Voy con mi familia."},{"id":"D","text":"El sábado a las ocho."},{"id":"E","text":"¿Cuándo es el concierto?"}]}','{"order":["E","D","A","B","C"],"policy":{"accents":"strict"}}','published','L1-U14-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-musica-15','es1-musica','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Qué instrumento toca el hermano de Sofía?","input":"sentence"},{"prompt":"¿Cuándo tienen ensayo?","input":"sentence"},{"prompt":"¿Por qué lee Sofía la letra?","input":"sentence"},{"prompt":"¿Dónde es el concierto?","input":"sentence"}],"text":"Sofía canta en un coro y su hermano toca la guitarra. Los miércoles tienen un ensayo. Sofía lee la letra de cada canción para entender las palabras. Le gusta la música tranquila, pero su hermano prefiere un ritmo rápido. El sábado dan un concierto en el parque. Sus padres y sus amigos van a escucharlos."}','{"items":[{"display":"La guitarra.","answers":["La guitarra."]},{"display":"Los miércoles.","answers":["Los miércoles."]},{"display":"Para entender las palabras.","answers":["Para entender las palabras."]},{"display":"En el parque.","answers":["En el parque."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U14-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-musica-16','es1-musica','open','writing','כותבים לחיים','כתבו הזמנה להופעה. ציינו יום, שעה, מקום, כלי נגינה ומשתתפים. הוסיפו סיבה להגיע ושאלה למוזמן.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Hola, Ana, tenemos un concierto el sábado a las ocho en el parque. Yo canto en un coro y mi hermano toca la guitarra. Nuestros amigos también tocan el piano y la batería. Ensayamos los miércoles y leemos la letra de cada canción. La música tiene un ritmo alegre y es divertida. ¿Quieres venir con tu familia?"],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U14-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-proyectos-y-metas','es-1','es-1-daily','מטרות ופרויקטים','Proyectos y metas','לתאר פעולות לקידום מטרה ולהגדיר זמן ומספרים.','workbook','[{"he":"querer + infinitivo","target":"הווה"},{"he":"תאריכים","target":"antes del"}]','["querer + שם פועל","תאריכים"]','{"rules":["רצון מתואר ב־querer ושם פועל; פעולה שמקדמת את המטרה מתוארת בהווה.","בתאריך משתמשים ב־el ובמבנה יום de חודש. ליעד לפני תאריך: antes del.","אין צורך בזמן עתיד בתרגילים האלה. ההווה מספיק לתכנון."],"examples":["Quiero aprender español. Practico todos los días.","Mi meta es terminar antes del veinte de junio.","Estudio quince minutos tres veces por semana."],"tips":["לתדירות משתמשים ב־por: tres veces por semana. אין צורך ב־en la semana."],"mistakes":[{"text":"אחרי querer הפועל השני נשאר בשם הפועל, בדיוק כמו בעברית: \"אני רוצה לתרגל\". הטעות מגיעה מהרצון להטות הכול. וזכרו ש־de + el תמיד מתכווץ ל־del.","pairs":[{"bad":"Quiero practico","good":"Quiero practicar"},{"bad":"antes de el diez","good":"antes del diez"}]}]}','[{"term":"abril","he":"אפריל"},{"term":"agosto","he":"אוגוסט"},{"term":"ahorrar","he":"לחסוך"},{"term":"ahorrar dinero","he":"לחסוך כסף"},{"term":"amistad","he":"חברות"},{"term":"año","he":"שנה"},{"term":"antes de","he":"לפני"},{"term":"aprender","he":"ללמוד"},{"term":"aprender algo nuevo","he":"ללמוד דבר חדש"},{"term":"ayuda","he":"עזרה"},{"term":"ayudar","he":"לעזור"},{"term":"carrera","he":"קריירה / מסלול לימודים"},{"term":"catorce","he":"ארבע עשרה"},{"term":"certificado","he":"תעודה"},{"term":"cien","he":"מאה"},{"term":"cinco","he":"חמש"},{"term":"cincuenta","he":"חמישים"},{"term":"comenzar","he":"להתחיל"},{"term":"comer más sano","he":"לאכול בריא יותר"},{"term":"computadora","he":"מחשב"},{"term":"consejo","he":"עצה"},{"term":"cuarenta","he":"ארבעים"},{"term":"cuatro","he":"ארבע"},{"term":"curso","he":"קורס"},{"term":"descansar","he":"לנוח / לָנוּחַ"},{"term":"después de","he":"אחרי"},{"term":"día","he":"יום"},{"term":"diciembre","he":"דצמבר"},{"term":"diecinueve","he":"תשע עשרה"},{"term":"dieciocho","he":"שמונה עשרה"},{"term":"dieciséis","he":"שש עשרה"},{"term":"diecisiete","he":"שבע עשרה"},{"term":"diez","he":"עשר"},{"term":"doce","he":"שתים עשרה"},{"term":"domingo","he":"יום ראשון / רִאשׁוֹן (יוֹם)"},{"term":"dos","he":"שתיים"},{"term":"empezar","he":"להתחיל"},{"term":"enero","he":"ינואר"},{"term":"entrenar","he":"להתאמן"},{"term":"español","he":"ספרדית"},{"term":"estudiar","he":"ללמוד"},{"term":"febrero","he":"פברואר"},{"term":"fecha de inicio","he":"תאריך התחלה"},{"term":"finalizar","he":"לסיים"},{"term":"hablar","he":"לדבר"},{"term":"hacer ejercicio","he":"להתאמן / לעשות פעילות גופנית"},{"term":"hacer nuevos amigos","he":"לרכוש חברים חדשים"},{"term":"hobby","he":"תחביב"},{"term":"horas","he":"שעות"},{"term":"idea","he":"רעיון"},{"term":"importante","he":"חשוב"},{"term":"inglés","he":"אנגלית"},{"term":"iniciar","he":"להתחיל"},{"term":"jueves","he":"יום חמישי"},{"term":"julio","he":"יולי"},{"term":"junio","he":"יוני"},{"term":"leer más libros","he":"לקרוא יותר ספרים"},{"term":"libro","he":"ספר / סֵפֶר"},{"term":"lunes","he":"יום שני"},{"term":"martes","he":"יום שלישי"},{"term":"marzo","he":"מרץ"},{"term":"mayo","he":"מאי"},{"term":"mes","he":"חודש"},{"term":"meta","he":"מטרה"},{"term":"miércoles","he":"יום רביעי"},{"term":"necesitar","he":"להזדקק"},{"term":"noventa","he":"תשעים"},{"term":"noviembre","he":"נובמבר"},{"term":"nueve","he":"תשע"},{"term":"objetivo","he":"יעד"},{"term":"obtener mejores calificaciones","he":"להשיג ציונים טובים יותר"},{"term":"ochenta","he":"שמונים"},{"term":"ocho","he":"שמונה"},{"term":"octubre","he":"אוקטובר"},{"term":"once","he":"אחת עשרה"},{"term":"organizado","he":"מאורגן"},{"term":"organizar","he":"לארגן"},{"term":"pagar","he":"לשלם"},{"term":"paso","he":"צעד"},{"term":"pedir","he":"לבקש / להזמין / לבקש"},{"term":"planear","he":"לתכנן"},{"term":"poder","he":"להיות מסוגל"},{"term":"practicar","he":"לתרגל"},{"term":"profesor","he":"מורה"},{"term":"progreso","he":"התקדמות"},{"term":"proyecto","he":"פרויקט"},{"term":"querer","he":"לרצות"},{"term":"quince","he":"חמש עשרה"},{"term":"recibir","he":"לקבל"},{"term":"romance","he":"קשר רומנטי"},{"term":"sábado","he":"שבת"},{"term":"seis","he":"שש"},{"term":"semana","he":"שבוע"},{"term":"septiembre","he":"ספטמבר"},{"term":"sesenta","he":"שישים"},{"term":"setenta","he":"שבעים"},{"term":"siete","he":"שבע"},{"term":"terminar","he":"לסיים"},{"term":"tiempo","he":"זמן / מזג אוויר / זמן לפי ההקשר"},{"term":"trabajar","he":"לעבוד"},{"term":"trece","he":"שלוש עשרה"},{"term":"treinta","he":"שלושים"},{"term":"treinta y uno","he":"שלושים ואחת"},{"term":"tres","he":"שלוש"},{"term":"uno","he":"אחד / אחת"},{"term":"usar","he":"להשתמש / ללבוש / להשתמש"},{"term":"veinte","he":"עשרים"},{"term":"veinticinco","he":"עשרים וחמש"},{"term":"veinticuatro","he":"עשרים וארבע"},{"term":"veintidós","he":"עשרים ושתיים"},{"term":"veintinueve","he":"עשרים ותשע"},{"term":"veintiocho","he":"עשרים ושמונה"},{"term":"veintiséis","he":"עשרים ושש"},{"term":"veintisiete","he":"עשרים ושבע"},{"term":"veintitrés","he":"עשרים ושלוש"},{"term":"veintiuno","he":"עשרים ואחת"},{"term":"vender","he":"למכור"},{"term":"vida","he":"חיים"},{"term":"viernes","he":"יום שישי"},{"term":"vivir","he":"לגור / לחיות"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/994764526/goals-and-projects-basic-spanish-flash-cards/?new"}]','published','workbook L1 unit 15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-proyectos-y-metas-01','es1-proyectos-y-metas','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"מטרה ___","input":"text"},{"prompt":"להתחיל ___","input":"text"},{"prompt":"לתכנן ___","input":"text"},{"prompt":"לסיים ___","input":"text"}]}','{"items":[{"display":"meta","answers":["meta"]},{"display":"empezar","answers":["empezar"]},{"display":"planear","answers":["planear"]},{"display":"terminar","answers":["terminar"]}],"policy":{"accents":"lenient"}}','published','L1-U15-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-proyectos-y-metas-02','es1-proyectos-y-metas','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"Quiero ___ español.","input":"choice","options":["aprender","aprendo"]},{"prompt":"Ella ___ todos los días.","hint":"practicar","input":"text"},{"prompt":"Nosotros ___ ayuda.","hint":"necesitar","input":"text"},{"prompt":"Mi curso empieza ___ cinco de mayo.","input":"choice","options":["el","en"]},{"prompt":"31 → כתבו במילים","input":"text"},{"prompt":"Termino antes ___ diez de junio.","input":"choice","options":["del","de el"]},{"prompt":"Ella quiere ___ veinte palabras.","input":"choice","options":["aprender","aprende"]},{"prompt":"Practico tres veces ___ semana.","input":"choice","options":["por","en"]}]}','{"items":[{"display":"aprender","choice":0},{"display":"practica","answers":["practica"]},{"display":"necesitamos","answers":["necesitamos"]},{"display":"el","choice":0},{"display":"treinta y uno","answers":["treinta y uno"]},{"display":"del","choice":0},{"display":"aprender","choice":0},{"display":"por","choice":0}],"policy":{"accents":"strict"}}','published','L1-U15-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-proyectos-y-metas-03','es1-proyectos-y-metas','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"Quiero practico cada día.","input":"sentence"},{"prompt":"Termino antes de el diez de junio.","input":"sentence"},{"prompt":"Mi curso empieza en cinco de mayo.","input":"sentence"},{"prompt":"Nosotros necesita ayuda.","input":"sentence"}]}','{"items":[{"display":"Quiero practicar cada día.","answers":["Quiero practicar cada día."]},{"display":"Termino antes del diez de junio.","answers":["Termino antes del diez de junio."]},{"display":"Mi curso empieza el cinco de mayo.","answers":["Mi curso empieza el cinco de mayo."]},{"display":"Nosotros necesitamos ayuda.","answers":["Nosotros necesitamos ayuda."]}],"policy":{"accents":"strict"}}','published','L1-U15-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-proyectos-y-metas-04','es1-proyectos-y-metas','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"Yo estudio veinte minutos. → Ella…","input":"sentence"},{"prompt":"Quiero practico cada día. → תקנו","input":"sentence"},{"prompt":"12 de septiembre → היום במילים","input":"sentence"}]}','{"items":[{"display":"Ella estudia veinte minutos.","answers":["Ella estudia veinte minutos."]},{"display":"Quiero practicar cada día.","answers":["Quiero practicar cada día."]},{"display":"doce de septiembre","answers":["doce de septiembre"]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U15-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-proyectos-y-metas-05','es1-proyectos-y-metas','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"המטרה שלי היא לקרוא ספר בספרדית.","input":"sentence"},{"prompt":"אני מתרגל שלוש פעמים בשבוע.","input":"sentence"},{"prompt":"הקורס שלי מתחיל בחמישה במאי.","input":"sentence"},{"prompt":"אני רוצה לסיים לפני העשרים ביוני.","input":"sentence"}]}','{"items":[{"display":"Mi meta es leer un libro en español.","answers":["Mi meta es leer un libro en español."]},{"display":"Practico tres veces por semana.","answers":["Practico tres veces por semana."]},{"display":"Mi curso empieza el cinco de mayo.","answers":["Mi curso empieza el cinco de mayo."]},{"display":"Quiero terminar antes del veinte de junio.","answers":["Quiero terminar antes del veinte de junio."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U15-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-proyectos-y-metas-06','es1-proyectos-y-metas','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿Cuál es la meta de la persona que escribe?","input":"sentence"},{"prompt":"¿Cuántos minutos estudia por semana?","input":"sentence"},{"prompt":"¿Qué quiere aprender Eva?","input":"sentence"}],"text":"Mi meta es leer un libro corto en español antes del treinta de junio.\nEstudio quince minutos los lunes, miércoles y viernes. Leo dos páginas cada vez.\nMi amiga Eva practica conmigo los viernes. Ella quiere aprender veinte palabras nuevas este mes.\nTenemos un cuaderno para ver nuestro progreso."}','{"items":[{"display":"Leer un libro corto en español antes del treinta de junio.","answers":["Leer un libro corto en español antes del treinta de junio."]},{"display":"Estudia cuarenta y cinco minutos por semana.","answers":["Estudia cuarenta y cinco minutos por semana.","quince minutos, tres veces por semana"]},{"display":"Quiere aprender veinte palabras nuevas.","answers":["Quiere aprender veinte palabras nuevas."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U15-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-proyectos-y-metas-07','es1-proyectos-y-metas','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Cuál es tu meta para este mes?\n¿Qué haces para llegar a tu meta?\n¿Cuánto tiempo practicas por semana?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U15-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-proyectos-y-metas-08','es1-proyectos-y-metas','open','writing','כתיבה','כתבו כרטיס מטרה של 6 משפטים: המטרה, תאריך, שתי פעולות קבועות, תדירות ומי יכול לעזור. כתבו את המספרים במילים.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Mi meta es leer un libro en español. Quiero terminar antes del veinte de julio. Leo dos páginas cada día. Estudio diez palabras los lunes. Practico quince minutos por la noche. Mi amiga estudia conmigo."],"criteria":""}','published','L1-U15-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-proyectos-y-metas-09','es1-proyectos-y-metas','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"45 → כתבו במילים","input":"text"},{"prompt":"Estudio ___ lunes.","cue":"בכל יום שני","input":"choice","options":["el","los"]}]}','{"items":[{"display":"cuarenta y cinco","answers":["cuarenta y cinco"]},{"display":"los","choice":1}],"policy":{"accents":"strict"}}','published','L1-U15-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-proyectos-y-metas-10','es1-proyectos-y-metas','open','speaking','אתגר לבחירה','כתבו תוכנית קצרה חלופית ליום עמוס. הגדירו פעולה שנמשכת חמש דקות ושומרת על הקשר למטרה.','self','{"prompt":"","brief":"","note":"משימה פתוחה לבחירה: אין מפתח. אפשר להביא את הניסוח לשיעור."}','{"models":[],"criteria":""}','published','L1-U15-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-proyectos-y-metas-11','es1-proyectos-y-metas','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["tiempo","empezar","estudiar","semana","planear","idea","día","sábado"],"right":[{"id":"A","text":"שבוע"},{"id":"B","text":"לתכנן"},{"id":"C","text":"ללמוד"},{"id":"D","text":"שבת"},{"id":"E","text":"יום"},{"id":"F","text":"להתחיל"},{"id":"G","text":"זמן"},{"id":"H","text":"רעיון"}]}','{"pairs":["G","F","C","A","B","H","E","D"],"policy":{"accents":"lenient"}}','published','L1-U15-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-proyectos-y-metas-12','es1-proyectos-y-metas','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"Mi ___ es terminar el curso.","input":"bank"},{"prompt":"Para recordar las fechas, necesito ___ mi tiempo.","input":"bank"},{"prompt":"Después del curso recibo un ___.","input":"bank"},{"prompt":"El mes después de agosto es ___.","input":"bank"},{"prompt":"Para mejorar mi español, necesito ___ todos los días.","input":"bank"},{"prompt":"Guardo dinero: quiero ___.","input":"bank"}],"wordbank":["certificado","organizar","practicar","meta","septiembre","ahorrar"]}','{"items":[{"display":"meta","answers":["meta"]},{"display":"organizar","answers":["organizar"]},{"display":"certificado","answers":["certificado"]},{"display":"septiembre","answers":["septiembre"]},{"display":"practicar","answers":["practicar"]},{"display":"ahorrar","answers":["ahorrar"]}],"policy":{"accents":"strict"}}','published','L1-U15-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-proyectos-y-metas-13','es1-proyectos-y-metas','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"Yo quiero aprender español.","cue":"ella","input":"sentence"},{"prompt":"Necesitamos practicar.","cue":"yo","input":"sentence"},{"prompt":"Él empieza en septiembre.","cue":"ellos","input":"sentence"},{"prompt":"Tú puedes ayudar.","cue":"nosotros","input":"sentence"}]}','{"items":[{"display":"Ella quiere aprender español.","answers":["Ella quiere aprender español."]},{"display":"Necesito practicar.","answers":["Necesito practicar."]},{"display":"Ellos empiezan en septiembre.","answers":["Ellos empiezan en septiembre."]},{"display":"Nosotros podemos ayudar.","answers":["Nosotros podemos ayudar."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U15-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-proyectos-y-metas-14','es1-proyectos-y-metas','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"Quiero terminar un curso de español."},{"id":"B","text":"Muy bien. Puedo ayudarte los sábados."},{"id":"C","text":"¿Cuál es tu meta para este año?"},{"id":"D","text":"¿Cuándo empiezas?"},{"id":"E","text":"El quince de septiembre. Practico los lunes y jueves."}]}','{"order":["C","A","D","E","B"],"policy":{"accents":"strict"}}','published','L1-U15-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-proyectos-y-metas-15','es1-proyectos-y-metas','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Cuándo quiere terminar Andrés el curso?","input":"sentence"},{"prompt":"¿Cuándo empieza?","input":"sentence"},{"prompt":"¿Cuánto estudia los lunes y jueves?","input":"sentence"},{"prompt":"¿Para qué quiere el certificado?","input":"sentence"}],"text":"Andrés quiere terminar un curso de español en diciembre. Empieza el quince de septiembre. Los lunes y jueves estudia una hora en casa. Los sábados practica con una amiga. Cuando necesita ayuda, habla con su profesor. Quiere un certificado para su trabajo. Su meta es importante y organiza su tiempo para practicar cada semana."}','{"items":[{"display":"En diciembre.","answers":["En diciembre."]},{"display":"El quince de septiembre.","answers":["El quince de septiembre."]},{"display":"Una hora cada día.","answers":["Una hora cada día."]},{"display":"Para su trabajo.","answers":["Para su trabajo."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U15-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-proyectos-y-metas-16','es1-proyectos-y-metas','open','writing','כותבים לחיים','תכננו מטרה אישית. ציינו תאריך התחלה, מועד סיום ושלושה צעדים לביצוע. הוסיפו תדירות ואדם שיכול לעזור. השתמשו ב־quiero, necesito ו־puedo.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Quiero terminar un curso de español en diciembre. Empiezo el quince de septiembre y necesito organizar mi tiempo. Primero estudio una hora los lunes y jueves. Después practico con una amiga todos los sábados. También leo un libro y puedo pedir ayuda a mi profesor. Mi meta es recibir un certificado para mi trabajo."],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U15-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-descubrimientos','es-1','es-1-out','מגלים את העולם','Descubrimientos','לתאר פעולות של חיות ולהשתמש במילות מקום.','workbook','[{"he":"פעלים בהווה","target":"מילות מקום"},{"he":"debajo de · encima de","target":"cerca de · lejos de"}]','["פעלים","מילות מקום"]','{"rules":["גם כשמדברים על חיות הפועל מותאם ליחיד או לרבים. ב־volar הצורות הן vuela · vuelan.","מילות מקום דורשות de אחריהן: debajo de · encima de · cerca de · lejos de.","con גם לציון אמצעי: Escribo con la mano. ושתי הצורות נכונות: encima de = arriba de."],"examples":["El mono trepa. Los monos trepan.","El pájaro vuela. Los pájaros vuelan.","El gato está debajo de la mesa. Japón está lejos de Israel."],"tips":["por מציין תנועה לאורך או דרך: El mono trepa por el árbol. לעומת en שמציין מיקום סטטי."],"mistakes":[{"text":"בעברית מילת המקום היא מילה אחת (\"מתחת\", \"ליד\"), ולכן ה־de נופל בתרגום. בספרדית הוא חלק מהביטוי. וגם כשהנושא הוא חיה, הפועל חייב להתאים למספר.","pairs":[{"bad":"debajo la mesa","good":"debajo de la mesa"},{"bad":"Los monos trepa","good":"Los monos trepan"}]}]}','[{"term":"al lado de","he":"ליד"},{"term":"animal","he":"חיה"},{"term":"árbol","he":"עץ"},{"term":"bailar","he":"לרקוד"},{"term":"boca","he":"פה"},{"term":"bosque","he":"יער"},{"term":"cabeza","he":"ראש"},{"term":"caminar","he":"ללכת / לָלֶכֶת"},{"term":"cantar","he":"לשיר"},{"term":"cara","he":"פנים"},{"term":"cerca de","he":"קרוב ל־ / קרוב ל"},{"term":"comer","he":"לאכול / לֶאֱכוֹל"},{"term":"contar","he":"לספור"},{"term":"correr","he":"לרוץ"},{"term":"crear","he":"ליצור"},{"term":"creativo","he":"יצירתי"},{"term":"cuello","he":"צוואר"},{"term":"debajo de","he":"מתחת ל־ / מתחת"},{"term":"derecha","he":"ימינה / ימין"},{"term":"dibujar","he":"לצייר"},{"term":"elefante","he":"פיל"},{"term":"en","he":"ב־ / ב..."},{"term":"encima de","he":"מעל ל / מעל ל־"},{"term":"escalar","he":"לטפס"},{"term":"escribir","he":"לכתוב"},{"term":"estudiar","he":"ללמוד"},{"term":"flores","he":"פרחים"},{"term":"gato","he":"חתול"},{"term":"hablar","he":"לדבר"},{"term":"hermano","he":"אח"},{"term":"hoja","he":"עלה"},{"term":"imagen","he":"תמונה"},{"term":"imaginar","he":"לדמיין"},{"term":"izquierda","he":"שמאלה / שמאל"},{"term":"jirafa","he":"ג''ירפה"},{"term":"lápiz","he":"עיפרון"},{"term":"leer","he":"לקרוא"},{"term":"lejos de","he":"רחוק מ־ / רחוק מ"},{"term":"león","he":"אריה"},{"term":"leopardo","he":"נמר"},{"term":"libro","he":"ספר / סֵפֶר"},{"term":"lógico","he":"הגיוני"},{"term":"mano","he":"יד"},{"term":"mar","he":"ים"},{"term":"mono","he":"קוף"},{"term":"nariz","he":"אף"},{"term":"nombre","he":"שם"},{"term":"ojo","he":"עין"},{"term":"ojos","he":"עיניים"},{"term":"oreja","he":"אוזן"},{"term":"organizar","he":"לארגן"},{"term":"país","he":"מדינה / ארץ / מדינה"},{"term":"pájaro","he":"ציפור"},{"term":"parte del cuerpo","he":"חלק גוף"},{"term":"pensar","he":"לחשוב"},{"term":"perro","he":"כלב"},{"term":"pie","he":"כף רגל"},{"term":"pierna","he":"רגל"},{"term":"pies","he":"כפות רגליים"},{"term":"planificar","he":"לתכנן"},{"term":"resolver","he":"לפתור"},{"term":"selva","he":"יער גשם"},{"term":"sonreír","he":"לחייך"},{"term":"trepar","he":"לטפס"},{"term":"usar","he":"להשתמש / ללבוש / להשתמש"},{"term":"ver","he":"לראות"},{"term":"volar","he":"לעוף"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1058767411/espanol-basico-descubrimientos-flash-cards/?funnelUUID=37979ad9-31a7-4c3e-8003-ee94881bb4b0"}]','published','workbook L1 unit 16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-descubrimientos-01','es1-descubrimientos','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"חיה ___","input":"text"},{"prompt":"פיל ___","input":"text"},{"prompt":"ג׳ירפה ___","input":"text"},{"prompt":"קוף ___","input":"text"}]}','{"items":[{"display":"animal","answers":["animal"]},{"display":"elefante","answers":["elefante"]},{"display":"jirafa","answers":["jirafa"]},{"display":"mono","answers":["mono"]}],"policy":{"accents":"lenient"}}','published','L1-U16-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-descubrimientos-02','es1-descubrimientos','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"El elefante ___.","hint":"caminar","input":"text"},{"prompt":"Los monos ___.","hint":"trepar","input":"text"},{"prompt":"El pájaro ___.","input":"choice","options":["vuela","vuelan"]},{"prompt":"Las jirafas ___.","hint":"comer","input":"text"},{"prompt":"El gato está debajo ___ la mesa.","input":"choice","options":["de","con"]},{"prompt":"Escribo ___ la mano.","input":"choice","options":["con","en"]},{"prompt":"Israel está ___ Jordania.","input":"choice","options":["cerca de","lejos de"]},{"prompt":"Japón está ___ Israel.","input":"choice","options":["cerca de","lejos de"]}]}','{"items":[{"display":"camina","answers":["camina"]},{"display":"trepan","answers":["trepan"]},{"display":"vuela","choice":0},{"display":"comen","answers":["comen"]},{"display":"de","choice":0},{"display":"con","choice":0},{"display":"cerca de","choice":0},{"display":"lejos de","choice":1}],"policy":{"accents":"strict"}}','published','L1-U16-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-descubrimientos-03','es1-descubrimientos','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"Los monos trepa por el árbol.","input":"sentence"},{"prompt":"El pájaro vuelan.","input":"sentence"},{"prompt":"El gato está debajo la mesa.","input":"sentence"},{"prompt":"Escribo en la mano.","input":"sentence"}]}','{"items":[{"display":"Los monos trepan por el árbol.","answers":["Los monos trepan por el árbol."]},{"display":"El pájaro vuela.","answers":["El pájaro vuela."]},{"display":"El gato está debajo de la mesa.","answers":["El gato está debajo de la mesa."]},{"display":"Escribo con la mano.","answers":["Escribo con la mano."]}],"policy":{"accents":"strict"}}','published','L1-U16-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-descubrimientos-04','es1-descubrimientos','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"El mono come. → רבים","input":"sentence"},{"prompt":"El pájaro vuela. → רבים","input":"sentence"},{"prompt":"El gato está encima de la silla. → החליפו מעל במתחת","input":"sentence"}]}','{"items":[{"display":"Los monos comen.","answers":["Los monos comen."]},{"display":"Los pájaros vuelan.","answers":["Los pájaros vuelan."]},{"display":"El gato está debajo de la silla.","answers":["El gato está debajo de la silla."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U16-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-descubrimientos-05','es1-descubrimientos','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"הקוף מטפס על העץ.","input":"sentence"},{"prompt":"הציפורים עפות.","input":"sentence"},{"prompt":"החתול נמצא מתחת לשולחן.","input":"sentence"},{"prompt":"יפן רחוקה מישראל.","input":"sentence"}]}','{"items":[{"display":"El mono trepa por el árbol.","answers":["El mono trepa por el árbol."]},{"display":"Los pájaros vuelan.","answers":["Los pájaros vuelan."]},{"display":"El gato está debajo de la mesa.","answers":["El gato está debajo de la mesa."]},{"display":"Japón está lejos de Israel.","answers":["Japón está lejos de Israel."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U16-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-descubrimientos-06','es1-descubrimientos','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿Qué hace el mono?","input":"sentence"},{"prompt":"¿Dónde está el gato?","input":"sentence"},{"prompt":"¿Qué animal está a la derecha del árbol?","input":"sentence"}],"text":"En este dibujo hay un árbol y una mesa. Un mono trepa por el árbol.\nUn pájaro está encima de la mesa y un gato está debajo de la mesa.\nA la derecha del árbol hay una jirafa. La jirafa come.\nUn elefante camina al lado del árbol."}','{"items":[{"display":"Trepa por el árbol.","answers":["Trepa por el árbol."]},{"display":"Está debajo de la mesa.","answers":["Está debajo de la mesa."]},{"display":"La jirafa.","answers":["La jirafa."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U16-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-descubrimientos-07','es1-descubrimientos','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Cuál es tu animal favorito?\n¿Dónde vive?\n¿Qué hace normalmente?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U16-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-descubrimientos-08','es1-descubrimientos','open','writing','כתיבה','כתבו חידה של 5 משפטים על חיה: מיקום, שתי פעולות ושני מאפיינים. כתבו את התשובה בנפרד כדי שאפשר יהיה לנחש.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Es un animal grande. Tiene un cuello largo. Vive en África. Come hojas. Camina cerca de otros animales. Respuesta: la jirafa."],"criteria":""}','published','L1-U16-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-descubrimientos-09','es1-descubrimientos','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"El banco está al lado ___ museo.","input":"choice","options":["de el","del"]},{"prompt":"___ dos sillas.","input":"choice","options":["Hay","Está"]}]}','{"items":[{"display":"del","choice":1},{"display":"Hay","choice":0}],"policy":{"accents":"strict"}}','published','L1-U16-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-descubrimientos-10','es1-descubrimientos','open','speaking','אתגר לבחירה','ציירו את הסצנה שבטקסט והוסיפו שתי חיות. כתבו מה הן עושות והיכן הן נמצאות. בדקו שאין סתירה בין הציור למשפטים.','self','{"prompt":"","brief":"","note":"משימה פתוחה לבחירה: אין מפתח. אפשר להביא את הניסוח לשיעור."}','{"models":[],"criteria":""}','published','L1-U16-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-descubrimientos-11','es1-descubrimientos','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["cantar","cerca de","pierna","jirafa","imaginar","dibujar","mano","sonreír"],"right":[{"id":"A","text":"לדמיין"},{"id":"B","text":"קרוב ל"},{"id":"C","text":"לצייר"},{"id":"D","text":"לשיר"},{"id":"E","text":"לחייך"},{"id":"F","text":"יד"},{"id":"G","text":"רגל"},{"id":"H","text":"ג''ירפה"}]}','{"pairs":["D","B","G","H","A","C","F","E"],"policy":{"accents":"lenient"}}','published','L1-U16-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-descubrimientos-12','es1-descubrimientos','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"El ___ trepa por el árbol.","input":"bank"},{"prompt":"El pájaro puede ___.","input":"bank"},{"prompt":"La ___ tiene el cuello largo.","input":"bank"},{"prompt":"Uso los ___ para ver.","input":"bank"},{"prompt":"Escribo con la ___.","input":"bank"},{"prompt":"El lápiz está ___ del libro: no puedo verlo.","input":"bank"}],"wordbank":["volar","debajo","jirafa","mono","ojos","mano"]}','{"items":[{"display":"mono","answers":["mono"]},{"display":"volar","answers":["volar"]},{"display":"jirafa","answers":["jirafa"]},{"display":"ojos","answers":["ojos"]},{"display":"mano","answers":["mano"]},{"display":"debajo","answers":["debajo"]}],"policy":{"accents":"strict"}}','published','L1-U16-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-descubrimientos-13','es1-descubrimientos','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"El pájaro vuela.","cue":"רבים","input":"sentence"},{"prompt":"Yo dibujo un animal.","cue":"nosotros","input":"sentence"},{"prompt":"La mano está debajo del libro.","cue":"רבים","input":"sentence"},{"prompt":"Tú cuentas los animales.","cue":"ella","input":"sentence"}]}','{"items":[{"display":"Los pájaros vuelan.","answers":["Los pájaros vuelan."]},{"display":"Nosotros dibujamos un animal.","answers":["Nosotros dibujamos un animal."]},{"display":"Las manos están debajo del libro.","answers":["Las manos están debajo del libro."]},{"display":"Ella cuenta los animales.","answers":["Ella cuenta los animales."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U16-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-descubrimientos-14','es1-descubrimientos','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"¿Dónde está el pájaro?"},{"id":"B","text":"Encima del árbol, y la jirafa está al lado."},{"id":"C","text":"¿Qué dibujas?"},{"id":"D","text":"Un mono, una jirafa y un pájaro."},{"id":"E","text":"Ahora veo los tres animales."}]}','{"order":["C","D","A","B","E"],"policy":{"accents":"strict"}}','published','L1-U16-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-descubrimientos-15','es1-descubrimientos','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Cuántos animales dibuja Julia?","input":"sentence"},{"prompt":"¿Qué hace el mono?","input":"sentence"},{"prompt":"¿Dónde está la mano?","input":"sentence"},{"prompt":"¿Qué escribe el hermano de Julia?","input":"sentence"}],"text":"Julia dibuja tres animales. Un mono trepa por un árbol y un pájaro vuela encima del árbol. Una jirafa está al lado y come hojas. Julia dibuja también una mano debajo de los animales. Su hermano cuenta los animales y escribe sus nombres. A Julia le gusta imaginar; a su hermano le gusta organizar las palabras."}','{"items":[{"display":"Tres.","answers":["Tres."]},{"display":"Trepa por un árbol.","answers":["Trepa por un árbol."]},{"display":"Debajo de los animales.","answers":["Debajo de los animales."]},{"display":"Los nombres de los animales.","answers":["Los nombres de los animales."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U16-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-descubrimientos-16','es1-descubrimientos','open','writing','כותבים לחיים','תארו תמונה דמיונית עם שלושה בעלי חיים. השתמשו בשלושה פעלים ובשלושה ביטויי מקום. הוסיפו שני חלקי גוף.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["En mi dibujo hay un mono, una jirafa y un pájaro. El mono trepa por un árbol. El pájaro vuela encima del árbol y la jirafa come hojas al lado de las flores. Una mano está debajo de los animales. Dibujo también dos ojos cerca de la mano. Mi hermano cuenta los animales y escribe sus nombres."],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U16-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-artes-y-manualidades','es-1','es-1-leisure','אמנות ויצירה','Artes y manualidades','לתאר יצירה ולהסביר מה אנשים עושים בהווה.','workbook','[{"he":"ser + תואר","target":"colores"},{"he":"פעלים בהווה","target":"porque"}]','["תיאור","porque"]','{"rules":["לתיאור צבע וצורה משתמשים ב־ser ובתואר שמתאים במין ובמספר.","לפעולה משתמשים בפועל מוטה: yo dibujo · ella pinta.","porque מחבר סיבה ונכתב במילה אחת, בלי הטעמה."],"examples":["El círculo es rojo. Las líneas son rojas.","Yo dibujo. Ella pinta. Nosotros pintamos.","Me gusta pintar porque es divertido."],"tips":["dibujar הוא ציור בקו ובעיפרון, pintar הוא ציור בצבע. בעברית מילה אחת, בספרדית שתיים."],"mistakes":[{"text":"הצבע הוא תואר לכל דבר ולכן מתאים במין ובמספר: líneas verdes. ואת porque (סיבה) כותבים במילה אחת, בניגוד ל־por qué (שאלה).","pairs":[{"bad":"Las líneas son verde","good":"Las líneas son verdes"},{"bad":"por que es divertido","good":"porque es divertido"}]}]}','[{"term":"a la derecha","he":"ימינה"},{"term":"a la izquierda","he":"שמאלה"},{"term":"abajo","he":"למטה"},{"term":"alegre","he":"שמח"},{"term":"amarillo","he":"צהוב"},{"term":"arriba","he":"למעלה"},{"term":"arte","he":"אמנות"},{"term":"artista","he":"אמן"},{"term":"azul","he":"כחול"},{"term":"bailar","he":"לרקוד"},{"term":"blanco","he":"לבן"},{"term":"brillante","he":"מבריק"},{"term":"caballete","he":"כן ציור"},{"term":"cámara","he":"מצלמה"},{"term":"cantar","he":"לשיר"},{"term":"círculo","he":"עיגול"},{"term":"color","he":"צבע"},{"term":"colorido","he":"צבעוני"},{"term":"concierto","he":"קונצרט / הופעה / הופעה"},{"term":"cuaderno","he":"מחברת"},{"term":"cuadrado","he":"ריבוע"},{"term":"cuadro","he":"תמונה / ציור"},{"term":"danza","he":"מחול"},{"term":"debajo de","he":"מתחת ל־ / מתחת"},{"term":"dentro","he":"בפנים"},{"term":"dentro de","he":"בתוך"},{"term":"dibujar","he":"לצייר"},{"term":"divertido","he":"מהנה / מצחיק"},{"term":"encima de","he":"מעל ל / מעל ל־"},{"term":"escultura","he":"פיסול / פסל"},{"term":"estatua","he":"פסל"},{"term":"forma","he":"צורה"},{"term":"grande","he":"גדול"},{"term":"guitarra","he":"גיטרה"},{"term":"gustar","he":"למצוא חן, למשל me gusta = אני אוהב"},{"term":"hacer","he":"לעשות"},{"term":"hermoso","he":"יפה"},{"term":"importante","he":"חשוב"},{"term":"interesante","he":"מעניין"},{"term":"lápiz","he":"עיפרון"},{"term":"largo","he":"ארוך"},{"term":"lienzo","he":"בד ציור"},{"term":"línea","he":"קו"},{"term":"madera","he":"עץ כחומר"},{"term":"mano","he":"יד"},{"term":"máscara","he":"מסכה"},{"term":"material","he":"חומר"},{"term":"micrófono","he":"מיקרופון"},{"term":"mirar","he":"להסתכל / לצפות / לצפות / להסתכל"},{"term":"moderno","he":"מודרני"},{"term":"museo","he":"מוזיאון"},{"term":"negro","he":"שחור"},{"term":"nuevo","he":"חדש"},{"term":"objeto","he":"חפץ"},{"term":"oscuro","he":"כהה"},{"term":"pequeño","he":"קטן"},{"term":"pesado","he":"כבד"},{"term":"piano","he":"פסנתר"},{"term":"pincel","he":"מכחול"},{"term":"pintar","he":"לצייר / לצבוע / לצייר"},{"term":"pintura","he":"ציור"},{"term":"porque","he":"מפני ש־"},{"term":"preferir","he":"להעדיף"},{"term":"rojo","he":"אדום"},{"term":"simple","he":"פשוט"},{"term":"tambor","he":"תוף"},{"term":"tener","he":"יש ל־ / להיות בעל"},{"term":"tocar (música)","he":"לנגן"},{"term":"triángulo","he":"משולש"},{"term":"verde","he":"ירוק"},{"term":"viejo","he":"ישן"},{"term":"visitar","he":"לבקר"},{"term":"zapatillas de ballet","he":"נעלי בלט"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/858627241/basic-spanish-arts-crafts-flash-cards/"}]','published','workbook L1 unit 17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-artes-y-manualidades-01','es1-artes-y-manualidades','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"עיגול ___","input":"text"},{"prompt":"ריבוע ___","input":"text"},{"prompt":"משולש ___","input":"text"},{"prompt":"קו ___","input":"text"}]}','{"items":[{"display":"círculo","answers":["círculo"]},{"display":"cuadrado","answers":["cuadrado"]},{"display":"triángulo","answers":["triángulo"]},{"display":"línea","answers":["línea"]}],"policy":{"accents":"lenient"}}','published','L1-U17-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-artes-y-manualidades-02','es1-artes-y-manualidades','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"El círculo ___ rojo.","input":"choice","options":["es","está"]},{"prompt":"Las líneas son ___.","input":"choice","options":["negra","negras"]},{"prompt":"Yo ___ un cuadro.","hint":"pintar","input":"text"},{"prompt":"Ella ___ animales.","hint":"dibujar","input":"text"},{"prompt":"Nosotros ___ una canción.","hint":"cantar","input":"text"},{"prompt":"Me ___ dibujar.","input":"choice","options":["gusta","gustan"]},{"prompt":"Las flores ___ rojas.","input":"choice","options":["es","son"]},{"prompt":"Me gusta dibujar ___ es divertido.","input":"choice","options":["porque","por qué"]}]}','{"items":[{"display":"es","choice":0},{"display":"negras","choice":1},{"display":"pinto","answers":["pinto"]},{"display":"dibuja","answers":["dibuja"]},{"display":"cantamos","answers":["cantamos"]},{"display":"gusta","choice":0},{"display":"son","choice":1},{"display":"porque","choice":0}],"policy":{"accents":"strict"}}','published','L1-U17-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-artes-y-manualidades-03','es1-artes-y-manualidades','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"El cuadrado es amarilla.","input":"sentence"},{"prompt":"Yo pinta un círculo.","input":"sentence"},{"prompt":"Las líneas son verde.","input":"sentence"},{"prompt":"Me gusta pintar por que es divertido.","input":"sentence"}]}','{"items":[{"display":"El cuadrado es amarillo.","answers":["El cuadrado es amarillo."]},{"display":"Yo pinto un círculo.","answers":["Yo pinto un círculo."]},{"display":"Las líneas son verdes.","answers":["Las líneas son verdes."]},{"display":"Me gusta pintar porque es divertido.","answers":["Me gusta pintar porque es divertido."]}],"policy":{"accents":"strict"}}','published','L1-U17-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-artes-y-manualidades-04','es1-artes-y-manualidades','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"El cuadrado es amarillo. → רבים","input":"sentence"},{"prompt":"Yo pinto un círculo. → Ella…","input":"sentence"},{"prompt":"Las líneas son verdes. → שלילה","input":"sentence"}]}','{"items":[{"display":"Los cuadrados son amarillos.","answers":["Los cuadrados son amarillos."]},{"display":"Ella pinta un círculo.","answers":["Ella pinta un círculo."]},{"display":"Las líneas no son verdes.","answers":["Las líneas no son verdes."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U17-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-artes-y-manualidades-05','es1-artes-y-manualidades','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"העיגול אדום.","input":"sentence"},{"prompt":"הקווים שחורים.","input":"sentence"},{"prompt":"אני מצייר ציפור.","input":"sentence"},{"prompt":"אני אוהב לצייר כי זה כיף.","input":"sentence"}]}','{"items":[{"display":"El círculo es rojo.","answers":["El círculo es rojo."]},{"display":"Las líneas son negras.","answers":["Las líneas son negras."]},{"display":"Dibujo un pájaro.","answers":["Dibujo un pájaro."]},{"display":"Me gusta dibujar porque es divertido.","answers":["Me gusta dibujar porque es divertido."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U17-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-artes-y-manualidades-06','es1-artes-y-manualidades','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿De qué color es la ventana?","input":"sentence"},{"prompt":"¿Dónde está el árbol?","input":"sentence"},{"prompt":"¿Qué pinta la hermana?","input":"sentence"}],"text":"En mi dibujo hay una casa pequeña. La casa es blanca y tiene una ventana azul.\nA la izquierda de la casa hay un árbol verde.\nEncima de la casa hay un círculo amarillo: es el sol.\nMi hermana pinta flores rojas y yo dibujo un pájaro. Nos gusta crear juntos."}','{"items":[{"display":"Es azul.","answers":["Es azul."]},{"display":"Está a la izquierda de la casa.","answers":["Está a la izquierda de la casa."]},{"display":"Pinta flores rojas.","answers":["Pinta flores rojas."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U17-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-artes-y-manualidades-07','es1-artes-y-manualidades','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Qué te gusta crear con tus manos?\n¿Qué colores te gustan?\n¿Prefieres dibujar o pintar? ¿Por qué?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U17-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-artes-y-manualidades-08','es1-artes-y-manualidades','open','writing','כתיבה','ציירו יצירה פשוטה וכתבו לה תיאור של 6 משפטים: שלושה פרטים חזותיים, שתי פעולות ומשפט המסביר למה אתם אוהבים אותה.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Mi dibujo es pequeño. La casa es blanca. Las flores son rojas. Dibujo un pájaro. Mi hermana pinta el árbol. Me gusta el dibujo porque es colorido."],"criteria":""}','published','L1-U17-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-artes-y-manualidades-09','es1-artes-y-manualidades','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"El pájaro ___.","input":"choice","options":["vuela","vuelan"]},{"prompt":"Quiero ___.","input":"choice","options":["pinto","pintar"]}]}','{"items":[{"display":"vuela","choice":0},{"display":"pintar","choice":1}],"policy":{"accents":"strict"}}','published','L1-U17-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-artes-y-manualidades-10','es1-artes-y-manualidades','open','speaking','אתגר לבחירה','בלי להראות את הציור, הקליטו תיאור של ארבעה פרטים. בקשו ממישהו לצייר לפיו והשוו את התוצאות.','self','{"prompt":"","brief":"","note":"משימה פתוחה לבחירה: אין מפתח. אפשר להביא את הניסוח לשיעור."}','{"models":[],"criteria":""}','published','L1-U17-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-artes-y-manualidades-11','es1-artes-y-manualidades','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["bailar","divertido","cuadrado","cámara","guitarra","abajo","pincel","triángulo"],"right":[{"id":"A","text":"מהנה / מצחיק"},{"id":"B","text":"גיטרה"},{"id":"C","text":"מצלמה"},{"id":"D","text":"למטה"},{"id":"E","text":"משולש"},{"id":"F","text":"לרקוד"},{"id":"G","text":"ריבוע"},{"id":"H","text":"מכחול"}]}','{"pairs":["F","A","G","C","B","D","H","E"],"policy":{"accents":"lenient"}}','published','L1-U17-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-artes-y-manualidades-12','es1-artes-y-manualidades','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"Pinto sobre un ___.","input":"bank"},{"prompt":"Pongo el lienzo en un ___.","input":"bank"},{"prompt":"Uso un ___ pequeño para pintar los detalles.","input":"bank"},{"prompt":"Un ___ tiene tres lados.","input":"bank"},{"prompt":"Me cubro la cara con una ___.","input":"bank"},{"prompt":"El contrario de viejo es ___.","input":"bank"}],"wordbank":["caballete","triángulo","lienzo","nuevo","pincel","máscara"]}','{"items":[{"display":"lienzo","answers":["lienzo"]},{"display":"caballete","answers":["caballete"]},{"display":"pincel","answers":["pincel"]},{"display":"triángulo","answers":["triángulo"]},{"display":"máscara","answers":["máscara"]},{"display":"nuevo","answers":["nuevo"]}],"policy":{"accents":"strict"}}','published','L1-U17-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-artes-y-manualidades-13','es1-artes-y-manualidades','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"El círculo es azul.","cue":"רבים","input":"sentence"},{"prompt":"La máscara es pequeña.","cue":"רבים","input":"sentence"},{"prompt":"Yo pinto un cuadro.","cue":"ella","input":"sentence"},{"prompt":"El pincel es nuevo.","cue":"רבים","input":"sentence"}]}','{"items":[{"display":"Los círculos son azules.","answers":["Los círculos son azules."]},{"display":"Las máscaras son pequeñas.","answers":["Las máscaras son pequeñas."]},{"display":"Ella pinta un cuadro.","answers":["Ella pinta un cuadro."]},{"display":"Los pinceles son nuevos.","answers":["Los pinceles son nuevos."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U17-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-artes-y-manualidades-14','es1-artes-y-manualidades','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"Aquí están. ¿Qué pintas?"},{"id":"B","text":"Un cuadrado rojo con un círculo azul dentro."},{"id":"C","text":"Un lienzo y un pincel pequeño."},{"id":"D","text":"¿Qué necesitas para pintar?"},{"id":"E","text":"Me gusta. Yo dibujo un triángulo amarillo."}]}','{"order":["D","C","A","B","E"],"policy":{"accents":"strict"}}','published','L1-U17-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-artes-y-manualidades-15','es1-artes-y-manualidades','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Dónde está el lienzo?","input":"sentence"},{"prompt":"¿De qué color es el círculo?","input":"sentence"},{"prompt":"¿Dónde está el triángulo?","input":"sentence"},{"prompt":"¿Qué hace el amigo de Alba?","input":"sentence"}],"text":"Alba pinta sobre un lienzo que está en un caballete de madera. Usa un pincel pequeño. Primero pinta un cuadrado rojo y después un círculo azul dentro del cuadrado. A la izquierda dibuja un triángulo amarillo. Su amigo hace una máscara verde. Les gusta crear objetos coloridos porque su casa es muy blanca."}','{"items":[{"display":"En un caballete de madera.","answers":["En un caballete de madera."]},{"display":"Azul.","answers":["Azul."]},{"display":"A la izquierda.","answers":["A la izquierda."]},{"display":"Una máscara verde.","answers":["Una máscara verde."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U17-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-artes-y-manualidades-16','es1-artes-y-manualidades','open','writing','כותבים לחיים','תארו יצירה משלכם: כלי עבודה, שלוש צורות ושלושה צבעים. השתמשו בשני ביטויי מקום והסבירו למה אתם אוהבים את היצירה.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Pinto un cuadro sobre un lienzo con un pincel pequeño. Primero dibujo un cuadrado rojo. Dentro del cuadrado hay un círculo azul. A la izquierda dibujo un triángulo amarillo. El cuadro está en un caballete de madera. Me gusta mi pintura porque es colorida y alegre."],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U17-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-el-clima','es-1','es-1-out','מזג האוויר','El clima','לתאר מזג אוויר ולמסור טמפרטורות במספרים.','workbook','[{"he":"hace · está · hay","target":"מספרים"},{"he":"תיאור","target":"grados"}]','["hace ו־está","מספרים"]','{"rules":["hace calor / frío / viento לתחושה הכללית, está nublado / soleado למצב השמיים, hay nubes / una tormenta לקיום של תופעה.","לטמפרטורה: hace veinte grados או la temperatura es de veinte grados.","הנתונים בתרגילים דמיוניים ונועדו לתרגול המספרים."],"examples":["Hace frío. Está nublado. Hay nubes.","La temperatura máxima es de veintiocho grados.","La mínima es de menos dos grados."],"tips":["לטמפרטורה שלילית אומרים menos dos grados או dos grados bajo cero. שתי הצורות נפוצות."],"mistakes":[{"text":"בעברית אומרים \"חם היום\" במילה אחת, ובספרדית הבחירה בין hace, está ו־hay קבועה לכל ביטוי. הדרך לזכור: תחושה עם hace, שמיים עם está, קיום עם hay.","pairs":[{"bad":"Hoy está calor","good":"Hoy hace calor"},{"bad":"El cielo hace nublado","good":"El cielo está nublado"}]}]}','[{"term":"actividad","he":"פעילות"},{"term":"al aire libre","he":"בחוץ באוויר הפתוח"},{"term":"ascenso de temperatura","he":"עלייה בטמפרטורה"},{"term":"cálido","he":"חמים / חם"},{"term":"calor","he":"חום"},{"term":"caluroso","he":"חם"},{"term":"caminar","he":"ללכת / לָלֶכֶת"},{"term":"catorce","he":"ארבע עשרה"},{"term":"chaparrones dispersos","he":"ממטרים פזורים"},{"term":"cien","he":"מאה"},{"term":"cinco","he":"חמש"},{"term":"cincuenta","he":"חמישים"},{"term":"ciudad","he":"עיר"},{"term":"clima","he":"מזג אוויר"},{"term":"cuarenta","he":"ארבעים"},{"term":"cuatro","he":"ארבע"},{"term":"despejado","he":"בהיר"},{"term":"diecinueve","he":"תשע עשרה"},{"term":"dieciocho","he":"שמונה עשרה"},{"term":"dieciséis","he":"שש עשרה"},{"term":"diecisiete","he":"שבע עשרה"},{"term":"diez","he":"עשר"},{"term":"doce","he":"שתים עשרה"},{"term":"domingo","he":"יום ראשון / רִאשׁוֹן (יוֹם)"},{"term":"dos","he":"שתיים"},{"term":"espacio cerrado","he":"חלל סגור"},{"term":"esquiar","he":"לעשות סקי"},{"term":"estación","he":"תחנה / עונה"},{"term":"estudio","he":"אולפן"},{"term":"fresco","he":"קריר / טרי"},{"term":"frío","he":"קר"},{"term":"grado","he":"מעלה"},{"term":"grados","he":"מעלות"},{"term":"hacer calor","he":"להיות חם"},{"term":"hacer frío","he":"להיות קר"},{"term":"hacer senderismo","he":"לצאת לטיול רגלי"},{"term":"helado","he":"גלידה"},{"term":"hoy","he":"היום"},{"term":"inestable","he":"לא יציב"},{"term":"invierno","he":"חורף"},{"term":"ir al parque","he":"ללכת לפארק"},{"term":"jueves","he":"יום חמישי"},{"term":"leve ascenso","he":"עלייה קלה"},{"term":"llover","he":"לרדת גשם"},{"term":"lluvia","he":"גשם"},{"term":"lluvioso","he":"גשום"},{"term":"lunes","he":"יום שני"},{"term":"mañana","he":"בוקר / מחר"},{"term":"martes","he":"יום שלישי"},{"term":"máxima","he":"מקסימום"},{"term":"mayormente despejado","he":"בהיר ברובו"},{"term":"menos","he":"מינוס"},{"term":"miércoles","he":"יום רביעי"},{"term":"mínima","he":"מינימום"},{"term":"mirar una película","he":"לראות סרט"},{"term":"montaña","he":"הר"},{"term":"mundo","he":"עולם"},{"term":"nadar","he":"לשחות"},{"term":"nevar","he":"לרדת שלג"},{"term":"nieve","he":"שלג"},{"term":"noventa","he":"תשעים"},{"term":"nublado","he":"מעונן"},{"term":"nueve","he":"תשע"},{"term":"ochenta","he":"שמונים"},{"term":"ocho","he":"שמונה"},{"term":"once","he":"אחת עשרה"},{"term":"otoño","he":"סתיו"},{"term":"país","he":"מדינה / ארץ / מדינה"},{"term":"parcialmente nublado","he":"מעונן חלקית"},{"term":"playa","he":"חוף / חוף ים / חוֹף"},{"term":"preferir","he":"להעדיף"},{"term":"primavera","he":"אביב"},{"term":"pronóstico","he":"תחזית"},{"term":"pronóstico extendido","he":"תחזית לטווח ארוך"},{"term":"quince","he":"חמש עשרה"},{"term":"reportero","he":"כתב"},{"term":"sábado","he":"שבת"},{"term":"seis","he":"שש"},{"term":"senderismo","he":"טיול רגלי"},{"term":"sesenta","he":"שישים"},{"term":"setenta","he":"שבעים"},{"term":"siete","he":"שבע"},{"term":"sol","he":"שמש"},{"term":"soleado","he":"שמשי"},{"term":"temperatura","he":"טמפרטורה"},{"term":"tiempo","he":"זמן / מזג אוויר / זמן לפי ההקשר"},{"term":"tomar helado","he":"לאכול גלידה"},{"term":"tormenta","he":"סערה"},{"term":"tormentas","he":"סערות"},{"term":"trece","he":"שלוש עשרה"},{"term":"treinta","he":"שלושים"},{"term":"treinta y uno","he":"שלושים ואחת"},{"term":"tres","he":"שלוש"},{"term":"uno","he":"אחד / אחת"},{"term":"veinte","he":"עשרים"},{"term":"veinticinco","he":"עשרים וחמש"},{"term":"veinticuatro","he":"עשרים וארבע"},{"term":"veintidós","he":"עשרים ושתיים"},{"term":"veintinueve","he":"עשרים ותשע"},{"term":"veintiocho","he":"עשרים ושמונה"},{"term":"veintiséis","he":"עשרים ושש"},{"term":"veintisiete","he":"עשרים ושבע"},{"term":"veintitrés","he":"עשרים ושלוש"},{"term":"veintiuno","he":"עשרים ואחת"},{"term":"verano","he":"קיץ"},{"term":"viento","he":"רוח"},{"term":"viernes","he":"יום שישי"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/1031678926/the-weather-basic-spanish-flash-cards/?new"}]','published','workbook L1 unit 18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-el-clima-01','es1-el-clima','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"שמשי ___","input":"text"},{"prompt":"מעונן ___","input":"text"},{"prompt":"קור או קר ___","input":"text"},{"prompt":"חום ___","input":"text"}]}','{"items":[{"display":"soleado","answers":["soleado"]},{"display":"nublado","answers":["nublado"]},{"display":"frío","answers":["frío"]},{"display":"calor","answers":["calor"]}],"policy":{"accents":"lenient"}}','published','L1-U18-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-el-clima-02','es1-el-clima','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"Hoy ___ calor.","input":"choice","options":["hace","está"]},{"prompt":"El cielo ___ nublado.","input":"choice","options":["hace","está"]},{"prompt":"___ nubes.","input":"choice","options":["Hay","Es"]},{"prompt":"La temperatura es ___ veinte grados.","input":"choice","options":["de","a"]},{"prompt":"28 → כתבו במילים","input":"text"},{"prompt":"-3 grados → המספר במילים","input":"text"},{"prompt":"___ una tormenta.","input":"choice","options":["Hay","Hace"]},{"prompt":"En invierno ___ frío.","input":"choice","options":["hace","está"]}]}','{"items":[{"display":"hace","choice":0},{"display":"está","choice":1},{"display":"Hay","choice":0},{"display":"de","choice":0},{"display":"veintiocho","answers":["veintiocho"]},{"display":"menos tres grados","answers":["menos tres grados"]},{"display":"Hay","choice":0},{"display":"hace","choice":0}],"policy":{"accents":"strict"}}','published','L1-U18-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-el-clima-03','es1-el-clima','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"Hoy está calor.","input":"sentence"},{"prompt":"El cielo hace nublado.","input":"sentence"},{"prompt":"La temperatura es a veinte grados.","input":"sentence"},{"prompt":"Hace treinta grado.","input":"sentence"}]}','{"items":[{"display":"Hoy hace calor.","answers":["Hoy hace calor."]},{"display":"El cielo está nublado.","answers":["El cielo está nublado."]},{"display":"La temperatura es de veinte grados.","answers":["La temperatura es de veinte grados."]},{"display":"Hace treinta grados.","answers":["Hace treinta grados."]}],"policy":{"accents":"strict"}}','published','L1-U18-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-el-clima-04','es1-el-clima','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"Hace 32 grados. → המספר במילים","input":"sentence"},{"prompt":"Está nublado. → החליפו מעונן בשמשי","input":"sentence"},{"prompt":"Hay nubes. → שלילה","input":"sentence"}]}','{"items":[{"display":"Hace treinta y dos grados.","answers":["Hace treinta y dos grados.","La temperatura es de treinta y dos grados"]},{"display":"Está soleado.","answers":["Está soleado."]},{"display":"No hay nubes.","answers":["No hay nubes."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U18-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-el-clima-05','es1-el-clima','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"היום חם ושמשי.","input":"sentence"},{"prompt":"מעונן ויש עננים.","input":"sentence"},{"prompt":"הטמפרטורה המקסימלית היא שלושים מעלות.","input":"sentence"},{"prompt":"בחורף קר.","input":"sentence"}]}','{"items":[{"display":"Hoy hace calor y está soleado.","answers":["Hoy hace calor y está soleado."]},{"display":"Está nublado y hay nubes.","answers":["Está nublado y hay nubes."]},{"display":"La temperatura máxima es de treinta grados.","answers":["La temperatura máxima es de treinta grados."]},{"display":"En invierno hace frío.","answers":["En invierno hace frío."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U18-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-el-clima-06','es1-el-clima','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿Cuál es la temperatura máxima en la ciudad A?","input":"sentence"},{"prompt":"¿Cuál es la temperatura mínima en la ciudad B?","input":"sentence"},{"prompt":"¿Qué hace Leo?","input":"sentence"}],"text":"Este es un informe de práctica. En la ciudad A hace calor y está soleado.\nLa temperatura máxima es de treinta grados y la mínima es de veinte.\nEn la ciudad B hace frío y está nublado. La máxima es de ocho grados y la mínima es de menos dos.\nEn la ciudad A, Ana va a la playa. En la ciudad B, Leo mira una película en casa."}','{"items":[{"display":"Es de treinta grados.","answers":["Es de treinta grados."]},{"display":"Es de menos dos grados.","answers":["Es de menos dos grados."]},{"display":"Mira una película en casa.","answers":["Mira una película en casa."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U18-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-el-clima-07','es1-el-clima','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Cómo está el clima hoy donde estás?\n¿Cuál es tu estación favorita?\n¿Qué haces cuando hace frío?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U18-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-el-clima-08','es1-el-clima','open','writing','כתיבה','כתבו תחזית דמיונית ל־3 ימים בזמן הווה, שני משפטים לכל יום: מזג אוויר וטמפרטורה, ואז פעילות מתאימה. כתבו מספרים במילים.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["El lunes está soleado y hace veinticinco grados. Voy al parque. El martes hace frío y la temperatura es de diez grados. Leo en casa. El miércoles está nublado y hace dieciocho grados. Camino con mi amiga."],"criteria":""}','published','L1-U18-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-el-clima-09','es1-el-clima','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"22 → כתבו במילים","input":"text"},{"prompt":"Mi casa ___ cerca del parque.","input":"choice","options":["es","está"]}]}','{"items":[{"display":"veintidós","answers":["veintidós"]},{"display":"está","choice":1}],"policy":{"accents":"strict"}}','published','L1-U18-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-el-clima-10','es1-el-clima','open','speaking','אתגר לבחירה','הקליטו דיווח מזג אוויר של 45 שניות לשתי ערים דמיוניות. מסרו לכל עיר מקסימום, מינימום ופעילות מתאימה.','self','{"prompt":"","brief":"","note":"משימה פתוחה לבחירה: אין מפתח. אפשר להביא את הניסוח לשיעור."}','{"models":[],"criteria":""}','published','L1-U18-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-el-clima-11','es1-el-clima','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["montaña","ir al parque","jueves","sábado","ciudad","lluvioso","miércoles","domingo"],"right":[{"id":"A","text":"יום רביעי"},{"id":"B","text":"ללכת לפארק"},{"id":"C","text":"יום חמישי"},{"id":"D","text":"הר"},{"id":"E","text":"יום ראשון"},{"id":"F","text":"גשום"},{"id":"G","text":"שבת"},{"id":"H","text":"עיר"}]}','{"pairs":["D","B","C","G","H","F","A","E"],"policy":{"accents":"lenient"}}','published','L1-U18-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-el-clima-12','es1-el-clima','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"Cuando hay muchas nubes, está ___.","input":"bank"},{"prompt":"La temperatura más alta del día es la ___.","input":"bank"},{"prompt":"La temperatura más baja del día es la ___.","input":"bank"},{"prompt":"En la piscina me gusta ___.","input":"bank"},{"prompt":"En la montaña hacemos ___.","input":"bank"},{"prompt":"Veinte más dos son ___.","input":"bank"}],"wordbank":["máxima","mínima","veintidós","nadar","nublado","senderismo"]}','{"items":[{"display":"nublado","answers":["nublado"]},{"display":"máxima","answers":["máxima"]},{"display":"mínima","answers":["mínima"]},{"display":"nadar","answers":["nadar"]},{"display":"senderismo","answers":["senderismo"]},{"display":"veintidós","answers":["veintidós"]}],"policy":{"accents":"strict"}}','published','L1-U18-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-el-clima-13','es1-el-clima','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"El día es frío.","cue":"רבים","input":"sentence"},{"prompt":"La mañana es soleada.","cue":"רבים","input":"sentence"},{"prompt":"Prefiero el verano.","cue":"ella","input":"sentence"},{"prompt":"Yo nado en la playa.","cue":"nosotros","input":"sentence"}]}','{"items":[{"display":"Los días son fríos.","answers":["Los días son fríos."]},{"display":"Las mañanas son soleadas.","answers":["Las mañanas son soleadas."]},{"display":"Ella prefiere el verano.","answers":["Ella prefiere el verano."]},{"display":"Nosotros nadamos en la playa.","answers":["Nosotros nadamos en la playa."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U18-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-el-clima-14','es1-el-clima','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"Está nublado, pero no llueve."},{"id":"B","text":"Entonces, ¿podemos hacer senderismo?"},{"id":"C","text":"Perfecto. El martes hace calor y vamos a la playa."},{"id":"D","text":"Sí, hace fresco. Llevamos un abrigo."},{"id":"E","text":"¿Qué tiempo hace el lunes?"}]}','{"order":["E","A","B","D","C"],"policy":{"accents":"strict"}}','published','L1-U18-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-el-clima-15','es1-el-clima','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Cuál es la máxima del lunes?","input":"sentence"},{"prompt":"¿Llueve el lunes?","input":"sentence"},{"prompt":"¿Por qué hace senderismo Elena el lunes?","input":"sentence"},{"prompt":"¿Qué hace el martes?","input":"sentence"}],"text":"Elena mira un pronóstico inventado para planificar dos días. El lunes, la máxima es de veintidós grados y la mínima de doce. Está nublado, pero no llueve. Elena hace senderismo porque prefiere caminar cuando hace fresco. El martes, la máxima es de treinta grados. Hace calor y Elena va a la playa para nadar."}','{"items":[{"display":"Veintidós grados.","answers":["Veintidós grados."]},{"display":"No.","answers":["No."]},{"display":"Porque prefiere caminar cuando hace fresco.","answers":["Porque prefiere caminar cuando hace fresco."]},{"display":"Va a la playa para nadar.","answers":["Va a la playa para nadar."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U18-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-el-clima-16','es1-el-clima','open','writing','כותבים לחיים','המציאו תחזית ליומיים. כתבו טמפרטורת מינימום ומקסימום לכל יום במילים, תארו את מזג האוויר והתאימו פעילות לכל יום.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["El lunes está nublado y hace fresco. La temperatura máxima es de veintidós grados y la mínima es de doce. Hago senderismo en la montaña porque no llueve. El martes hace calor y está soleado. La máxima es de treinta grados y la mínima es de veinte. Voy a la playa para nadar y tomar un helado."],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U18-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es1-como-relajarse','es-1','es-1-leisure','איך נרגעים','Cómo relajarse','לתאר פעולות אישיות ותחושות באמצעות משפטי תיאור.','workbook','[{"he":"פעלים חוזרים","target":"sentirse · relajarse"},{"he":"תיאור","target":"ser + תואר"}]','["פעלים חוזרים","תיאור"]','{"rules":["ב־relajarse וב־sentirse הכינוי משתנה לפי הגוף: me siento · te sientes · se siente · nos sentimos · se sienten.","תיאור תחושה מתאים לאדם ומשתנה במין ובמספר; תיאור של אווירה או מוזיקה משתמש ב־ser.","שימו לב: me siento הוא גם אני מרגיש וגם אני יושב. ההקשר קובע."],"examples":["Me relajo en casa. Ella se relaja en el parque.","Me siento cansado (sentirse). Me siento en una silla (sentarse).","La música es relajante. Las sillas son cómodas."],"tips":["התואר מתאים למי שמרגיש: גבר אומר me siento cansado ואישה אומרת me siento cansada."],"mistakes":[{"text":"בעברית \"אני נרגע\" היא מילה אחת ולכן הכינוי נופל. בספרדית הוא חובה ומשתנה עם הגוף. ושימו לב לזוג: sentirse = מרגיש, sentarse = יושב.","pairs":[{"bad":"Yo relajo en casa","good":"Yo me relajo en casa"},{"bad":"Nosotros se sentimos","good":"Nosotros nos sentimos"}]}]}','[{"term":"acostarse","he":"ללכת לישון / לשכב / ללכת לישון"},{"term":"agua","he":"מים / מַיִם"},{"term":"ambiente","he":"סְבִיבָה"},{"term":"bañarse","he":"להתרחץ"},{"term":"beber","he":"לשתות / לִשְׁתּוֹת"},{"term":"bien","he":"היטב"},{"term":"café","he":"בית קפה / קפה / קפה / קָפֶה"},{"term":"calmante","he":"מרגיע"},{"term":"cama","he":"מיטה / מִטָּה"},{"term":"caminar","he":"ללכת / לָלֶכֶת"},{"term":"cansado","he":"עייף"},{"term":"cansado/a","he":"עָיֵף / עֲיֵפָה"},{"term":"casa","he":"בית פיזי / בית / בַּיִת"},{"term":"chocolate","he":"שוקולד / שׁוֹקוֹלָד"},{"term":"comer","he":"לאכול / לֶאֱכוֹל"},{"term":"cómodo","he":"נוח"},{"term":"cómodo/a","he":"נוח / נוֹחַ / נוֹחָה"},{"term":"concentrarse","he":"להתרכז"},{"term":"cuerpo","he":"גּוּף"},{"term":"descansar","he":"לנוח / לָנוּחַ"},{"term":"despacio","he":"לאט"},{"term":"despertarse","he":"להתעורר"},{"term":"después del trabajo","he":"אחרי העבודה"},{"term":"domingo","he":"יום ראשון / רִאשׁוֹן (יוֹם)"},{"term":"dormir","he":"לישון / לִישׁוֹן"},{"term":"ducharse","he":"להתקלח"},{"term":"energético/a","he":"אנרגטי; לתיאור אדם נפוץ גם enérgico/a"},{"term":"enérgico/a","he":"נמרץ / מלא אנרגיה"},{"term":"enojado/a","he":"כּוֹעֵס / כּוֹעֶסֶת"},{"term":"escuchar","he":"להקשיב / להאזין"},{"term":"estirarse","he":"להתמתח"},{"term":"estresado","he":"לחוץ"},{"term":"estresado/a","he":"לָחוּץ / לְחוּצָה"},{"term":"examen","he":"מִבְחָן"},{"term":"feliz","he":"שָׂמֵחַ / שְׂמֵחָה"},{"term":"gusto","he":"טעם"},{"term":"hablar","he":"לדבר"},{"term":"hamaca","he":"ערסל"},{"term":"hambre","he":"רעב"},{"term":"hambriento/a","he":"רָעֵב / רְעֵבָה"},{"term":"helado","he":"גלידה"},{"term":"juego","he":"משחק / מִשְׂחָק"},{"term":"leer","he":"לקרוא"},{"term":"levantarse","he":"לקום"},{"term":"libro","he":"ספר / סֵפֶר"},{"term":"mal","he":"רע"},{"term":"mano","he":"יד"},{"term":"manzana","he":"תפוח"},{"term":"manzanilla","he":"קמומיל"},{"term":"meditación","he":"מֶדִיטַצְיָה"},{"term":"meditar","he":"לעשות מדיטציה"},{"term":"mucho","he":"הרבה"},{"term":"música","he":"מוזיקה / מוּזִיקָה"},{"term":"naturaleza","he":"טבע"},{"term":"nervioso/a","he":"עַצְבָּנִי / עַצְבָּנִית"},{"term":"oído","he":"שמיעה"},{"term":"oír","he":"לשמוע"},{"term":"oler","he":"לְהָרִיחַ"},{"term":"olfato","he":"ריח"},{"term":"parque","he":"פארק / פָּארְק"},{"term":"película","he":"סרט / סֶרֶט"},{"term":"playa","he":"חוף / חוף ים / חוֹף"},{"term":"prueba","he":"מבחן"},{"term":"recibir","he":"לקבל"},{"term":"regalo","he":"מַתָּנָה"},{"term":"relajado","he":"רגוע"},{"term":"relajado/a","he":"רָגוּעַ / רְגוּעָה"},{"term":"relajarse","he":"להירגע"},{"term":"respiración","he":"נשימה"},{"term":"respirar","he":"לנשום"},{"term":"sed","he":"צמא"},{"term":"sentarse","he":"להתיישב"},{"term":"sentidos","he":"חוּשִׁים"},{"term":"sentir","he":"לחוש"},{"term":"sentir (me siento)","he":"להרגיש; בצורה me siento הפועל הוא sentirse"},{"term":"sentirse","he":"להרגיש"},{"term":"silencioso","he":"שקט"},{"term":"silla","he":"כיסא / כִּסֵּא"},{"term":"suave","he":"רך / עדין / רך"},{"term":"tacto","he":"מישוש"},{"term":"té","he":"תֵּה"},{"term":"temprano","he":"מוקדם"},{"term":"tener hambre","he":"להיות רעב"},{"term":"tener sed","he":"להיות צמא"},{"term":"tocar","he":"לגעת/לנגן / לנגן / לָגַעַת"},{"term":"traje de baño","he":"בגד ים"},{"term":"tranquilo","he":"רגוע / שקט / רגוע / שקט או רגוע"},{"term":"tranquilo/a","he":"שָׁקֵט / שְׁקֵטָה"},{"term":"ventana","he":"חלון"},{"term":"ver / mirar","he":"לִרְאוֹת"},{"term":"vista","he":"ראייה"}]','["תרגלתי את רשימת המילים וסימנתי מילים לחזרה נוספת.","אני משתמש או משתמשת בשני מוקדי השיעור במשפטים שלמים.","תיקנתי את הטעויות שלי מול המשוב."]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/856287205/basic-spanish-como-relajarse-actualizado-flash-cards/?new="}]','published','workbook L1 unit 19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-como-relajarse-01','es1-como-relajarse','recall','vocab','שליפת מילים מהזיכרון','כתבו בספרדית את המילה המתאימה לכל מילה בעברית, בלי להציץ.','auto','{"items":[{"prompt":"רגוע ___","input":"text"},{"prompt":"לחוץ ___","input":"text"},{"prompt":"עייף ___","input":"text"},{"prompt":"שקט או רגוע ___","input":"text"}]}','{"items":[{"display":"relajado","answers":["relajado"]},{"display":"estresado","answers":["estresado"]},{"display":"cansado","answers":["cansado"]},{"display":"tranquilo","answers":["tranquilo"]}],"policy":{"accents":"lenient"}}','published','L1-U19-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-como-relajarse-02','es1-como-relajarse','gap','grammar','דקדוק בפעולה','השלימו. כשמופיע שם פועל, הטו אותו בהווה; כשמופיעות אפשרויות, בחרו את המתאימה.','auto','{"items":[{"prompt":"Yo ___ relajo en casa.","input":"choice","options":["me","se"]},{"prompt":"Ana se ___ cansada.","input":"choice","options":["siento","siente"]},{"prompt":"Nosotros ___ sentimos tranquilos.","input":"choice","options":["nos","se"]},{"prompt":"Las sillas son ___.","input":"choice","options":["cómoda","cómodas"]},{"prompt":"La música ___ tranquila.","input":"choice","options":["es","son"]},{"prompt":"Ellos ___ relajan por la noche.","input":"choice","options":["nos","se"]},{"prompt":"Después del trabajo, Eva se ___ cansada.","input":"choice","options":["siente","sienta"]},{"prompt":"Ella se ___ en una silla cómoda y lee.","input":"choice","options":["siente","sienta"]}]}','{"items":[{"display":"me","choice":0},{"display":"siente","choice":1},{"display":"nos","choice":0},{"display":"cómodas","choice":1},{"display":"es","choice":0},{"display":"se","choice":1},{"display":"siente","choice":0},{"display":"sienta","choice":1}],"policy":{"accents":"strict"}}','published','L1-U19-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-como-relajarse-03','es1-como-relajarse','correction','grammar','מצאו ותקנו את הטעות','בכל משפט יש טעות אחת. כתבו את המשפט המתוקן במלואו.','auto','{"items":[{"prompt":"Yo relajo en casa por la noche.","input":"sentence"},{"prompt":"Nosotros se sentimos tranquilos.","input":"sentence"},{"prompt":"Las sillas son cómoda.","input":"sentence"},{"prompt":"La música son tranquila.","input":"sentence"}]}','{"items":[{"display":"Yo me relajo en casa por la noche.","answers":["Yo me relajo en casa por la noche."]},{"display":"Nosotros nos sentimos tranquilos.","answers":["Nosotros nos sentimos tranquilos."]},{"display":"Las sillas son cómodas.","answers":["Las sillas son cómodas."]},{"display":"La música es tranquila.","answers":["La música es tranquila."]}],"policy":{"accents":"strict"}}','published','L1-U19-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-como-relajarse-04','es1-como-relajarse','transform','grammar','תרגול מבוקר','סדרו או שנו את המשפט לפי ההנחיה. שמרו על המשמעות, מלבד השינוי שהתבקש, ושנו גם כינויי שייכות אם צריך.','auto','{"items":[{"prompt":"Yo me relajo en el parque. → Ella…","input":"sentence"},{"prompt":"Me siento tranquilo. → Nosotros…","input":"sentence"},{"prompt":"La silla es cómoda. → רבים","input":"sentence"}]}','{"items":[{"display":"Ella se relaja en el parque.","answers":["Ella se relaja en el parque."]},{"display":"Nosotros nos sentimos tranquilos.","answers":["Nosotros nos sentimos tranquilos."]},{"display":"Las sillas son cómodas.","answers":["Las sillas son cómodas."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U19-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-como-relajarse-05','es1-como-relajarse','translate','production','מעברית לספרדית','כתבו את המשפט בספרדית. אין אפשרויות בחירה: זה התרגיל שבודק מה באמת נשאר.','auto','{"items":[{"prompt":"אני נרגע בבית.","input":"sentence"},{"prompt":"אנחנו מרגישים רגועים.","input":"sentence"},{"prompt":"המוזיקה מרגיעה.","input":"sentence"},{"prompt":"היא מרגישה עייפה אחרי העבודה.","input":"sentence"}]}','{"items":[{"display":"Me relajo en casa.","answers":["Me relajo en casa."]},{"display":"Nos sentimos tranquilos.","answers":["Nos sentimos tranquilos."]},{"display":"La música es relajante.","answers":["La música es relajante."]},{"display":"Ella se siente cansada después del trabajo.","answers":["Ella se siente cansada después del trabajo."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U19-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-como-relajarse-06','es1-como-relajarse','reading','reading','קריאה','קראו את הטקסט וענו בספרדית על השאלות.','auto','{"items":[{"prompt":"¿Cómo se siente Eva después del trabajo?","input":"sentence"},{"prompt":"¿Qué bebe Eva?","input":"sentence"},{"prompt":"¿Cómo se relaja su hermano?","input":"sentence"}],"text":"Los viernes Eva se siente cansada después del trabajo.\nPara relajarse, se sienta en una silla cómoda y escucha música. Su casa es tranquila.\nBebe té y lee un libro. Su hermano se relaja de otra forma: camina por el parque.\nLos domingos los dos se sienten contentos y descansan en casa."}','{"items":[{"display":"Se siente cansada.","answers":["Se siente cansada."]},{"display":"Bebe té.","answers":["Bebe té."]},{"display":"Camina por el parque.","answers":["Camina por el parque."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U19-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-como-relajarse-07','es1-como-relajarse','open','speaking','עכשיו אתם','ענו במשפטים מלאים. אחר כך אמרו את התשובות בקול בלי לקרוא. אפשר להשתמש בפרטים דמיוניים.','self','{"prompt":"¿Cuándo te sientes relajado o relajada?\n¿Qué haces para descansar?\n¿Cómo es tu lugar favorito para relajarte?","brief":"","note":"משימה אישית: אין תשובה אחת נכונה. בדקו את עצמכם לפי ההנחיה."}','{"models":[],"criteria":""}','published','L1-U19-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-como-relajarse-08','es1-como-relajarse','open','writing','כתיבה','כתבו שגרת רגיעה של 6 משפטים: מתי, איפה, שני פעלים עם כינוי חוזר, תיאור הסביבה ותחושה. השתמשו בהווה בלבד.
לפני הכתיבה בחרו ארבע מילים מהנושא. בסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Los viernes me siento cansada. Me relajo en casa por la noche. Mi sala de estar es tranquila. Descanso en una silla cómoda. Escucho música y bebo té. Después me siento relajada."],"criteria":""}','published','L1-U19-E8',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-como-relajarse-09','es1-como-relajarse','gap','grammar','חזרה משולבת','השלימו או בחרו את הצורה הנכונה. התרגיל חוזר על מבנים מנושאים אחרים ברמה.','auto','{"items":[{"prompt":"Ella ___ ducha por la mañana.","input":"choice","options":["me","se"]},{"prompt":"Los cuadros ___ bonitos.","input":"choice","options":["es","son"]}]}','{"items":[{"display":"se","choice":1},{"display":"son","choice":1}],"policy":{"accents":"strict"}}','published','L1-U19-E9',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-como-relajarse-10','es1-como-relajarse','open','speaking','אתגר לבחירה','שלבו שני נושאים קודמים: תארו יום רגוע עם מזג אוויר, אוכל או מוזיקה. כתבו 4 משפטים חדשים בלי להעתיק מהתרגילים.','self','{"prompt":"","brief":"","note":"משימה פתוחה לבחירה: אין מפתח. אפשר להביא את הניסוח לשיעור."}','{"models":[],"criteria":""}','published','L1-U19-E10',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-como-relajarse-11','es1-como-relajarse','match','vocab','מחברים מילה למשמעות','התאימו כל מילה בספרדית לפירושה בעברית. כתבו את האות המתאימה. כל אפשרות משמשת פעם אחת.','auto','{"left":["cansado/a","tranquilo/a","cuerpo","hambriento/a","domingo","sentidos","libro","casa"],"right":[{"id":"A","text":"בַּיִת"},{"id":"B","text":"שָׁקֵט / שְׁקֵטָה"},{"id":"C","text":"גּוּף"},{"id":"D","text":"חוּשִׁים"},{"id":"E","text":"עָיֵף / עֲיֵפָה"},{"id":"F","text":"סֵפֶר"},{"id":"G","text":"רִאשׁוֹן (יוֹם)"},{"id":"H","text":"רָעֵב / רְעֵבָה"}]}','{"pairs":["E","B","C","H","G","D","F","A"],"policy":{"accents":"lenient"}}','published','L1-U19-E11',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-como-relajarse-12','es1-como-relajarse','bank','vocab','אוצר מילים בהקשר','השלימו מתוך המחסן. השתמשו בכל מילה פעם אחת, בלי לשנות את צורתה.','auto','{"items":[{"prompt":"Después de trabajar muchas horas me siento ___.","input":"bank"},{"prompt":"Antes de dormir bebo té de ___.","input":"bank"},{"prompt":"Cuando tengo hambre, ___.","input":"bank"},{"prompt":"Cuando tengo sed, ___ agua.","input":"bank"},{"prompt":"Por la noche me ___ en una silla para leer.","input":"bank"},{"prompt":"En el jardín descanso en una ___.","input":"bank"}],"wordbank":["cansado","manzanilla","como","siento","bebo","hamaca"]}','{"items":[{"display":"cansado","answers":["cansado"]},{"display":"manzanilla","answers":["manzanilla"]},{"display":"como","answers":["como"]},{"display":"bebo","answers":["bebo"]},{"display":"siento","answers":["siento"]},{"display":"hamaca","answers":["hamaca"]}],"policy":{"accents":"strict"}}','published','L1-U19-E12',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-como-relajarse-13','es1-como-relajarse','transform','grammar','משנים ומדייקים','כתבו את המשפט מחדש לפי הגוף או השינוי המצוין. שנו גם פעלים, תארים וכינויי שייכות לפי הצורך.','auto','{"items":[{"prompt":"Me siento relajado.","cue":"ella","input":"sentence"},{"prompt":"Me siento en la silla.","cue":"ellos","input":"sentence"},{"prompt":"Nos estiramos por la mañana.","cue":"yo","input":"sentence"},{"prompt":"Tú te acuestas temprano.","cue":"nosotros","input":"sentence"}]}','{"items":[{"display":"Ella se siente relajada.","answers":["Ella se siente relajada."]},{"display":"Ellos se sientan en la silla.","answers":["Ellos se sientan en la silla."]},{"display":"Me estiro por la mañana.","answers":["Me estiro por la mañana."]},{"display":"Nos acostamos temprano.","answers":["Nos acostamos temprano."]}],"policy":{"accents":"strict","optionalLeading":["yo","tú","él","ella","usted","nosotros","nosotras","vosotros","vosotras","ellos","ellas","ustedes"]}}','published','L1-U19-E13',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-como-relajarse-14','es1-como-relajarse','order','communication','בונים שיחה','סדרו את השורות לשיחה הגיונית, ואחר כך קראו אותה בקול.','auto','{"lines":[{"id":"A","text":"¿También lees antes de dormir?"},{"id":"B","text":"Bebo té de manzanilla y escucho música tranquila."},{"id":"C","text":"¿Qué haces para relajarte?"},{"id":"D","text":"Me siento cansada después del trabajo."},{"id":"E","text":"Sí, me siento junto a la ventana y leo un libro."}]}','{"order":["D","C","B","A","E"],"policy":{"accents":"strict"}}','published','L1-U19-E14',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-como-relajarse-15','es1-como-relajarse','reading','reading','קוראים ומבינים','קראו וענו בספרדית. אפשר להיעזר באוצר המילים. לאחר מכן סמנו בטקסט את המשפט שתומך בכל תשובה.','auto','{"items":[{"prompt":"¿Cómo se siente Irene después del trabajo?","input":"sentence"},{"prompt":"¿Qué bebe?","input":"sentence"},{"prompt":"¿Qué prefiere hacer su hermano?","input":"sentence"},{"prompt":"¿Dónde descansa Irene los domingos?","input":"sentence"}],"text":"Después del trabajo, Irene se siente cansada. Se sienta en una silla junto a la ventana, bebe té de manzanilla y escucha música tranquila. Respira despacio y lee un libro. Su hermano prefiere estirarse y caminar por el parque. Los domingos Irene descansa en una hamaca. El ambiente es silencioso y ella se siente relajada."}','{"items":[{"display":"Cansada.","answers":["Cansada."]},{"display":"Té de manzanilla.","answers":["Té de manzanilla."]},{"display":"Estirarse y caminar por el parque.","answers":["Estirarse y caminar por el parque."]},{"display":"En una hamaca.","answers":["En una hamaca."]}],"policy":{"accents":"lenient","match":"content"}}','published','L1-U19-E15',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es1-como-relajarse-16','es1-como-relajarse','open','writing','כותבים לחיים','תארו ערב רגוע. שלבו שלושה פעלים חוזרים, שלוש פעולות נוספות, שני חפצים ושני תיאורים של מצב או תחושה.
כתבו 6 עד 8 משפטים והשתמשו בלפחות שמונה מילים או ביטויים מאוצר המילים של הנושא. אפשר להמציא פרטים. לפני הכתיבה בחרו מילים, ובסיום הקיפו אותן ובדקו את הפעלים.','self','{"prompt":"","brief":""}','{"models":["Después del trabajo me siento cansado y necesito descansar. Me siento en una silla cómoda junto a la ventana. Bebo té de manzanilla y escucho música tranquila. Después leo un libro y respiro despacio. Me estiro y me acuesto temprano. Al final de la noche me siento relajado."],"criteria":"בדקו: 6 עד 8 משפטים; לפחות שמונה מילים או ביטויים מהנושא; כל הפרטים שהתבקשו; התאמת גוף, מין ומספר. דוגמה אפשרית בלבד, לא תשובה יחידה."}','published','L1-U19-E16',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO levels (id,language_id,number,name_he,name_target,cefr,description,status,challenge_enabled,rubric,created_at,updated_at) VALUES ('es-2','es',2,'ספרדית רמה 2','Español · Nivel 2 · Intermedio','A2','הרחבת השיחה והביטחון: עבר, עתיד, חוויות ותיאור מצבים יומיומיים.','published',1,'[["קריטריון","עדיין לא","כמעט","הושלם"],["התאמה למשימה","חלק מן הפרטים חסרים","רוב הפרטים קיימים","כל הפרטים והרחבה"],["אוצר מילים","פחות מן הכמות שנדרשה","הכמות קיימת עם חזרות","מגוון מדויק ובהקשר"],["דקדוק","השגיאות מקשות","המסר ברור למרות שגיאות","שליטה טובה ותיקון עצמי"],["מבנה ובהירות","הרעיונות אינם מסודרים","יש רצף בסיסי","פתיחה, פיתוח וסיום ברורים"]]',1788220800000,1788220800000);
