INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas','es-2','es-2-memories','חוויות מן העבר','Experiencias pasadas','לדבר ולכתוב על הנושא „חוויות מן העבר“ בספרדית, תוך שימוש במבנים: Pretérito indefinido, pretérito perfecto e imperfecto.','derived','[{"he":"דקדוק בשימוש","target":"Pretérito indefinido, pretérito perfecto e imperfecto"},{"he":"אוצר מילים: חוויות מן העבר","target":"Experiencias pasadas"}]','["Pretérito indefinido, pretérito perfecto e imperfecto"]','{"rules":[],"examples":["Ayer fui al museo.","Cuando era niño jugaba cada día.","Nunca he comido sushi.","¿Qué hacías normalmente cuando eras niño?"],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Aprendí / Aprendiste / Aprendió (aprender)","he":"למד / למדת / למדתי"},{"term":"Bailé / Bailaste / Bailó (bailar)","he":"רקד / רקדת / רקדתי"},{"term":"Biblioteca","he":"ספרייה"},{"term":"Caminé / Caminaste / Caminó (caminar)","he":"הלך / הלכת / הלכתי"},{"term":"Campo","he":"שדה / כפר"},{"term":"Canción","he":"שיר"},{"term":"Canté / Cantaste / Cantó (cantar)","he":"שר / שרת / שרתי"},{"term":"Clase","he":"שיעור"},{"term":"Corrí / Corriste / Corrió (correr)","he":"רץ / רצת / רצתי"},{"term":"Deporte","he":"ספורט"},{"term":"Descansé / Descansaste / Descansó (descansar)","he":"נח / נח / נחתי"},{"term":"Dormí / Dormiste / Durmió (dormir)","he":"ישן / ישנת / ישנתי"},{"term":"El otro día","he":"ביום האחר"},{"term":"El verano pasado","he":"בקיץ שעבר"},{"term":"En 2010","he":"בשנת 2010"},{"term":"En aquella época","he":"באותה תקופה"},{"term":"En mi infancia","he":"בילדותי"},{"term":"Enseñé / Enseñaste / Enseñó (enseñar)","he":"לימד / לימדת / לימדתי"},{"term":"Esperé / Esperaste / Esperó (esperar)","he":"חיכה / חיכית / חיכיתי"},{"term":"Examen","he":"מבחן"},{"term":"Fiesta","he":"מסיבה"},{"term":"Hace un mes","he":"לפני חודש"},{"term":"Hace una semana","he":"לפני שבוע"},{"term":"Historia","he":"סיפור / היסטוריה / סיפור"},{"term":"Hotel","he":"מלון"},{"term":"Montaña","he":"הר"},{"term":"Museo","he":"מוזיאון"},{"term":"Por la mañana","he":"בבוקר"},{"term":"Recuerdo","he":"זיכרון / מזכרת"},{"term":"Reí / Reíste / Rió (reír)","he":"צחק / צחקת / צחקתי"},{"term":"Salí / Saliste / Salió (salir)","he":"יצא / יצאת / יצאתי"},{"term":"Soñé / Soñaste / Soñó (soñar)","he":"חלם / חלמת / חלמתי"},{"term":"Tomé / Tomaste / Tomó (tomar)","he":"לקח / לקחת / לקחתי"},{"term":"Visité / Visitaste / Visitó (visitar)","he":"ביקר / ביקרת / ביקרתי"},{"term":"Volví / Volviste / Volvió (volver)","he":"חזר / חזרת / חזרתי"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1069755691/experiencias-pasadas-actualizado-flash-cards/"}]','published','workbook L2 unit 01',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas-01','es2-experiencias-pasadas','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"חיכה / חיכית / חיכיתי ___","input":"text"},{"prompt":"רץ / רצת / רצתי ___","input":"text"},{"prompt":"בבוקר ___","input":"text"},{"prompt":"ישן / ישנת / ישנתי ___","input":"text"},{"prompt":"זיכרון ___","input":"text"},{"prompt":"לפני שבוע ___","input":"text"}]}','{"items":[{"display":"Esperé / Esperaste / Esperó (esperar)","answers":["Esperé / Esperaste / Esperó (esperar)","Esperé / Esperaste / Esperó","Esperé","Esperaste","Esperó"]},{"display":"Corrí / Corriste / Corrió (correr)","answers":["Corrí / Corriste / Corrió (correr)","Corrí / Corriste / Corrió","Corrí","Corriste","Corrió"]},{"display":"Por la mañana","answers":["Por la mañana"]},{"display":"Dormí / Dormiste / Durmió (dormir)","answers":["Dormí / Dormiste / Durmió (dormir)","Dormí / Dormiste / Durmió","Dormí","Dormiste","Durmió"]},{"display":"Recuerdo","answers":["Recuerdo"]},{"display":"Hace una semana","answers":["Hace una semana"]}],"policy":{"accents":"lenient"}}','published','L2-U01-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas-02','es2-experiencias-pasadas','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Esperé / Esperaste / Esperó (esperar)","Corrí / Corriste / Corrió (correr)","Por la mañana","Dormí / Dormiste / Durmió (dormir)","Recuerdo","Hace una semana","Volví / Volviste / Volvió (volver)","Montaña"],"right":[{"id":"A","text":"חזר / חזרת / חזרתי"},{"id":"B","text":"ישן / ישנת / ישנתי"},{"id":"C","text":"זיכרון"},{"id":"D","text":"בבוקר"},{"id":"E","text":"לפני שבוע"},{"id":"F","text":"הר"},{"id":"G","text":"חיכה / חיכית / חיכיתי"},{"id":"H","text":"רץ / רצת / רצתי"}]}','{"pairs":["G","H","D","B","C","E","A","F"],"policy":{"accents":"lenient"}}','published','L2-U01-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas-03','es2-experiencias-pasadas','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"חיכה / חיכית / חיכיתי","input":"choice","options":["Esperé / Esperaste / Esperó (esperar)","Reí / Reíste / Rió (reír)","Fiesta"]},{"prompt":"רץ / רצת / רצתי","input":"choice","options":["Hace un mes","Corrí / Corriste / Corrió (correr)","Fiesta"]},{"prompt":"בבוקר","input":"choice","options":["Descansé / Descansaste / Descansó (descansar)","Por la mañana","Caminé / Caminaste / Caminó (caminar)"]},{"prompt":"ישן / ישנת / ישנתי","input":"choice","options":["Aprendí / Aprendiste / Aprendió (aprender)","El verano pasado","Dormí / Dormiste / Durmió (dormir)"]},{"prompt":"זיכרון","input":"choice","options":["Recuerdo","Hotel","En 2010"]},{"prompt":"לפני שבוע","input":"choice","options":["Clase","Museo","Hace una semana"]}]}','{"items":[{"display":"Esperé / Esperaste / Esperó (esperar)","choice":0},{"display":"Corrí / Corriste / Corrió (correr)","choice":1},{"display":"Por la mañana","choice":1},{"display":"Dormí / Dormiste / Durmió (dormir)","choice":2},{"display":"Recuerdo","choice":0},{"display":"Hace una semana","choice":2}],"policy":{"accents":"lenient"}}','published','L2-U01-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas-04','es2-experiencias-pasadas','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"נח / נח / נחתי = ___","input":"bank"},{"prompt":"בשנת 2010 = ___","input":"bank"}],"wordbank":["Descansé / Descansaste / Descansó (descansar)","historia","museo","En 2010","salió","visitó"],"text":"El sábado pasado, Clara {{1}} temprano, {{2}} un {{3}} y después cenó con sus amigos. Cuando caminaba hacia el restaurante, empezó a llover. Aun así, llegó a tiempo y contó una {{4}} divertida de su infancia."}','{"items":[{"display":"salió","answers":["salió"]},{"display":"visitó","answers":["visitó"]},{"display":"museo","answers":["museo"]},{"display":"historia","answers":["historia"]},{"display":"Descansé / Descansaste / Descansó (descansar)","answers":["Descansé / Descansaste / Descansó (descansar)","Descansé / Descansaste / Descansó"]},{"display":"En 2010","answers":["En 2010"]}],"policy":{"accents":"strict"}}','published','L2-U01-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas-05','es2-experiencias-pasadas','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["pasado","Qué","semana","hiciste","fin","el","de"]},{"prompt":"","input":"tokens","tokens":["ayer","despertaste","te","hora","qué","A"]},{"prompt":"","input":"tokens","tokens":["tu","comiste","Qué","última","comida","en"]},{"prompt":"","input":"tokens","tokens":["visitaste","pasado","mes","el","lugares","Qué"]}]}','{"items":[{"display":"¿Qué hiciste el fin de semana pasado?","answers":["¿Qué hiciste el fin de semana pasado?"]},{"display":"¿A qué hora te despertaste ayer?","answers":["¿A qué hora te despertaste ayer?"]},{"display":"¿Qué comiste en tu última comida?","answers":["¿Qué comiste en tu última comida?"]},{"display":"¿Qué lugares visitaste el mes pasado?","answers":["¿Qué lugares visitaste el mes pasado?"]}],"policy":{"accents":"strict"}}','published','L2-U01-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas-06','es2-experiencias-pasadas','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Ayer iba al museo una vez.","input":"sentence"},{"prompt":"Cuando era niño jugué cada día.","input":"sentence"},{"prompt":"Nunca he comí sushi.","input":"sentence"},{"prompt":"¿Qué hiciste cuando eras niño normalmente?","input":"sentence"}]}','{"items":[{"display":"Ayer fui al museo.","answers":["Ayer fui al museo."]},{"display":"Cuando era niño jugaba cada día.","answers":["Cuando era niño jugaba cada día."]},{"display":"Nunca he comido sushi.","answers":["Nunca he comido sushi."]},{"display":"¿Qué hacías normalmente cuando eras niño?","answers":["¿Qué hacías normalmente cuando eras niño?"]}],"policy":{"accents":"strict"}}','published','L2-U01-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas-07','es2-experiencias-pasadas','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Ayer iba al museo una vez.","Ayer fui al museo."]},{"prompt":"","input":"choice","options":["Cuando era niño jugaba cada día.","Cuando era niño jugué cada día."]},{"prompt":"","input":"choice","options":["Nunca he comí sushi.","Nunca he comido sushi."]},{"prompt":"","input":"choice","options":["¿Qué hacías normalmente cuando eras niño?","¿Qué hiciste cuando eras niño normalmente?"]}]}','{"items":[{"display":"Ayer fui al museo.","choice":1},{"display":"Cuando era niño jugué cada día.","choice":1},{"display":"Nunca he comido sushi.","choice":1},{"display":"¿Qué hiciste cuando eras niño normalmente?","choice":1}],"policy":{"accents":"strict"}}','published','L2-U01-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas-08','es2-experiencias-pasadas','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**yo** · visitar · ayer","input":"text"},{"prompt":"**Clara** · salir · el sábado pasado","input":"text"},{"prompt":"**nosotros** · comer · esta semana","input":"text"},{"prompt":"**tú** · viajar · nunca","input":"text"}]}','{"items":[{"display":"visité","answers":["visité"]},{"display":"salió","answers":["salió"]},{"display":"hemos comido","answers":["hemos comido"]},{"display":"has viajado","answers":["has viajado"]}],"policy":{"accents":"strict"}}','published','L2-U01-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas-09','es2-experiencias-pasadas','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Qué hiciste el fin de semana pasado?\n¿A qué hora te despertaste ayer?\n¿Qué comiste en tu última comida?\n¿Qué lugares visitaste el mes pasado?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U01-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas-10','es2-experiencias-pasadas','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**yo** · visitar · ayer","input":"text"},{"prompt":"**Clara** · salir · el sábado pasado","input":"text"},{"prompt":"**nosotros** · comer · esta semana","input":"text"},{"prompt":"**tú** · viajar · nunca","input":"text"},{"prompt":"**yo** · jugar · cuando era niño","input":"text"},{"prompt":"**ellos** · vivir · antes","input":"text"},{"prompt":"**usted** · hacer · ayer","input":"text"},{"prompt":"**nosotras** · ver · anoche","input":"text"}]}','{"items":[{"display":"visité","answers":["visité"]},{"display":"salió","answers":["salió"]},{"display":"hemos comido","answers":["hemos comido"]},{"display":"has viajado","answers":["has viajado"]},{"display":"jugaba","answers":["jugaba"]},{"display":"vivían","answers":["vivían"]},{"display":"hizo","answers":["hizo"]},{"display":"vimos","answers":["vimos"]}],"policy":{"accents":"strict"}}','published','L2-U01-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas-11','es2-experiencias-pasadas','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué hizo Clara primero?","input":"sentence"},{"prompt":"¿Qué ocurrió mientras caminaba?","input":"sentence"},{"prompt":"¿Qué contó durante la cena?","input":"sentence"}],"text":"El sábado pasado, Clara salió temprano, visitó un museo y después cenó con sus amigos. Cuando caminaba hacia el restaurante, empezó a llover. Aun así, llegó a tiempo y contó una historia divertida de su infancia."}','{"items":[{"display":"Salió temprano y visitó un museo.","answers":["Salió temprano y visitó un museo."]},{"display":"Empezó a llover.","answers":["Empezó a llover."]},{"display":"Una historia divertida de su infancia.","answers":["Una historia divertida de su infancia."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U01-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas-12','es2-experiencias-pasadas','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Experiencias pasadas\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["El sábado pasado, Clara salió temprano, visitó un museo y después cenó con sus amigos. Cuando caminaba hacia el restaurante, empezó a llover. Aun así, llegó a tiempo y contó una historia divertida de su infancia."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U01-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas-13','es2-experiencias-pasadas','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Qué hizo Clara primero?"},{"id":"B","text":"Respuesta: Empezó a llover."},{"id":"C","text":"Pregunta: ¿Qué ocurrió mientras caminaba?"},{"id":"D","text":"Respuesta: Salió temprano y visitó un museo."},{"id":"E","text":"Respuesta: Una historia divertida de su infancia."},{"id":"F","text":"Pregunta: ¿Qué contó durante la cena?"}]}','{"order":["A","D","C","B","F","E"],"policy":{"accents":"strict"}}','published','L2-U01-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas-14','es2-experiencias-pasadas','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Cuando caminaba hacia el restaurante, empezó a llover."},{"id":"B","text":"Aun así, llegó a tiempo y contó una historia divertida de su infancia."},{"id":"C","text":"El sábado pasado, Clara salió temprano, visitó un museo y después cenó con sus amigos."}]}','{"order":["C","A","B"],"policy":{"accents":"strict"}}','published','L2-U01-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas-15','es2-experiencias-pasadas','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre experiencias pasadas es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre experiencias pasadas es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U01-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas-16','es2-experiencias-pasadas','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"בבוקר = ___","input":"text"},{"prompt":"ישן / ישנת / ישנתי = ___","input":"text"},{"prompt":"זיכרון = ___","input":"text"},{"prompt":"לפני שבוע = ___","input":"text"},{"prompt":"**nosotras** · ver · anoche","input":"text"},{"prompt":"**usted** · hacer · ayer","input":"text"},{"prompt":"**ellos** · vivir · antes","input":"text"},{"prompt":"**yo** · jugar · cuando era niño","input":"text"},{"prompt":"**tú** · viajar · nunca","input":"text"},{"prompt":"**nosotros** · comer · esta semana","input":"text"}]}','{"items":[{"display":"Por la mañana","answers":["Por la mañana"],"policy":{"accents":"lenient"}},{"display":"Dormí / Dormiste / Durmió (dormir)","answers":["Dormí / Dormiste / Durmió (dormir)","Dormí / Dormiste / Durmió","Dormí","Dormiste","Durmió"],"policy":{"accents":"lenient"}},{"display":"Recuerdo","answers":["Recuerdo"],"policy":{"accents":"lenient"}},{"display":"Hace una semana","answers":["Hace una semana"],"policy":{"accents":"lenient"}},{"display":"vimos","answers":["vimos"]},{"display":"hizo","answers":["hizo"]},{"display":"vivían","answers":["vivían"]},{"display":"jugaba","answers":["jugaba"]},{"display":"has viajado","answers":["has viajado"]},{"display":"hemos comido","answers":["hemos comido"]}],"policy":{"accents":"strict"}}','published','L2-U01-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-experiencias-pasadas-17','es2-experiencias-pasadas','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["El sábado pasado, Clara salió temprano, visitó un museo y después cenó con sus amigos. Cuando caminaba hacia el restaurante, empezó a llover."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U01-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado','es-2','es-2-memories','החיים שלי בעבר','Mi vida en pasado','לדבר ולכתוב על הנושא „החיים שלי בעבר“ בספרדית, תוך שימוש במבנים: Primera, segunda y tercera persona en el pasado.','derived','[{"he":"דקדוק בשימוש","target":"Primera, segunda y tercera persona en el pasado"},{"he":"אוצר מילים: החיים שלי בעבר","target":"Mi vida en pasado"}]','["Primera, segunda y tercera persona en el pasado"]','{"rules":[],"examples":["Yo nací en Haifa.","¿Dónde creciste?","Mi compañera vivía en Madrid.","Ayer nosotros fuimos al cine."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Anoche","he":"אתמול בלילה"},{"term":"Ayer","he":"אתמול"},{"term":"Bebí / Bebiste / Bebió (beber)","he":"שתיתי / שתית / שתה"},{"term":"Cine","he":"קולנוע"},{"term":"Cociné / Cocinaste / Cocinó (cocinar)","he":"בישלתי / בישלת / בישל"},{"term":"Comí / Comiste / Comió (comer)","he":"אכלתי / אכלת / אכל"},{"term":"Compré / Compraste / Compró (comprar)","he":"קניתי / קנית / קנה"},{"term":"Conocí / Conociste / Conoció (conocer)","he":"הכרתי / הכרת / הכיר"},{"term":"Cuando era niño","he":"כשהייתי ילד"},{"term":"Cumpleaños","he":"יום הולדת"},{"term":"El año pasado","he":"בשנה שעברה / שנה שעברה"},{"term":"El fin de semana pasado","he":"בסוף השבוע שעבר"},{"term":"Escuché / Escuchaste / Escuchó (escuchar)","he":"הקשבתי / הקשבת / הקשיב"},{"term":"Estudié / Estudiaste / Estudió (estudiar)","he":"למדתי / למדת / למד"},{"term":"Estuve / Estuviste / Estuvo (estar)","he":"הייתי / היית / היה"},{"term":"Fui / Fuiste / Fue (ir)","he":"נסעתי / נסעת / נסע / הייתי / היית / היה"},{"term":"Hablé / Hablaste / Habló (hablar)","he":"דיברתי / דיברת / דיבר"},{"term":"Hace dos días","he":"לפני יומיים"},{"term":"Hice / Hiciste / Hizo (hacer)","he":"עשיתי / עשית / עשה"},{"term":"Jugué / Jugaste / Jugó (jugar)","he":"שיחקתי / שיחקת / שיחק"},{"term":"La semana pasada","he":"בשבוע שעבר / שבוע שעבר"},{"term":"Leí / Leíste / Leyó (leer)","he":"קראתי / קראת / קרא"},{"term":"Me mudé / Te mudaste / Se mudó (mudarse)","he":"עברתי / עברת / עבר"},{"term":"Olvidé / Olvidaste / Olvidó (olvidar)","he":"שכחתי / שכחת / שכח"},{"term":"Organicé / Organizaste / Organizó (organizar)","he":"ארגנתי / ארגנת / ארגן"},{"term":"Película","he":"סרט"},{"term":"Perdí / Perdiste / Perdió (perder)","he":"איבדתי / איבדת / איבד"},{"term":"Playa","he":"חוף ים / חוף"},{"term":"Restaurante","he":"מסעדה"},{"term":"Supermercado","he":"סופרמרקט"},{"term":"Trabajé / Trabajaste / Trabajó (trabajar)","he":"עבדתי / עבדת / עבד"},{"term":"Vacaciones","he":"חופשה"},{"term":"Vi / Viste / Vio (ver)","he":"ראיתי / ראית / ראה"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1069751182/clase-mi-vida-en-pasado-flash-cards/"}]','published','workbook L2 unit 02',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado-01','es2-mi-vida-en-pasado','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"דיברתי / דיברת / דיבר ___","input":"text"},{"prompt":"לפני יומיים ___","input":"text"},{"prompt":"בשנה שעברה ___","input":"text"},{"prompt":"אתמול ___","input":"text"},{"prompt":"הכרתי / הכרת / הכיר ___","input":"text"},{"prompt":"סרט ___","input":"text"}]}','{"items":[{"display":"Hablé / Hablaste / Habló (hablar)","answers":["Hablé / Hablaste / Habló (hablar)","Hablé / Hablaste / Habló","Hablé","Hablaste","Habló"]},{"display":"Hace dos días","answers":["Hace dos días"]},{"display":"El año pasado","answers":["El año pasado"]},{"display":"Ayer","answers":["Ayer"]},{"display":"Conocí / Conociste / Conoció (conocer)","answers":["Conocí / Conociste / Conoció (conocer)","Conocí / Conociste / Conoció","Conocí","Conociste","Conoció"]},{"display":"Película","answers":["Película"]}],"policy":{"accents":"lenient"}}','published','L2-U02-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado-02','es2-mi-vida-en-pasado','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Hablé / Hablaste / Habló (hablar)","Hace dos días","El año pasado","Ayer","Conocí / Conociste / Conoció (conocer)","Película","La semana pasada","Comí / Comiste / Comió (comer)"],"right":[{"id":"A","text":"לפני יומיים"},{"id":"B","text":"בשבוע שעבר"},{"id":"C","text":"אתמול"},{"id":"D","text":"בשנה שעברה"},{"id":"E","text":"אכלתי / אכלת / אכל"},{"id":"F","text":"דיברתי / דיברת / דיבר"},{"id":"G","text":"הכרתי / הכרת / הכיר"},{"id":"H","text":"סרט"}]}','{"pairs":["F","A","D","C","G","H","B","E"],"policy":{"accents":"lenient"}}','published','L2-U02-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado-03','es2-mi-vida-en-pasado','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"דיברתי / דיברת / דיבר","input":"choice","options":["Supermercado","Hablé / Hablaste / Habló (hablar)","Fui / Fuiste / Fue (ir)"]},{"prompt":"לפני יומיים","input":"choice","options":["Bebí / Bebiste / Bebió (beber)","Hace dos días","Olvidé / Olvidaste / Olvidó (olvidar)"]},{"prompt":"בשנה שעברה","input":"choice","options":["El fin de semana pasado","El año pasado","Playa"]},{"prompt":"אתמול","input":"choice","options":["Ayer","Fui / Fuiste / Fue (ser)","Organicé / Organizaste / Organizó (organizar)"]},{"prompt":"הכרתי / הכרת / הכיר","input":"choice","options":["Supermercado","Organicé / Organizaste / Organizó (organizar)","Conocí / Conociste / Conoció (conocer)"]},{"prompt":"סרט","input":"choice","options":["Vi / Viste / Vio (ver)","Película","Hice / Hiciste / Hizo (hacer)"]}]}','{"items":[{"display":"Hablé / Hablaste / Habló (hablar)","choice":1},{"display":"Hace dos días","choice":1},{"display":"El año pasado","choice":1},{"display":"Ayer","choice":0},{"display":"Conocí / Conociste / Conoció (conocer)","choice":2},{"display":"Película","choice":1}],"policy":{"accents":"lenient"}}','published','L2-U02-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado-04','es2-mi-vida-en-pasado','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"בסוף השבוע שעבר = ___","input":"bank"},{"prompt":"אתמול = ___","input":"bank"},{"prompt":"שיחקתי / שיחקת / שיחק = ___","input":"bank"}],"wordbank":["Jugué / Jugaste / Jugó (jugar)","El fin de semana pasado","Ayer","conoció","El año pasado","estudiar"],"text":"David nació en Haifa y creció cerca del mar. De niño jugaba al fútbol todos los días. {{1}} viajó a Madrid, {{2}} a parte de su familia y empezó a {{3}} español con más constancia."}','{"items":[{"display":"El año pasado","answers":["El año pasado"]},{"display":"conoció","answers":["conoció"]},{"display":"estudiar","answers":["estudiar"]},{"display":"El fin de semana pasado","answers":["El fin de semana pasado"]},{"display":"Ayer","answers":["Ayer"]},{"display":"Jugué / Jugaste / Jugó (jugar)","answers":["Jugué / Jugaste / Jugó (jugar)","Jugué / Jugaste / Jugó"]}],"policy":{"accents":"strict"}}','published','L2-U02-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado-05','es2-mi-vida-en-pasado','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["ayer","por","hiciste","la","tarde","Qué"]},{"prompt":"","input":"tokens","tokens":["comida","última","Qué","comiste","en","tu"]},{"prompt":"","input":"tokens","tokens":["la","serie","viste","en","última","Qué","película"]},{"prompt":"","input":"tokens","tokens":["hiciste","fin","Qué","de","el","semana","pasado"]}]}','{"items":[{"display":"¿Qué hiciste ayer por la tarde?","answers":["¿Qué hiciste ayer por la tarde?"]},{"display":"¿Qué comiste en tu última comida?","answers":["¿Qué comiste en tu última comida?"]},{"display":"¿Qué viste en la última película/serie?","answers":["¿Qué viste en la última película/serie?"]},{"display":"¿Qué hiciste el fin de semana pasado?","answers":["¿Qué hiciste el fin de semana pasado?"]}],"policy":{"accents":"strict"}}','published','L2-U02-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado-06','es2-mi-vida-en-pasado','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Yo nació en Haifa.","input":"sentence"},{"prompt":"¿Dónde crecíste?","input":"sentence"},{"prompt":"Mi compañera vivían en Madrid.","input":"sentence"},{"prompt":"Ayer nosotros fue al cine.","input":"sentence"}]}','{"items":[{"display":"Yo nací en Haifa.","answers":["Yo nací en Haifa."]},{"display":"¿Dónde creciste?","answers":["¿Dónde creciste?"]},{"display":"Mi compañera vivía en Madrid.","answers":["Mi compañera vivía en Madrid."]},{"display":"Ayer nosotros fuimos al cine.","answers":["Ayer nosotros fuimos al cine."]}],"policy":{"accents":"strict"}}','published','L2-U02-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado-07','es2-mi-vida-en-pasado','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Yo nací en Haifa.","Yo nació en Haifa."]},{"prompt":"","input":"choice","options":["¿Dónde creciste?","¿Dónde crecíste?"]},{"prompt":"","input":"choice","options":["Mi compañera vivían en Madrid.","Mi compañera vivía en Madrid."]},{"prompt":"","input":"choice","options":["Ayer nosotros fuimos al cine.","Ayer nosotros fue al cine."]}]}','{"items":[{"display":"Yo nació en Haifa.","choice":1},{"display":"¿Dónde crecíste?","choice":1},{"display":"Mi compañera vivía en Madrid.","choice":1},{"display":"Ayer nosotros fue al cine.","choice":1}],"policy":{"accents":"strict"}}','published','L2-U02-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado-08','es2-mi-vida-en-pasado','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**yo** · nacer · en 1995","input":"text"},{"prompt":"**tú** · crecer · en Haifa","input":"text"},{"prompt":"**él** · vivir · de niño","input":"text"},{"prompt":"**nosotros** · viajar · el año pasado","input":"text"}]}','{"items":[{"display":"nací","answers":["nací"]},{"display":"creciste","answers":["creciste"]},{"display":"vivía","answers":["vivía"]},{"display":"viajamos","answers":["viajamos"]}],"policy":{"accents":"strict"}}','published','L2-U02-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado-09','es2-mi-vida-en-pasado','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Qué hiciste ayer por la tarde?\n¿Qué comiste en tu última comida?\n¿Qué viste en la última película/serie?\n¿Qué hiciste el fin de semana pasado?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U02-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado-10','es2-mi-vida-en-pasado','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**yo** · nacer · en 1995","input":"text"},{"prompt":"**tú** · crecer · en Haifa","input":"text"},{"prompt":"**él** · vivir · de niño","input":"text"},{"prompt":"**nosotros** · viajar · el año pasado","input":"text"},{"prompt":"**ellas** · jugar · ayer","input":"text"},{"prompt":"**usted** · conocer · en 2024","input":"text"},{"prompt":"**vosotros** · estudiar · anoche","input":"text"},{"prompt":"**ella** · empezar · la semana pasada","input":"text"}]}','{"items":[{"display":"nací","answers":["nací"]},{"display":"creciste","answers":["creciste"]},{"display":"vivía","answers":["vivía"]},{"display":"viajamos","answers":["viajamos"]},{"display":"jugaron","answers":["jugaron"]},{"display":"conoció","answers":["conoció"]},{"display":"estudiasteis","answers":["estudiasteis"]},{"display":"empezó","answers":["empezó"]}],"policy":{"accents":"strict"}}','published','L2-U02-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado-11','es2-mi-vida-en-pasado','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Dónde creció David?","input":"sentence"},{"prompt":"¿Qué hacía de niño?","input":"sentence"},{"prompt":"¿Qué cambios ocurrieron el año pasado?","input":"sentence"}],"text":"David nació en Haifa y creció cerca del mar. De niño jugaba al fútbol todos los días. El año pasado viajó a Madrid, conoció a parte de su familia y empezó a estudiar español con más constancia."}','{"items":[{"display":"Cerca del mar.","answers":["Cerca del mar."]},{"display":"Jugaba al fútbol todos los días.","answers":["Jugaba al fútbol todos los días."]},{"display":"Viajó a Madrid, conoció a parte de su familia y empezó a estudiar español.","answers":["Viajó a Madrid, conoció a parte de su familia y empezó a estudiar español."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U02-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado-12','es2-mi-vida-en-pasado','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Mi vida en pasado\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["David nació en Haifa y creció cerca del mar. De niño jugaba al fútbol todos los días. El año pasado viajó a Madrid, conoció a parte de su familia y empezó a estudiar español con más constancia."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U02-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado-13','es2-mi-vida-en-pasado','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: Viajó a Madrid, conoció a parte de su familia y empezó a estudiar español."},{"id":"B","text":"Respuesta: Jugaba al fútbol todos los días."},{"id":"C","text":"Pregunta: ¿Qué cambios ocurrieron el año pasado?"},{"id":"D","text":"Pregunta: ¿Qué hacía de niño?"},{"id":"E","text":"Respuesta: Cerca del mar."},{"id":"F","text":"Pregunta: ¿Dónde creció David?"}]}','{"order":["F","E","D","B","C","A"],"policy":{"accents":"strict"}}','published','L2-U02-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado-14','es2-mi-vida-en-pasado','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"El año pasado viajó a Madrid, conoció a parte de su familia y empezó a estudiar español con más constancia."},{"id":"B","text":"David nació en Haifa y creció cerca del mar."},{"id":"C","text":"De niño jugaba al fútbol todos los días."}]}','{"order":["B","C","A"],"policy":{"accents":"strict"}}','published','L2-U02-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado-15','es2-mi-vida-en-pasado','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre mi vida en pasado es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre mi vida en pasado es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U02-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado-16','es2-mi-vida-en-pasado','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"בשנה שעברה = ___","input":"text"},{"prompt":"אתמול = ___","input":"text"},{"prompt":"הכרתי / הכרת / הכיר = ___","input":"text"},{"prompt":"סרט = ___","input":"text"},{"prompt":"**ella** · empezar · la semana pasada","input":"text"},{"prompt":"**vosotros** · estudiar · anoche","input":"text"},{"prompt":"**usted** · conocer · en 2024","input":"text"},{"prompt":"**ellas** · jugar · ayer","input":"text"},{"prompt":"**nosotros** · viajar · el año pasado","input":"text"},{"prompt":"**él** · vivir · de niño","input":"text"}]}','{"items":[{"display":"El año pasado","answers":["El año pasado"],"policy":{"accents":"lenient"}},{"display":"Ayer","answers":["Ayer"],"policy":{"accents":"lenient"}},{"display":"Conocí / Conociste / Conoció (conocer)","answers":["Conocí / Conociste / Conoció (conocer)","Conocí / Conociste / Conoció","Conocí","Conociste","Conoció"],"policy":{"accents":"lenient"}},{"display":"Película","answers":["Película"],"policy":{"accents":"lenient"}},{"display":"empezó","answers":["empezó"]},{"display":"estudiasteis","answers":["estudiasteis"]},{"display":"conoció","answers":["conoció"]},{"display":"jugaron","answers":["jugaron"]},{"display":"viajamos","answers":["viajamos"]},{"display":"vivía","answers":["vivía"]}],"policy":{"accents":"strict"}}','published','L2-U02-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-mi-vida-en-pasado-17','es2-mi-vida-en-pasado','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["David nació en Haifa y creció cerca del mar. De niño jugaba al fútbol todos los días."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U02-E16',16,1788220800000,1788220800000);
