INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-viajes-futuro-proximo-01','es2-viajes-futuro-proximo','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"להכיר ___","input":"text"},{"prompt":"לבקר ___","input":"text"},{"prompt":"להשתמש ___","input":"text"},{"prompt":"בסוף ___","input":"text"},{"prompt":"מצלמה ___","input":"text"},{"prompt":"בקרוב ___","input":"text"}]}','{"items":[{"display":"Conocer","answers":["Conocer"]},{"display":"Visitar","answers":["Visitar"]},{"display":"Usar","answers":["Usar"]},{"display":"Al final","answers":["Al final"]},{"display":"Cámara","answers":["Cámara"]},{"display":"Pronto","answers":["Pronto"]}],"policy":{"accents":"lenient"}}','published','L2-U03-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-viajes-futuro-proximo-02','es2-viajes-futuro-proximo','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Conocer","Visitar","Usar","Al final","Cámara","Pronto","Dormir","Hacer"],"right":[{"id":"A","text":"מצלמה"},{"id":"B","text":"בקרוב"},{"id":"C","text":"לעשות"},{"id":"D","text":"להשתמש"},{"id":"E","text":"להכיר"},{"id":"F","text":"לבקר"},{"id":"G","text":"בסוף"},{"id":"H","text":"לישון"}]}','{"pairs":["E","F","D","G","A","B","H","C"],"policy":{"accents":"lenient"}}','published','L2-U03-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-viajes-futuro-proximo-03','es2-viajes-futuro-proximo','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"להכיר","input":"choice","options":["Conocer","Mañana","Ver"]},{"prompt":"לבקר","input":"choice","options":["Visitar","Tren","Dormir"]},{"prompt":"להשתמש","input":"choice","options":["Usar","Comer","Ver"]},{"prompt":"בסוף","input":"choice","options":["Billete","Disfrutar","Al final"]},{"prompt":"מצלמה","input":"choice","options":["Tren","Maleta","Cámara"]},{"prompt":"בקרוב","input":"choice","options":["Luego","Pronto","Primero"]}]}','{"items":[{"display":"Conocer","choice":0},{"display":"Visitar","choice":0},{"display":"Usar","choice":0},{"display":"Al final","choice":2},{"display":"Cámara","choice":2},{"display":"Pronto","choice":1}],"policy":{"accents":"lenient"}}','published','L2-U03-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-viajes-futuro-proximo-04','es2-viajes-futuro-proximo','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true}],"wordbank":["dormir","viajar","visitar","después","Primero","tren"],"text":"Este verano, Nur va a {{1}} en {{2}} por España. {{3}} va a {{4}} Madrid, {{5}} va a {{6}} dos noches en Valencia y al final va a descansar en la playa. Va a llevar una maleta pequeña y una cámara."}','{"items":[{"display":"viajar","answers":["viajar"]},{"display":"tren","answers":["tren"]},{"display":"Primero","answers":["Primero"]},{"display":"visitar","answers":["visitar"]},{"display":"después","answers":["después"]},{"display":"dormir","answers":["dormir"]}],"policy":{"accents":"strict"}}','published','L2-U03-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-viajes-futuro-proximo-05','es2-viajes-futuro-proximo','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["viajar","a","vas","próximas","tus","vacaciones","dónde","en","A"]},{"prompt":"","input":"tokens","tokens":["Con","vas","a","viajar","quién"]},{"prompt":"","input":"tokens","tokens":["a","ese","viaje","vas","en","hacer","Qué"]},{"prompt":"","input":"tokens","tokens":["a","dormir","vas","Dónde"]}]}','{"items":[{"display":"¿A dónde vas a viajar en tus próximas vacaciones?","answers":["¿A dónde vas a viajar en tus próximas vacaciones?"]},{"display":"¿Con quién vas a viajar?","answers":["¿Con quién vas a viajar?"]},{"display":"¿Qué vas a hacer en ese viaje?","answers":["¿Qué vas a hacer en ese viaje?"]},{"display":"¿Dónde vas a dormir?","answers":["¿Dónde vas a dormir?"]}],"policy":{"accents":"strict"}}','published','L2-U03-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-viajes-futuro-proximo-06','es2-viajes-futuro-proximo','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Voy a viajando mañana.","input":"sentence"},{"prompt":"Ellos va a visitar Madrid.","input":"sentence"},{"prompt":"Vamos viajar en tren.","input":"sentence"},{"prompt":"¿Qué vas hacer?","input":"sentence"}]}','{"items":[{"display":"Voy a viajar mañana.","answers":["Voy a viajar mañana."]},{"display":"Ellos van a visitar Madrid.","answers":["Ellos van a visitar Madrid."]},{"display":"Vamos a viajar en tren.","answers":["Vamos a viajar en tren."]},{"display":"¿Qué vas a hacer?","answers":["¿Qué vas a hacer?"]}],"policy":{"accents":"strict"}}','published','L2-U03-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-viajes-futuro-proximo-07','es2-viajes-futuro-proximo','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Voy a viajando mañana.","Voy a viajar mañana."]},{"prompt":"","input":"choice","options":["Ellos van a visitar Madrid.","Ellos va a visitar Madrid."]},{"prompt":"","input":"choice","options":["Vamos a viajar en tren.","Vamos viajar en tren."]},{"prompt":"","input":"choice","options":["¿Qué vas a hacer?","¿Qué vas hacer?"]}]}','{"items":[{"display":"Voy a viajar mañana.","choice":1},{"display":"Ellos va a visitar Madrid.","choice":1},{"display":"Vamos viajar en tren.","choice":1},{"display":"¿Qué vas hacer?","choice":1}],"policy":{"accents":"strict"}}','published','L2-U03-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-viajes-futuro-proximo-08','es2-viajes-futuro-proximo','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**yo** · viajar · este verano","input":"text"},{"prompt":"**tú** · reservar · mañana","input":"text"},{"prompt":"**ella** · visitar · este fin de semana","input":"text"},{"prompt":"**nosotros** · dormir · esta noche","input":"text"}]}','{"items":[{"display":"voy a viajar","answers":["voy a viajar"]},{"display":"vas a reservar","answers":["vas a reservar"]},{"display":"va a visitar","answers":["va a visitar"]},{"display":"vamos a dormir","answers":["vamos a dormir"]}],"policy":{"accents":"strict"}}','published','L2-U03-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-viajes-futuro-proximo-09','es2-viajes-futuro-proximo','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿A dónde vas a viajar en tus próximas vacaciones?\n¿Con quién vas a viajar?\n¿Qué vas a hacer en ese viaje?\n¿Dónde vas a dormir?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U03-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-viajes-futuro-proximo-10','es2-viajes-futuro-proximo','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**yo** · viajar · este verano","input":"text"},{"prompt":"**tú** · reservar · mañana","input":"text"},{"prompt":"**ella** · visitar · este fin de semana","input":"text"},{"prompt":"**nosotros** · dormir · esta noche","input":"text"},{"prompt":"**ellos** · llevar · en el viaje","input":"text"},{"prompt":"**usted** · salir · esta tarde","input":"text"},{"prompt":"**vosotras** · descansar · el domingo","input":"text"},{"prompt":"**mis amigos** · volver · mañana","input":"text"}]}','{"items":[{"display":"voy a viajar","answers":["voy a viajar"]},{"display":"vas a reservar","answers":["vas a reservar"]},{"display":"va a visitar","answers":["va a visitar"]},{"display":"vamos a dormir","answers":["vamos a dormir"]},{"display":"van a llevar","answers":["van a llevar"]},{"display":"va a salir","answers":["va a salir"]},{"display":"vais a descansar","answers":["vais a descansar"]},{"display":"van a volver","answers":["van a volver"]}],"policy":{"accents":"strict"}}','published','L2-U03-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-viajes-futuro-proximo-11','es2-viajes-futuro-proximo','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Cómo va a viajar Nur?","input":"sentence"},{"prompt":"¿Dónde va a dormir?","input":"sentence"},{"prompt":"¿Qué va a llevar?","input":"sentence"}],"text":"Este verano, Nur va a viajar en tren por España. Primero va a visitar Madrid, después va a dormir dos noches en Valencia y al final va a descansar en la playa. Va a llevar una maleta pequeña y una cámara."}','{"items":[{"display":"En tren.","answers":["En tren."]},{"display":"Dos noches en Valencia.","answers":["Dos noches en Valencia."]},{"display":"Una maleta pequeña y una cámara.","answers":["Una maleta pequeña y una cámara."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U03-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-viajes-futuro-proximo-12','es2-viajes-futuro-proximo','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Viajes · futuro próximo\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Este verano, Nur va a viajar en tren por España. Primero va a visitar Madrid, después va a dormir dos noches en Valencia y al final va a descansar en la playa. Va a llevar una maleta pequeña y una cámara."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U03-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-viajes-futuro-proximo-13','es2-viajes-futuro-proximo','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: En tren."},{"id":"B","text":"Pregunta: ¿Dónde va a dormir?"},{"id":"C","text":"Respuesta: Una maleta pequeña y una cámara."},{"id":"D","text":"Respuesta: Dos noches en Valencia."},{"id":"E","text":"Pregunta: ¿Qué va a llevar?"},{"id":"F","text":"Pregunta: ¿Cómo va a viajar Nur?"}]}','{"order":["F","A","B","D","E","C"],"policy":{"accents":"strict"}}','published','L2-U03-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-viajes-futuro-proximo-14','es2-viajes-futuro-proximo','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Este verano, Nur va a viajar en tren por España."},{"id":"B","text":"Va a llevar una maleta pequeña y una cámara."},{"id":"C","text":"Primero va a visitar Madrid, después va a dormir dos noches en Valencia y al final va a descansar en la playa."}]}','{"order":["A","C","B"],"policy":{"accents":"strict"}}','published','L2-U03-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-viajes-futuro-proximo-15','es2-viajes-futuro-proximo','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre viajes · futuro próximo es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre viajes · futuro próximo es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U03-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-viajes-futuro-proximo-16','es2-viajes-futuro-proximo','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"להשתמש = ___","input":"text"},{"prompt":"בסוף = ___","input":"text"},{"prompt":"מצלמה = ___","input":"text"},{"prompt":"בקרוב = ___","input":"text"},{"prompt":"**mis amigos** · volver · mañana","input":"text"},{"prompt":"**vosotras** · descansar · el domingo","input":"text"},{"prompt":"**usted** · salir · esta tarde","input":"text"},{"prompt":"**ellos** · llevar · en el viaje","input":"text"},{"prompt":"**nosotros** · dormir · esta noche","input":"text"},{"prompt":"**ella** · visitar · este fin de semana","input":"text"}]}','{"items":[{"display":"Usar","answers":["Usar"],"policy":{"accents":"lenient"}},{"display":"Al final","answers":["Al final"],"policy":{"accents":"lenient"}},{"display":"Cámara","answers":["Cámara"],"policy":{"accents":"lenient"}},{"display":"Pronto","answers":["Pronto"],"policy":{"accents":"lenient"}},{"display":"van a volver","answers":["van a volver"]},{"display":"vais a descansar","answers":["vais a descansar"]},{"display":"va a salir","answers":["va a salir"]},{"display":"van a llevar","answers":["van a llevar"]},{"display":"vamos a dormir","answers":["vamos a dormir"]},{"display":"va a visitar","answers":["va a visitar"]}],"policy":{"accents":"strict"}}','published','L2-U03-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-viajes-futuro-proximo-17','es2-viajes-futuro-proximo','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Este verano, Nur va a viajar en tren por España. Primero va a visitar Madrid, después va a dormir dos noches en Valencia y al final va a descansar en la playa."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U03-E16',16,1788220800000,1788220800000);
