"term":"Recibir (recibí)","he":"קיבלתי"},{"term":"Recuerdo","he":"זיכרון / מזכרת"},{"term":"Regalo","he":"מתנה"},{"term":"Restaurante","he":"מסעדה"},{"term":"Ser (fui)","he":"הייתי / להיות"},{"term":"Tener (tuve)","he":"היה לי"},{"term":"Tradición","he":"מסורת"},{"term":"Viaje","he":"נסיעה / טיול / טיול"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1071344404/ocasiones-especiales-pasado-flash-cards/"}]','published','workbook L2 unit 06',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-ocasiones-especiales-pasado-01','es2-ocasiones-especiales-pasado','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"אתמול ___","input":"text"},{"prompt":"יומן ___","input":"text"},{"prompt":"זיכרון ___","input":"text"},{"prompt":"ציר זמן ___","input":"text"},{"prompt":"אתמול בלילה ___","input":"text"},{"prompt":"מסעדה ___","input":"text"}]}','{"items":[{"display":"Ayer","answers":["Ayer"]},{"display":"Diario","answers":["Diario"]},{"display":"Recuerdo","answers":["Recuerdo"]},{"display":"Línea del tiempo","answers":["Línea del tiempo"]},{"display":"Anoche","answers":["Anoche"]},{"display":"Restaurante","answers":["Restaurante"]}],"policy":{"accents":"lenient"}}','published','L2-U06-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-ocasiones-especiales-pasado-02','es2-ocasiones-especiales-pasado','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Ayer","Diario","Recuerdo","Línea del tiempo","Anoche","Restaurante","Hacer (hice)","Graduación"],"right":[{"id":"A","text":"אתמול בלילה"},{"id":"B","text":"ציר זמן"},{"id":"C","text":"יומן"},{"id":"D","text":"אתמול"},{"id":"E","text":"זיכרון"},{"id":"F","text":"סיום לימודים"},{"id":"G","text":"עשיתי"},{"id":"H","text":"מסעדה"}]}','{"pairs":["D","C","E","B","A","H","G","F"],"policy":{"accents":"lenient"}}','published','L2-U06-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-ocasiones-especiales-pasado-03','es2-ocasiones-especiales-pasado','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"אתמול","input":"choice","options":["Ayer","Comer (comí)","Hace dos años"]},{"prompt":"יומן","input":"choice","options":["Fiesta","Diario","Restaurante"]},{"prompt":"זיכרון","input":"choice","options":["Recuerdo","Diario","Música"]},{"prompt":"ציר זמן","input":"choice","options":["Línea del tiempo","Regalo","Amigos"]},{"prompt":"אתמול בלילה","input":"choice","options":["Anoche","Línea del tiempo","Ser (fui)"]},{"prompt":"מסעדה","input":"choice","options":["Restaurante","Experiencia","Escuela"]}]}','{"items":[{"display":"Ayer","choice":0},{"display":"Diario","choice":1},{"display":"Recuerdo","choice":0},{"display":"Línea del tiempo","choice":0},{"display":"Anoche","choice":0},{"display":"Restaurante","choice":0}],"policy":{"accents":"lenient"}}','published','L2-U06-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-ocasiones-especiales-pasado-04','es2-ocasiones-especiales-pasado','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"מסורת = ___","input":"bank"},{"prompt":"טיול = ___","input":"bank"}],"wordbank":["graduación","Tradición","El año pasado","familia","comida","Viaje"],"text":"{{1}} celebramos la {{2}} de mi hermana. La {{3}} llegó temprano, preparó {{4}} y llevó regalos. Después del discurso, todos brindaron, bailaron y sacaron muchas fotos para recordar la ocasión."}','{"items":[{"display":"El año pasado","answers":["El año pasado"]},{"display":"graduación","answers":["graduación"]},{"display":"familia","answers":["familia"]},{"display":"comida","answers":["comida"]},{"display":"Tradición","answers":["Tradición"]},{"display":"Viaje","answers":["Viaje"]}],"policy":{"accents":"strict"}}','published','L2-U06-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-ocasiones-especiales-pasado-05','es2-ocasiones-especiales-pasado','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["tu","regalo","cumpleaños","recibiste","Qué","último","en"]},{"prompt":"","input":"tokens","tokens":["año","regalo","diste","familiar","o","un","amigo","a","el","pasado","Qué"]},{"prompt":"","input":"tokens","tokens":["tu","Dónde","cumpleaños","mejor","celebraste"]},{"prompt":"","input":"tokens","tokens":["hiciste","Qué","tu","día","escuela","de","en","primer"]}]}','{"items":[{"display":"¿Qué regalo recibiste en tu último cumpleaños?","answers":["¿Qué regalo recibiste en tu último cumpleaños?"]},{"display":"¿Qué regalo diste a un amigo o familiar el año pasado?","answers":["¿Qué regalo diste a un amigo o familiar el año pasado?"]},{"display":"¿Dónde celebraste tu mejor cumpleaños?","answers":["¿Dónde celebraste tu mejor cumpleaños?"]},{"display":"¿Qué hiciste en tu primer día de escuela?","answers":["¿Qué hiciste en tu primer día de escuela?"]}],"policy":{"accents":"strict"}}','published','L2-U06-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-ocasiones-especiales-pasado-06','es2-ocasiones-especiales-pasado','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Ayer celebramos mañana.","input":"sentence"},{"prompt":"Ella recibieron un regalo.","input":"sentence"},{"prompt":"Fuimos en una fiesta.","input":"sentence"},{"prompt":"La familia comió y bailaban una vez.","input":"sentence"}]}','{"items":[{"display":"Ayer celebramos la graduación.","answers":["Ayer celebramos la graduación."]},{"display":"Ella recibió un regalo.","answers":["Ella recibió un regalo."]},{"display":"Fuimos a una fiesta.","answers":["Fuimos a una fiesta."]},{"display":"La familia comió y bailó.","answers":["La familia comió y bailó."]}],"policy":{"accents":"strict"}}','published','L2-U06-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-ocasiones-especiales-pasado-07','es2-ocasiones-especiales-pasado','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Ayer celebramos la graduación.","Ayer celebramos mañana."]},{"prompt":"","input":"choice","options":["Ella recibió un regalo.","Ella recibieron un regalo."]},{"prompt":"","input":"choice","options":["Fuimos en una fiesta.","Fuimos a una fiesta."]},{"prompt":"","input":"choice","options":["La familia comió y bailaban una vez.","La familia comió y bailó."]}]}','{"items":[{"display":"Ayer celebramos mañana.","choice":1},{"display":"Ella recibieron un regalo.","choice":1},{"display":"Fuimos a una fiesta.","choice":1},{"display":"La familia comió y bailó.","choice":1}],"policy":{"accents":"strict"}}','published','L2-U06-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-ocasiones-especiales-pasado-08','es2-ocasiones-especiales-pasado','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**nosotros** · celebrar · el año pasado","input":"text"},{"prompt":"**la familia** · llegar · temprano","input":"text"},{"prompt":"**ellos** · preparar · ayer","input":"text"},{"prompt":"**mi hermana** · llevar · un regalo","input":"text"}]}','{"items":[{"display":"celebramos","answers":["celebramos"]},{"display":"llegó","answers":["llegó"]},{"display":"prepararon","answers":["prepararon"]},{"display":"llevó","answers":["llevó"]}],"policy":{"accents":"strict"}}','published','L2-U06-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-ocasiones-especiales-pasado-09','es2-ocasiones-especiales-pasado','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Qué regalo recibiste en tu último cumpleaños?\n¿Qué regalo diste a un amigo o familiar el año pasado?\n¿Dónde celebraste tu mejor cumpleaños?\n¿Qué hiciste en tu primer día de escuela?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U06-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-ocasiones-especiales-pasado-10','es2-ocasiones-especiales-pasado','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**nosotros** · celebrar · el año pasado","input":"text"},{"prompt":"**la familia** · llegar · temprano","input":"text"},{"prompt":"**ellos** · preparar · ayer","input":"text"},{"prompt":"**mi hermana** · llevar · un regalo","input":"text"},{"prompt":"**todos** · brindar · después del discurso","input":"text"},{"prompt":"**tú** · bailar · anoche","input":"text"},{"prompt":"**él** · sacar · muchas fotos","input":"text"},{"prompt":"**yo** · recibir · un regalo ayer","input":"text"}]}','{"items":[{"display":"celebramos","answers":["celebramos"]},{"display":"llegó","answers":["llegó"]},{"display":"prepararon","answers":["prepararon"]},{"display":"llevó","answers":["llevó"]},{"display":"brindaron","answers":["brindaron"]},{"display":"bailaste","answers":["bailaste"]},{"display":"sacó","answers":["sacó"]},{"display":"recibí","answers":["recibí"]}],"policy":{"accents":"strict"}}','published','L2-U06-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-ocasiones-especiales-pasado-11','es2-ocasiones-especiales-pasado','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué celebró la familia?","input":"sentence"},{"prompt":"¿Qué pasó después del discurso?","input":"sentence"},{"prompt":"¿Para qué sacaron fotos?","input":"sentence"}],"text":"El año pasado celebramos la graduación de mi hermana. La familia llegó temprano, preparó comida y llevó regalos. Después del discurso, todos brindaron, bailaron y sacaron muchas fotos para recordar la ocasión."}','{"items":[{"display":"La graduación de su hermana.","answers":["La graduación de su hermana."]},{"display":"Todos brindaron, bailaron y sacaron fotos.","answers":["Todos brindaron, bailaron y sacaron fotos."]},{"display":"Para recordar la ocasión.","answers":["Para recordar la ocasión."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U06-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-ocasiones-especiales-pasado-12','es2-ocasiones-especiales-pasado','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Ocasiones especiales · pasado\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["El año pasado celebramos la graduación de mi hermana. La familia llegó temprano, preparó comida y llevó regalos. Después del discurso, todos brindaron, bailaron y sacaron muchas fotos para recordar la ocasión."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U06-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-ocasiones-especiales-pasado-13','es2-ocasiones-especiales-pasado','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Para qué sacaron fotos?"},{"id":"B","text":"Respuesta: Para recordar la ocasión."},{"id":"C","text":"Pregunta: ¿Qué pasó después del discurso?"},{"id":"D","text":"Respuesta: La graduación de su hermana."},{"id":"E","text":"Pregunta: ¿Qué celebró la familia?"},{"id":"F","text":"Respuesta: Todos brindaron, bailaron y sacaron fotos."}]}','{"order":["E","D","C","F","A","B"],"policy":{"accents":"strict"}}','published','L2-U06-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-ocasiones-especiales-pasado-14','es2-ocasiones-especiales-pasado','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"La familia llegó temprano, preparó comida y llevó regalos."},{"id":"B","text":"El año pasado celebramos la graduación de mi hermana."},{"id":"C","text":"Después del discurso, todos brindaron, bailaron y sacaron muchas fotos para recordar la ocasión."}]}','{"order":["B","A","C"],"policy":{"accents":"strict"}}','published','L2-U06-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-ocasiones-especiales-pasado-15','es2-ocasiones-especiales-pasado','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre ocasiones especiales · pasado es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre ocasiones especiales · pasado es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U06-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-ocasiones-especiales-pasado-16','es2-ocasiones-especiales-pasado','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"זיכרון = ___","input":"text"},{"prompt":"ציר זמן = ___","input":"text"},{"prompt":"אתמול בלילה = ___","input":"text"},{"prompt":"מסעדה = ___","input":"text"},{"prompt":"**yo** · recibir · un regalo ayer","input":"text"},{"prompt":"**él** · sacar · muchas fotos","input":"text"},{"prompt":"**tú** · bailar · anoche","input":"text"},{"prompt":"**todos** · brindar · después del discurso","input":"text"},{"prompt":"**mi hermana** · llevar · un regalo","input":"text"},{"prompt":"**ellos** · preparar · ayer","input":"text"}]}','{"items":[{"display":"Recuerdo","answers":["Recuerdo"],"policy":{"accents":"lenient"}},{"display":"Línea del tiempo","answers":["Línea del tiempo"],"policy":{"accents":"lenient"}},{"display":"Anoche","answers":["Anoche"],"policy":{"accents":"lenient"}},{"display":"Restaurante","answers":["Restaurante"],"policy":{"accents":"lenient"}},{"display":"recibí","answers":["recibí"]},{"display":"sacó","answers":["sacó"]},{"display":"bailaste","answers":["bailaste"]},{"display":"brindaron","answers":["brindaron"]},{"display":"llevó","answers":["llevó"]},{"display":"prepararon","answers":["prepararon"]}],"policy":{"accents":"strict"}}','published','L2-U06-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-ocasiones-especiales-pasado-17','es2-ocasiones-especiales-pasado','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["El año pasado celebramos la graduación de mi hermana. La familia llegó temprano, preparó comida y llevó regalos."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U06-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud','es-2','es-2-goals','בריאות','Salud','לדבר ולכתוב על הנושא „בריאות“ בספרדית, תוך שימוש במבנים: Pasado, consejos y verbos modales.','derived','[{"he":"דקדוק בשימוש","target":"Pasado, consejos y verbos modales"},{"he":"אוצר מילים: בריאות","target":"Salud"}]','["Pasado, consejos y verbos modales"]','{"rules":[],"examples":["Tengo dolor de cabeza.","Debes descansar.","Yo debería beber agua.","Ayer me sentí mal."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Beber (bebí)","he":"שתיתי / לשתות"},{"term":"Cita","he":"תור"},{"term":"Comer","he":"לאכול / אכלתי"},{"term":"Consejo","he":"עצה"},{"term":"Cuidarse","he":"לשמור על עצמך"},{"term":"Debe","he":"צריך"},{"term":"Debería","he":"כדאי"},{"term":"Descansar","he":"לנוח"},{"term":"Doctor","he":"רופא"},{"term":"Dolor","he":"כאב"},{"term":"Dolor de cabeza","he":"כאב ראש"},{"term":"Dolor de espalda","he":"כאב גב"},{"term":"Dolor de garganta","he":"כאב גרון"},{"term":"Dormir","he":"לישון"},{"term":"Hábito","he":"הרגל"},{"term":"Hacer ejercicio","he":"לעשות ספורט"},{"term":"Hospital","he":"בית חולים"},{"term":"Medicamento","he":"תרופה"},{"term":"Podría","he":"יכול / אולי (אפשרות"},{"term":"Preguntar","he":"לשאול"},{"term":"Puede","he":"אולי"},{"term":"Que te mejores pronto","he":"החלמה מהירה"},{"term":"Resfriado (enfermedad)","he":"הצטננות"},{"term":"Responder","he":"לענות"},{"term":"Salud","he":"בריאות"},{"term":"Saludable","he":"בריא"},{"term":"Sentir","he":"להרגיש"},{"term":"Será mejor que lo","he":"עדיף ש..."},{"term":"Tengo que","he":"חייב"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/1058986766/conversational-english-health-flash-cards/"}]','published','workbook L2 unit 07',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud-01','es2-salud','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"בריא ___","input":"text"},{"prompt":"עדיף ש... ___","input":"text"},{"prompt":"חייב ___","input":"text"},{"prompt":"כאב גרון ___","input":"text"},{"prompt":"אולי (אפשרות ___","input":"text"},{"prompt":"לשאול ___","input":"text"}]}','{"items":[{"display":"Saludable","answers":["Saludable"]},{"display":"Será mejor que lo","answers":["Será mejor que lo"]},{"display":"Tengo que","answers":["Tengo que"]},{"display":"Dolor de garganta","answers":["Dolor de garganta"]},{"display":"Podría (posibilidad)","answers":["Podría (posibilidad)","Podría"]},{"display":"Preguntar","answers":["Preguntar"]}],"policy":{"accents":"lenient"}}','published','L2-U07-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud-02','es2-salud','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Saludable","Será mejor que lo","Tengo que","Dolor de garganta","Podría (posibilidad)","Preguntar","Dolor de cabeza","Dormir"],"right":[{"id":"A","text":"עדיף ש..."},{"id":"B","text":"אולי (אפשרות"},{"id":"C","text":"חייב"},{"id":"D","text":"כאב גרון"},{"id":"E","text":"לישון"},{"id":"F","text":"כאב ראש"},{"id":"G","text":"בריא"},{"id":"H","text":"לשאול"}]}','{"pairs":["G","A","C","D","B","H","F","E"],"policy":{"accents":"lenient"}}','published','L2-U07-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud-03','es2-salud','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"בריא","input":"choice","options":["Podría (posibilidad)","Cuidarse","Saludable"]},{"prompt":"עדיף ש...","input":"choice","options":["Dolor de cabeza","Será mejor que lo","Resfriado (enfermedad)"]},{"prompt":"חייב","input":"choice","options":["Tengo que","Doctor","Comer"]},{"prompt":"כאב גרון","input":"choice","options":["Beber","Dormir","Dolor de garganta"]},{"prompt":"אולי (אפשרות","input":"choice","options":["Será mejor que lo","Dolor","Podría (posibilidad)"]},{"prompt":"לשאול","input":"choice","options":["Preguntar","Dolor de cabeza","Tengo que"]}]}','{"items":[{"display":"Saludable","choice":2},{"display":"Será mejor que lo","choice":1},{"display":"Tengo que","choice":0},{"display":"Dolor de garganta","choice":2},{"display":"Podría (posibilidad)","choice":2},{"display":"Preguntar","choice":0}],"policy":{"accents":"lenient"}}','published','L2-U07-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud-04','es2-salud','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true}],"wordbank":["medicamento","doctor","dolor de garganta","beber","descansar","cita"],"text":"Ayer Tomás tenía {{1}} y de cabeza. Llamó al {{2}} y consiguió una {{3}}. El médico le dijo que debía {{4}}, {{5}} agua y tomar el {{6}}. Hoy se siente mejor."}','{"items":[{"display":"dolor de garganta","answers":["dolor de garganta"]},{"display":"doctor","answers":["doctor"]},{"display":"cita","answers":["cita"]},{"display":"descansar","answers":["descansar"]},{"display":"beber","answers":["beber"]},{"display":"medicamento","answers":["medicamento"]}],"policy":{"accents":"strict"}}','published','L2-U07-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud-05','es2-salud','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["Cómo","tu","salud","cuidas"]},{"prompt":"","input":"tokens","tokens":["fuiste","vez","al","fue","que","última","la","médico","Cuándo"]},{"prompt":"","input":"tokens","tokens":["Qué","importante","para","ejercicio","buena","hacer","alimentación","ti","más","o","es","una"]},{"prompt":"","input":"tokens","tokens":["a","Qué","Haces","veces","tipo","de","Cuántas","ejercicio","semana","ejercicio","la"]}]}','{"items":[{"display":"¿Cómo cuidas tu salud?","answers":["¿Cómo cuidas tu salud?"]},{"display":"¿Cuándo fue la última vez que fuiste al médico?","answers":["¿Cuándo fue la última vez que fuiste al médico?"]},{"display":"¿Qué es más importante para ti: una buena alimentación o hacer ejercicio?","answers":["¿Qué es más importante para ti: una buena alimentación o hacer ejercicio?"]},{"display":"¿Haces ejercicio? ¿Qué tipo de ejercicio? ¿Cuántas veces a la semana?","answers":["¿Haces ejercicio? ¿Qué tipo de ejercicio? ¿Cuántas veces a la semana?"]}],"policy":{"accents":"strict"}}','published','L2-U07-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud-06','es2-salud','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Tengo dolor en cabeza.","input":"sentence"},{"prompt":"Debes a descansar.","input":"sentence"},{"prompt":"Yo debería bebo agua.","input":"sentence"},{"prompt":"Ayer me siento mal.","input":"sentence"}]}','{"items":[{"display":"Tengo dolor de cabeza.","answers":["Tengo dolor de cabeza."]},{"display":"Debes descansar.","answers":["Debes descansar."]},{"display":"Yo debería beber agua.","answers":["Yo debería beber agua."]},{"display":"Ayer me sentí mal.","answers":["Ayer me sentí mal."]}],"policy":{"accents":"strict"}}','published','L2-U07-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud-07','es2-salud','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Tengo dolor en cabeza.","Tengo dolor de cabeza."]},{"prompt":"","input":"choice","options":["Debes a descansar.","Debes descansar."]},{"prompt":"","input":"choice","options":["Yo debería beber agua.","Yo debería bebo agua."]},{"prompt":"","input":"choice","options":["Ayer me siento mal.","Ayer me sentí mal."]}]}','{"items":[{"display":"Tengo dolor de cabeza.","choice":1},{"display":"Debes descansar.","choice":1},{"display":"Yo debería bebo agua.","choice":1},{"display":"Ayer me sentí mal.","choice":1}],"policy":{"accents":"strict"}}','published','L2-U07-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud-08','es2-salud','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**Tomás** · tener · ayer","input":"text"},{"prompt":"**yo** · llamar · esta mañana","input":"text"},{"prompt":"**ella** · conseguir · ayer","input":"text"},{"prompt":"**el paciente** · deber · según el médico","input":"text"}]}','{"items":[{"display":"tenía","answers":["tenía"]},{"display":"llamé","answers":["llamé"]},{"display":"consiguió","answers":["consiguió"]},{"display":"debía","answers":["debía"]}],"policy":{"accents":"strict"}}','published','L2-U07-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud-09','es2-salud','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Cómo cuidas tu salud?\n¿Cuándo fue la última vez que fuiste al médico?\n¿Qué es más importante para ti: una buena alimentación o hacer ejercicio?\n¿Haces ejercicio? ¿Qué tipo de ejercicio? ¿Cuántas veces a la semana?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U07-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud-10','es2-salud','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**Tomás** · tener · ayer","input":"text"},{"prompt":"**yo** · llamar · esta mañana","input":"text"},{"prompt":"**ella** · conseguir · ayer","input":"text"},{"prompt":"**el paciente** · deber · según el médico","input":"text"},{"prompt":"**tú** · deber · hoy","input":"text"},{"prompt":"**yo** · deber · como consejo","input":"text"},{"prompt":"**él** · sentirse · hoy","input":"text"},{"prompt":"**tú** · tomar · ayer","input":"text"}]}','{"items":[{"display":"tenía","answers":["tenía"]},{"display":"llamé","answers":["llamé"]},{"display":"consiguió","answers":["consiguió"]},{"display":"debía","answers":["debía"]},{"display":"debes","answers":["debes"]},{"display":"debería","answers":["debería"]},{"display":"se siente","answers":["se siente"]},{"display":"tomaste","answers":["tomaste"]}],"policy":{"accents":"strict"}}','published','L2-U07-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud-11','es2-salud','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué síntomas tenía Tomás?","input":"sentence"},{"prompt":"¿Qué consejo recibió?","input":"sentence"},{"prompt":"¿Cómo se siente hoy?","input":"sentence"}],"text":"Ayer Tomás tenía dolor de garganta y de cabeza. Llamó al doctor y consiguió una cita. El médico le dijo que debía descansar, beber agua y tomar el medicamento. Hoy se siente mejor."}','{"items":[{"display":"Dolor de garganta y de cabeza.","answers":["Dolor de garganta y de cabeza."]},{"display":"Descansar, beber agua y tomar el medicamento.","answers":["Descansar, beber agua y tomar el medicamento."]},{"display":"Se siente mejor.","answers":["Se siente mejor."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U07-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud-12','es2-salud','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Salud\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Ayer Tomás tenía dolor de garganta y de cabeza. Llamó al doctor y consiguió una cita. El médico le dijo que debía descansar, beber agua y tomar el medicamento. Hoy se siente mejor."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U07-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud-13','es2-salud','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: Se siente mejor."},{"id":"B","text":"Pregunta: ¿Cómo se siente hoy?"},{"id":"C","text":"Pregunta: ¿Qué consejo recibió?"},{"id":"D","text":"Respuesta: Descansar, beber agua y tomar el medicamento."},{"id":"E","text":"Pregunta: ¿Qué síntomas tenía Tomás?"},{"id":"F","text":"Respuesta: Dolor de garganta y de cabeza."}]}','{"order":["E","F","C","D","B","A"],"policy":{"accents":"strict"}}','published','L2-U07-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud-14','es2-salud','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Llamó al doctor y consiguió una cita."},{"id":"B","text":"El médico le dijo que debía descansar, beber agua y tomar el medicamento."},{"id":"C","text":"Ayer Tomás tenía dolor de garganta y de cabeza."},{"id":"D","text":"Hoy se siente mejor."}]}','{"order":["C","A","B","D"],"policy":{"accents":"strict"}}','published','L2-U07-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud-15','es2-salud','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre salud es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre salud es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U07-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud-16','es2-salud','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"חייב = ___","input":"text"},{"prompt":"כאב גרון = ___","input":"text"},{"prompt":"אולי (אפשרות = ___","input":"text"},{"prompt":"לשאול = ___","input":"text"},{"prompt":"**tú** · tomar · ayer","input":"text"},{"prompt":"**él** · sentirse · hoy","input":"text"},{"prompt":"**yo** · deber · como consejo","input":"text"},{"prompt":"**tú** · deber · hoy","input":"text"},{"prompt":"**el paciente** · deber · según el médico","input":"text"},{"prompt":"**ella** · conseguir · ayer","input":"text"}]}','{"items":[{"display":"Tengo que","answers":["Tengo que"],"policy":{"accents":"lenient"}},{"display":"Dolor de garganta","answers":["Dolor de garganta"],"policy":{"accents":"lenient"}},{"display":"Podría (posibilidad)","answers":["Podría (posibilidad)","Podría"],"policy":{"accents":"lenient"}},{"display":"Preguntar","answers":["Preguntar"],"policy":{"accents":"lenient"}},{"display":"tomaste","answers":["tomaste"]},{"display":"se siente","answers":["se siente"]},{"display":"debería","answers":["debería"]},{"display":"debes","answers":["debes"]},{"display":"debía","answers":["debía"]},{"display":"consiguió","answers":["consiguió"]}],"policy":{"accents":"strict"}}','published','L2-U07-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-salud-17','es2-salud','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Ayer Tomás tenía dolor de garganta y de cabeza. Llamó al doctor y consiguió una cita."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U07-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es2-planes-para-el-fin-de-semana','es-2','es-2-plans','תוכניות לסוף השבוע','Planes para el fin de semana','לדבר ולכתוב על הנושא „תוכניות לסוף השבוע“ בספרדית, תוך שימוש במבנים: Planes, preferencias y futuro.','derived','[{"he":"דקדוק בשימוש","target":"Planes, preferencias y futuro"},{"he":"אוצר מילים: תוכניות לסוף השבוע","target":"Planes para el fin de semana"}]','["Planes, preferencias y futuro"]','{"rules":[],"examples":["Voy a hacer un plan.","El sábado iremos al parque.","Mi amiga prefiere descansar.","Este plan es más divertido que aquel."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"aburrido","he":"משעמם"},{"term":"activo","he":"פעיל"},{"term":"al aire libre","he":"בחוץ"},{"term":"alimento","he":"אוכל / מזון"},{"term":"cronograma","he":"לוח זמנים"},{"term":"Cultura","he":"תרבות"},{"term":"debate","he":"ויכוח"},{"term":"dentro","he":"בתוך / בפנים"},{"term":"Descansar","he":"לנוח"},{"term":"divertido","he":"משעשע / מצחיק / מהנה / מצחיק / / מהנה / מצחיק"},{"term":"energía","he":"אנרגיה"},{"term":"Experiencia","he":"חוויה / ניסיון"},{"term":"favorito","he":"מועדף / אהוב / מועדף / אהוב"},{"term":"fin de semana","he":"סוף שבוע"},{"term":"Futuro","he":"עתיד"},{"term":"ganador","he":"מנצח"},{"term":"guía","he":"מדריכה / מדריך"},{"term":"Mañana","he":"מחר / מחר / בוקר"},{"term":"necesidad","he":"צורך"},{"term":"noche","he":"לילה"},{"term":"Opinión","he":"דעה"},{"term":"plan","he":"תוכנית"},{"term":"posibilidad","he":"אפשרות"},{"term":"recomendación","he":"המלצה"},{"term":"relajación","he":"הרגעה"},{"term":"sorprendente","he":"מפתיע"},{"term":"tarde","he":"אחר הצהריים"},{"term":"transporte","he":"תחבורה"},{"term":"turista","he":"תייר"},{"term":"votar","he":"להצביע"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizle