INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-planes-para-el-fin-de-semana-01','es2-planes-para-el-fin-de-semana','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"לוח זמנים ___","input":"text"},{"prompt":"דעה ___","input":"text"},{"prompt":"אפשרות ___","input":"text"},{"prompt":"אנרגיה ___","input":"text"},{"prompt":"בחוץ ___","input":"text"},{"prompt":"תרבות ___","input":"text"}]}','{"items":[{"display":"cronograma","answers":["cronograma"]},{"display":"opinión","answers":["opinión"]},{"display":"posibilidad","answers":["posibilidad"]},{"display":"energía","answers":["energía"]},{"display":"al aire libre","answers":["al aire libre"]},{"display":"cultura","answers":["cultura"]}],"policy":{"accents":"lenient"}}','published','L2-U08-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-planes-para-el-fin-de-semana-02','es2-planes-para-el-fin-de-semana','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["cronograma","opinión","posibilidad","energía","al aire libre","cultura","fin de semana","dentro"],"right":[{"id":"A","text":"בחוץ"},{"id":"B","text":"סוף שבוע"},{"id":"C","text":"בתוך / בפנים"},{"id":"D","text":"תרבות"},{"id":"E","text":"אפשרות"},{"id":"F","text":"לוח זמנים"},{"id":"G","text":"דעה"},{"id":"H","text":"אנרגיה"}]}','{"pairs":["F","G","E","H","A","D","B","C"],"policy":{"accents":"lenient"}}','published','L2-U08-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-planes-para-el-fin-de-semana-03','es2-planes-para-el-fin-de-semana','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"לוח זמנים","input":"choice","options":["cronograma","sorprendente","cultura"]},{"prompt":"דעה","input":"choice","options":["favorito","descansar","opinión"]},{"prompt":"אפשרות","input":"choice","options":["cronograma","posibilidad","alimento"]},{"prompt":"אנרגיה","input":"choice","options":["energía","plan","dentro"]},{"prompt":"בחוץ","input":"choice","options":["al aire libre","recomendación","guía"]},{"prompt":"תרבות","input":"choice","options":["opinión","cultura","al aire libre"]}]}','{"items":[{"display":"cronograma","choice":0},{"display":"opinión","choice":2},{"display":"posibilidad","choice":1},{"display":"energía","choice":0},{"display":"al aire libre","choice":0},{"display":"cultura","choice":1}],"policy":{"accents":"lenient"}}','published','L2-U08-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-planes-para-el-fin-de-semana-04','es2-planes-para-el-fin-de-semana','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true}],"wordbank":["mañana","al aire libre","descansar","noche","fin de semana","plan"],"text":"Este {{1}}, Eva va a visitar una ciudad nueva. Por la {{2}} hará una actividad {{3}} y por la {{4}} irá a un concierto. Su amiga prefiere {{5}}, así que necesitan negociar el {{6}}."}','{"items":[{"display":"fin de semana","answers":["fin de semana"]},{"display":"mañana","answers":["mañana"]},{"display":"al aire libre","answers":["al aire libre"]},{"display":"noche","answers":["noche"]},{"display":"descansar","answers":["descansar"]},{"display":"plan","answers":["plan"]}],"policy":{"accents":"strict"}}','published','L2-U08-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-planes-para-el-fin-de-semana-05','es2-planes-para-el-fin-de-semana','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["planeas","fin","Qué","este","de","semana","hacer"]},{"prompt":"","input":"tokens","tokens":["fin","puedas","que","semana","imaginar","el","mejor","Cómo","de","es"]},{"prompt":"","input":"tokens","tokens":["Cómo","imaginar","fin","de","puedas","peor","el","semana","que","es"]},{"prompt":"","input":"tokens","tokens":["este","o","amigos","a","con","pasar","Vas","con","semana","familiares","tiempo","de","fin"]}]}','{"items":[{"display":"¿Qué planeas hacer este fin de semana?","answers":["¿Qué planeas hacer este fin de semana?"]},{"display":"¿Cómo es el mejor fin de semana que puedas imaginar?","answers":["¿Cómo es el mejor fin de semana que puedas imaginar?"]},{"display":"¿Cómo es el peor fin de semana que puedas imaginar?","answers":["¿Cómo es el peor fin de semana que puedas imaginar?"]},{"display":"¿Vas a pasar tiempo con amigos o con familiares este fin de semana?","answers":["¿Vas a pasar tiempo con amigos o con familiares este fin de semana?"]}],"policy":{"accents":"strict"}}','published','L2-U08-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-planes-para-el-fin-de-semana-06','es2-planes-para-el-fin-de-semana','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Voy hacer un plan.","input":"sentence"},{"prompt":"El sábado iremos ayer.","input":"sentence"},{"prompt":"Mi amiga prefieren descansar.","input":"sentence"},{"prompt":"Este plan es más divertido que aquel plan es.","input":"sentence"}]}','{"items":[{"display":"Voy a hacer un plan.","answers":["Voy a hacer un plan."]},{"display":"El sábado iremos al parque.","answers":["El sábado iremos al parque."]},{"display":"Mi amiga prefiere descansar.","answers":["Mi amiga prefiere descansar."]},{"display":"Este plan es más divertido que aquel.","answers":["Este plan es más divertido que aquel."]}],"policy":{"accents":"strict"}}','published','L2-U08-E6',5,1788220800000,1788220800000);
