INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-planes-para-el-fin-de-semana-08','es2-planes-para-el-fin-de-semana','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**Eva** · visitar · este fin de semana","input":"text"},{"prompt":"**ella** · hacer · por la mañana","input":"text"},{"prompt":"**Eva** · ir · por la noche","input":"text"},{"prompt":"**su amiga** · preferir · ahora","input":"text"}]}','{"items":[{"display":"va a visitar","answers":["va a visitar"]},{"display":"hará","answers":["hará"]},{"display":"irá","answers":["irá"]},{"display":"prefiere","answers":["prefiere"]}],"policy":{"accents":"strict"}}','published','L2-U08-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-planes-para-el-fin-de-semana-09','es2-planes-para-el-fin-de-semana','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Qué planeas hacer este fin de semana?\n¿Cómo es el mejor fin de semana que puedas imaginar?\n¿Cómo es el peor fin de semana que puedas imaginar?\n¿Vas a pasar tiempo con amigos o con familiares este fin de semana?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U08-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-planes-para-el-fin-de-semana-10','es2-planes-para-el-fin-de-semana','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**Eva** · visitar · este fin de semana","input":"text"},{"prompt":"**ella** · hacer · por la mañana","input":"text"},{"prompt":"**Eva** · ir · por la noche","input":"text"},{"prompt":"**su amiga** · preferir · ahora","input":"text"},{"prompt":"**nosotros** · necesitar · hoy","input":"text"},{"prompt":"**ellos** · descansar · el domingo","input":"text"},{"prompt":"**tú** · salir · mañana","input":"text"},{"prompt":"**nosotras** · ver · el sábado","input":"text"}]}','{"items":[{"display":"va a visitar","answers":["va a visitar"]},{"display":"hará","answers":["hará"]},{"display":"irá","answers":["irá"]},{"display":"prefiere","answers":["prefiere"]},{"display":"necesitamos","answers":["necesitamos"]},{"display":"van a descansar","answers":["van a descansar"]},{"display":"saldrás","answers":["saldrás"]},{"display":"veremos","answers":["veremos"]}],"policy":{"accents":"strict"}}','published','L2-U08-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-planes-para-el-fin-de-semana-11','es2-planes-para-el-fin-de-semana','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué hará Eva por la mañana?","input":"sentence"},{"prompt":"¿Qué prefiere su amiga?","input":"sentence"},{"prompt":"¿Qué necesitan hacer juntas?","input":"sentence"}],"text":"Este fin de semana, Eva va a visitar una ciudad nueva. Por la mañana hará una actividad al aire libre y por la noche irá a un concierto. Su amiga prefiere descansar, así que necesitan negociar el plan."}','{"items":[{"display":"Hará una actividad al aire libre.","answers":["Hará una actividad al aire libre."]},{"display":"Prefiere descansar.","answers":["Prefiere descansar."]},{"display":"Necesitan negociar el plan.","answers":["Necesitan negociar el plan."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U08-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-planes-para-el-fin-de-semana-12','es2-planes-para-el-fin-de-semana','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Planes para el fin de semana\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Este fin de semana, Eva va a visitar una ciudad nueva. Por la mañana hará una actividad al aire libre y por la noche irá a un concierto. Su amiga prefiere descansar, así que necesitan negociar el plan."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U08-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-planes-para-el-fin-de-semana-13','es2-planes-para-el-fin-de-semana','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: Necesitan negociar el plan."},{"id":"B","text":"Pregunta: ¿Qué prefiere su amiga?"},{"id":"C","text":"Pregunta: ¿Qué necesitan hacer juntas?"},{"id":"D","text":"Respuesta: Hará una actividad al aire libre."},{"id":"E","text":"Pregunta: ¿Qué hará Eva por la mañana?"},{"id":"F","text":"Respuesta: Prefiere descansar."}]}','{"order":["E","D","B","F","C","A"],"policy":{"accents":"strict"}}','published','L2-U08-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-planes-para-el-fin-de-semana-14','es2-planes-para-el-fin-de-semana','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Este fin de semana, Eva va a visitar una ciudad nueva."},{"id":"B","text":"Su amiga prefiere descansar, así que necesitan negociar el plan."},{"id":"C","text":"Por la mañana hará una actividad al aire libre y por la noche irá a un concierto."}]}','{"order":["A","C","B"],"policy":{"accents":"strict"}}','published','L2-U08-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-planes-para-el-fin-de-semana-15','es2-planes-para-el-fin-de-semana','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre planes para el fin de semana es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre planes para el fin de semana es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U08-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-planes-para-el-fin-de-semana-16','es2-planes-para-el-fin-de-semana','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"אפשרות = ___","input":"text"},{"prompt":"אנרגיה = ___","input":"text"},{"prompt":"בחוץ = ___","input":"text"},{"prompt":"תרבות = ___","input":"text"},{"prompt":"**nosotras** · ver · el sábado","input":"text"},{"prompt":"**tú** · salir · mañana","input":"text"},{"prompt":"**ellos** · descansar · el domingo","input":"text"},{"prompt":"**nosotros** · necesitar · hoy","input":"text"},{"prompt":"**su amiga** · preferir · ahora","input":"text"},{"prompt":"**Eva** · ir · por la noche","input":"text"}]}','{"items":[{"display":"posibilidad","answers":["posibilidad"],"policy":{"accents":"lenient"}},{"display":"energía","answers":["energía"],"policy":{"accents":"lenient"}},{"display":"al aire libre","answers":["al aire libre"],"policy":{"accents":"lenient"}},{"display":"cultura","answers":["cultura"],"policy":{"accents":"lenient"}},{"display":"veremos","answers":["veremos"]},{"display":"saldrás","answers":["saldrás"]},{"display":"van a descansar","answers":["van a descansar"]},{"display":"necesitamos","answers":["necesitamos"]},{"display":"prefiere","answers":["prefiere"]},{"display":"irá","answers":["irá"]}],"policy":{"accents":"strict"}}','published','L2-U08-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-planes-para-el-fin-de-semana-17','es2-planes-para-el-fin-de-semana','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Este fin de semana, Eva va a visitar una ciudad nueva. Por la mañana hará una actividad al aire libre y por la noche irá a un concierto."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U08-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales','es-2','es-2-celebrations','פסטיבלים','Festivales','לדבר ולכתוב על הנושא „פסטיבלים“ בספרדית, תוך שימוש במבנים: Condiciones, invitaciones y narrativa cultural.','derived','[{"he":"דקדוק בשימוש","target":"Condiciones, invitaciones y narrativa cultural"},{"he":"אוצר מילים: פסטיבלים","target":"Festivales"}]','["Condiciones, invitaciones y narrativa cultural"]','{"rules":[],"examples":["Si vas, verás un desfile.","La gente llevará disfraces.","El festival es más divertido que el otro.","Voy a celebrar la tradición."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Artistas","he":"אמנים"},{"term":"Bailar","he":"לרקוד"},{"term":"Celebrar","he":"לחגוג"},{"term":"Clima","he":"מזג אוויר"},{"term":"Colores","he":"צבעים"},{"term":"Comida","he":"אוכל"},{"term":"Costumbre","he":"מנהג"},{"term":"Cultural","he":"תרבותי"},{"term":"Desfile","he":"מצעד"},{"term":"Diablo","he":"שטן"},{"term":"Disfraz","he":"תחפושת"},{"term":"Disfrazarse","he":"להתלבש"},{"term":"Entrada (ticket)","he":"כרטיס"},{"term":"Estatus social","he":"מעמד חברתי"},{"term":"Evento","he":"אירוע"},{"term":"Feriado","he":"חופשה"},{"term":"Festival","he":"פסטיבל"},{"term":"Festival de","he":"פסטיבל"},{"term":"Fiesta callejera","he":"מסיבת רחוב"},{"term":"Género musical","he":"סגנון מוזיקה"},{"term":"Indígena","he":"ילידי"},{"term":"Máscara","he":"מסכה"},{"term":"Música","he":"מוזיקה"},{"term":"Naranja","he":"כתום"},{"term":"Preparación","he":"הכנה"},{"term":"Reina","he":"מלכה"},{"term":"Tradición","he":"מסורת"},{"term":"Vikingo","he":"ויקינג"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/1001272696/conversational-spanish-festivals-flash-cards/"}]','published','workbook L2 unit 09',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales-01','es2-festivales','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"אוכל ___","input":"text"},{"prompt":"הכנה ___","input":"text"},{"prompt":"מסורת ___","input":"text"},{"prompt":"פסטיבל ___","input":"text"},{"prompt":"להתלבש ___","input":"text"},{"prompt":"מזג אוויר ___","input":"text"}]}','{"items":[{"display":"Comida","answers":["Comida"]},{"display":"Preparación","answers":["Preparación"]},{"display":"Tradición","answers":["Tradición"]},{"display":"Festival de","answers":["Festival de"]},{"display":"Disfrazarse","answers":["Disfrazarse"]},{"display":"Clima","answers":["Clima"]}],"policy":{"accents":"lenient"}}','published','L2-U09-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales-02','es2-festivales','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Comida","Preparación","Tradición","Festival de","Disfrazarse","Clima","Desfile","Bailar"],"right":[{"id":"A","text":"לרקוד"},{"id":"B","text":"להתלבש"},{"id":"C","text":"הכנה"},{"id":"D","text":"מסורת"},{"id":"E","text":"מזג אוויר"},{"id":"F","text":"מצעד"},{"id":"G","text":"אוכל"},{"id":"H","text":"פסטיבל"}]}','{"pairs":["G","C","D","H","B","E","F","A"],"policy":{"accents":"lenient"}}','published','L2-U09-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales-03','es2-festivales','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"אוכל","input":"choice","options":["Indígena","Desfile","Comida"]},{"prompt":"הכנה","input":"choice","options":["Costumbre","Entrada","Preparación"]},{"prompt":"מסורת","input":"choice","options":["Diablo","Colores","Tradición"]},{"prompt":"פסטיבל","input":"choice","options":["Feriado","Festival de","Género musical"]},{"prompt":"להתלבש","input":"choice","options":["Disfraz","Reina","Disfrazarse"]},{"prompt":"מזג אוויר","input":"choice","options":["Clima","Diablo","Tradición"]}]}','{"items":[{"display":"Comida","choice":2},{"display":"Preparación","choice":2},{"display":"Tradición","choice":2},{"display":"Festival de","choice":1},{"display":"Disfrazarse","choice":2},{"display":"Clima","choice":0}],"policy":{"accents":"lenient"}}','published','L2-U09-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales-04','es2-festivales','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true}],"wordbank":["artistas","comida","desfile","festival de","música","colores"],"text":"Si vas al {{1}} primavera, verás un {{2}} lleno de {{3}} y escucharás {{4}} en la calle. Mucha gente llevará disfraces y máscaras. Por la noche habrá {{5}}, baile y {{6}} de diferentes países."}','{"items":[{"display":"festival de","answers":["festival de"]},{"display":"desfile","answers":["desfile"]},{"display":"colores","answers":["colores"]},{"display":"música","answers":["música"]},{"display":"comida","answers":["comida"]},{"display":"artistas","answers":["artistas"]}],"policy":{"accents":"strict"}}','published','L2-U09-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales-05','es2-festivales','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["A","qué","fuiste","festivales"]},{"prompt":"","input":"tokens","tokens":["en","último","O","pasado","te","tu","vestiste","año","qué","el","qué","festival","disfrazaste","De"]},{"prompt":"","input":"tokens","tokens":["algún","años","vas","al","Hay","que","festival","los","todos"]},{"prompt":"","input":"tokens","tokens":["a","vas","qué","A","ir","festivales"]}]}','{"items":[{"display":"¿A qué festivales fuiste?","answers":["¿A qué festivales fuiste?"]},{"display":"¿De qué te disfrazaste el año pasado? ¿O qué vestiste en tu último festival?","answers":["¿De qué te disfrazaste el año pasado? ¿O qué vestiste en tu último festival?"]},{"display":"¿Hay algún festival al que vas todos los años?","answers":["¿Hay algún festival al que vas todos los años?"]},{"display":"¿A qué festivales vas a ir?","answers":["¿A qué festivales vas a ir?"]}],"policy":{"accents":"strict"}}','published','L2-U09-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales-06','es2-festivales','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Si vas, verás un desfile ayer.","input":"sentence"},{"prompt":"La gente llevarán disfraces.","input":"sentence"},{"prompt":"El festival es más divertido como el otro.","input":"sentence"},{"prompt":"Voy a celebraré la tradición.","input":"sentence"}]}','{"items":[{"display":"Si vas, verás un desfile.","answers":["Si vas, verás un desfile."]},{"display":"La gente llevará disfraces.","answers":["La gente llevará disfraces."]},{"display":"El festival es más divertido que el otro.","answers":["El festival es más divertido que el otro."]},{"display":"Voy a celebrar la tradición.","answers":["Voy a celebrar la tradición."]}],"policy":{"accents":"strict"}}','published','L2-U09-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales-07','es2-festivales','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Si vas, verás un desfile ayer.","Si vas, verás un desfile."]},{"prompt":"","input":"choice","options":["La gente llevarán disfraces.","La gente llevará disfraces."]},{"prompt":"","input":"choice","options":["El festival es más divertido que el otro.","El festival es más divertido como el otro."]},{"prompt":"","input":"choice","options":["Voy a celebraré la tradición.","Voy a celebrar la tradición."]}]}','{"items":[{"display":"Si vas, verás un desfile.","choice":1},{"display":"La gente llevará disfraces.","choice":1},{"display":"El festival es más divertido como el otro.","choice":1},{"display":"Voy a celebrar la tradición.","choice":1}],"policy":{"accents":"strict"}}','published','L2-U09-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales-08','es2-festivales','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**tú** · ir · si tienes tiempo","input":"text"},{"prompt":"**tú** · ver · en el festival","input":"text"},{"prompt":"**vosotros** · escuchar · en la calle","input":"text"},{"prompt":"**mucha gente** · llevar · disfraces","input":"text"}]}','{"items":[{"display":"vas","answers":["vas"]},{"display":"verás","answers":["verás"]},{"display":"escucharéis","answers":["escucharéis"]},{"display":"llevará","answers":["llevará"]}],"policy":{"accents":"strict"}}','published','L2-U09-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales-09','es2-festivales','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿A qué festivales fuiste?\n¿De qué te disfrazaste el año pasado? ¿O qué vestiste en tu último festival?\n¿Hay algún festival al que vas todos los años?\n¿A qué festivales vas a ir?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U09-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales-10','es2-festivales','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**tú** · ir · si tienes tiempo","input":"text"},{"prompt":"**tú** · ver · en el festival","input":"text"},{"prompt":"**vosotros** · escuchar · en la calle","input":"text"},{"prompt":"**mucha gente** · llevar · disfraces","input":"text"},{"prompt":"**por la noche** · haber · comida y baile","input":"text"},{"prompt":"**ellos** · celebrar · mañana","input":"text"},{"prompt":"**yo** · invitar · la próxima vez","input":"text"},{"prompt":"**el desfile** · ser · muy colorido","input":"text"}]}','{"items":[{"display":"vas","answers":["vas"]},{"display":"verás","answers":["verás"]},{"display":"escucharéis","answers":["escucharéis"]},{"display":"llevará","answers":["llevará"]},{"display":"habrá","answers":["habrá"]},{"display":"celebrarán","answers":["celebrarán"]},{"display":"invitaré","answers":["invitaré"]},{"display":"será","answers":["será"]}],"policy":{"accents":"strict"}}','published','L2-U09-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales-11','es2-festivales','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué verán los visitantes?","input":"sentence"},{"prompt":"¿Qué llevará mucha gente?","input":"sentence"},{"prompt":"¿Qué habrá por la noche?","input":"sentence"}],"text":"Si vas al festival de primavera, verás un desfile lleno de colores y escucharás música en la calle. Mucha gente llevará disfraces y máscaras. Por la noche habrá comida, baile y artistas de diferentes países."}','{"items":[{"display":"Un desfile lleno de colores.","answers":["Un desfile lleno de colores."]},{"display":"Disfraces y máscaras.","answers":["Disfraces y máscaras."]},{"display":"Comida, baile y artistas de diferentes países.","answers":["Comida, baile y artistas de diferentes países."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U09-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales-12','es2-festivales','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Festivales\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Si vas al festival de primavera, verás un desfile lleno de colores y escucharás música en la calle. Mucha gente llevará disfraces y máscaras. Por la noche habrá comida, baile y artistas de diferentes países."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U09-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales-13','es2-festivales','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Qué habrá por la noche?"},{"id":"B","text":"Pregunta: ¿Qué llevará mucha gente?"},{"id":"C","text":"Respuesta: Comida, baile y artistas de diferentes países."},{"id":"D","text":"Respuesta: Disfraces y máscaras."},{"id":"E","text":"Respuesta: Un desfile lleno de colores."},{"id":"F","text":"Pregunta: ¿Qué verán los visitantes?"}]}','{"order":["F","E","B","D","A","C"],"policy":{"accents":"strict"}}','published','L2-U09-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales-14','es2-festivales','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Mucha gente llevará disfraces y máscaras."},{"id":"B","text":"Si vas al festival de primavera, verás un desfile lleno de colores y escucharás música en la calle."},{"id":"C","text":"Por la noche habrá comida, baile y artistas de diferentes países."}]}','{"order":["B","A","C"],"policy":{"accents":"strict"}}','published','L2-U09-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales-15','es2-festivales','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre festivales es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre festivales es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U09-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales-16','es2-festivales','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"מסורת = ___","input":"text"},{"prompt":"פסטיבל = ___","input":"text"},{"prompt":"להתלבש = ___","input":"text"},{"prompt":"מזג אוויר = ___","input":"text"},{"prompt":"**el desfile** · ser · muy colorido","input":"text"},{"prompt":"**yo** · invitar · la próxima vez","input":"text"},{"prompt":"**ellos** · celebrar · mañana","input":"text"},{"prompt":"**por la noche** · haber · comida y baile","input":"text"},{"prompt":"**mucha gente** · llevar · disfraces","input":"text"},{"prompt":"**vosotros** · escuchar · en la calle","input":"text"}]}','{"items":[{"display":"Tradición","answers":["Tradición"],"policy":{"accents":"lenient"}},{"display":"Festival de","answers":["Festival de"],"policy":{"accents":"lenient"}},{"display":"Disfrazarse","answers":["Disfrazarse"],"policy":{"accents":"lenient"}},{"display":"Clima","answers":["Clima"],"policy":{"accents":"lenient"}},{"display":"será","answers":["será"]},{"display":"invitaré","answers":["invitaré"]},{"display":"celebrarán","answers":["celebrarán"]},{"display":"habrá","answers":["habrá"]},{"display":"llevará","answers":["llevará"]},{"display":"escucharéis","answers":["escucharéis"]}],"policy":{"accents":"strict"}}','published','L2-U09-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-festivales-17','es2-festivales','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Si vas al festival de primavera, verás un desfile lleno de colores y escucharás música en la calle. Mucha gente llevará disfraces y máscaras."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U09-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos','es-2','es-2-memories','חלומות לילה','Sueños nocturnos','לדבר ולכתוב על הנושא „חלומות לילה“ בספרדית, תוך שימוש במבנים: Pretérito, imperfecto y descripción espacial.','derived','[{"he":"דקדוק בשימוש","target":"Pretérito, imperfecto y descripción espacial"},{"he":"אוצר מילים: חלומות לילה","target":"Sueños nocturnos"}]','["Pretérito, imperfecto y descripción espacial"]','{"rules":[],"examples":["Anoche soñé que volaba.","La llave estaba encima de la mesa.","Mientras caía, me desperté.","La calle estaba vacía."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"A pesar de","he":"למרות"},{"term":"Al lado de","he":"ליד"},{"term":"Alarma / despertador","he":"שעון מעורר"},{"term":"Alrededor de","he":"סביב"},{"term":"Caer","he":"ליפול"},{"term":"Calle","he":"רחוב"},{"term":"Debido a","he":"בגלל"},{"term":"Despertar","he":"להתעורר"},{"term":"Detrás de","he":"מאחורי"},{"term":"En lugar de","he":"במקום"},{"term":"Encima","he":"מעל"},{"term":"Escalera","he":"סולם"},{"term":"Examen","he":"מבחן"},{"term":"Extraño","he":"מוזר"},{"term":"Frente a","he":"מול"},{"term":"Habitación","he":"חדר"},{"term":"Hombre","he":"גבר"},{"term":"Junto a","he":"ליד"},{"term":"Llave","he":"מפתח"},{"term":"Lúcido","he":"בהיר"},{"term":"Misterioso","he":"מסתורי"},{"term":"Mujer","he":"אישה"},{"term":"Niño","he":"ילד"},{"term":"Pastel","he":"עוגה"},{"term":"Perseguir","he":"לרדוף"},{"term":"Playa","he":"חוף ים / חוף"},{"term":"Rápido","he":"מהר"},{"term":"Soñar","he":"לחלום"},{"term":"Subterráneo","he":"תת-קרקעי"},{"term":"Sueño","he":"חלום"},{"term":"Vacío","he":"ריק"},{"term":"Volar","he":"לעוף"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/994790485/nighttime-dreams-conversational-spanish-flash-cards/"}]','published','workbook L2 unit 10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos-01','es2-suenos-nocturnos','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"מבחן ___","input":"text"},{"prompt":"בגלל ___","input":"text"},{"prompt":"עוגה ___","input":"text"},{"prompt":"חדר ___","input":"text"},{"prompt":"בהיר ___","input":"text"},{"prompt":"ליד ___","input":"text"}]}','{"items":[{"display":"Examen","answers":["Examen"]},{"display":"Debido a","answers":["Debido a"]},{"display":"Pastel","answers":["Pastel"]},{"display":"Habitación","answers":["Habitación"]},{"display":"Lúcido","answers":["Lúcido"]},{"display":"Junto a","answers":["Junto a"]}],"policy":{"accents":"lenient"}}','published','L2-U10-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos-02','es2-suenos-nocturnos','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Examen","Debido a","Pastel","Habitación","Lúcido","Junto a","Niño","Alarma / despertador"],"right":[{"id":"A","text":"בהיר"},{"id":"B","text":"ליד"},{"id":"C","text":"שעון מעורר"},{"id":"D","text":"בגלל"},{"id":"E","text":"חדר"},{"id":"F","text":"מבחן"},{"id":"G","text":"עוגה"},{"id":"H","text":"ילד"}]}','{"pairs":["F","D","G","E","A","B","H","C"],"policy":{"accents":"lenient"}}','published','L2-U10-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos-03','es2-suenos-nocturnos','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"מבחן","input":"choice","options":["En lugar de","Despertar","Examen"]},{"prompt":"בגלל","input":"choice","options":["Pastel","Debido a","Examen"]},{"prompt":"עוגה","input":"choice","options":["Pastel","Despertar","Playa"]},{"prompt":"חדר","input":"choice","options":["Al lado de","Habitación","Lúcido"]},{"prompt":"בהיר","input":"choice","options":["Lúcido","Niño","En lugar de"]},{"prompt":"ליד","input":"choice","options":["Llave","Junto a","Lúcido"]}]}','{"items":[{"display":"Examen","choice":2},{"display":"Debido a","choice":1},{"display":"Pastel","choice":0},{"display":"Habitación","choice":1},{"display":"Lúcido","choice":0},{"display":"Junto a","choice":1}],"policy":{"accents":"lenient"}}','published','L2-U10-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos-04','es2-suenos-nocturnos','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"עוגה = ___","input":"bank"}],"wordbank":["playa","encima","Pastel","llave","mujer","escalera"],"text":"Anoche soñé que volaba {{1}} de una ciudad vacía. Una {{2}} misteriosa me dio una {{3}}, pero cuando abrí la puerta caí por una {{4}}. Me desperté justo antes de llegar a una {{5}} subterránea."}','{"items":[{"display":"encima","answers":["encima"]},{"display":"mujer","answers":["mujer"]},{"display":"llave","answers":["llave"]},{"display":"escalera","answers":["escalera"]},{"display":"playa","answers":["playa"]},{"display":"Pastel","answers":["Pastel"]}],"policy":{"accents":"strict"}}','published','L2-U10-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos-05','es2-suenos-nocturnos','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["Recuerdas","despiertas","cuando","te","tus","sueños"]},{"prompt":"","input":"tokens","tokens":["estos","de","sueños","vez","uno","Alguna","soñaste"]},{"prompt":"","input":"tokens","tokens":["contarnos","qué","recuerdes","un","sueño","en","pasó","Puedes","que"]},{"prompt":"","input":"tokens","tokens":["alguna","estabas","que","o","Soñaste","vez","en","país","otra","época"]}]}','{"items":[{"display":"¿Recuerdas tus sueños cuando te despiertas?","answers":["¿Recuerdas tus sueños cuando te despiertas?"]},{"display":"¿Alguna vez soñaste uno de estos sueños?","answers":["¿Alguna vez soñaste uno de estos sueños?"]},{"display":"¿Puedes contarnos qué pasó en un sueño que recuerdes?","answers":["¿Puedes contarnos qué pasó en un sueño que recuerdes?"]},{"display":"¿Soñaste alguna vez que estabas en otra época o país?","answers":["¿Soñaste alguna vez que estabas en otra época o país?"]}],"policy":{"accents":"strict"}}','published','L2-U10-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos-06','es2-suenos-nocturnos','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Anoche sueño que volaba.","input":"sentence"},{"prompt":"La llave estaba encima la mesa.","input":"sentence"},{"prompt":"Mientras caí, me despertaba.","input":"sentence"},{"prompt":"La calle eran vacía.","input":"sentence"}]}','{"items":[{"display":"Anoche soñé que volaba.","answers":["Anoche soñé que volaba."]},{"display":"La llave estaba encima de la mesa.","answers":["La llave estaba encima de la mesa."]},{"display":"Mientras caía, me desperté.","answers":["Mientras caía, me desperté."]},{"display":"La calle estaba vacía.","answers":["La calle estaba vacía."]}],"policy":{"accents":"strict"}}','published','L2-U10-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos-07','es2-suenos-nocturnos','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Anoche sueño que volaba.","Anoche soñé que volaba."]},{"prompt":"","input":"choice","options":["La llave estaba encima de la mesa.","La llave estaba encima la mesa."]},{"prompt":"","input":"choice","options":["Mientras caía, me desperté.","Mientras caí, me despertaba."]},{"prompt":"","input":"choice","options":["La calle eran vacía.","La calle estaba vacía."]}]}','{"items":[{"display":"Anoche soñé que volaba.","choice":1},{"display":"La llave estaba encima la mesa.","choice":1},{"display":"Mientras caí, me despertaba.","choice":1},{"display":"La calle estaba vacía.","choice":1}],"policy":{"accents":"strict"}}','published','L2-U10-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos-08','es2-suenos-nocturnos','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**yo** · soñar · anoche","input":"text"},{"prompt":"**yo** · volar · mientras soñaba","input":"text"},{"prompt":"**una mujer** · dar · una llave","input":"text"},{"prompt":"**yo** · abrir · la puerta","input":"text"}]}','{"items":[{"display":"soñé","answers":["soñé"]},{"display":"volaba","answers":["volaba"]},{"display":"dio","answers":["dio"]},{"display":"abrí","answers":["abrí"]}],"policy":{"accents":"strict"}}','published','L2-U10-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos-09','es2-suenos-nocturnos','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Recuerdas tus sueños cuando te despiertas?\n¿Alguna vez soñaste uno de estos sueños?\n¿Puedes contarnos qué pasó en un sueño que recuerdes?\n¿Soñaste alguna vez que estabas en otra época o país?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U10-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos-10','es2-suenos-nocturnos','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**yo** · soñar · anoche","input":"text"},{"prompt":"**yo** · volar · mientras soñaba","input":"text"},{"prompt":"**una mujer** · dar · una llave","input":"text"},{"prompt":"**yo** · abrir · la puerta","input":"text"},{"prompt":"**yo** · caer · de repente","input":"text"},{"prompt":"**yo** · despertarse · justo después","input":"text"},{"prompt":"**la ciudad** · ser · en el sueño","input":"text"},{"prompt":"**la calle** · estar · vacía","input":"text"}]}','{"items":[{"display":"soñé","answers":["soñé"]},{"display":"volaba","answers":["volaba"]},{"display":"dio","answers":["dio"]},{"display":"abrí","answers":["abrí"]},{"display":"caí","answers":["caí"]},{"display":"me desperté","answers":["me desperté"]},{"display":"era","answers":["era"]},{"display":"estaba","answers":["estaba"]}],"policy":{"accents":"strict"}}','published','L2-U10-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos-11','es2-suenos-nocturnos','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Dónde volaba la persona?","input":"sentence"},{"prompt":"¿Qué recibió?","input":"sentence"},{"prompt":"¿Cuándo se despertó?","input":"sentence"}],"text":"Anoche soñé que volaba encima de una ciudad vacía. Una mujer misteriosa me dio una llave, pero cuando abrí la puerta caí por una escalera. Me desperté justo antes de llegar a una playa subterránea."}','{"items":[{"display":"Encima de una ciudad vacía.","answers":["Encima de una ciudad vacía."]},{"display":"Una llave.","answers":["Una llave."]},{"display":"Justo antes de llegar a una playa subterránea.","answers":["Justo antes de llegar a una playa subterránea."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U10-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos-12','es2-suenos-nocturnos','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Sueños nocturnos\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Anoche soñé que volaba encima de una ciudad vacía. Una mujer misteriosa me dio una llave, pero cuando abrí la puerta caí por una escalera. Me desperté justo antes de llegar a una playa subterránea."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U10-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos-13','es2-suenos-nocturnos','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: Una llave."},{"id":"B","text":"Respuesta: Encima de una ciudad vacía."},{"id":"C","text":"Pregunta: ¿Cuándo se despertó?"},{"id":"D","text":"Respuesta: Justo antes de llegar a una playa subterránea."},{"id":"E","text":"Pregunta: ¿Dónde volaba la persona?"},{"id":"F","text":"Pregunta: ¿Qué recibió?"}]}','{"order":["E","B","F","A","C","D"],"policy":{"accents":"strict"}}','published','L2-U10-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos-14','es2-suenos-nocturnos','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Me desperté justo antes de llegar a una playa subterránea."},{"id":"B","text":"Una mujer misteriosa me dio una llave, pero cuando abrí la puerta caí por una escalera."},{"id":"C","text":"Anoche soñé que volaba encima de una ciudad vacía."}]}','{"order":["C","B","A"],"policy":{"accents":"strict"}}','published','L2-U10-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos-15','es2-suenos-nocturnos','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre sueños nocturnos es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre sueños nocturnos es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U10-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos-16','es2-suenos-nocturnos','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"עוגה = ___","input":"text"},{"prompt":"חדר = ___","input":"text"},{"prompt":"בהיר = ___","input":"text"},{"prompt":"ליד = ___","input":"text"},{"prompt":"**la calle** · estar · vacía","input":"text"},{"prompt":"**la ciudad** · ser · en el sueño","input":"text"},{"prompt":"**yo** · despertarse · justo después","input":"text"},{"prompt":"**yo** · caer · de repente","input":"text"},{"prompt":"**yo** · abrir · la puerta","input":"text"},{"prompt":"**una mujer** · dar · una llave","input":"text"}]}','{"items":[{"display":"Pastel","answers":["Pastel"],"policy":{"accents":"lenient"}},{"display":"Habitación","answers":["Habitación"],"policy":{"accents":"lenient"}},{"display":"Lúcido","answers":["Lúcido"],"policy":{"accents":"lenient"}},{"display":"Junto a","answers":["Junto a"],"policy":{"accents":"lenient"}},{"display":"estaba","answers":["estaba"]},{"display":"era","answers":["era"]},{"display":"me desperté","answers":["me desperté"]},{"display":"caí","answers":["caí"]},{"display":"abrí","answers":["abrí"]},{"display":"dio","answers":["dio"]}],"policy":{"accents":"strict"}}','published','L2-U10-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-suenos-nocturnos-17','es2-suenos-nocturnos','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Anoche soñé que volaba encima de una ciudad vacía. Una mujer misteriosa me dio una llave, pero cuando abrí la puerta caí por una escalera."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U10-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado','es-2','es-2-goals','פרויקטים ומטרות: עבר','Proyectos y metas · pasado','לדבר ולכתוב על הנושא „פרויקטים ומטרות: עבר“ בספרדית, תוך שימוש במבנים: Logros, decisiones y reflexión en pasado.','derived','[{"he":"דקדוק בשימוש","target":"Logros, decisiones y reflexión en pasado"},{"he":"אוצר מילים: פרויקטים ומטרות: עבר","target":"Proyectos y metas · pasado"}]','["Logros, decisiones y reflexión en pasado"]','{"rules":[],"examples":["Hace dos años logré mi meta.","Nosotros establecimos un proyecto.","La decisión tuvo impacto.","Ayer me sentí feliz al terminar."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Acción","he":"פעולה"},{"term":"Alcanzar","he":"להגיע"},{"term":"Ayudar","he":"לעזור"},{"term":"Cambio","he":"שינוי"},{"term":"Celebrar","he":"לחגוג"},{"term":"Comunicar","he":"לתקשר"},{"term":"Contribución","he":"תרומה"},{"term":"Decisión","he":"החלטה"},{"term":"Establecer","he":"להקים"},{"term":"Futuro","he":"עתיד"},{"term":"Hacer","he":"לעשות / עשיתי"},{"term":"Lograr","he":"להשיג"},{"term":"Meta","he":"מטרה"},{"term":"Objetivo","he":"יעד"},{"term":"Pasado","he":"עבר"},{"term":"plan","he":"תוכנית"},{"term":"Proyecto","he":"פרויקט"},{"term":"Resultados","he":"תוצאות"},{"term":"Sentir","he":"להרגיש"},{"term":"Voluntario","he":"מתנדב / התנדבות"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/985525722/goals-and-proyects-conversational-spanish-flash-cards/"}]','published','workbook L2 unit 11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado-01','es2-proyectos-y-metas-pasado','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"שינוי ___","input":"text"},{"prompt":"לחגוג ___","input":"text"},{"prompt":"עתיד ___","input":"text"},{"prompt":"להקים ___","input":"text"},{"prompt":"להרגיש ___","input":"text"},{"prompt":"תוצאות ___","input":"text"}]}','{"items":[{"display":"Cambio","answers":["Cambio"]},{"display":"Celebrar","answers":["Celebrar"]},{"display":"Futuro","answers":["Futuro"]},{"display":"Establecer","answers":["Establecer"]},{"display":"Sentir","answers":["Sentir"]},{"display":"Resultados","answers":["Resultados"]}],"policy":{"accents":"lenient"}}','published','L2-U11-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado-02','es2-proyectos-y-metas-pasado','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Cambio","Celebrar","Futuro","Establecer","Sentir","Resultados","Plan","Hacer"],"right":[{"id":"A","text":"לעשות"},{"id":"B","text":"לחגוג"},{"id":"C","text":"תוצאות"},{"id":"D","text":"עתיד"},{"id":"E","text":"להקים"},{"id":"F","text":"שינוי"},{"id":"G","text":"להרגיש"},{"id":"H","text":"תוכנית"}]}','{"pairs":["F","B","D","E","G","C","H","A"],"policy":{"accents":"lenient"}}','published','L2-U11-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado-03','es2-proyectos-y-metas-pasado','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"שינוי","input":"choice","options":["Hacer","Voluntario","Cambio"]},{"prompt":"לחגוג","input":"choice","options":["Celebrar","Sentir","Alcanzar"]},{"prompt":"עתיד","input":"choice","options":["Lograr","Acción","Futuro"]},{"prompt":"להקים","input":"choice","options":["Voluntario","Establecer","Cambio"]},{"prompt":"להרגיש","input":"choice","options":["Comunicar","Lograr","Sentir"]},{"prompt":"תוצאות","input":"choice","options":["Resultados","Objetivo","Celebrar"]}]}','{"items":[{"display":"Cambio","choice":2},{"display":"Celebrar","choice":0},{"display":"Futuro","choice":2},{"display":"Establecer","choice":1},{"display":"Sentir","choice":2},{"display":"Resultados","choice":0}],"policy":{"accents":"lenient"}}','published','L2-U11-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado-04','es2-proyectos-y-metas-pasado','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"לחגוג = ___","input":"bank"}],"wordbank":["meta","resultados","Celebrar","decisión","plan","proyecto"],"text":"Hace dos años, Lina estableció una {{1}} difícil: terminar un {{2}} comunitario. Organizó un equipo, comunicó el {{3}} y pidió ayuda. Cuando celebraron los {{4}}, sintió que cada {{5}} había valido la pena."}','{"items":[{"display":"meta","answers":["meta"]},{"display":"proyecto","answers":["proyecto"]},{"display":"plan","answers":["plan"]},{"display":"resultados","answers":["resultados"]},{"display":"decisión","answers":["decisión"]},{"display":"Celebrar","answers":["Celebrar"]}],"policy":{"accents":"strict"}}','published','L2-U11-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado-05','es2-proyectos-y-metas-pasado','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["tu","ahora","hiciste","meta","para","acercarte","Qué","a","hasta"]},{"prompt":"","input":"tokens","tokens":["tu","lograste","La","fue","Cuál","última","meta"]},{"prompt":"","input":"tokens","tokens":["meta","tu","lograr","para","Qué","hiciste","última"]},{"prompt":"","input":"tokens","tokens":["Cómo","tu","cuando","lograste","sentiste","te","meta"]}]}','{"items":[{"display":"¿Qué hiciste hasta ahora para acercarte a tu meta?","answers":["¿Qué hiciste hasta ahora para acercarte a tu meta?"]},{"display":"¿Cuál fue tu última meta? ¿La lograste?","answers":["¿Cuál fue tu última meta? ¿La lograste?"]},{"display":"¿Qué hiciste para lograr tu última meta?","answers":["¿Qué hiciste para lograr tu última meta?"]},{"display":"¿Cómo te sentiste cuando lograste tu meta?","answers":["¿Cómo te sentiste cuando lograste tu meta?"]}],"policy":{"accents":"strict"}}','published','L2-U11-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado-06','es2-proyectos-y-metas-pasado','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Hace dos años logro mi meta.","input":"sentence"},{"prompt":"Nosotros estableció un proyecto.","input":"sentence"},{"prompt":"La decisión tuvieron impacto.","input":"sentence"},{"prompt":"Ayer sentía feliz al terminar una vez.","input":"sentence"}]}','{"items":[{"display":"Hace dos años logré mi meta.","answers":["Hace dos años logré mi meta."]},{"display":"Nosotros establecimos un proyecto.","answers":["Nosotros establecimos un proyecto."]},{"display":"La decisión tuvo impacto.","answers":["La decisión tuvo impacto."]},{"display":"Ayer me sentí feliz al terminar.","answers":["Ayer me sentí feliz al terminar."]}],"policy":{"accents":"strict"}}','published','L2-U11-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado-07','es2-proyectos-y-metas-pasado','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Hace dos años logré mi meta.","Hace dos años logro mi meta."]},{"prompt":"","input":"choice","options":["Nosotros establecimos un proyecto.","Nosotros estableció un proyecto."]},{"prompt":"","input":"choice","options":["La decisión tuvieron impacto.","La decisión tuvo impacto."]},{"prompt":"","input":"choice","options":["Ayer sentía feliz al terminar una vez.","Ayer me sentí feliz al terminar."]}]}','{"items":[{"display":"Hace dos años logro mi meta.","choice":1},{"display":"Nosotros estableció un proyecto.","choice":1},{"display":"La decisión tuvo impacto.","choice":1},{"display":"Ayer me sentí feliz al terminar.","choice":1}],"policy":{"accents":"strict"}}','published','L2-U11-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado-08','es2-proyectos-y-metas-pasado','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**Lina** · establecer · hace dos años","input":"text"},{"prompt":"**ella** · terminar · el proyecto","input":"text"},{"prompt":"**Lina** · organizar · después","input":"text"},{"prompt":"**nosotros** · comunicar · ayer","input":"text"}]}','{"items":[{"display":"estableció","answers":["estableció"]},{"display":"terminó","answers":["terminó"]},{"display":"organizó","answers":["organizó"]},{"display":"comunicamos","answers":["comunicamos"]}],"policy":{"accents":"strict"}}','published','L2-U11-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado-09','es2-proyectos-y-metas-pasado','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Qué hiciste hasta ahora para acercarte a tu meta?\n¿Cuál fue tu última meta? ¿La lograste?\n¿Qué hiciste para lograr tu última meta?\n¿Cómo te sentiste cuando lograste tu meta?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U11-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado-10','es2-proyectos-y-metas-pasado','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**Lina** · establecer · hace dos años","input":"text"},{"prompt":"**ella** · terminar · el proyecto","input":"text"},{"prompt":"**Lina** · organizar · después","input":"text"},{"prompt":"**nosotros** · comunicar · ayer","input":"text"},{"prompt":"**tú** · pedir · la semana pasada","input":"text"},{"prompt":"**ellos** · celebrar · al final","input":"text"},{"prompt":"**ella** · sentir · al terminar","input":"text"},{"prompt":"**la decisión** · tener · un gran impacto","input":"text"}]}','{"items":[{"display":"estableció","answers":["estableció"]},{"display":"terminó","answers":["terminó"]},{"display":"organizó","answers":["organizó"]},{"display":"comunicamos","answers":["comunicamos"]},{"display":"pediste","answers":["pediste"]},{"display":"celebraron","answers":["celebraron"]},{"display":"sintió","answers":["sintió"]},{"display":"tuvo","answers":["tuvo"]}],"policy":{"accents":"strict"}}','published','L2-U11-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado-11','es2-proyectos-y-metas-pasado','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué meta estableció Lina?","input":"sentence"},{"prompt":"¿Qué acciones realizó?","input":"sentence"},{"prompt":"¿Cómo se sintió al final?","input":"sentence"}],"text":"Hace dos años, Lina estableció una meta difícil: terminar un proyecto comunitario. Organizó un equipo, comunicó el plan y pidió ayuda. Cuando celebraron los resultados, sintió que cada decisión había valido la pena."}','{"items":[{"display":"Terminar un proyecto comunitario.","answers":["Terminar un proyecto comunitario."]},{"display":"Organizó un equipo, comunicó el plan y pidió ayuda.","answers":["Organizó un equipo, comunicó el plan y pidió ayuda."]},{"display":"Sintió que cada decisión había valido la pena.","answers":["Sintió que cada decisión había valido la pena."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U11-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado-12','es2-proyectos-y-metas-pasado','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Proyectos y metas · pasado\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Hace dos años, Lina estableció una meta difícil: terminar un proyecto comunitario. Organizó un equipo, comunicó el plan y pidió ayuda. Cuando celebraron los resultados, sintió que cada decisión había valido la pena."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U11-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado-13','es2-proyectos-y-metas-pasado','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: Sintió que cada decisión había valido la pena."},{"id":"B","text":"Respuesta: Organizó un equipo, comunicó el plan y pidió ayuda."},{"id":"C","text":"Respuesta: Terminar un proyecto comunitario."},{"id":"D","text":"Pregunta: ¿Cómo se sintió al final?"},{"id":"E","text":"Pregunta: ¿Qué meta estableció Lina?"},{"id":"F","text":"Pregunta: ¿Qué acciones realizó?"}]}','{"order":["E","C","F","B","D","A"],"policy":{"accents":"strict"}}','published','L2-U11-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado-14','es2-proyectos-y-metas-pasado','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Organizó un equipo, comunicó el plan y pidió ayuda."},{"id":"B","text":"Cuando celebraron los resultados, sintió que cada decisión había valido la pena."},{"id":"C","text":"Hace dos años, Lina estableció una meta difícil: terminar un proyecto comunitario."}]}','{"order":["C","A","B"],"policy":{"accents":"strict"}}','published','L2-U11-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado-15','es2-proyectos-y-metas-pasado','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre proyectos y metas · pasado es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre proyectos y metas · pasado es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U11-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado-16','es2-proyectos-y-metas-pasado','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"עתיד = ___","input":"text"},{"prompt":"להקים = ___","input":"text"},{"prompt":"להרגיש = ___","input":"text"},{"prompt":"תוצאות = ___","input":"text"},{"prompt":"**la decisión** · tener · un gran impacto","input":"text"},{"prompt":"**ella** · sentir · al terminar","input":"text"},{"prompt":"**ellos** · celebrar · al final","input":"text"},{"prompt":"**tú** · pedir · la semana pasada","input":"text"},{"prompt":"**nosotros** · comunicar · ayer","input":"text"},{"prompt":"**Lina** · organizar · después","input":"text"}]}','{"items":[{"display":"Futuro","answers":["Futuro"],"policy":{"accents":"lenient"}},{"display":"Establecer","answers":["Establecer"],"policy":{"accents":"lenient"}},{"display":"Sentir","answers":["Sentir"],"policy":{"accents":"lenient"}},{"display":"Resultados","answers":["Resultados"],"policy":{"accents":"lenient"}},{"display":"tuvo","answers":["tuvo"]},{"display":"sintió","answers":["sintió"]},{"display":"celebraron","answers":["celebraron"]},{"display":"pediste","answers":["pediste"]},{"display":"comunicamos","answers":["comunicamos"]},{"display":"organizó","answers":["organizó"]}],"policy":{"accents":"strict"}}','published','L2-U11-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-pasado-17','es2-proyectos-y-metas-pasado','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Hace dos años, Lina estableció una meta difícil: terminar un proyecto comunitario. Organizó un equipo, comunicó el plan y pidió ayuda."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U11-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro','es-2','es-2-goals','פרויקטים ומטרות: עתיד','Proyectos y metas · futuro','לדבר ולכתוב על הנושא „פרויקטים ומטרות: עתיד“ בספרדית, תוך שימוש במבנים: Metas, visualización y futuro.','derived','[{"he":"דקדוק בשימוש","target":"Metas, visualización y futuro"},{"he":"אוצר מילים: פרויקטים ומטרות: עתיד","target":"Proyectos y metas · futuro"}]','["Metas, visualización y futuro"]','{"rules":[],"examples":["El año próximo voy a lograr la meta.","Ella organizará el proyecto.","Nosotros estableceremos objetivos.","En el futuro ayudaremos."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Acción","he":"פעולה"},{"term":"Alcanzar","he":"להגיע"},{"term":"Ayudar","he":"לעזור"},{"term":"Cambio","he":"שינוי"},{"term":"Celebrar","he":"לחגוג"},{"term":"Comunicar","he":"לתקשר"},{"term":"Contribución","he":"תרומה"},{"term":"Decisión","he":"החלטה"},{"term":"Establecer","he":"להקים"},{"term":"Futuro","he":"עתיד"},{"term":"Hacer","he":"לעשות / עשיתי"},{"term":"Lograr","he":"להשיג"},{"term":"Meta","he":"מטרה"},{"term":"Objetivo","he":"יעד"},{"term":"Pasado","he":"עבר"},{"term":"plan","he":"תוכנית"},{"term":"Proyecto","he":"פרויקט"},{"term":"Resultados","he":"תוצאות"},{"term":"Sentir","he":"להרגיש"},{"term":"Voluntario","he":"מתנדב / התנדבות"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/985525722/goals-and-proyects-conversational-spanish-flash-cards/"}]','published','workbook L2 unit 12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro-01','es2-proyectos-y-metas-futuro','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"תרומה ___","input":"text"},{"prompt":"שינוי ___","input":"text"},{"prompt":"תוצאות ___","input":"text"},{"prompt":"להגיע ___","input":"text"},{"prompt":"להקים ___","input":"text"},{"prompt":"לעשות ___","input":"text"}]}','{"items":[{"display":"Contribución","answers":["Contribución"]},{"display":"Cambio","answers":["Cambio"]},{"display":"Resultados","answers":["Resultados"]},{"display":"Alcanzar","answers":["Alcanzar"]},{"display":"Establecer","answers":["Establecer"]},{"display":"Hacer","answers":["Hacer"]}],"policy":{"accents":"lenient"}}','published','L2-U12-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro-02','es2-proyectos-y-metas-futuro','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Contribución","Cambio","Resultados","Alcanzar","Establecer","Hacer","Voluntario","Pasado"],"right":[{"id":"A","text":"תרומה"},{"id":"B","text":"לעשות"},{"id":"C","text":"תוצאות"},{"id":"D","text":"מתנדב"},{"id":"E","text":"עבר"},{"id":"F","text":"שינוי"},{"id":"G","text":"להקים"},{"id":"H","text":"להגיע"}]}','{"pairs":["A","F","C","H","G","B","D","E"],"policy":{"accents":"lenient"}}','published','L2-U12-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro-03','es2-proyectos-y-metas-futuro','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"תרומה","input":"choice","options":["Resultados","Cambio","Contribución"]},{"prompt":"שינוי","input":"choice","options":["Resultados","Cambio","Ayudar"]},{"prompt":"תוצאות","input":"choice","options":["Hacer","Celebrar","Resultados"]},{"prompt":"להגיע","input":"choice","options":["Alcanzar","Ayudar","Meta"]},{"prompt":"להקים","input":"choice","options":["Objetivo","Acción","Establecer"]},{"prompt":"לעשות","input":"choice","options":["Pasado","Hacer","Objetivo"]}]}','{"items":[{"display":"Contribución","choice":2},{"display":"Cambio","choice":1},{"display":"Resultados","choice":2},{"display":"Alcanzar","choice":0},{"display":"Establecer","choice":2},{"display":"Hacer","choice":1}],"policy":{"accents":"lenient"}}','published','L2-U12-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro-04','es2-proyectos-y-metas-futuro','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"לחגוג = ___","input":"bank"},{"prompt":"פעולה = ___","input":"bank"},{"prompt":"לתקשר = ___","input":"bank"},{"prompt":"יעד = ___","input":"bank"}],"wordbank":["Comunicar","proyecto","Acción","Celebrar","voluntario","Objetivo"],"text":"El próximo año, Marcos establecerá tres objetivos. Ahorrará para un curso, participará como {{1}} y aprenderá una habilidad nueva. Para lograrlo, dividirá cada {{2}} en acciones pequeñas y celebrará cada resultado."}','{"items":[{"display":"voluntario","answers":["voluntario"]},{"display":"proyecto","answers":["proyecto"]},{"display":"Celebrar","answers":["Celebrar"]},{"display":"Acción","answers":["Acción"]},{"display":"Comunicar","answers":["Comunicar"]},{"display":"Objetivo","answers":["Objetivo"]}],"policy":{"accents":"strict"}}','published','L2-U12-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro-05','es2-proyectos-y-metas-futuro','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["hacer","meta","realidad","haga","a","meta","Cuál","tu","vas","se","es","cuando","tu","Qué"]},{"prompt":"","input":"tokens","tokens":["para","Qué","hacer","tu","vas","continuación","cumplir","a","con","a","meta"]},{"prompt":"","input":"tokens","tokens":["meta","logres","a","Cómo","te","vas","tu","sentir","cuando"]},{"prompt":"","input":"tokens","tokens":["Qué","vas","a","hacer","alcanzar","tu","de","después","meta"]}]}','{"items":[{"display":"¿Cuál es tu meta? ¿Qué vas a hacer cuando tu meta se haga realidad?","answers":["¿Cuál es tu meta? ¿Qué vas a hacer cuando tu meta se haga realidad?"]},{"display":"¿Qué vas a hacer a continuación para cumplir con tu meta?","answers":["¿Qué vas a hacer a continuación para cumplir con tu meta?"]},{"display":"¿Cómo te vas a sentir cuando logres tu meta?","answers":["¿Cómo te vas a sentir cuando logres tu meta?"]},{"display":"¿Qué vas a hacer después de alcanzar tu meta?","answers":["¿Qué vas a hacer después de alcanzar tu meta?"]}],"policy":{"accents":"strict"}}','published','L2-U12-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro-06','es2-proyectos-y-metas-futuro','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"El año próximo voy a lograré la meta.","input":"sentence"},{"prompt":"Ella organizarán el proyecto.","input":"sentence"},{"prompt":"Nosotros estableceré objetivos.","input":"sentence"},{"prompt":"En el futuro ayudamos ayer.","input":"sentence"}]}','{"items":[{"display":"El año próximo voy a lograr la meta.","answers":["El año próximo voy a lograr la meta."]},{"display":"Ella organizará el proyecto.","answers":["Ella organizará el proyecto."]},{"display":"Nosotros estableceremos objetivos.","answers":["Nosotros estableceremos objetivos."]},{"display":"En el futuro ayudaremos.","answers":["En el futuro ayudaremos."]}],"policy":{"accents":"strict"}}','published','L2-U12-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro-07','es2-proyectos-y-metas-futuro','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["El año próximo voy a lograré la meta.","El año próximo voy a lograr la meta."]},{"prompt":"","input":"choice","options":["Ella organizarán el proyecto.","Ella organizará el proyecto."]},{"prompt":"","input":"choice","options":["Nosotros estableceremos objetivos.","Nosotros estableceré objetivos."]},{"prompt":"","input":"choice","options":["En el futuro ayudaremos.","En el futuro ayudamos ayer."]}]}','{"items":[{"display":"El año próximo voy a lograr la meta.","choice":1},{"display":"Ella organizará el proyecto.","choice":1},{"display":"Nosotros estableceré objetivos.","choice":1},{"display":"En el futuro ayudamos ayer.","choice":1}],"policy":{"accents":"strict"}}','published','L2-U12-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro-08','es2-proyectos-y-metas-futuro','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**Marcos** · establecer · el próximo año","input":"text"},{"prompt":"**yo** · ahorrar · desde mañana","input":"text"},{"prompt":"**ellos** · participar · el año próximo","input":"text"},{"prompt":"**tú** · aprender · en el futuro","input":"text"}]}','{"items":[{"display":"establecerá","answers":["establecerá"]},{"display":"ahorraré","answers":["ahorraré"]},{"display":"participarán","answers":["participarán"]},{"display":"aprenderás","answers":["aprenderás"]}],"policy":{"accents":"strict"}}','published','L2-U12-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro-09','es2-proyectos-y-metas-futuro','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Cuál es tu meta? ¿Qué vas a hacer cuando tu meta se haga realidad?\n¿Qué vas a hacer a continuación para cumplir con tu meta?\n¿Cómo te vas a sentir cuando logres tu meta?\n¿Qué vas a hacer después de alcanzar tu meta?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U12-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro-10','es2-proyectos-y-metas-futuro','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**Marcos** · establecer · el próximo año","input":"text"},{"prompt":"**yo** · ahorrar · desde mañana","input":"text"},{"prompt":"**ellos** · participar · el año próximo","input":"text"},{"prompt":"**tú** · aprender · en el futuro","input":"text"},{"prompt":"**él** · dividir · cada proyecto","input":"text"},{"prompt":"**nosotros** · celebrar · cada resultado","input":"text"},{"prompt":"**vosotros** · lograr · pronto","input":"text"},{"prompt":"**ella** · tener · tres objetivos","input":"text"}]}','{"items":[{"display":"establecerá","answers":["establecerá"]},{"display":"ahorraré","answers":["ahorraré"]},{"display":"participarán","answers":["participarán"]},{"display":"aprenderás","answers":["aprenderás"]},{"display":"dividirá","answers":["dividirá"]},{"display":"celebraremos","answers":["celebraremos"]},{"display":"lograréis","answers":["lograréis"]},{"display":"tendrá","answers":["tendrá"]}],"policy":{"accents":"strict"}}','published','L2-U12-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro-11','es2-proyectos-y-metas-futuro','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Cuántos objetivos tendrá Marcos?","input":"sentence"},{"prompt":"¿Cómo organizará sus proyectos?","input":"sentence"},{"prompt":"¿Qué celebrará?","input":"sentence"}],"text":"El próximo año, Marcos establecerá tres objetivos. Ahorrará para un curso, participará como voluntario y aprenderá una habilidad nueva. Para lograrlo, dividirá cada proyecto en acciones pequeñas y celebrará cada resultado."}','{"items":[{"display":"Tres.","answers":["Tres."]},{"display":"Dividirá cada proyecto en acciones pequeñas.","answers":["Dividirá cada proyecto en acciones pequeñas."]},{"display":"Cada resultado.","answers":["Cada resultado."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U12-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro-12','es2-proyectos-y-metas-futuro','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Proyectos y metas · futuro\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["El próximo año, Marcos establecerá tres objetivos. Ahorrará para un curso, participará como voluntario y aprenderá una habilidad nueva. Para lograrlo, dividirá cada proyecto en acciones pequeñas y celebrará cada resultado."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U12-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro-13','es2-proyectos-y-metas-futuro','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Cómo organizará sus proyectos?"},{"id":"B","text":"Pregunta: ¿Cuántos objetivos tendrá Marcos?"},{"id":"C","text":"Respuesta: Dividirá cada proyecto en acciones pequeñas."},{"id":"D","text":"Respuesta: Tres."},{"id":"E","text":"Pregunta: ¿Qué celebrará?"},{"id":"F","text":"Respuesta: Cada resultado."}]}','{"order":["B","D","A","C","E","F"],"policy":{"accents":"strict"}}','published','L2-U12-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro-14','es2-proyectos-y-metas-futuro','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Para lograrlo, dividirá cada proyecto en acciones pequeñas y celebrará cada resultado."},{"id":"B","text":"Ahorrará para un curso, participará como voluntario y aprenderá una habilidad nueva."},{"id":"C","text":"El próximo año, Marcos establecerá tres objetivos."}]}','{"order":["C","B","A"],"policy":{"accents":"strict"}}','published','L2-U12-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro-15','es2-proyectos-y-metas-futuro','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre proyectos y metas · futuro es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre proyectos y metas · futuro es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U12-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro-16','es2-proyectos-y-metas-futuro','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"תוצאות = ___","input":"text"},{"prompt":"להגיע = ___","input":"text"},{"prompt":"להקים = ___","input":"text"},{"prompt":"לעשות = ___","input":"text"},{"prompt":"**ella** · tener · tres objetivos","input":"text"},{"prompt":"**vosotros** · lograr · pronto","input":"text"},{"prompt":"**nosotros** · celebrar · cada resultado","input":"text"},{"prompt":"**él** · dividir · cada proyecto","input":"text"},{"prompt":"**tú** · aprender · en el futuro","input":"text"},{"prompt":"**ellos** · participar · el año próximo","input":"text"}]}','{"items":[{"display":"Resultados","answers":["Resultados"],"policy":{"accents":"lenient"}},{"display":"Alcanzar","answers":["Alcanzar"],"policy":{"accents":"lenient"}},{"display":"Establecer","answers":["Establecer"],"policy":{"accents":"lenient"}},{"display":"Hacer","answers":["Hacer"],"policy":{"accents":"lenient"}},{"display":"tendrá","answers":["tendrá"]},{"display":"lograréis","answers":["lograréis"]},{"display":"celebraremos","answers":["celebraremos"]},{"display":"dividirá","answers":["dividirá"]},{"display":"aprenderás","answers":["aprenderás"]},{"display":"participarán","answers":["participarán"]}],"policy":{"accents":"strict"}}','published','L2-U12-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-proyectos-y-metas-futuro-17','es2-proyectos-y-metas-futuro','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["El próximo año, Marcos establecerá tres objetivos. Ahorrará para un curso, participará como voluntario y aprenderá una habilidad nueva."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U12-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro','es-2','es-2-goals','התנדבות ועזרה לזולת','Voluntariado y ayuda al otro','לדבר ולכתוב על הנושא „התנדבות ועזרה לזולת“ בספרדית, תוך שימוש במבנים: Pasado simple, imperfecto e impacto social.','derived','[{"he":"דקדוק בשימוש","target":"Pasado simple, imperfecto e impacto social"},{"he":"אוצר מילים: התנדבות ועזרה לזולת","target":"Voluntariado y ayuda al otro"}]','["Pasado simple, imperfecto e impacto social"]','{"rules":[],"examples":["Cuando era voluntario ayudaba cada semana.","La campaña tenía impacto cada día.","Ayer compartí mi tiempo.","La organización necesitaba apoyo."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Acción","he":"פעולה"},{"term":"Apoyo","he":"תמיכה"},{"term":"Ayuda","he":"עזרה"},{"term":"Ayudar","he":"לעזור"},{"term":"Bondad","he":"חסד"},{"term":"Caridad","he":"צדקה"},{"term":"Compartir","he":"לשתף"},{"term":"Comunidad","he":"קהילה"},{"term":"Contribución","he":"תרומה"},{"term":"Cuidado","he":"אכפתיות"},{"term":"Dar (di)","he":"נתתי / לתת"},{"term":"Habilidades","he":"יכולות"},{"term":"Hacer","he":"לעשות / עשיתי"},{"term":"Impacto","he":"השפעה"},{"term":"Local","he":"מקומי"},{"term":"Necesitar","he":"להצטרך"},{"term":"Organización sin fines de lucro","he":"ארגון ללא מטרות רווח"},{"term":"Personas","he":"אנשים"},{"term":"Tiempo","he":"זמן"},{"term":"Venir","he":"לבוא"},{"term":"Voluntario","he":"מתנדב / התנדבות"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/867296099/conversational-spanish-volunteering-flash-cards/"}]','published','workbook L2 unit 13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro-01','es2-voluntariado-y-ayuda-al-otro','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"להצטרך ___","input":"text"},{"prompt":"אכפתיות ___","input":"text"},{"prompt":"עזרה ___","input":"text"},{"prompt":"תמיכה ___","input":"text"},{"prompt":"קהילה ___","input":"text"},{"prompt":"תרומה ___","input":"text"}]}','{"items":[{"display":"Necesitar","answers":["Necesitar"]},{"display":"Cuidado","answers":["Cuidado"]},{"display":"Ayuda","answers":["Ayuda"]},{"display":"Apoyo","answers":["Apoyo"]},{"display":"Comunidad","answers":["Comunidad"]},{"display":"Contribución","answers":["Contribución"]}],"policy":{"accents":"lenient"}}','published','L2-U13-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro-02','es2-voluntariado-y-ayuda-al-otro','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Necesitar","Cuidado","Ayuda","Apoyo","Comunidad","Contribución","Personas","Impacto"],"right":[{"id":"A","text":"תמיכה"},{"id":"B","text":"קהילה"},{"id":"C","text":"להצטרך"},{"id":"D","text":"אכפתיות"},{"id":"E","text":"עזרה"},{"id":"F","text":"אנשים"},{"id":"G","text":"תרומה"},{"id":"H","text":"השפעה"}]}','{"pairs":["C","D","E","A","B","G","F","H"],"policy":{"accents":"lenient"}}','published','L2-U13-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro-03','es2-voluntariado-y-ayuda-al-otro','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"להצטרך","input":"choice","options":["Compartir","Ayudar","Necesitar"]},{"prompt":"אכפתיות","input":"choice","options":["Cuidado","Comunidad","Caridad"]},{"prompt":"עזרה","input":"choice","options":["Ayuda","Venir","Dar"]},{"prompt":"תמיכה","input":"choice","options":["Ayudar","Dar","Apoyo"]},{"prompt":"קהילה","input":"choice","options":["Contribución","Ayudar","Comunidad"]},{"prompt":"תרומה","input":"choice","options":["Apoyo","Contribución","Ayuda"]}]}','{"items":[{"display":"Necesitar","choice":2},{"display":"Cuidado","choice":0},{"display":"Ayuda","choice":0},{"display":"Apoyo","choice":2},{"display":"Comunidad","choice":2},{"display":"Contribución","choice":1}],"policy":{"accents":"lenient"}}','published','L2-U13-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro-04','es2-voluntariado-y-ayuda-al-otro','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"לעשות = ___","input":"bank"}],"wordbank":["comunidad","local","impacto","Hacer","tiempo","personas"],"text":"Cuando Ana era voluntaria, ayudaba cada semana en una organización {{1}}. Compartía su {{2}} con {{3}} mayores y organizaba actividades. Un día creó una campaña que tuvo un gran {{4}} en la {{5}}."}','{"items":[{"display":"local","answers":["local"]},{"display":"tiempo","answers":["tiempo"]},{"display":"personas","answers":["personas"]},{"display":"impacto","answers":["impacto"]},{"display":"comunidad","answers":["comunidad"]},{"display":"Hacer","answers":["Hacer"]}],"policy":{"accents":"strict"}}','published','L2-U13-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro-05','es2-voluntariado-y-ayuda-al-otro','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["de","Por","qué","Puedes","una","lucro","organización","que","fines","admires","nombrar","sin"]},{"prompt":"","input":"tokens","tokens":["esta","organización","Qué","hacía"]},{"prompt":"","input":"tokens","tokens":["Cuál","organización","papel","en","tu","esta","aportabas","era","Qué"]},{"prompt":"","input":"tokens","tokens":["organización","esta","cerró","qué","Por"]}]}','{"items":[{"display":"¿Puedes nombrar una organización sin fines de lucro que admires? ¿Por qué?","answers":["¿Puedes nombrar una organización sin fines de lucro que admires? ¿Por qué?"]},{"display":"¿Qué hacía esta organización?","answers":["¿Qué hacía esta organización?"]},{"display":"¿Cuál era tu papel en esta organización? ¿Qué aportabas?","answers":["¿Cuál era tu papel en esta organización? ¿Qué aportabas?"]},{"display":"¿Por qué cerró esta organización?","answers":["¿Por qué cerró esta organización?"]}],"policy":{"accents":"strict"}}','published','L2-U13-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro-06','es2-voluntariado-y-ayuda-al-otro','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Cuando era voluntario ayudé cada semana.","input":"sentence"},{"prompt":"La campaña tuvo un impacto todos los días.","input":"sentence"},{"prompt":"Ayer compartía mi tiempo una vez.","input":"sentence"},{"prompt":"La organización necesitaban apoyo.","input":"sentence"}]}','{"items":[{"display":"Cuando era voluntario ayudaba cada semana.","answers":["Cuando era voluntario ayudaba cada semana."]},{"display":"La campaña tenía impacto cada día.","answers":["La campaña tenía impacto cada día."]},{"display":"Ayer compartí mi tiempo.","answers":["Ayer compartí mi tiempo."]},{"display":"La organización necesitaba apoyo.","answers":["La organización necesitaba apoyo."]}],"policy":{"accents":"strict"}}','published','L2-U13-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro-07','es2-voluntariado-y-ayuda-al-otro','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Cuando era voluntario ayudaba cada semana.","Cuando era voluntario ayudé cada semana."]},{"prompt":"","input":"choice","options":["La campaña tuvo un impacto todos los días.","La campaña tenía impacto cada día."]},{"prompt":"","input":"choice","options":["Ayer compartí mi tiempo.","Ayer compartía mi tiempo una vez."]},{"prompt":"","input":"choice","options":["La organización necesitaban apoyo.","La organización necesitaba apoyo."]}]}','{"items":[{"display":"Cuando era voluntario ayudé cada semana.","choice":1},{"display":"La campaña tenía impacto cada día.","choice":1},{"display":"Ayer compartía mi tiempo una vez.","choice":1},{"display":"La organización necesitaba apoyo.","choice":1}],"policy":{"accents":"strict"}}','published','L2-U13-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro-08','es2-voluntariado-y-ayuda-al-otro','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**Ana** · ser · cuando era voluntaria","input":"text"},{"prompt":"**ella** · ayudar · cada semana","input":"text"},{"prompt":"**Ana** · compartir · habitualmente","input":"text"},{"prompt":"**nosotros** · organizar · todos los meses","input":"text"}]}','{"items":[{"display":"era","answers":["era"]},{"display":"ayudaba","answers":["ayudaba"]},{"display":"compartía","answers":["compartía"]},{"display":"organizábamos","answers":["organizábamos"]}],"policy":{"accents":"strict"}}','published','L2-U13-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro-09','es2-voluntariado-y-ayuda-al-otro','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Puedes nombrar una organización sin fines de lucro que admires? ¿Por qué?\n¿Qué hicieron?\n¿Eres voluntario ahora?\n¿Qué hacía esta organización?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U13-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro-10','es2-voluntariado-y-ayuda-al-otro','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**Ana** · ser · cuando era voluntaria","input":"text"},{"prompt":"**ella** · ayudar · cada semana","input":"text"},{"prompt":"**Ana** · compartir · habitualmente","input":"text"},{"prompt":"**nosotros** · organizar · todos los meses","input":"text"},{"prompt":"**ella** · crear · un día","input":"text"},{"prompt":"**la campaña** · tener · un gran impacto","input":"text"},{"prompt":"**ellos** · colaborar · ayer","input":"text"},{"prompt":"**tú** · apoyar · la semana pasada","input":"text"}]}','{"items":[{"display":"era","answers":["era"]},{"display":"ayudaba","answers":["ayudaba"]},{"display":"compartía","answers":["compartía"]},{"display":"organizábamos","answers":["organizábamos"]},{"display":"creó","answers":["creó"]},{"display":"tuvo","answers":["tuvo"]},{"display":"colaboraron","answers":["colaboraron"]},{"display":"apoyaste","answers":["apoyaste"]}],"policy":{"accents":"strict"}}','published','L2-U13-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro-11','es2-voluntariado-y-ayuda-al-otro','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Con quién compartía su tiempo?","input":"sentence"},{"prompt":"¿Qué hacía habitualmente?","input":"sentence"},{"prompt":"¿Qué ocurrió un día?","input":"sentence"}],"text":"Cuando Ana era voluntaria, ayudaba cada semana en una organización local. Compartía su tiempo con personas mayores y organizaba actividades. Un día creó una campaña que tuvo un gran impacto en la comunidad."}','{"items":[{"display":"Con personas mayores.","answers":["Con personas mayores."]},{"display":"Ayudaba y organizaba actividades cada semana.","answers":["Ayudaba y organizaba actividades cada semana."]},{"display":"Creó una campaña con gran impacto.","answers":["Creó una campaña con gran impacto."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U13-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro-12','es2-voluntariado-y-ayuda-al-otro','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Voluntariado y ayuda al otro\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Cuando Ana era voluntaria, ayudaba cada semana en una organización local. Compartía su tiempo con personas mayores y organizaba actividades. Un día creó una campaña que tuvo un gran impacto en la comunidad."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U13-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro-13','es2-voluntariado-y-ayuda-al-otro','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: Ayudaba y organizaba actividades cada semana."},{"id":"B","text":"Pregunta: ¿Qué ocurrió un día?"},{"id":"C","text":"Pregunta: ¿Con quién compartía su tiempo?"},{"id":"D","text":"Respuesta: Creó una campaña con gran impacto."},{"id":"E","text":"Respuesta: Con personas mayores."},{"id":"F","text":"Pregunta: ¿Qué hacía habitualmente?"}]}','{"order":["C","E","F","A","B","D"],"policy":{"accents":"strict"}}','published','L2-U13-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro-14','es2-voluntariado-y-ayuda-al-otro','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Un día creó una campaña que tuvo un gran impacto en la comunidad."},{"id":"B","text":"Cuando Ana era voluntaria, ayudaba cada semana en una organización local."},{"id":"C","text":"Compartía su tiempo con personas mayores y organizaba actividades."}]}','{"order":["B","C","A"],"policy":{"accents":"strict"}}','published','L2-U13-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro-15','es2-voluntariado-y-ayuda-al-otro','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre voluntariado y ayuda al otro es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre voluntariado y ayuda al otro es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U13-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro-16','es2-voluntariado-y-ayuda-al-otro','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"עזרה = ___","input":"text"},{"prompt":"תמיכה = ___","input":"text"},{"prompt":"קהילה = ___","input":"text"},{"prompt":"תרומה = ___","input":"text"},{"prompt":"**tú** · apoyar · la semana pasada","input":"text"},{"prompt":"**ellos** · colaborar · ayer","input":"text"},{"prompt":"**la campaña** · tener · un gran impacto","input":"text"},{"prompt":"**ella** · crear · un día","input":"text"},{"prompt":"**nosotros** · organizar · todos los meses","input":"text"},{"prompt":"**Ana** · compartir · habitualmente","input":"text"}]}','{"items":[{"display":"Ayuda","answers":["Ayuda"],"policy":{"accents":"lenient"}},{"display":"Apoyo","answers":["Apoyo"],"policy":{"accents":"lenient"}},{"display":"Comunidad","answers":["Comunidad"],"policy":{"accents":"lenient"}},{"display":"Contribución","answers":["Contribución"],"policy":{"accents":"lenient"}},{"display":"apoyaste","answers":["apoyaste"]},{"display":"colaboraron","answers":["colaboraron"]},{"display":"tuvo","answers":["tuvo"]},{"display":"creó","answers":["creó"]},{"display":"organizábamos","answers":["organizábamos"]},{"display":"compartía","answers":["compartía"]}],"policy":{"accents":"strict"}}','published','L2-U13-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-voluntariado-y-ayuda-al-otro-17','es2-voluntariado-y-ayuda-al-otro','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Cuando Ana era voluntaria, ayudaba cada semana en una organización local. Compartía su tiempo con personas mayores y organizaba actividades."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U13-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes','es-2','es-2-memories','רכילות','Chismes','לדבר ולכתוב על הנושא „רכילות“ בספרדית, תוך שימוש במבנים: Pasado simple y comparaciones.','derived','[{"he":"דקדוק בשימוש","target":"Pasado simple y comparaciones"},{"he":"אוצר מילים: רכילות","target":"Chismes"}]','["Pasado simple y comparaciones"]','{"rules":[],"examples":["Esta historia es falsa.","El chisme es peor.","Ayer yo conté un secreto.","Ella no lo compartió porque era falso."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Amigo","he":"חבר"},{"term":"Celebridad","he":"סלבריטאי"},{"term":"Cena","he":"ארוחת ערב"},{"term":"Chisme","he":"רכילות"},{"term":"Chismoso","he":"רכלן"},{"term":"Comparación","he":"השוואה"},{"term":"Comparaciones","he":"השוואות"},{"term":"Contar","he":"לספר"},{"term":"divertido","he":"משעשע / מצחיק / מהנה / מצחיק / / מהנה / מצחיק"},{"term":"Entrevista","he":"ראיון"},{"term":"Escuchar","he":"לשמוע / להקשיב / לשמוע / להקשיב"},{"term":"Escuela","he":"בית ספר"},{"term":"Falso","he":"שקרי / לא נכון / שקרי"},{"term":"Familia","he":"משפחה"},{"term":"Famoso","he":"מפורסם"},{"term":"Gracioso","he":"מצחיק"},{"term":"Grupo","he":"קבוצה / להקה / קבוצה"},{"term":"Historia","he":"סיפור / היסטוריה / סיפור"},{"term":"Imagen","he":"תמונה"},{"term":"Interesante","he":"מעניין / ת / מעניין"},{"term":"Inventar","he":"להמציא"},{"term":"Invitado","he":"אורח"},{"term":"Más","he":"יותר"},{"term":"Mejor","he":"טוב יותר"},{"term":"Menos","he":"פחות"},{"term":"Pareja","he":"זוג"},{"term":"Pasado","he":"עבר"},{"term":"Peligroso","he":"מסוכן"},{"term":"Peor","he":"גרוע יותר"},{"term":"Redes","he":"רשתות"},{"term":"Secreto","he":"סוד"},{"term":"Simple","he":"פשוט"},{"term":"Sociales","he":"חברתיות"},{"term":"Trabajo","he":"עבודה"},{"term":"Verdadero","he":"אמיתי / אמיתי / נכון"},{"term":"votar","he":"להצביע"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/865367283/conversational-spanish-chsimes-actualizado-flash-cards/"}]','published','workbook L2 unit 14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes-01','es2-chismes','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"עבר ___","input":"text"},{"prompt":"עבודה ___","input":"text"},{"prompt":"השוואה ___","input":"text"},{"prompt":"מסוכן ___","input":"text"},{"prompt":"השוואות ___","input":"text"},{"prompt":"אמיתי ___","input":"text"}]}','{"items":[{"display":"Pasado","answers":["Pasado"]},{"display":"Trabajo","answers":["Trabajo"]},{"display":"Comparación","answers":["Comparación"]},{"display":"Peligroso","answers":["Peligroso"]},{"display":"Comparaciones","answers":["Comparaciones"]},{"display":"Verdadero","answers":["Verdadero"]}],"policy":{"accents":"lenient"}}','published','L2-U14-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes-02','es2-chismes','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Pasado","Trabajo","Comparación","Peligroso","Comparaciones","Verdadero","Famoso","Gracioso"],"right":[{"id":"A","text":"עבר"},{"id":"B","text":"מסוכן"},{"id":"C","text":"מפורסם"},{"id":"D","text":"עבודה"},{"id":"E","text":"השוואות"},{"id":"F","text":"השוואה"},{"id":"G","text":"אמיתי"},{"id":"H","text":"מצחיק"}]}','{"pairs":["A","D","F","B","E","G","C","H"],"policy":{"accents":"lenient"}}','published','L2-U14-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes-03','es2-chismes','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"עבר","input":"choice","options":["Secreto","Pasado","Chisme"]},{"prompt":"עבודה","input":"choice","options":["Famoso","Trabajo","Pasado"]},{"prompt":"השוואה","input":"choice","options":["Comparación","Secreto","Famoso"]},{"prompt":"מסוכן","input":"choice","options":["Entrevista","Peor","Peligroso"]},{"prompt":"השוואות","input":"choice","options":["Familia","Comparaciones","Grupo"]},{"prompt":"אמיתי","input":"choice","options":["Historia","Verdadero","Redes"]}]}','{"items":[{"display":"Pasado","choice":1},{"display":"Trabajo","choice":1},{"display":"Comparación","choice":0},{"display":"Peligroso","choice":2},{"display":"Comparaciones","choice":1},{"display":"Verdadero","choice":1}],"policy":{"accents":"lenient"}}','published','L2-U14-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes-04','es2-chismes','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true}],"wordbank":["interesante","chisme","falso","celebridad","historia","amigo"],"text":"Ayer circuló un {{1}} {{2}} sobre una {{3}}. La {{4}} parecía {{5}}, pero nadie conocía la fuente. Julia comparó dos versiones, preguntó a un {{6}} y decidió no compartir el secreto en redes sociales."}','{"items":[{"display":"chisme","answers":["chisme"]},{"display":"falso","answers":["falso"]},{"display":"celebridad","answers":["celebridad"]},{"display":"historia","answers":["historia"]},{"display":"interesante","answers":["interesante"]},{"display":"amigo","answers":["amigo"]}],"policy":{"accents":"strict"}}','published','L2-U14-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes-05','es2-chismes','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["contar","qué","a","Por","la","le","piensas","que","gusta","chismes","gente"]},{"prompt":"","input":"tokens","tokens":["amigo","último","lo","Qué","de","un","escuchaste","que","fue"]},{"prompt":"","input":"tokens","tokens":["ayer","qué","hablaste","quién","y","sobre","Con"]},{"prompt":"","input":"tokens","tokens":["la","Qué","pasada","semana","el","chisme","o","escuela","la","en","trabajo","en","escuchaste"]}]}','{"items":[{"display":"¿Por qué piensas que a la gente le gusta contar chismes?","answers":["¿Por qué piensas que a la gente le gusta contar chismes?"]},{"display":"¿Qué fue lo último que escuchaste de un amigo?","answers":["¿Qué fue lo último que escuchaste de un amigo?"]},{"display":"¿Con quién hablaste ayer y sobre qué?","answers":["¿Con quién hablaste ayer y sobre qué?"]},{"display":"¿Qué chisme escuchaste en la escuela o en el trabajo la semana pasada?","answers":["¿Qué chisme escuchaste en la escuela o en el trabajo la semana pasada?"]}],"policy":{"accents":"strict"}}','published','L2-U14-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes-06','es2-chismes','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Este historia es falso.","input":"sentence"},{"prompt":"El chisme es más peor.","input":"sentence"},{"prompt":"Ayer yo contar un secreto.","input":"sentence"},{"prompt":"Ella no compartió porque era verdadero falso.","input":"sentence"}]}','{"items":[{"display":"Esta historia es falsa.","answers":["Esta historia es falsa."]},{"display":"El chisme es peor.","answers":["El chisme es peor."]},{"display":"Ayer yo conté un secreto.","answers":["Ayer yo conté un secreto."]},{"display":"Ella no lo compartió porque era falso.","answers":["Ella no lo compartió porque era falso."]}],"policy":{"accents":"strict"}}','published','L2-U14-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes-07','es2-chismes','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Esta historia es falsa.","Este historia es falso."]},{"prompt":"","input":"choice","options":["El chisme es peor.","El chisme es más peor."]},{"prompt":"","input":"choice","options":["Ayer yo contar un secreto.","Ayer yo conté un secreto."]},{"prompt":"","input":"choice","options":["Ella no lo compartió porque era falso.","Ella no compartió porque era verdadero falso."]}]}','{"items":[{"display":"Este historia es falso.","choice":1},{"display":"El chisme es más peor.","choice":1},{"display":"Ayer yo conté un secreto.","choice":1},{"display":"Ella no compartió porque era verdadero falso.","choice":1}],"policy":{"accents":"strict"}}','published','L2-U14-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes-08','es2-chismes','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**un chisme** · circular · ayer","input":"text"},{"prompt":"**la historia** · parecer · al principio","input":"text"},{"prompt":"**nadie** · conocer · en ese momento","input":"text"},{"prompt":"**Julia** · comparar · después","input":"text"}]}','{"items":[{"display":"circuló","answers":["circuló"]},{"display":"parecía","answers":["parecía"]},{"display":"conocía","answers":["conocía"]},{"display":"comparó","answers":["comparó"]}],"policy":{"accents":"strict"}}','published','L2-U14-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes-09','es2-chismes','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Por qué piensas que a la gente le gusta contar chismes?\n¿Qué fue lo último que escuchaste de un amigo?\n¿Con quién hablaste ayer y sobre qué?\n¿Qué chisme escuchaste en la escuela o en el trabajo la semana pasada?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U14-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes-10','es2-chismes','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**un chisme** · circular · ayer","input":"text"},{"prompt":"**la historia** · parecer · al principio","input":"text"},{"prompt":"**nadie** · conocer · en ese momento","input":"text"},{"prompt":"**Julia** · comparar · después","input":"text"},{"prompt":"**tú** · preguntar · ayer","input":"text"},{"prompt":"**ella** · decidir · al final","input":"text"},{"prompt":"**ellos** · compartir · la semana pasada","input":"text"},{"prompt":"**el secreto** · ser · falso","input":"text"}]}','{"items":[{"display":"circuló","answers":["circuló"]},{"display":"parecía","answers":["parecía"]},{"display":"conocía","answers":["conocía"]},{"display":"comparó","answers":["comparó"]},{"display":"preguntaste","answers":["preguntaste"]},{"display":"decidió","answers":["decidió"]},{"display":"compartieron","answers":["compartieron"]},{"display":"era","answers":["era"]}],"policy":{"accents":"strict"}}','published','L2-U14-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes-11','es2-chismes','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Cómo era el chisme?","input":"sentence"},{"prompt":"¿Qué comparó Julia?","input":"sentence"},{"prompt":"¿Qué decidió no hacer?","input":"sentence"}],"text":"Ayer circuló un chisme falso sobre una celebridad. La historia parecía interesante, pero nadie conocía la fuente. Julia comparó dos versiones, preguntó a un amigo y decidió no compartir el secreto en redes sociales."}','{"items":[{"display":"Era falso.","answers":["Era falso."]},{"display":"Dos versiones.","answers":["Dos versiones."]},{"display":"No compartir el secreto en redes sociales.","answers":["No compartir el secreto en redes sociales."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U14-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes-12','es2-chismes','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Chismes\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Ayer circuló un chisme falso sobre una celebridad. La historia parecía interesante, pero nadie conocía la fuente. Julia comparó dos versiones, preguntó a un amigo y decidió no compartir el secreto en redes sociales."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U14-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes-13','es2-chismes','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: Era falso."},{"id":"B","text":"Pregunta: ¿Qué comparó Julia?"},{"id":"C","text":"Pregunta: ¿Cómo era el chisme?"},{"id":"D","text":"Respuesta: No compartir el secreto en redes sociales."},{"id":"E","text":"Pregunta: ¿Qué decidió no hacer?"},{"id":"F","text":"Respuesta: Dos versiones."}]}','{"order":["C","A","B","F","E","D"],"policy":{"accents":"strict"}}','published','L2-U14-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes-14','es2-chismes','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Julia comparó dos versiones, preguntó a un amigo y decidió no compartir el secreto en redes sociales."},{"id":"B","text":"La historia parecía interesante, pero nadie conocía la fuente."},{"id":"C","text":"Ayer circuló un chisme falso sobre una celebridad."}]}','{"order":["C","B","A"],"policy":{"accents":"strict"}}','published','L2-U14-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes-15','es2-chismes','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre chismes es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre chismes es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U14-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes-16','es2-chismes','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"השוואה = ___","input":"text"},{"prompt":"מסוכן = ___","input":"text"},{"prompt":"השוואות = ___","input":"text"},{"prompt":"אמיתי = ___","input":"text"},{"prompt":"**el secreto** · ser · falso","input":"text"},{"prompt":"**ellos** · compartir · la semana pasada","input":"text"},{"prompt":"**ella** · decidir · al final","input":"text"},{"prompt":"**tú** · preguntar · ayer","input":"text"},{"prompt":"**Julia** · comparar · después","input":"text"},{"prompt":"**nadie** · conocer · en ese momento","input":"text"}]}','{"items":[{"display":"Comparación","answers":["Comparación"],"policy":{"accents":"lenient"}},{"display":"Peligroso","answers":["Peligroso"],"policy":{"accents":"lenient"}},{"display":"Comparaciones","answers":["Comparaciones"],"policy":{"accents":"lenient"}},{"display":"Verdadero","answers":["Verdadero"],"policy":{"accents":"lenient"}},{"display":"era","answers":["era"]},{"display":"compartieron","answers":["compartieron"]},{"display":"decidió","answers":["decidió"]},{"display":"preguntaste","answers":["preguntaste"]},{"display":"comparó","answers":["comparó"]},{"display":"conocía","answers":["conocía"]}],"policy":{"accents":"strict"}}','published','L2-U14-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-chismes-17','es2-chismes','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Ayer circuló un chisme falso sobre una celebridad. La historia parecía interesante, pero nadie conocía la fuente."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U14-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion','es-2','es-2-plans','רילוקיישן','Reubicación','לדבר ולכתוב על הנושא „רילוקיישן“ בספרדית, תוך שימוש במבנים: Planes, futuro y lenguaje de adaptación.','derived','[{"he":"דקדוק בשימוש","target":"Planes, futuro y lenguaje de adaptación"},{"he":"אוצר מילים: רילוקיישן","target":"Reubicación"}]','["Planes, futuro y lenguaje de adaptación"]','{"rules":[],"examples":["Me voy a mudar en julio.","Encontraré un apartamento pronto.","La ciudad es mejor.","Ellos harán las maletas."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Aeropuerto","he":"שדה תעופה"},{"term":"Ahorrar dinero","he":"לחסוך כסף"},{"term":"Amigo","he":"חבר"},{"term":"Ansioso","he":"חרד"},{"term":"Aprender el idioma","he":"ללמוד את השפה"},{"term":"Asustado","he":"מפוחד"},{"term":"Barrio","he":"שכונה"},{"term":"Biblioteca","he":"ספרייה"},{"term":"Buscar","he":"לחפש"},{"term":"Centro comercial","he":"קניון"},{"term":"Cine","he":"קולנוע"},{"term":"Ciudad","he":"עיר"},{"term":"Compañero","he":"עמית / חבר"},{"term":"Emocionado","he":"נרגש"},{"term":"Encontrar un apartamento","he":"למצוא דירה"},{"term":"Encontrar un trabajo","he":"למצוא עבודה"},{"term":"Escuela","he":"בית ספר"},{"term":"Estación de tren","he":"תחנת רכבת"},{"term":"Familia","he":"משפחה"},{"term":"Farmacia","he":"בית מרקחת"},{"term":"Feliz","he":"שמח"},{"term":"Grupo","he":"קבוצה / להקה / קבוצה"},{"term":"Hacer amigos","he":"לעשות חברים"},{"term":"Hacer las maletas","he":"לארוז מזוודות"},{"term":"Haré…","he":"אני אעשה..."},{"term":"Hospital","he":"בית חולים"},{"term":"Hotel","he":"מלון"},{"term":"Más","he":"יותר"},{"term":"Me mudaré…","he":"אני אעבור דירה ל..."},{"term":"Mejor","he":"טוב יותר"},{"term":"Mejorará…","he":"זה ישתפר..."},{"term":"Menos","he":"פחות"},{"term":"Mercado","he":"שוק"},{"term":"Mudarse","he":"לעבור דירה"},{"term":"Parque","he":"פארק"},{"term":"Peor","he":"גרוע יותר"},{"term":"Restaurante","he":"מסעדה"},{"term":"Supermercado","he":"סופרמרקט"},{"term":"Triste","he":"עצוב"},{"term":"Universidad","he":"אוניברסיטה"},{"term":"Viajar","he":"לטייל / לנסוע / לנסוע"},{"term":"Vivir","he":"לחיות"},{"term":"Voy a…","he":"אני הולך/ת ל..."}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/867385502/conversational-spanish-relocation-flash-cards/"}]','published','workbook L2 unit 15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion-01','es2-reubicacion','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"זה ישתפר... ___","input":"text"},{"prompt":"קבוצה ___","input":"text"},{"prompt":"שדה תעופה ___","input":"text"},{"prompt":"ללמוד את השפה ___","input":"text"},{"prompt":"ספרייה ___","input":"text"},{"prompt":"אוניברסיטה ___","input":"text"}]}','{"items":[{"display":"Mejorará…","answers":["Mejorará…"]},{"display":"Grupo","answers":["Grupo"]},{"display":"Aeropuerto","answers":["Aeropuerto"]},{"display":"Aprender el idioma","answers":["Aprender el idioma"]},{"display":"Biblioteca","answers":["Biblioteca"]},{"display":"Universidad","answers":["Universidad"]}],"policy":{"accents":"lenient"}}','published','L2-U15-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion-02','es2-reubicacion','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Mejorará…","Grupo","Aeropuerto","Aprender el idioma","Biblioteca","Universidad","Más","Farmacia"],"right":[{"id":"A","text":"זה ישתפר..."},{"id":"B","text":"יותר"},{"id":"C","text":"שדה תעופה"},{"id":"D","text":"אוניברסיטה"},{"id":"E","text":"ספרייה"},{"id":"F","text":"בית מרקחת"},{"id":"G","text":"ללמוד את השפה"},{"id":"H","text":"קבוצה"}]}','{"pairs":["A","H","C","G","E","D","B","F"],"policy":{"accents":"lenient"}}','published','L2-U15-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion-03','es2-reubicacion','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"זה ישתפר...","input":"choice","options":["Mejorará…","Hotel","Aprender el idioma"]},{"prompt":"קבוצה","input":"choice","options":["Cine","Grupo","Farmacia"]},{"prompt":"שדה תעופה","input":"choice","options":["Mudarse","Ahorrar dinero","Aeropuerto"]},{"prompt":"ללמוד את השפה","input":"choice","options":["Aprender el idioma","Supermercado","Mercado"]},{"prompt":"ספרייה","input":"choice","options":["Aeropuerto","Biblioteca","Hospital"]},{"prompt":"אוניברסיטה","input":"choice","options":["Universidad","Centro comercial","Vivir"]}]}','{"items":[{"display":"Mejorará…","choice":0},{"display":"Grupo","choice":1},{"display":"Aeropuerto","choice":2},{"display":"Aprender el idioma","choice":0},{"display":"Biblioteca","choice":1},{"display":"Universidad","choice":0}],"policy":{"accents":"lenient"}}','published','L2-U15-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion-04','es2-reubicacion','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"למצוא דירה = ___","input":"bank"},{"prompt":"לעשות חברים = ___","input":"bank"}],"wordbank":["ansioso","emocionado","Encontrar un apartamento","Hacer amigos","ciudad","buscar"],"text":"Dentro de seis meses, Amir se mudará a otra {{1}}. Va a {{2}} un apartamento cerca de la estación, aprenderá el idioma y encontrará un trabajo. Está {{3}}, aunque también se siente un poco {{4}}."}','{"items":[{"display":"ciudad","answers":["ciudad"]},{"display":"buscar","answers":["buscar"]},{"display":"emocionado","answers":["emocionado"]},{"display":"ansioso","answers":["ansioso"]},{"display":"Encontrar un apartamento","answers":["Encontrar un apartamento"]},{"display":"Hacer amigos","answers":["Hacer amigos"]}],"policy":{"accents":"strict"}}','published','L2-U15-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion-05','es2-reubicacion','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["mudarte","A","dónde","Quieres"]},{"prompt":"","input":"tokens","tokens":["Con","quién","a","te","vas","mudar"]},{"prompt":"","input":"tokens","tokens":["de","harás","Qué","mudarte","antes"]},{"prompt":"","input":"tokens","tokens":["Qué","después","mejorará","te","de","que","mudes"]}]}','{"items":[{"display":"¿Quieres mudarte? ¿A dónde?","answers":["¿Quieres mudarte? ¿A dónde?"]},{"display":"¿Con quién te vas a mudar?","answers":["¿Con quién te vas a mudar?"]},{"display":"¿Qué harás antes de mudarte?","answers":["¿Qué harás antes de mudarte?"]},{"display":"¿Qué mejorará después de que te mudes?","answers":["¿Qué mejorará después de que te mudes?"]}],"policy":{"accents":"strict"}}','published','L2-U15-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion-06','es2-reubicacion','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Me voy mudar en julio.","input":"sentence"},{"prompt":"Encontraré un apartamento ayer.","input":"sentence"},{"prompt":"La ciudad es más mejor.","input":"sentence"},{"prompt":"Ellos hará las maletas.","input":"sentence"}]}','{"items":[{"display":"Me voy a mudar en julio.","answers":["Me voy a mudar en julio."]},{"display":"Encontraré un apartamento pronto.","answers":["Encontraré un apartamento pronto."]},{"display":"La ciudad es mejor.","answers":["La ciudad es mejor."]},{"display":"Ellos harán las maletas.","answers":["Ellos harán las maletas."]}],"policy":{"accents":"strict"}}','published','L2-U15-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion-07','es2-reubicacion','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Me voy mudar en julio.","Me voy a mudar en julio."]},{"prompt":"","input":"choice","options":["Encontraré un apartamento pronto.","Encontraré un apartamento ayer."]},{"prompt":"","input":"choice","options":["La ciudad es mejor.","La ciudad es más mejor."]},{"prompt":"","input":"choice","options":["Ellos hará las maletas.","Ellos harán las maletas."]}]}','{"items":[{"display":"Me voy a mudar en julio.","choice":1},{"display":"Encontraré un apartamento ayer.","choice":1},{"display":"La ciudad es más mejor.","choice":1},{"display":"Ellos harán las maletas.","choice":1}],"policy":{"accents":"strict"}}','published','L2-U15-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion-08','es2-reubicacion','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**Amir** · mudarse · dentro de seis meses","input":"text"},{"prompt":"**él** · buscar · muy pronto","input":"text"},{"prompt":"**yo** · aprender · el próximo año","input":"text"},{"prompt":"**ella** · encontrar · pronto","input":"text"}]}','{"items":[{"display":"se mudará","answers":["se mudará"]},{"display":"va a buscar","answers":["va a buscar"]},{"display":"aprenderé","answers":["aprenderé"]},{"display":"encontrará","answers":["encontrará"]}],"policy":{"accents":"strict"}}','published','L2-U15-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion-09','es2-reubicacion','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Quieres mudarte? ¿A dónde?\n¿Con quién te vas a mudar?\n¿Cuándo te mudarás?\n¿Qué harás antes de mudarte?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U15-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion-10','es2-reubicacion','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**Amir** · mudarse · dentro de seis meses","input":"text"},{"prompt":"**él** · buscar · muy pronto","input":"text"},{"prompt":"**yo** · aprender · el próximo año","input":"text"},{"prompt":"**ella** · encontrar · pronto","input":"text"},{"prompt":"**Amir** · estar · ahora","input":"text"},{"prompt":"**él** · sentirse · hoy","input":"text"},{"prompt":"**ellos** · hacer · mañana","input":"text"},{"prompt":"**tú** · vivir · el año próximo","input":"text"}]}','{"items":[{"display":"se mudará","answers":["se mudará"]},{"display":"va a buscar","answers":["va a buscar"]},{"display":"aprenderé","answers":["aprenderé"]},{"display":"encontrará","answers":["encontrará"]},{"display":"está","answers":["está"]},{"display":"se siente","answers":["se siente"]},{"display":"harán","answers":["harán"]},{"display":"vivirás","answers":["vivirás"]}],"policy":{"accents":"strict"}}','published','L2-U15-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion-11','es2-reubicacion','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Cuándo se mudará Amir?","input":"sentence"},{"prompt":"¿Dónde buscará apartamento?","input":"sentence"},{"prompt":"¿Qué emociones siente?","input":"sentence"}],"text":"Dentro de seis meses, Amir se mudará a otra ciudad. Va a buscar un apartamento cerca de la estación, aprenderá el idioma y encontrará un trabajo. Está emocionado, aunque también se siente un poco ansioso."}','{"items":[{"display":"Dentro de seis meses.","answers":["Dentro de seis meses."]},{"display":"Cerca de la estación.","answers":["Cerca de la estación."]},{"display":"Emocionado y un poco ansioso.","answers":["Emocionado y un poco ansioso."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U15-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion-12','es2-reubicacion','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Reubicación\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Dentro de seis meses, Amir se mudará a otra ciudad. Va a buscar un apartamento cerca de la estación, aprenderá el idioma y encontrará un trabajo. Está emocionado, aunque también se siente un poco ansioso."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U15-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion-13','es2-reubicacion','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: Cerca de la estación."},{"id":"B","text":"Respuesta: Emocionado y un poco ansioso."},{"id":"C","text":"Pregunta: ¿Dónde buscará apartamento?"},{"id":"D","text":"Pregunta: ¿Qué emociones siente?"},{"id":"E","text":"Respuesta: Dentro de seis meses."},{"id":"F","text":"Pregunta: ¿Cuándo se mudará Amir?"}]}','{"order":["F","E","C","A","D","B"],"policy":{"accents":"strict"}}','published','L2-U15-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion-14','es2-reubicacion','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Dentro de seis meses, Amir se mudará a otra ciudad."},{"id":"B","text":"Está emocionado, aunque también se siente un poco ansioso."},{"id":"C","text":"Va a buscar un apartamento cerca de la estación, aprenderá el idioma y encontrará un trabajo."}]}','{"order":["A","C","B"],"policy":{"accents":"strict"}}','published','L2-U15-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion-15','es2-reubicacion','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre reubicación es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre reubicación es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U15-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion-16','es2-reubicacion','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"שדה תעופה = ___","input":"text"},{"prompt":"ללמוד את השפה = ___","input":"text"},{"prompt":"ספרייה = ___","input":"text"},{"prompt":"אוניברסיטה = ___","input":"text"},{"prompt":"**tú** · vivir · el año próximo","input":"text"},{"prompt":"**ellos** · hacer · mañana","input":"text"},{"prompt":"**él** · sentirse · hoy","input":"text"},{"prompt":"**Amir** · estar · ahora","input":"text"},{"prompt":"**ella** · encontrar · pronto","input":"text"},{"prompt":"**yo** · aprender · el próximo año","input":"text"}]}','{"items":[{"display":"Aeropuerto","answers":["Aeropuerto"],"policy":{"accents":"lenient"}},{"display":"Aprender el idioma","answers":["Aprender el idioma"],"policy":{"accents":"lenient"}},{"display":"Biblioteca","answers":["Biblioteca"],"policy":{"accents":"lenient"}},{"display":"Universidad","answers":["Universidad"],"policy":{"accents":"lenient"}},{"display":"vivirás","answers":["vivirás"]},{"display":"harán","answers":["harán"]},{"display":"se siente","answers":["se siente"]},{"display":"está","answers":["está"]},{"display":"encontrará","answers":["encontrará"]},{"display":"aprenderé","answers":["aprenderé"]}],"policy":{"accents":"strict"}}','published','L2-U15-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-reubicacion-17','es2-reubicacion','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Dentro de seis meses, Amir se mudará a otra ciudad. Va a buscar un apartamento cerca de la estación, aprenderá el idioma y encontrará un trabajo."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U15-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad','es-2','es-2-society','זהות וקהילה','Identidad y comunidad','לדבר ולכתוב על הנושא „זהות וקהילה“ בספרדית, תוך שימוש במבנים: Ser, estar, comparaciones y futuro.','derived','[{"he":"דקדוק בשימוש","target":"Ser, estar, comparaciones y futuro"},{"he":"אוצר מילים: זהות וקהילה","target":"Identidad y comunidad"}]','["Ser, estar, comparaciones y futuro"]','{"rules":[],"examples":["Mi comunidad es diversa.","El centro está cerca.","En cinco años habrá más espacios.","Este barrio es tan activo como aquel."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Actividad","he":"פעילות"},{"term":"Cambiar","he":"לשנות"},{"term":"Características","he":"תכונות"},{"term":"Ciudadanía","he":"אזרחות"},{"term":"Comparaciones","he":"השוואות"},{"term":"Comunidad","he":"קהילה"},{"term":"Descripción","he":"תיאור"},{"term":"Diferencia","he":"הבדל"},{"term":"Diverso","he":"מגוון"},{"term":"El/la más","he":"הכי / ביותר / הכי"},{"term":"En 10 años","he":"בעוד עשר שנים"},{"term":"En 5 años","he":"בעוד חמש שנים"},{"term":"Entrevista","he":"ראיון"},{"term":"Estado","he":"מצב"},{"term":"Estar (estuve)","he":"נמצאּתי / הייתי / להיות זמני / להימצא"},{"term":"Estaré","he":"במקום / )אהיה (במצב"},{"term":"Falso","he":"שקרי / לא נכון / שקרי"},{"term":"Familia","he":"משפחה"},{"term":"Futuro","he":"עתיד"},{"term":"Género","he":"מגדר / ז''אנר"},{"term":"Identidad","he":"זהות"},{"term":"Importante","he":"חשוב"},{"term":"Inclusivo","he":"מכליל"},{"term":"Localidad","he":"יישוב"},{"term":"Lugar","he":"מקום"},{"term":"Más que","he":"יותר מ־"},{"term":"Menos que","he":"פחות מ־"},{"term":"Nacionalidad","he":"לאום"},{"term":"Persona","he":"איש / אדם"},{"term":"Preguntas","he":"שאלות"},{"term":"Presentación","he":"מצגת / הצגה"},{"term":"Profesión","he":"מקצוע"},{"term":"Religión","he":"דת"},{"term":"Ser (fui)","he":"הייתי / להיות"},{"term":"Seré","he":"אהיה"},{"term":"Tan… como","he":"כמו / כמו… כמו"},{"term":"Verdadero","he":"אמיתי / אמיתי / נכון"},{"term":"Voy a","he":"אני עומד ל־ / אני הולך ל־ / אני הולך ל / ……אני עומד ל"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/1070284737/identidad-y-comunidad-actualizado-flash-cards/"}]','published','workbook L2 unit 16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad-01','es2-identidad-y-comunidad','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"בעוד עשר שנים ___","input":"text"},{"prompt":"להיות ___","input":"text"},{"prompt":"פעילות ___","input":"text"},{"prompt":"להיות זמני / להימצא ___","input":"text"},{"prompt":"אני עומד ל־ / אני הולך ל־ ___","input":"text"},{"prompt":"הכי ___","input":"text"}]}','{"items":[{"display":"En 10 años","answers":["En 10 años"]},{"display":"Ser","answers":["Ser"]},{"display":"Actividad","answers":["Actividad"]},{"display":"Estar","answers":["Estar"]},{"display":"Voy a","answers":["Voy a"]},{"display":"El/la más","answers":["El/la más"]}],"policy":{"accents":"lenient"}}','published','L2-U16-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad-02','es2-identidad-y-comunidad','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["En 10 años","Ser","Actividad","Estar","Voy a","El/la más","Identidad","Futuro"],"right":[{"id":"A","text":"עתיד"},{"id":"B","text":"אני עומד ל־ / אני הולך ל־"},{"id":"C","text":"בעוד עשר שנים"},{"id":"D","text":"הכי"},{"id":"E","text":"להיות זמני / להימצא"},{"id":"F","text":"להיות"},{"id":"G","text":"פעילות"},{"id":"H","text":"זהות"}]}','{"pairs":["C","F","G","E","B","D","H","A"],"policy":{"accents":"lenient"}}','published','L2-U16-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad-03','es2-identidad-y-comunidad','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"בעוד עשר שנים","input":"choice","options":["Descripción","En 10 años","Cambiar"]},{"prompt":"להיות","input":"choice","options":["Estar","Ser","Localidad"]},{"prompt":"פעילות","input":"choice","options":["Lugar","Actividad","Características"]},{"prompt":"להיות זמני / להימצא","input":"choice","options":["Comparaciones","Tan… como","Estar"]},{"prompt":"אני עומד ל־ / אני הולך ל־","input":"choice","options":["Voy a","Más que","Lugar"]},{"prompt":"הכי","input":"choice","options":["El/la más","Preguntas","Seré"]}]}','{"items":[{"display":"En 10 años","choice":1},{"display":"Ser","choice":1},{"display":"Actividad","choice":1},{"display":"Estar","choice":2},{"display":"Voy a","choice":0},{"display":"El/la más","choice":0}],"policy":{"accents":"lenient"}}','published','L2-U16-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad-04','es2-identidad-y-comunidad','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"מכליל = ___","input":"bank"},{"prompt":"להיות זמני / להימצא = ___","input":"bank"},{"prompt":"חשוב = ___","input":"bank"},{"prompt":"לאום = ___","input":"bank"},{"prompt":"ראיון = ___","input":"bank"}],"wordbank":["Importante","Estar","comunidad","Entrevista","Inclusivo","Nacionalidad"],"text":"Nuestra {{1}} es diversa y está cerca del centro. Algunas familias están organizando nuevas actividades inclusivas. En cinco años habrá más espacios culturales y el barrio será tan activo como otras zonas de la ciudad."}','{"items":[{"display":"comunidad","answers":["comunidad"]},{"display":"Inclusivo","answers":["Inclusivo"]},{"display":"Estar","answers":["Estar"]},{"display":"Importante","answers":["Importante"]},{"display":"Nacionalidad","answers":["Nacionalidad"]},{"display":"Entrevista","answers":["Entrevista"]}],"policy":{"accents":"strict"}}','published','L2-U16-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad-05','es2-identidad-y-comunidad','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["Cuál","De","eres","es","tu","país","nacionalidad","qué"]},{"prompt":"","input":"tokens","tokens":["Cuál","tu","es","género"]},{"prompt":"","input":"tokens","tokens":["comunidad","identidad","tu","de","compartes","o","familia","con","tu","parte","Qué"]},{"prompt":"","input":"tokens","tokens":["solo","Qué","tuyos","aspectos","son"]}]}','{"items":[{"display":"¿De qué país eres? ¿Cuál es tu nacionalidad?","answers":["¿De qué país eres? ¿Cuál es tu nacionalidad?"]},{"display":"¿Cuál es tu género?","answers":["¿Cuál es tu género?"]},{"display":"¿Qué parte de tu identidad compartes con tu familia o comunidad?","answers":["¿Qué parte de tu identidad compartes con tu familia o comunidad?"]},{"display":"¿Qué aspectos son solo tuyos?","answers":["¿Qué aspectos son solo tuyos?"]}],"policy":{"accents":"strict"}}','published','L2-U16-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad-06','es2-identidad-y-comunidad','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Mi comunidad está diversa.","input":"sentence"},{"prompt":"El centro es cerca.","input":"sentence"},{"prompt":"En cinco años estamos más espacios.","input":"sentence"},{"prompt":"Este barrio es tan activo que aquel.","input":"sentence"}]}','{"items":[{"display":"Mi comunidad es diversa.","answers":["Mi comunidad es diversa."]},{"display":"El centro está cerca.","answers":["El centro está cerca."]},{"display":"En cinco años habrá más espacios.","answers":["En cinco años habrá más espacios."]},{"display":"Este barrio es tan activo como aquel.","answers":["Este barrio es tan activo como aquel."]}],"policy":{"accents":"strict"}}','published','L2-U16-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad-07','es2-identidad-y-comunidad','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Mi comunidad está diversa.","Mi comunidad es diversa."]},{"prompt":"","input":"choice","options":["El centro es cerca.","El centro está cerca."]},{"prompt":"","input":"choice","options":["En cinco años habrá más espacios.","En cinco años estamos más espacios."]},{"prompt":"","input":"choice","options":["Este barrio es tan activo que aquel.","Este barrio es tan activo como aquel."]}]}','{"items":[{"display":"Mi comunidad es diversa.","choice":1},{"display":"El centro está cerca.","choice":1},{"display":"En cinco años estamos más espacios.","choice":1},{"display":"Este barrio es tan activo como aquel.","choice":1}],"policy":{"accents":"strict"}}','published','L2-U16-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad-08','es2-identidad-y-comunidad','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**la comunidad** · ser · diversa","input":"text"},{"prompt":"**el barrio** · estar · cerca del centro","input":"text"},{"prompt":"**las familias** · organizar · ahora","input":"text"},{"prompt":"**en cinco años** · haber · más espacios","input":"text"}]}','{"items":[{"display":"es","answers":["es"]},{"display":"está","answers":["está"]},{"display":"están organizando","answers":["están organizando"]},{"display":"habrá","answers":["habrá"]}],"policy":{"accents":"strict"}}','published','L2-U16-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad-09','es2-identidad-y-comunidad','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿De qué país eres? ¿Cuál es tu nacionalidad?\n¿Dónde estás ahora?\n¿Practicas alguna religión?\n¿Cuál es tu género?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U16-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad-10','es2-identidad-y-comunidad','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**la comunidad** · ser · diversa","input":"text"},{"prompt":"**el barrio** · estar · cerca del centro","input":"text"},{"prompt":"**las familias** · organizar · ahora","input":"text"},{"prompt":"**en cinco años** · haber · más espacios","input":"text"},{"prompt":"**el barrio** · ser · en el futuro","input":"text"},{"prompt":"**las actividades** · ser · inclusivas","input":"text"},{"prompt":"**los espacios** · estar · abiertos mañana","input":"text"},{"prompt":"**la zona** · tener · más servicios","input":"text"}]}','{"items":[{"display":"es","answers":["es"]},{"display":"está","answers":["está"]},{"display":"están organizando","answers":["están organizando"]},{"display":"habrá","answers":["habrá"]},{"display":"será","answers":["será"]},{"display":"son","answers":["son"]},{"display":"estarán","answers":["estarán"]},{"display":"tendrá","answers":["tendrá"]}],"policy":{"accents":"strict"}}','published','L2-U16-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad-11','es2-identidad-y-comunidad','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Cómo es la comunidad?","input":"sentence"},{"prompt":"¿Qué están organizando las familias?","input":"sentence"},{"prompt":"¿Cómo será el barrio?","input":"sentence"}],"text":"Nuestra comunidad es diversa y está cerca del centro. Algunas familias están organizando nuevas actividades inclusivas. En cinco años habrá más espacios culturales y el barrio será tan activo como otras zonas de la ciudad."}','{"items":[{"display":"Es diversa.","answers":["Es diversa."]},{"display":"Actividades inclusivas.","answers":["Actividades inclusivas."]},{"display":"Será tan activo como otras zonas de la ciudad.","answers":["Será tan activo como otras zonas de la ciudad."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U16-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad-12','es2-identidad-y-comunidad','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Identidad y comunidad\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Nuestra comunidad es diversa y está cerca del centro. Algunas familias están organizando nuevas actividades inclusivas. En cinco años habrá más espacios culturales y el barrio será tan activo como otras zonas de la ciudad."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U16-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad-13','es2-identidad-y-comunidad','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Qué están organizando las familias?"},{"id":"B","text":"Pregunta: ¿Cómo es la comunidad?"},{"id":"C","text":"Respuesta: Es diversa."},{"id":"D","text":"Respuesta: Actividades inclusivas."},{"id":"E","text":"Pregunta: ¿Cómo será el barrio?"},{"id":"F","text":"Respuesta: Será tan activo como otras zonas de la ciudad."}]}','{"order":["B","C","A","D","E","F"],"policy":{"accents":"strict"}}','published','L2-U16-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad-14','es2-identidad-y-comunidad','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Algunas familias están organizando nuevas actividades inclusivas."},{"id":"B","text":"Nuestra comunidad es diversa y está cerca del centro."},{"id":"C","text":"En cinco años habrá más espacios culturales y el barrio será tan activo como otras zonas de la ciudad."}]}','{"order":["B","A","C"],"policy":{"accents":"strict"}}','published','L2-U16-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad-15','es2-identidad-y-comunidad','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre identidad y comunidad es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre identidad y comunidad es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U16-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad-16','es2-identidad-y-comunidad','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"פעילות = ___","input":"text"},{"prompt":"להיות זמני / להימצא = ___","input":"text"},{"prompt":"אני עומד ל־ / אני הולך ל־ = ___","input":"text"},{"prompt":"הכי = ___","input":"text"},{"prompt":"**la zona** · tener · más servicios","input":"text"},{"prompt":"**los espacios** · estar · abiertos mañana","input":"text"},{"prompt":"**las actividades** · ser · inclusivas","input":"text"},{"prompt":"**el barrio** · ser · en el futuro","input":"text"},{"prompt":"**en cinco años** · haber · más espacios","input":"text"},{"prompt":"**las familias** · organizar · ahora","input":"text"}]}','{"items":[{"display":"Actividad","answers":["Actividad"],"policy":{"accents":"lenient"}},{"display":"Estar","answers":["Estar"],"policy":{"accents":"lenient"}},{"display":"Voy a","answers":["Voy a"],"policy":{"accents":"lenient"}},{"display":"El/la más","answers":["El/la más"],"policy":{"accents":"lenient"}},{"display":"tendrá","answers":["tendrá"]},{"display":"estarán","answers":["estarán"]},{"display":"son","answers":["son"]},{"display":"será","answers":["será"]},{"display":"habrá","answers":["habrá"]},{"display":"están organizando","answers":["están organizando"]}],"policy":{"accents":"strict"}}','published','L2-U16-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-identidad-y-comunidad-17','es2-identidad-y-comunidad','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Nuestra comunidad es diversa y está cerca del centro. Algunas familias están organizando nuevas actividades inclusivas."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U16-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad','es-2','es-2-society','קיימות','Sustentabilidad','לדבר ולכתוב על הנושא „קיימות“ בספרדית, תוך שימוש במבנים: Futuro, comparaciones y decisiones ecológicas.','derived','[{"he":"דקדוק בשימוש","target":"Futuro, comparaciones y decisiones ecológicas"},{"he":"אוצר מילים: קיימות","target":"Sustentabilidad"}]','["Futuro, comparaciones y decisiones ecológicas"]','{"rules":[],"examples":["Vamos a reducir el plástico.","Habrá menos contaminación.","La bicicleta es más ecológica que el coche.","El aire estará limpio."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Agua","he":"מים"},{"term":"Aire","he":"אויר"},{"term":"Árbol","he":"עץ"},{"term":"Autobús","he":"אוטובוס"},{"term":"Basura","he":"אשפה"},{"term":"Bicicleta","he":"אופנים"},{"term":"Bolsa","he":"תיק / שקית"},{"term":"Bosque","he":"יער"},{"term":"Botella","he":"בקבוק"},{"term":"Campaña","he":"מבצע / קמפיין"},{"term":"Ciudad","he":"עיר"},{"term":"Coche","he":"מכונית / רכב / מכונית"},{"term":"Comunidad","he":"קהילה"},{"term":"Contaminación","he":"זיהום"},{"term":"Ecológico","he":"ידידותי לסביבה / אקולוגי"},{"term":"El/la más","he":"הכי / ביותר / הכי"},{"term":"Electricidad","he":"חשמל"},{"term":"Eléctrico","he":"חשמלי"},{"term":"energía","he":"אנרגיה"},{"term":"Eólica, )","he":"רוח (אנרגיה רוח"},{"term":"Futuro","he":"עתיד"},{"term":"Habrá","he":"יהיה"},{"term":"Limpio","he":"נקי"},{"term":"Más… que","he":"יותר… מ"},{"term":"Menos… que","he":"פחות… מ"},{"term":"Papel","he":"נייר"},{"term":"Planeta","he":"פלנטה / כוכב לכת"},{"term":"Plástico","he":"פלסטיק"},{"term":"Reciclaje","he":"מחזור"},{"term":"Reforestación","he":"ייעור מחדש"},{"term":"Solar","he":"שמשי"},{"term":"Sucio","he":"מלוכלך"},{"term":"Tan… como","he":"כמו / כמו… כמו"},{"term":"Tierra","he":"כדור הארץ / ארץ"},{"term":"transporte","he":"תחבורה"},{"term":"Verde","he":"ירוק"},{"term":"Vidrio","he":"זכוכית"},{"term":"Voy a","he":"אני עומד ל־ / אני הולך ל־ / אני הולך ל / ……אני עומד ל"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/1070716091/espanol-conversacional-sustenabilidad-flash-cards/"}]','published','workbook L2 unit 17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad-01','es2-sustentabilidad','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"רוח (אנרגיה רוח ___","input":"text"},{"prompt":"עיר ___","input":"text"},{"prompt":"ירוק ___","input":"text"},{"prompt":"אנרגיה ___","input":"text"},{"prompt":"יהיה ___","input":"text"},{"prompt":"מחזור ___","input":"text"}]}','{"items":[{"display":"Eólica, )","answers":["Eólica, )"]},{"display":"Ciudad","answers":["Ciudad"]},{"display":"Verde","answers":["Verde"]},{"display":"Energía","answers":["Energía"]},{"display":"Habrá","answers":["Habrá"]},{"display":"Reciclaje","answers":["Reciclaje"]}],"policy":{"accents":"lenient"}}','published','L2-U17-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad-02','es2-sustentabilidad','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Eólica, )","Ciudad","Verde","Energía","Habrá","Reciclaje","Coche","Ecológico"],"right":[{"id":"A","text":"מחזור"},{"id":"B","text":"עיר"},{"id":"C","text":"ירוק"},{"id":"D","text":"יהיה"},{"id":"E","text":"רוח (אנרגיה רוח"},{"id":"F","text":"אנרגיה"},{"id":"G","text":"ידידותי לסביבה / אקולוגי"},{"id":"H","text":"מכונית"}]}','{"pairs":["E","B","C","F","D","A","H","G"],"policy":{"accents":"lenient"}}','published','L2-U17-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad-03','es2-sustentabilidad','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"רוח (אנרגיה רוח","input":"choice","options":["Reforestación","Eólica, )","Campaña"]},{"prompt":"עיר","input":"choice","options":["Ciudad","Basura","Futuro"]},{"prompt":"ירוק","input":"choice","options":["Verde","Contaminación","Transporte"]},{"prompt":"אנרגיה","input":"choice","options":["Basura","Tierra","Energía"]},{"prompt":"יהיה","input":"choice","options":["Aire","Ecológico","Habrá"]},{"prompt":"מחזור","input":"choice","options":["Reciclaje","Agua","Eléctrico"]}]}','{"items":[{"display":"Eólica, )","choice":1},{"display":"Ciudad","choice":0},{"display":"Verde","choice":0},{"display":"Energía","choice":2},{"display":"Habrá","choice":2},{"display":"Reciclaje","choice":0}],"policy":{"accents":"lenient"}}','published','L2-U17-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad-04','es2-sustentabilidad','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true}],"wordbank":["vidrio","reciclaje","plástico","papel","comunidad","habrá"],"text":"El municipio va a reducir el {{1}} y construirá más carriles para bicicletas. También {{2}} puntos de {{3}} para {{4}} y {{5}}. Si la {{6}} participa, el aire estará más limpio y habrá menos basura."}','{"items":[{"display":"plástico","answers":["plástico"]},{"display":"habrá","answers":["habrá"]},{"display":"reciclaje","answers":["reciclaje"]},{"display":"papel","answers":["papel"]},{"display":"vidrio","answers":["vidrio"]},{"display":"comunidad","answers":["comunidad"]}],"policy":{"accents":"strict"}}','published','L2-U17-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad-05','es2-sustentabilidad','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["llevar","tus","Qué","usas","y","para","compras","del","qué","supermercado","por"]},{"prompt":"","input":"tokens","tokens":["electricidad","menos","Qué","en","para","haces","gastar","casa"]},{"prompt":"","input":"tokens","tokens":["y","de","Qué","haces","cómo","basura","tipo","lo","más","reciclas"]},{"prompt":"","input":"tokens","tokens":["y","por","tu","qué","prefieres","ciudad","Cómo","moverte","en"]}]}','{"items":[{"display":"¿Qué usas para llevar tus compras del supermercado y por qué?","answers":["¿Qué usas para llevar tus compras del supermercado y por qué?"]},{"display":"¿Qué haces en casa para gastar menos electricidad?","answers":["¿Qué haces en casa para gastar menos electricidad?"]},{"display":"¿Qué tipo de basura reciclas más y cómo lo haces?","answers":["¿Qué tipo de basura reciclas más y cómo lo haces?"]},{"display":"¿Cómo prefieres moverte en tu ciudad y por qué?","answers":["¿Cómo prefieres moverte en tu ciudad y por qué?"]}],"policy":{"accents":"strict"}}','published','L2-U17-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad-06','es2-sustentabilidad','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Vamos a reduciremos el plástico.","input":"sentence"},{"prompt":"Habrá menos contaminaciones.","input":"sentence"},{"prompt":"La bicicleta es más ecológica como el coche.","input":"sentence"},{"prompt":"El aire estarán limpio.","input":"sentence"}]}','{"items":[{"display":"Vamos a reducir el plástico.","answers":["Vamos a reducir el plástico."]},{"display":"Habrá menos contaminación.","answers":["Habrá menos contaminación."]},{"display":"La bicicleta es más ecológica que el coche.","answers":["La bicicleta es más ecológica que el coche."]},{"display":"El aire estará limpio.","answers":["El aire estará limpio."]}],"policy":{"accents":"strict"}}','published','L2-U17-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad-07','es2-sustentabilidad','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Vamos a reducir el plástico.","Vamos a reduciremos el plástico."]},{"prompt":"","input":"choice","options":["Habrá menos contaminación.","Habrá menos contaminaciones."]},{"prompt":"","input":"choice","options":["La bicicleta es más ecológica que el coche.","La bicicleta es más ecológica como el coche."]},{"prompt":"","input":"choice","options":["El aire estará limpio.","El aire estarán limpio."]}]}','{"items":[{"display":"Vamos a reduciremos el plástico.","choice":1},{"display":"Habrá menos contaminaciones.","choice":1},{"display":"La bicicleta es más ecológica como el coche.","choice":1},{"display":"El aire estarán limpio.","choice":1}],"policy":{"accents":"strict"}}','published','L2-U17-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad-08','es2-sustentabilidad','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**el municipio** · reducir · muy pronto","input":"text"},{"prompt":"**la ciudad** · construir · el próximo año","input":"text"},{"prompt":"**en el barrio** · haber · puntos de reciclaje","input":"text"},{"prompt":"**la comunidad** · participar · mañana","input":"text"}]}','{"items":[{"display":"va a reducir","answers":["va a reducir"]},{"display":"construirá","answers":["construirá"]},{"display":"habrá","answers":["habrá"]},{"display":"participará","answers":["participará"]}],"policy":{"accents":"strict"}}','published','L2-U17-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad-09','es2-sustentabilidad','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Qué usas para llevar tus compras del supermercado y por qué?\n¿Cómo llevas el agua cuando sales de casa (botella de plástico, vaso, termo…)?\n¿Qué haces en casa para gastar menos electricidad?\n¿Qué tipo de basura reciclas más y cómo lo haces?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U17-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad-10','es2-sustentabilidad','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**el municipio** · reducir · muy pronto","input":"text"},{"prompt":"**la ciudad** · construir · el próximo año","input":"text"},{"prompt":"**en el barrio** · haber · puntos de reciclaje","input":"text"},{"prompt":"**la comunidad** · participar · mañana","input":"text"},{"prompt":"**el aire** · estar · más limpio","input":"text"},{"prompt":"**ellos** · reciclar · desde mañana","input":"text"},{"prompt":"**nosotros** · usar · menos plástico","input":"text"},{"prompt":"**la basura** · disminuir · en el futuro","input":"text"}]}','{"items":[{"display":"va a reducir","answers":["va a reducir"]},{"display":"construirá","answers":["construirá"]},{"display":"habrá","answers":["habrá"]},{"display":"participará","answers":["participará"]},{"display":"estará","answers":["estará"]},{"display":"reciclarán","answers":["reciclarán"]},{"display":"usaremos","answers":["usaremos"]},{"display":"disminuirá","answers":["disminuirá"]}],"policy":{"accents":"strict"}}','published','L2-U17-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad-11','es2-sustentabilidad','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué reducirá el municipio?","input":"sentence"},{"prompt":"¿Qué se podrá reciclar?","input":"sentence"},{"prompt":"¿Qué pasará si participa la comunidad?","input":"sentence"}],"text":"El municipio va a reducir el plástico y construirá más carriles para bicicletas. También habrá puntos de reciclaje para papel y vidrio. Si la comunidad participa, el aire estará más limpio y habrá menos basura."}','{"items":[{"display":"El plástico.","answers":["El plástico."]},{"display":"Papel y vidrio.","answers":["Papel y vidrio."]},{"display":"El aire estará más limpio y habrá menos basura.","answers":["El aire estará más limpio y habrá menos basura."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U17-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad-12','es2-sustentabilidad','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Sustentabilidad\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["El municipio va a reducir el plástico y construirá más carriles para bicicletas. También habrá puntos de reciclaje para papel y vidrio. Si la comunidad participa, el aire estará más limpio y habrá menos basura."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U17-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad-13','es2-sustentabilidad','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Qué pasará si participa la comunidad?"},{"id":"B","text":"Respuesta: Papel y vidrio."},{"id":"C","text":"Respuesta: El plástico."},{"id":"D","text":"Respuesta: El aire estará más limpio y habrá menos basura."},{"id":"E","text":"Pregunta: ¿Qué se podrá reciclar?"},{"id":"F","text":"Pregunta: ¿Qué reducirá el municipio?"}]}','{"order":["F","C","E","B","A","D"],"policy":{"accents":"strict"}}','published','L2-U17-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad-14','es2-sustentabilidad','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Si la comunidad participa, el aire estará más limpio y habrá menos basura."},{"id":"B","text":"También habrá puntos de reciclaje para papel y vidrio."},{"id":"C","text":"El municipio va a reducir el plástico y construirá más carriles para bicicletas."}]}','{"order":["C","B","A"],"policy":{"accents":"strict"}}','published','L2-U17-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad-15','es2-sustentabilidad','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre sustentabilidad es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre sustentabilidad es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U17-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad-16','es2-sustentabilidad','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"ירוק = ___","input":"text"},{"prompt":"אנרגיה = ___","input":"text"},{"prompt":"יהיה = ___","input":"text"},{"prompt":"מחזור = ___","input":"text"},{"prompt":"**la basura** · disminuir · en el futuro","input":"text"},{"prompt":"**nosotros** · usar · menos plástico","input":"text"},{"prompt":"**ellos** · reciclar · desde mañana","input":"text"},{"prompt":"**el aire** · estar · más limpio","input":"text"},{"prompt":"**la comunidad** · participar · mañana","input":"text"},{"prompt":"**en el barrio** · haber · puntos de reciclaje","input":"text"}]}','{"items":[{"display":"Verde","answers":["Verde"],"policy":{"accents":"lenient"}},{"display":"Energía","answers":["Energía"],"policy":{"accents":"lenient"}},{"display":"Habrá","answers":["Habrá"],"policy":{"accents":"lenient"}},{"display":"Reciclaje","answers":["Reciclaje"],"policy":{"accents":"lenient"}},{"display":"disminuirá","answers":["disminuirá"]},{"display":"usaremos","answers":["usaremos"]},{"display":"reciclarán","answers":["reciclarán"]},{"display":"estará","answers":["estará"]},{"display":"participará","answers":["participará"]},{"display":"habrá","answers":["habrá"]}],"policy":{"accents":"strict"}}','published','L2-U17-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-sustentabilidad-17','es2-sustentabilidad','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["El municipio va a reducir el plástico y construirá más carriles para bicicletas. También habrá puntos de reciclaje para papel y vidrio."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U17-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas','es-2','es-2-society','טלוויזיה וסרטים','Televisión y películas','לדבר ולכתוב על הנושא „טלוויזיה וסרטים“ בספרדית, תוך שימוש במבנים: Pasado, presente, futuro y opinión.','derived','[{"he":"דקדוק בשימוש","target":"Pasado, presente, futuro y opinión"},{"he":"אוצר מילים: טלוויזיה וסרטים","target":"Televisión y películas"}]','["Pasado, presente, futuro y opinión"]','{"rules":[],"examples":["Ayer vi una película.","La actriz fue más interesante que el actor.","Mañana veremos el tráiler.","La escena pasó en Madrid."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Acción","he":"פעולה"},{"term":"Actor","he":"שחקן"},{"term":"Actriz","he":"שחקנית"},{"term":"Animación","he":"אנימציה"},{"term":"Argumento","he":"עלילה"},{"term":"Aventura","he":"הרפתקה"},{"term":"Ciencia ficción","he":"מדע בדיוני"},{"term":"Cine","he":"קולנוע"},{"term":"Comedia","he":"קומדיה"},{"term":"Comparar","he":"להשוות"},{"term":"Contar","he":"לספר"},{"term":"Describir","he":"לתאר"},{"term":"Director","he":"במאי"},{"term":"Drama","he":"דרמה"},{"term":"Escena","he":"סצנה"},{"term":"Escuchar","he":"לשמוע / להקשיב / לשמוע / להקשיב"},{"term":"favorito","he":"מועדף / אהוב / מועדף / אהוב"},{"term":"Futuro","he":"עתיד"},{"term":"Género","he":"מגדר / ז''אנר"},{"term":"Gustar","he":"למצוא חן / לאהוב"},{"term":"Hablar","he":"לדבר"},{"term":"Historia","he":"סיפור / היסטוריה / סיפור"},{"term":"Imaginar","he":"לדמיין"},{"term":"Inventar","he":"להמציא"},{"term":"Mirar","he":"לצפות"},{"term":"Narrar","he":"לספר סיפור"},{"term":"Opinión","he":"דעה"},{"term":"Pasado","he":"עבר"},{"term":"Película","he":"סרט"},{"term":"Personaje","he":"דמות"},{"term":"Pregunta","he":"שאלה"},{"term":"Presente","he":"הווה"},{"term":"Recordar","he":"לזכור"},{"term":"Respuesta","he":"תשובה"},{"term":"Serie","he":"סדרה"},{"term":"Televisión","he":"טלוויזיה"},{"term":"Terror","he":"אימה"},{"term":"Tráiler","he":"קדימון"},{"term":"Ver","he":"לראות"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1071343088/espanol-conversacional-peliculas-y-tv-actualizado-flash-cards/"}]','published','workbook L2 unit 18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas-01','es2-television-y-peliculas','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"קומדיה ___","input":"text"},{"prompt":"לספר סיפור ___","input":"text"},{"prompt":"לספר ___","input":"text"},{"prompt":"במאי ___","input":"text"},{"prompt":"שחקן ___","input":"text"},{"prompt":"להקשיב ___","input":"text"}]}','{"items":[{"display":"Comedia","answers":["Comedia"]},{"display":"Narrar","answers":["Narrar"]},{"display":"Contar","answers":["Contar"]},{"display":"Director","answers":["Director"]},{"display":"Actor","answers":["Actor"]},{"display":"Escuchar","answers":["Escuchar"]}],"policy":{"accents":"lenient"}}','published','L2-U18-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas-02','es2-television-y-peliculas','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Comedia","Narrar","Contar","Director","Actor","Escuchar","Ver","Personaje"],"right":[{"id":"A","text":"שחקן"},{"id":"B","text":"לראות"},{"id":"C","text":"לספר סיפור"},{"id":"D","text":"להקשיב"},{"id":"E","text":"קומדיה"},{"id":"F","text":"במאי"},{"id":"G","text":"לספר"},{"id":"H","text":"דמות"}]}','{"pairs":["E","C","G","F","A","D","B","H"],"policy":{"accents":"lenient"}}','published','L2-U18-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas-03','es2-television-y-peliculas','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"קומדיה","input":"choice","options":["Recordar","Pregunta","Comedia"]},{"prompt":"לספר סיפור","input":"choice","options":["Narrar","Pasado","Imaginar"]},{"prompt":"לספר","input":"choice","options":["Ver","Película","Contar"]},{"prompt":"במאי","input":"choice","options":["Director","Contar","Narrar"]},{"prompt":"שחקן","input":"choice","options":["Respuesta","Actor","Comedia"]},{"prompt":"להקשיב","input":"choice","options":["Drama","Actor","Escuchar"]}]}','{"items":[{"display":"Comedia","choice":2},{"display":"Narrar","choice":0},{"display":"Contar","choice":2},{"display":"Director","choice":0},{"display":"Actor","choice":1},{"display":"Escuchar","choice":2}],"policy":{"accents":"lenient"}}','published','L2-U18-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas-04','es2-television-y-peliculas','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"פעולה = ___","input":"bank"},{"prompt":"שאלה = ___","input":"bank"}],"wordbank":["argumento","tráiler","Acción","ciencia ficción","Pregunta","película"],"text":"Ayer vimos una {{1}} de {{2}}. La protagonista encontró una ciudad secreta y decidió protegerla. El {{3}} fue más original que el {{4}}, aunque algunas escenas eran demasiado largas."}','{"items":[{"display":"película","answers":["película"]},{"display":"ciencia ficción","answers":["ciencia ficción"]},{"display":"argumento","answers":["argumento"]},{"display":"tráiler","answers":["tráiler"]},{"display":"Acción","answers":["Acción"]},{"display":"Pregunta","answers":["Pregunta"]}],"policy":{"accents":"strict"}}','published','L2-U18-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas-05','es2-television-y-peliculas','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["niño","mirabas","mucho","película","Qué","eras","cuando","a"]},{"prompt":"","input":"tokens","tokens":["viste","Cuál","el","película","primera","cine","que","fue","la","en"]},{"prompt":"","input":"tokens","tokens":["última","la","serie","fue","Cuál","viste","que"]},{"prompt":"","input":"tokens","tokens":["película","la","serie","Con","o","última","quién","viste"]}]}','{"items":[{"display":"¿Qué película mirabas mucho cuando eras niño/a?","answers":["¿Qué película mirabas mucho cuando eras niño/a?"]},{"display":"¿Cuál fue la primera película que viste en el cine?","answers":["¿Cuál fue la primera película que viste en el cine?"]},{"display":"¿Cuál fue la última serie que viste?","answers":["¿Cuál fue la última serie que viste?"]},{"display":"¿Con quién viste la última película o serie?","answers":["¿Con quién viste la última película o serie?"]}],"policy":{"accents":"strict"}}','published','L2-U18-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas-06','es2-television-y-peliculas','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Ayer veo una película.","input":"sentence"},{"prompt":"La actriz fue más interesante como el actor.","input":"sentence"},{"prompt":"Mañana vimos el tráiler.","input":"sentence"},{"prompt":"La escena se pasó en Madrid.","input":"sentence"}]}','{"items":[{"display":"Ayer vi una película.","answers":["Ayer vi una película."]},{"display":"La actriz fue más interesante que el actor.","answers":["La actriz fue más interesante que el actor."]},{"display":"Mañana veremos el tráiler.","answers":["Mañana veremos el tráiler."]},{"display":"La escena pasó en Madrid.","answers":["La escena pasó en Madrid."]}],"policy":{"accents":"strict"}}','published','L2-U18-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas-07','es2-television-y-peliculas','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Ayer vi una película.","Ayer veo una película."]},{"prompt":"","input":"choice","options":["La actriz fue más interesante como el actor.","La actriz fue más interesante que el actor."]},{"prompt":"","input":"choice","options":["Mañana veremos el tráiler.","Mañana vimos el tráiler."]},{"prompt":"","input":"choice","options":["La escena pasó en Madrid.","La escena se pasó en Madrid."]}]}','{"items":[{"display":"Ayer veo una película.","choice":1},{"display":"La actriz fue más interesante que el actor.","choice":1},{"display":"Mañana vimos el tráiler.","choice":1},{"display":"La escena se pasó en Madrid.","choice":1}],"policy":{"accents":"strict"}}','published','L2-U18-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas-08','es2-television-y-peliculas','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**nosotros** · ver · ayer","input":"text"},{"prompt":"**la protagonista** · encontrar · en la película","input":"text"},{"prompt":"**ella** · decidir · después","input":"text"},{"prompt":"**el argumento** · ser · más original","input":"text"}]}','{"items":[{"display":"vimos","answers":["vimos"]},{"display":"encontró","answers":["encontró"]},{"display":"decidió","answers":["decidió"]},{"display":"fue","answers":["fue"]}],"policy":{"accents":"strict"}}','published','L2-U18-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas-09','es2-television-y-peliculas','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Qué película mirabas mucho cuando eras niño/a?\n¿Cuál fue la primera película que viste en el cine?\n¿Cuál fue la última serie que viste?\n¿Con quién viste la última película o serie?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U18-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas-10','es2-television-y-peliculas','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**nosotros** · ver · ayer","input":"text"},{"prompt":"**la protagonista** · encontrar · en la película","input":"text"},{"prompt":"**ella** · decidir · después","input":"text"},{"prompt":"**el argumento** · ser · más original","input":"text"},{"prompt":"**las escenas** · ser · demasiado largas","input":"text"},{"prompt":"**nosotros** · ver · mañana","input":"text"},{"prompt":"**yo** · recomendar · después de verla","input":"text"},{"prompt":"**la película** · gustar · a mí","input":"text"}]}','{"items":[{"display":"vimos","answers":["vimos"]},{"display":"encontró","answers":["encontró"]},{"display":"decidió","answers":["decidió"]},{"display":"fue","answers":["fue"]},{"display":"eran","answers":["eran"]},{"display":"veremos","answers":["veremos"]},{"display":"recomendaré","answers":["recomendaré"]},{"display":"me gustó","answers":["me gustó"]}],"policy":{"accents":"strict"}}','published','L2-U18-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas-11','es2-television-y-peliculas','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué género tenía la película?","input":"sentence"},{"prompt":"¿Qué encontró la protagonista?","input":"sentence"},{"prompt":"¿Cómo era el argumento en comparación con el tráiler?","input":"sentence"}],"text":"Ayer vimos una película de ciencia ficción. La protagonista encontró una ciudad secreta y decidió protegerla. El argumento fue más original que el tráiler, aunque algunas escenas eran demasiado largas."}','{"items":[{"display":"Ciencia ficción.","answers":["Ciencia ficción."]},{"display":"Una ciudad secreta.","answers":["Una ciudad secreta."]},{"display":"Más original que el tráiler.","answers":["Más original que el tráiler."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U18-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas-12','es2-television-y-peliculas','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Televisión y películas\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Ayer vimos una película de ciencia ficción. La protagonista encontró una ciudad secreta y decidió protegerla. El argumento fue más original que el tráiler, aunque algunas escenas eran demasiado largas."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U18-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas-13','es2-television-y-peliculas','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Qué encontró la protagonista?"},{"id":"B","text":"Respuesta: Una ciudad secreta."},{"id":"C","text":"Pregunta: ¿Qué género tenía la película?"},{"id":"D","text":"Pregunta: ¿Cómo era el argumento en comparación con el tráiler?"},{"id":"E","text":"Respuesta: Más original que el tráiler."},{"id":"F","text":"Respuesta: Ciencia ficción."}]}','{"order":["C","F","A","B","D","E"],"policy":{"accents":"strict"}}','published','L2-U18-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas-14','es2-television-y-peliculas','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Ayer vimos una película de ciencia ficción."},{"id":"B","text":"La protagonista encontró una ciudad secreta y decidió protegerla."},{"id":"C","text":"El argumento fue más original que el tráiler, aunque algunas escenas eran demasiado largas."}]}','{"order":["A","B","C"],"policy":{"accents":"strict"}}','published','L2-U18-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas-15','es2-television-y-peliculas','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre televisión y películas es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre televisión y películas es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U18-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas-16','es2-television-y-peliculas','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"לספר = ___","input":"text"},{"prompt":"במאי = ___","input":"text"},{"prompt":"שחקן = ___","input":"text"},{"prompt":"להקשיב = ___","input":"text"},{"prompt":"**la película** · gustar · a mí","input":"text"},{"prompt":"**yo** · recomendar · después de verla","input":"text"},{"prompt":"**nosotros** · ver · mañana","input":"text"},{"prompt":"**las escenas** · ser · demasiado largas","input":"text"},{"prompt":"**el argumento** · ser · más original","input":"text"},{"prompt":"**ella** · decidir · después","input":"text"}]}','{"items":[{"display":"Contar","answers":["Contar"],"policy":{"accents":"lenient"}},{"display":"Director","answers":["Director"],"policy":{"accents":"lenient"}},{"display":"Actor","answers":["Actor"],"policy":{"accents":"lenient"}},{"display":"Escuchar","answers":["Escuchar"],"policy":{"accents":"lenient"}},{"display":"me gustó","answers":["me gustó"]},{"display":"recomendaré","answers":["recomendaré"]},{"display":"veremos","answers":["veremos"]},{"display":"eran","answers":["eran"]},{"display":"fue","answers":["fue"]},{"display":"decidió","answers":["decidió"]}],"policy":{"accents":"strict"}}','published','L2-U18-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-television-y-peliculas-17','es2-television-y-peliculas','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Ayer vimos una película de ciencia ficción. La protagonista encontró una ciudad secreta y decidió protegerla."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U18-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro','es-2','es-2-society','רשתות חברתיות: עתיד','Redes sociales · futuro','לדבר ולכתוב על הנושא „רשתות חברתיות: עתיד“ בספרדית, תוך שימוש במבנים: Futuro y comparaciones digitales.','derived','[{"he":"דקדוק בשימוש","target":"Futuro y comparaciones digitales"},{"he":"אוצר מילים: רשתות חברתיות: עתיד","target":"Redes sociales · futuro"}]','["Futuro y comparaciones digitales"]','{"rules":[],"examples":["La plataforma será más segura que esta.","Los usuarios van a controlar sus datos.","Mañana subiré un video.","Habrá menos anuncios."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Adictivo/a","he":"ת / ממכר"},{"term":"Aprender","he":"ללמוד"},{"term":"Bajar / descargar","he":"להוריד"},{"term":"Comentario","he":"תגובה"},{"term":"Comparar","he":"להשוות"},{"term":"Compartir","he":"לשתף"},{"term":"Comunicar","he":"לתקשר"},{"term":"Conectar","he":"להתחבר"},{"term":"Cuenta","he":"חשבון"},{"term":"Divertido/a","he":"מהנה / מצחיק"},{"term":"El/la más","he":"הכי / ביותר / הכי"},{"term":"El/la menos","he":"הכי פחות"},{"term":"Escribir","he":"לכתוב"},{"term":"Escuchar","he":"לשמוע / להקשיב / לשמוע / להקשיב"},{"term":"Experiencia","he":"חוויה / ניסיון"},{"term":"Foto","he":"תמונה"},{"term":"Futuro","he":"עתיד"},{"term":"Hablar","he":"לדבר"},{"term":"Hashtag","he":"האשטג"},{"term":"Historia / story","he":"סטורי"},{"term":"Interesante","he":"מעניין / ת / מעניין"},{"term":"Like / me gusta","he":"אהבתי / לייק"},{"term":"Más… que","he":"יותר… מ"},{"term":"Medios de comunicación","he":"אמצעי תקשורת"},{"term":"Menos… que","he":"פחות… מ"},{"term":"Mirar / ver","he":"לראות / להסתכל"},{"term":"Pasado","he":"עבר"},{"term":"Perfil","he":"פרופיל"},{"term":"Plataforma","he":"פלטפורמה"},{"term":"Popular","he":"פופולרי"},{"term":"Presente","he":"הווה"},{"term":"Problema","he":"בעיה"},{"term":"Publicación / post","he":"פרסום / פוסט"},{"term":"Rápido/a","he":"ה / מהיר"},{"term":"Red social","he":"רשת חברתית"},{"term":"Seguidor","he":"עוקב"},{"term":"Seguro/a","he":"ה / בטוח"},{"term":"Solución","he":"פתרון"},{"term":"Subir (contenido)","he":"להעלות תוכן"},{"term":"Video","he":"סרטון"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/881348695/conversational-spanish-social-media-futuro-flash-cards/"}]','published','workbook L2 unit 19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro-01','es2-redes-sociales-futuro','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"רשת חברתית ___","input":"text"},{"prompt":"אהבתי / לייק ___","input":"text"},{"prompt":"יותר… מ ___","input":"text"},{"prompt":"להתחבר ___","input":"text"},{"prompt":"הכי ___","input":"text"},{"prompt":"תגובה ___","input":"text"}]}','{"items":[{"display":"Red social","answers":["Red social"]},{"display":"Like / me gusta","answers":["Like / me gusta","Like","me gusta"]},{"display":"Más… que","answers":["Más… que"]},{"display":"Conectar","answers":["Conectar"]},{"display":"El/la más","answers":["El/la más"]},{"display":"Comentario","answers":["Comentario"]}],"policy":{"accents":"lenient"}}','published','L2-U19-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro-02','es2-redes-sociales-futuro','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Red social","Like / me gusta","Más… que","Conectar","El/la más","Comentario","Divertido/a","Escribir"],"right":[{"id":"A","text":"מהנה / מצחיק"},{"id":"B","text":"רשת חברתית"},{"id":"C","text":"לכתוב"},{"id":"D","text":"יותר… מ"},{"id":"E","text":"הכי"},{"id":"F","text":"תגובה"},{"id":"G","text":"להתחבר"},{"id":"H","text":"אהבתי / לייק"}]}','{"pairs":["B","H","D","G","E","F","A","C"],"policy":{"accents":"lenient"}}','published','L2-U19-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro-03','es2-redes-sociales-futuro','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"רשת חברתית","input":"choice","options":["Hashtag","Experiencia","Red social"]},{"prompt":"אהבתי / לייק","input":"choice","options":["Like / me gusta","Pasado","Rápido/a"]},{"prompt":"יותר… מ","input":"choice","options":["Divertido/a","Historia / story","Más… que"]},{"prompt":"להתחבר","input":"choice","options":["Conectar","El/la menos","El/la más"]},{"prompt":"הכי","input":"choice","options":["Subir (contenido)","Escribir","El/la más"]},{"prompt":"תגובה","input":"choice","options":["Comentario","Hablar","Seguro/a"]}]}','{"items":[{"display":"Red social","choice":2},{"display":"Like / me gusta","choice":0},{"display":"Más… que","choice":2},{"display":"Conectar","choice":0},{"display":"El/la más","choice":2},{"display":"Comentario","choice":0}],"policy":{"accents":"lenient"}}','published','L2-U19-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro-04','es2-redes-sociales-futuro','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"חוויה = ___","input":"bank"},{"prompt":"יותר… מ = ___","input":"bank"},{"prompt":"אמצעי תקשורת = ___","input":"bank"}],"wordbank":["Experiencia","futuro","Más… que","red social","Medios de comunicación","contenido"],"text":"En el {{1}}, la {{2}} de Paula será más segura y menos adictiva que las plataformas actuales. Los usuarios van a controlar sus datos, compartirán {{3}} educativo y podrán ocultar el número de likes."}','{"items":[{"display":"futuro","answers":["futuro"]},{"display":"red social","answers":["red social"]},{"display":"contenido","answers":["contenido"]},{"display":"Experiencia","answers":["Experiencia"]},{"display":"Más… que","answers":["Más… que"]},{"display":"Medios de comunicación","answers":["Medios de comunicación"]}],"policy":{"accents":"strict"}}','published','L2-U19-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro-05','es2-redes-sociales-futuro','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["futuro","vas","a","usar","en","Qué","Por","social","red","menos","qué","el"]},{"prompt":"","input":"tokens","tokens":["los","sociales","traer","nuevos","las","Qué","próximos","en","redes","van","a","años","problemas"]},{"prompt":"","input":"tokens","tokens":["Spotify","a","de","Qué","escuchar","en","vas","YouTube","la","o","música","clase","después"]},{"prompt":"","input":"tokens","tokens":["foto","Qué","sociales","o","a","qué","video","Por","a","año","vas","tus","subir","este","redes"]}]}','{"items":[{"display":"¿Qué red social vas a usar menos en el futuro? ¿Por qué?","answers":["¿Qué red social vas a usar menos en el futuro? ¿Por qué?"]},{"display":"¿Qué problemas nuevos van a traer las redes sociales en los próximos años?","answers":["¿Qué problemas nuevos van a traer las redes sociales en los próximos años?"]},{"display":"¿Qué música vas a escuchar en YouTube o Spotify después de la clase?","answers":["¿Qué música vas a escuchar en YouTube o Spotify después de la clase?"]},{"display":"¿Qué foto o video vas a subir a tus redes sociales este año? ¿Por qué?","answers":["¿Qué foto o video vas a subir a tus redes sociales este año? ¿Por qué?"]}],"policy":{"accents":"strict"}}','published','L2-U19-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro-06','es2-redes-sociales-futuro','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"La plataforma será más segura como esta.","input":"sentence"},{"prompt":"Los usuarios va a controlar sus datos.","input":"sentence"},{"prompt":"Mañana subí un video.","input":"sentence"},{"prompt":"Habrá menos más anuncios.","input":"sentence"}]}','{"items":[{"display":"La plataforma será más segura que esta.","answers":["La plataforma será más segura que esta."]},{"display":"Los usuarios van a controlar sus datos.","answers":["Los usuarios van a controlar sus datos."]},{"display":"Mañana subiré un video.","answers":["Mañana subiré un video."]},{"display":"Habrá menos anuncios.","answers":["Habrá menos anuncios."]}],"policy":{"accents":"strict"}}','published','L2-U19-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro-07','es2-redes-sociales-futuro','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["La plataforma será más segura como esta.","La plataforma será más segura que esta."]},{"prompt":"","input":"choice","options":["Los usuarios va a controlar sus datos.","Los usuarios van a controlar sus datos."]},{"prompt":"","input":"choice","options":["Mañana subiré un video.","Mañana subí un video."]},{"prompt":"","input":"choice","options":["Habrá menos anuncios.","Habrá menos más anuncios."]}]}','{"items":[{"display":"La plataforma será más segura que esta.","choice":1},{"display":"Los usuarios van a controlar sus datos.","choice":1},{"display":"Mañana subí un video.","choice":1},{"display":"Habrá menos más anuncios.","choice":1}],"policy":{"accents":"strict"}}','published','L2-U19-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro-08','es2-redes-sociales-futuro','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**la red social** · ser · en el futuro","input":"text"},{"prompt":"**los usuarios** · controlar · pronto","input":"text"},{"prompt":"**ellos** · compartir · desde mañana","input":"text"},{"prompt":"**los usuarios** · poder · en el futuro","input":"text"}]}','{"items":[{"display":"será","answers":["será"]},{"display":"controlarán","answers":["controlarán"]},{"display":"van a compartir","answers":["van a compartir"]},{"display":"podrán","answers":["podrán"]}],"policy":{"accents":"strict"}}','published','L2-U19-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro-09','es2-redes-sociales-futuro','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Qué red social vas a usar menos en el futuro? ¿Por qué?\n¿Qué problemas nuevos van a traer las redes sociales en los próximos años?\n¿Qué música vas a escuchar en YouTube o Spotify después de la clase?\n¿Qué foto o video vas a subir a tus redes sociales este año? ¿Por qué?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U19-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro-10','es2-redes-sociales-futuro','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**la red social** · ser · en el futuro","input":"text"},{"prompt":"**los usuarios** · controlar · pronto","input":"text"},{"prompt":"**ellos** · compartir · desde mañana","input":"text"},{"prompt":"**los usuarios** · poder · en el futuro","input":"text"},{"prompt":"**en la plataforma** · haber · menos anuncios","input":"text"},{"prompt":"**la empresa** · reducir · el próximo año","input":"text"},{"prompt":"**nosotros** · proteger · nuestros datos","input":"text"},{"prompt":"**tú** · usar · la aplicación mañana","input":"text"}]}','{"items":[{"display":"será","answers":["será"]},{"display":"controlarán","answers":["controlarán"]},{"display":"van a compartir","answers":["van a compartir"]},{"display":"podrán","answers":["podrán"]},{"display":"habrá","answers":["habrá"]},{"display":"reducirá","answers":["reducirá"]},{"display":"protegeremos","answers":["protegeremos"]},{"display":"usarás","answers":["usarás"]}],"policy":{"accents":"strict"}}','published','L2-U19-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro-11','es2-redes-sociales-futuro','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Cómo será la red social?","input":"sentence"},{"prompt":"¿Qué controlarán los usuarios?","input":"sentence"},{"prompt":"¿Qué número podrán ocultar?","input":"sentence"}],"text":"En el futuro, la red social de Paula será más segura y menos adictiva que las plataformas actuales. Los usuarios van a controlar sus datos, compartirán contenido educativo y podrán ocultar el número de likes."}','{"items":[{"display":"Más segura y menos adictiva.","answers":["Más segura y menos adictiva."]},{"display":"Sus datos.","answers":["Sus datos."]},{"display":"El número de likes.","answers":["El número de likes."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U19-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro-12','es2-redes-sociales-futuro','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Redes sociales · futuro\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["En el futuro, la red social de Paula será más segura y menos adictiva que las plataformas actuales. Los usuarios van a controlar sus datos, compartirán contenido educativo y podrán ocultar el número de likes."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U19-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro-13','es2-redes-sociales-futuro','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: El número de likes."},{"id":"B","text":"Respuesta: Sus datos."},{"id":"C","text":"Respuesta: Más segura y menos adictiva."},{"id":"D","text":"Pregunta: ¿Qué controlarán los usuarios?"},{"id":"E","text":"Pregunta: ¿Qué número podrán ocultar?"},{"id":"F","text":"Pregunta: ¿Cómo será la red social?"}]}','{"order":["F","C","D","B","E","A"],"policy":{"accents":"strict"}}','published','L2-U19-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro-14','es2-redes-sociales-futuro','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Los usuarios van a controlar sus datos, compartirán contenido educativo y podrán ocultar el número de likes."},{"id":"B","text":"En el futuro, la red social de Paula será más segura y menos adictiva que las plataformas actuales."}]}','{"order":["B","A"],"policy":{"accents":"strict"}}','published','L2-U19-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro-15','es2-redes-sociales-futuro','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre redes sociales · futuro es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre redes sociales · futuro es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U19-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro-16','es2-redes-sociales-futuro','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"יותר… מ = ___","input":"text"},{"prompt":"להתחבר = ___","input":"text"},{"prompt":"הכי = ___","input":"text"},{"prompt":"תגובה = ___","input":"text"},{"prompt":"**tú** · usar · la aplicación mañana","input":"text"},{"prompt":"**nosotros** · proteger · nuestros datos","input":"text"},{"prompt":"**la empresa** · reducir · el próximo año","input":"text"},{"prompt":"**en la plataforma** · haber · menos anuncios","input":"text"},{"prompt":"**los usuarios** · poder · en el futuro","input":"text"},{"prompt":"**ellos** · compartir · desde mañana","input":"text"}]}','{"items":[{"display":"Más… que","answers":["Más… que"],"policy":{"accents":"lenient"}},{"display":"Conectar","answers":["Conectar"],"policy":{"accents":"lenient"}},{"display":"El/la más","answers":["El/la más"],"policy":{"accents":"lenient"}},{"display":"Comentario","answers":["Comentario"],"policy":{"accents":"lenient"}},{"display":"usarás","answers":["usarás"]},{"display":"protegeremos","answers":["protegeremos"]},{"display":"reducirá","answers":["reducirá"]},{"display":"habrá","answers":["habrá"]},{"display":"podrán","answers":["podrán"]},{"display":"van a compartir","answers":["van a compartir"]}],"policy":{"accents":"strict"}}','published','L2-U19-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-futuro-17','es2-redes-sociales-futuro','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["En el futuro, la red social de Paula será más segura y menos adictiva que las plataformas actuales. Los usuarios van a controlar sus datos, compartirán contenido educativo y podrán ocultar el número de likes."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U19-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado','es-2','es-2-society','רשתות חברתיות: עבר','Redes sociales · pasado','לדבר ולכתוב על הנושא „רשתות חברתיות: עבר“ בספרדית, תוך שימוש במבנים: Narración de experiencias digitales.','derived','[{"he":"דקדוק בשימוש","target":"Narración de experiencias digitales"},{"he":"אוצר מילים: רשתות חברתיות: עבר","target":"Redes sociales · pasado"}]','["Narración de experiencias digitales"]','{"rules":[],"examples":["La semana pasada subí dos fotos.","Ella escribió un comentario.","Ayer borré la publicación.","El perfil estaba privado."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Adictivo/a","he":"ת / ממכר"},{"term":"Aprender","he":"ללמוד"},{"term":"Bajar / descargar","he":"להוריד"},{"term":"Comentario","he":"תגובה"},{"term":"Comparar","he":"להשוות"},{"term":"Compartir","he":"לשתף"},{"term":"Comunicar","he":"לתקשר"},{"term":"Conectar","he":"להתחבר"},{"term":"Cuenta","he":"חשבון"},{"term":"Divertido/a","he":"מהנה / מצחיק"},{"term":"El/la más","he":"הכי / ביותר / הכי"},{"term":"El/la menos","he":"הכי פחות"},{"term":"Escribir","he":"לכתוב"},{"term":"Escuchar","he":"לשמוע / להקשיב / לשמוע / להקשיב"},{"term":"Experiencia","he":"חוויה / ניסיון"},{"term":"Foto","he":"תמונה"},{"term":"Futuro","he":"עתיד"},{"term":"Hablar","he":"לדבר"},{"term":"Hashtag","he":"האשטג"},{"term":"Historia / story","he":"סטורי"},{"term":"Interesante","he":"מעניין / ת / מעניין"},{"term":"Like / me gusta","he":"אהבתי / לייק"},{"term":"Más… que","he":"יותר… מ"},{"term":"Medios de comunicación","he":"אמצעי תקשורת"},{"term":"Menos… que","he":"פחות… מ"},{"term":"Mirar / ver","he":"לראות / להסתכל"},{"term":"Pasado","he":"עבר"},{"term":"Perfil","he":"פרופיל"},{"term":"Plataforma","he":"פלטפורמה"},{"term":"Popular","he":"פופולרי"},{"term":"Presente","he":"הווה"},{"term":"Problema","he":"בעיה"},{"term":"Publicación / post","he":"פרסום / פוסט"},{"term":"Rápido/a","he":"ה / מהיר"},{"term":"Red social","he":"רשת חברתית"},{"term":"Seguidor","he":"עוקב"},{"term":"Seguro/a","he":"ה / בטוח"},{"term":"Solución","he":"פתרון"},{"term":"Subir (contenido)","he":"להעלות תוכן"},{"term":"Video","he":"סרטון"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1071363390/redes-sociales-pasado-flash-cards/"}]','published','workbook L2 unit 20',20,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado-01','es2-redes-sociales-pasado','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"להתחבר ___","input":"text"},{"prompt":"עוקב ___","input":"text"},{"prompt":"להעלות תוכן ___","input":"text"},{"prompt":"מהנה / מצחיק ___","input":"text"},{"prompt":"הכי פחות ___","input":"text"},{"prompt":"פתרון ___","input":"text"}]}','{"items":[{"display":"Conectar","answers":["Conectar"]},{"display":"Seguidor","answers":["Seguidor"]},{"display":"Subir (contenido)","answers":["Subir (contenido)","Subir"]},{"display":"Divertido/a","answers":["Divertido/a","Divertido","Divertida"]},{"display":"El/la menos","answers":["El/la menos"]},{"display":"Solución","answers":["Solución"]}],"policy":{"accents":"lenient"}}','published','L2-U20-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado-02','es2-redes-sociales-pasado','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Conectar","Seguidor","Subir (contenido)","Divertido/a","El/la menos","Solución","Comunicar","Escuchar"],"right":[{"id":"A","text":"להעלות תוכן"},{"id":"B","text":"מהנה / מצחיק"},{"id":"C","text":"להקשיב"},{"id":"D","text":"פתרון"},{"id":"E","text":"להתחבר"},{"id":"F","text":"לתקשר"},{"id":"G","text":"הכי פחות"},{"id":"H","text":"עוקב"}]}','{"pairs":["E","H","A","B","G","D","F","C"],"policy":{"accents":"lenient"}}','published','L2-U20-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado-03','es2-redes-sociales-pasado','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"להתחבר","input":"choice","options":["Experiencia","Conectar","Seguro/a"]},{"prompt":"עוקב","input":"choice","options":["Interesante","Seguidor","El/la más"]},{"prompt":"להעלות תוכן","input":"choice","options":["Historia / story","Subir (contenido)","El/la más"]},{"prompt":"מהנה / מצחיק","input":"choice","options":["Video","Publicación / post","Divertido/a"]},{"prompt":"הכי פחות","input":"choice","options":["Compartir","Comunicar","El/la menos"]},{"prompt":"פתרון","input":"choice","options":["Subir (contenido)","Solución","Pasado"]}]}','{"items":[{"display":"Conectar","choice":1},{"display":"Seguidor","choice":1},{"display":"Subir (contenido)","choice":1},{"display":"Divertido/a","choice":2},{"display":"El/la menos","choice":2},{"display":"Solución","choice":1}],"policy":{"accents":"lenient"}}','published','L2-U20-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado-04','es2-redes-sociales-pasado','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"תגובה = ___","input":"bank"},{"prompt":"להקשיב = ___","input":"bank"},{"prompt":"רשת חברתית = ___","input":"bank"}],"wordbank":["Comentario","Escuchar","foto","Red social","perfil","cuenta"],"text":"La semana pasada, Noa abrió una {{1}} nueva, subió dos videos y escribió varios comentarios. Después descubrió que había compartido una {{2}} privada por error. La borró rápidamente y cambió la configuración del {{3}}."}','{"items":[{"display":"cuenta","answers":["cuenta"]},{"display":"foto","answers":["foto"]},{"display":"perfil","answers":["perfil"]},{"display":"Comentario","answers":["Comentario"]},{"display":"Escuchar","answers":["Escuchar"]},{"display":"Red social","answers":["Red social"]}],"policy":{"accents":"strict"}}','published','L2-U20-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado-05','es2-redes-sociales-pasado','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["Por","social","Qué","usaste","qué","red","ayer"]},{"prompt":"","input":"tokens","tokens":["tus","Cuál","última","la","redes","o","subiste","que","sociales","fue","video","foto","a"]},{"prompt":"","input":"tokens","tokens":["Spotify","YouTube","o","la","pasada","música","semana","Qué","en","escuchaste"]},{"prompt":"","input":"tokens","tokens":["última","publicación","que","interesante","viste","fue","la","Dónde","Cuál"]}]}','{"items":[{"display":"¿Qué red social usaste ayer? ¿Por qué?","answers":["¿Qué red social usaste ayer? ¿Por qué?"]},{"display":"¿Cuál fue la última foto o video que subiste a tus redes sociales?","answers":["¿Cuál fue la última foto o video que subiste a tus redes sociales?"]},{"display":"¿Qué música escuchaste en YouTube o Spotify la semana pasada?","answers":["¿Qué música escuchaste en YouTube o Spotify la semana pasada?"]},{"display":"¿Cuál fue la última publicación interesante que viste? ¿Dónde?","answers":["¿Cuál fue la última publicación interesante que viste? ¿Dónde?"]}],"policy":{"accents":"strict"}}','published','L2-U20-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado-06','es2-redes-sociales-pasado','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"La semana pasada subo dos fotos.","input":"sentence"},{"prompt":"Ella escribieron un comentario.","input":"sentence"},{"prompt":"Ayer he borré la publicación.","input":"sentence"},{"prompt":"El perfil estaban privado.","input":"sentence"}]}','{"items":[{"display":"La semana pasada subí dos fotos.","answers":["La semana pasada subí dos fotos."]},{"display":"Ella escribió un comentario.","answers":["Ella escribió un comentario."]},{"display":"Ayer borré la publicación.","answers":["Ayer borré la publicación."]},{"display":"El perfil estaba privado.","answers":["El perfil estaba privado."]}],"policy":{"accents":"strict"}}','published','L2-U20-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado-07','es2-redes-sociales-pasado','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["La semana pasada subí dos fotos.","La semana pasada subo dos fotos."]},{"prompt":"","input":"choice","options":["Ella escribieron un comentario.","Ella escribió un comentario."]},{"prompt":"","input":"choice","options":["Ayer borré la publicación.","Ayer he borré la publicación."]},{"prompt":"","input":"choice","options":["El perfil estaban privado.","El perfil estaba privado."]}]}','{"items":[{"display":"La semana pasada subo dos fotos.","choice":1},{"display":"Ella escribió un comentario.","choice":1},{"display":"Ayer he borré la publicación.","choice":1},{"display":"El perfil estaba privado.","choice":1}],"policy":{"accents":"strict"}}','published','L2-U20-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado-08','es2-redes-sociales-pasado','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**Noa** · abrir · la semana pasada","input":"text"},{"prompt":"**ella** · subir · después","input":"text"},{"prompt":"**Noa** · escribir · ayer","input":"text"},{"prompt":"**ella** · descubrir · más tarde","input":"text"}]}','{"items":[{"display":"abrió","answers":["abrió"]},{"display":"subió","answers":["subió"]},{"display":"escribió","answers":["escribió"]},{"display":"descubrió","answers":["descubrió"]}],"policy":{"accents":"strict"}}','published','L2-U20-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado-09','es2-redes-sociales-pasado','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Qué red social usaste ayer? ¿Por qué?\n¿Cuál fue la última foto o video que subiste a tus redes sociales?\n¿Qué música escuchaste en YouTube o Spotify la semana pasada?\n¿Cuál fue la última publicación interesante que viste? ¿Dónde?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U20-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado-10','es2-redes-sociales-pasado','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**Noa** · abrir · la semana pasada","input":"text"},{"prompt":"**ella** · subir · después","input":"text"},{"prompt":"**Noa** · escribir · ayer","input":"text"},{"prompt":"**ella** · descubrir · más tarde","input":"text"},{"prompt":"**Noa** · compartir · antes de borrarla","input":"text"},{"prompt":"**ella** · borrar · rápidamente","input":"text"},{"prompt":"**Noa** · cambiar · al final","input":"text"},{"prompt":"**el perfil** · estar · antes","input":"text"}]}','{"items":[{"display":"abrió","answers":["abrió"]},{"display":"subió","answers":["subió"]},{"display":"escribió","answers":["escribió"]},{"display":"descubrió","answers":["descubrió"]},{"display":"había compartido","answers":["había compartido"]},{"display":"borró","answers":["borró"]},{"display":"cambió","answers":["cambió"]},{"display":"estaba","answers":["estaba"]}],"policy":{"accents":"strict"}}','published','L2-U20-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado-11','es2-redes-sociales-pasado','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué abrió Noa?","input":"sentence"},{"prompt":"¿Qué compartió por error?","input":"sentence"},{"prompt":"¿Qué hizo después?","input":"sentence"}],"text":"La semana pasada, Noa abrió una cuenta nueva, subió dos videos y escribió varios comentarios. Después descubrió que había compartido una foto privada por error. La borró rápidamente y cambió la configuración del perfil."}','{"items":[{"display":"Una cuenta nueva.","answers":["Una cuenta nueva."]},{"display":"Una foto privada.","answers":["Una foto privada."]},{"display":"La borró y cambió la configuración del perfil.","answers":["La borró y cambió la configuración del perfil."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U20-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado-12','es2-redes-sociales-pasado','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Redes sociales · pasado\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["La semana pasada, Noa abrió una cuenta nueva, subió dos videos y escribió varios comentarios. Después descubrió que había compartido una foto privada por error. La borró rápidamente y cambió la configuración del perfil."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U20-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado-13','es2-redes-sociales-pasado','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Qué abrió Noa?"},{"id":"B","text":"Pregunta: ¿Qué compartió por error?"},{"id":"C","text":"Respuesta: Una foto privada."},{"id":"D","text":"Respuesta: La borró y cambió la configuración del perfil."},{"id":"E","text":"Pregunta: ¿Qué hizo después?"},{"id":"F","text":"Respuesta: Una cuenta nueva."}]}','{"order":["A","F","B","C","E","D"],"policy":{"accents":"strict"}}','published','L2-U20-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado-14','es2-redes-sociales-pasado','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"La semana pasada, Noa abrió una cuenta nueva, subió dos videos y escribió varios comentarios."},{"id":"B","text":"Después descubrió que había compartido una foto privada por error."},{"id":"C","text":"La borró rápidamente y cambió la configuración del perfil."}]}','{"order":["A","B","C"],"policy":{"accents":"strict"}}','published','L2-U20-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado-15','es2-redes-sociales-pasado','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre redes sociales · pasado es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre redes sociales · pasado es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U20-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado-16','es2-redes-sociales-pasado','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"להעלות תוכן = ___","input":"text"},{"prompt":"מהנה / מצחיק = ___","input":"text"},{"prompt":"הכי פחות = ___","input":"text"},{"prompt":"פתרון = ___","input":"text"},{"prompt":"**el perfil** · estar · antes","input":"text"},{"prompt":"**Noa** · cambiar · al final","input":"text"},{"prompt":"**ella** · borrar · rápidamente","input":"text"},{"prompt":"**Noa** · compartir · antes de borrarla","input":"text"},{"prompt":"**ella** · descubrir · más tarde","input":"text"},{"prompt":"**Noa** · escribir · ayer","input":"text"}]}','{"items":[{"display":"Subir (contenido)","answers":["Subir (contenido)","Subir"],"policy":{"accents":"lenient"}},{"display":"Divertido/a","answers":["Divertido/a","Divertido","Divertida"],"policy":{"accents":"lenient"}},{"display":"El/la menos","answers":["El/la menos"],"policy":{"accents":"lenient"}},{"display":"Solución","answers":["Solución"],"policy":{"accents":"lenient"}},{"display":"estaba","answers":["estaba"]},{"display":"cambió","answers":["cambió"]},{"display":"borró","answers":["borró"]},{"display":"había compartido","answers":["había compartido"]},{"display":"descubrió","answers":["descubrió"]},{"display":"escribió","answers":["escribió"]}],"policy":{"accents":"strict"}}','published','L2-U20-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-redes-sociales-pasado-17','es2-redes-sociales-pasado','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["La semana pasada, Noa abrió una cuenta nueva, subió dos videos y escribió varios comentarios. Después descubrió que había compartido una foto privada por error."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U20-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica','es-2','es-2-memories','מוזיקה','Música','לדבר ולכתוב על הנושא „מוזיקה“ בספרדית, תוך שימוש במבנים: Biografía, recuerdos, opinión y tiempos simples.','derived','[{"he":"דקדוק בשימוש","target":"Biografía, recuerdos, opinión y tiempos simples"},{"he":"אוצר מילים: מוזיקה","target":"Música"}]','["Biografía, recuerdos, opinión y tiempos simples"]','{"rules":[],"examples":["Cuando era niño escuchaba música cada día.","Ayer fui a un concierto.","El cantante es más famoso que el grupo.","El próximo año tocará en un festival."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"aburrido","he":"משעמם"},{"term":"Año","he":"שנה"},{"term":"Artista","he":"אמנית / אמן"},{"term":"Bailar","he":"לרקוד"},{"term":"Biografía","he":"ביוגרפיה"},{"term":"Canción","he":"שיר"},{"term":"Cantante","he":"זמרת / זמר"},{"term":"Cantar","he":"לשיר"},{"term":"Comparación","he":"השוואה"},{"term":"Concierto","he":"קונצרט / הופעה / קונצרט"},{"term":"Creativo","he":"יצירתי"},{"term":"Cultura","he":"תרבות"},{"term":"divertido","he":"משעשע / מצחיק / מהנה / מצחיק / / מהנה / מצחיק"},{"term":"Escuchar","he":"לשמוע / להקשיב / לשמוע / להקשיב"},{"term":"Estilo","he":"סגנון"},{"term":"Experiencia","he":"חוויה / ניסיון"},{"term":"Famoso","he":"מפורסם"},{"term":"favorito","he":"מועדף / אהוב / מועדף / אהוב"},{"term":"Festival","he":"פסטיבל"},{"term":"Flamenco","he":"פלמנקו"},{"term":"Futuro","he":"עתיד"},{"term":"Género","he":"מגדר / ז''אנר"},{"term":"Grupo","he":"קבוצה / להקה / קבוצה"},{"term":"Historia","he":"סיפור / היסטוריה / סיפור"},{"term":"Infancia","he":"ילדות"},{"term":"Juventud","he":"נעורים"},{"term":"Letra (de canción), )","he":"מילים (של שיר"},{"term":"Música","he":"מוזיקה"},{"term":"Opinión","he":"דעה"},{"term":"País","he":"מדינה"},{"term":"Pasado","he":"עבר"},{"term":"Pop","he":"פופ"},{"term":"Presente","he":"הווה"},{"term":"Recuerdo","he":"זיכרון / מזכרת"},{"term":"Reguetón","he":"רגאטון"},{"term":"Rock","he":"רוק"},{"term":"Salsa","he":"סלסה"},{"term":"sorprendente","he":"מפתיע"},{"term":"Vida","he":"חיים"},{"term":"Voz","he":"קול"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1072064549/musica-flash-cards/"}]','published','workbook L2 unit 21',21,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica-01','es2-musica','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"מדינה ___","input":"text"},{"prompt":"שיר ___","input":"text"},{"prompt":"משעמם ___","input":"text"},{"prompt":"דעה ___","input":"text"},{"prompt":"נעורים ___","input":"text"},{"prompt":"אמנית / אמן ___","input":"text"}]}','{"items":[{"display":"País","answers":["País"]},{"display":"Canción","answers":["Canción"]},{"display":"Aburrido","answers":["Aburrido"]},{"display":"Opinión","answers":["Opinión"]},{"display":"Juventud","answers":["Juventud"]},{"display":"Artista","answers":["Artista"]}],"policy":{"accents":"lenient"}}','published','L2-U21-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica-02','es2-musica','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["País","Canción","Aburrido","Opinión","Juventud","Artista","Favorito","Divertido"],"right":[{"id":"A","text":"מדינה"},{"id":"B","text":"דעה"},{"id":"C","text":"נעורים"},{"id":"D","text":"אהוב"},{"id":"E","text":"משעמם"},{"id":"F","text":"מהנה / מצחיק"},{"id":"G","text":"שיר"},{"id":"H","text":"אמנית / אמן"}]}','{"pairs":["A","G","E","B","C","H","D","F"],"policy":{"accents":"lenient"}}','published','L2-U21-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica-03','es2-musica','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"מדינה","input":"choice","options":["Creativo","País","Comparación"]},{"prompt":"שיר","input":"choice","options":["Canción","Concierto","Escuchar"]},{"prompt":"משעמם","input":"choice","options":["Letra (de canción), )","Aburrido","Salsa"]},{"prompt":"דעה","input":"choice","options":["Pasado","Reguetón","Opinión"]},{"prompt":"נעורים","input":"choice","options":["Juventud","Cultura","Comparación"]},{"prompt":"אמנית / אמן","input":"choice","options":["Pasado","Canción","Artista"]}]}','{"items":[{"display":"País","choice":1},{"display":"Canción","choice":0},{"display":"Aburrido","choice":1},{"display":"Opinión","choice":2},{"display":"Juventud","choice":0},{"display":"Artista","choice":2}],"policy":{"accents":"lenient"}}','published','L2-U21-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica-04','es2-musica','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true}],"wordbank":["año","grupo","pasado","música","rock","festival"],"text":"Cuando era adolescente, Mateo escuchaba {{1}} y tocaba la guitarra en un {{2}}. El {{3}} {{4}} fue a un {{5}} de {{6}} latina y descubrió la salsa. Ahora practica ese género y el próximo verano dará un concierto."}','{"items":[{"display":"rock","answers":["rock"]},{"display":"grupo","answers":["grupo"]},{"display":"año","answers":["año"]},{"display":"pasado","answers":["pasado"]},{"display":"festival","answers":["festival"]},{"display":"música","answers":["música"]}],"policy":{"accents":"strict"}}','published','L2-U21-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica-05','es2-musica','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["Te","bailar","gusta","año","bailaste","música","Qué","el","pasado"]},{"prompt":"","input":"tokens","tokens":["última","escuchaste","la","canción","que","famosa","Cuál","fue"]},{"prompt":"","input":"tokens","tokens":["con","serie","una","o","o","latina","Viste","película","española","Cuál","música"]},{"prompt":"","input":"tokens","tokens":["palabra","piensas","país","Qué","escuchas","salsa","la","cuando"]}]}','{"items":[{"display":"¿Te gusta bailar? ¿Qué música bailaste el año pasado?","answers":["¿Te gusta bailar? ¿Qué música bailaste el año pasado?"]},{"display":"¿Cuál fue la última canción famosa que escuchaste?","answers":["¿Cuál fue la última canción famosa que escuchaste?"]},{"display":"¿Viste una película o serie con música española o latina? ¿Cuál?","answers":["¿Viste una película o serie con música española o latina? ¿Cuál?"]},{"display":"¿Qué país piensas cuando escuchas la palabra salsa?","answers":["¿Qué país piensas cuando escuchas la palabra salsa?"]}],"policy":{"accents":"strict"}}','published','L2-U21-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica-06','es2-musica','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Cuando era niño escuché música cada día.","input":"sentence"},{"prompt":"Ayer voy a un concierto.","input":"sentence"},{"prompt":"El cantante es más famoso como el grupo.","input":"sentence"},{"prompt":"El próximo año tocó en un festival.","input":"sentence"}]}','{"items":[{"display":"Cuando era niño escuchaba música cada día.","answers":["Cuando era niño escuchaba música cada día."]},{"display":"Ayer fui a un concierto.","answers":["Ayer fui a un concierto."]},{"display":"El cantante es más famoso que el grupo.","answers":["El cantante es más famoso que el grupo."]},{"display":"El próximo año tocará en un festival.","answers":["El próximo año tocará en un festival."]}],"policy":{"accents":"strict"}}','published','L2-U21-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica-07','es2-musica','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Cuando era niño escuchaba música cada día.","Cuando era niño escuché música cada día."]},{"prompt":"","input":"choice","options":["Ayer voy a un concierto.","Ayer fui a un concierto."]},{"prompt":"","input":"choice","options":["El cantante es más famoso que el grupo.","El cantante es más famoso como el grupo."]},{"prompt":"","input":"choice","options":["El próximo año tocará en un festival.","El próximo año tocó en un festival."]}]}','{"items":[{"display":"Cuando era niño escuché música cada día.","choice":1},{"display":"Ayer fui a un concierto.","choice":1},{"display":"El cantante es más famoso como el grupo.","choice":1},{"display":"El próximo año tocó en un festival.","choice":1}],"policy":{"accents":"strict"}}','published','L2-U21-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica-08','es2-musica','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**Mateo** · escuchar · cuando era adolescente","input":"text"},{"prompt":"**él** · tocar · en esa época","input":"text"},{"prompt":"**Mateo** · ir · el año pasado","input":"text"},{"prompt":"**él** · descubrir · en el festival","input":"text"}]}','{"items":[{"display":"escuchaba","answers":["escuchaba"]},{"display":"tocaba","answers":["tocaba"]},{"display":"fue","answers":["fue"]},{"display":"descubrió","answers":["descubrió"]}],"policy":{"accents":"strict"}}','published','L2-U21-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica-09','es2-musica','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Te gusta bailar? ¿Qué música bailaste el año pasado?\n¿Cuál fue la última canción famosa que escuchaste?\n¿Viste una película o serie con música española o latina? ¿Cuál?\n¿Qué país piensas cuando escuchas la palabra salsa?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L2-U21-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica-10','es2-musica','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**Mateo** · escuchar · cuando era adolescente","input":"text"},{"prompt":"**él** · tocar · en esa época","input":"text"},{"prompt":"**Mateo** · ir · el año pasado","input":"text"},{"prompt":"**él** · descubrir · en el festival","input":"text"},{"prompt":"**Mateo** · practicar · ahora","input":"text"},{"prompt":"**él** · dar · el próximo verano","input":"text"},{"prompt":"**a Mateo** · gustar · actualmente","input":"text"},{"prompt":"**la cantante** · cantar · mañana","input":"text"}]}','{"items":[{"display":"escuchaba","answers":["escuchaba"]},{"display":"tocaba","answers":["tocaba"]},{"display":"fue","answers":["fue"]},{"display":"descubrió","answers":["descubrió"]},{"display":"practica","answers":["practica"]},{"display":"dará","answers":["dará"]},{"display":"le gusta","answers":["le gusta"]},{"display":"cantará","answers":["cantará"]}],"policy":{"accents":"strict"}}','published','L2-U21-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica-11','es2-musica','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué música escuchaba Mateo?","input":"sentence"},{"prompt":"¿Qué descubrió el año pasado?","input":"sentence"},{"prompt":"¿Qué hará el próximo verano?","input":"sentence"}],"text":"Cuando era adolescente, Mateo escuchaba rock y tocaba la guitarra en un grupo. El año pasado fue a un festival de música latina y descubrió la salsa. Ahora practica ese género y el próximo verano dará un concierto."}','{"items":[{"display":"Rock.","answers":["Rock."]},{"display":"La salsa.","answers":["La salsa."]},{"display":"Dará un concierto.","answers":["Dará un concierto."]}],"policy":{"accents":"lenient","match":"content"}}','published','L2-U21-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica-12','es2-musica','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Música\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Cuando era adolescente, Mateo escuchaba rock y tocaba la guitarra en un grupo. El año pasado fue a un festival de música latina y descubrió la salsa. Ahora practica ese género y el próximo verano dará un concierto."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L2-U21-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica-13','es2-musica','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: Rock."},{"id":"B","text":"Pregunta: ¿Qué descubrió el año pasado?"},{"id":"C","text":"Respuesta: La salsa."},{"id":"D","text":"Pregunta: ¿Qué hará el próximo verano?"},{"id":"E","text":"Respuesta: Dará un concierto."},{"id":"F","text":"Pregunta: ¿Qué música escuchaba Mateo?"}]}','{"order":["F","A","B","C","D","E"],"policy":{"accents":"strict"}}','published','L2-U21-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica-14','es2-musica','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Ahora practica ese género y el próximo verano dará un concierto."},{"id":"B","text":"El año pasado fue a un festival de música latina y descubrió la salsa."},{"id":"C","text":"Cuando era adolescente, Mateo escuchaba rock y tocaba la guitarra en un grupo."}]}','{"order":["C","B","A"],"policy":{"accents":"strict"}}','published','L2-U21-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica-15','es2-musica','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre música es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre música es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L2-U21-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica-16','es2-musica','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"משעמם = ___","input":"text"},{"prompt":"דעה = ___","input":"text"},{"prompt":"נעורים = ___","input":"text"},{"prompt":"אמנית / אמן = ___","input":"text"},{"prompt":"**la cantante** · cantar · mañana","input":"text"},{"prompt":"**a Mateo** · gustar · actualmente","input":"text"},{"prompt":"**él** · dar · el próximo verano","input":"text"},{"prompt":"**Mateo** · practicar · ahora","input":"text"},{"prompt":"**él** · descubrir · en el festival","input":"text"},{"prompt":"**Mateo** · ir · el año pasado","input":"text"}]}','{"items":[{"display":"Aburrido","answers":["Aburrido"],"policy":{"accents":"lenient"}},{"display":"Opinión","answers":["Opinión"],"policy":{"accents":"lenient"}},{"display":"Juventud","answers":["Juventud"],"policy":{"accents":"lenient"}},{"display":"Artista","answers":["Artista"],"policy":{"accents":"lenient"}},{"display":"cantará","answers":["cantará"]},{"display":"le gusta","answers":["le gusta"]},{"display":"dará","answers":["dará"]},{"display":"practica","answers":["practica"]},{"display":"descubrió","answers":["descubrió"]},{"display":"fue","answers":["fue"]}],"policy":{"accents":"strict"}}','published','L2-U21-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es2-musica-17','es2-musica','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Cuando era adolescente, Mateo escuchaba rock y tocaba la guitarra en un grupo. El año pasado fue a un festival de música latina y descubrió la salsa."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L2-U21-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO levels (id,language_id,number,name_he,name_target,cefr,description,status,challenge_enabled,rubric,created_at,updated_at) VALUES ('es-3','es',3,'ספרדית רמה 3','Español · Nivel 3 · B1','B1','ספרדית עצמאית: טקסטים ארוכים, הבעת דעה, תנאים, סבילות וסובחונטיבו.','published',1,'[["קריטריון","עדיין לא","כמעט","הושלם"],["התאמה למשימה","חלק מן הפרטים חסרים","רוב הפרטים קיימים","כל הפרטים והרחבה"],["אוצר מילים","פחות מן הכמות שנדרשה","הכמות קיימת עם חזרות","מגוון מדויק ובהקשר"],["דקדוק","השגיאות מקשות","המסר ברור למרות שגיאות","שליטה טובה ותיקון עצמי"],["מבנה ובהירות","הרעיונות אינם מסודרים","יש רצף בסיסי","פתיחה, פיתוח וסיום ברורים"]]',1788220800000,1788220800000);
