INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes','es-3','es-3-stories','נסיעות וחוויות','Viajes','לדבר ולכתוב על הנושא „נסיעות וחוויות“ בספרדית, תוך שימוש במבנים: Pretérito perfecto, pretérito indefinido y pluscuamperfecto.','derived','[{"he":"דקדוק בשימוש","target":"Pretérito perfecto, pretérito indefinido y pluscuamperfecto"},{"he":"אוצר מילים: נסיעות וחוויות","target":"Viajes"}]','["Pretérito perfecto, pretérito indefinido y pluscuamperfecto"]','{"rules":[],"examples":["He viajado a Perú tres veces.","Antes de reservar, ya había comparado varias rutas.","El año pasado perdí una conexión.","Cuando llegué, el avión ya había salido."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"aeropuerto","he":"שדה תעופה"},{"term":"alojamiento","he":"לינה"},{"term":"amigo/a","he":"ה / חבר"},{"term":"carretera","he":"כביש"},{"term":"comida","he":"אוכל"},{"term":"contar","he":"לספר"},{"term":"equipaje","he":"מטען"},{"term":"experiencia","he":"חוויה / ניסיון"},{"term":"extraño","he":"מוזר"},{"term":"grupo","he":"קבוצה"},{"term":"historia","he":"סיפור"},{"term":"hostel","he":"הוסטל"},{"term":"maleta","he":"מזוודה"},{"term":"mapa","he":"מפה"},{"term":"mentira","he":"שקר"},{"term":"pasaporte","he":"דרכון"},{"term":"película","he":"סרט"},{"term":"perder","he":"לאבד"},{"term":"perderse","he":"ללכת לאיבוד"},{"term":"planear","he":"לתכנן"},{"term":"pregunta","he":"שאלה"},{"term":"preparado/ a","he":"נה / מוכן"},{"term":"reservar","he":"להזמין"},{"term":"respuesta","he":"תשובה"},{"term":"retraso","he":"עיכוב"},{"term":"solo/a","he":"לבד"},{"term":"verdad","he":"אמת"},{"term":"viajar","he":"לנסוע"},{"term":"viaje","he":"טיול"},{"term":"vuelo","he":"טיסה"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/1057550900/traveling-extreme-spanish-flash-cards/?new"}]','published','workbook L3 unit 01',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-01','es3-viajes','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"לבד ___","input":"text"},{"prompt":"מוזר ___","input":"text"},{"prompt":"אמת ___","input":"text"},{"prompt":"דרכון ___","input":"text"},{"prompt":"לתכנן ___","input":"text"},{"prompt":"להזמין ___","input":"text"}]}','{"items":[{"display":"solo/a","answers":["solo/a","solo","sola"]},{"display":"extraño","answers":["extraño"]},{"display":"verdad","answers":["verdad"]},{"display":"pasaporte","answers":["pasaporte"]},{"display":"planear","answers":["planear"]},{"display":"reservar","answers":["reservar"]}],"policy":{"accents":"lenient"}}','published','L3-U01-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-02','es3-viajes','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["solo/a","extraño","verdad","pasaporte","planear","reservar","comida","vuelo"],"right":[{"id":"A","text":"אוכל"},{"id":"B","text":"אמת"},{"id":"C","text":"לתכנן"},{"id":"D","text":"לבד"},{"id":"E","text":"טיסה"},{"id":"F","text":"להזמין"},{"id":"G","text":"מוזר"},{"id":"H","text":"דרכון"}]}','{"pairs":["D","G","B","H","C","F","A","E"],"policy":{"accents":"lenient"}}','published','L3-U01-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-03','es3-viajes','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"לבד","input":"choice","options":["preparado/ a","aeropuerto","solo/a"]},{"prompt":"מוזר","input":"choice","options":["extraño","viajar","solo/a"]},{"prompt":"אמת","input":"choice","options":["maleta","verdad","perder"]},{"prompt":"דרכון","input":"choice","options":["pasaporte","verdad","mapa"]},{"prompt":"לתכנן","input":"choice","options":["retraso","planear","experiencia"]},{"prompt":"להזמין","input":"choice","options":["mentira","reservar","viajar"]}]}','{"items":[{"display":"solo/a","choice":2},{"display":"extraño","choice":0},{"display":"verdad","choice":1},{"display":"pasaporte","choice":0},{"display":"planear","choice":1},{"display":"reservar","choice":1}],"policy":{"accents":"lenient"}}','published','L3-U01-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-04','es3-viajes','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"מפה = ___","input":"bank"},{"prompt":"לינה = ___","input":"bank"},{"prompt":"שאלה = ___","input":"bank"},{"prompt":"חוויה = ___","input":"bank"}],"wordbank":["reservar","experiencia","alojamiento","vuelo","mapa","pregunta"],"text":"Marta ha visitado doce países y siempre prepara sus viajes con cuidado. Antes de {{1}} su último {{2}}, ya había comparado varias rutas y había contratado un seguro. El año pasado viajó a Perú, pero perdió una conexión en Lima y tuvo que cambiar sus planes."}','{"items":[{"display":"reservar","answers":["reservar"]},{"display":"vuelo","answers":["vuelo"]},{"display":"mapa","answers":["mapa"]},{"display":"alojamiento","answers":["alojamiento"]},{"display":"pregunta","answers":["pregunta"]},{"display":"experiencia","answers":["experiencia"]}],"policy":{"accents":"strict"}}','published','L3-U01-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-05','es3-viajes','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["que","mejor","has","el","sido","Cuál","hecho","ha","viaje"]},{"prompt":"","input":"tokens","tokens":["ha","inesperado","pasado","viajabas","es","Qué","te","más","lo","mientras","que"]},{"prompt":"","input":"tokens","tokens":["visitado","Cuántos","en","países","vida","has","tu"]},{"prompt":"","input":"tokens","tokens":["Alguna","planear","la","viajado","fue","experiencia","sin","has","vez","Cómo","nada"]}]}','{"items":[{"display":"¿Cuál ha sido el mejor viaje que has hecho?","answers":["¿Cuál ha sido el mejor viaje que has hecho?"]},{"display":"¿Qué es lo más inesperado que te ha pasado mientras viajabas?","answers":["¿Qué es lo más inesperado que te ha pasado mientras viajabas?"]},{"display":"¿Cuántos países has visitado en tu vida?","answers":["¿Cuántos países has visitado en tu vida?"]},{"display":"¿Alguna vez has viajado sin planear nada? ¿Cómo fue la experiencia?","answers":["¿Alguna vez has viajado sin planear nada? ¿Cómo fue la experiencia?"]}],"policy":{"accents":"strict"}}','published','L3-U01-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-06','es3-viajes','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"He viajé a Perú tres veces.","input":"sentence"},{"prompt":"Antes de reservar, comparé ya varias rutas.","input":"sentence"},{"prompt":"El año pasado he perdido una conexión.","input":"sentence"},{"prompt":"Cuando llegué, el avión ya salió.","input":"sentence"}]}','{"items":[{"display":"He viajado a Perú tres veces.","answers":["He viajado a Perú tres veces."]},{"display":"Antes de reservar, ya había comparado varias rutas.","answers":["Antes de reservar, ya había comparado varias rutas."]},{"display":"El año pasado perdí una conexión.","answers":["El año pasado perdí una conexión."]},{"display":"Cuando llegué, el avión ya había salido.","answers":["Cuando llegué, el avión ya había salido."]}],"policy":{"accents":"strict"}}','published','L3-U01-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-07','es3-viajes','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["He viajado a Perú tres veces.","He viajé a Perú tres veces."]},{"prompt":"","input":"choice","options":["Antes de reservar, comparé ya varias rutas.","Antes de reservar, ya había comparado varias rutas."]},{"prompt":"","input":"choice","options":["El año pasado he perdido una conexión.","El año pasado perdí una conexión."]},{"prompt":"","input":"choice","options":["Cuando llegué, el avión ya había salido.","Cuando llegué, el avión ya salió."]}]}','{"items":[{"display":"He viajé a Perú tres veces.","choice":1},{"display":"Antes de reservar, ya había comparado varias rutas.","choice":1},{"display":"El año pasado perdí una conexión.","choice":1},{"display":"Cuando llegué, el avión ya salió.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U01-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-08','es3-viajes','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**yo** · viajar · este año","input":"text"},{"prompt":"**Marta** · comparar · antes de reservar","input":"text"},{"prompt":"**ella** · perder · el año pasado","input":"text"},{"prompt":"**nosotros** · contratar · antes del viaje","input":"text"}]}','{"items":[{"display":"he viajado","answers":["he viajado"]},{"display":"había comparado","answers":["había comparado"]},{"display":"perdió","answers":["perdió"]},{"display":"habíamos contratado","answers":["habíamos contratado"]}],"policy":{"accents":"strict"}}','published','L3-U01-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-09','es3-viajes','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Cuál ha sido el mejor viaje que has hecho?\n¿Qué es lo más inesperado que te ha pasado mientras viajabas?\n¿Cuántos países has visitado en tu vida?\n¿Alguna vez has viajado sin planear nada? ¿Cómo fue la experiencia?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U01-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-10','es3-viajes','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**yo** · viajar · este año","input":"text"},{"prompt":"**Marta** · comparar · antes de reservar","input":"text"},{"prompt":"**ella** · perder · el año pasado","input":"text"},{"prompt":"**nosotros** · contratar · antes del viaje","input":"text"},{"prompt":"**tú** · visitar · hasta hoy","input":"text"},{"prompt":"**ellos** · salir · antes de nuestra llegada","input":"text"},{"prompt":"**tú** · llegar · ayer","input":"text"},{"prompt":"**yo** · alojarse · varias veces","input":"text"}]}','{"items":[{"display":"he viajado","answers":["he viajado"]},{"display":"había comparado","answers":["había comparado"]},{"display":"perdió","answers":["perdió"]},{"display":"habíamos contratado","answers":["habíamos contratado"]},{"display":"has visitado","answers":["has visitado"]},{"display":"habían salido","answers":["habían salido"]},{"display":"llegaste","answers":["llegaste"]},{"display":"me he alojado","answers":["me he alojado"]}],"policy":{"accents":"strict"}}','published','L3-U01-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-11','es3-viajes','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Cuántos países ha visitado Marta?","input":"sentence"},{"prompt":"¿Qué había hecho antes de reservar el vuelo?","input":"sentence"},{"prompt":"¿Qué ocurrió en Lima?","input":"sentence"}],"text":"Marta ha visitado doce países y siempre prepara sus viajes con cuidado. Antes de reservar su último vuelo, ya había comparado varias rutas y había contratado un seguro. El año pasado viajó a Perú, pero perdió una conexión en Lima y tuvo que cambiar sus planes."}','{"items":[{"display":"Ha visitado doce países.","answers":["Ha visitado doce países."]},{"display":"Ya había comparado varias rutas y había contratado un seguro.","answers":["Ya había comparado varias rutas y había contratado un seguro."]},{"display":"Perdió una conexión y tuvo que cambiar sus planes.","answers":["Perdió una conexión y tuvo que cambiar sus planes."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U01-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-12','es3-viajes','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Viajes\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Marta ha visitado doce países y siempre prepara sus viajes con cuidado. Antes de reservar su último vuelo, ya había comparado varias rutas y había contratado un seguro. El año pasado viajó a Perú, pero perdió una conexión en Lima y tuvo que cambiar sus planes."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U01-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-13','es3-viajes','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: Ha visitado doce países."},{"id":"B","text":"Respuesta: Perdió una conexión y tuvo que cambiar sus planes."},{"id":"C","text":"Pregunta: ¿Cuántos países ha visitado Marta?"},{"id":"D","text":"Respuesta: Ya había comparado varias rutas y había contratado un seguro."},{"id":"E","text":"Pregunta: ¿Qué ocurrió en Lima?"},{"id":"F","text":"Pregunta: ¿Qué había hecho antes de reservar el vuelo?"}]}','{"order":["C","A","F","D","E","B"],"policy":{"accents":"strict"}}','published','L3-U01-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-14','es3-viajes','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Antes de reservar su último vuelo, ya había comparado varias rutas y había contratado un seguro."},{"id":"B","text":"Marta ha visitado doce países y siempre prepara sus viajes con cuidado."},{"id":"C","text":"El año pasado viajó a Perú, pero perdió una conexión en Lima y tuvo que cambiar sus planes."}]}','{"order":["B","A","C"],"policy":{"accents":"strict"}}','published','L3-U01-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-15','es3-viajes','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre viajes es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre viajes es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U01-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-16','es3-viajes','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"אמת = ___","input":"text"},{"prompt":"דרכון = ___","input":"text"},{"prompt":"לתכנן = ___","input":"text"},{"prompt":"להזמין = ___","input":"text"},{"prompt":"**yo** · alojarse · varias veces","input":"text"},{"prompt":"**tú** · llegar · ayer","input":"text"},{"prompt":"**ellos** · salir · antes de nuestra llegada","input":"text"},{"prompt":"**tú** · visitar · hasta hoy","input":"text"},{"prompt":"**nosotros** · contratar · antes del viaje","input":"text"},{"prompt":"**ella** · perder · el año pasado","input":"text"}]}','{"items":[{"display":"verdad","answers":["verdad"],"policy":{"accents":"lenient"}},{"display":"pasaporte","answers":["pasaporte"],"policy":{"accents":"lenient"}},{"display":"planear","answers":["planear"],"policy":{"accents":"lenient"}},{"display":"reservar","answers":["reservar"],"policy":{"accents":"lenient"}},{"display":"me he alojado","answers":["me he alojado"]},{"display":"llegaste","answers":["llegaste"]},{"display":"habían salido","answers":["habían salido"]},{"display":"has visitado","answers":["has visitado"]},{"display":"habíamos contratado","answers":["habíamos contratado"]},{"display":"perdió","answers":["perdió"]}],"policy":{"accents":"strict"}}','published','L3-U01-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-17','es3-viajes','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Marta ha visitado doce países y siempre prepara sus viajes con cuidado. Antes de reservar su último vuelo, ya había comparado varias rutas y había contratado un seguro."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U01-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-18','es3-viajes','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"Todos los alumnos deberán hablar y ___ una historia de viaje.","input":"bank"},{"prompt":"¿Alguna vez te has alojado en un ___?","input":"bank"},{"prompt":"¿Ya habías estudiado algún idioma antes de ___ al extranjero por primera vez?","input":"bank"},{"prompt":"¿Alguna vez has hecho un viaje por ___ con amigos?","input":"bank"},{"prompt":"¿Alguna vez has viajado sin planear nada? ¿Cómo fue la ___?","input":"bank"},{"prompt":"¿Alguna vez has perdido tu ___ en el aeropuerto?","input":"bank"},{"prompt":"¿Alguna vez has realizado un viaje turístico o un viaje en ___?","input":"bank"},{"prompt":"¿Alguna vez has visitado un lugar que viste en una ___?","input":"bank"},{"prompt":"Para cuando hiciste eso, yo ya había... y contaré una ___.","input":"bank"},{"prompt":"שאלה = ___","input":"bank"}],"wordbank":["historia","película","pregunta","contar","equipaje","experiencia","carretera","grupo","viajar","hostel"]}','{"items":[{"display":"contar","answers":["contar"]},{"display":"hostel","answers":["hostel"]},{"display":"viajar","answers":["viajar"]},{"display":"carretera","answers":["carretera"]},{"display":"experiencia","answers":["experiencia"]},{"display":"equipaje","answers":["equipaje"]},{"display":"grupo","answers":["grupo"]},{"display":"película","answers":["película"]},{"display":"historia","answers":["historia"]},{"display":"pregunta","answers":["pregunta"]}],"policy":{"accents":"strict"}}','published','L3-U01-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-19','es3-viajes','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Este año, yo ___.","input":"text","hint":"viajar"},{"prompt":"Antes de reservar, Marta ___.","input":"text","hint":"comparar"},{"prompt":"El año pasado, ella ___.","input":"text","hint":"perder"},{"prompt":"Antes del viaje, nosotros ___.","input":"text","hint":"contratar"},{"prompt":"Tú ___ hasta hoy.","input":"text","hint":"visitar"},{"prompt":"Antes de nuestra llegada, ellos ___.","input":"text","hint":"salir"},{"prompt":"Ayer, tú ___.","input":"text","hint":"llegar"},{"prompt":"Yo ___ varias veces.","input":"text","hint":"alojarse"}]}','{"items":[{"display":"he viajado","answers":["he viajado"]},{"display":"había comparado","answers":["había comparado"]},{"display":"perdió","answers":["perdió"]},{"display":"habíamos contratado","answers":["habíamos contratado"]},{"display":"has visitado","answers":["has visitado"]},{"display":"habían salido","answers":["habían salido"]},{"display":"llegaste","answers":["llegaste"]},{"display":"me he alojado","answers":["me he alojado"]}],"policy":{"accents":"strict"}}','published','L3-U01-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-viajes-20','es3-viajes','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Por qué cambió Paula su ruta?","input":"sentence"},{"prompt":"¿Quién le recomendó un sendero seguro?","input":"sentence"},{"prompt":"¿Qué aprendió de la experiencia?","input":"sentence"},{"prompt":"¿Qué no había contratado Paula antes de salir?","input":"sentence"},{"prompt":"¿Cómo ha cambiado su forma de organizarse?","input":"sentence"}],"text":"Paula había planeado una ruta de cinco días por la Patagonia, pero una tormenta cerró el camino principal. En vez de cancelar el viaje, habló con una familia local que le recomendó un sendero seguro y le ofreció alojamiento. Paula regresó un día más tarde de lo previsto, aunque afirma que la experiencia le enseñó a viajar con más flexibilidad.\n\nAntes de salir, Paula ya había reservado el alojamiento, había comprobado la fecha de caducidad de su pasaporte y había preparado una maleta ligera. Sin embargo, no había contratado un seguro de viaje. Cuando volvió a casa, contó que el vuelo de regreso había sufrido un retraso de seis horas y que parte del equipaje se había perdido en el aeropuerto. Desde entonces, ha cambiado su forma de organizarse: guarda copias de los documentos, compara distintas rutas y reserva una cantidad de dinero para imprevistos. También ha recomendado a sus amigos que dejen espacio en el itinerario, porque un viaje no siempre sale como se había imaginado.\n\nAl comparar el viaje real con el itinerario original, Paula comprendió que los mejores recuerdos no siempre nacen de una reserva perfecta. Ahora se siente más segura porque ha aprendido a reaccionar ante un retraso, una pérdida o un cambio inesperado."}','{"items":[{"display":"Porque una tormenta cerró el camino principal","answers":["Porque una tormenta cerró el camino principal"]},{"display":"Una familia local","answers":["Una familia local"]},{"display":"A viajar con más flexibilidad","answers":["A viajar con más flexibilidad"]},{"display":"Un seguro de viaje","answers":["Un seguro de viaje"]},{"display":"Guarda copias, compara rutas y reserva dinero para imprevistos","answers":["Guarda copias, compara rutas y reserva dinero para imprevistos"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U01-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros','es-3','es-3-work','כסף וחיסכון','Dinero y ahorros','לדבר ולכתוב על הנושא „כסף וחיסכון“ בספרדית, תוך שימוש במבנים: Condicionales, voz pasiva y decisiones financieras.','derived','[{"he":"דקדוק בשימוש","target":"Condicionales, voz pasiva y decisiones financieras"},{"he":"אוצר מילים: כסף וחיסכון","target":"Dinero y ahorros"}]','["Condicionales, voz pasiva y decisiones financieras"]','{"rules":[],"examples":["Si ahorro este mes, invertiré el dinero.","Si ganara más, ayudaría a mi familia.","Si hubiera controlado mis gastos, habría evitado la deuda.","El préstamo fue aprobado por el banco."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Acciones","he":"פעולות"},{"term":"Agua","he":"מים"},{"term":"Ahorrar","he":"לחסוך"},{"term":"Ahorros","he":"חיסכון"},{"term":"Banco","he":"בנק"},{"term":"Cambiar","he":"לשנות"},{"term":"Condicional","he":"משפט תנאי / תנאי / מותנה"},{"term":"Consejo","he":"עצה"},{"term":"Coste / costo","he":"עלות"},{"term":"Cuenta","he":"חשבון"},{"term":"Desperdiciar","he":"לבזבז"},{"term":"Desperdicio de comida","he":"בזבוז מזון"},{"term":"Deuda","he":"חוב"},{"term":"Dinero","he":"כסף"},{"term":"Educación financiera","he":"חינוך פיננסי"},{"term":"Energía","he":"אנרגיה"},{"term":"Entretenimiento","he":"בידור"},{"term":"Error","he":"טעות"},{"term":"Futuro","he":"עתיד"},{"term":"Gastar","he":"להוציא כסף"},{"term":"Gastos","he":"הוצאות"},{"term":"Hábito","he":"הרגל"},{"term":"Hábito de consumo","he":"הרגל צריכה"},{"term":"Hipotético","he":"היפותטי"},{"term":"Ingresos","he":"הכנסה"},{"term":"Invertir","he":"להשקיע"},{"term":"Objetivo / meta","he":"מטרה"},{"term":"Oportunidad","he":"הזדמנות"},{"term":"Planificar","he":"לתכנן"},{"term":"Presupuesto","he":"תקציב"},{"term":"Prima / bono","he":"בונוס"},{"term":"Reducir","he":"להפחית"},{"term":"Responsabilidad","he":"אחריות"},{"term":"Resultado","he":"תוצאה"},{"term":"Reutilizar","he":"להשתמש מחדש / לעשות שימוש חוזר"},{"term":"Seguridad","he":"ביטחון"},{"term":"Solución","he":"פתרון"},{"term":"Sueldo / salario","he":"משכורת"},{"term":"Transporte","he":"תחבורה"},{"term":"Voz pasiva","he":"סביל"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1072903874/dinero-y-ahorros-flash-cards/?new"}]','published','workbook L3 unit 02',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-01','es3-dinero-y-ahorros','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"לשנות ___","input":"text"},{"prompt":"לתכנן ___","input":"text"},{"prompt":"חוב ___","input":"text"},{"prompt":"סביל ___","input":"text"},{"prompt":"להוציא כסף ___","input":"text"},{"prompt":"הרגל ___","input":"text"}]}','{"items":[{"display":"Cambiar","answers":["Cambiar"]},{"display":"Planificar","answers":["Planificar"]},{"display":"Deuda","answers":["Deuda"]},{"display":"Voz pasiva","answers":["Voz pasiva"]},{"display":"Gastar","answers":["Gastar"]},{"display":"Hábito","answers":["Hábito"]}],"policy":{"accents":"lenient"}}','published','L3-U02-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-02','es3-dinero-y-ahorros','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Cambiar","Planificar","Deuda","Voz pasiva","Gastar","Hábito","Consejo","Solución"],"right":[{"id":"A","text":"להוציא כסף"},{"id":"B","text":"סביל"},{"id":"C","text":"חוב"},{"id":"D","text":"פתרון"},{"id":"E","text":"לתכנן"},{"id":"F","text":"הרגל"},{"id":"G","text":"עצה"},{"id":"H","text":"לשנות"}]}','{"pairs":["H","E","C","B","A","F","G","D"],"policy":{"accents":"lenient"}}','published','L3-U02-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-03','es3-dinero-y-ahorros','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"לשנות","input":"choice","options":["Futuro","Cambiar","Sueldo / salario"]},{"prompt":"לתכנן","input":"choice","options":["Planificar","Agua","Ahorrar"]},{"prompt":"חוב","input":"choice","options":["Deuda","Cambiar","Coste / costo"]},{"prompt":"סביל","input":"choice","options":["Voz pasiva","Sueldo / salario","Reutilizar"]},{"prompt":"להוציא כסף","input":"choice","options":["Cambiar","Gastos","Gastar"]},{"prompt":"הרגל","input":"choice","options":["Transporte","Hábito","Energía"]}]}','{"items":[{"display":"Cambiar","choice":1},{"display":"Planificar","choice":0},{"display":"Deuda","choice":0},{"display":"Voz pasiva","choice":0},{"display":"Gastar","choice":2},{"display":"Hábito","choice":1}],"policy":{"accents":"lenient"}}','published','L3-U02-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-04','es3-dinero-y-ahorros','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"בזבוז מזון = ___","input":"bank"},{"prompt":"מים = ___","input":"bank"}],"wordbank":["Agua","bono","gastos","Desperdicio de comida","deuda","sueldo"],"text":"Andrés ha ahorrado una parte de su {{1}} durante todo el año. Si recibe un {{2}}, invertirá la mitad; si ganara más, también ayudaría a su familia. Reconoce que, si hubiera controlado mejor sus {{3}} el año pasado, habría evitado una {{4}}."}','{"items":[{"display":"sueldo","answers":["sueldo"]},{"display":"bono","answers":["bono"]},{"display":"gastos","answers":["gastos"]},{"display":"deuda","answers":["deuda"]},{"display":"Desperdicio de comida","answers":["Desperdicio de comida"]},{"display":"Agua","answers":["Agua"]}],"policy":{"accents":"strict"}}','published','L3-U02-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-05','es3-dinero-y-ahorros','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["deberían","ahorrar","que","mes","cada","los","jóvenes","dinero","piensas","Cuánto"]},{"prompt":"","input":"tokens","tokens":["20","si","redujera","Qué","tu","%","se","salario","harías","un"]},{"prompt":"","input":"tokens","tokens":["día","en","aprender","los","adolescentes","ahorro","buenos","hoy","pueden","Cómo","de","hábitos"]},{"prompt":"","input":"tokens","tokens":["estilo","tu","cómo","de","a","vida","afecta"]}]}','{"items":[{"display":"¿Cuánto dinero piensas que deberían ahorrar los jóvenes cada mes?","answers":["¿Cuánto dinero piensas que deberían ahorrar los jóvenes cada mes?"]},{"display":"¿Qué harías si tu salario se redujera un 20%?","answers":["¿Qué harías si tu salario se redujera un 20%?"]},{"display":"¿Cómo pueden aprender hoy en día los adolescentes buenos hábitos de ahorro?","answers":["¿Cómo pueden aprender hoy en día los adolescentes buenos hábitos de ahorro?"]},{"display":"¿cómo afecta a tu estilo de vida?","answers":["¿cómo afecta a tu estilo de vida?"]}],"policy":{"accents":"strict"}}','published','L3-U02-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-06','es3-dinero-y-ahorros','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Si ahorro este mes, invertiría el dinero.","input":"sentence"},{"prompt":"Si ganaría más, ayudaría a mi familia.","input":"sentence"},{"prompt":"Si hubiera controlado mis gastos, evitaría la deuda del año pasado.","input":"sentence"},{"prompt":"El préstamo fue aprobar por el banco.","input":"sentence"}]}','{"items":[{"display":"Si ahorro este mes, invertiré el dinero.","answers":["Si ahorro este mes, invertiré el dinero."]},{"display":"Si ganara más, ayudaría a mi familia.","answers":["Si ganara más, ayudaría a mi familia."]},{"display":"Si hubiera controlado mis gastos, habría evitado la deuda.","answers":["Si hubiera controlado mis gastos, habría evitado la deuda."]},{"display":"El préstamo fue aprobado por el banco.","answers":["El préstamo fue aprobado por el banco."]}],"policy":{"accents":"strict"}}','published','L3-U02-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-07','es3-dinero-y-ahorros','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Si ahorro este mes, invertiré el dinero.","Si ahorro este mes, invertiría el dinero."]},{"prompt":"","input":"choice","options":["Si ganara más, ayudaría a mi familia.","Si ganaría más, ayudaría a mi familia."]},{"prompt":"","input":"choice","options":["Si hubiera controlado mis gastos, evitaría la deuda del año pasado.","Si hubiera controlado mis gastos, habría evitado la deuda."]},{"prompt":"","input":"choice","options":["El préstamo fue aprobado por el banco.","El préstamo fue aprobar por el banco."]}]}','{"items":[{"display":"Si ahorro este mes, invertiría el dinero.","choice":1},{"display":"Si ganaría más, ayudaría a mi familia.","choice":1},{"display":"Si hubiera controlado mis gastos, habría evitado la deuda.","choice":1},{"display":"El préstamo fue aprobar por el banco.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U02-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-08','es3-dinero-y-ahorros','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**yo** · ahorrar · si mantengo el plan","input":"text"},{"prompt":"**Andrés** · invertir · si ganara más","input":"text"},{"prompt":"**él** · evitar · si hubiera controlado sus gastos","input":"text"},{"prompt":"**el préstamo** · aprobar · ayer","input":"text"}]}','{"items":[{"display":"ahorraré","answers":["ahorraré"]},{"display":"invertiría","answers":["invertiría"]},{"display":"habría evitado","answers":["habría evitado"]},{"display":"fue aprobado","answers":["fue aprobado"]}],"policy":{"accents":"strict"}}','published','L3-U02-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-09','es3-dinero-y-ahorros','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Cuánto dinero piensas que deberían ahorrar los jóvenes cada mes?\n¿Qué harías si tu salario se redujera un 20%?\n¿Cómo pueden aprender hoy en día los adolescentes buenos hábitos de ahorro?\n¿cómo se gastaría?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U02-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-10','es3-dinero-y-ahorros','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**yo** · ahorrar · si mantengo el plan","input":"text"},{"prompt":"**Andrés** · invertir · si ganara más","input":"text"},{"prompt":"**él** · evitar · si hubiera controlado sus gastos","input":"text"},{"prompt":"**el préstamo** · aprobar · ayer","input":"text"},{"prompt":"**nosotros** · gastar · este mes","input":"text"},{"prompt":"**tú** · reducir · si quisieras","input":"text"},{"prompt":"**ellos** · perder · si hubieran invertido mal","input":"text"},{"prompt":"**el dinero** · transferir · mañana","input":"text"}]}','{"items":[{"display":"ahorraré","answers":["ahorraré"]},{"display":"invertiría","answers":["invertiría"]},{"display":"habría evitado","answers":["habría evitado"]},{"display":"fue aprobado","answers":["fue aprobado"]},{"display":"hemos gastado","answers":["hemos gastado"]},{"display":"reducirías","answers":["reducirías"]},{"display":"habrían perdido","answers":["habrían perdido"]},{"display":"será transferido","answers":["será transferido"]}],"policy":{"accents":"strict"}}','published','L3-U02-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-11','es3-dinero-y-ahorros','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué ha hecho Andrés durante el año?","input":"sentence"},{"prompt":"¿Qué hará si recibe un bono?","input":"sentence"},{"prompt":"¿Qué habría evitado con un mejor control?","input":"sentence"}],"text":"Andrés ha ahorrado una parte de su sueldo durante todo el año. Si recibe un bono, invertirá la mitad; si ganara más, también ayudaría a su familia. Reconoce que, si hubiera controlado mejor sus gastos el año pasado, habría evitado una deuda."}','{"items":[{"display":"Ha ahorrado una parte de su sueldo.","answers":["Ha ahorrado una parte de su sueldo."]},{"display":"Invertirá la mitad.","answers":["Invertirá la mitad."]},{"display":"Habría evitado una deuda.","answers":["Habría evitado una deuda."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U02-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-12','es3-dinero-y-ahorros','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Dinero y ahorros\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Andrés ha ahorrado una parte de su sueldo durante todo el año. Si recibe un bono, invertirá la mitad; si ganara más, también ayudaría a su familia. Reconoce que, si hubiera controlado mejor sus gastos el año pasado, habría evitado una deuda."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U02-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-13','es3-dinero-y-ahorros','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: Ha ahorrado una parte de su sueldo."},{"id":"B","text":"Pregunta: ¿Qué habría evitado con un mejor control?"},{"id":"C","text":"Respuesta: Habría evitado una deuda."},{"id":"D","text":"Pregunta: ¿Qué ha hecho Andrés durante el año?"},{"id":"E","text":"Respuesta: Invertirá la mitad."},{"id":"F","text":"Pregunta: ¿Qué hará si recibe un bono?"}]}','{"order":["D","A","F","E","B","C"],"policy":{"accents":"strict"}}','published','L3-U02-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-14','es3-dinero-y-ahorros','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Si recibe un bono, invertirá la mitad; si ganara más, también ayudaría a su familia."},{"id":"B","text":"Reconoce que, si hubiera controlado mejor sus gastos el año pasado, habría evitado una deuda."},{"id":"C","text":"Andrés ha ahorrado una parte de su sueldo durante todo el año."}]}','{"order":["C","A","B"],"policy":{"accents":"strict"}}','published','L3-U02-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-15','es3-dinero-y-ahorros','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre dinero y ahorros es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre dinero y ahorros es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U02-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-16','es3-dinero-y-ahorros','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"חוב = ___","input":"text"},{"prompt":"סביל = ___","input":"text"},{"prompt":"להוציא כסף = ___","input":"text"},{"prompt":"הרגל = ___","input":"text"},{"prompt":"**el dinero** · transferir · mañana","input":"text"},{"prompt":"**ellos** · perder · si hubieran invertido mal","input":"text"},{"prompt":"**tú** · reducir · si quisieras","input":"text"},{"prompt":"**nosotros** · gastar · este mes","input":"text"},{"prompt":"**el préstamo** · aprobar · ayer","input":"text"},{"prompt":"**él** · evitar · si hubiera controlado sus gastos","input":"text"}]}','{"items":[{"display":"Deuda","answers":["Deuda"],"policy":{"accents":"lenient"}},{"display":"Voz pasiva","answers":["Voz pasiva"],"policy":{"accents":"lenient"}},{"display":"Gastar","answers":["Gastar"],"policy":{"accents":"lenient"}},{"display":"Hábito","answers":["Hábito"],"policy":{"accents":"lenient"}},{"display":"será transferido","answers":["será transferido"]},{"display":"habrían perdido","answers":["habrían perdido"]},{"display":"reducirías","answers":["reducirías"]},{"display":"hemos gastado","answers":["hemos gastado"]},{"display":"fue aprobado","answers":["fue aprobado"]},{"display":"habría evitado","answers":["habría evitado"]}],"policy":{"accents":"strict"}}','published','L3-U02-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-17','es3-dinero-y-ahorros','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Andrés ha ahorrado una parte de su sueldo durante todo el año. Si recibe un bono, invertirá la mitad; si ganara más, también ayudaría a su familia."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U02-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-18','es3-dinero-y-ahorros','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"Habla de cómo se desperdicia dinero en el ___.","input":"bank"},{"prompt":"Habla de cómo pueden ahorrarse los costes de ___.","input":"bank"},{"prompt":"Habla de cómo puede reducirse el ___.","input":"bank"},{"prompt":"Oración con si (condición) + oración principal (___).","input":"bank"},{"prompt":"Ejemplo: Si ahorras dinero, tienes más ___.","input":"bank"},{"prompt":"¿Cuánto ___ piensas que deberían ahorrar los jóvenes cada mes?","input":"bank"},{"prompt":"Primero: Si ahorras tu dinero hoy, ¿qué harás con él en el ___?","input":"bank"},{"prompt":"¿Cuánto dinero piensas que deberían ___ los jóvenes cada mes?","input":"bank"},{"prompt":"Cero: Si compras menos cosas pequeñas, ¿qué pasa con tus ___?","input":"bank"},{"prompt":"A un amigo le fue robado el dinero de su ___ bancaria. ¿Qué debería hacerse?","input":"bank"}],"wordbank":["Entretenimiento","Futuro","Resultado","Desperdicio de comida","Transporte","Ahorrar","Ahorros","Cuenta","Seguridad","Dinero"]}','{"items":[{"display":"Entretenimiento","answers":["Entretenimiento"]},{"display":"Transporte","answers":["Transporte"]},{"display":"Desperdicio de comida","answers":["Desperdicio de comida"]},{"display":"Resultado","answers":["Resultado"]},{"display":"Seguridad","answers":["Seguridad"]},{"display":"Dinero","answers":["Dinero"]},{"display":"Futuro","answers":["Futuro"]},{"display":"Ahorrar","answers":["Ahorrar"]},{"display":"Ahorros","answers":["Ahorros"]},{"display":"Cuenta","answers":["Cuenta"]}],"policy":{"accents":"strict"}}','published','L3-U02-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-19','es3-dinero-y-ahorros','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Si mantengo el plan, yo ___.","input":"text","hint":"ahorrar"},{"prompt":"Si ganara más, Andrés ___.","input":"text","hint":"invertir"},{"prompt":"Si hubiera controlado sus gastos, él ___.","input":"text","hint":"evitar"},{"prompt":"Ayer, el préstamo ___.","input":"text","hint":"aprobar"},{"prompt":"Este mes, nosotros ___.","input":"text","hint":"gastar"},{"prompt":"Si quisieras, tú ___.","input":"text","hint":"reducir"},{"prompt":"Si hubieran invertido mal, ellos ___.","input":"text","hint":"perder"},{"prompt":"Mañana, el dinero ___.","input":"text","hint":"transferir"}]}','{"items":[{"display":"ahorraré","answers":["ahorraré"]},{"display":"invertiría","answers":["invertiría"]},{"display":"habría evitado","answers":["habría evitado"]},{"display":"fue aprobado","answers":["fue aprobado"]},{"display":"hemos gastado","answers":["hemos gastado"]},{"display":"reducirías","answers":["reducirías"]},{"display":"habrían perdido","answers":["habrían perdido"]},{"display":"será transferido","answers":["será transferido"]}],"policy":{"accents":"strict"}}','published','L3-U02-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-dinero-y-ahorros-20','es3-dinero-y-ahorros','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Qué canceló Diego?","input":"sentence"},{"prompt":"¿Para qué creó una cuenta de emergencia?","input":"sentence"},{"prompt":"¿Qué habría hecho sin ese fondo?","input":"sentence"},{"prompt":"¿Qué le permitiría aumentar sus ahorros?","input":"sentence"},{"prompt":"¿Qué haría Diego cuando recibiera la próxima prima?","input":"sentence"}],"text":"Diego revisó sus gastos después de recibir una factura inesperada. Canceló dos suscripciones que casi no utilizaba y empezó a transferir una cantidad fija a una cuenta de emergencia. Tres meses después tuvo que reparar el coche. Si no hubiera creado ese fondo, habría pedido un préstamo para pagar la reparación.\n\nEl presupuesto mensual de Diego fue revisado con ayuda de una asesora del banco. Ella le explicó que sus ingresos eran estables, pero que una parte excesiva del sueldo se destinaba a gastos pequeños. Si redujera esas compras, podría aumentar sus ahorros sin renunciar a todo lo que disfruta. Diego decidió que, cuando recibiera la próxima prima, pagaría primero una parte de la deuda. También comparó varias opciones de inversión, aunque no aceptó ninguna antes de entender el riesgo. Si hubiera seguido gastando sin controlar la cuenta, su situación financiera habría empeorado y el préstamo habría sido más difícil de devolver.\n\nSu objetivo no es hacerse rico rápidamente, sino tomar decisiones sostenibles. Cada domingo registra los gastos, revisa el saldo de la cuenta y decide cuánto puede ahorrar. Así ha convertido el presupuesto en una herramienta de libertad y no en un castigo."}','{"items":[{"display":"Dos suscripciones","answers":["Dos suscripciones"]},{"display":"Para cubrir gastos inesperados","answers":["Para cubrir gastos inesperados"]},{"display":"Habría pedido un préstamo","answers":["Habría pedido un préstamo"]},{"display":"Reducir los gastos pequeños","answers":["Reducir los gastos pequeños"]},{"display":"Pagaría una parte de la deuda","answers":["Pagaría una parte de la deuda"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U02-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal','es-3','es-3-work','קריירה והתפתחות אישית','Carrera y desarrollo personal','לדבר ולכתוב על הנושא „קריירה והתפתחות אישית“ בספרדית, תוך שימוש במבנים: Pasado, condicionales y voz pasiva en el mundo laboral.','derived','[{"he":"דקדוק בשימוש","target":"Pasado, condicionales y voz pasiva en el mundo laboral"},{"he":"אוצר מילים: קריירה והתפתחות אישית","target":"Carrera y desarrollo personal"}]','["Pasado, condicionales y voz pasiva en el mundo laboral"]','{"rules":[],"examples":["Lucía ha trabajado en tres empresas.","Si su jefe la hubiera apoyado, habría crecido más rápido.","Su currículum fue revisado ayer.","Mañana tendrá una entrevista."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Carrera","he":"קריירה"},{"term":"Colega","he":"עמית"},{"term":"Comunicación","he":"תקשורת"},{"term":"Condicional","he":"משפט תנאי / תנאי / מותנה"},{"term":"Confianza","he":"אמון / ביטחון / אמון"},{"term":"Contratación","he":"גיוס"},{"term":"Currículum","he":"קורות חיים"},{"term":"Desafío","he":"אתגר"},{"term":"Desarrollo","he":"התפתחות"},{"term":"Despido","he":"פיטורים"},{"term":"Empresa","he":"חברה"},{"term":"Entrevista","he":"ראיון"},{"term":"Equilibrio","he":"איזון"},{"term":"Éxito","he":"הצלחה"},{"term":"experiencia","he":"חוויה / ניסיון"},{"term":"Formación","he":"הכשרה"},{"term":"Fracaso","he":"כישלון"},{"term":"Futuro","he":"עתיד"},{"term":"Habilidades","he":"מיומנויות"},{"term":"Hipótesis","he":"השערה / השערה / הנחה"},{"term":"Inspiración","he":"השראה"},{"term":"Jefe","he":"מנהל / בוס"},{"term":"Logro","he":"הישג"},{"term":"Memorable","he":"בלתי נשכח"},{"term":"Motivación","he":"מוטיבציה"},{"term":"Narración","he":"נרטיב / סיפור / סיפור / נרטיב"},{"term":"Negociación","he":"משא ומתן"},{"term":"Networking","he":"רשת קשרים / נטוורקינג"},{"term":"Objetivo","he":"מטרה"},{"term":"Oportunidad","he":"הזדמנות"},{"term":"Pasado","he":"עבר"},{"term":"Presente","he":"הווה"},{"term":"Profesión","he":"מקצוע"},{"term":"Proyecto","he":"פרויקט"},{"term":"Puesto","he":"משרה"},{"term":"Rutina","he":"שגרה"},{"term":"Salario","he":"משכורת"},{"term":"Trabajo","he":"עבודה"},{"term":"Vida laboral","he":"חיים מקצועיים"},{"term":"Vida personal","he":"חיים אישיים"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/1071844576/carrera-y-desarrollo-personal-flash-cards/?new"}]','published','workbook L3 unit 03',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-01','es3-carrera-y-desarrollo-personal','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"נרטיב / סיפור ___","input":"text"},{"prompt":"השערה ___","input":"text"},{"prompt":"מנהל / בוס ___","input":"text"},{"prompt":"תקשורת ___","input":"text"},{"prompt":"הצלחה ___","input":"text"},{"prompt":"עמית ___","input":"text"}]}','{"items":[{"display":"Narración","answers":["Narración"]},{"display":"Hipótesis","answers":["Hipótesis"]},{"display":"Jefe","answers":["Jefe"]},{"display":"Comunicación","answers":["Comunicación"]},{"display":"Éxito","answers":["Éxito"]},{"display":"Colega","answers":["Colega"]}],"policy":{"accents":"lenient"}}','published','L3-U03-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-02','es3-carrera-y-desarrollo-personal','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Narración","Hipótesis","Jefe","Comunicación","Éxito","Colega","Confianza","Formación"],"right":[{"id":"A","text":"הכשרה"},{"id":"B","text":"תקשורת"},{"id":"C","text":"מנהל / בוס"},{"id":"D","text":"הצלחה"},{"id":"E","text":"נרטיב / סיפור"},{"id":"F","text":"אמון / ביטחון"},{"id":"G","text":"השערה"},{"id":"H","text":"עמית"}]}','{"pairs":["E","G","C","B","D","H","F","A"],"policy":{"accents":"lenient"}}','published','L3-U03-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-03','es3-carrera-y-desarrollo-personal','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"נרטיב / סיפור","input":"choice","options":["Carrera","Narración","Jefe"]},{"prompt":"השערה","input":"choice","options":["Hipótesis","Vida personal","Colega"]},{"prompt":"מנהל / בוס","input":"choice","options":["Presente","Profesión","Jefe"]},{"prompt":"תקשורת","input":"choice","options":["Motivación","Currículum","Comunicación"]},{"prompt":"הצלחה","input":"choice","options":["Desafío","Éxito","Entrevista"]},{"prompt":"עמית","input":"choice","options":["Currículum","Oportunidad","Colega"]}]}','{"items":[{"display":"Narración","choice":1},{"display":"Hipótesis","choice":0},{"display":"Jefe","choice":2},{"display":"Comunicación","choice":2},{"display":"Éxito","choice":1},{"display":"Colega","choice":2}],"policy":{"accents":"lenient"}}','published','L3-U03-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-04','es3-carrera-y-desarrollo-personal','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"אמון / ביטחון = ___","input":"bank"},{"prompt":"שגרה = ___","input":"bank"}],"wordbank":["entrevista","currículum","jefe","puesto","Confianza","Rutina"],"text":"Lucía ha trabajado en tres empresas y ahora busca un {{1}} con más responsabilidad. En su empleo anterior no recibió suficiente apoyo; si su {{2}} la hubiera orientado mejor, habría crecido más rápido. Esta semana su {{3}} fue revisado y mañana tendrá una nueva {{4}}."}','{"items":[{"display":"puesto","answers":["puesto"]},{"display":"jefe","answers":["jefe"]},{"display":"currículum","answers":["currículum"]},{"display":"entrevista","answers":["entrevista"]},{"display":"Confianza","answers":["Confianza"]},{"display":"Rutina","answers":["Rutina"]}],"policy":{"accents":"strict"}}','published','L3-U03-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-05','es3-carrera-y-desarrollo-personal','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["haces","de","manera","en","Qué","trabajo","rutinaria","el"]},{"prompt":"","input":"tokens","tokens":["el","dinero","en","para","el","Qué","personal","ti","o","interés","es","más","trabajo","el","importante"]},{"prompt":"","input":"tokens","tokens":["es","sí","significativo","ti","trabajo","qué","Sientes","no","tu","para","qué","que","Por","o","por"]},{"prompt":"","input":"tokens","tokens":["Qué","por","trabajo","otras","ti","cosas","además","del","haces","mismo"]}]}','{"items":[{"display":"¿Qué haces en el trabajo de manera rutinaria?","answers":["¿Qué haces en el trabajo de manera rutinaria?"]},{"display":"¿Qué es más importante para ti en el trabajo: el dinero o el interés personal?","answers":["¿Qué es más importante para ti en el trabajo: el dinero o el interés personal?"]},{"display":"¿Sientes que tu trabajo es significativo para ti? ¿Por qué sí o por qué no?","answers":["¿Sientes que tu trabajo es significativo para ti? ¿Por qué sí o por qué no?"]},{"display":"¿Qué otras cosas haces por ti mismo además del trabajo?","answers":["¿Qué otras cosas haces por ti mismo además del trabajo?"]}],"policy":{"accents":"strict"}}','published','L3-U03-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-06','es3-carrera-y-desarrollo-personal','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Lucía ha trabajó en tres empresas.","input":"sentence"},{"prompt":"Si su jefe la hubiera apoyado, crecería más rápido entonces.","input":"sentence"},{"prompt":"Su currículum fue revisar ayer.","input":"sentence"},{"prompt":"Mañana tuvo una entrevista.","input":"sentence"}]}','{"items":[{"display":"Lucía ha trabajado en tres empresas.","answers":["Lucía ha trabajado en tres empresas."]},{"display":"Si su jefe la hubiera apoyado, habría crecido más rápido.","answers":["Si su jefe la hubiera apoyado, habría crecido más rápido."]},{"display":"Su currículum fue revisado ayer.","answers":["Su currículum fue revisado ayer."]},{"display":"Mañana tendrá una entrevista.","answers":["Mañana tendrá una entrevista."]}],"policy":{"accents":"strict"}}','published','L3-U03-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-07','es3-carrera-y-desarrollo-personal','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Lucía ha trabajado en tres empresas.","Lucía ha trabajó en tres empresas."]},{"prompt":"","input":"choice","options":["Si su jefe la hubiera apoyado, crecería más rápido entonces.","Si su jefe la hubiera apoyado, habría crecido más rápido."]},{"prompt":"","input":"choice","options":["Su currículum fue revisado ayer.","Su currículum fue revisar ayer."]},{"prompt":"","input":"choice","options":["Mañana tendrá una entrevista.","Mañana tuvo una entrevista."]}]}','{"items":[{"display":"Lucía ha trabajó en tres empresas.","choice":1},{"display":"Si su jefe la hubiera apoyado, habría crecido más rápido.","choice":1},{"display":"Su currículum fue revisar ayer.","choice":1},{"display":"Mañana tuvo una entrevista.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U03-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-08','es3-carrera-y-desarrollo-personal','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**Lucía** · trabajar · hasta ahora","input":"text"},{"prompt":"**ella** · crecer · si hubiera recibido apoyo","input":"text"},{"prompt":"**el candidato** · seleccionar · ayer","input":"text"},{"prompt":"**yo** · actualizar · mañana","input":"text"}]}','{"items":[{"display":"ha trabajado","answers":["ha trabajado"]},{"display":"habría crecido","answers":["habría crecido"]},{"display":"fue seleccionado","answers":["fue seleccionado"]},{"display":"actualizaré","answers":["actualizaré"]}],"policy":{"accents":"strict"}}','published','L3-U03-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-09','es3-carrera-y-desarrollo-personal','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Qué haces en el trabajo de manera rutinaria?\n¿Qué es más importante para ti en el trabajo: el dinero o el interés personal?\n¿Sientes que tu trabajo es significativo para ti? ¿Por qué sí o por qué no?\n¿Qué otras cosas haces por ti mismo además del trabajo?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U03-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-10','es3-carrera-y-desarrollo-personal','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**Lucía** · trabajar · hasta ahora","input":"text"},{"prompt":"**ella** · crecer · si hubiera recibido apoyo","input":"text"},{"prompt":"**el candidato** · seleccionar · ayer","input":"text"},{"prompt":"**yo** · actualizar · mañana","input":"text"},{"prompt":"**nosotros** · aceptar · si ofrecieran mejores condiciones","input":"text"},{"prompt":"**la vacante** · publicar · esta semana","input":"text"},{"prompt":"**tú** · dirigir · el año pasado","input":"text"},{"prompt":"**ellos** · ascender · si trabajaran mejor","input":"text"}]}','{"items":[{"display":"ha trabajado","answers":["ha trabajado"]},{"display":"habría crecido","answers":["habría crecido"]},{"display":"fue seleccionado","answers":["fue seleccionado"]},{"display":"actualizaré","answers":["actualizaré"]},{"display":"aceptaríamos","answers":["aceptaríamos"]},{"display":"ha sido publicada","answers":["ha sido publicada"]},{"display":"dirigiste","answers":["dirigiste"]},{"display":"ascenderían","answers":["ascenderían"]}],"policy":{"accents":"strict"}}','published','L3-U03-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-11','es3-carrera-y-desarrollo-personal','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué busca Lucía?","input":"sentence"},{"prompt":"¿Qué habría ocurrido con más orientación?","input":"sentence"},{"prompt":"¿Qué fue revisado esta semana?","input":"sentence"}],"text":"Lucía ha trabajado en tres empresas y ahora busca un puesto con más responsabilidad. En su empleo anterior no recibió suficiente apoyo; si su jefe la hubiera orientado mejor, habría crecido más rápido. Esta semana su currículum fue revisado y mañana tendrá una nueva entrevista."}','{"items":[{"display":"Un puesto con más responsabilidad.","answers":["Un puesto con más responsabilidad."]},{"display":"Habría crecido más rápido.","answers":["Habría crecido más rápido."]},{"display":"Su currículum.","answers":["Su currículum."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U03-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-12','es3-carrera-y-desarrollo-personal','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Carrera y desarrollo personal\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Lucía ha trabajado en tres empresas y ahora busca un puesto con más responsabilidad. En su empleo anterior no recibió suficiente apoyo; si su jefe la hubiera orientado mejor, habría crecido más rápido. Esta semana su currículum fue revisado y mañana tendrá una nueva entrevista."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U03-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-13','es3-carrera-y-desarrollo-personal','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: Habría crecido más rápido."},{"id":"B","text":"Respuesta: Su currículum."},{"id":"C","text":"Respuesta: Un puesto con más responsabilidad."},{"id":"D","text":"Pregunta: ¿Qué habría ocurrido con más orientación?"},{"id":"E","text":"Pregunta: ¿Qué busca Lucía?"},{"id":"F","text":"Pregunta: ¿Qué fue revisado esta semana?"}]}','{"order":["E","C","D","A","F","B"],"policy":{"accents":"strict"}}','published','L3-U03-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-14','es3-carrera-y-desarrollo-personal','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"En su empleo anterior no recibió suficiente apoyo; si su jefe la hubiera orientado mejor, habría crecido más rápido."},{"id":"B","text":"Lucía ha trabajado en tres empresas y ahora busca un puesto con más responsabilidad."},{"id":"C","text":"Esta semana su currículum fue revisado y mañana tendrá una nueva entrevista."}]}','{"order":["B","A","C"],"policy":{"accents":"strict"}}','published','L3-U03-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-15','es3-carrera-y-desarrollo-personal','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre carrera y desarrollo personal es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre carrera y desarrollo personal es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U03-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-16','es3-carrera-y-desarrollo-personal','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"מנהל / בוס = ___","input":"text"},{"prompt":"תקשורת = ___","input":"text"},{"prompt":"הצלחה = ___","input":"text"},{"prompt":"עמית = ___","input":"text"},{"prompt":"**ellos** · ascender · si trabajaran mejor","input":"text"},{"prompt":"**tú** · dirigir · el año pasado","input":"text"},{"prompt":"**la vacante** · publicar · esta semana","input":"text"},{"prompt":"**nosotros** · aceptar · si ofrecieran mejores condiciones","input":"text"},{"prompt":"**yo** · actualizar · mañana","input":"text"},{"prompt":"**el candidato** · seleccionar · ayer","input":"text"}]}','{"items":[{"display":"Jefe","answers":["Jefe"],"policy":{"accents":"lenient"}},{"display":"Comunicación","answers":["Comunicación"],"policy":{"accents":"lenient"}},{"display":"Éxito","answers":["Éxito"],"policy":{"accents":"lenient"}},{"display":"Colega","answers":["Colega"],"policy":{"accents":"lenient"}},{"display":"ascenderían","answers":["ascenderían"]},{"display":"dirigiste","answers":["dirigiste"]},{"display":"ha sido publicada","answers":["ha sido publicada"]},{"display":"aceptaríamos","answers":["aceptaríamos"]},{"display":"actualizaré","answers":["actualizaré"]},{"display":"fue seleccionado","answers":["fue seleccionado"]}],"policy":{"accents":"strict"}}','published','L3-U03-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-17','es3-carrera-y-desarrollo-personal','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Lucía ha trabajado en tres empresas y ahora busca un puesto con más responsabilidad. En su empleo anterior no recibió suficiente apoyo; si su jefe la hubiera orientado mejor, habría crecido más rápido."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U03-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-18','es3-carrera-y-desarrollo-personal','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"¿Qué haces en el ___ de manera rutinaria? (di tres cosas).","input":"bank"},{"prompt":"Mañana voy a presentar un ___ importante.","input":"bank"},{"prompt":"¿Qué necesitas hacer para tener un buen equilibrio entre la ___ y personal?","input":"bank"},{"prompt":"¿Cuál es la fuente de ___?","input":"bank"},{"prompt":"Futuro/___: en el futuro…, dentro de cinco años…, si pudiera…, me gustaría…","input":"bank"},{"prompt":"Háblame de un éxito o un ___ que te enseñó algo importante.","input":"bank"},{"prompt":"Si mi jefe anterior me hubiera dado más apoyo, habría crecido más en la ___.","input":"bank"},{"prompt":"¿Qué necesitas hacer para tener un buen ___ entre la vida laboral y personal?","input":"bank"},{"prompt":"Usar estructuras claras en presente, pasado y ___.","input":"bank"},{"prompt":"Usar estructuras claras en presente, ___ y futuro.","input":"bank"}],"wordbank":["Empresa","Fracaso","Trabajo","Proyecto","Condicional","Vida laboral","Pasado","Inspiración","Equilibrio","Futuro"]}','{"items":[{"display":"Trabajo","answers":["Trabajo"]},{"display":"Proyecto","answers":["Proyecto"]},{"display":"Vida laboral","answers":["Vida laboral"]},{"display":"Inspiración","answers":["Inspiración"]},{"display":"Condicional","answers":["Condicional"]},{"display":"Fracaso","answers":["Fracaso"]},{"display":"Empresa","answers":["Empresa"]},{"display":"Equilibrio","answers":["Equilibrio"]},{"display":"Futuro","answers":["Futuro"]},{"display":"Pasado","answers":["Pasado"]}],"policy":{"accents":"strict"}}','published','L3-U03-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-19','es3-carrera-y-desarrollo-personal','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Lucía ___ hasta ahora.","input":"text","hint":"trabajar"},{"prompt":"Si hubiera recibido apoyo, ella ___.","input":"text","hint":"crecer"},{"prompt":"Ayer, el candidato ___.","input":"text","hint":"seleccionar"},{"prompt":"Mañana, yo ___.","input":"text","hint":"actualizar"},{"prompt":"Si ofrecieran mejores condiciones, nosotros ___.","input":"text","hint":"aceptar"},{"prompt":"Esta semana, la vacante ___.","input":"text","hint":"publicar"},{"prompt":"El año pasado, tú ___.","input":"text","hint":"dirigir"},{"prompt":"Si trabajaran mejor, ellos ___.","input":"text","hint":"ascender"}]}','{"items":[{"display":"ha trabajado","answers":["ha trabajado"]},{"display":"habría crecido","answers":["habría crecido"]},{"display":"fue seleccionado","answers":["fue seleccionado"]},{"display":"actualizaré","answers":["actualizaré"]},{"display":"aceptaríamos","answers":["aceptaríamos"]},{"display":"ha sido publicada","answers":["ha sido publicada"]},{"display":"dirigiste","answers":["dirigiste"]},{"display":"ascenderían","answers":["ascenderían"]}],"policy":{"accents":"strict"}}','published','L3-U03-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-carrera-y-desarrollo-personal-20','es3-carrera-y-desarrollo-personal','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Qué preparó Nuria?","input":"sentence"},{"prompt":"¿Quién revisó su portafolio?","input":"sentence"},{"prompt":"¿Qué le ofreció la empresa?","input":"sentence"},{"prompt":"¿Por qué no quiso elegir solo por el sueldo?","input":"sentence"},{"prompt":"¿Cómo define Nuria ahora el éxito?","input":"sentence"}],"text":"Nuria quería cambiar de profesión, pero no tenía experiencia formal en el nuevo sector. Preparó un portafolio con proyectos personales y pidió a una mentora que lo revisara. Durante la entrevista explicó qué habilidades podía transferir de su empleo anterior. La empresa valoró su preparación y le ofreció un puesto inicial con un plan de formación.\n\nAntes de solicitar el puesto, Nuria había hablado con varios colegas y había analizado el equilibrio entre la vida laboral y la vida personal. Si hubiera elegido solo por el sueldo, quizá habría repetido la rutina que quería abandonar. Durante el proceso, su candidatura fue evaluada por dos responsables y su experiencia anterior fue considerada una ventaja. La mentora le aconsejó que no ocultara los fracasos, sino que explicara lo que había aprendido de ellos. Nuria piensa que, si recibe apoyo del nuevo jefe y mantiene objetivos realistas, podrá desarrollar su carrera sin sacrificar su bienestar. Para ella, el éxito ya no significa trabajar más horas, sino avanzar con una dirección clara.\n\nUn mes después, Nuria empezó la formación y comprobó que todavía tenía mucho que aprender. No obstante, se sintió valorada por sus colegas y pudo aplicar habilidades que había desarrollado en otros trabajos. El cambio profesional dejó de parecerle un fracaso."}','{"items":[{"display":"Un portafolio con proyectos personales","answers":["Un portafolio con proyectos personales"]},{"display":"Una mentora","answers":["Una mentora"]},{"display":"Un puesto inicial con un plan de formación","answers":["Un puesto inicial con un plan de formación"]},{"display":"Porque podría repetir la rutina que quería abandonar","answers":["Porque podría repetir la rutina que quería abandonar"]},{"display":"Como avanzar con una dirección clara sin trabajar más horas","answers":["Como avanzar con una dirección clara sin trabajar más horas"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U03-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial','es-3','es-3-society','בינה מלאכותית','Inteligencia artificial','לדבר ולכתוב על הנושא „בינה מלאכותית“ בספרדית, תוך שימוש במבנים: Futuro, hipótesis, pasiva y argumentación.','derived','[{"he":"דקדוק בשימוש","target":"Futuro, hipótesis, pasiva y argumentación"},{"he":"אוצר מילים: בינה מלאכותית","target":"Inteligencia artificial"}]','["Futuro, hipótesis, pasiva y argumentación"]','{"rules":[],"examples":["Los datos son analizados automáticamente.","El próximo año la herramienta responderá mejor.","Sería más útil si protegieran la privacidad.","La escuela ha adoptado un asistente."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Android","he":"אנדרואיד"},{"term":"Aplicación","he":"אפליקציה"},{"term":"Aprender","he":"ללמוד"},{"term":"Argumento","he":"טיעון"},{"term":"Cambio","he":"שינוי"},{"term":"Canción","he":"שיר"},{"term":"Candidatura","he":"מועמדות"},{"term":"Computadora","he":"מחשב"},{"term":"Condicional","he":"משפט תנאי / תנאי / מותנה"},{"term":"Convincente","he":"משכנע"},{"term":"Creatividad","he":"יצירתיות"},{"term":"Debate","he":"דיון / ויכוח"},{"term":"Definición","he":"הגדרה"},{"term":"Distopía","he":"דיסטופיה"},{"term":"Elecciones","he":"בחירות"},{"term":"Estudiante","he":"תלמיד / סטודנט / תלמיד"},{"term":"Futuro","he":"עתיד"},{"term":"Habilidad","he":"יכולת"},{"term":"Hipotético","he":"היפותטי"},{"term":"historia","he":"סיפור"},{"term":"Información","he":"מידע"},{"term":"Innovación","he":"חדשנות"},{"term":"Inteligencia artificial","he":"בינה מלאכותית"},{"term":"Internet","he":"אינטרנט"},{"term":"Lenguaje natural","he":"שפה טבעית"},{"term":"Máquina","he":"מכונה"},{"term":"Mundo","he":"עולם"},{"term":"Opinión","he":"דעה"},{"term":"Predicción","he":"נבואה"},{"term":"Profesor","he":"מורה"},{"term":"Realidad","he":"מציאות"},{"term":"Resolver problemas","he":"לפתור בעיות"},{"term":"Robot","he":"רובוט"},{"term":"Rol","he":"תפקיד"},{"term":"Superviviente","he":"שורד"},{"term":"Tecnología","he":"טכנולוגיה"},{"term":"Utopía","he":"אוטופיה"},{"term":"Voto","he":"הצבעה"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1073072642/clase-ia-actualizada-flash-cards/?i=1b52po&x=1jqt"}]','published','workbook L3 unit 04',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-01','es3-inteligencia-artificial','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"שפה טבעית ___","input":"text"},{"prompt":"אוטופיה ___","input":"text"},{"prompt":"הגדרה ___","input":"text"},{"prompt":"עתיד ___","input":"text"},{"prompt":"מועמדות ___","input":"text"},{"prompt":"יצירתיות ___","input":"text"}]}','{"items":[{"display":"Lenguaje natural","answers":["Lenguaje natural"]},{"display":"Utopía","answers":["Utopía"]},{"display":"Definición","answers":["Definición"]},{"display":"Futuro","answers":["Futuro"]},{"display":"Candidatura","answers":["Candidatura"]},{"display":"Creatividad","answers":["Creatividad"]}],"policy":{"accents":"lenient"}}','published','L3-U04-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-02','es3-inteligencia-artificial','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Lenguaje natural","Utopía","Definición","Futuro","Candidatura","Creatividad","Robot","Convincente"],"right":[{"id":"A","text":"הגדרה"},{"id":"B","text":"שפה טבעית"},{"id":"C","text":"אוטופיה"},{"id":"D","text":"משכנע"},{"id":"E","text":"מועמדות"},{"id":"F","text":"רובוט"},{"id":"G","text":"יצירתיות"},{"id":"H","text":"עתיד"}]}','{"pairs":["B","C","A","H","E","G","F","D"],"policy":{"accents":"lenient"}}','published','L3-U04-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-03','es3-inteligencia-artificial','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"שפה טבעית","input":"choice","options":["Definición","Lenguaje natural","Voto"]},{"prompt":"אוטופיה","input":"choice","options":["Resolver problemas","Profesor","Utopía"]},{"prompt":"הגדרה","input":"choice","options":["Definición","Resolver problemas","Convincente"]},{"prompt":"עתיד","input":"choice","options":["Máquina","Mundo","Futuro"]},{"prompt":"מועמדות","input":"choice","options":["Candidatura","Estudiante","Realidad"]},{"prompt":"יצירתיות","input":"choice","options":["Creatividad","Mundo","Aplicación"]}]}','{"items":[{"display":"Lenguaje natural","choice":1},{"display":"Utopía","choice":2},{"display":"Definición","choice":0},{"display":"Futuro","choice":2},{"display":"Candidatura","choice":0},{"display":"Creatividad","choice":0}],"policy":{"accents":"lenient"}}','published','L3-U04-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-04','es3-inteligencia-artificial','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"היפותטי = ___","input":"bank"},{"prompt":"בחירות = ___","input":"bank"},{"prompt":"נבואה = ___","input":"bank"},{"prompt":"מורה = ___","input":"bank"},{"prompt":"מכונה = ___","input":"bank"}],"wordbank":["Hipotético","Máquina","Predicción","Profesor","inteligencia artificial","Elecciones"],"text":"Una escuela ha adoptado un asistente de {{1}} para organizar materiales. Los datos son analizados automáticamente, aunque el equipo revisa cada recomendación. El próximo año la herramienta responderá mejor y sería aún más útil si los programadores protegieran la privacidad desde el diseño."}','{"items":[{"display":"inteligencia artificial","answers":["inteligencia artificial"]},{"display":"Hipotético","answers":["Hipotético"]},{"display":"Elecciones","answers":["Elecciones"]},{"display":"Predicción","answers":["Predicción"]},{"display":"Profesor","answers":["Profesor"]},{"display":"Máquina","answers":["Máquina"]}],"policy":{"accents":"strict"}}','published','L3-U04-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-05','es3-inteligencia-artificial','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["hacer","para","tiene","la","IA","tecnología","calificar","Qué","como","que"]},{"prompt":"","input":"tokens","tokens":["tu","ejemplo","de","a","día","usas","en","IA","Qué","día"]},{"prompt":"","input":"tokens","tokens":["el","La","en","cambiará","tu","vida","IA","futuro"]},{"prompt":"","input":"tokens","tokens":["mejor","vida","sería","IA","La","o","sin","peor"]}]}','{"items":[{"display":"¿Qué tiene que hacer la tecnología para calificar como IA?","answers":["¿Qué tiene que hacer la tecnología para calificar como IA?"]},{"display":"¿Qué ejemplo de IA usas en tu día a día?","answers":["¿Qué ejemplo de IA usas en tu día a día?"]},{"display":"¿La IA cambiará tu vida en el futuro?","answers":["¿La IA cambiará tu vida en el futuro?"]},{"display":"¿La vida sin IA sería mejor o peor?","answers":["¿La vida sin IA sería mejor o peor?"]}],"policy":{"accents":"strict"}}','published','L3-U04-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-06','es3-inteligencia-artificial','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Los datos analizan automáticamente.","input":"sentence"},{"prompt":"El próximo año la herramienta respondió mejor.","input":"sentence"},{"prompt":"Sería más útil si protegerán la privacidad.","input":"sentence"},{"prompt":"La escuela ha adoptar un asistente.","input":"sentence"}]}','{"items":[{"display":"Los datos son analizados automáticamente.","answers":["Los datos son analizados automáticamente."]},{"display":"El próximo año la herramienta responderá mejor.","answers":["El próximo año la herramienta responderá mejor."]},{"display":"Sería más útil si protegieran la privacidad.","answers":["Sería más útil si protegieran la privacidad."]},{"display":"La escuela ha adoptado un asistente.","answers":["La escuela ha adoptado un asistente."]}],"policy":{"accents":"strict"}}','published','L3-U04-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-07','es3-inteligencia-artificial','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Los datos analizan automáticamente.","Los datos son analizados automáticamente."]},{"prompt":"","input":"choice","options":["El próximo año la herramienta respondió mejor.","El próximo año la herramienta responderá mejor."]},{"prompt":"","input":"choice","options":["Sería más útil si protegerán la privacidad.","Sería más útil si protegieran la privacidad."]},{"prompt":"","input":"choice","options":["La escuela ha adoptar un asistente.","La escuela ha adoptado un asistente."]}]}','{"items":[{"display":"Los datos son analizados automáticamente.","choice":1},{"display":"El próximo año la herramienta responderá mejor.","choice":1},{"display":"Sería más útil si protegieran la privacidad.","choice":1},{"display":"La escuela ha adoptado un asistente.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U04-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-08','es3-inteligencia-artificial','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**un asistente** · adoptar · este año","input":"text"},{"prompt":"**la herramienta** · responder · el próximo año","input":"text"},{"prompt":"**la IA** · usar · si fuera segura","input":"text"},{"prompt":"**los programadores** · proteger · si lo hubieran previsto","input":"text"}]}','{"items":[{"display":"ha sido adoptado","answers":["ha sido adoptado"]},{"display":"responderá","answers":["responderá"]},{"display":"se usaría","answers":["se usaría"]},{"display":"habrían protegido","answers":["habrían protegido"]}],"policy":{"accents":"strict"}}','published','L3-U04-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-09','es3-inteligencia-artificial','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Qué tiene que hacer la tecnología para calificar como IA?\n¿Qué ejemplo de IA usas en tu día a día?\n¿La IA cambiará tu vida en el futuro?\n¿La vida sin IA sería mejor o peor?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U04-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-10','es3-inteligencia-artificial','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**un asistente** · adoptar · este año","input":"text"},{"prompt":"**la herramienta** · responder · el próximo año","input":"text"},{"prompt":"**la IA** · usar · si fuera segura","input":"text"},{"prompt":"**los programadores** · proteger · si lo hubieran previsto","input":"text"},{"prompt":"**los datos** · analizar · actualmente","input":"text"},{"prompt":"**nosotros** · evaluar · mañana","input":"text"},{"prompt":"**tú** · confiar · si hubiera transparencia","input":"text"},{"prompt":"**el sistema** · mejorar · desde su lanzamiento","input":"text"}]}','{"items":[{"display":"ha sido adoptado","answers":["ha sido adoptado"]},{"display":"responderá","answers":["responderá"]},{"display":"se usaría","answers":["se usaría"]},{"display":"habrían protegido","answers":["habrían protegido"]},{"display":"son analizados","answers":["son analizados"]},{"display":"evaluaremos","answers":["evaluaremos"]},{"display":"confiarías","answers":["confiarías"]},{"display":"ha mejorado","answers":["ha mejorado"]}],"policy":{"accents":"strict"}}','published','L3-U04-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-11','es3-inteligencia-artificial','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Para qué se adoptó el asistente?","input":"sentence"},{"prompt":"¿Cómo son analizados los datos?","input":"sentence"},{"prompt":"¿Qué deberían proteger los programadores?","input":"sentence"}],"text":"Una escuela ha adoptado un asistente de inteligencia artificial para organizar materiales. Los datos son analizados automáticamente, aunque el equipo revisa cada recomendación. El próximo año la herramienta responderá mejor y sería aún más útil si los programadores protegieran la privacidad desde el diseño."}','{"items":[{"display":"Para organizar materiales.","answers":["Para organizar materiales."]},{"display":"Automáticamente.","answers":["Automáticamente."]},{"display":"La privacidad.","answers":["La privacidad."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U04-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-12','es3-inteligencia-artificial','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Inteligencia artificial\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Una escuela ha adoptado un asistente de inteligencia artificial para organizar materiales. Los datos son analizados automáticamente, aunque el equipo revisa cada recomendación. El próximo año la herramienta responderá mejor y sería aún más útil si los programadores protegieran la privacidad desde el diseño."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U04-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-13','es3-inteligencia-artificial','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Cómo son analizados los datos?"},{"id":"B","text":"Respuesta: Automáticamente."},{"id":"C","text":"Pregunta: ¿Qué deberían proteger los programadores?"},{"id":"D","text":"Respuesta: Para organizar materiales."},{"id":"E","text":"Respuesta: La privacidad."},{"id":"F","text":"Pregunta: ¿Para qué se adoptó el asistente?"}]}','{"order":["F","D","A","B","C","E"],"policy":{"accents":"strict"}}','published','L3-U04-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-14','es3-inteligencia-artificial','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Los datos son analizados automáticamente, aunque el equipo revisa cada recomendación."},{"id":"B","text":"El próximo año la herramienta responderá mejor y sería aún más útil si los programadores protegieran la privacidad desde el diseño."},{"id":"C","text":"Una escuela ha adoptado un asistente de inteligencia artificial para organizar materiales."}]}','{"order":["C","A","B"],"policy":{"accents":"strict"}}','published','L3-U04-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-15','es3-inteligencia-artificial','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre inteligencia artificial es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre inteligencia artificial es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U04-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-16','es3-inteligencia-artificial','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"הגדרה = ___","input":"text"},{"prompt":"עתיד = ___","input":"text"},{"prompt":"מועמדות = ___","input":"text"},{"prompt":"יצירתיות = ___","input":"text"},{"prompt":"**el sistema** · mejorar · desde su lanzamiento","input":"text"},{"prompt":"**tú** · confiar · si hubiera transparencia","input":"text"},{"prompt":"**nosotros** · evaluar · mañana","input":"text"},{"prompt":"**los datos** · analizar · actualmente","input":"text"},{"prompt":"**los programadores** · proteger · si lo hubieran previsto","input":"text"},{"prompt":"**la IA** · usar · si fuera segura","input":"text"}]}','{"items":[{"display":"Definición","answers":["Definición"],"policy":{"accents":"lenient"}},{"display":"Futuro","answers":["Futuro"],"policy":{"accents":"lenient"}},{"display":"Candidatura","answers":["Candidatura"],"policy":{"accents":"lenient"}},{"display":"Creatividad","answers":["Creatividad"],"policy":{"accents":"lenient"}},{"display":"ha mejorado","answers":["ha mejorado"]},{"display":"confiarías","answers":["confiarías"]},{"display":"evaluaremos","answers":["evaluaremos"]},{"display":"son analizados","answers":["son analizados"]},{"display":"habrían protegido","answers":["habrían protegido"]},{"display":"se usaría","answers":["se usaría"]}],"policy":{"accents":"strict"}}','published','L3-U04-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-17','es3-inteligencia-artificial','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Una escuela ha adoptado un asistente de inteligencia artificial para organizar materiales. Los datos son analizados automáticamente, aunque el equipo revisa cada recomendación."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U04-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-18','es3-inteligencia-artificial','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"Cada estudiante elige un ___ diferente. Tendrán 10 minutos para preparar su candidatura.","input":"bank"},{"prompt":"Si hubiera una ___, yo sería el mejor líder.","input":"bank"},{"prompt":"“Mi ___ será un rap sobre mi perro, que es grande y cariñoso.”","input":"bank"},{"prompt":"Cada ___ elige un rol diferente. Tendrán 10 minutos para preparar su candidatura.","input":"bank"},{"prompt":"Una ___ en futuro.","input":"bank"},{"prompt":"___ / condicional (situaciones posibles o imaginarias).","input":"bank"},{"prompt":"El ___ comparte la pantalla y lee el texto en voz alta.","input":"bank"},{"prompt":"“Continúa la ___ con 5 frases usando el futuro (será, cambiará, viviremos…).”","input":"bank"},{"prompt":"Tu ___ personal: “¿La IA reemplazará a los profesores?”","input":"bank"},{"prompt":"Hipotético / ___ (situaciones posibles o imaginarias).","input":"bank"}],"wordbank":["Opinión","Predicción","Rol","Historia","Profesor","Hipotético","Estudiante","Distopía","Condicional","Canción"]}','{"items":[{"display":"Rol","answers":["Rol"]},{"display":"Distopía","answers":["Distopía"]},{"display":"Canción","answers":["Canción"]},{"display":"Estudiante","answers":["Estudiante"]},{"display":"Predicción","answers":["Predicción"]},{"display":"Hipotético","answers":["Hipotético"]},{"display":"Profesor","answers":["Profesor"]},{"display":"Historia","answers":["Historia"]},{"display":"Opinión","answers":["Opinión"]},{"display":"Condicional","answers":["Condicional"]}],"policy":{"accents":"strict"}}','published','L3-U04-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-19','es3-inteligencia-artificial','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Este año, un asistente ___.","input":"text","hint":"adoptar"},{"prompt":"El próximo año, la herramienta ___.","input":"text","hint":"responder"},{"prompt":"Si fuera segura, la IA ___.","input":"text","hint":"usar"},{"prompt":"Si lo hubieran previsto, los programadores ___.","input":"text","hint":"proteger"},{"prompt":"Actualmente, los datos ___.","input":"text","hint":"analizar"},{"prompt":"Mañana, nosotros ___.","input":"text","hint":"evaluar"},{"prompt":"Si hubiera transparencia, tú ___.","input":"text","hint":"confiar"},{"prompt":"El sistema ___ desde su lanzamiento.","input":"text","hint":"mejorar"}]}','{"items":[{"display":"ha sido adoptado","answers":["ha sido adoptado"]},{"display":"responderá","answers":["responderá"]},{"display":"se usaría","answers":["se usaría"]},{"display":"habrían protegido","answers":["habrían protegido"]},{"display":"son analizados","answers":["son analizados"]},{"display":"evaluaremos","answers":["evaluaremos"]},{"display":"confiarías","answers":["confiarías"]},{"display":"ha mejorado","answers":["ha mejorado"]}],"policy":{"accents":"strict"}}','published','L3-U04-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-inteligencia-artificial-20','es3-inteligencia-artificial','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Para qué incorporó la clínica el asistente?","input":"sentence"},{"prompt":"¿Qué hizo el equipo antes de activarlo?","input":"sentence"},{"prompt":"¿Quién conservó la responsabilidad final?","input":"sentence"},{"prompt":"¿Durante cuánto tiempo será evaluado el proyecto?","input":"sentence"},{"prompt":"¿Qué podría ocurrir si la herramienta aprendiera de información incompleta?","input":"sentence"}],"text":"Una clínica incorporó un asistente de inteligencia artificial para organizar citas y resumir documentos. Antes de activarlo, el equipo eliminó los datos que podían identificar a los pacientes. Además, ninguna recomendación médica se enviaba sin revisión humana. El sistema ahorró tiempo, pero la directora recordó que la responsabilidad final seguía siendo de los profesionales.\n\nEl proyecto fue presentado primero a un comité de ética y después será evaluado durante seis meses. Los responsables predicen que el asistente reducirá las tareas repetitivas y permitirá que el personal dedique más tiempo a los pacientes. No obstante, algunos trabajadores temen que un robot tome decisiones que requieren empatía. Si la herramienta aprendiera de información incompleta, podría producir recomendaciones injustas. Por eso, todos los resultados serán revisados y cualquier error será documentado. La directora cree que, en el futuro, la inteligencia artificial resolverá muchos problemas, pero insiste en que el lenguaje natural y la habilidad humana para comprender el contexto seguirán siendo esenciales.\n\nLa clínica publicará un informe con los cambios, los errores y el tiempo ahorrado. De este modo, los pacientes podrán saber cómo se utiliza su información. Si el proceso resulta transparente, la tecnología será aceptada con más confianza."}','{"items":[{"display":"Para organizar citas y resumir documentos","answers":["Para organizar citas y resumir documentos"]},{"display":"Eliminó los datos que podían identificar a los pacientes","answers":["Eliminó los datos que podían identificar a los pacientes"]},{"display":"Los profesionales","answers":["Los profesionales"]},{"display":"Durante seis meses","answers":["Durante seis meses"]},{"display":"Podría producir recomendaciones injustas","answers":["Podría producir recomendaciones injustas"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U04-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas','es-3','es-3-stories','מציאויות חלופיות','Realidades alternativas','לדבר ולכתוב על הנושא „מציאויות חלופיות“ בספרדית, תוך שימוש במבנים: Segundo, tercer y condicional mixto.','derived','[{"he":"דקדוק בשימוש","target":"Segundo, tercer y condicional mixto"},{"he":"אוצר מילים: מציאויות חלופיות","target":"Realidades alternativas"}]','["Segundo, tercer y condicional mixto"]','{"rules":[],"examples":["Si pudiera mudarme, investigaría el océano.","Si hubieran construido la ciudad, ya habríamos aprendido mucho más.","Una decisión podría haber cambiado el presente.","Si viviera allí, sería feliz."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Alternar / cambiar","he":"להחליף"},{"term":"Alternativa","he":"חלופה"},{"term":"Cambio","he":"שינוי"},{"term":"Causalidad","he":"סיבתיות"},{"term":"Condicional","he":"משפט תנאי / תנאי / מותנה"},{"term":"Consecuencia","he":"תוצאה"},{"term":"Creatividad","he":"יצירתיות"},{"term":"Cronología","he":"כרונולוגיה"},{"term":"Decisión","he":"החלטה"},{"term":"Destino","he":"גורל"},{"term":"Distopía","he":"דיסטופיה"},{"term":"Divergencia","he":"הסתעפות"},{"term":"Escenario","he":"תרחיש / זירה / סצנה"},{"term":"Especulación","he":"ספקולציה"},{"term":"Especulativo","he":"ספקולטיבי"},{"term":"Falso","he":"מזויף"},{"term":"Futuro","he":"עתיד"},{"term":"Hipotético","he":"היפותטי"},{"term":"historia","he":"סיפור"},{"term":"Imaginación","he":"דמיון"},{"term":"Inteligencia artificial","he":"בינה מלאכותית"},{"term":"Inversión (cambio)","he":"היפוך"},{"term":"Línea de tiempo","he":"ציר זמן"},{"term":"Multiverso","he":"יקום-רב"},{"term":"Mundo","he":"עולם"},{"term":"Narrativa","he":"נרטיב / סיפור / נרטיב"},{"term":"Oportunidad","he":"הזדמנות"},{"term":"Paradoja","he":"פרדוקס"},{"term":"Pasado","he":"עבר"},{"term":"Posibilidad","he":"אפשרות"},{"term":"Presente","he":"הווה"},{"term":"Realidad alternativa","he":"מציאות חלופית"},{"term":"Reinventar","he":"לדמיין מחדש"},{"term":"Resultado","he":"תוצאה"},{"term":"Revisionista","he":"רוויזיוניסטי"},{"term":"Sociedad","he":"חברה"},{"term":"Tecnología","he":"טכנולוגיה"},{"term":"Utopía","he":"אוטופיה"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/1070299625/realidades-alternativas-actualizado-flash-cards/?new"}]','published','workbook L3 unit 05',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-01','es3-realidades-alternativas','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"דמיון ___","input":"text"},{"prompt":"מותנה ___","input":"text"},{"prompt":"לדמיין מחדש ___","input":"text"},{"prompt":"עתיד ___","input":"text"},{"prompt":"יקום-רב ___","input":"text"},{"prompt":"סיבתיות ___","input":"text"}]}','{"items":[{"display":"Imaginación","answers":["Imaginación"]},{"display":"Condicional","answers":["Condicional"]},{"display":"Reinventar","answers":["Reinventar"]},{"display":"Futuro","answers":["Futuro"]},{"display":"Multiverso","answers":["Multiverso"]},{"display":"Causalidad","answers":["Causalidad"]}],"policy":{"accents":"lenient"}}','published','L3-U05-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-02','es3-realidades-alternativas','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Imaginación","Condicional","Reinventar","Futuro","Multiverso","Causalidad","Especulativo","Falso"],"right":[{"id":"A","text":"סיבתיות"},{"id":"B","text":"דמיון"},{"id":"C","text":"לדמיין מחדש"},{"id":"D","text":"יקום-רב"},{"id":"E","text":"עתיד"},{"id":"F","text":"ספקולטיבי"},{"id":"G","text":"מותנה"},{"id":"H","text":"מזויף"}]}','{"pairs":["B","G","C","E","D","A","F","H"],"policy":{"accents":"lenient"}}','published','L3-U05-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-03','es3-realidades-alternativas','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"דמיון","input":"choice","options":["Alternar / cambiar","Imaginación","Narrativa"]},{"prompt":"מותנה","input":"choice","options":["Escenario","Pasado","Condicional"]},{"prompt":"לדמיין מחדש","input":"choice","options":["Reinventar","Consecuencia","Causalidad"]},{"prompt":"עתיד","input":"choice","options":["Realidad alternativa","Futuro","Divergencia"]},{"prompt":"יקום-רב","input":"choice","options":["Causalidad","Multiverso","Divergencia"]},{"prompt":"סיבתיות","input":"choice","options":["Causalidad","Alternar / cambiar","Especulativo"]}]}','{"items":[{"display":"Imaginación","choice":1},{"display":"Condicional","choice":2},{"display":"Reinventar","choice":0},{"display":"Futuro","choice":1},{"display":"Multiverso","choice":1},{"display":"Causalidad","choice":0}],"policy":{"accents":"lenient"}}','published','L3-U05-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-04','es3-realidades-alternativas','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"גורל = ___","input":"bank"},{"prompt":"כרונולוגיה = ___","input":"bank"},{"prompt":"ציר זמן = ___","input":"bank"}],"wordbank":["pasado","Línea de tiempo","decisión","presente","Cronología","Destino"],"text":"Nora imagina cómo sería vivir en una ciudad submarina. Si pudiera mudarse allí, investigaría el océano; si los científicos hubieran construido esa ciudad hace décadas, ya habríamos aprendido mucho más. Una sola {{1}} del {{2}} podría haber cambiado nuestro {{3}}."}','{"items":[{"display":"decisión","answers":["decisión"]},{"display":"pasado","answers":["pasado"]},{"display":"presente","answers":["presente"]},{"display":"Destino","answers":["Destino"]},{"display":"Cronología","answers":["Cronología"]},{"display":"Línea de tiempo","answers":["Línea de tiempo"]}],"policy":{"accents":"strict"}}','published','L3-U05-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-05','es3-realidades-alternativas','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["y","qué","elegirías","por","cuál"]},{"prompt":"","input":"tokens","tokens":["alternativa","historia","Qué","significa","para","la","ti"]},{"prompt":"","input":"tokens","tokens":["qué","eso","cambiarías","Por"]},{"prompt":"","input":"tokens","tokens":["vida","mejoraría","Cómo","tu"]}]}','{"items":[{"display":"¿cuál elegirías y por qué?","answers":["¿cuál elegirías y por qué?"]},{"display":"¿Qué significa para ti la historia alternativa?","answers":["¿Qué significa para ti la historia alternativa?"]},{"display":"¿Por qué cambiarías eso?","answers":["¿Por qué cambiarías eso?"]},{"display":"¿Cómo mejoraría tu vida?","answers":["¿Cómo mejoraría tu vida?"]}],"policy":{"accents":"strict"}}','published','L3-U05-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-06','es3-realidades-alternativas','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Si podría mudarme, investigaría el océano.","input":"sentence"},{"prompt":"Si hubieran construido la ciudad, aprenderíamos ya mucho más.","input":"sentence"},{"prompt":"Una decisión podría cambió el presente.","input":"sentence"},{"prompt":"Si viviría allí, sería feliz.","input":"sentence"}]}','{"items":[{"display":"Si pudiera mudarme, investigaría el océano.","answers":["Si pudiera mudarme, investigaría el océano."]},{"display":"Si hubieran construido la ciudad, ya habríamos aprendido mucho más.","answers":["Si hubieran construido la ciudad, ya habríamos aprendido mucho más."]},{"display":"Una decisión podría haber cambiado el presente.","answers":["Una decisión podría haber cambiado el presente."]},{"display":"Si viviera allí, sería feliz.","answers":["Si viviera allí, sería feliz."]}],"policy":{"accents":"strict"}}','published','L3-U05-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-07','es3-realidades-alternativas','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Si podría mudarme, investigaría el océano.","Si pudiera mudarme, investigaría el océano."]},{"prompt":"","input":"choice","options":["Si hubieran construido la ciudad, ya habríamos aprendido mucho más.","Si hubieran construido la ciudad, aprenderíamos ya mucho más."]},{"prompt":"","input":"choice","options":["Una decisión podría haber cambiado el presente.","Una decisión podría cambió el presente."]},{"prompt":"","input":"choice","options":["Si viviera allí, sería feliz.","Si viviría allí, sería feliz."]}]}','{"items":[{"display":"Si pudiera mudarme, investigaría el océano.","choice":1},{"display":"Si hubieran construido la ciudad, aprenderíamos ya mucho más.","choice":1},{"display":"Una decisión podría cambió el presente.","choice":1},{"display":"Si viviría allí, sería feliz.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U05-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-08','es3-realidades-alternativas','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**yo** · poder · después de «si» en una hipótesis","input":"text"},{"prompt":"**Nora** · investigar · si viviera bajo el mar","input":"text"},{"prompt":"**los científicos** · construir · si lo hubieran intentado","input":"text"},{"prompt":"**nosotros** · aprender · si la ciudad hubiera existido durante décadas","input":"text"}]}','{"items":[{"display":"pudiera","answers":["pudiera"]},{"display":"investigaría","answers":["investigaría"]},{"display":"habrían construido","answers":["habrían construido"]},{"display":"habríamos aprendido","answers":["habríamos aprendido"]}],"policy":{"accents":"strict"}}','published','L3-U05-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-09','es3-realidades-alternativas','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿qué sería?\n¿cuál elegirías y por qué?\n¿Qué significa para ti la historia alternativa?\n¿Por qué cambiarías eso?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U05-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-10','es3-realidades-alternativas','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**yo** · poder · después de «si» en una hipótesis","input":"text"},{"prompt":"**Nora** · investigar · si viviera bajo el mar","input":"text"},{"prompt":"**los científicos** · construir · si lo hubieran intentado","input":"text"},{"prompt":"**nosotros** · aprender · si la ciudad hubiera existido durante décadas","input":"text"},{"prompt":"**una decisión** · cambiar · en otra realidad","input":"text"},{"prompt":"**tú** · elegir · si tuvieras otra oportunidad","input":"text"},{"prompt":"**ellos** · descubrir · si hubieran continuado","input":"text"},{"prompt":"**el mundo** · ser · si la historia fuera distinta","input":"text"}]}','{"items":[{"display":"pudiera","answers":["pudiera"]},{"display":"investigaría","answers":["investigaría"]},{"display":"habrían construido","answers":["habrían construido"]},{"display":"habríamos aprendido","answers":["habríamos aprendido"]},{"display":"podría haber cambiado","answers":["podría haber cambiado"]},{"display":"elegirías","answers":["elegirías"]},{"display":"habrían descubierto","answers":["habrían descubierto"]},{"display":"sería","answers":["sería"]}],"policy":{"accents":"strict"}}','published','L3-U05-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-11','es3-realidades-alternativas','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Dónde imagina vivir Nora?","input":"sentence"},{"prompt":"¿Qué haría allí?","input":"sentence"},{"prompt":"¿Qué habría cambiado nuestro conocimiento?","input":"sentence"}],"text":"Nora imagina cómo sería vivir en una ciudad submarina. Si pudiera mudarse allí, investigaría el océano; si los científicos hubieran construido esa ciudad hace décadas, ya habríamos aprendido mucho más. Una sola decisión del pasado podría haber cambiado nuestro presente."}','{"items":[{"display":"En una ciudad submarina.","answers":["En una ciudad submarina."]},{"display":"Investigaría el océano.","answers":["Investigaría el océano."]},{"display":"La construcción de la ciudad hace décadas.","answers":["La construcción de la ciudad hace décadas."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U05-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-12','es3-realidades-alternativas','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Realidades alternativas\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Nora imagina cómo sería vivir en una ciudad submarina. Si pudiera mudarse allí, investigaría el océano; si los científicos hubieran construido esa ciudad hace décadas, ya habríamos aprendido mucho más. Una sola decisión del pasado podría haber cambiado nuestro presente."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U05-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-13','es3-realidades-alternativas','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Qué habría cambiado nuestro conocimiento?"},{"id":"B","text":"Pregunta: ¿Qué haría allí?"},{"id":"C","text":"Respuesta: La construcción de la ciudad hace décadas."},{"id":"D","text":"Pregunta: ¿Dónde imagina vivir Nora?"},{"id":"E","text":"Respuesta: En una ciudad submarina."},{"id":"F","text":"Respuesta: Investigaría el océano."}]}','{"order":["D","E","B","F","A","C"],"policy":{"accents":"strict"}}','published','L3-U05-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-14','es3-realidades-alternativas','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Nora imagina cómo sería vivir en una ciudad submarina."},{"id":"B","text":"Una sola decisión del pasado podría haber cambiado nuestro presente."},{"id":"C","text":"Si pudiera mudarse allí, investigaría el océano; si los científicos hubieran construido esa ciudad hace décadas, ya habríamos aprendido mucho más."}]}','{"order":["A","C","B"],"policy":{"accents":"strict"}}','published','L3-U05-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-15','es3-realidades-alternativas','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre realidades alternativas es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre realidades alternativas es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U05-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-16','es3-realidades-alternativas','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"לדמיין מחדש = ___","input":"text"},{"prompt":"עתיד = ___","input":"text"},{"prompt":"יקום-רב = ___","input":"text"},{"prompt":"סיבתיות = ___","input":"text"},{"prompt":"**el mundo** · ser · si la historia fuera distinta","input":"text"},{"prompt":"**ellos** · descubrir · si hubieran continuado","input":"text"},{"prompt":"**tú** · elegir · si tuvieras otra oportunidad","input":"text"},{"prompt":"**una decisión** · cambiar · en otra realidad","input":"text"},{"prompt":"**nosotros** · aprender · si la ciudad hubiera existido durante décadas","input":"text"},{"prompt":"**los científicos** · construir · si lo hubieran intentado","input":"text"}]}','{"items":[{"display":"Reinventar","answers":["Reinventar"],"policy":{"accents":"lenient"}},{"display":"Futuro","answers":["Futuro"],"policy":{"accents":"lenient"}},{"display":"Multiverso","answers":["Multiverso"],"policy":{"accents":"lenient"}},{"display":"Causalidad","answers":["Causalidad"],"policy":{"accents":"lenient"}},{"display":"sería","answers":["sería"]},{"display":"habrían descubierto","answers":["habrían descubierto"]},{"display":"elegirías","answers":["elegirías"]},{"display":"podría haber cambiado","answers":["podría haber cambiado"]},{"display":"habríamos aprendido","answers":["habríamos aprendido"]},{"display":"habrían construido","answers":["habrían construido"]}],"policy":{"accents":"strict"}}','published','L3-U05-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-17','es3-realidades-alternativas','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Nora imagina cómo sería vivir en una ciudad submarina. Si pudiera mudarse allí, investigaría el océano; si los científicos hubieran construido esa ciudad hace décadas, ya habríamos aprendido mucho más."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U05-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-18','es3-realidades-alternativas','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"___: Si los robots gobernaran…","input":"bank"},{"prompt":"Si hubiera tomado otra ___ en la escuela, habría…","input":"bank"},{"prompt":"Practicar vocabulario abstracto (___, distopía, cambio, sociedad, tecnología).","input":"bank"},{"prompt":"¿Qué significa para ti la ___ alternativa?","input":"bank"},{"prompt":"Desarrollar la creatividad y la capacidad de ___.","input":"bank"},{"prompt":"Cada grupo presenta su ___ al resto de la clase.","input":"bank"},{"prompt":"Segundo condicional → hipótesis sobre el ___ /futuro.","input":"bank"},{"prompt":"Fomentar la ___, el trabajo en grupo y la comparación de ideas.","input":"bank"},{"prompt":"___: Si no hubiera escuelas…","input":"bank"},{"prompt":"Si hubiera aceptado una ___, habría…","input":"bank"}],"wordbank":["Sociedad","Especulación","Oportunidad","Decisión","Presente","Utopía","Historia","Realidad alternativa","Creatividad","Tecnología"]}','{"items":[{"display":"Tecnología","answers":["Tecnología"]},{"display":"Decisión","answers":["Decisión"]},{"display":"Utopía","answers":["Utopía"]},{"display":"Historia","answers":["Historia"]},{"display":"Especulación","answers":["Especulación"]},{"display":"Realidad alternativa","answers":["Realidad alternativa"]},{"display":"Presente","answers":["Presente"]},{"display":"Creatividad","answers":["Creatividad"]},{"display":"Sociedad","answers":["Sociedad"]},{"display":"Oportunidad","answers":["Oportunidad"]}],"policy":{"accents":"strict"}}','published','L3-U05-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-19','es3-realidades-alternativas','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Si yo ___ elegir sin límites, cambiaría de vida.","input":"text","hint":"poder"},{"prompt":"Si viviera bajo el mar, Nora ___.","input":"text","hint":"investigar"},{"prompt":"Si lo hubieran intentado, los científicos ___.","input":"text","hint":"construir"},{"prompt":"Si la ciudad hubiera existido durante décadas, nosotros ___.","input":"text","hint":"aprender"},{"prompt":"Una decisión ___ en otra realidad.","input":"text","hint":"cambiar"},{"prompt":"Si tuvieras otra oportunidad, tú ___.","input":"text","hint":"elegir"},{"prompt":"Si hubieran continuado, ellos ___.","input":"text","hint":"descubrir"},{"prompt":"Si la historia fuera distinta, el mundo ___.","input":"text","hint":"ser"}]}','{"items":[{"display":"pudiera","answers":["pudiera"]},{"display":"investigaría","answers":["investigaría"]},{"display":"habrían construido","answers":["habrían construido"]},{"display":"habríamos aprendido","answers":["habríamos aprendido"]},{"display":"podría haber cambiado","answers":["podría haber cambiado"]},{"display":"elegirías","answers":["elegirías"]},{"display":"habrían descubierto","answers":["habrían descubierto"]},{"display":"sería","answers":["sería"]}],"policy":{"accents":"strict"}}','published','L3-U05-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-realidades-alternativas-20','es3-realidades-alternativas','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Cada cuánto cambiaban de trabajo?","input":"sentence"},{"prompt":"¿Qué deseaban algunos habitantes?","input":"sentence"},{"prompt":"¿Qué permitiría Leo?","input":"sentence"},{"prompt":"¿Qué echaría de menos Leo en la segunda sociedad?","input":"sentence"},{"prompt":"¿Qué tendría hoy si hubiera recibido una formación más flexible?","input":"sentence"}],"text":"En una realidad alternativa, Leo encontró una ciudad en la que nadie necesitaba elegir una sola profesión. Cada persona cambiaba de trabajo cada cuatro años y recibía formación gratuita. Al principio la idea le pareció perfecta, pero después comprendió que algunos habitantes deseaban profundizar en una sola actividad. Si pudiera rediseñar el sistema, permitiría que cada persona eligiera su propio ritmo.\n\nLeo también imaginó una segunda posibilidad: una sociedad en la que todas las decisiones importantes fueran tomadas por una inteligencia artificial. Si viviera allí, al principio disfrutaría de la seguridad y del orden, pero pronto echaría de menos la libertad de equivocarse. Si los habitantes hubieran cuestionado el sistema desde el comienzo, quizá no habrían creado una distopía tan eficiente. La divergencia entre ambas realidades le hizo pensar en su propio presente. Si hubiera recibido una formación más flexible cuando era joven, hoy tendría menos miedo a cambiar de profesión. Su escenario ideal no sería una utopía perfecta, sino un multiverso de posibilidades donde cada persona pudiera revisar sus elecciones.\n\nLa experiencia no le dio una respuesta definitiva, pero cambió su manera de pensar. Desde entonces, cuando imagina una realidad alternativa, se pregunta quién decide las reglas, quién obtiene los beneficios y qué consecuencias inesperadas podría tener cada elección."}','{"items":[{"display":"Cada cuatro años","answers":["Cada cuatro años"]},{"display":"Profundizar en una sola actividad","answers":["Profundizar en una sola actividad"]},{"display":"Que cada persona eligiera su propio ritmo","answers":["Que cada persona eligiera su propio ritmo"]},{"display":"La libertad de equivocarse","answers":["La libertad de equivocarse"]},{"display":"Menos miedo a cambiar de profesión","answers":["Menos miedo a cambiar de profesión"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U05-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa','es-3','es-3-stories','כתיבה יצירתית','Escritura creativa','לדבר ולכתוב על הנושא „כתיבה יצירתית“ בספרדית, תוך שימוש במבנים: Narración avanzada, pluscuamperfecto y conectores.','derived','[{"he":"דקדוק בשימוש","target":"Narración avanzada, pluscuamperfecto y conectores"},{"he":"אוצר מילים: כתיבה יצירתית","target":"Escritura creativa"}]','["Narración avanzada, pluscuamperfecto y conectores"]','{"rules":[],"examples":["Inés entró en la casa.","Había perdido el teléfono antes de entrar.","Mientras buscaba una salida, escuchaba pasos.","Cuando llegó la policía, la casa ya había desaparecido."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"A fin de que…","he":"כדי ש"},{"term":"A pesar de que…","he":"למרות ש"},{"term":"Alibi (coartada)","he":"טענת חפות / אליבי"},{"term":"Clímax","he":"שיא"},{"term":"Coherencia","he":"עקביות"},{"term":"Cohesión","he":"לכידות / קוהרנטיות"},{"term":"Condicional","he":"משפט תנאי / תנאי / מותנה"},{"term":"Conector","he":"מִ ּלַת קִ ּׁשּור"},{"term":"Contradicción","he":"סתירה"},{"term":"Contraste","he":"ניגוד"},{"term":"Descripción","he":"תיאור"},{"term":"Desenlace","he":"סיום עלילה"},{"term":"Detalle","he":"פרט"},{"term":"Detective","he":"בלש"},{"term":"Escenario","he":"תרחיש / זירה / סצנה"},{"term":"Evidencia","he":"הוכחה / ראיה"},{"term":"Expresión","he":"ביטוי"},{"term":"Formular","he":"לנסח"},{"term":"Hipótesis","he":"השערה / השערה / הנחה"},{"term":"Interpretación","he":"פרשנות"},{"term":"Interpretar","he":"לפרש / לשחק / לגלם"},{"term":"Misterio","he":"תעלומה"},{"term":"Narración","he":"נרטיב / סיפור / סיפור / נרטיב"},{"term":"Narrador","he":"מספר"},{"term":"Periodista","he":"עיתונאי"},{"term":"Perspectiva","he":"נקודת מבט / נקודת מבטs"},{"term":"Pluscuamperfecto, )","he":"פלוסקוומפרפקטו (עבר לפני עבר"},{"term":"Punto de vista","he":"נקודת השקפה"},{"term":"Redactar","he":"לנסח בכתב"},{"term":"Robo","he":"גניבה"},{"term":"Secuencia","he":"רצף"},{"term":"Sin embargo","he":"למרות זאת / עם זאת"},{"term":"Sospechoso","he":"חשוד"},{"term":"Suposición","he":"הנחה"},{"term":"Testigo","he":"עד"},{"term":"Versión","he":"גרסה"},{"term":"Versión oficial","he":"גרסה רשמית"},{"term":"Voz narrativa","he":"קול סיפורי"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/921689816/creative-writing-extreme-spanish-actualizado-flash-cards/"}]','published','workbook L3 unit 06',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-01','es3-escritura-creativa','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"טענת חפות / אליבי ___","input":"text"},{"prompt":"סתירה ___","input":"text"},{"prompt":"ניגוד ___","input":"text"},{"prompt":"הוכחה / ראיה ___","input":"text"},{"prompt":"סיפור / נרטיב ___","input":"text"},{"prompt":"נקודת השקפה ___","input":"text"}]}','{"items":[{"display":"Alibi (coartada)","answers":["Alibi (coartada)","Alibi"]},{"display":"Contradicción","answers":["Contradicción"]},{"display":"Contraste","answers":["Contraste"]},{"display":"Evidencia","answers":["Evidencia"]},{"display":"Narración","answers":["Narración"]},{"display":"Punto de vista","answers":["Punto de vista"]}],"policy":{"accents":"lenient"}}','published','L3-U06-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-02','es3-escritura-creativa','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Alibi (coartada)","Contradicción","Contraste","Evidencia","Narración","Punto de vista","Formular","Sospechoso"],"right":[{"id":"A","text":"סיפור / נרטיב"},{"id":"B","text":"הוכחה / ראיה"},{"id":"C","text":"סתירה"},{"id":"D","text":"טענת חפות / אליבי"},{"id":"E","text":"ניגוד"},{"id":"F","text":"חשוד"},{"id":"G","text":"לנסח"},{"id":"H","text":"נקודת השקפה"}]}','{"pairs":["D","C","E","B","A","H","G","F"],"policy":{"accents":"lenient"}}','published','L3-U06-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-03','es3-escritura-creativa','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"טענת חפות / אליבי","input":"choice","options":["Alibi (coartada)","A pesar de que…","Clímax"]},{"prompt":"סתירה","input":"choice","options":["Narrador","Contradicción","Punto de vista"]},{"prompt":"ניגוד","input":"choice","options":["Contraste","Contradicción","Secuencia"]},{"prompt":"הוכחה / ראיה","input":"choice","options":["Evidencia","Misterio","Versión"]},{"prompt":"סיפור / נרטיב","input":"choice","options":["Narración","Evidencia","Detalle"]},{"prompt":"נקודת השקפה","input":"choice","options":["Punto de vista","Versión oficial","Condicional"]}]}','{"items":[{"display":"Alibi (coartada)","choice":0},{"display":"Contradicción","choice":1},{"display":"Contraste","choice":0},{"display":"Evidencia","choice":0},{"display":"Narración","choice":0},{"display":"Punto de vista","choice":0}],"policy":{"accents":"lenient"}}','published','L3-U06-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-04','es3-escritura-creativa','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"למרות ש = ___","input":"bank"},{"prompt":"חשוד = ___","input":"bank"},{"prompt":"לנסח = ___","input":"bank"},{"prompt":"נקודת השקפה = ___","input":"bank"},{"prompt":"סיום עלילה = ___","input":"bank"}],"wordbank":["A pesar de que…","Desenlace","detalle","Formular","Punto de vista","Sospechoso"],"text":"Inés entró en una casa abandonada después de que había perdido su teléfono en el bosque. Mientras buscaba una salida, escuchaba pasos y anotaba cada {{1}} en su diario. Cuando llegó la policía, la casa había desaparecido y solo quedaba una carta sobre el suelo."}','{"items":[{"display":"detalle","answers":["detalle"]},{"display":"A pesar de que…","answers":["A pesar de que…"]},{"display":"Sospechoso","answers":["Sospechoso"]},{"display":"Formular","answers":["Formular"]},{"display":"Punto de vista","answers":["Punto de vista"]},{"display":"Desenlace","answers":["Desenlace"]}],"policy":{"accents":"strict"}}','published','L3-U06-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-05','es3-escritura-creativa','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["Qué","escritura","para","ti","es","creativa","la"]},{"prompt":"","input":"tokens","tokens":["te","Sobre","escribir","gusta","qué","por","qué"]},{"prompt":"","input":"tokens","tokens":["escrito","del","orgulloso","Has","sientas","fue","algo","te","que","Qué"]},{"prompt":"","input":"tokens","tokens":["en","otro","lo","más","difícil","es","escribir","idioma","ti","para","al","Qué"]}]}','{"items":[{"display":"¿Qué es para ti la escritura creativa?","answers":["¿Qué es para ti la escritura creativa?"]},{"display":"¿Sobre qué te gusta escribir? ¿por qué?","answers":["¿Sobre qué te gusta escribir? ¿por qué?"]},{"display":"¿Has escrito algo del que te sientas orgulloso? ¿Qué fue?","answers":["¿Has escrito algo del que te sientas orgulloso? ¿Qué fue?"]},{"display":"¿Qué es lo más difícil para ti al escribir en otro idioma?","answers":["¿Qué es lo más difícil para ti al escribir en otro idioma?"]}],"policy":{"accents":"strict"}}','published','L3-U06-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-06','es3-escritura-creativa','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Inés entraba en la casa una vez.","input":"sentence"},{"prompt":"Había perdido el teléfono después de entrar.","input":"sentence"},{"prompt":"Mientras buscó una salida, escuchaba pasos.","input":"sentence"},{"prompt":"Cuando llegó la policía, la casa desapareció ya.","input":"sentence"}]}','{"items":[{"display":"Inés entró en la casa.","answers":["Inés entró en la casa."]},{"display":"Había perdido el teléfono antes de entrar.","answers":["Había perdido el teléfono antes de entrar."]},{"display":"Mientras buscaba una salida, escuchaba pasos.","answers":["Mientras buscaba una salida, escuchaba pasos."]},{"display":"Cuando llegó la policía, la casa ya había desaparecido.","answers":["Cuando llegó la policía, la casa ya había desaparecido."]}],"policy":{"accents":"strict"}}','published','L3-U06-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-07','es3-escritura-creativa','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Inés entraba en la casa una vez.","Inés entró en la casa."]},{"prompt":"","input":"choice","options":["Había perdido el teléfono después de entrar.","Había perdido el teléfono antes de entrar."]},{"prompt":"","input":"choice","options":["Mientras buscaba una salida, escuchaba pasos.","Mientras buscó una salida, escuchaba pasos."]},{"prompt":"","input":"choice","options":["Cuando llegó la policía, la casa ya había desaparecido.","Cuando llegó la policía, la casa desapareció ya."]}]}','{"items":[{"display":"Inés entró en la casa.","choice":1},{"display":"Había perdido el teléfono antes de entrar.","choice":1},{"display":"Mientras buscó una salida, escuchaba pasos.","choice":1},{"display":"Cuando llegó la policía, la casa desapareció ya.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U06-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-08','es3-escritura-creativa','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**Inés** · perder · antes de entrar","input":"text"},{"prompt":"**ella** · entrar · después","input":"text"},{"prompt":"**Inés** · escuchar · mientras buscaba","input":"text"},{"prompt":"**la casa** · desaparecer · antes de llegar la policía","input":"text"}]}','{"items":[{"display":"había perdido","answers":["había perdido"]},{"display":"entró","answers":["entró"]},{"display":"escuchaba","answers":["escuchaba"]},{"display":"había desaparecido","answers":["había desaparecido"]}],"policy":{"accents":"strict"}}','published','L3-U06-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-09','es3-escritura-creativa','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Qué es para ti la escritura creativa?\n¿Sobre qué te gusta escribir? ¿por qué?\n¿Has escrito algo del que te sientas orgulloso? ¿Qué fue?\n¿Qué es lo más difícil para ti al escribir en otro idioma?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U06-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-10','es3-escritura-creativa','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**Inés** · perder · antes de entrar","input":"text"},{"prompt":"**ella** · entrar · después","input":"text"},{"prompt":"**Inés** · escuchar · mientras buscaba","input":"text"},{"prompt":"**la casa** · desaparecer · antes de llegar la policía","input":"text"},{"prompt":"**yo** · saber · después de «si» en una hipótesis","input":"text"},{"prompt":"**yo** · llamar · si hubiera tenido teléfono","input":"text"},{"prompt":"**ellos** · encontrar · ayer","input":"text"},{"prompt":"**la tormenta** · rugir · durante toda la noche","input":"text"}]}','{"items":[{"display":"había perdido","answers":["había perdido"]},{"display":"entró","answers":["entró"]},{"display":"escuchaba","answers":["escuchaba"]},{"display":"había desaparecido","answers":["había desaparecido"]},{"display":"supiera","answers":["supiera"]},{"display":"habría llamado","answers":["habría llamado"]},{"display":"encontraron","answers":["encontraron"]},{"display":"rugía","answers":["rugía"]}],"policy":{"accents":"strict"}}','published','L3-U06-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-11','es3-escritura-creativa','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Por qué entró Inés en la casa?","input":"sentence"},{"prompt":"¿Qué hacía mientras buscaba una salida?","input":"sentence"},{"prompt":"¿Qué quedaba cuando llegó la policía?","input":"sentence"}],"text":"Inés entró en una casa abandonada después de que había perdido su teléfono en el bosque. Mientras buscaba una salida, escuchaba pasos y anotaba cada detalle en su diario. Cuando llegó la policía, la casa había desaparecido y solo quedaba una carta sobre el suelo."}','{"items":[{"display":"Porque había perdido su teléfono.","answers":["Porque había perdido su teléfono."]},{"display":"Escuchaba pasos y anotaba detalles.","answers":["Escuchaba pasos y anotaba detalles."]},{"display":"Una carta.","answers":["Una carta."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U06-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-12','es3-escritura-creativa','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Escritura creativa\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Inés entró en una casa abandonada después de que había perdido su teléfono en el bosque. Mientras buscaba una salida, escuchaba pasos y anotaba cada detalle en su diario. Cuando llegó la policía, la casa había desaparecido y solo quedaba una carta sobre el suelo."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U06-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-13','es3-escritura-creativa','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Por qué entró Inés en la casa?"},{"id":"B","text":"Respuesta: Escuchaba pasos y anotaba detalles."},{"id":"C","text":"Pregunta: ¿Qué hacía mientras buscaba una salida?"},{"id":"D","text":"Pregunta: ¿Qué quedaba cuando llegó la policía?"},{"id":"E","text":"Respuesta: Porque había perdido su teléfono."},{"id":"F","text":"Respuesta: Una carta."}]}','{"order":["A","E","C","B","D","F"],"policy":{"accents":"strict"}}','published','L3-U06-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-14','es3-escritura-creativa','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Mientras buscaba una salida, escuchaba pasos y anotaba cada detalle en su diario."},{"id":"B","text":"Cuando llegó la policía, la casa había desaparecido y solo quedaba una carta sobre el suelo."},{"id":"C","text":"Inés entró en una casa abandonada después de que había perdido su teléfono en el bosque."}]}','{"order":["C","A","B"],"policy":{"accents":"strict"}}','published','L3-U06-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-15','es3-escritura-creativa','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre escritura creativa es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre escritura creativa es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U06-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-16','es3-escritura-creativa','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"ניגוד = ___","input":"text"},{"prompt":"הוכחה / ראיה = ___","input":"text"},{"prompt":"סיפור / נרטיב = ___","input":"text"},{"prompt":"נקודת השקפה = ___","input":"text"},{"prompt":"**la tormenta** · rugir · durante toda la noche","input":"text"},{"prompt":"**ellos** · encontrar · ayer","input":"text"},{"prompt":"**yo** · llamar · si hubiera tenido teléfono","input":"text"},{"prompt":"**yo** · saber · después de «si» en una hipótesis","input":"text"},{"prompt":"**la casa** · desaparecer · antes de llegar la policía","input":"text"},{"prompt":"**Inés** · escuchar · mientras buscaba","input":"text"}]}','{"items":[{"display":"Contraste","answers":["Contraste"],"policy":{"accents":"lenient"}},{"display":"Evidencia","answers":["Evidencia"],"policy":{"accents":"lenient"}},{"display":"Narración","answers":["Narración"],"policy":{"accents":"lenient"}},{"display":"Punto de vista","answers":["Punto de vista"],"policy":{"accents":"lenient"}},{"display":"rugía","answers":["rugía"]},{"display":"encontraron","answers":["encontraron"]},{"display":"habría llamado","answers":["habría llamado"]},{"display":"supiera","answers":["supiera"]},{"display":"había desaparecido","answers":["había desaparecido"]},{"display":"escuchaba","answers":["escuchaba"]}],"policy":{"accents":"strict"}}','published','L3-U06-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-17','es3-escritura-creativa','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Inés entró en una casa abandonada después de que había perdido su teléfono en el bosque. Mientras buscaba una salida, escuchaba pasos y anotaba cada detalle en su diario."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U06-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-18','es3-escritura-creativa','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"¿Qué aporta cada ___ a la historia?","input":"bank"},{"prompt":"Variedad de puntos de vista: protagonista, ___, autoridad, objeto.","input":"bank"},{"prompt":"Condición/___: en caso de que, siempre que, a condición de que.","input":"bank"},{"prompt":"Contraste: ___, a pesar de que, no obstante.","input":"bank"},{"prompt":"Detectives: formulan hipótesis, escriben 2 frases con ___.","input":"bank"},{"prompt":"___: en primer lugar, después, mientras tanto, finalmente.","input":"bank"},{"prompt":"Explorar cómo el punto de vista narrativo cambia la ___ de una historia.","input":"bank"},{"prompt":"Practicar la ___ narrativa escribiendo con un final impuesto.","input":"bank"},{"prompt":"¿Qué ___ es más convincente?","input":"bank"},{"prompt":"¿La historia mantuvo ___ o se volvió absurda?","input":"bank"}],"wordbank":["Hipótesis","Secuencia","Coherencia","Cohesión","Versión","Interpretación","Testigo","Condicional","Perspectiva","Sin embargo"]}','{"items":[{"display":"Perspectiva","answers":["Perspectiva"]},{"display":"Testigo","answers":["Testigo"]},{"display":"Hipótesis","answers":["Hipótesis"]},{"display":"Sin embargo","answers":["Sin embargo"]},{"display":"Condicional","answers":["Condicional"]},{"display":"Secuencia","answers":["Secuencia"]},{"display":"Interpretación","answers":["Interpretación"]},{"display":"Cohesión","answers":["Cohesión"]},{"display":"Versión","answers":["Versión"]},{"display":"Coherencia","answers":["Coherencia"]}],"policy":{"accents":"strict"}}','published','L3-U06-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-19','es3-escritura-creativa','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Antes de entrar, Inés ___.","input":"text","hint":"perder"},{"prompt":"Ella ___ después.","input":"text","hint":"entrar"},{"prompt":"Inés ___ mientras buscaba.","input":"text","hint":"escuchar"},{"prompt":"Antes de llegar la policía, la casa ___.","input":"text","hint":"desaparecer"},{"prompt":"Si yo ___ la verdad, tomaría otra decisión.","input":"text","hint":"saber"},{"prompt":"Si hubiera tenido teléfono, yo ___.","input":"text","hint":"llamar"},{"prompt":"Ayer, ellos ___.","input":"text","hint":"encontrar"},{"prompt":"La tormenta ___ durante toda la noche.","input":"text","hint":"rugir"}]}','{"items":[{"display":"había perdido","answers":["había perdido"]},{"display":"entró","answers":["entró"]},{"display":"escuchaba","answers":["escuchaba"]},{"display":"había desaparecido","answers":["había desaparecido"]},{"display":"supiera","answers":["supiera"]},{"display":"habría llamado","answers":["habría llamado"]},{"display":"encontraron","answers":["encontraron"]},{"display":"rugía","answers":["rugía"]}],"policy":{"accents":"strict"}}','published','L3-U06-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-escritura-creativa-20','es3-escritura-creativa','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Qué perdió Tomás?","input":"sentence"},{"prompt":"¿Cómo reconstruyó la escena?","input":"sentence"},{"prompt":"¿Qué destacó el jurado?","input":"sentence"},{"prompt":"¿Quién narraba el cuento?","input":"sentence"},{"prompt":"¿Qué elemento mantenía la tensión?","input":"sentence"}],"text":"Tomás perdió el cuaderno donde había escrito el final de un cuento para un concurso. Como no recordaba las frases exactas, reconstruyó la escena desde otro punto de vista. La nueva versión era menos perfecta, pero también más personal. El jurado premió el relato y destacó precisamente la voz auténtica que había surgido del accidente.\n\nEl cuento estaba narrado por un testigo que parecía fiable, aunque al final se descubría que también era sospechoso del robo. Tomás había preparado una secuencia muy clara, pero el accidente lo obligó a cambiar la perspectiva. Primero reconstruyó el escenario; después comparó la versión del detective con la del periodista; sin embargo, ninguna coincidía por completo. Cuando ya había escrito la última escena, añadió una pista que conectaba todos los detalles anteriores. Por eso, el misterio funcionó mejor que en el borrador original. El jurado explicó que el contraste entre las voces mantenía la tensión y que el narrador había ocultado información sin engañar directamente al lector.\n\nDespués del concurso, Tomás transformó el relato en un pódcast. Cada personaje contaba la misma noche desde su perspectiva y el público tenía que decidir qué versión era más creíble. Así, la historia continuó creciendo después de haber sido premiada."}','{"items":[{"display":"El cuaderno","answers":["El cuaderno"]},{"display":"Desde otro punto de vista","answers":["Desde otro punto de vista"]},{"display":"La voz auténtica","answers":["La voz auténtica"]},{"display":"Un testigo que también era sospechoso","answers":["Un testigo que también era sospechoso"]},{"display":"El contraste entre las voces","answers":["El contraste entre las voces"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U06-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion','es-3','es-3-work','חינוך','Educación','לדבר ולכתוב על הנושא „חינוך“ בספרדית, תוך שימוש במבנים: Pretérito perfecto, futuro, hipótesis y propuestas.','derived','[{"he":"דקדוק בשימוש","target":"Pretérito perfecto, futuro, hipótesis y propuestas"},{"he":"אוצר מילים: חינוך","target":"Educación"}]','["Pretérito perfecto, futuro, hipótesis y propuestas"]','{"rules":[],"examples":["Los estudiantes han participado en el proyecto.","Las clases serán organizadas de otra manera.","Si los gobiernos invirtieran más, el cambio sería más justo.","La plataforma que usan adapta las tareas."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Aprender","he":"ללמוד"},{"term":"aprendizaje autónomo","he":"למידה עצמאית"},{"term":"aprobar - )","he":"לעבור (מבחן"},{"term":"cambio social","he":"שינוי חברתי"},{"term":"carrera universitaria","he":"לימודים אקדמיים"},{"term":"centro educativo","he":"מוסד חינוכי"},{"term":"compañero de clase","he":"חבר לכיתה"},{"term":"curso online","he":"קורס מקוון"},{"term":"desarrollo personal","he":"התפתחות אישית"},{"term":"educación inclusiva","he":"חינוך משלב"},{"term":"educación privada","he":"חינוך פרטי"},{"term":"educación pública","he":"חינוך ציבורי"},{"term":"enseñar","he":"ללמד"},{"term":"Estudiante","he":"תלמיד / סטודנט / תלמיד"},{"term":"estudiar","he":"ללמוד"},{"term":"estudios superiores","he":"השכלה גבוהה"},{"term":"evaluación","he":"הערכה"},{"term":"examen","he":"מבחן"},{"term":"formación profesional","he":"הכשרה מקצועית"},{"term":"futuro de la educación","he":"עתיד החינוך"},{"term":"Habilidades","he":"מיומנויות"},{"term":"Logro","he":"הישג"},{"term":"mejorar","he":"להשתפר / לשפר"},{"term":"Motivación","he":"מוטיבציה"},{"term":"nota","he":"ציון"},{"term":"orientador","he":"יועץ חינוכי"},{"term":"practicar","he":"לתרגל"},{"term":"presentación","he":"פרזנטציה / הצגה"},{"term":"Profesor","he":"מורה"},{"term":"progreso","he":"התקדמות"},{"term":"sistema educativo","he":"מערכת החינוך"},{"term":"suspender","he":"להיכשל"},{"term":"tarea","he":"שיעורי בית"},{"term":"tecnología educativa","he":"טכנולוגיה חינוכית"},{"term":"trabajo en grupo","he":"עבודה בקבוצה"},{"term":"tutor","he":"חונך"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1120948790/educacion-flash-cards/?new"}]','published','workbook L3 unit 07',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-01','es3-educacion','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"חינוך פרטי ___","input":"text"},{"prompt":"שיעורי בית ___","input":"text"},{"prompt":"ללמוד ___","input":"text"},{"prompt":"השכלה גבוהה ___","input":"text"},{"prompt":"ציון ___","input":"text"},{"prompt":"לתרגל ___","input":"text"}]}','{"items":[{"display":"educación privada","answers":["educación privada"]},{"display":"tarea","answers":["tarea"]},{"display":"aprender","answers":["aprender"]},{"display":"estudios superiores","answers":["estudios superiores"]},{"display":"nota","answers":["nota"]},{"display":"practicar","answers":["practicar"]}],"policy":{"accents":"lenient"}}','published','L3-U07-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-02','es3-educacion','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["educación privada","tarea","aprender","estudios superiores","nota","practicar","curso online","profesor"],"right":[{"id":"A","text":"ללמוד"},{"id":"B","text":"שיעורי בית"},{"id":"C","text":"לתרגל"},{"id":"D","text":"ציון"},{"id":"E","text":"מורה"},{"id":"F","text":"חינוך פרטי"},{"id":"G","text":"קורס מקוון"},{"id":"H","text":"השכלה גבוהה"}]}','{"pairs":["F","B","A","H","D","C","G","E"],"policy":{"accents":"lenient"}}','published','L3-U07-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-03','es3-educacion','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"חינוך פרטי","input":"choice","options":["educación inclusiva","progreso","educación privada"]},{"prompt":"שיעורי בית","input":"choice","options":["nota","trabajo en grupo","tarea"]},{"prompt":"ללמוד","input":"choice","options":["aprender","nota","estudios superiores"]},{"prompt":"השכלה גבוהה","input":"choice","options":["suspender","practicar","estudios superiores"]},{"prompt":"ציון","input":"choice","options":["examen","nota","futuro de la educación"]},{"prompt":"לתרגל","input":"choice","options":["practicar","motivación","educación inclusiva"]}]}','{"items":[{"display":"educación privada","choice":2},{"display":"tarea","choice":2},{"display":"aprender","choice":0},{"display":"estudios superiores","choice":2},{"display":"nota","choice":1},{"display":"practicar","choice":0}],"policy":{"accents":"lenient"}}','published','L3-U07-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-04','es3-educacion','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"השכלה גבוהה = ___","input":"bank"},{"prompt":"עבודה בקבוצה = ___","input":"bank"},{"prompt":"הישג = ___","input":"bank"},{"prompt":"שינוי חברתי = ___","input":"bank"},{"prompt":"מערכת החינוך = ___","input":"bank"},{"prompt":"חינוך ציבורי = ___","input":"bank"}],"wordbank":["sistema educativo","educación pública","cambio social","estudios superiores","trabajo en grupo","logro"],"text":"Los estudiantes han participado en un proyecto para diseñar la escuela del futuro. La plataforma que utilizan adapta las tareas a cada persona. En 2035 muchas clases serán organizadas de otra manera y, si los gobiernos invirtieran más en formación, el cambio sería más justo."}','{"items":[{"display":"estudios superiores","answers":["estudios superiores"]},{"display":"trabajo en grupo","answers":["trabajo en grupo"]},{"display":"logro","answers":["logro"]},{"display":"cambio social","answers":["cambio social"]},{"display":"sistema educativo","answers":["sistema educativo"]},{"display":"educación pública","answers":["educación pública"]}],"policy":{"accents":"strict"}}','published','L3-U07-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-05','es3-educacion','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["tu","haya","aprendizaje","alguna","Has","experiencia","que","te","marcado","de","vida","tenido","en"]},{"prompt":"","input":"tokens","tokens":["Cuándo","fue","qué","Por","ocurrió","importante"]},{"prompt":"","input":"tokens","tokens":["materia","te","mucho","estudiado","costado","Has","que","alguna","haya"]},{"prompt":"","input":"tokens","tokens":["Qué","mejorar","exactamente","hiciste","para"]}]}','{"items":[{"display":"¿Has tenido alguna experiencia de aprendizaje que te haya marcado en tu vida?","answers":["¿Has tenido alguna experiencia de aprendizaje que te haya marcado en tu vida?"]},{"display":"¿Cuándo ocurrió? ¿Por qué fue importante?","answers":["¿Cuándo ocurrió? ¿Por qué fue importante?"]},{"display":"¿Has estudiado alguna materia que te haya costado mucho?","answers":["¿Has estudiado alguna materia que te haya costado mucho?"]},{"display":"¿Qué hiciste exactamente para mejorar?","answers":["¿Qué hiciste exactamente para mejorar?"]}],"policy":{"accents":"strict"}}','published','L3-U07-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-06','es3-educacion','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Los estudiantes han participando en el proyecto.","input":"sentence"},{"prompt":"Las clases serán organizar de otra manera.","input":"sentence"},{"prompt":"Si los gobiernos invertirían más, el cambio sería justo.","input":"sentence"},{"prompt":"La plataforma que usan adaptará ayer las tareas.","input":"sentence"}]}','{"items":[{"display":"Los estudiantes han participado en el proyecto.","answers":["Los estudiantes han participado en el proyecto."]},{"display":"Las clases serán organizadas de otra manera.","answers":["Las clases serán organizadas de otra manera."]},{"display":"Si los gobiernos invirtieran más, el cambio sería más justo.","answers":["Si los gobiernos invirtieran más, el cambio sería más justo."]},{"display":"La plataforma que usan adapta las tareas.","answers":["La plataforma que usan adapta las tareas."]}],"policy":{"accents":"strict"}}','published','L3-U07-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-07','es3-educacion','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Los estudiantes han participando en el proyecto.","Los estudiantes han participado en el proyecto."]},{"prompt":"","input":"choice","options":["Las clases serán organizadas de otra manera.","Las clases serán organizar de otra manera."]},{"prompt":"","input":"choice","options":["Si los gobiernos invirtieran más, el cambio sería más justo.","Si los gobiernos invertirían más, el cambio sería justo."]},{"prompt":"","input":"choice","options":["La plataforma que usan adapta las tareas.","La plataforma que usan adaptará ayer las tareas."]}]}','{"items":[{"display":"Los estudiantes han participado en el proyecto.","choice":1},{"display":"Las clases serán organizar de otra manera.","choice":1},{"display":"Si los gobiernos invertirían más, el cambio sería justo.","choice":1},{"display":"La plataforma que usan adaptará ayer las tareas.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U07-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-08','es3-educacion','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**los estudiantes** · participar · este año","input":"text"},{"prompt":"**las clases** · organizar · en 2035","input":"text"},{"prompt":"**los gobiernos** · invertir · después de «si» en una hipótesis","input":"text"},{"prompt":"**el cambio** · ser · con más inversión","input":"text"}]}','{"items":[{"display":"han participado","answers":["han participado"]},{"display":"serán organizadas","answers":["serán organizadas"]},{"display":"invirtieran","answers":["invirtieran"]},{"display":"sería","answers":["sería"]}],"policy":{"accents":"strict"}}','published','L3-U07-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-09','es3-educacion','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Has tenido alguna experiencia de aprendizaje que te haya marcado en tu vida?\n¿Cuándo ocurrió? ¿Por qué fue importante?\n¿Has estudiado alguna materia que te haya costado mucho?\n¿Qué hiciste exactamente para mejorar?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U07-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-10','es3-educacion','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**los estudiantes** · participar · este año","input":"text"},{"prompt":"**las clases** · organizar · en 2035","input":"text"},{"prompt":"**los gobiernos** · invertir · después de «si» en una hipótesis","input":"text"},{"prompt":"**el cambio** · ser · con más inversión","input":"text"},{"prompt":"**la plataforma** · adaptar · actualmente","input":"text"},{"prompt":"**nosotros** · aprender · hasta hoy","input":"text"},{"prompt":"**la escuela** · transformar · el próximo año","input":"text"},{"prompt":"**tú** · proponer · si fueras ministro","input":"text"}]}','{"items":[{"display":"han participado","answers":["han participado"]},{"display":"serán organizadas","answers":["serán organizadas"]},{"display":"invirtieran","answers":["invirtieran"]},{"display":"sería","answers":["sería"]},{"display":"adapta","answers":["adapta"]},{"display":"hemos aprendido","answers":["hemos aprendido"]},{"display":"se transformará","answers":["se transformará"]},{"display":"propondrías","answers":["propondrías"]}],"policy":{"accents":"strict"}}','published','L3-U07-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-11','es3-educacion','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿En qué proyecto han participado?","input":"sentence"},{"prompt":"¿Qué hace la plataforma?","input":"sentence"},{"prompt":"¿Qué haría el cambio más justo?","input":"sentence"}],"text":"Los estudiantes han participado en un proyecto para diseñar la escuela del futuro. La plataforma que utilizan adapta las tareas a cada persona. En 2035 muchas clases serán organizadas de otra manera y, si los gobiernos invirtieran más en formación, el cambio sería más justo."}','{"items":[{"display":"En un proyecto para diseñar la escuela del futuro.","answers":["En un proyecto para diseñar la escuela del futuro."]},{"display":"Adapta las tareas a cada persona.","answers":["Adapta las tareas a cada persona."]},{"display":"Más inversión en formación.","answers":["Más inversión en formación."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U07-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-12','es3-educacion','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Educación\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Los estudiantes han participado en un proyecto para diseñar la escuela del futuro. La plataforma que utilizan adapta las tareas a cada persona. En 2035 muchas clases serán organizadas de otra manera y, si los gobiernos invirtieran más en formación, el cambio sería más justo."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U07-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-13','es3-educacion','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Qué haría el cambio más justo?"},{"id":"B","text":"Respuesta: Adapta las tareas a cada persona."},{"id":"C","text":"Respuesta: En un proyecto para diseñar la escuela del futuro."},{"id":"D","text":"Pregunta: ¿Qué hace la plataforma?"},{"id":"E","text":"Pregunta: ¿En qué proyecto han participado?"},{"id":"F","text":"Respuesta: Más inversión en formación."}]}','{"order":["E","C","D","B","A","F"],"policy":{"accents":"strict"}}','published','L3-U07-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-14','es3-educacion','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"En 2035 muchas clases serán organizadas de otra manera y, si los gobiernos invirtieran más en formación, el cambio sería más justo."},{"id":"B","text":"Los estudiantes han participado en un proyecto para diseñar la escuela del futuro."},{"id":"C","text":"La plataforma que utilizan adapta las tareas a cada persona."}]}','{"order":["B","C","A"],"policy":{"accents":"strict"}}','published','L3-U07-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-15','es3-educacion','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre educación es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre educación es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U07-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-16','es3-educacion','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"ללמוד = ___","input":"text"},{"prompt":"השכלה גבוהה = ___","input":"text"},{"prompt":"ציון = ___","input":"text"},{"prompt":"לתרגל = ___","input":"text"},{"prompt":"**tú** · proponer · si fueras ministro","input":"text"},{"prompt":"**la escuela** · transformar · el próximo año","input":"text"},{"prompt":"**nosotros** · aprender · hasta hoy","input":"text"},{"prompt":"**la plataforma** · adaptar · actualmente","input":"text"},{"prompt":"**el cambio** · ser · con más inversión","input":"text"},{"prompt":"**los gobiernos** · invertir · después de «si» en una hipótesis","input":"text"}]}','{"items":[{"display":"aprender","answers":["aprender"],"policy":{"accents":"lenient"}},{"display":"estudios superiores","answers":["estudios superiores"],"policy":{"accents":"lenient"}},{"display":"nota","answers":["nota"],"policy":{"accents":"lenient"}},{"display":"practicar","answers":["practicar"],"policy":{"accents":"lenient"}},{"display":"propondrías","answers":["propondrías"]},{"display":"se transformará","answers":["se transformará"]},{"display":"hemos aprendido","answers":["hemos aprendido"]},{"display":"adapta","answers":["adapta"]},{"display":"sería","answers":["sería"]},{"display":"invirtieran","answers":["invirtieran"]}],"policy":{"accents":"strict"}}','published','L3-U07-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-17','es3-educacion','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Los estudiantes han participado en un proyecto para diseñar la escuela del futuro. La plataforma que utilizan adapta las tareas a cada persona."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U07-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-18','es3-educacion','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"El próximo semestre voy a tomar un curso de ___.","input":"bank"},{"prompt":"¿Qué asignatura crees que va a desaparecer del ___ en el futuro?","input":"bank"},{"prompt":"¿Qué hiciste exactamente para ___?","input":"bank"},{"prompt":"¿Qué vas a ___ el próximo año o qué te gustaría estudiar?","input":"bank"},{"prompt":"La voy a ___ con actividades prácticas, juegos de rol y conversaciones reales.","input":"bank"},{"prompt":"Cada ___ presenta una de sus tres materias, la que considere más importante.","input":"bank"},{"prompt":"טכנולוגיה חינוכית = ___","input":"bank"},{"prompt":"חבר לכיתה = ___","input":"bank"},{"prompt":"למידה עצמאית = ___","input":"bank"},{"prompt":"הישג = ___","input":"bank"}],"wordbank":["formación profesional","estudiante","compañero de clase","mejorar","tecnología educativa","aprendizaje autónomo","estudiar","enseñar","logro","sistema educativo"]}','{"items":[{"display":"formación profesional","answers":["formación profesional"]},{"display":"sistema educativo","answers":["sistema educativo"]},{"display":"mejorar","answers":["mejorar"]},{"display":"estudiar","answers":["estudiar"]},{"display":"enseñar","answers":["enseñar"]},{"display":"estudiante","answers":["estudiante"]},{"display":"tecnología educativa","answers":["tecnología educativa"]},{"display":"compañero de clase","answers":["compañero de clase"]},{"display":"aprendizaje autónomo","answers":["aprendizaje autónomo"]},{"display":"logro","answers":["logro"]}],"policy":{"accents":"strict"}}','published','L3-U07-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-19','es3-educacion','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Este año, los estudiantes ___.","input":"text","hint":"participar"},{"prompt":"Las clases ___ en 2035.","input":"text","hint":"organizar"},{"prompt":"Si los gobiernos ___ más, la educación mejoraría.","input":"text","hint":"invertir"},{"prompt":"El cambio ___ con más inversión.","input":"text","hint":"ser"},{"prompt":"Actualmente, la plataforma ___.","input":"text","hint":"adaptar"},{"prompt":"Nosotros ___ hasta hoy.","input":"text","hint":"aprender"},{"prompt":"El próximo año, la escuela ___.","input":"text","hint":"transformar"},{"prompt":"Si fueras ministro, tú ___.","input":"text","hint":"proponer"}]}','{"items":[{"display":"han participado","answers":["han participado"]},{"display":"serán organizadas","answers":["serán organizadas"]},{"display":"invirtieran","answers":["invirtieran"]},{"display":"sería","answers":["sería"]},{"display":"adapta","answers":["adapta"]},{"display":"hemos aprendido","answers":["hemos aprendido"]},{"display":"se transformará","answers":["se transformará"]},{"display":"propondrías","answers":["propondrías"]}],"policy":{"accents":"strict"}}','published','L3-U07-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-educacion-20','es3-educacion','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Para quién se creó el programa?","input":"sentence"},{"prompt":"¿Por qué prepararon materiales sin conexión?","input":"sentence"},{"prompt":"¿Qué propusieron las familias?","input":"sentence"},{"prompt":"¿Qué han recibido los profesores?","input":"sentence"},{"prompt":"¿Qué ocurriría si se invirtiera más en infraestructura?","input":"sentence"}],"text":"Una escuela rural creó un programa híbrido para alumnos que vivían lejos. Como la conexión a internet no siempre era estable, los profesores prepararon también materiales que podían descargarse y usarse sin conexión. Después de un semestre, la asistencia había mejorado. Las familias pidieron que el programa continuara, aunque propusieron más encuentros presenciales.\n\nDesde que comenzó el programa, los profesores han recibido formación profesional y el centro educativo ha creado un servicio de orientación para las familias. El próximo año se ofrecerán tutorías en línea y se prestarán dispositivos a quienes no tengan ordenador. Si la administración invirtiera más en infraestructura, la educación inclusiva llegaría a otras comunidades rurales. Algunos docentes proponen que se combinen los recursos digitales con actividades prácticas, porque no quieren que el estudiante aprenda siempre frente a una pantalla. El director espera que la educación pública aproveche este modelo y que las nuevas medidas reduzcan la diferencia entre quienes viven cerca de una escuela y quienes deben recorrer largas distancias.\n\nLos alumnos también han creado grupos de estudio y han compartido recursos con otros centros. Si el proyecto continúa, podrán completar sus estudios superiores sin abandonar su comunidad. Para muchos, esa posibilidad representa un cambio profundo en su futuro."}','{"items":[{"display":"Para alumnos que vivían lejos","answers":["Para alumnos que vivían lejos"]},{"display":"Porque la conexión a internet no siempre era estable","answers":["Porque la conexión a internet no siempre era estable"]},{"display":"Más encuentros presenciales","answers":["Más encuentros presenciales"]},{"display":"Formación profesional","answers":["Formación profesional"]},{"display":"La educación inclusiva llegaría a otras comunidades rurales","answers":["La educación inclusiva llegaría a otras comunidades rurales"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U07-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento','es-3','es-3-stories','בידור','Entretenimiento','לדבר ולכתוב על הנושא „בידור“ בספרדית, תוך שימוש במבנים: Experiencias, opinión argumentada y tiempos del pasado.','derived','[{"he":"דקדוק בשימוש","target":"Experiencias, opinión argumentada y tiempos del pasado"},{"he":"אוצר מילים: בידור","target":"Entretenimiento"}]','["Experiencias, opinión argumentada y tiempos del pasado"]','{"rules":[],"examples":["Daniel ha visto muchas series.","Cuando llegó, los actores ya habían empezado.","La película fue la que más le impresionó el año pasado.","La recomendaría a quienes disfrutan del cine independiente."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Analizar","he":"לנתח"},{"term":"Audiencia","he":"צופים / קהל"},{"term":"Colaboración","he":"שיתוף פעולה"},{"term":"Colaborar","he":"לשתף פעולה"},{"term":"Comparar","he":"להשוות"},{"term":"Contenido","he":"תוכן"},{"term":"Crítica (reseña)","he":"ביקורת"},{"term":"Dirigir","he":"לביים"},{"term":"Editar","he":"לערוך"},{"term":"Estrenar","he":"לעלות לבכורה"},{"term":"Estreno","he":"בכורה"},{"term":"Evaluar","he":"להעריך"},{"term":"Exagerado","he":"מוגזם"},{"term":"experiencia","he":"חוויה / ניסיון"},{"term":"Género (cinematográfico/musical)","he":"ז׳אנר"},{"term":"Icónico","he":"סמלי / איקוני"},{"term":"Impacto","he":"השפעה"},{"term":"Industria","he":"תעשייה"},{"term":"Influir","he":"להשפיע"},{"term":"Infravalorado","he":"לא מוערך מספיק"},{"term":"Innovador","he":"חדשני"},{"term":"Inolvidable","he":"בלתי נשכח"},{"term":"Inspirador","he":"מעורר השראה"},{"term":"Interpretar","he":"לפרש / לשחק / לגלם"},{"term":"Lanzar (película, canción)","he":"לשחרר / להוציא לאור"},{"term":"Mensaje","he":"מסר / הודעה"},{"term":"Narrativa","he":"נרטיב / סיפור / נרטיב"},{"term":"Plataforma","he":"פלטפורמה"},{"term":"Premio","he":"פרס"},{"term":"Producir","he":"להפיק"},{"term":"Provocador","he":"פרובוקטיבי / מעורר מחשבה"},{"term":"Recomendar","he":"להמליץ"},{"term":"Sensacionalista","he":"צעקני / סנסציוני"},{"term":"Sobrevalorado","he":"מוערך יתר על המידה"},{"term":"Superficial","he":"שטחי"},{"term":"Tendencia","he":"מגמה"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1121277448/entretenimiento-flash-cards/?new"}]','published','workbook L3 unit 08',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-01','es3-entretenimiento','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"מוערך יתר על המידה ___","input":"text"},{"prompt":"בלתי נשכח ___","input":"text"},{"prompt":"שטחי ___","input":"text"},{"prompt":"לא מוערך מספיק ___","input":"text"},{"prompt":"פלטפורמה ___","input":"text"},{"prompt":"להעריך ___","input":"text"}]}','{"items":[{"display":"Sobrevalorado","answers":["Sobrevalorado"]},{"display":"Inolvidable","answers":["Inolvidable"]},{"display":"Superficial","answers":["Superficial"]},{"display":"Infravalorado","answers":["Infravalorado"]},{"display":"Plataforma","answers":["Plataforma"]},{"display":"Evaluar","answers":["Evaluar"]}],"policy":{"accents":"lenient"}}','published','L3-U08-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-02','es3-entretenimiento','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Sobrevalorado","Inolvidable","Superficial","Infravalorado","Plataforma","Evaluar","Producir","Mensaje"],"right":[{"id":"A","text":"להפיק"},{"id":"B","text":"מוערך יתר על המידה"},{"id":"C","text":"להעריך"},{"id":"D","text":"פלטפורמה"},{"id":"E","text":"בלתי נשכח"},{"id":"F","text":"שטחי"},{"id":"G","text":"מסר"},{"id":"H","text":"לא מוערך מספיק"}]}','{"pairs":["B","E","F","H","D","C","A","G"],"policy":{"accents":"lenient"}}','published','L3-U08-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-03','es3-entretenimiento','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"מוערך יתר על המידה","input":"choice","options":["Sobrevalorado","Innovador","Analizar"]},{"prompt":"בלתי נשכח","input":"choice","options":["Infravalorado","Dirigir","Inolvidable"]},{"prompt":"שטחי","input":"choice","options":["Superficial","Inolvidable","Narrativa"]},{"prompt":"לא מוערך מספיק","input":"choice","options":["Narrativa","Infravalorado","Audiencia"]},{"prompt":"פלטפורמה","input":"choice","options":["Plataforma","Tendencia","Exagerado"]},{"prompt":"להעריך","input":"choice","options":["Evaluar","Inspirador","Comparar"]}]}','{"items":[{"display":"Sobrevalorado","choice":0},{"display":"Inolvidable","choice":2},{"display":"Superficial","choice":0},{"display":"Infravalorado","choice":1},{"display":"Plataforma","choice":0},{"display":"Evaluar","choice":0}],"policy":{"accents":"lenient"}}','published','L3-U08-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-04','es3-entretenimiento','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"חדשני = ___","input":"bank"},{"prompt":"מגמה = ___","input":"bank"},{"prompt":"השפעה = ___","input":"bank"},{"prompt":"שיתוף פעולה = ___","input":"bank"},{"prompt":"מוערך יתר על המידה = ___","input":"bank"},{"prompt":"מסר = ___","input":"bank"}],"wordbank":["Colaboración","Impacto","Sobrevalorado","Tendencia","Innovador","Mensaje"],"text":"Daniel ha visto muchas series este año, pero una película chilena fue la que más le impresionó. Cuando llegó al festival, los actores ya habían empezado una conversación con el público. Daniel considera que la obra es original y la recomendaría a quienes disfrutan del cine independiente."}','{"items":[{"display":"Innovador","answers":["Innovador"]},{"display":"Tendencia","answers":["Tendencia"]},{"display":"Impacto","answers":["Impacto"]},{"display":"Colaboración","answers":["Colaboración"]},{"display":"Sobrevalorado","answers":["Sobrevalorado"]},{"display":"Mensaje","answers":["Mensaje"]}],"policy":{"accents":"strict"}}','published','L3-U08-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-05','es3-entretenimiento','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["ti","es","Qué","el","entretenimiento","para"]},{"prompt":"","input":"tokens","tokens":["Qué","pasado","has","Has","te","alguna","vez","evento","un","abandonado","porque","aburrido","cultural","ha"]},{"prompt":"","input":"tokens","tokens":["los","vivo","en","has","años","más","disfrutado","últimos","o","concierto","en","espectáculo","Qué"]},{"prompt":"","input":"tokens","tokens":["Prefieres","lo","lo","o","indie","mainstream"]}]}','{"items":[{"display":"¿Qué es para ti el entretenimiento?","answers":["¿Qué es para ti el entretenimiento?"]},{"display":"¿Has abandonado alguna vez un evento cultural porque te has aburrido? ¿Qué ha pasado?","answers":["¿Has abandonado alguna vez un evento cultural porque te has aburrido? ¿Qué ha pasado?"]},{"display":"¿Qué concierto o espectáculo en vivo has disfrutado más en los últimos años?","answers":["¿Qué concierto o espectáculo en vivo has disfrutado más en los últimos años?"]},{"display":"¿Prefieres lo mainstream o lo indie?","answers":["¿Prefieres lo mainstream o lo indie?"]}],"policy":{"accents":"strict"}}','published','L3-U08-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-06','es3-entretenimiento','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Daniel ha vio muchas series.","input":"sentence"},{"prompt":"Cuando llegó, los actores ya empezaron antes.","input":"sentence"},{"prompt":"La película fue la que más le ha impresionado el año pasado.","input":"sentence"},{"prompt":"La recomendaría a quienes disfruta del cine independiente.","input":"sentence"}]}','{"items":[{"display":"Daniel ha visto muchas series.","answers":["Daniel ha visto muchas series."]},{"display":"Cuando llegó, los actores ya habían empezado.","answers":["Cuando llegó, los actores ya habían empezado."]},{"display":"La película fue la que más le impresionó el año pasado.","answers":["La película fue la que más le impresionó el año pasado."]},{"display":"La recomendaría a quienes disfrutan del cine independiente.","answers":["La recomendaría a quienes disfrutan del cine independiente."]}],"policy":{"accents":"strict"}}','published','L3-U08-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-07','es3-entretenimiento','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Daniel ha vio muchas series.","Daniel ha visto muchas series."]},{"prompt":"","input":"choice","options":["Cuando llegó, los actores ya habían empezado.","Cuando llegó, los actores ya empezaron antes."]},{"prompt":"","input":"choice","options":["La película fue la que más le impresionó el año pasado.","La película fue la que más le ha impresionado el año pasado."]},{"prompt":"","input":"choice","options":["La recomendaría a quienes disfruta del cine independiente.","La recomendaría a quienes disfrutan del cine independiente."]}]}','{"items":[{"display":"Daniel ha visto muchas series.","choice":1},{"display":"Cuando llegó, los actores ya empezaron antes.","choice":1},{"display":"La película fue la que más le ha impresionado el año pasado.","choice":1},{"display":"La recomendaría a quienes disfrutan del cine independiente.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U08-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-08','es3-entretenimiento','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**Daniel** · ver · este año","input":"text"},{"prompt":"**la película** · impresionar · el año pasado","input":"text"},{"prompt":"**los actores** · empezar · antes de su llegada","input":"text"},{"prompt":"**Daniel** · recomendar · si le preguntaran","input":"text"}]}','{"items":[{"display":"ha visto","answers":["ha visto"]},{"display":"impresionó","answers":["impresionó"]},{"display":"habían empezado","answers":["habían empezado"]},{"display":"recomendaría","answers":["recomendaría"]}],"policy":{"accents":"strict"}}','published','L3-U08-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-09','es3-entretenimiento','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Qué es para ti el entretenimiento?\n¿Por qué?\n¿Has abandonado alguna vez un evento cultural porque te has aburrido? ¿Qué ha pasado?\n¿Qué concierto o espectáculo en vivo has disfrutado más en los últimos años?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U08-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-10','es3-entretenimiento','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**Daniel** · ver · este año","input":"text"},{"prompt":"**la película** · impresionar · el año pasado","input":"text"},{"prompt":"**los actores** · empezar · antes de su llegada","input":"text"},{"prompt":"**Daniel** · recomendar · si le preguntaran","input":"text"},{"prompt":"**el festival** · organizar · este mes","input":"text"},{"prompt":"**nosotros** · disfrutar · ayer","input":"text"},{"prompt":"**tú** · elegir · si tuvieras tiempo","input":"text"},{"prompt":"**la serie** · ganar · el año pasado","input":"text"}]}','{"items":[{"display":"ha visto","answers":["ha visto"]},{"display":"impresionó","answers":["impresionó"]},{"display":"habían empezado","answers":["habían empezado"]},{"display":"recomendaría","answers":["recomendaría"]},{"display":"ha sido organizado","answers":["ha sido organizado"]},{"display":"disfrutamos","answers":["disfrutamos"]},{"display":"elegirías","answers":["elegirías"]},{"display":"ganó","answers":["ganó"]}],"policy":{"accents":"strict"}}','published','L3-U08-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-11','es3-entretenimiento','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué impresionó más a Daniel?","input":"sentence"},{"prompt":"¿Qué había empezado cuando llegó?","input":"sentence"},{"prompt":"¿A quién recomendaría la obra?","input":"sentence"}],"text":"Daniel ha visto muchas series este año, pero una película chilena fue la que más le impresionó. Cuando llegó al festival, los actores ya habían empezado una conversación con el público. Daniel considera que la obra es original y la recomendaría a quienes disfrutan del cine independiente."}','{"items":[{"display":"Una película chilena.","answers":["Una película chilena."]},{"display":"Una conversación entre los actores y el público.","answers":["Una conversación entre los actores y el público."]},{"display":"A quienes disfrutan del cine independiente.","answers":["A quienes disfrutan del cine independiente."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U08-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-12','es3-entretenimiento','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Entretenimiento\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Daniel ha visto muchas series este año, pero una película chilena fue la que más le impresionó. Cuando llegó al festival, los actores ya habían empezado una conversación con el público. Daniel considera que la obra es original y la recomendaría a quienes disfrutan del cine independiente."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U08-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-13','es3-entretenimiento','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Qué había empezado cuando llegó?"},{"id":"B","text":"Respuesta: Una conversación entre los actores y el público."},{"id":"C","text":"Pregunta: ¿A quién recomendaría la obra?"},{"id":"D","text":"Pregunta: ¿Qué impresionó más a Daniel?"},{"id":"E","text":"Respuesta: Una película chilena."},{"id":"F","text":"Respuesta: A quienes disfrutan del cine independiente."}]}','{"order":["D","E","A","B","C","F"],"policy":{"accents":"strict"}}','published','L3-U08-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-14','es3-entretenimiento','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Daniel ha visto muchas series este año, pero una película chilena fue la que más le impresionó."},{"id":"B","text":"Daniel considera que la obra es original y la recomendaría a quienes disfrutan del cine independiente."},{"id":"C","text":"Cuando llegó al festival, los actores ya habían empezado una conversación con el público."}]}','{"order":["A","C","B"],"policy":{"accents":"strict"}}','published','L3-U08-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-15','es3-entretenimiento','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre entretenimiento es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre entretenimiento es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U08-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-16','es3-entretenimiento','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"שטחי = ___","input":"text"},{"prompt":"לא מוערך מספיק = ___","input":"text"},{"prompt":"פלטפורמה = ___","input":"text"},{"prompt":"להעריך = ___","input":"text"},{"prompt":"**la serie** · ganar · el año pasado","input":"text"},{"prompt":"**tú** · elegir · si tuvieras tiempo","input":"text"},{"prompt":"**nosotros** · disfrutar · ayer","input":"text"},{"prompt":"**el festival** · organizar · este mes","input":"text"},{"prompt":"**Daniel** · recomendar · si le preguntaran","input":"text"},{"prompt":"**los actores** · empezar · antes de su llegada","input":"text"}]}','{"items":[{"display":"Superficial","answers":["Superficial"],"policy":{"accents":"lenient"}},{"display":"Infravalorado","answers":["Infravalorado"],"policy":{"accents":"lenient"}},{"display":"Plataforma","answers":["Plataforma"],"policy":{"accents":"lenient"}},{"display":"Evaluar","answers":["Evaluar"],"policy":{"accents":"lenient"}},{"display":"ganó","answers":["ganó"]},{"display":"elegirías","answers":["elegirías"]},{"display":"disfrutamos","answers":["disfrutamos"]},{"display":"ha sido organizado","answers":["ha sido organizado"]},{"display":"recomendaría","answers":["recomendaría"]},{"display":"habían empezado","answers":["habían empezado"]}],"policy":{"accents":"strict"}}','published','L3-U08-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-17','es3-entretenimiento','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Daniel ha visto muchas series este año, pero una película chilena fue la que más le impresionó. Cuando llegó al festival, los actores ya habían empezado una conversación con el público."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U08-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-18','es3-entretenimiento','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"La ___ musical ha cambiado por completo con el streaming.","input":"bank"},{"prompt":"¿Qué ___ te ha sorprendido más?","input":"bank"},{"prompt":"Los productores han utilizado escándalos para atraer ___.","input":"bank"},{"prompt":"Ej.: superficial, exagerado, ___, polémico, repetitivo.","input":"bank"},{"prompt":"Ej.: superficial, ___, sensacionalista, polémico, repetitivo.","input":"bank"},{"prompt":"חדשני = ___","input":"bank"},{"prompt":"השפעה = ___","input":"bank"},{"prompt":"ביקורת = ___","input":"bank"},{"prompt":"סמלי / איקוני = ___","input":"bank"},{"prompt":"ז׳אנר = ___","input":"bank"}],"wordbank":["Innovador","Crítica (reseña)","Género (cinematográfico/musical)","Impacto","Sensacionalista","Industria","Colaboración","Icónico","Audiencia","Exagerado"]}','{"items":[{"display":"Industria","answers":["Industria"]},{"display":"Colaboración","answers":["Colaboración"]},{"display":"Audiencia","answers":["Audiencia"]},{"display":"Sensacionalista","answers":["Sensacionalista"]},{"display":"Exagerado","answers":["Exagerado"]},{"display":"Innovador","answers":["Innovador"]},{"display":"Impacto","answers":["Impacto"]},{"display":"Crítica (reseña)","answers":["Crítica (reseña)","Crítica"]},{"display":"Icónico","answers":["Icónico"]},{"display":"Género (cinematográfico/musical)","answers":["Género (cinematográfico/musical)","Género"]}],"policy":{"accents":"strict"}}','published','L3-U08-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-19','es3-entretenimiento','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Este año, Daniel ___.","input":"text","hint":"ver"},{"prompt":"El año pasado, la película ___.","input":"text","hint":"impresionar"},{"prompt":"Antes de su llegada, los actores ___.","input":"text","hint":"empezar"},{"prompt":"Si le preguntaran, Daniel ___.","input":"text","hint":"recomendar"},{"prompt":"Este mes, el festival ___.","input":"text","hint":"organizar"},{"prompt":"Ayer, nosotros ___.","input":"text","hint":"disfrutar"},{"prompt":"Si tuvieras tiempo, tú ___.","input":"text","hint":"elegir"},{"prompt":"El año pasado, la serie ___.","input":"text","hint":"ganar"}]}','{"items":[{"display":"ha visto","answers":["ha visto"]},{"display":"impresionó","answers":["impresionó"]},{"display":"habían empezado","answers":["habían empezado"]},{"display":"recomendaría","answers":["recomendaría"]},{"display":"ha sido organizado","answers":["ha sido organizado"]},{"display":"disfrutamos","answers":["disfrutamos"]},{"display":"elegirías","answers":["elegirías"]},{"display":"ganó","answers":["ganó"]}],"policy":{"accents":"strict"}}','published','L3-U08-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-entretenimiento-20','es3-entretenimiento','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Dónde se organizaron las funciones?","input":"sentence"},{"prompt":"¿Qué podía donar el público?","input":"sentence"},{"prompt":"¿Qué cambios pidió la gente?","input":"sentence"},{"prompt":"¿Cómo fue considerada la primera película por muchos espectadores?","input":"sentence"},{"prompt":"¿Por qué fue inspirador el proyecto según el texto?","input":"sentence"}],"text":"Un barrio recuperó un cine cerrado y organizó funciones al aire libre durante el verano. Las entradas eran gratuitas, pero el público podía donar alimentos para una asociación local. Después de la primera función, varias personas pidieron subtítulos y una zona accesible. Los organizadores hicieron los cambios y la asistencia aumentó cada semana.\n\nLa programación incluía una película independiente que había sido ignorada por la industria y un documental considerado provocador por la crítica. Muchos espectadores dijeron que la primera obra era innovadora e inolvidable, mientras que otros la encontraron lenta y sobrevalorada. La directora del festival defendió la selección: explicó que una audiencia diversa necesita propuestas que no sean superficiales ni sensacionalistas. Antes de recuperar el cine, los vecinos solo habían visto grandes producciones comerciales. Después del festival, varios jóvenes empezaron a organizar debates y recomendaron títulos infravalorados. En mi opinión, el proyecto fue inspirador porque no intentó complacer a todo el mundo, sino ampliar la conversación cultural del barrio.\n\nEl cine se convirtió en un punto de encuentro y no solo en una sala de proyección. La audiencia aprendió a expresar opiniones opuestas con argumentos, y los organizadores entendieron que una programación de calidad también debe ser accesible."}','{"items":[{"display":"Al aire libre","answers":["Al aire libre"]},{"display":"Alimentos","answers":["Alimentos"]},{"display":"Subtítulos y una zona accesible","answers":["Subtítulos y una zona accesible"]},{"display":"Innovadora e inolvidable","answers":["Innovadora e inolvidable"]},{"display":"Porque amplió la conversación cultural del barrio","answers":["Porque amplió la conversación cultural del barrio"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U08-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes','es-3','es-3-society','חדשות אקטואליות','Noticias recientes','לדבר ולכתוב על הנושא „חדשות אקטואליות“ בספרדית, תוך שימוש במבנים: Estilo indirecto, voz pasiva y tiempos mezclados.','derived','[{"he":"דקדוק בשימוש","target":"Estilo indirecto, voz pasiva y tiempos mezclados"},{"he":"אוצר מילים: חדשות אקטואליות","target":"Noticias recientes"}]','["Estilo indirecto, voz pasiva y tiempos mezclados"]','{"rules":[],"examples":["La portavoz dijo que el gobierno anunciaría el plan al día siguiente.","Explicó que la propuesta ya había sido aprobada.","Los detalles serían publicados en la web.","Muchos ciudadanos han expresado dudas."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Afirmar","he":"לטעון / לאשר"},{"term":"Aplicar (medidas)","he":"ליישם"},{"term":"Argumento","he":"טיעון"},{"term":"artículo","he":"כתבה"},{"term":"Aumentar","he":"לעלות / לגדול"},{"term":"Comentar","he":"לומר / להגיב"},{"term":"Comparar","he":"להשוות"},{"term":"Consumir noticias","he":"לצרוך חדשות"},{"term":"Contexto","he":"הקשר"},{"term":"Crisis","he":"משבר"},{"term":"Debatir","he":"לדון / להתווכח"},{"term":"Declarar / Anuncio","he":"הודעה / להצהיר"},{"term":"Desastre","he":"אסון"},{"term":"Descuento","he":"הנחה"},{"term":"Elegir","he":"לבחור"},{"term":"Estilo indirecto","he":"סגנון עקיף"},{"term":"Frecuencia","he":"תדירות"},{"term":"Fuente (de información)","he":"מקור"},{"term":"Hipótesis","he":"השערה / השערה / הנחה"},{"term":"Impacto","he":"השפעה"},{"term":"Informar","he":"לדווח"},{"term":"Medidas (gubernamentales)","he":"אמצעים / צעדים"},{"term":"mejorar","he":"להשתפר / לשפר"},{"term":"Movilidad","he":"ניידות"},{"term":"noticia","he":"חדשות"},{"term":"Opinión","he":"דעה"},{"term":"Portavoz","he":"דובר / דוברת / דובר"},{"term":"Predicción / Pronóstico","he":"תחזית"},{"term":"Protesta","he":"הפגנה"},{"term":"Reaccionar","he":"להגיב"},{"term":"Redes sociales","he":"רשתות חברתיות"},{"term":"reportero / periodista","he":"עיתונאי / כתב"},{"term":"Resumir","he":"לסכם"},{"term":"Rumor","he":"שמועה"},{"term":"titular","he":"כותרת"},{"term":"Transporte público","he":"תחבורה ציבורית"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/1121348298/noticias-recientes-flash-cards/?new"}]','published','workbook L3 unit 09',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-01','es3-noticias-recientes','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"מקור ___","input":"text"},{"prompt":"תדירות ___","input":"text"},{"prompt":"השערה / הנחה ___","input":"text"},{"prompt":"סגנון עקיף ___","input":"text"},{"prompt":"משבר ___","input":"text"},{"prompt":"דובר ___","input":"text"}]}','{"items":[{"display":"Fuente (de información)","answers":["Fuente (de información)","Fuente"]},{"display":"Frecuencia","answers":["Frecuencia"]},{"display":"Hipótesis","answers":["Hipótesis"]},{"display":"Estilo indirecto","answers":["Estilo indirecto"]},{"display":"Crisis","answers":["Crisis"]},{"display":"Portavoz","answers":["Portavoz"]}],"policy":{"accents":"lenient"}}','published','L3-U09-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-02','es3-noticias-recientes','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Fuente (de información)","Frecuencia","Hipótesis","Estilo indirecto","Crisis","Portavoz","Movilidad","Medidas (gubernamentales)"],"right":[{"id":"A","text":"מקור"},{"id":"B","text":"ניידות"},{"id":"C","text":"אמצעים / צעדים"},{"id":"D","text":"תדירות"},{"id":"E","text":"סגנון עקיף"},{"id":"F","text":"דובר"},{"id":"G","text":"משבר"},{"id":"H","text":"השערה / הנחה"}]}','{"pairs":["A","D","H","E","G","F","B","C"],"policy":{"accents":"lenient"}}','published','L3-U09-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-03','es3-noticias-recientes','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"מקור","input":"choice","options":["Fuente (de información)","Comentar","Descuento"]},{"prompt":"תדירות","input":"choice","options":["Movilidad","Frecuencia","Debatir"]},{"prompt":"השערה / הנחה","input":"choice","options":["Descuento","Hipótesis","Comparar"]},{"prompt":"סגנון עקיף","input":"choice","options":["Rumor","Estilo indirecto","reportero / periodista"]},{"prompt":"משבר","input":"choice","options":["Crisis","Protesta","Elegir"]},{"prompt":"דובר","input":"choice","options":["Descuento","Portavoz","Mejorar"]}]}','{"items":[{"display":"Fuente (de información)","choice":0},{"display":"Frecuencia","choice":1},{"display":"Hipótesis","choice":1},{"display":"Estilo indirecto","choice":1},{"display":"Crisis","choice":0},{"display":"Portavoz","choice":1}],"policy":{"accents":"lenient"}}','published','L3-U09-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-04','es3-noticias-recientes','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"חדשות = ___","input":"bank"},{"prompt":"לדון / להתווכח = ___","input":"bank"},{"prompt":"הקשר = ___","input":"bank"},{"prompt":"תחבורה ציבורית = ___","input":"bank"},{"prompt":"שמועה = ___","input":"bank"}],"wordbank":["Rumor","portavoz","noticia","Contexto","Transporte público","Debatir"],"text":"La {{1}} dijo que el gobierno anunciaría un nuevo plan al día siguiente. Explicó que la propuesta ya había sido aprobada y que los detalles serían publicados en la web. Desde entonces, muchos ciudadanos han expresado dudas y varios expertos han pedido más transparencia."}','{"items":[{"display":"portavoz","answers":["portavoz"]},{"display":"noticia","answers":["noticia"]},{"display":"Debatir","answers":["Debatir"]},{"display":"Contexto","answers":["Contexto"]},{"display":"Transporte público","answers":["Transporte público"]},{"display":"Rumor","answers":["Rumor"]}],"policy":{"accents":"strict"}}','published','L3-U09-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-05','es3-noticias-recientes','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["Cada","persona","noticias","una","que","cuánto","debe","consumir","crees"]},{"prompt":"","input":"tokens","tokens":["es","de","ti","expresión","para","la","libertad","Qué"]},{"prompt":"","input":"tokens","tokens":["tu","recientemente","o","crisis","ocurrido","desastre","en","protesta","una","Ha","zona"]},{"prompt":"","input":"tokens","tokens":["han","sociales","las","noticias","las","con","Cómo","cambiado","redes"]}]}','{"items":[{"display":"¿Cada cuánto crees que una persona debe consumir noticias?","answers":["¿Cada cuánto crees que una persona debe consumir noticias?"]},{"display":"¿Qué es para ti la libertad de expresión?","answers":["¿Qué es para ti la libertad de expresión?"]},{"display":"¿Ha ocurrido una protesta, crisis o desastre en tu zona recientemente?","answers":["¿Ha ocurrido una protesta, crisis o desastre en tu zona recientemente?"]},{"display":"¿Cómo han cambiado las noticias con las redes sociales?","answers":["¿Cómo han cambiado las noticias con las redes sociales?"]}],"policy":{"accents":"strict"}}','published','L3-U09-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-06','es3-noticias-recientes','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"La portavoz dijo que el gobierno anunciará el plan al día siguiente.","input":"sentence"},{"prompt":"Explicó que la propuesta ya aprobó.","input":"sentence"},{"prompt":"Los detalles publicarían en la web.","input":"sentence"},{"prompt":"Muchos ciudadanos han expresó dudas.","input":"sentence"}]}','{"items":[{"display":"La portavoz dijo que el gobierno anunciaría el plan al día siguiente.","answers":["La portavoz dijo que el gobierno anunciaría el plan al día siguiente."]},{"display":"Explicó que la propuesta ya había sido aprobada.","answers":["Explicó que la propuesta ya había sido aprobada."]},{"display":"Los detalles serían publicados en la web.","answers":["Los detalles serían publicados en la web."]},{"display":"Muchos ciudadanos han expresado dudas.","answers":["Muchos ciudadanos han expresado dudas."]}],"policy":{"accents":"strict"}}','published','L3-U09-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-07','es3-noticias-recientes','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["La portavoz dijo que el gobierno anunciará el plan al día siguiente.","La portavoz dijo que el gobierno anunciaría el plan al día siguiente."]},{"prompt":"","input":"choice","options":["Explicó que la propuesta ya había sido aprobada.","Explicó que la propuesta ya aprobó."]},{"prompt":"","input":"choice","options":["Los detalles publicarían en la web.","Los detalles serían publicados en la web."]},{"prompt":"","input":"choice","options":["Muchos ciudadanos han expresado dudas.","Muchos ciudadanos han expresó dudas."]}]}','{"items":[{"display":"La portavoz dijo que el gobierno anunciaría el plan al día siguiente.","choice":1},{"display":"Explicó que la propuesta ya aprobó.","choice":1},{"display":"Los detalles serían publicados en la web.","choice":1},{"display":"Muchos ciudadanos han expresó dudas.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U09-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-08','es3-noticias-recientes','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**la portavoz** · decir · ayer","input":"text"},{"prompt":"**el gobierno** · anunciar · según la portavoz","input":"text"},{"prompt":"**la propuesta** · aprobar · antes del anuncio","input":"text"},{"prompt":"**los detalles** · publicar · mañana","input":"text"}]}','{"items":[{"display":"dijo","answers":["dijo"]},{"display":"anunciaría","answers":["anunciaría"]},{"display":"había sido aprobada","answers":["había sido aprobada"]},{"display":"serán publicados","answers":["serán publicados"]}],"policy":{"accents":"strict"}}','published','L3-U09-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-09','es3-noticias-recientes','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Cada cuánto crees que una persona debe consumir noticias?\n¿Qué es para ti la libertad de expresión?\n¿Ha ocurrido una protesta, crisis o desastre en tu zona recientemente?\n¿Cómo han cambiado las noticias con las redes sociales?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U09-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-10','es3-noticias-recientes','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**la portavoz** · decir · ayer","input":"text"},{"prompt":"**el gobierno** · anunciar · según la portavoz","input":"text"},{"prompt":"**la propuesta** · aprobar · antes del anuncio","input":"text"},{"prompt":"**los detalles** · publicar · mañana","input":"text"},{"prompt":"**los ciudadanos** · expresar · desde entonces","input":"text"},{"prompt":"**los expertos** · pedir · esta semana","input":"text"},{"prompt":"**el plan** · debatir · actualmente","input":"text"},{"prompt":"**nosotros** · informar · al día siguiente","input":"text"}]}','{"items":[{"display":"dijo","answers":["dijo"]},{"display":"anunciaría","answers":["anunciaría"]},{"display":"había sido aprobada","answers":["había sido aprobada"]},{"display":"serán publicados","answers":["serán publicados"]},{"display":"han expresado","answers":["han expresado"]},{"display":"han pedido","answers":["han pedido"]},{"display":"es debatido","answers":["es debatido"]},{"display":"informaríamos","answers":["informaríamos"]}],"policy":{"accents":"strict"}}','published','L3-U09-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-11','es3-noticias-recientes','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué dijo la portavoz?","input":"sentence"},{"prompt":"¿Qué ya había sido aprobado?","input":"sentence"},{"prompt":"¿Qué han pedido varios expertos?","input":"sentence"}],"text":"La portavoz dijo que el gobierno anunciaría un nuevo plan al día siguiente. Explicó que la propuesta ya había sido aprobada y que los detalles serían publicados en la web. Desde entonces, muchos ciudadanos han expresado dudas y varios expertos han pedido más transparencia."}','{"items":[{"display":"Que el gobierno anunciaría un nuevo plan.","answers":["Que el gobierno anunciaría un nuevo plan."]},{"display":"La propuesta.","answers":["La propuesta."]},{"display":"Más transparencia.","answers":["Más transparencia."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U09-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-12','es3-noticias-recientes','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Noticias recientes\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["La portavoz dijo que el gobierno anunciaría un nuevo plan al día siguiente. Explicó que la propuesta ya había sido aprobada y que los detalles serían publicados en la web. Desde entonces, muchos ciudadanos han expresado dudas y varios expertos han pedido más transparencia."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U09-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-13','es3-noticias-recientes','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: Que el gobierno anunciaría un nuevo plan."},{"id":"B","text":"Respuesta: La propuesta."},{"id":"C","text":"Pregunta: ¿Qué dijo la portavoz?"},{"id":"D","text":"Respuesta: Más transparencia."},{"id":"E","text":"Pregunta: ¿Qué han pedido varios expertos?"},{"id":"F","text":"Pregunta: ¿Qué ya había sido aprobado?"}]}','{"order":["C","A","F","B","E","D"],"policy":{"accents":"strict"}}','published','L3-U09-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-14','es3-noticias-recientes','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Explicó que la propuesta ya había sido aprobada y que los detalles serían publicados en la web."},{"id":"B","text":"Desde entonces, muchos ciudadanos han expresado dudas y varios expertos han pedido más transparencia."},{"id":"C","text":"La portavoz dijo que el gobierno anunciaría un nuevo plan al día siguiente."}]}','{"order":["C","A","B"],"policy":{"accents":"strict"}}','published','L3-U09-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-15','es3-noticias-recientes','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre noticias recientes es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre noticias recientes es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U09-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-16','es3-noticias-recientes','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"השערה / הנחה = ___","input":"text"},{"prompt":"סגנון עקיף = ___","input":"text"},{"prompt":"משבר = ___","input":"text"},{"prompt":"דובר = ___","input":"text"},{"prompt":"**nosotros** · informar · al día siguiente","input":"text"},{"prompt":"**el plan** · debatir · actualmente","input":"text"},{"prompt":"**los expertos** · pedir · esta semana","input":"text"},{"prompt":"**los ciudadanos** · expresar · desde entonces","input":"text"},{"prompt":"**los detalles** · publicar · mañana","input":"text"},{"prompt":"**la propuesta** · aprobar · antes del anuncio","input":"text"}]}','{"items":[{"display":"Hipótesis","answers":["Hipótesis"],"policy":{"accents":"lenient"}},{"display":"Estilo indirecto","answers":["Estilo indirecto"],"policy":{"accents":"lenient"}},{"display":"Crisis","answers":["Crisis"],"policy":{"accents":"lenient"}},{"display":"Portavoz","answers":["Portavoz"],"policy":{"accents":"lenient"}},{"display":"informaríamos","answers":["informaríamos"]},{"display":"es debatido","answers":["es debatido"]},{"display":"han pedido","answers":["han pedido"]},{"display":"han expresado","answers":["han expresado"]},{"display":"serán publicados","answers":["serán publicados"]},{"display":"había sido aprobada","answers":["había sido aprobada"]}],"policy":{"accents":"strict"}}','published','L3-U09-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-17','es3-noticias-recientes','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["La portavoz dijo que el gobierno anunciaría un nuevo plan al día siguiente. Explicó que la propuesta ya había sido aprobada y que los detalles serían publicados en la web."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U09-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-18','es3-noticias-recientes','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"¿Cada cuánto crees que una persona debe ___?","input":"bank"},{"prompt":"¿Cómo han cambiado las noticias con las ___?","input":"bank"},{"prompt":"¿En tu ___, los niños están demasiado expuestos a las noticias?","input":"bank"},{"prompt":"¿Has visto una ___ o predicción del tiempo equivocada? ¿Qué pasó?","input":"bank"},{"prompt":"Mira si el ___ está en presente, pasado o futuro.","input":"bank"},{"prompt":"¿Ha ocurrido una protesta, crisis o ___ en tu zona recientemente?","input":"bank"},{"prompt":"הקשר = ___","input":"bank"},{"prompt":"כתבה = ___","input":"bank"},{"prompt":"לומר / להגיב = ___","input":"bank"},{"prompt":"ליישם = ___","input":"bank"}],"wordbank":["Consumir noticias","Desastre","noticia","Comentar","artículo","Opinión","titular","Contexto","Aplicar (medidas)","Redes sociales"]}','{"items":[{"display":"Consumir noticias","answers":["Consumir noticias"]},{"display":"Redes sociales","answers":["Redes sociales"]},{"display":"Opinión","answers":["Opinión"]},{"display":"noticia","answers":["noticia"]},{"display":"titular","answers":["titular"]},{"display":"Desastre","answers":["Desastre"]},{"display":"Contexto","answers":["Contexto"]},{"display":"artículo","answers":["artículo"]},{"display":"Comentar","answers":["Comentar"]},{"display":"Aplicar (medidas)","answers":["Aplicar (medidas)","Aplicar"]}],"policy":{"accents":"strict"}}','published','L3-U09-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-19','es3-noticias-recientes','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Ayer, la portavoz ___.","input":"text","hint":"decir"},{"prompt":"El gobierno ___ según la portavoz.","input":"text","hint":"anunciar"},{"prompt":"Antes del anuncio, la propuesta ___.","input":"text","hint":"aprobar"},{"prompt":"Mañana, los detalles ___.","input":"text","hint":"publicar"},{"prompt":"Los ciudadanos ___ desde entonces.","input":"text","hint":"expresar"},{"prompt":"Esta semana, los expertos ___.","input":"text","hint":"pedir"},{"prompt":"Actualmente, el plan ___.","input":"text","hint":"debatir"},{"prompt":"Al día siguiente, nosotros ___.","input":"text","hint":"informar"}]}','{"items":[{"display":"dijo","answers":["dijo"]},{"display":"anunciaría","answers":["anunciaría"]},{"display":"había sido aprobada","answers":["había sido aprobada"]},{"display":"serán publicados","answers":["serán publicados"]},{"display":"han expresado","answers":["han expresado"]},{"display":"han pedido","answers":["han pedido"]},{"display":"es debatido","answers":["es debatido"]},{"display":"informaríamos","answers":["informaríamos"]}],"policy":{"accents":"strict"}}','published','L3-U09-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-noticias-recientes-20','es3-noticias-recientes','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Qué afirmaba la noticia?","input":"sentence"},{"prompt":"¿Cómo verificó Sara la información?","input":"sentence"},{"prompt":"¿Qué ocurriría realmente?","input":"sentence"},{"prompt":"¿Qué declaró el portavoz sobre el rumor?","input":"sentence"},{"prompt":"¿Qué explicó Sara sobre las fuentes?","input":"sentence"}],"text":"Una noticia afirmaba que el ayuntamiento cerraría todos los mercados del centro. Antes de publicarla, Sara consultó el documento original y habló con dos fuentes independientes. Descubrió que solo se renovaría un mercado durante seis semanas. Su artículo explicó el error y mostró por qué un titular alarmista podía cambiar la percepción de los lectores.\n\nEl portavoz municipal declaró que el rumor había surgido de una versión antigua del plan. Añadió que la información correcta sería publicada esa misma tarde y que los comerciantes serían avisados directamente. El artículo de Sara fue compartido por otros medios y el titular original fue corregido. Más tarde, varios lectores comentaron que ya habían enviado la noticia falsa a sus familias. Sara explicó que una fuente oficial no siempre es suficiente y que cada dato debe ser comparado con documentos y testimonios. También informó de que el mercado renovado permanecería abierto durante los fines de semana para reducir el impacto sobre los negocios.\n\nLa periodista concluyó que verificar una noticia exige tiempo, especialmente cuando el rumor confirma lo que el público ya quiere creer. Por eso recomienda leer más allá del titular, comprobar la fecha y buscar el origen de cualquier afirmación sorprendente."}','{"items":[{"display":"Que el ayuntamiento cerraría todos los mercados del centro","answers":["Que el ayuntamiento cerraría todos los mercados del centro"]},{"display":"Consultó el documento original y habló con dos fuentes independientes","answers":["Consultó el documento original y habló con dos fuentes independientes"]},{"display":"Se renovaría un mercado durante seis semanas","answers":["Se renovaría un mercado durante seis semanas"]},{"display":"Que había surgido de una versión antigua del plan","answers":["Que había surgido de una versión antigua del plan"]},{"display":"Que cada dato debe compararse con documentos y testimonios","answers":["Que cada dato debe compararse con documentos y testimonios"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U09-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor','es-3','es-3-people','חוגגים אהבה','Celebramos el amor','לדבר ולכתוב על הנושא „חוגגים אהבה“ בספרדית, תוך שימוש במבנים: Subjuntivo, deseos y estilo indirecto.','derived','[{"he":"דקדוק בשימוש","target":"Subjuntivo, deseos y estilo indirecto"},{"he":"אוצר מילים: חוגגים אהבה","target":"Celebramos el amor"}]','["Subjuntivo, deseos y estilo indirecto"]','{"rules":[],"examples":["Elena espera que su pareja respete sus proyectos.","Su familia recomendó que no se apresurara.","Una amiga contó que su hermano había cambiado de ciudad.","Si vivieran cerca, podrían construir una relación."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Afecto","he":"חיבה"},{"term":"Alegría","he":"שמחה"},{"term":"Cariño","he":"חיבה / אהבה"},{"term":"Celebración","he":"חגיגה"},{"term":"Comparación","he":"השוואה"},{"term":"Compromiso","he":"מחויבות"},{"term":"Confianza","he":"אמון / ביטחון / אמון"},{"term":"Consejo","he":"עצה"},{"term":"Costumbre","he":"מנהג"},{"term":"Cultura","he":"תרבות"},{"term":"Declaración","he":"הצהרה"},{"term":"Deseo","he":"רצון / משאלה"},{"term":"Diferencia","he":"הבדל"},{"term":"Discusión","he":"ויכוח"},{"term":"Duda","he":"ספק"},{"term":"Emoción","he":"רגש"},{"term":"Esperanza","he":"תקווה"},{"term":"Festividad","he":"חג"},{"term":"Fidelidad","he":"נאמנות"},{"term":"Gesto","he":"מחווה"},{"term":"Igualdad","he":"שוויון"},{"term":"Inferior","he":"נחות"},{"term":"Intimidad","he":"קרבה"},{"term":"Opinión","he":"דעה"},{"term":"Pareja","he":"זוג"},{"term":"Perspectiva","he":"נקודת מבט / נקודת מבטs"},{"term":"Promesa","he":"הבטחה"},{"term":"Recomendación","he":"המלצה"},{"term":"Regalo","he":"מתנה"},{"term":"Relación","he":"מערכת יחסים"},{"term":"Respeto","he":"כבוד"},{"term":"Ritual","he":"טקס"},{"term":"Símbolo","he":"סמל"},{"term":"Superior","he":"טוב יותר / עליון"},{"term":"Tradición","he":"מסורת"},{"term":"Tristeza","he":"עצב"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1073213590/celebramos-el-amor-nivel-3-flash-cards/?new"}]','published','workbook L3 unit 10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-01','es3-celebramos-el-amor','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"מתנה ___","input":"text"},{"prompt":"הצהרה ___","input":"text"},{"prompt":"שמחה ___","input":"text"},{"prompt":"המלצה ___","input":"text"},{"prompt":"הבדל ___","input":"text"},{"prompt":"מסורת ___","input":"text"}]}','{"items":[{"display":"Regalo","answers":["Regalo"]},{"display":"Declaración","answers":["Declaración"]},{"display":"Alegría","answers":["Alegría"]},{"display":"Recomendación","answers":["Recomendación"]},{"display":"Diferencia","answers":["Diferencia"]},{"display":"Tradición","answers":["Tradición"]}],"policy":{"accents":"lenient"}}','published','L3-U10-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-02','es3-celebramos-el-amor','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Regalo","Declaración","Alegría","Recomendación","Diferencia","Tradición","Relación","Deseo"],"right":[{"id":"A","text":"שמחה"},{"id":"B","text":"מערכת יחסים"},{"id":"C","text":"המלצה"},{"id":"D","text":"מתנה"},{"id":"E","text":"מסורת"},{"id":"F","text":"הבדל"},{"id":"G","text":"רצון / משאלה"},{"id":"H","text":"הצהרה"}]}','{"pairs":["D","H","A","C","F","E","B","G"],"policy":{"accents":"lenient"}}','published','L3-U10-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-03','es3-celebramos-el-amor','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"מתנה","input":"choice","options":["Regalo","Relación","Fidelidad"]},{"prompt":"הצהרה","input":"choice","options":["Declaración","Gesto","Duda"]},{"prompt":"שמחה","input":"choice","options":["Respeto","Alegría","Comparación"]},{"prompt":"המלצה","input":"choice","options":["Símbolo","Recomendación","Tradición"]},{"prompt":"הבדל","input":"choice","options":["Deseo","Diferencia","Ritual"]},{"prompt":"מסורת","input":"choice","options":["Ritual","Tradición","Perspectiva"]}]}','{"items":[{"display":"Regalo","choice":0},{"display":"Declaración","choice":0},{"display":"Alegría","choice":1},{"display":"Recomendación","choice":1},{"display":"Diferencia","choice":1},{"display":"Tradición","choice":1}],"policy":{"accents":"lenient"}}','published','L3-U10-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-04','es3-celebramos-el-amor','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"מנהג = ___","input":"bank"},{"prompt":"עצה = ___","input":"bank"},{"prompt":"חגיגה = ___","input":"bank"},{"prompt":"רגש = ___","input":"bank"}],"wordbank":["Celebración","Consejo","relación","Emoción","Costumbre","pareja"],"text":"Elena espera que su futura {{1}} respete sus proyectos y sepa escuchar. Su familia le recomendó que no se apresurara, y una amiga contó que su hermano había cambiado de ciudad por amor. Elena cree que, si ambos vivieran cerca, podrían construir una {{2}} con más calma."}','{"items":[{"display":"pareja","answers":["pareja"]},{"display":"relación","answers":["relación"]},{"display":"Costumbre","answers":["Costumbre"]},{"display":"Consejo","answers":["Consejo"]},{"display":"Celebración","answers":["Celebración"]},{"display":"Emoción","answers":["Emoción"]}],"policy":{"accents":"strict"}}','published','L3-U10-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-05','es3-celebramos-el-amor','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["importante","es","que","el","amor","Crees","el","qué","dinero","más","Por","que"]},{"prompt":"","input":"tokens","tokens":["romántica","Cuál","es","conoces","celebración","más","ti","para","que","la"]},{"prompt":"","input":"tokens","tokens":["una","alegra","te","situación","relación","Qué","en"]},{"prompt":"","input":"tokens","tokens":["estilo","Cómo","indirecto","contarías","en","lo"]}]}','{"items":[{"display":"¿Crees que el amor es más importante que el dinero? ¿Por qué?","answers":["¿Crees que el amor es más importante que el dinero? ¿Por qué?"]},{"display":"¿Cuál es para ti la celebración más romántica que conoces?","answers":["¿Cuál es para ti la celebración más romántica que conoces?"]},{"display":"¿Qué situación te alegra en una relación?","answers":["¿Qué situación te alegra en una relación?"]},{"display":"¿Cómo lo contarías en estilo indirecto?","answers":["¿Cómo lo contarías en estilo indirecto?"]}],"policy":{"accents":"strict"}}','published','L3-U10-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-06','es3-celebramos-el-amor','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Elena espera que su pareja respeta sus proyectos.","input":"sentence"},{"prompt":"Su familia recomendó que no se apresuró.","input":"sentence"},{"prompt":"Una amiga contó que su hermano ha cambiado de ciudad antes.","input":"sentence"},{"prompt":"Si vivirían cerca, podrían construir una relación.","input":"sentence"}]}','{"items":[{"display":"Elena espera que su pareja respete sus proyectos.","answers":["Elena espera que su pareja respete sus proyectos."]},{"display":"Su familia recomendó que no se apresurara.","answers":["Su familia recomendó que no se apresurara."]},{"display":"Una amiga contó que su hermano había cambiado de ciudad.","answers":["Una amiga contó que su hermano había cambiado de ciudad."]},{"display":"Si vivieran cerca, podrían construir una relación.","answers":["Si vivieran cerca, podrían construir una relación."]}],"policy":{"accents":"strict"}}','published','L3-U10-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-07','es3-celebramos-el-amor','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Elena espera que su pareja respeta sus proyectos.","Elena espera que su pareja respete sus proyectos."]},{"prompt":"","input":"choice","options":["Su familia recomendó que no se apresuró.","Su familia recomendó que no se apresurara."]},{"prompt":"","input":"choice","options":["Una amiga contó que su hermano había cambiado de ciudad.","Una amiga contó que su hermano ha cambiado de ciudad antes."]},{"prompt":"","input":"choice","options":["Si vivirían cerca, podrían construir una relación.","Si vivieran cerca, podrían construir una relación."]}]}','{"items":[{"display":"Elena espera que su pareja respete sus proyectos.","choice":1},{"display":"Su familia recomendó que no se apresurara.","choice":1},{"display":"Una amiga contó que su hermano ha cambiado de ciudad antes.","choice":1},{"display":"Si vivieran cerca, podrían construir una relación.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U10-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-08','es3-celebramos-el-amor','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**la pareja** · respetar · Elena espera que","input":"text"},{"prompt":"**Elena** · apresurarse · su familia recomendó que no","input":"text"},{"prompt":"**el hermano** · cambiar · antes de la conversación","input":"text"},{"prompt":"**ellos** · vivir · si estuvieran cerca","input":"text"}]}','{"items":[{"display":"respete","answers":["respete"]},{"display":"se apresurara","answers":["se apresurara"]},{"display":"había cambiado","answers":["había cambiado"]},{"display":"vivirían","answers":["vivirían"]}],"policy":{"accents":"strict"}}','published','L3-U10-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-09','es3-celebramos-el-amor','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Crees que el amor es más importante que el dinero? ¿Por qué?\n¿Cuál es para ti la celebración más romántica que conoces?\n¿Qué pondrías?\n¿Qué situación te alegra en una relación?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U10-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-10','es3-celebramos-el-amor','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**la pareja** · respetar · Elena espera que","input":"text"},{"prompt":"**Elena** · apresurarse · su familia recomendó que no","input":"text"},{"prompt":"**el hermano** · cambiar · antes de la conversación","input":"text"},{"prompt":"**ellos** · vivir · si estuvieran cerca","input":"text"},{"prompt":"**la relación** · construir · con más tiempo","input":"text"},{"prompt":"**tú** · escuchar · quiero que","input":"text"},{"prompt":"**nosotros** · conocer · hasta ahora","input":"text"},{"prompt":"**ella** · decir · ayer","input":"text"}]}','{"items":[{"display":"respete","answers":["respete"]},{"display":"se apresurara","answers":["se apresurara"]},{"display":"había cambiado","answers":["había cambiado"]},{"display":"vivirían","answers":["vivirían"]},{"display":"podría construirse","answers":["podría construirse"]},{"display":"escuches","answers":["escuches"]},{"display":"nos hemos conocido","answers":["nos hemos conocido"]},{"display":"dijo","answers":["dijo"]}],"policy":{"accents":"strict"}}','published','L3-U10-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-11','es3-celebramos-el-amor','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué espera Elena de su pareja?","input":"sentence"},{"prompt":"¿Qué le recomendó su familia?","input":"sentence"},{"prompt":"¿Qué podrían construir si vivieran cerca?","input":"sentence"}],"text":"Elena espera que su futura pareja respete sus proyectos y sepa escuchar. Su familia le recomendó que no se apresurara, y una amiga contó que su hermano había cambiado de ciudad por amor. Elena cree que, si ambos vivieran cerca, podrían construir una relación con más calma."}','{"items":[{"display":"Que respete sus proyectos y sepa escuchar.","answers":["Que respete sus proyectos y sepa escuchar."]},{"display":"Que no se apresurara.","answers":["Que no se apresurara."]},{"display":"Una relación con más calma.","answers":["Una relación con más calma."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U10-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-12','es3-celebramos-el-amor','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Celebramos el amor\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Elena espera que su futura pareja respete sus proyectos y sepa escuchar. Su familia le recomendó que no se apresurara, y una amiga contó que su hermano había cambiado de ciudad por amor. Elena cree que, si ambos vivieran cerca, podrían construir una relación con más calma."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U10-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-13','es3-celebramos-el-amor','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Qué le recomendó su familia?"},{"id":"B","text":"Pregunta: ¿Qué espera Elena de su pareja?"},{"id":"C","text":"Respuesta: Que no se apresurara."},{"id":"D","text":"Respuesta: Una relación con más calma."},{"id":"E","text":"Respuesta: Que respete sus proyectos y sepa escuchar."},{"id":"F","text":"Pregunta: ¿Qué podrían construir si vivieran cerca?"}]}','{"order":["B","E","A","C","F","D"],"policy":{"accents":"strict"}}','published','L3-U10-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-14','es3-celebramos-el-amor','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Su familia le recomendó que no se apresurara, y una amiga contó que su hermano había cambiado de ciudad por amor."},{"id":"B","text":"Elena espera que su futura pareja respete sus proyectos y sepa escuchar."},{"id":"C","text":"Elena cree que, si ambos vivieran cerca, podrían construir una relación con más calma."}]}','{"order":["B","A","C"],"policy":{"accents":"strict"}}','published','L3-U10-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-15','es3-celebramos-el-amor','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre celebramos el amor es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre celebramos el amor es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U10-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-16','es3-celebramos-el-amor','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"שמחה = ___","input":"text"},{"prompt":"המלצה = ___","input":"text"},{"prompt":"הבדל = ___","input":"text"},{"prompt":"מסורת = ___","input":"text"},{"prompt":"**ella** · decir · ayer","input":"text"},{"prompt":"**nosotros** · conocer · hasta ahora","input":"text"},{"prompt":"**tú** · escuchar · quiero que","input":"text"},{"prompt":"**la relación** · construir · con más tiempo","input":"text"},{"prompt":"**ellos** · vivir · si estuvieran cerca","input":"text"},{"prompt":"**el hermano** · cambiar · antes de la conversación","input":"text"}]}','{"items":[{"display":"Alegría","answers":["Alegría"],"policy":{"accents":"lenient"}},{"display":"Recomendación","answers":["Recomendación"],"policy":{"accents":"lenient"}},{"display":"Diferencia","answers":["Diferencia"],"policy":{"accents":"lenient"}},{"display":"Tradición","answers":["Tradición"],"policy":{"accents":"lenient"}},{"display":"dijo","answers":["dijo"]},{"display":"nos hemos conocido","answers":["nos hemos conocido"]},{"display":"escuches","answers":["escuches"]},{"display":"podría construirse","answers":["podría construirse"]},{"display":"vivirían","answers":["vivirían"]},{"display":"había cambiado","answers":["había cambiado"]}],"policy":{"accents":"strict"}}','published','L3-U10-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-17','es3-celebramos-el-amor','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Elena espera que su futura pareja respete sus proyectos y sepa escuchar. Su familia le recomendó que no se apresurara, y una amiga contó que su hermano había cambiado de ciudad por amor."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U10-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-18','es3-celebramos-el-amor','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"En tu ___, ¿qué costumbre de amor o de pareja es diferente a otras culturas?","input":"bank"},{"prompt":"En tu cultura, ¿qué ___ de amor o de pareja es diferente a otras culturas?","input":"bank"},{"prompt":"Objetivo: practicar el subjuntivo en contextos de emoción, deseo, recomendación y ___.","input":"bank"},{"prompt":"Espero que siempre haya ___.","input":"bank"},{"prompt":"Esto genera ___ y contraste entre deseos de diferentes alumnos.","input":"bank"},{"prompt":"Objetivo: practicar el subjuntivo en contextos de ___, deseo, recomendación y duda.","input":"bank"},{"prompt":"Completa: Quiero que mi ___ … ¿Qué pondrías?","input":"bank"},{"prompt":"חג = ___","input":"bank"},{"prompt":"עצב = ___","input":"bank"},{"prompt":"חיבה = ___","input":"bank"}],"wordbank":["Confianza","Pareja","Tristeza","Festividad","Duda","Costumbre","Discusión","Afecto","Cultura","Emoción"]}','{"items":[{"display":"Cultura","answers":["Cultura"]},{"display":"Costumbre","answers":["Costumbre"]},{"display":"Duda","answers":["Duda"]},{"display":"Confianza","answers":["Confianza"]},{"display":"Discusión","answers":["Discusión"]},{"display":"Emoción","answers":["Emoción"]},{"display":"Pareja","answers":["Pareja"]},{"display":"Festividad","answers":["Festividad"]},{"display":"Tristeza","answers":["Tristeza"]},{"display":"Afecto","answers":["Afecto"]}],"policy":{"accents":"strict"}}','published','L3-U10-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-19','es3-celebramos-el-amor','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Elena espera que la pareja ___ sus proyectos.","input":"text","hint":"respetar"},{"prompt":"Su familia recomendó que Elena no ___.","input":"text","hint":"apresurarse"},{"prompt":"Antes de la conversación, el hermano ___.","input":"text","hint":"cambiar"},{"prompt":"Si estuvieran cerca, ellos ___.","input":"text","hint":"vivir"},{"prompt":"La relación ___ con más tiempo.","input":"text","hint":"construir"},{"prompt":"Quiero que tú ___ con atención.","input":"text","hint":"escuchar"},{"prompt":"Nosotros ___ hasta ahora.","input":"text","hint":"conocer"},{"prompt":"Ayer, ella ___.","input":"text","hint":"decir"}]}','{"items":[{"display":"respete","answers":["respete"]},{"display":"se apresurara","answers":["se apresurara"]},{"display":"había cambiado","answers":["había cambiado"]},{"display":"vivirían","answers":["vivirían"]},{"display":"podría construirse","answers":["podría construirse"]},{"display":"escuches","answers":["escuches"]},{"display":"nos hemos conocido","answers":["nos hemos conocido"]},{"display":"dijo","answers":["dijo"]}],"policy":{"accents":"strict"}}','published','L3-U10-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-celebramos-el-amor-20','es3-celebramos-el-amor','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Qué hacían al principio con sus llamadas?","input":"sentence"},{"prompt":"¿Cuántas noches reservaron para hablar?","input":"sentence"},{"prompt":"¿Qué dejaron de interpretar como falta de interés?","input":"sentence"},{"prompt":"¿Qué desea Eva que haga Martín?","input":"sentence"},{"prompt":"¿Qué harían si uno recibiera una buena oportunidad laboral?","input":"sentence"}],"text":"Eva y Martín vivían en ciudades distintas y al principio improvisaban todas sus llamadas. Con el tiempo comprendieron que necesitaban acuerdos más claros. Reservaron dos noches por semana para hablar sin interrupciones y fijaron una fecha para revisar su plan de futuro. La distancia no desapareció, pero dejaron de interpretar el silencio como falta de interés.\n\nLa pareja espera que la relación mantenga la confianza, el respeto y la intimidad a pesar de la distancia. Eva desea que Martín le comunique sus preocupaciones antes de que se conviertan en una discusión, y él prefiere que ambos protejan también su vida personal. Una amiga les recomendó que no tomaran una decisión por presión y contó que ella había abandonado una relación por falta de compromiso. Eva y Martín sueñan con vivir en la misma ciudad, pero quieren que el cambio sea justo para los dos. Si uno recibiera una buena oportunidad laboral, hablarían primero de sus expectativas y buscarían una solución que cuidara el afecto y la independencia.\n\nCon estos acuerdos, ambos se sienten más tranquilos y pueden expresar cariño sin controlar cada momento del otro. Han comprendido que una relación a distancia necesita compromiso, pero también confianza para que cada persona conserve su propio espacio."}','{"items":[{"display":"Las improvisaban","answers":["Las improvisaban"]},{"display":"Dos noches por semana","answers":["Dos noches por semana"]},{"display":"El silencio","answers":["El silencio"]},{"display":"Que comunique sus preocupaciones","answers":["Que comunique sus preocupaciones"]},{"display":"Hablarían de sus expectativas y buscarían una solución justa","answers":["Hablarían de sus expectativas y buscarían una solución justa"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U10-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas','es-3','es-3-work','יחסי ציבור','Relaciones públicas','לדבר ולכתוב על הנושא „יחסי ציבור“ בספרדית, תוך שימוש במבנים: Comunicación profesional, tiempos mixtos y registro formal.','derived','[{"he":"דקדוק בשימוש","target":"Comunicación profesional, tiempos mixtos y registro formal"},{"he":"אוצר מילים: יחסי ציבור","target":"Relaciones públicas"}]','["Comunicación profesional, tiempos mixtos y registro formal"]','{"rules":[],"examples":["La empresa ha lanzado una campaña.","El comunicado fue escrito con claridad.","Los especialistas fueron invitados a responder.","La directora prometió que actuaría si surgía otro problema."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Borrón y cuenta nueva","he":"לפתוח דף חדש"},{"term":"Campaña","he":"קמפיין"},{"term":"CEO","he":"מנכ״ל"},{"term":"Comunicado","he":"הודעה רשמית"},{"term":"Comunicar","he":"למסור מידע / לתקשר"},{"term":"Confianza","he":"אמון / ביטחון / אמון"},{"term":"Crisis","he":"משבר"},{"term":"Cuidar","he":"לשמור על / לטפל"},{"term":"Cuidar la imagen","he":"לשמור על התדמית"},{"term":"Dar una mano","he":"לעזור / להושיט יד"},{"term":"Decidir","he":"להחליט"},{"term":"Disculpa","he":"התנצלות"},{"term":"Error","he":"טעות"},{"term":"Estrategia","he":"אסטרטגיה"},{"term":"Explicar","he":"להסביר"},{"term":"Imagen","he":"תדמית"},{"term":"Jugar bien sus cartas","he":"לשחק נכון את הקלפים"},{"term":"Justificar","he":"לנמק / להצדיק / להצדיק"},{"term":"Medios","he":"כלי תקשורת"},{"term":"mejorar","he":"להשתפר / לשפר"},{"term":"Mensaje","he":"מסר / הודעה"},{"term":"ONG","he":"עמותה"},{"term":"Portavoz","he":"דובר / דוברת / דובר"},{"term":"Público","he":"קהל"},{"term":"Reaccionar","he":"להגיב"},{"term":"Recuperar","he":"להחזיר / לשקם"},{"term":"Redes sociales","he":"רשתות חברתיות"},{"term":"Relaciones públicas","he":"יחסי ציבור"},{"term":"Responder","he":"להגיב"},{"term":"Robarse el protagonismo","he":"לגנוב את ההצגה"},{"term":"RRPP - )","he":"יח״צ (יחסי ציבור"},{"term":"Tener buena imagen","he":"תדמית טובה"},{"term":"Transmitir","he":"למסור / להעביר"},{"term":"TV","he":"טלוויזיה"},{"term":"Volar bajo el radar","he":"להישאר מתחת לרדאר"},{"term":"Volverse viral","he":"להפוך לוויראלי"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1124113621/relaciones-publicas-flash-cards/?new"}]','published','workbook L3 unit 11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-01','es3-relaciones-publicas','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"לפתוח דף חדש ___","input":"text"},{"prompt":"תדמית ___","input":"text"},{"prompt":"טעות ___","input":"text"},{"prompt":"אסטרטגיה ___","input":"text"},{"prompt":"למסור מידע / לתקשר ___","input":"text"},{"prompt":"לשמור על ___","input":"text"}]}','{"items":[{"display":"Borrón y cuenta nueva","answers":["Borrón y cuenta nueva"]},{"display":"Imagen","answers":["Imagen"]},{"display":"Error","answers":["Error"]},{"display":"Estrategia","answers":["Estrategia"]},{"display":"Comunicar","answers":["Comunicar"]},{"display":"Cuidar","answers":["Cuidar"]}],"policy":{"accents":"lenient"}}','published','L3-U11-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-02','es3-relaciones-publicas','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Borrón y cuenta nueva","Imagen","Error","Estrategia","Comunicar","Cuidar","Confianza","Jugar bien sus cartas"],"right":[{"id":"A","text":"למסור מידע / לתקשר"},{"id":"B","text":"טעות"},{"id":"C","text":"תדמית"},{"id":"D","text":"לשמור על"},{"id":"E","text":"אסטרטגיה"},{"id":"F","text":"לשחק נכון את הקלפים"},{"id":"G","text":"אמון"},{"id":"H","text":"לפתוח דף חדש"}]}','{"pairs":["H","C","B","E","A","D","G","F"],"policy":{"accents":"lenient"}}','published','L3-U11-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-03','es3-relaciones-publicas','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"לפתוח דף חדש","input":"choice","options":["Borrón y cuenta nueva","Responder","Redes sociales"]},{"prompt":"תדמית","input":"choice","options":["Disculpa","Imagen","Estrategia"]},{"prompt":"טעות","input":"choice","options":["Error","Crisis","Dar una mano"]},{"prompt":"אסטרטגיה","input":"choice","options":["Explicar","Estrategia","Responder"]},{"prompt":"למסור מידע / לתקשר","input":"choice","options":["ONG","Medios","Comunicar"]},{"prompt":"לשמור על","input":"choice","options":["Cuidar","RRPP - )","Reaccionar"]}]}','{"items":[{"display":"Borrón y cuenta nueva","choice":0},{"display":"Imagen","choice":1},{"display":"Error","choice":0},{"display":"Estrategia","choice":1},{"display":"Comunicar","choice":2},{"display":"Cuidar","choice":0}],"policy":{"accents":"lenient"}}','published','L3-U11-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-04','es3-relaciones-publicas','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true}],"wordbank":["responder","confianza","recuperar","campaña","público","comunicado"],"text":"La empresa ha lanzado una {{1}} para {{2}} la {{3}} de sus clientes. El {{4}} fue escrito con un tono claro y varios especialistas fueron invitados a {{5}} preguntas. La directora explicó que el {{6}} esperaba transparencia y prometió actuar rápidamente si surgía otro problema."}','{"items":[{"display":"campaña","answers":["campaña"]},{"display":"recuperar","answers":["recuperar"]},{"display":"confianza","answers":["confianza"]},{"display":"comunicado","answers":["comunicado"]},{"display":"responder","answers":["responder"]},{"display":"público","answers":["público"]}],"policy":{"accents":"strict"}}','published','L3-U11-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-05','es3-relaciones-publicas','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["profesionales","Qué","diferencia","te","otros","de"]},{"prompt":"","input":"tokens","tokens":["Qué","clientes","principal","para","tus","resuelves","problema"]},{"prompt":"","input":"tokens","tokens":["problema","cómo","empezó","y","ha","pasado","Qué","el","exactamente"]}]}','{"items":[{"display":"¿Qué te diferencia de otros profesionales?","answers":["¿Qué te diferencia de otros profesionales?"]},{"display":"¿Qué problema principal resuelves para tus clientes?","answers":["¿Qué problema principal resuelves para tus clientes?"]},{"display":"¿Qué ha pasado exactamente y cómo empezó el problema?","answers":["¿Qué ha pasado exactamente y cómo empezó el problema?"]}],"policy":{"accents":"strict"}}','published','L3-U11-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-06','es3-relaciones-publicas','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"La empresa ha lanzó una campaña.","input":"sentence"},{"prompt":"El comunicado fue escribir con claridad.","input":"sentence"},{"prompt":"Los especialistas fueron invitar a responder.","input":"sentence"},{"prompt":"La directora prometió que actuó si surgía otro problema.","input":"sentence"}]}','{"items":[{"display":"La empresa ha lanzado una campaña.","answers":["La empresa ha lanzado una campaña."]},{"display":"El comunicado fue escrito con claridad.","answers":["El comunicado fue escrito con claridad."]},{"display":"Los especialistas fueron invitados a responder.","answers":["Los especialistas fueron invitados a responder."]},{"display":"La directora prometió que actuaría si surgía otro problema.","answers":["La directora prometió que actuaría si surgía otro problema."]}],"policy":{"accents":"strict"}}','published','L3-U11-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-07','es3-relaciones-publicas','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["La empresa ha lanzó una campaña.","La empresa ha lanzado una campaña."]},{"prompt":"","input":"choice","options":["El comunicado fue escrito con claridad.","El comunicado fue escribir con claridad."]},{"prompt":"","input":"choice","options":["Los especialistas fueron invitados a responder.","Los especialistas fueron invitar a responder."]},{"prompt":"","input":"choice","options":["La directora prometió que actuaría si surgía otro problema.","La directora prometió que actuó si surgía otro problema."]}]}','{"items":[{"display":"La empresa ha lanzado una campaña.","choice":1},{"display":"El comunicado fue escribir con claridad.","choice":1},{"display":"Los especialistas fueron invitar a responder.","choice":1},{"display":"La directora prometió que actuó si surgía otro problema.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U11-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-08','es3-relaciones-publicas','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**la empresa** · lanzar · esta semana","input":"text"},{"prompt":"**el comunicado** · escribir · ayer","input":"text"},{"prompt":"**los especialistas** · invitar · antes del evento","input":"text"},{"prompt":"**el público** · esperar · según la directora","input":"text"}]}','{"items":[{"display":"ha lanzado","answers":["ha lanzado"]},{"display":"fue escrito","answers":["fue escrito"]},{"display":"fueron invitados","answers":["fueron invitados"]},{"display":"esperaba","answers":["esperaba"]}],"policy":{"accents":"strict"}}','published','L3-U11-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-09','es3-relaciones-publicas','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Qué te diferencia de otros profesionales?\n¿Qué problema principal resuelves para tus clientes?\n¿Qué ha pasado exactamente y cómo empezó el problema?\n¿Para qué se lanzó la campaña?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U11-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-10','es3-relaciones-publicas','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**la empresa** · lanzar · esta semana","input":"text"},{"prompt":"**el comunicado** · escribir · ayer","input":"text"},{"prompt":"**los especialistas** · invitar · antes del evento","input":"text"},{"prompt":"**el público** · esperar · según la directora","input":"text"},{"prompt":"**otro problema** · surgir · en presente: cuando aparece","input":"text"},{"prompt":"**nosotros** · responder · si surge un problema","input":"text"},{"prompt":"**tú** · mejorar · si recibieras comentarios","input":"text"},{"prompt":"**la estrategia** · evaluar · mañana","input":"text"}]}','{"items":[{"display":"ha lanzado","answers":["ha lanzado"]},{"display":"fue escrito","answers":["fue escrito"]},{"display":"fueron invitados","answers":["fueron invitados"]},{"display":"esperaba","answers":["esperaba"]},{"display":"surge","answers":["surge"]},{"display":"responderemos","answers":["responderemos"]},{"display":"mejorarías","answers":["mejorarías"]},{"display":"será evaluada","answers":["será evaluada"]}],"policy":{"accents":"strict"}}','published','L3-U11-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-11','es3-relaciones-publicas','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Para qué se lanzó la campaña?","input":"sentence"},{"prompt":"¿Quiénes fueron invitados?","input":"sentence"},{"prompt":"¿Qué esperaba el público?","input":"sentence"}],"text":"La empresa ha lanzado una campaña para recuperar la confianza de sus clientes. El comunicado fue escrito con un tono claro y varios especialistas fueron invitados a responder preguntas. La directora explicó que el público esperaba transparencia y prometió actuar rápidamente si surgía otro problema."}','{"items":[{"display":"Para recuperar la confianza de los clientes.","answers":["Para recuperar la confianza de los clientes."]},{"display":"Varios especialistas.","answers":["Varios especialistas."]},{"display":"Transparencia.","answers":["Transparencia."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U11-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-12','es3-relaciones-publicas','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Relaciones públicas\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["La empresa ha lanzado una campaña para recuperar la confianza de sus clientes. El comunicado fue escrito con un tono claro y varios especialistas fueron invitados a responder preguntas. La directora explicó que el público esperaba transparencia y prometió actuar rápidamente si surgía otro problema."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U11-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-13','es3-relaciones-publicas','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: Transparencia."},{"id":"B","text":"Respuesta: Varios especialistas."},{"id":"C","text":"Respuesta: Para recuperar la confianza de los clientes."},{"id":"D","text":"Pregunta: ¿Qué esperaba el público?"},{"id":"E","text":"Pregunta: ¿Para qué se lanzó la campaña?"},{"id":"F","text":"Pregunta: ¿Quiénes fueron invitados?"}]}','{"order":["E","C","F","B","D","A"],"policy":{"accents":"strict"}}','published','L3-U11-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-14','es3-relaciones-publicas','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"La empresa ha lanzado una campaña para recuperar la confianza de sus clientes."},{"id":"B","text":"El comunicado fue escrito con un tono claro y varios especialistas fueron invitados a responder preguntas."},{"id":"C","text":"La directora explicó que el público esperaba transparencia y prometió actuar rápidamente si surgía otro problema."}]}','{"order":["A","B","C"],"policy":{"accents":"strict"}}','published','L3-U11-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-15','es3-relaciones-publicas','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre relaciones públicas es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre relaciones públicas es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U11-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-16','es3-relaciones-publicas','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"טעות = ___","input":"text"},{"prompt":"אסטרטגיה = ___","input":"text"},{"prompt":"למסור מידע / לתקשר = ___","input":"text"},{"prompt":"לשמור על = ___","input":"text"},{"prompt":"**la estrategia** · evaluar · mañana","input":"text"},{"prompt":"**tú** · mejorar · si recibieras comentarios","input":"text"},{"prompt":"**nosotros** · responder · si surge un problema","input":"text"},{"prompt":"**otro problema** · surgir · en presente: cuando aparece","input":"text"},{"prompt":"**el público** · esperar · según la directora","input":"text"},{"prompt":"**los especialistas** · invitar · antes del evento","input":"text"}]}','{"items":[{"display":"Error","answers":["Error"],"policy":{"accents":"lenient"}},{"display":"Estrategia","answers":["Estrategia"],"policy":{"accents":"lenient"}},{"display":"Comunicar","answers":["Comunicar"],"policy":{"accents":"lenient"}},{"display":"Cuidar","answers":["Cuidar"],"policy":{"accents":"lenient"}},{"display":"será evaluada","answers":["será evaluada"]},{"display":"mejorarías","answers":["mejorarías"]},{"display":"responderemos","answers":["responderemos"]},{"display":"surge","answers":["surge"]},{"display":"esperaba","answers":["esperaba"]},{"display":"fueron invitados","answers":["fueron invitados"]}],"policy":{"accents":"strict"}}','published','L3-U11-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-17','es3-relaciones-publicas','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["La empresa ha lanzado una campaña para recuperar la confianza de sus clientes. El comunicado fue escrito con un tono claro y varios especialistas fueron invitados a responder preguntas."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U11-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-18','es3-relaciones-publicas','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"Sé mi periodista y hazme 6 preguntas sobre una ___ pública.","input":"bank"},{"prompt":"Ha habido un error en ___ y la imagen de la empresa se ha visto afectada.","input":"bank"},{"prompt":"Dame una situación (empresa, ___ o persona pública) y un público específico.","input":"bank"},{"prompt":"Quiero escribir un ___ corto de RRPP.","input":"bank"},{"prompt":"Dame una situación (empresa, ONG o persona pública) y un ___ específico.","input":"bank"},{"prompt":"Corrige todo y hazme ___ el texto.","input":"bank"},{"prompt":"Quiero practicar ___.","input":"bank"},{"prompt":"לגנוב את ההצגה = ___","input":"bank"},{"prompt":"דוברת / דובר = ___","input":"bank"},{"prompt":"יח״צ (יחסי ציבור = ___","input":"bank"}],"wordbank":["Portavoz","Mejorar","Relaciones públicas","RRPP - )","ONG","Crisis","Público","Redes sociales","Robarse el protagonismo","Mensaje"]}','{"items":[{"display":"Crisis","answers":["Crisis"]},{"display":"Redes sociales","answers":["Redes sociales"]},{"display":"ONG","answers":["ONG"]},{"display":"Mensaje","answers":["Mensaje"]},{"display":"Público","answers":["Público"]},{"display":"Mejorar","answers":["Mejorar"]},{"display":"Relaciones públicas","answers":["Relaciones públicas"]},{"display":"Robarse el protagonismo","answers":["Robarse el protagonismo"]},{"display":"Portavoz","answers":["Portavoz"]},{"display":"RRPP - )","answers":["RRPP - )"]}],"policy":{"accents":"strict"}}','published','L3-U11-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-19','es3-relaciones-publicas','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Esta semana, la empresa ___.","input":"text","hint":"lanzar"},{"prompt":"Ayer, el comunicado ___.","input":"text","hint":"escribir"},{"prompt":"Antes del evento, los especialistas ___.","input":"text","hint":"invitar"},{"prompt":"El público ___ según la directora.","input":"text","hint":"esperar"},{"prompt":"Cuando aparece, otro problema ___ de repente.","input":"text","hint":"surgir"},{"prompt":"Si surge un problema, nosotros ___.","input":"text","hint":"responder"},{"prompt":"Si recibieras comentarios, tú ___.","input":"text","hint":"mejorar"},{"prompt":"Mañana, la estrategia ___.","input":"text","hint":"evaluar"}]}','{"items":[{"display":"ha lanzado","answers":["ha lanzado"]},{"display":"fue escrito","answers":["fue escrito"]},{"display":"fueron invitados","answers":["fueron invitados"]},{"display":"esperaba","answers":["esperaba"]},{"display":"surge","answers":["surge"]},{"display":"responderemos","answers":["responderemos"]},{"display":"mejorarías","answers":["mejorarías"]},{"display":"será evaluada","answers":["será evaluada"]}],"policy":{"accents":"strict"}}','published','L3-U11-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-relaciones-publicas-20','es3-relaciones-publicas','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Por qué recibió críticas el restaurante?","input":"sentence"},{"prompt":"¿Qué reconoció la directora?","input":"sentence"},{"prompt":"¿Qué creó para los mensajes futuros?","input":"sentence"},{"prompt":"¿Para qué se preparó la estrategia?","input":"sentence"},{"prompt":"¿Qué habría ocurrido si la empresa hubiera negado la crisis?","input":"sentence"}],"text":"Un restaurante recibió críticas después de comunicar mal un cambio en su menú. La directora publicó una explicación clara, respondió preguntas y reconoció que el aviso anterior había sido confuso. También creó un protocolo para revisar futuros mensajes antes de difundirlos. La confianza no se recuperó de inmediato, pero los clientes valoraron que la empresa asumiera su responsabilidad.\n\nEl equipo de relaciones públicas analizó la imagen de la marca y preparó una estrategia para recuperar la confianza del público. En un comunicado formal, la portavoz afirmó que las normas internas habían sido actualizadas y que todos los empleados recibirían formación. Los medios solicitaron más detalles, por lo que se organizó una rueda de prensa. Si la empresa hubiera negado la crisis, el mensaje habría parecido poco creíble y la campaña habría fracasado. En cambio, la directora mantuvo un registro transparente, respondió a los comentarios en las redes sociales y prometió publicar los resultados de la revisión. La reputación tardó en mejorar, pero la comunicación profesional evitó un daño mayor.\n\nMeses después, la empresa incorporó el protocolo a todas sus campañas. Cada mensaje importante debe ser aprobado por dos personas y adaptado al canal correspondiente. La crisis se convirtió así en una oportunidad para mejorar la estrategia de comunicación."}','{"items":[{"display":"Porque comunicó mal un cambio en su menú","answers":["Porque comunicó mal un cambio en su menú"]},{"display":"Que el aviso anterior había sido confuso","answers":["Que el aviso anterior había sido confuso"]},{"display":"Un protocolo de revisión","answers":["Un protocolo de revisión"]},{"display":"Para recuperar la confianza del público","answers":["Para recuperar la confianza del público"]},{"display":"El mensaje habría parecido poco creíble y la campaña habría fracasado","answers":["El mensaje habría parecido poco creíble y la campaña habría fracasado"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U11-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion','es-3','es-3-people','מיינדפולנס ורגיעה','Mindfulness y relajación','לדבר ולכתוב על הנושא „מיינדפולנס ורגיעה“ בספרדית, תוך שימוש במבנים: Pasado, presente, futuro y condicional.','derived','[{"he":"דקדוק בשימוש","target":"Pasado, presente, futuro y condicional"},{"he":"אוצר מילים: מיינדפולנס ורגיעה","target":"Mindfulness y relajación"}]','["Pasado, presente, futuro y condicional"]','{"rules":[],"examples":["Maya ha practicado mindfulness durante seis meses.","Antes de empezar, ya había probado varias aplicaciones.","Mañana hará una sesión más larga.","Si lo hubiera descubierto antes, habría cuidado mejor su descanso."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Ansiedad","he":"חרדה"},{"term":"Aroma","he":"ניחוח"},{"term":"Bienestar","he":"רווחה"},{"term":"Bosque","he":"יער"},{"term":"Calma","he":"רוגע"},{"term":"Ciudad","he":"עיר"},{"term":"Concentración","he":"ריכוז"},{"term":"Condicional","he":"משפט תנאי / תנאי / מותנה"},{"term":"Cuerpo","he":"גוף"},{"term":"Descansar","he":"לנוח"},{"term":"Desconectarse","he":"להתנתק"},{"term":"Emoción","he":"רגש"},{"term":"Energía","he":"אנרגיה"},{"term":"Equilibrio","he":"איזון"},{"term":"Estrés","he":"לחץ / סטרס / לחץ"},{"term":"Futuro","he":"עתיד"},{"term":"Gusto","he":"טעם"},{"term":"Hábito","he":"הרגל"},{"term":"Imaginación","he":"דמיון"},{"term":"Meditar","he":"למדוט"},{"term":"Mente","he":"תודעה / מחשבה"},{"term":"Montaña","he":"הר"},{"term":"Naturaleza","he":"טבע"},{"term":"Oído","he":"שמיעה"},{"term":"Olfato","he":"ריח"},{"term":"Paisaje","he":"נוף"},{"term":"Playa","he":"חוף ים"},{"term":"Respiración","he":"נשימה"},{"term":"Respirar","he":"לנשום"},{"term":"Retiro","he":"פרישה / ריטריט"},{"term":"Ruido","he":"רעש"},{"term":"Serenidad","he":"שלווה"},{"term":"Silencio","he":"שקט"},{"term":"Sueño","he":"שינה"},{"term":"Tacto","he":"מגע"},{"term":"Taller","he":"סדנה"},{"term":"Tensión","he":"מתח"},{"term":"Vista","he":"ראייה"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/860753650/extreme-spanish-mindfulness-flash-cards/"}]','published','workbook L3 unit 12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-01','es3-mindfulness-y-relajacion','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"טעם ___","input":"text"},{"prompt":"דמיון ___","input":"text"},{"prompt":"מתח ___","input":"text"},{"prompt":"מגע ___","input":"text"},{"prompt":"רעש ___","input":"text"},{"prompt":"טבע ___","input":"text"}]}','{"items":[{"display":"Gusto","answers":["Gusto"]},{"display":"Imaginación","answers":["Imaginación"]},{"display":"Tensión","answers":["Tensión"]},{"display":"Tacto","answers":["Tacto"]},{"display":"Ruido","answers":["Ruido"]},{"display":"Naturaleza","answers":["Naturaleza"]}],"policy":{"accents":"lenient"}}','published','L3-U12-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-02','es3-mindfulness-y-relajacion','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Gusto","Imaginación","Tensión","Tacto","Ruido","Naturaleza","Sueño","Calma"],"right":[{"id":"A","text":"מגע"},{"id":"B","text":"טבע"},{"id":"C","text":"רעש"},{"id":"D","text":"דמיון"},{"id":"E","text":"טעם"},{"id":"F","text":"שינה"},{"id":"G","text":"רוגע"},{"id":"H","text":"מתח"}]}','{"pairs":["E","D","H","A","C","B","F","G"],"policy":{"accents":"lenient"}}','published','L3-U12-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-03','es3-mindfulness-y-relajacion','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"טעם","input":"choice","options":["Desconectarse","Gusto","Retiro"]},{"prompt":"דמיון","input":"choice","options":["Desconectarse","Imaginación","Paisaje"]},{"prompt":"מתח","input":"choice","options":["Tensión","Tacto","Descansar"]},{"prompt":"מגע","input":"choice","options":["Cuerpo","Tacto","Energía"]},{"prompt":"רעש","input":"choice","options":["Olfato","Tacto","Ruido"]},{"prompt":"טבע","input":"choice","options":["Equilibrio","Naturaleza","Olfato"]}]}','{"items":[{"display":"Gusto","choice":1},{"display":"Imaginación","choice":1},{"display":"Tensión","choice":0},{"display":"Tacto","choice":1},{"display":"Ruido","choice":2},{"display":"Naturaleza","choice":1}],"policy":{"accents":"lenient"}}','published','L3-U12-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-04','es3-mindfulness-y-relajacion','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"ניחוח = ___","input":"bank"},{"prompt":"רוגע = ___","input":"bank"},{"prompt":"טבע = ___","input":"bank"},{"prompt":"שקט = ___","input":"bank"},{"prompt":"ריכוז = ___","input":"bank"},{"prompt":"לחץ / סטרס = ___","input":"bank"}],"wordbank":["Calma","Naturaleza","Estrés","Aroma","Silencio","Concentración"],"text":"Maya ha practicado mindfulness durante seis meses. Antes de empezar, dormía mal y ya había probado varias aplicaciones sin éxito. Ahora medita cada mañana, mañana hará una sesión más larga y piensa que, si hubiera descubierto esta práctica antes, habría cuidado mejor su descanso."}','{"items":[{"display":"Aroma","answers":["Aroma"]},{"display":"Calma","answers":["Calma"]},{"display":"Naturaleza","answers":["Naturaleza"]},{"display":"Silencio","answers":["Silencio"]},{"display":"Concentración","answers":["Concentración"]},{"display":"Estrés","answers":["Estrés"]}],"policy":{"accents":"strict"}}','published','L3-U12-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-05','es3-mindfulness-y-relajacion','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["haces","Qué","relajarte","necesitas","normalmente","cuando"]},{"prompt":"","input":"tokens","tokens":["calma","qué","la","o","ciudad","transmite","Qué","la","más","naturaleza","Por","te","lugar"]},{"prompt":"","input":"tokens","tokens":["tiene","acompañado","relajarte","cada","opción","solo","Prefieres","ventajas","o","Qué"]},{"prompt":"","input":"tokens","tokens":["redes","tu","papel","las","Qué","nivel","juegan","estrés","de","en","sociales"]}]}','{"items":[{"display":"¿Qué haces normalmente cuando necesitas relajarte?","answers":["¿Qué haces normalmente cuando necesitas relajarte?"]},{"display":"¿Qué lugar te transmite más calma: la ciudad o la naturaleza? ¿Por qué?","answers":["¿Qué lugar te transmite más calma: la ciudad o la naturaleza? ¿Por qué?"]},{"display":"¿Prefieres relajarte solo o acompañado? ¿Qué ventajas tiene cada opción?","answers":["¿Prefieres relajarte solo o acompañado? ¿Qué ventajas tiene cada opción?"]},{"display":"¿Qué papel juegan las redes sociales en tu nivel de estrés?","answers":["¿Qué papel juegan las redes sociales en tu nivel de estrés?"]}],"policy":{"accents":"strict"}}','published','L3-U12-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-06','es3-mindfulness-y-relajacion','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Maya ha practicó mindfulness durante seis meses.","input":"sentence"},{"prompt":"Antes de empezar, ha probado ya varias aplicaciones.","input":"sentence"},{"prompt":"Mañana hizo una sesión más larga.","input":"sentence"},{"prompt":"Si lo hubiera descubierto antes, cuidaría mejor su descanso entonces.","input":"sentence"}]}','{"items":[{"display":"Maya ha practicado mindfulness durante seis meses.","answers":["Maya ha practicado mindfulness durante seis meses."]},{"display":"Antes de empezar, ya había probado varias aplicaciones.","answers":["Antes de empezar, ya había probado varias aplicaciones."]},{"display":"Mañana hará una sesión más larga.","answers":["Mañana hará una sesión más larga."]},{"display":"Si lo hubiera descubierto antes, habría cuidado mejor su descanso.","answers":["Si lo hubiera descubierto antes, habría cuidado mejor su descanso."]}],"policy":{"accents":"strict"}}','published','L3-U12-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-07','es3-mindfulness-y-relajacion','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Maya ha practicado mindfulness durante seis meses.","Maya ha practicó mindfulness durante seis meses."]},{"prompt":"","input":"choice","options":["Antes de empezar, ha probado ya varias aplicaciones.","Antes de empezar, ya había probado varias aplicaciones."]},{"prompt":"","input":"choice","options":["Mañana hará una sesión más larga.","Mañana hizo una sesión más larga."]},{"prompt":"","input":"choice","options":["Si lo hubiera descubierto antes, cuidaría mejor su descanso entonces.","Si lo hubiera descubierto antes, habría cuidado mejor su descanso."]}]}','{"items":[{"display":"Maya ha practicó mindfulness durante seis meses.","choice":1},{"display":"Antes de empezar, ya había probado varias aplicaciones.","choice":1},{"display":"Mañana hizo una sesión más larga.","choice":1},{"display":"Si lo hubiera descubierto antes, habría cuidado mejor su descanso.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U12-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-08','es3-mindfulness-y-relajacion','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**Maya** · practicar · durante seis meses","input":"text"},{"prompt":"**ella** · probar · antes de empezar","input":"text"},{"prompt":"**Maya** · meditar · cada mañana","input":"text"},{"prompt":"**ella** · hacer · mañana","input":"text"}]}','{"items":[{"display":"ha practicado","answers":["ha practicado"]},{"display":"había probado","answers":["había probado"]},{"display":"medita","answers":["medita"]},{"display":"hará","answers":["hará"]}],"policy":{"accents":"strict"}}','published','L3-U12-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-09','es3-mindfulness-y-relajacion','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Qué haces normalmente cuando necesitas relajarte?\n¿Qué lugar te transmite más calma: la ciudad o la naturaleza? ¿Por qué?\n¿Prefieres relajarte solo o acompañado? ¿Qué ventajas tiene cada opción?\n¿Qué papel juegan las redes sociales en tu nivel de estrés?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U12-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-10','es3-mindfulness-y-relajacion','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**Maya** · practicar · durante seis meses","input":"text"},{"prompt":"**ella** · probar · antes de empezar","input":"text"},{"prompt":"**Maya** · meditar · cada mañana","input":"text"},{"prompt":"**ella** · hacer · mañana","input":"text"},{"prompt":"**yo** · descubrir · en una hipótesis del pasado","input":"text"},{"prompt":"**yo** · empezar · si hubiera tenido tiempo","input":"text"},{"prompt":"**nosotros** · sentirse · después de la sesión","input":"text"},{"prompt":"**tú** · respirar · cuando estás nervioso","input":"text"}]}','{"items":[{"display":"ha practicado","answers":["ha practicado"]},{"display":"había probado","answers":["había probado"]},{"display":"medita","answers":["medita"]},{"display":"hará","answers":["hará"]},{"display":"hubiera descubierto","answers":["hubiera descubierto"]},{"display":"habría empezado","answers":["habría empezado"]},{"display":"nos sentimos","answers":["nos sentimos"]},{"display":"respiras","answers":["respiras"]}],"policy":{"accents":"strict"}}','published','L3-U12-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-11','es3-mindfulness-y-relajacion','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Cuánto tiempo ha practicado Maya?","input":"sentence"},{"prompt":"¿Qué había probado antes?","input":"sentence"},{"prompt":"¿Qué hará mañana?","input":"sentence"}],"text":"Maya ha practicado mindfulness durante seis meses. Antes de empezar, dormía mal y ya había probado varias aplicaciones sin éxito. Ahora medita cada mañana, mañana hará una sesión más larga y piensa que, si hubiera descubierto esta práctica antes, habría cuidado mejor su descanso."}','{"items":[{"display":"Durante seis meses.","answers":["Durante seis meses."]},{"display":"Varias aplicaciones.","answers":["Varias aplicaciones."]},{"display":"Hará una sesión más larga.","answers":["Hará una sesión más larga."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U12-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-12','es3-mindfulness-y-relajacion','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Mindfulness y relajación\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Maya ha practicado mindfulness durante seis meses. Antes de empezar, dormía mal y ya había probado varias aplicaciones sin éxito. Ahora medita cada mañana, mañana hará una sesión más larga y piensa que, si hubiera descubierto esta práctica antes, habría cuidado mejor su descanso."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U12-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-13','es3-mindfulness-y-relajacion','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Qué había probado antes?"},{"id":"B","text":"Respuesta: Durante seis meses."},{"id":"C","text":"Respuesta: Hará una sesión más larga."},{"id":"D","text":"Pregunta: ¿Cuánto tiempo ha practicado Maya?"},{"id":"E","text":"Pregunta: ¿Qué hará mañana?"},{"id":"F","text":"Respuesta: Varias aplicaciones."}]}','{"order":["D","B","A","F","E","C"],"policy":{"accents":"strict"}}','published','L3-U12-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-14','es3-mindfulness-y-relajacion','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Ahora medita cada mañana, mañana hará una sesión más larga y piensa que, si hubiera descubierto esta práctica antes, habría cuidado mejor su descanso."},{"id":"B","text":"Antes de empezar, dormía mal y ya había probado varias aplicaciones sin éxito."},{"id":"C","text":"Maya ha practicado mindfulness durante seis meses."}]}','{"order":["C","B","A"],"policy":{"accents":"strict"}}','published','L3-U12-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-15','es3-mindfulness-y-relajacion','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre mindfulness y relajación es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre mindfulness y relajación es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U12-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-16','es3-mindfulness-y-relajacion','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"מתח = ___","input":"text"},{"prompt":"מגע = ___","input":"text"},{"prompt":"רעש = ___","input":"text"},{"prompt":"טבע = ___","input":"text"},{"prompt":"**tú** · respirar · cuando estás nervioso","input":"text"},{"prompt":"**nosotros** · sentirse · después de la sesión","input":"text"},{"prompt":"**yo** · empezar · si hubiera tenido tiempo","input":"text"},{"prompt":"**yo** · descubrir · en una hipótesis del pasado","input":"text"},{"prompt":"**ella** · hacer · mañana","input":"text"},{"prompt":"**Maya** · meditar · cada mañana","input":"text"}]}','{"items":[{"display":"Tensión","answers":["Tensión"],"policy":{"accents":"lenient"}},{"display":"Tacto","answers":["Tacto"],"policy":{"accents":"lenient"}},{"display":"Ruido","answers":["Ruido"],"policy":{"accents":"lenient"}},{"display":"Naturaleza","answers":["Naturaleza"],"policy":{"accents":"lenient"}},{"display":"respiras","answers":["respiras"]},{"display":"nos sentimos","answers":["nos sentimos"]},{"display":"habría empezado","answers":["habría empezado"]},{"display":"hubiera descubierto","answers":["hubiera descubierto"]},{"display":"hará","answers":["hará"]},{"display":"medita","answers":["medita"]}],"policy":{"accents":"strict"}}','published','L3-U12-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-17','es3-mindfulness-y-relajacion','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Maya ha practicado mindfulness durante seis meses. Antes de empezar, dormía mal y ya había probado varias aplicaciones sin éxito."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U12-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-18','es3-mindfulness-y-relajacion','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"¿Qué lugar te transmite más calma: la ___ o la naturaleza? ¿Por qué?","input":"bank"},{"prompt":"Usar vocabulario de emociones, acciones, ambientes y ___ /mente.","input":"bank"},{"prompt":"Fomentar descripción sensorial (vista, ___, olfato, tacto, gusto).","input":"bank"},{"prompt":"Fomentar descripción sensorial (vista, oído, ___, tacto, gusto).","input":"bank"},{"prompt":"Pasado: “El verano pasado estuve en una playa y sentí ___ en mis músculos.”","input":"bank"},{"prompt":"Fomentar descripción sensorial (___, oído, olfato, tacto, gusto).","input":"bank"},{"prompt":"“Hoy me concentro en ___ para liberar tensión.”","input":"bank"},{"prompt":"“Si pudiera ___ todos los días, tendría más serenidad.”","input":"bank"},{"prompt":"Usar el segundo ___ para situaciones hipotéticas.","input":"bank"},{"prompt":"“Soy Ana. Si pudiera estar ahora en un lugar relajante, estaría en la ___.”","input":"bank"}],"wordbank":["Olfato","Respirar","Meditar","Oído","Cuerpo","Vista","Serenidad","Playa","Condicional","Ciudad"]}','{"items":[{"display":"Ciudad","answers":["Ciudad"]},{"display":"Cuerpo","answers":["Cuerpo"]},{"display":"Oído","answers":["Oído"]},{"display":"Olfato","answers":["Olfato"]},{"display":"Serenidad","answers":["Serenidad"]},{"display":"Vista","answers":["Vista"]},{"display":"Respirar","answers":["Respirar"]},{"display":"Meditar","answers":["Meditar"]},{"display":"Condicional","answers":["Condicional"]},{"display":"Playa","answers":["Playa"]}],"policy":{"accents":"strict"}}','published','L3-U12-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-19','es3-mindfulness-y-relajacion','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Maya ___ durante seis meses.","input":"text","hint":"practicar"},{"prompt":"Antes de empezar, ella ___.","input":"text","hint":"probar"},{"prompt":"Maya ___ cada mañana.","input":"text","hint":"meditar"},{"prompt":"Mañana, ella ___.","input":"text","hint":"hacer"},{"prompt":"En aquella hipótesis, yo ___ la respuesta antes.","input":"text","hint":"descubrir"},{"prompt":"Si hubiera tenido tiempo, yo ___.","input":"text","hint":"empezar"},{"prompt":"Nosotros ___ después de la sesión.","input":"text","hint":"sentirse"},{"prompt":"Tú ___ cuando estás nervioso.","input":"text","hint":"respirar"}]}','{"items":[{"display":"ha practicado","answers":["ha practicado"]},{"display":"había probado","answers":["había probado"]},{"display":"medita","answers":["medita"]},{"display":"hará","answers":["hará"]},{"display":"hubiera descubierto","answers":["hubiera descubierto"]},{"display":"habría empezado","answers":["habría empezado"]},{"display":"nos sentimos","answers":["nos sentimos"]},{"display":"respiras","answers":["respiras"]}],"policy":{"accents":"strict"}}','published','L3-U12-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-mindfulness-y-relajacion-20','es3-mindfulness-y-relajacion','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Cuánto duraba el silencio?","input":"sentence"},{"prompt":"¿Cuánto tiempo probaron la práctica?","input":"sentence"},{"prompt":"¿Cómo quedó la práctica al final?","input":"sentence"},{"prompt":"¿Qué hacen ahora para recuperar la concentración?","input":"sentence"},{"prompt":"¿Qué ofrecerán en el futuro?","input":"sentence"}],"text":"Una empresa propuso cinco minutos de silencio sin teléfonos al comenzar la jornada. Algunos empleados pensaron que sería una pérdida de tiempo, pero aceptaron probarlo durante dos semanas. Al final del experimento, la mayoría dijo que empezaba el día con menos tensión. El equipo decidió mantener la práctica, aunque de forma voluntaria.\n\nAntes del experimento, varios empleados habían intentado meditar con una aplicación, pero se distraían con los mensajes. Ahora practican una respiración lenta, observan la tensión del cuerpo y vuelven a la tarea con más concentración. La próxima semana evaluarán si la pausa también influye en la energía de la tarde. Si yo trabajara en esa oficina, participaría algunos días, aunque necesitaría un espacio tranquilo. La responsable de bienestar recuerda que la serenidad no aparece de inmediato y que descansar no significa evitar las responsabilidades. En el futuro ofrecerán sesiones más largas, pero nadie estará obligado a asistir: cada persona podrá elegir la técnica que le ayude a desconectarse y reducir la ansiedad.\n\nLos empleados no afirman que la práctica resuelva todos sus problemas. Sin embargo, han aprendido a reconocer cuándo necesitan parar, respirar o descansar. Esa conciencia les permite cuidar el bienestar antes de que la tensión se transforme en agotamiento."}','{"items":[{"display":"Cinco minutos","answers":["Cinco minutos"]},{"display":"Dos semanas","answers":["Dos semanas"]},{"display":"De forma voluntaria","answers":["De forma voluntaria"]},{"display":"Practican una respiración lenta y observan la tensión del cuerpo","answers":["Practican una respiración lenta y observan la tensión del cuerpo"]},{"display":"Sesiones más largas","answers":["Sesiones más largas"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U12-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad','es-3','es-3-society','קיימות','Sustentabilidad','לדבר ולכתוב על הנושא „קיימות“ בספרדית, תוך שימוש במבנים: Condicionales, recomendaciones y persuasión formal.','derived','[{"he":"דקדוק בשימוש","target":"Condicionales, recomendaciones y persuasión formal"},{"he":"אוצר מילים: קיימות","target":"Sustentabilidad"}]','["Condicionales, recomendaciones y persuasión formal"]','{"rules":[],"examples":["Se han instalado nuevos puntos de reciclaje.","Si los residentes separaran los residuos, habría menos basura.","Los expertos recomiendan que el gobierno invierta.","La ciudad ha reducido el plástico."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Agua","he":"מים"},{"term":"Aire limpio","he":"אוויר נקי"},{"term":"Árboles","he":"עצים"},{"term":"Basura","he":"אשפה"},{"term":"Biodiversidad","he":"מגוון ביולוגי"},{"term":"Bosque","he":"יער"},{"term":"Cambio climático","he":"שינוי אקלים"},{"term":"Campaña","he":"קמפיין"},{"term":"Campo","he":"כפר"},{"term":"Carta","he":"מכתב"},{"term":"Ciudad","he":"עיר"},{"term":"Ciudadanos","he":"אזרחים"},{"term":"Conservar","he":"לשמר"},{"term":"Contaminación","he":"זיהום"},{"term":"Cuidar","he":"לשמור על / לטפל"},{"term":"Deberíamos","he":"היינו צריכים"},{"term":"Energía","he":"אנרגיה"},{"term":"Eslogan","he":"סיסמה"},{"term":"Futuro","he":"עתיד"},{"term":"Gobierno","he":"ממשלה"},{"term":"Hábitos","he":"הרגלים"},{"term":"Haríamos","he":"היינו עושים"},{"term":"Medio ambiente","he":"סביבה"},{"term":"mejorar","he":"להשתפר / לשפר"},{"term":"Naturaleza","he":"טבע"},{"term":"Plantar","he":"לשתול"},{"term":"Podríamos","he":"היינו יכולים"},{"term":"Político","he":"פוליטיקאי"},{"term":"Propuesta","he":"הצעה"},{"term":"Proteger","he":"להגן"},{"term":"Reciclaje","he":"מיחזור"},{"term":"Reciclar","he":"למחזר"},{"term":"Recursos","he":"משאבים"},{"term":"Reducir","he":"להפחית"},{"term":"Reutilizar","he":"להשתמש מחדש / לעשות שימוש חוזר"},{"term":"Sustentabilidad","he":"קיימות"},{"term":"Tierra","he":"אדמה"},{"term":"Transporte público","he":"תחבורה ציבורית"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/859133355/extreme-spanish-sustainability-flash-cards/"}]','published','workbook L3 unit 13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-01','es3-sustentabilidad','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"אנרגיה ___","input":"text"},{"prompt":"מיחזור ___","input":"text"},{"prompt":"מכתב ___","input":"text"},{"prompt":"אשפה ___","input":"text"},{"prompt":"עתיד ___","input":"text"},{"prompt":"אדמה ___","input":"text"}]}','{"items":[{"display":"Energía","answers":["Energía"]},{"display":"Reciclaje","answers":["Reciclaje"]},{"display":"Carta","answers":["Carta"]},{"display":"Basura","answers":["Basura"]},{"display":"Futuro","answers":["Futuro"]},{"display":"Tierra","answers":["Tierra"]}],"policy":{"accents":"lenient"}}','published','L3-U13-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-02','es3-sustentabilidad','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Energía","Reciclaje","Carta","Basura","Futuro","Tierra","Agua","Propuesta"],"right":[{"id":"A","text":"עתיד"},{"id":"B","text":"אנרגיה"},{"id":"C","text":"מים"},{"id":"D","text":"מיחזור"},{"id":"E","text":"אשפה"},{"id":"F","text":"הצעה"},{"id":"G","text":"אדמה"},{"id":"H","text":"מכתב"}]}','{"pairs":["B","D","H","E","A","G","C","F"],"policy":{"accents":"lenient"}}','published','L3-U13-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-03','es3-sustentabilidad','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"אנרגיה","input":"choice","options":["Energía","Mejorar","Reciclaje"]},{"prompt":"מיחזור","input":"choice","options":["Naturaleza","Reciclaje","Energía"]},{"prompt":"מכתב","input":"choice","options":["Energía","Carta","Proteger"]},{"prompt":"אשפה","input":"choice","options":["Transporte público","Propuesta","Basura"]},{"prompt":"עתיד","input":"choice","options":["Futuro","Carta","Conservar"]},{"prompt":"אדמה","input":"choice","options":["Futuro","Tierra","Cambio climático"]}]}','{"items":[{"display":"Energía","choice":0},{"display":"Reciclaje","choice":1},{"display":"Carta","choice":1},{"display":"Basura","choice":2},{"display":"Futuro","choice":0},{"display":"Tierra","choice":1}],"policy":{"accents":"lenient"}}','published','L3-U13-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-04','es3-sustentabilidad','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"היינו צריכים = ___","input":"bank"},{"prompt":"מגוון ביולוגי = ___","input":"bank"}],"wordbank":["gobierno","Deberíamos","basura","Biodiversidad","ciudad","reciclaje"],"text":"La {{1}} ha reducido el uso de plástico y se han instalado nuevos puntos de {{2}}. Si los residentes separaran todos sus residuos, el vertedero recibiría mucha menos {{3}}. Los expertos recomiendan que el {{4}} invierta en transporte limpio y que informe mejor a la población."}','{"items":[{"display":"ciudad","answers":["ciudad"]},{"display":"reciclaje","answers":["reciclaje"]},{"display":"basura","answers":["basura"]},{"display":"gobierno","answers":["gobierno"]},{"display":"Deberíamos","answers":["Deberíamos"]},{"display":"Biodiversidad","answers":["Biodiversidad"]}],"policy":{"accents":"strict"}}','published','L3-U13-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-05','es3-sustentabilidad','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["para","ambiente","podrías","Qué","tú","hacer","medio","proteger","el"]},{"prompt":"","input":"tokens","tokens":["en","campo","o","ciudad","la","en","el","Vivirías"]},{"prompt":"","input":"tokens","tokens":["Cómo","podríamos","proteger","ambiente","mejor","al","medio"]},{"prompt":"","input":"tokens","tokens":["al","podrías","respecto","tú","hacer","Hay","que","algo"]}]}','{"items":[{"display":"¿Qué podrías hacer tú para proteger el medio ambiente?","answers":["¿Qué podrías hacer tú para proteger el medio ambiente?"]},{"display":"¿Vivirías en el campo o en la ciudad?","answers":["¿Vivirías en el campo o en la ciudad?"]},{"display":"¿Cómo podríamos proteger mejor al medio ambiente?","answers":["¿Cómo podríamos proteger mejor al medio ambiente?"]},{"display":"¿Hay algo que tú podrías hacer al respecto?","answers":["¿Hay algo que tú podrías hacer al respecto?"]}],"policy":{"accents":"strict"}}','published','L3-U13-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-06','es3-sustentabilidad','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Se han instalar nuevos puntos de reciclaje.","input":"sentence"},{"prompt":"Si los residentes separarían los residuos, habría menos basura.","input":"sentence"},{"prompt":"Los expertos recomiendan que el gobierno invierte.","input":"sentence"},{"prompt":"La ciudad ha reducida el plástico.","input":"sentence"}]}','{"items":[{"display":"Se han instalado nuevos puntos de reciclaje.","answers":["Se han instalado nuevos puntos de reciclaje."]},{"display":"Si los residentes separaran los residuos, habría menos basura.","answers":["Si los residentes separaran los residuos, habría menos basura."]},{"display":"Los expertos recomiendan que el gobierno invierta.","answers":["Los expertos recomiendan que el gobierno invierta."]},{"display":"La ciudad ha reducido el plástico.","answers":["La ciudad ha reducido el plástico."]}],"policy":{"accents":"strict"}}','published','L3-U13-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-07','es3-sustentabilidad','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Se han instalar nuevos puntos de reciclaje.","Se han instalado nuevos puntos de reciclaje."]},{"prompt":"","input":"choice","options":["Si los residentes separaran los residuos, habría menos basura.","Si los residentes separarían los residuos, habría menos basura."]},{"prompt":"","input":"choice","options":["Los expertos recomiendan que el gobierno invierta.","Los expertos recomiendan que el gobierno invierte."]},{"prompt":"","input":"choice","options":["La ciudad ha reducido el plástico.","La ciudad ha reducida el plástico."]}]}','{"items":[{"display":"Se han instalado nuevos puntos de reciclaje.","choice":1},{"display":"Si los residentes separarían los residuos, habría menos basura.","choice":1},{"display":"Los expertos recomiendan que el gobierno invierte.","choice":1},{"display":"La ciudad ha reducida el plástico.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U13-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-08','es3-sustentabilidad','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**la ciudad** · reducir · este año","input":"text"},{"prompt":"**los puntos** · instalar · recientemente","input":"text"},{"prompt":"**los residentes** · separar · después de «si» en una condición hipotética","input":"text"},{"prompt":"**el vertedero** · recibir · con más reciclaje","input":"text"}]}','{"items":[{"display":"ha reducido","answers":["ha reducido"]},{"display":"han sido instalados","answers":["han sido instalados"]},{"display":"separaran","answers":["separaran"]},{"display":"recibiría","answers":["recibiría"]}],"policy":{"accents":"strict"}}','published','L3-U13-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-09','es3-sustentabilidad','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Qué podrías hacer tú para proteger el medio ambiente?\n¿Vivirías en el campo o en la ciudad?\n¿Cómo podríamos proteger mejor al medio ambiente?\n¿Hay algo que tú podrías hacer al respecto?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U13-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-10','es3-sustentabilidad','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**la ciudad** · reducir · este año","input":"text"},{"prompt":"**los puntos** · instalar · recientemente","input":"text"},{"prompt":"**los residentes** · separar · después de «si» en una condición hipotética","input":"text"},{"prompt":"**el vertedero** · recibir · con más reciclaje","input":"text"},{"prompt":"**el gobierno** · invertir · los expertos recomiendan que","input":"text"},{"prompt":"**la ley** · aprobar · mañana","input":"text"},{"prompt":"**nosotros** · cambiar · si fuera necesario","input":"text"},{"prompt":"**las emisiones** · disminuir · el próximo año","input":"text"}]}','{"items":[{"display":"ha reducido","answers":["ha reducido"]},{"display":"han sido instalados","answers":["han sido instalados"]},{"display":"separaran","answers":["separaran"]},{"display":"recibiría","answers":["recibiría"]},{"display":"invierta","answers":["invierta"]},{"display":"debería aprobarse","answers":["debería aprobarse"]},{"display":"cambiaríamos","answers":["cambiaríamos"]},{"display":"disminuirán","answers":["disminuirán"]}],"policy":{"accents":"strict"}}','published','L3-U13-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-11','es3-sustentabilidad','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué ha reducido la ciudad?","input":"sentence"},{"prompt":"¿Qué se ha instalado?","input":"sentence"},{"prompt":"¿Qué recomiendan los expertos?","input":"sentence"}],"text":"La ciudad ha reducido el uso de plástico y se han instalado nuevos puntos de reciclaje. Si los residentes separaran todos sus residuos, el vertedero recibiría mucha menos basura. Los expertos recomiendan que el gobierno invierta en transporte limpio y que informe mejor a la población."}','{"items":[{"display":"El uso de plástico.","answers":["El uso de plástico."]},{"display":"Nuevos puntos de reciclaje.","answers":["Nuevos puntos de reciclaje."]},{"display":"Que el gobierno invierta en transporte limpio e informe mejor.","answers":["Que el gobierno invierta en transporte limpio e informe mejor."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U13-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-12','es3-sustentabilidad','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Sustentabilidad\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["La ciudad ha reducido el uso de plástico y se han instalado nuevos puntos de reciclaje. Si los residentes separaran todos sus residuos, el vertedero recibiría mucha menos basura. Los expertos recomiendan que el gobierno invierta en transporte limpio y que informe mejor a la población."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U13-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-13','es3-sustentabilidad','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Qué ha reducido la ciudad?"},{"id":"B","text":"Respuesta: Que el gobierno invierta en transporte limpio e informe mejor."},{"id":"C","text":"Respuesta: Nuevos puntos de reciclaje."},{"id":"D","text":"Pregunta: ¿Qué se ha instalado?"},{"id":"E","text":"Respuesta: El uso de plástico."},{"id":"F","text":"Pregunta: ¿Qué recomiendan los expertos?"}]}','{"order":["A","E","D","C","F","B"],"policy":{"accents":"strict"}}','published','L3-U13-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-14','es3-sustentabilidad','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"La ciudad ha reducido el uso de plástico y se han instalado nuevos puntos de reciclaje."},{"id":"B","text":"Si los residentes separaran todos sus residuos, el vertedero recibiría mucha menos basura."},{"id":"C","text":"Los expertos recomiendan que el gobierno invierta en transporte limpio y que informe mejor a la población."}]}','{"order":["A","B","C"],"policy":{"accents":"strict"}}','published','L3-U13-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-15','es3-sustentabilidad','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre sustentabilidad es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre sustentabilidad es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U13-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-16','es3-sustentabilidad','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"מכתב = ___","input":"text"},{"prompt":"אשפה = ___","input":"text"},{"prompt":"עתיד = ___","input":"text"},{"prompt":"אדמה = ___","input":"text"},{"prompt":"**las emisiones** · disminuir · el próximo año","input":"text"},{"prompt":"**nosotros** · cambiar · si fuera necesario","input":"text"},{"prompt":"**la ley** · aprobar · mañana","input":"text"},{"prompt":"**el gobierno** · invertir · los expertos recomiendan que","input":"text"},{"prompt":"**el vertedero** · recibir · con más reciclaje","input":"text"},{"prompt":"**los residentes** · separar · después de «si» en una condición hipotética","input":"text"}]}','{"items":[{"display":"Carta","answers":["Carta"],"policy":{"accents":"lenient"}},{"display":"Basura","answers":["Basura"],"policy":{"accents":"lenient"}},{"display":"Futuro","answers":["Futuro"],"policy":{"accents":"lenient"}},{"display":"Tierra","answers":["Tierra"],"policy":{"accents":"lenient"}},{"display":"disminuirán","answers":["disminuirán"]},{"display":"cambiaríamos","answers":["cambiaríamos"]},{"display":"debería aprobarse","answers":["debería aprobarse"]},{"display":"invierta","answers":["invierta"]},{"display":"recibiría","answers":["recibiría"]},{"display":"separaran","answers":["separaran"]}],"policy":{"accents":"strict"}}','published','L3-U13-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-17','es3-sustentabilidad','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["La ciudad ha reducido el uso de plástico y se han instalado nuevos puntos de reciclaje. Si los residentes separaran todos sus residuos, el vertedero recibiría mucha menos basura."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U13-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-18','es3-sustentabilidad','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"Para mejorar el planeta, deberíamos ___ más árboles.","input":"bank"},{"prompt":"¿Cuál es el objetivo de la ___?","input":"bank"},{"prompt":"¿Qué podrías hacer tú para ___ el medio ambiente?","input":"bank"},{"prompt":"¿Qué podrías hacer tú para proteger el ___?","input":"bank"},{"prompt":"¿Cómo ___ proteger mejor al medio ambiente? Da un ejemplo.","input":"bank"},{"prompt":"Yo podría ___ más en casa.","input":"bank"},{"prompt":"Vas a escribir un mini-correo a un ___ o alcalde.","input":"bank"},{"prompt":"En tu mundo ideal, ¿Vivirías en el campo o en la ___?","input":"bank"},{"prompt":"“Para mejorar el planeta, deberíamos ___ el consumo de carne.”","input":"bank"},{"prompt":"¿Tiene un ___? Si sí, ¿cuál? Si no, ¿cómo funcionará sin él?","input":"bank"}],"wordbank":["Reducir","Político","Campaña","Proteger","Ciudad","Eslogan","Plantar","Podríamos","Reciclar","Medio ambiente"]}','{"items":[{"display":"Plantar","answers":["Plantar"]},{"display":"Campaña","answers":["Campaña"]},{"display":"Proteger","answers":["Proteger"]},{"display":"Medio ambiente","answers":["Medio ambiente"]},{"display":"Podríamos","answers":["Podríamos"]},{"display":"Reciclar","answers":["Reciclar"]},{"display":"Político","answers":["Político"]},{"display":"Ciudad","answers":["Ciudad"]},{"display":"Reducir","answers":["Reducir"]},{"display":"Eslogan","answers":["Eslogan"]}],"policy":{"accents":"strict"}}','published','L3-U13-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-19','es3-sustentabilidad','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Este año, la ciudad ___.","input":"text","hint":"reducir"},{"prompt":"Los puntos ___ recientemente.","input":"text","hint":"instalar"},{"prompt":"Si los residentes ___ los residuos, habría menos basura.","input":"text","hint":"separar"},{"prompt":"El vertedero ___ con más reciclaje.","input":"text","hint":"recibir"},{"prompt":"Los expertos recomiendan que el gobierno ___ más.","input":"text","hint":"invertir"},{"prompt":"Mañana, la ley ___.","input":"text","hint":"aprobar"},{"prompt":"Si fuera necesario, nosotros ___.","input":"text","hint":"cambiar"},{"prompt":"El próximo año, las emisiones ___.","input":"text","hint":"disminuir"}]}','{"items":[{"display":"ha reducido","answers":["ha reducido"]},{"display":"han sido instalados","answers":["han sido instalados"]},{"display":"separaran","answers":["separaran"]},{"display":"recibiría","answers":["recibiría"]},{"display":"invierta","answers":["invierta"]},{"display":"debería aprobarse","answers":["debería aprobarse"]},{"display":"cambiaríamos","answers":["cambiaríamos"]},{"display":"disminuirán","answers":["disminuirán"]}],"policy":{"accents":"strict"}}','published','L3-U13-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-sustentabilidad-20','es3-sustentabilidad','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Dónde instalaron el punto de compostaje?","input":"sentence"},{"prompt":"¿Qué causó el mal olor?","input":"sentence"},{"prompt":"¿Para qué utilizaron el compost?","input":"sentence"},{"prompt":"¿Qué recomienda el ayuntamiento?","input":"sentence"},{"prompt":"¿Qué habría ocurrido si no hubieran corregido la humedad?","input":"sentence"}],"text":"Los vecinos instalaron un punto de compostaje junto al jardín comunitario. Durante la primera semana apareció un olor desagradable porque habían añadido demasiados restos húmedos. Una especialista recomendó mezclarlos con hojas secas y explicar mejor qué materiales se aceptaban. El problema desapareció y el compost se utilizó después para cultivar tomates.\n\nEl ayuntamiento recomienda que cada edificio separe la basura y reduzca el consumo de agua y energía. Si más comunidades instalaran puntos de reciclaje y compostaje, se aprovecharían mejor los recursos y disminuiría la contaminación. Los vecinos han enviado una propuesta formal para que se proteja la biodiversidad del jardín y se planten especies locales. También piden que el transporte de los residuos sea realizado con vehículos limpios. Si no hubieran corregido el exceso de humedad, el proyecto habría sido rechazado por el barrio. Su experiencia demuestra que la sustentabilidad no depende solo de grandes políticas: requiere información clara, hábitos constantes y decisiones que cuiden el aire, la tierra y la naturaleza cercana.\n\nEl jardín produce ahora parte de su propio abono y compra menos fertilizantes. Además, los talleres han atraído a familias y escuelas. El proyecto local no resolverá la crisis ambiental, pero demuestra que una comunidad organizada puede reducir su impacto."}','{"items":[{"display":"Junto al jardín comunitario","answers":["Junto al jardín comunitario"]},{"display":"Demasiados restos húmedos","answers":["Demasiados restos húmedos"]},{"display":"Para cultivar tomates","answers":["Para cultivar tomates"]},{"display":"Que cada edificio separe la basura y reduzca el consumo de agua y energía","answers":["Que cada edificio separe la basura y reduzca el consumo de agua y energía"]},{"display":"El proyecto habría sido rechazado","answers":["El proyecto habría sido rechazado"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U13-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales','es-3','es-3-society','רשתות חברתיות','Redes sociales','לדבר ולכתוב על הנושא „רשתות חברתיות“ בספרדית, תוך שימוש במבנים: Voz pasiva, pretérito perfecto y noticias digitales.','derived','[{"he":"דקדוק בשימוש","target":"Voz pasiva, pretérito perfecto y noticias digitales"},{"he":"אוצר מילים: רשתות חברתיות","target":"Redes sociales"}]','["Voz pasiva, pretérito perfecto y noticias digitales"]','{"rules":[],"examples":["Un video falso ha sido compartido miles de veces.","Fue eliminado después de una verificación.","La creadora admitió que lo había publicado sin comprobar la fuente.","Nuevas reglas serán aplicadas pronto."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Algoritmo","he":"אלגוריתם"},{"term":"Aplicación","he":"אפליקציה"},{"term":"Apoyo","he":"תמיכה"},{"term":"Bloquear","he":"לחסום"},{"term":"Campaña","he":"קמפיין"},{"term":"Censura","he":"צנזורה"},{"term":"Chat","he":"צ׳אט"},{"term":"Comentario","he":"תגובה"},{"term":"Compartir","he":"לשתף"},{"term":"Crítica (reseña)","he":"ביקורת"},{"term":"Cuenta","he":"חשבון"},{"term":"Dar (me)","he":"לעשות לייק"},{"term":"Denunciar","he":"לדווח"},{"term":"Descargar","he":"להוריד"},{"term":"Etiquetar","he":"לתייג"},{"term":"experiencia","he":"חוויה / ניסיון"},{"term":"Foto","he":"תמונה"},{"term":"grupo","he":"קבוצה"},{"term":"Inclusión","he":"הכללה"},{"term":"Internet","he":"אינטרנט"},{"term":"Marca","he":"מותג"},{"term":"Mensaje","he":"מסר / הודעה"},{"term":"noticia","he":"חדשות"},{"term":"Perfil","he":"פרופיל"},{"term":"Plataforma","he":"פלטפורמה"},{"term":"Privacidad","he":"פרטיות"},{"term":"Publicación","he":"פרסום"},{"term":"Publicar","he":"לפרסם"},{"term":"Publicidad","he":"פרסומת"},{"term":"Red social","he":"רשת חברתית"},{"term":"Seguidor","he":"עוקב"},{"term":"Seguir","he":"לעקוב"},{"term":"Subir","he":"להעלות"},{"term":"Tendencia","he":"מגמה"},{"term":"Usuario","he":"משתמש"},{"term":"Video","he":"וידאו"},{"term":"Viral","he":"ויראלי"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/887935532/extreme-spanish-social-media-flash-cards/"}]','published','workbook L3 unit 14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-01','es3-redes-sociales','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"אלגוריתם ___","input":"text"},{"prompt":"מותג ___","input":"text"},{"prompt":"אפליקציה ___","input":"text"},{"prompt":"פרופיל ___","input":"text"},{"prompt":"לעשות לייק ___","input":"text"},{"prompt":"חשבון ___","input":"text"}]}','{"items":[{"display":"Algoritmo","answers":["Algoritmo"]},{"display":"Marca","answers":["Marca"]},{"display":"Aplicación","answers":["Aplicación"]},{"display":"Perfil","answers":["Perfil"]},{"display":"Dar (me)","answers":["Dar (me)","Dar"]},{"display":"Cuenta","answers":["Cuenta"]}],"policy":{"accents":"lenient"}}','published','L3-U14-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-02','es3-redes-sociales','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Algoritmo","Marca","Aplicación","Perfil","Dar (me)","Cuenta","Plataforma","Campaña"],"right":[{"id":"A","text":"אלגוריתם"},{"id":"B","text":"פרופיל"},{"id":"C","text":"פלטפורמה"},{"id":"D","text":"מותג"},{"id":"E","text":"לעשות לייק"},{"id":"F","text":"אפליקציה"},{"id":"G","text":"חשבון"},{"id":"H","text":"קמפיין"}]}','{"pairs":["A","D","F","B","E","G","C","H"],"policy":{"accents":"lenient"}}','published','L3-U14-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-03','es3-redes-sociales','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"אלגוריתם","input":"choice","options":["Compartir","Algoritmo","Red social"]},{"prompt":"מותג","input":"choice","options":["Algoritmo","Marca","Aplicación"]},{"prompt":"אפליקציה","input":"choice","options":["Apoyo","Aplicación","Marca"]},{"prompt":"פרופיל","input":"choice","options":["Perfil","Noticia","Campaña"]},{"prompt":"לעשות לייק","input":"choice","options":["Campaña","Dar (me)","Crítica"]},{"prompt":"חשבון","input":"choice","options":["Cuenta","Seguir","Dar (me)"]}]}','{"items":[{"display":"Algoritmo","choice":1},{"display":"Marca","choice":1},{"display":"Aplicación","choice":1},{"display":"Perfil","choice":0},{"display":"Dar (me)","choice":1},{"display":"Cuenta","choice":0}],"policy":{"accents":"lenient"}}','published','L3-U14-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-04','es3-redes-sociales','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"קמפיין = ___","input":"bank"},{"prompt":"תמיכה = ___","input":"bank"},{"prompt":"להוריד = ___","input":"bank"},{"prompt":"צנזורה = ___","input":"bank"}],"wordbank":["plataforma","Apoyo","Censura","video","Descargar","Campaña"],"text":"Un {{1}} falso ha sido compartido miles de veces y fue eliminado después de una verificación. La creadora admitió que lo había publicado sin comprobar la fuente. La {{2}} anunció que nuevas reglas serán aplicadas para que el contenido dudoso se revise más rápido."}','{"items":[{"display":"video","answers":["video"]},{"display":"plataforma","answers":["plataforma"]},{"display":"Campaña","answers":["Campaña"]},{"display":"Apoyo","answers":["Apoyo"]},{"display":"Descargar","answers":["Descargar"]},{"display":"Censura","answers":["Censura"]}],"policy":{"accents":"strict"}}','published','L3-U14-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-05','es3-redes-sociales','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["Has","por","de","rutina","diaria","culpa","sociales","las","tu","redes","cambiado"]},{"prompt":"","input":"tokens","tokens":["las","a","sociales","conocido","Has","importante","redes","a","alguien","gracias"]},{"prompt":"","input":"tokens","tokens":["últimamente","publicaciones","has","compartido","Qué"]},{"prompt":"","input":"tokens","tokens":["redes","la","inclusión","las","promueve","en","Cómo","sociales","se"]}]}','{"items":[{"display":"¿Has cambiado tu rutina diaria por culpa de las redes sociales?","answers":["¿Has cambiado tu rutina diaria por culpa de las redes sociales?"]},{"display":"¿Has conocido a alguien importante gracias a las redes sociales?","answers":["¿Has conocido a alguien importante gracias a las redes sociales?"]},{"display":"¿Qué publicaciones has compartido últimamente?","answers":["¿Qué publicaciones has compartido últimamente?"]},{"display":"¿Cómo se promueve la inclusión en las redes sociales?","answers":["¿Cómo se promueve la inclusión en las redes sociales?"]}],"policy":{"accents":"strict"}}','published','L3-U14-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-06','es3-redes-sociales','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Un video falso ha compartido miles de veces.","input":"sentence"},{"prompt":"Fue eliminar después de una verificación.","input":"sentence"},{"prompt":"La creadora admitió que lo publicó antes sin comprobar la fuente.","input":"sentence"},{"prompt":"Nuevas reglas serán aplicar pronto.","input":"sentence"}]}','{"items":[{"display":"Un video falso ha sido compartido miles de veces.","answers":["Un video falso ha sido compartido miles de veces."]},{"display":"Fue eliminado después de una verificación.","answers":["Fue eliminado después de una verificación."]},{"display":"La creadora admitió que lo había publicado sin comprobar la fuente.","answers":["La creadora admitió que lo había publicado sin comprobar la fuente."]},{"display":"Nuevas reglas serán aplicadas pronto.","answers":["Nuevas reglas serán aplicadas pronto."]}],"policy":{"accents":"strict"}}','published','L3-U14-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-07','es3-redes-sociales','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Un video falso ha sido compartido miles de veces.","Un video falso ha compartido miles de veces."]},{"prompt":"","input":"choice","options":["Fue eliminar después de una verificación.","Fue eliminado después de una verificación."]},{"prompt":"","input":"choice","options":["La creadora admitió que lo había publicado sin comprobar la fuente.","La creadora admitió que lo publicó antes sin comprobar la fuente."]},{"prompt":"","input":"choice","options":["Nuevas reglas serán aplicadas pronto.","Nuevas reglas serán aplicar pronto."]}]}','{"items":[{"display":"Un video falso ha compartido miles de veces.","choice":1},{"display":"Fue eliminado después de una verificación.","choice":1},{"display":"La creadora admitió que lo publicó antes sin comprobar la fuente.","choice":1},{"display":"Nuevas reglas serán aplicar pronto.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U14-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-08','es3-redes-sociales','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**el video** · compartir · miles de veces","input":"text"},{"prompt":"**el contenido** · eliminar · ayer","input":"text"},{"prompt":"**la creadora** · publicar · antes de verificar","input":"text"},{"prompt":"**las reglas** · aplicar · pronto","input":"text"}]}','{"items":[{"display":"ha sido compartido","answers":["ha sido compartido"]},{"display":"fue eliminado","answers":["fue eliminado"]},{"display":"había publicado","answers":["había publicado"]},{"display":"serán aplicadas","answers":["serán aplicadas"]}],"policy":{"accents":"strict"}}','published','L3-U14-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-09','es3-redes-sociales','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Has cambiado tu rutina diaria por culpa de las redes sociales?\n¿Has conocido a alguien importante gracias a las redes sociales?\n¿Qué publicaciones has compartido últimamente?\n¿Cómo se promueve la inclusión en las redes sociales?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U14-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-10','es3-redes-sociales','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**el video** · compartir · miles de veces","input":"text"},{"prompt":"**el contenido** · eliminar · ayer","input":"text"},{"prompt":"**la creadora** · publicar · antes de verificar","input":"text"},{"prompt":"**las reglas** · aplicar · pronto","input":"text"},{"prompt":"**los usuarios** · proteger · es importante que","input":"text"},{"prompt":"**la noticia** · verificar · antes de compartir","input":"text"},{"prompt":"**nosotros** · denunciar · esta mañana","input":"text"},{"prompt":"**la plataforma** · revisar · mañana","input":"text"}]}','{"items":[{"display":"ha sido compartido","answers":["ha sido compartido"]},{"display":"fue eliminado","answers":["fue eliminado"]},{"display":"había publicado","answers":["había publicado"]},{"display":"serán aplicadas","answers":["serán aplicadas"]},{"display":"protejan","answers":["protejan"]},{"display":"se verifique","answers":["se verifique"]},{"display":"hemos denunciado","answers":["hemos denunciado"]},{"display":"revisará","answers":["revisará"]}],"policy":{"accents":"strict"}}','published','L3-U14-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-11','es3-redes-sociales','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué ocurrió con el video?","input":"sentence"},{"prompt":"¿Qué admitió la creadora?","input":"sentence"},{"prompt":"¿Para qué se aplicarán nuevas reglas?","input":"sentence"}],"text":"Un video falso ha sido compartido miles de veces y fue eliminado después de una verificación. La creadora admitió que lo había publicado sin comprobar la fuente. La plataforma anunció que nuevas reglas serán aplicadas para que el contenido dudoso se revise más rápido."}','{"items":[{"display":"Fue compartido y después eliminado.","answers":["Fue compartido y después eliminado."]},{"display":"Que lo había publicado sin comprobar la fuente.","answers":["Que lo había publicado sin comprobar la fuente."]},{"display":"Para revisar más rápido el contenido dudoso.","answers":["Para revisar más rápido el contenido dudoso."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U14-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-12','es3-redes-sociales','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Redes sociales\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Un video falso ha sido compartido miles de veces y fue eliminado después de una verificación. La creadora admitió que lo había publicado sin comprobar la fuente. La plataforma anunció que nuevas reglas serán aplicadas para que el contenido dudoso se revise más rápido."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U14-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-13','es3-redes-sociales','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: Para revisar más rápido el contenido dudoso."},{"id":"B","text":"Respuesta: Que lo había publicado sin comprobar la fuente."},{"id":"C","text":"Pregunta: ¿Qué admitió la creadora?"},{"id":"D","text":"Respuesta: Fue compartido y después eliminado."},{"id":"E","text":"Pregunta: ¿Qué ocurrió con el video?"},{"id":"F","text":"Pregunta: ¿Para qué se aplicarán nuevas reglas?"}]}','{"order":["E","D","C","B","F","A"],"policy":{"accents":"strict"}}','published','L3-U14-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-14','es3-redes-sociales','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"La creadora admitió que lo había publicado sin comprobar la fuente."},{"id":"B","text":"Un video falso ha sido compartido miles de veces y fue eliminado después de una verificación."},{"id":"C","text":"La plataforma anunció que nuevas reglas serán aplicadas para que el contenido dudoso se revise más rápido."}]}','{"order":["B","A","C"],"policy":{"accents":"strict"}}','published','L3-U14-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-15','es3-redes-sociales','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre redes sociales es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre redes sociales es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U14-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-16','es3-redes-sociales','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"אפליקציה = ___","input":"text"},{"prompt":"פרופיל = ___","input":"text"},{"prompt":"לעשות לייק = ___","input":"text"},{"prompt":"חשבון = ___","input":"text"},{"prompt":"**la plataforma** · revisar · mañana","input":"text"},{"prompt":"**nosotros** · denunciar · esta mañana","input":"text"},{"prompt":"**la noticia** · verificar · antes de compartir","input":"text"},{"prompt":"**los usuarios** · proteger · es importante que","input":"text"},{"prompt":"**las reglas** · aplicar · pronto","input":"text"},{"prompt":"**la creadora** · publicar · antes de verificar","input":"text"}]}','{"items":[{"display":"Aplicación","answers":["Aplicación"],"policy":{"accents":"lenient"}},{"display":"Perfil","answers":["Perfil"],"policy":{"accents":"lenient"}},{"display":"Dar (me)","answers":["Dar (me)","Dar"],"policy":{"accents":"lenient"}},{"display":"Cuenta","answers":["Cuenta"],"policy":{"accents":"lenient"}},{"display":"revisará","answers":["revisará"]},{"display":"hemos denunciado","answers":["hemos denunciado"]},{"display":"se verifique","answers":["se verifique"]},{"display":"protejan","answers":["protejan"]},{"display":"serán aplicadas","answers":["serán aplicadas"]},{"display":"había publicado","answers":["había publicado"]}],"policy":{"accents":"strict"}}','published','L3-U14-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-17','es3-redes-sociales','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Un video falso ha sido compartido miles de veces y fue eliminado después de una verificación. La creadora admitió que lo había publicado sin comprobar la fuente."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U14-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-18','es3-redes-sociales','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"Regla: al menos una frase en voz pasiva + un ___ de opinión por titular.","input":"bank"},{"prompt":"“El escándalo ha sido utilizado como ___ por la marca.”","input":"bank"},{"prompt":"He visto un ___ que ha sido comentado más de 50 veces.","input":"bank"},{"prompt":"Mis amigos han creado un ___ nuevo en WhatsApp.","input":"bank"},{"prompt":"He encontrado una ___ que ha sido compartida más de 500 veces.","input":"bank"},{"prompt":"Mis amigos han cambiado su ___ de perfil varias veces.","input":"bank"},{"prompt":"El profesor pide que inventen su propio titular ___ usando voz pasiva.","input":"bank"},{"prompt":"“Esa ___ ha sido exagerada por los medios.”","input":"bank"},{"prompt":"צ׳אט = ___","input":"bank"},{"prompt":"רשת חברתית = ___","input":"bank"}],"wordbank":["Foto","Grupo","Publicación","Red social","Chat","Comentario","Publicidad","Video","Viral","Noticia"]}','{"items":[{"display":"Comentario","answers":["Comentario"]},{"display":"Publicidad","answers":["Publicidad"]},{"display":"Video","answers":["Video"]},{"display":"Grupo","answers":["Grupo"]},{"display":"Publicación","answers":["Publicación"]},{"display":"Foto","answers":["Foto"]},{"display":"Viral","answers":["Viral"]},{"display":"Noticia","answers":["Noticia"]},{"display":"Chat","answers":["Chat"]},{"display":"Red social","answers":["Red social"]}],"policy":{"accents":"strict"}}','published','L3-U14-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-19','es3-redes-sociales','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"El video ___ miles de veces.","input":"text","hint":"compartir"},{"prompt":"Ayer, el contenido ___.","input":"text","hint":"eliminar"},{"prompt":"Antes de verificar, la creadora ___.","input":"text","hint":"publicar"},{"prompt":"Las reglas ___ pronto.","input":"text","hint":"aplicar"},{"prompt":"Es importante que los usuarios ___ a los demás.","input":"text","hint":"proteger"},{"prompt":"Antes de compartir, la noticia ___.","input":"text","hint":"verificar"},{"prompt":"Esta mañana, nosotros ___.","input":"text","hint":"denunciar"},{"prompt":"Mañana, la plataforma ___.","input":"text","hint":"revisar"}]}','{"items":[{"display":"ha sido compartido","answers":["ha sido compartido"]},{"display":"fue eliminado","answers":["fue eliminado"]},{"display":"había publicado","answers":["había publicado"]},{"display":"serán aplicadas","answers":["serán aplicadas"]},{"display":"protejan","answers":["protejan"]},{"display":"se verifique","answers":["se verifique"]},{"display":"hemos denunciado","answers":["hemos denunciado"]},{"display":"revisará","answers":["revisará"]}],"policy":{"accents":"strict"}}','published','L3-U14-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-redes-sociales-20','es3-redes-sociales','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Qué había recibido Ana?","input":"sentence"},{"prompt":"¿Qué añadió al video?","input":"sentence"},{"prompt":"¿Qué regla personal creó?","input":"sentence"},{"prompt":"¿Cómo se identifican ahora las colaboraciones pagadas?","input":"sentence"},{"prompt":"¿Qué anunció la plataforma?","input":"sentence"}],"text":"Ana recomendó un curso en un video que alcanzó miles de visitas. Aunque había recibido acceso gratuito, no lo mencionó al principio. Sus seguidores se lo señalaron y ella añadió una aclaración visible. Después creó una regla personal: siempre indicaría cualquier relación comercial antes de expresar su opinión.\n\nDesde entonces, todas las colaboraciones pagadas han sido identificadas al principio de cada publicación. Ana también ha revisado los comentarios antiguos y ha eliminado mensajes que contenían información falsa. Su perfil ha recuperado credibilidad, aunque perdió algunos seguidores. La plataforma anunció que las cuentas comerciales serán controladas con nuevas herramientas y que el contenido patrocinado aparecerá con una etiqueta más visible. Varios usuarios han compartido la experiencia de Ana en un grupo dedicado al consumo responsable. Ella reconoce que había confundido una recomendación personal con publicidad y afirma que la transparencia debe formar parte de cualquier estrategia en una red social.\n\nAna no dejó de crear contenido ni de recomendar productos. Lo que cambió fue la relación con su audiencia: ahora distingue con claridad entre una experiencia personal y una colaboración comercial. Esa decisión ha fortalecido la confianza de sus seguidores."}','{"items":[{"display":"Acceso gratuito","answers":["Acceso gratuito"]},{"display":"Una aclaración visible","answers":["Una aclaración visible"]},{"display":"Indicar cualquier relación comercial antes de opinar","answers":["Indicar cualquier relación comercial antes de opinar"]},{"display":"Al principio de cada publicación","answers":["Al principio de cada publicación"]},{"display":"Que las cuentas comerciales serán controladas y el contenido patrocinado tendrá una etiqueta visible","answers":["Que las cuentas comerciales serán controladas y el contenido patrocinado tendrá una etiqueta visible"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U14-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad','es-3','es-3-people','זהות וקהילה','Identidad y comunidad','לדבר ולכתוב על הנושא „זהות וקהילה“ בספרדית, תוך שימוש במבנים: Segundo condicional, tiempos mezclados y argumentación.','derived','[{"he":"דקדוק בשימוש","target":"Segundo condicional, tiempos mezclados y argumentación"},{"he":"אוצר מילים: זהות וקהילה","target":"Identidad y comunidad"}]','["Segundo condicional, tiempos mezclados y argumentación"]','{"rules":[],"examples":["Samuel creció entre dos culturas.","Actualmente participa en una comunidad.","Si su familia no se hubiera mudado, vería su historia de otra forma.","Su manera de verse ha cambiado."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Ciudadanía","he":"אזרחות"},{"term":"Comparación","he":"השוואה"},{"term":"Compromiso","he":"מחויבות"},{"term":"Comunidad","he":"קהילה"},{"term":"Conflicto","he":"סכסוך / קונפליקט"},{"term":"Consecuencia","he":"תוצאה"},{"term":"Constitución","he":"חוקה"},{"term":"Contraste","he":"ניגוד"},{"term":"Creencias","he":"אמונות"},{"term":"Debate","he":"דיון / ויכוח"},{"term":"Derechos","he":"זכויות"},{"term":"Discriminación","he":"אפליה"},{"term":"Diversidad","he":"גיוון"},{"term":"Estereotipo","he":"סטריאוטיפ"},{"term":"Exclusión","he":"הדרה"},{"term":"Hipótesis","he":"השערה / השערה / הנחה"},{"term":"Identidad","he":"זהות"},{"term":"Ideología","he":"אידיאולוגיה"},{"term":"Igualdad","he":"שוויון"},{"term":"Inclusión","he":"הכללה"},{"term":"Influencia","he":"השפעה"},{"term":"Jerarquía","he":"היררכיה"},{"term":"Justicia","he":"צדק"},{"term":"Liderazgo","he":"מנהיגות"},{"term":"Mayoría","he":"רוב"},{"term":"Minoría","he":"מיעוט"},{"term":"Multiculturalidad","he":"רב־תרבותיות"},{"term":"Narrativa","he":"נרטיב / סיפור / נרטיב"},{"term":"Perspectiva","he":"נקודת מבט / נקודת מבטs"},{"term":"Pertenencia","he":"שייכות"},{"term":"Poder","he":"כוח"},{"term":"Prejuicio","he":"דעה קדומה"},{"term":"Principios","he":"עקרונות"},{"term":"Representación","he":"ייצוג"},{"term":"Responsabilidad","he":"אחריות"},{"term":"Rol","he":"תפקיד"},{"term":"Solidaridad","he":"סולידריות"},{"term":"Valores","he":"ערכים"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/il/859042961/extreme-spanish-identity-community-flash-cards/"}]','published','workbook L3 unit 15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-01','es3-identidad-y-comunidad','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"הדרה ___","input":"text"},{"prompt":"זכויות ___","input":"text"},{"prompt":"אמונות ___","input":"text"},{"prompt":"אפליה ___","input":"text"},{"prompt":"ייצוג ___","input":"text"},{"prompt":"נקודת מבט ___","input":"text"}]}','{"items":[{"display":"Exclusión","answers":["Exclusión"]},{"display":"Derechos","answers":["Derechos"]},{"display":"Creencias","answers":["Creencias"]},{"display":"Discriminación","answers":["Discriminación"]},{"display":"Representación","answers":["Representación"]},{"display":"Perspectiva","answers":["Perspectiva"]}],"policy":{"accents":"lenient"}}','published','L3-U15-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-02','es3-identidad-y-comunidad','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Exclusión","Derechos","Creencias","Discriminación","Representación","Perspectiva","Conflicto","Justicia"],"right":[{"id":"A","text":"סכסוך"},{"id":"B","text":"נקודת מבט"},{"id":"C","text":"צדק"},{"id":"D","text":"ייצוג"},{"id":"E","text":"זכויות"},{"id":"F","text":"אפליה"},{"id":"G","text":"הדרה"},{"id":"H","text":"אמונות"}]}','{"pairs":["G","E","H","F","D","B","A","C"],"policy":{"accents":"lenient"}}','published','L3-U15-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-03','es3-identidad-y-comunidad','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"הדרה","input":"choice","options":["Exclusión","Comunidad","Prejuicio"]},{"prompt":"זכויות","input":"choice","options":["Identidad","Valores","Derechos"]},{"prompt":"אמונות","input":"choice","options":["Creencias","Identidad","Discriminación"]},{"prompt":"אפליה","input":"choice","options":["Derechos","Discriminación","Hipótesis"]},{"prompt":"ייצוג","input":"choice","options":["Principios","Igualdad","Representación"]},{"prompt":"נקודת מבט","input":"choice","options":["Responsabilidad","Perspectiva","Discriminación"]}]}','{"items":[{"display":"Exclusión","choice":0},{"display":"Derechos","choice":2},{"display":"Creencias","choice":0},{"display":"Discriminación","choice":1},{"display":"Representación","choice":2},{"display":"Perspectiva","choice":1}],"policy":{"accents":"lenient"}}','published','L3-U15-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-04','es3-identidad-y-comunidad','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"רב־תרבותיות = ___","input":"bank"},{"prompt":"ערכים = ___","input":"bank"},{"prompt":"נקודת מבט = ___","input":"bank"},{"prompt":"אזרחות = ___","input":"bank"},{"prompt":"מחויבות = ___","input":"bank"}],"wordbank":["Ciudadanía","comunidad","Multiculturalidad","Valores","Perspectiva","Compromiso"],"text":"Samuel creció entre dos culturas y durante años se sentía dividido. Actualmente participa en una {{1}} que celebra ambas identidades y ha cambiado su manera de verse. Si su familia no se hubiera mudado, probablemente interpretaría su historia de otra forma."}','{"items":[{"display":"comunidad","answers":["comunidad"]},{"display":"Multiculturalidad","answers":["Multiculturalidad"]},{"display":"Valores","answers":["Valores"]},{"display":"Perspectiva","answers":["Perspectiva"]},{"display":"Ciudadanía","answers":["Ciudadanía"]},{"display":"Compromiso","answers":["Compromiso"]}],"policy":{"accents":"strict"}}','published','L3-U15-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-05','es3-identidad-y-comunidad','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["Te","parte","sientes","ellas","de"]},{"prompt":"","input":"tokens","tokens":["cambiado","ha","más","qué","y","tu","cuál","en","vida","por"]},{"prompt":"","input":"tokens","tokens":["comunidades","A","perteneces","qué"]},{"prompt":"","input":"tokens","tokens":["comunidad","y","la","identidad","es","Cuál","la","entre","conexión","la"]}]}','{"items":[{"display":"¿Te sientes parte de ellas?","answers":["¿Te sientes parte de ellas?"]},{"display":"¿cuál ha cambiado más en tu vida y por qué?","answers":["¿cuál ha cambiado más en tu vida y por qué?"]},{"display":"¿A qué comunidades perteneces?","answers":["¿A qué comunidades perteneces?"]},{"display":"¿Cuál es la conexión entre la identidad y la comunidad?","answers":["¿Cuál es la conexión entre la identidad y la comunidad?"]}],"policy":{"accents":"strict"}}','published','L3-U15-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-06','es3-identidad-y-comunidad','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Samuel crecía entre dos culturas una vez.","input":"sentence"},{"prompt":"Actualmente participó en una comunidad.","input":"sentence"},{"prompt":"Si su familia no se mudaría, vería su historia de otra forma.","input":"sentence"},{"prompt":"Su manera de verse ha cambiar.","input":"sentence"}]}','{"items":[{"display":"Samuel creció entre dos culturas.","answers":["Samuel creció entre dos culturas."]},{"display":"Actualmente participa en una comunidad.","answers":["Actualmente participa en una comunidad."]},{"display":"Si su familia no se hubiera mudado, vería su historia de otra forma.","answers":["Si su familia no se hubiera mudado, vería su historia de otra forma."]},{"display":"Su manera de verse ha cambiado.","answers":["Su manera de verse ha cambiado."]}],"policy":{"accents":"strict"}}','published','L3-U15-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-07','es3-identidad-y-comunidad','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Samuel creció entre dos culturas.","Samuel crecía entre dos culturas una vez."]},{"prompt":"","input":"choice","options":["Actualmente participa en una comunidad.","Actualmente participó en una comunidad."]},{"prompt":"","input":"choice","options":["Si su familia no se hubiera mudado, vería su historia de otra forma.","Si su familia no se mudaría, vería su historia de otra forma."]},{"prompt":"","input":"choice","options":["Su manera de verse ha cambiado.","Su manera de verse ha cambiar."]}]}','{"items":[{"display":"Samuel crecía entre dos culturas una vez.","choice":1},{"display":"Actualmente participó en una comunidad.","choice":1},{"display":"Si su familia no se mudaría, vería su historia de otra forma.","choice":1},{"display":"Su manera de verse ha cambiar.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U15-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-08','es3-identidad-y-comunidad','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**Samuel** · crecer · en su infancia","input":"text"},{"prompt":"**él** · sentirse · durante años","input":"text"},{"prompt":"**Samuel** · participar · actualmente","input":"text"},{"prompt":"**su familia** · mudarse · en una hipótesis irreal del pasado","input":"text"}]}','{"items":[{"display":"creció","answers":["creció"]},{"display":"se sentía","answers":["se sentía"]},{"display":"participa","answers":["participa"]},{"display":"se hubiera mudado","answers":["se hubiera mudado"]}],"policy":{"accents":"strict"}}','published','L3-U15-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-09','es3-identidad-y-comunidad','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Te sientes parte de ellas?\n¿cuál ha cambiado más en tu vida y por qué?\n¿A qué comunidades perteneces?\n¿Cuál es la conexión entre la identidad y la comunidad?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U15-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-10','es3-identidad-y-comunidad','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**Samuel** · crecer · en su infancia","input":"text"},{"prompt":"**él** · sentirse · durante años","input":"text"},{"prompt":"**Samuel** · participar · actualmente","input":"text"},{"prompt":"**su familia** · mudarse · en una hipótesis irreal del pasado","input":"text"},{"prompt":"**él** · interpretar · en ese caso","input":"text"},{"prompt":"**su identidad** · cambiar · con el tiempo","input":"text"},{"prompt":"**nosotros** · pertenecer · hoy","input":"text"},{"prompt":"**tú** · elegir · si pudieras","input":"text"}]}','{"items":[{"display":"creció","answers":["creció"]},{"display":"se sentía","answers":["se sentía"]},{"display":"participa","answers":["participa"]},{"display":"se hubiera mudado","answers":["se hubiera mudado"]},{"display":"interpretaría","answers":["interpretaría"]},{"display":"ha cambiado","answers":["ha cambiado"]},{"display":"pertenecemos","answers":["pertenecemos"]},{"display":"elegirías","answers":["elegirías"]}],"policy":{"accents":"strict"}}','published','L3-U15-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-11','es3-identidad-y-comunidad','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Entre qué creció Samuel?","input":"sentence"},{"prompt":"¿Dónde participa actualmente?","input":"sentence"},{"prompt":"¿Qué habría cambiado si su familia no se hubiera mudado?","input":"sentence"}],"text":"Samuel creció entre dos culturas y durante años se sentía dividido. Actualmente participa en una comunidad que celebra ambas identidades y ha cambiado su manera de verse. Si su familia no se hubiera mudado, probablemente interpretaría su historia de otra forma."}','{"items":[{"display":"Entre dos culturas.","answers":["Entre dos culturas."]},{"display":"En una comunidad que celebra ambas identidades.","answers":["En una comunidad que celebra ambas identidades."]},{"display":"Interpretaría su historia de otra forma.","answers":["Interpretaría su historia de otra forma."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U15-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-12','es3-identidad-y-comunidad','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Identidad y comunidad\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Samuel creció entre dos culturas y durante años se sentía dividido. Actualmente participa en una comunidad que celebra ambas identidades y ha cambiado su manera de verse. Si su familia no se hubiera mudado, probablemente interpretaría su historia de otra forma."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U15-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-13','es3-identidad-y-comunidad','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: En una comunidad que celebra ambas identidades."},{"id":"B","text":"Pregunta: ¿Qué habría cambiado si su familia no se hubiera mudado?"},{"id":"C","text":"Pregunta: ¿Dónde participa actualmente?"},{"id":"D","text":"Respuesta: Interpretaría su historia de otra forma."},{"id":"E","text":"Pregunta: ¿Entre qué creció Samuel?"},{"id":"F","text":"Respuesta: Entre dos culturas."}]}','{"order":["E","F","C","A","B","D"],"policy":{"accents":"strict"}}','published','L3-U15-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-14','es3-identidad-y-comunidad','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Actualmente participa en una comunidad que celebra ambas identidades y ha cambiado su manera de verse."},{"id":"B","text":"Si su familia no se hubiera mudado, probablemente interpretaría su historia de otra forma."},{"id":"C","text":"Samuel creció entre dos culturas y durante años se sentía dividido."}]}','{"order":["C","A","B"],"policy":{"accents":"strict"}}','published','L3-U15-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-15','es3-identidad-y-comunidad','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre identidad y comunidad es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre identidad y comunidad es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U15-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-16','es3-identidad-y-comunidad','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"אמונות = ___","input":"text"},{"prompt":"אפליה = ___","input":"text"},{"prompt":"ייצוג = ___","input":"text"},{"prompt":"נקודת מבט = ___","input":"text"},{"prompt":"**tú** · elegir · si pudieras","input":"text"},{"prompt":"**nosotros** · pertenecer · hoy","input":"text"},{"prompt":"**su identidad** · cambiar · con el tiempo","input":"text"},{"prompt":"**él** · interpretar · en ese caso","input":"text"},{"prompt":"**su familia** · mudarse · en una hipótesis irreal del pasado","input":"text"},{"prompt":"**Samuel** · participar · actualmente","input":"text"}]}','{"items":[{"display":"Creencias","answers":["Creencias"],"policy":{"accents":"lenient"}},{"display":"Discriminación","answers":["Discriminación"],"policy":{"accents":"lenient"}},{"display":"Representación","answers":["Representación"],"policy":{"accents":"lenient"}},{"display":"Perspectiva","answers":["Perspectiva"],"policy":{"accents":"lenient"}},{"display":"elegirías","answers":["elegirías"]},{"display":"pertenecemos","answers":["pertenecemos"]},{"display":"ha cambiado","answers":["ha cambiado"]},{"display":"interpretaría","answers":["interpretaría"]},{"display":"se hubiera mudado","answers":["se hubiera mudado"]},{"display":"participa","answers":["participa"]}],"policy":{"accents":"strict"}}','published','L3-U15-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-17','es3-identidad-y-comunidad','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Samuel creció entre dos culturas y durante años se sentía dividido. Actualmente participa en una comunidad que celebra ambas identidades y ha cambiado su manera de verse."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U15-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-18','es3-identidad-y-comunidad','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"Una ___ sobre qué pasaría si esa comunidad no existiera.","input":"bank"},{"prompt":"El elemento más importante de mi ___ es mi familia.","input":"bank"},{"prompt":"Construcción ___ (pasado, presente y futuro combinados).","input":"bank"},{"prompt":"Principios y ___: ¿qué defiende esta comunidad?","input":"bank"},{"prompt":"¿Cuál es la conexión entre la identidad y la ___?","input":"bank"},{"prompt":"Una ___ con otra comunidad.","input":"bank"},{"prompt":"La comunidad que, según ellos, tiene más ___ de influencia.","input":"bank"},{"prompt":"La comunidad que, según ellos, tiene más poder de ___.","input":"bank"},{"prompt":"Actividad 5: Mini ___: Identidad vs.","input":"bank"},{"prompt":"___ y valores: ¿qué defiende esta comunidad?","input":"bank"}],"wordbank":["Valores","Narrativa","Principios","Comparación","Comunidad","Influencia","Hipótesis","Identidad","Debate","Poder"]}','{"items":[{"display":"Hipótesis","answers":["Hipótesis"]},{"display":"Identidad","answers":["Identidad"]},{"display":"Narrativa","answers":["Narrativa"]},{"display":"Valores","answers":["Valores"]},{"display":"Comunidad","answers":["Comunidad"]},{"display":"Comparación","answers":["Comparación"]},{"display":"Poder","answers":["Poder"]},{"display":"Influencia","answers":["Influencia"]},{"display":"Debate","answers":["Debate"]},{"display":"Principios","answers":["Principios"]}],"policy":{"accents":"strict"}}','published','L3-U15-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-19','es3-identidad-y-comunidad','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Samuel ___ en su infancia.","input":"text","hint":"crecer"},{"prompt":"Él ___ durante años.","input":"text","hint":"sentirse"},{"prompt":"Actualmente, Samuel ___.","input":"text","hint":"participar"},{"prompt":"En aquella hipótesis irreal, su familia ___ antes.","input":"text","hint":"mudarse"},{"prompt":"Él ___ en ese caso.","input":"text","hint":"interpretar"},{"prompt":"Su identidad ___ con el tiempo.","input":"text","hint":"cambiar"},{"prompt":"Nosotros ___ hoy.","input":"text","hint":"pertenecer"},{"prompt":"Si pudieras, tú ___.","input":"text","hint":"elegir"}]}','{"items":[{"display":"creció","answers":["creció"]},{"display":"se sentía","answers":["se sentía"]},{"display":"participa","answers":["participa"]},{"display":"se hubiera mudado","answers":["se hubiera mudado"]},{"display":"interpretaría","answers":["interpretaría"]},{"display":"ha cambiado","answers":["ha cambiado"]},{"display":"pertenecemos","answers":["pertenecemos"]},{"display":"elegirías","answers":["elegirías"]}],"policy":{"accents":"strict"}}','published','L3-U15-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-identidad-y-comunidad-20','es3-identidad-y-comunidad','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿A quién entrevistó Layla?","input":"sentence"},{"prompt":"¿Qué hizo en lugar de corregir las formas de hablar?","input":"sentence"},{"prompt":"¿Qué mostró la exposición?","input":"sentence"},{"prompt":"¿Qué perdería la exposición si se eliminaran las diferencias lingüísticas?","input":"sentence"},{"prompt":"¿Cómo define Layla la inclusión?","input":"sentence"}],"text":"Layla entrevistó a personas mayores de su comunidad para una exposición sobre identidad. Algunas respondieron en español y otras mezclaron palabras de dos lenguas. En lugar de corregirlas, Layla conservó sus formas de hablar y añadió traducciones. La exposición mostró que una identidad compartida puede expresarse con voces muy diferentes.\n\nEl proyecto también analizó cómo los estereotipos afectan la representación de una minoría. Si Layla eliminara las diferencias lingüísticas, la exposición sería más uniforme, pero perdería muchos matices de la comunidad. Algunos visitantes reconocieron que antes asociaban la ciudadanía con una sola lengua y una sola cultura. Otros contaron experiencias de exclusión y discriminación. Layla argumentó que la inclusión no consiste en ocultar las diferencias, sino en crear un espacio de pertenencia donde la mayoría escuche otras perspectivas. Si más instituciones apoyaran iniciativas semejantes, habría menos prejuicios y la identidad colectiva podría construirse sin obligar a nadie a abandonar su historia personal.\n\nAl final de la visita, cada persona escribió una palabra relacionada con su identidad. Las respuestas fueron distintas, pero muchas mencionaban memoria, lengua, familia y futuro. El mural resultante se convirtió en una nueva representación de la comunidad."}','{"items":[{"display":"A personas mayores de su comunidad","answers":["A personas mayores de su comunidad"]},{"display":"Conservó sus formas de hablar y añadió traducciones","answers":["Conservó sus formas de hablar y añadió traducciones"]},{"display":"Que una identidad compartida puede expresarse con voces diferentes","answers":["Que una identidad compartida puede expresarse con voces diferentes"]},{"display":"Muchos matices de la comunidad","answers":["Muchos matices de la comunidad"]},{"display":"Como crear un espacio de pertenencia donde la mayoría escuche otras perspectivas","answers":["Como crear un espacio de pertenencia donde la mayoría escuche otras perspectivas"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U15-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural','es-3','es-3-society','חיים בעיר מול חיים בכפר','Vida urbana vs. vida rural','לדבר ולכתוב על הנושא „חיים בעיר מול חיים בכפר“ בספרדית, תוך שימוש במבנים: Oraciones de relativo, subjuntivo y opinión.','derived','[{"he":"דקדוק בשימוש","target":"Oraciones de relativo, subjuntivo y opinión"},{"he":"אוצר מילים: חיים בעיר מול חיים בכפר","target":"Vida urbana vs. vida rural"}]','["Oraciones de relativo, subjuntivo y opinión"]','{"rules":[],"examples":["Laura ha vivido en una capital y en un pueblo.","Busca un lugar que tenga servicios y naturaleza.","La ciudad donde trabaja ofrece oportunidades.","Si el trabajo se lo permitiera, se mudaría."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Acceso a servicios","he":"גישה לשירותים"},{"term":"Además","he":"בנוסף"},{"term":"Afectar","he":"להשפיע"},{"term":"Aislamiento","he":"בידוד"},{"term":"Aunque","he":"למרות ש"},{"term":"Barrio","he":"שכונה"},{"term":"Calidad de vida","he":"איכות חיים"},{"term":"Comunidad","he":"קהילה"},{"term":"Conexión social","he":"קשר חברתי"},{"term":"Creo que","he":"אני חושב ש"},{"term":"Densidad de población","he":"צפיפות אוכלוסייה"},{"term":"Depender","he":"להיות תלוי"},{"term":"Desarrollar","he":"לפתח"},{"term":"Desde mi punto de vista","he":"מנקודת המבט שלי"},{"term":"Donde","he":"שבו / איפה"},{"term":"En mi opinión","he":"לדעתי"},{"term":"Entorno","he":"סביבה"},{"term":"Espacios verdes","he":"שטחים ירוקים"},{"term":"Estilo de vida","he":"אורח חיים"},{"term":"Estrés","he":"לחץ / סטרס / לחץ"},{"term":"Infraestructura","he":"תשתיות"},{"term":"mejorar","he":"להשתפר / לשפר"},{"term":"Mudarse","he":"לעבור דירה"},{"term":"Ofrecer","he":"להציע"},{"term":"Oportunidades laborales","he":"הזדמנויות תעסוקה"},{"term":"Pienso que","he":"אני חושב ש"},{"term":"Porque","he":"כי"},{"term":"Que","he":"אשר / ש"},{"term":"Ritmo de vida","he":"קצב חיים"},{"term":"Ruido constante","he":"רעש מתמיד"},{"term":"Servicios públicos","he":"שירותים ציבוריים"},{"term":"Sin embargo","he":"למרות זאת / עם זאת"},{"term":"Tranquilidad","he":"רוגע"},{"term":"Transporte público","he":"תחבורה ציבורית"},{"term":"Vida rural","he":"חיים כפריים"},{"term":"Vida urbana","he":"חיים עירוניים"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1172786651/vida-urbana-vs-vida-rural-flash-cards/?new"}]','published','workbook L3 unit 16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-01','es3-vida-urbana-vs-vida-rural','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"איכות חיים ___","input":"text"},{"prompt":"שבו / איפה ___","input":"text"},{"prompt":"אני חושב ש ___","input":"text"},{"prompt":"שכונה ___","input":"text"},{"prompt":"להשפיע ___","input":"text"},{"prompt":"חיים עירוניים ___","input":"text"}]}','{"items":[{"display":"Calidad de vida","answers":["Calidad de vida"]},{"display":"Donde","answers":["Donde"]},{"display":"Creo que","answers":["Creo que"]},{"display":"Barrio","answers":["Barrio"]},{"display":"Afectar","answers":["Afectar"]},{"display":"Vida urbana","answers":["Vida urbana"]}],"policy":{"accents":"lenient"}}','published','L3-U16-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-02','es3-vida-urbana-vs-vida-rural','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Calidad de vida","Donde","Creo que","Barrio","Afectar","Vida urbana","Estrés","Pienso que"],"right":[{"id":"A","text":"להשפיע"},{"id":"B","text":"לחץ"},{"id":"C","text":"חיים עירוניים"},{"id":"D","text":"שבו / איפה"},{"id":"E","text":"אני חושב ש"},{"id":"F","text":"שכונה"},{"id":"G","text":"אני חושב ש"},{"id":"H","text":"איכות חיים"}]}','{"pairs":["H","D","E","F","A","C","B","G"],"policy":{"accents":"lenient"}}','published','L3-U16-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-03','es3-vida-urbana-vs-vida-rural','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"איכות חיים","input":"choice","options":["Densidad de población","Tranquilidad","Calidad de vida"]},{"prompt":"שבו / איפה","input":"choice","options":["Donde","Desarrollar","Ritmo de vida"]},{"prompt":"אני חושב ש","input":"choice","options":["Creo que","Donde","Sin embargo"]},{"prompt":"שכונה","input":"choice","options":["Afectar","Barrio","Aunque"]},{"prompt":"להשפיע","input":"choice","options":["Estrés","Afectar","Creo que"]},{"prompt":"חיים עירוניים","input":"choice","options":["Estrés","Infraestructura","Vida urbana"]}]}','{"items":[{"display":"Calidad de vida","choice":2},{"display":"Donde","choice":0},{"display":"Creo que","choice":0},{"display":"Barrio","choice":1},{"display":"Afectar","choice":1},{"display":"Vida urbana","choice":2}],"policy":{"accents":"lenient"}}','published','L3-U16-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-04','es3-vida-urbana-vs-vida-rural','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"להשפיע = ___","input":"bank"},{"prompt":"בידוד = ___","input":"bank"},{"prompt":"להציע = ___","input":"bank"},{"prompt":"עם זאת = ___","input":"bank"}],"wordbank":["Aislamiento","Afectar","Ofrecer","Sin embargo","que","donde"],"text":"Laura ha vivido tanto en una capital como en un pueblo pequeño. La ciudad {{1}} trabaja ofrece muchas oportunidades, mientras {{2}} el pueblo en el que viven sus abuelos tiene un ritmo más tranquilo. Busca un lugar que tenga servicios y naturaleza; si el trabajo remoto se lo permitiera, se mudaría mañana."}','{"items":[{"display":"donde","answers":["donde"]},{"display":"que","answers":["que"]},{"display":"Afectar","answers":["Afectar"]},{"display":"Aislamiento","answers":["Aislamiento"]},{"display":"Ofrecer","answers":["Ofrecer"]},{"display":"Sin embargo","answers":["Sin embargo"]}],"policy":{"accents":"strict"}}','published','L3-U16-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-05','es3-vida-urbana-vs-vida-rural','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["mejoraba","lugar","vida","tu","tenía","ese","calidad","que","de","Qué"]},{"prompt":"","input":"tokens","tokens":["otro","a","ciudad","otra","a","mudado","Alguna","has","te","o","barrio","vez"]},{"prompt":"","input":"tokens","tokens":["calidad","Cómo","tu","vida","ha","de","cambiado"]},{"prompt":"","input":"tokens","tokens":["tipo","comunidad","y","prefieres","Qué","qué","de","por"]}]}','{"items":[{"display":"¿Qué tenía ese lugar que mejoraba tu calidad de vida?","answers":["¿Qué tenía ese lugar que mejoraba tu calidad de vida?"]},{"display":"¿Alguna vez te has mudado a otra ciudad o a otro barrio?","answers":["¿Alguna vez te has mudado a otra ciudad o a otro barrio?"]},{"display":"¿Cómo ha cambiado tu calidad de vida?","answers":["¿Cómo ha cambiado tu calidad de vida?"]},{"display":"¿Qué tipo de comunidad prefieres y por qué?","answers":["¿Qué tipo de comunidad prefieres y por qué?"]}],"policy":{"accents":"strict"}}','published','L3-U16-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-06','es3-vida-urbana-vs-vida-rural','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Laura ha vivió en una capital y un pueblo.","input":"sentence"},{"prompt":"Busca un lugar que tiene servicios y naturaleza.","input":"sentence"},{"prompt":"La ciudad donde trabaja que ofrece oportunidades.","input":"sentence"},{"prompt":"Si el trabajo se lo permitiría, se mudaría.","input":"sentence"}]}','{"items":[{"display":"Laura ha vivido en una capital y en un pueblo.","answers":["Laura ha vivido en una capital y en un pueblo."]},{"display":"Busca un lugar que tenga servicios y naturaleza.","answers":["Busca un lugar que tenga servicios y naturaleza."]},{"display":"La ciudad donde trabaja ofrece oportunidades.","answers":["La ciudad donde trabaja ofrece oportunidades."]},{"display":"Si el trabajo se lo permitiera, se mudaría.","answers":["Si el trabajo se lo permitiera, se mudaría."]}],"policy":{"accents":"strict"}}','published','L3-U16-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-07','es3-vida-urbana-vs-vida-rural','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Laura ha vivió en una capital y un pueblo.","Laura ha vivido en una capital y en un pueblo."]},{"prompt":"","input":"choice","options":["Busca un lugar que tiene servicios y naturaleza.","Busca un lugar que tenga servicios y naturaleza."]},{"prompt":"","input":"choice","options":["La ciudad donde trabaja ofrece oportunidades.","La ciudad donde trabaja que ofrece oportunidades."]},{"prompt":"","input":"choice","options":["Si el trabajo se lo permitiera, se mudaría.","Si el trabajo se lo permitiría, se mudaría."]}]}','{"items":[{"display":"Laura ha vivido en una capital y en un pueblo.","choice":1},{"display":"Busca un lugar que tenga servicios y naturaleza.","choice":1},{"display":"La ciudad donde trabaja que ofrece oportunidades.","choice":1},{"display":"Si el trabajo se lo permitiría, se mudaría.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U16-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-08','es3-vida-urbana-vs-vida-rural','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**Laura** · vivir · hasta hoy","input":"text"},{"prompt":"**la ciudad** · ofrecer · actualmente","input":"text"},{"prompt":"**los abuelos** · vivir · desde hace años","input":"text"},{"prompt":"**el lugar** · tener · Laura busca que","input":"text"}]}','{"items":[{"display":"ha vivido","answers":["ha vivido"]},{"display":"ofrece","answers":["ofrece"]},{"display":"viven","answers":["viven"]},{"display":"tenga","answers":["tenga"]}],"policy":{"accents":"strict"}}','published','L3-U16-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-09','es3-vida-urbana-vs-vida-rural','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Qué tenía ese lugar que mejoraba tu calidad de vida?\n¿Por qué?\n¿Alguna vez te has mudado a otra ciudad o a otro barrio?\n¿Cómo ha cambiado tu calidad de vida?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U16-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-10','es3-vida-urbana-vs-vida-rural','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**Laura** · vivir · hasta hoy","input":"text"},{"prompt":"**la ciudad** · ofrecer · actualmente","input":"text"},{"prompt":"**los abuelos** · vivir · desde hace años","input":"text"},{"prompt":"**el lugar** · tener · Laura busca que","input":"text"},{"prompt":"**el trabajo** · permitir · después de «si» en una hipótesis","input":"text"},{"prompt":"**Laura** · mudarse · en ese caso","input":"text"},{"prompt":"**nosotros** · preferir · si tuviéramos opciones","input":"text"},{"prompt":"**el pueblo** · renovar · este año","input":"text"}]}','{"items":[{"display":"ha vivido","answers":["ha vivido"]},{"display":"ofrece","answers":["ofrece"]},{"display":"viven","answers":["viven"]},{"display":"tenga","answers":["tenga"]},{"display":"permitiera","answers":["permitiera"]},{"display":"se mudaría","answers":["se mudaría"]},{"display":"preferiríamos","answers":["preferiríamos"]},{"display":"ha sido renovado","answers":["ha sido renovado"]}],"policy":{"accents":"strict"}}','published','L3-U16-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-11','es3-vida-urbana-vs-vida-rural','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Dónde ha vivido Laura?","input":"sentence"},{"prompt":"¿Qué ofrece la ciudad?","input":"sentence"},{"prompt":"¿Qué tipo de lugar busca?","input":"sentence"}],"text":"Laura ha vivido tanto en una capital como en un pueblo pequeño. La ciudad donde trabaja ofrece muchas oportunidades, mientras que el pueblo en el que viven sus abuelos tiene un ritmo más tranquilo. Busca un lugar que tenga servicios y naturaleza; si el trabajo remoto se lo permitiera, se mudaría mañana."}','{"items":[{"display":"En una capital y en un pueblo pequeño.","answers":["En una capital y en un pueblo pequeño."]},{"display":"Muchas oportunidades.","answers":["Muchas oportunidades."]},{"display":"Un lugar que tenga servicios y naturaleza.","answers":["Un lugar que tenga servicios y naturaleza."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U16-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-12','es3-vida-urbana-vs-vida-rural','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Vida urbana vs. vida rural\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Laura ha vivido tanto en una capital como en un pueblo pequeño. La ciudad donde trabaja ofrece muchas oportunidades, mientras que el pueblo en el que viven sus abuelos tiene un ritmo más tranquilo. Busca un lugar que tenga servicios y naturaleza; si el trabajo remoto se lo permitiera, se mudaría mañana."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U16-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-13','es3-vida-urbana-vs-vida-rural','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Qué tipo de lugar busca?"},{"id":"B","text":"Pregunta: ¿Dónde ha vivido Laura?"},{"id":"C","text":"Respuesta: En una capital y en un pueblo pequeño."},{"id":"D","text":"Respuesta: Muchas oportunidades."},{"id":"E","text":"Pregunta: ¿Qué ofrece la ciudad?"},{"id":"F","text":"Respuesta: Un lugar que tenga servicios y naturaleza."}]}','{"order":["B","C","E","D","A","F"],"policy":{"accents":"strict"}}','published','L3-U16-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-14','es3-vida-urbana-vs-vida-rural','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"La ciudad donde trabaja ofrece muchas oportunidades, mientras que el pueblo en el que viven sus abuelos tiene un ritmo más tranquilo."},{"id":"B","text":"Laura ha vivido tanto en una capital como en un pueblo pequeño."},{"id":"C","text":"Busca un lugar que tenga servicios y naturaleza; si el trabajo remoto se lo permitiera, se mudaría mañana."}]}','{"order":["B","A","C"],"policy":{"accents":"strict"}}','published','L3-U16-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-15','es3-vida-urbana-vs-vida-rural','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre vida urbana vs. vida rural es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre vida urbana vs. vida rural es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U16-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-16','es3-vida-urbana-vs-vida-rural','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"אני חושב ש = ___","input":"text"},{"prompt":"שכונה = ___","input":"text"},{"prompt":"להשפיע = ___","input":"text"},{"prompt":"חיים עירוניים = ___","input":"text"},{"prompt":"**el pueblo** · renovar · este año","input":"text"},{"prompt":"**nosotros** · preferir · si tuviéramos opciones","input":"text"},{"prompt":"**Laura** · mudarse · en ese caso","input":"text"},{"prompt":"**el trabajo** · permitir · después de «si» en una hipótesis","input":"text"},{"prompt":"**el lugar** · tener · Laura busca que","input":"text"},{"prompt":"**los abuelos** · vivir · desde hace años","input":"text"}]}','{"items":[{"display":"Creo que","answers":["Creo que"],"policy":{"accents":"lenient"}},{"display":"Barrio","answers":["Barrio"],"policy":{"accents":"lenient"}},{"display":"Afectar","answers":["Afectar"],"policy":{"accents":"lenient"}},{"display":"Vida urbana","answers":["Vida urbana"],"policy":{"accents":"lenient"}},{"display":"ha sido renovado","answers":["ha sido renovado"]},{"display":"preferiríamos","answers":["preferiríamos"]},{"display":"se mudaría","answers":["se mudaría"]},{"display":"permitiera","answers":["permitiera"]},{"display":"tenga","answers":["tenga"]},{"display":"viven","answers":["viven"]}],"policy":{"accents":"strict"}}','published','L3-U16-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-17','es3-vida-urbana-vs-vida-rural','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Laura ha vivido tanto en una capital como en un pueblo pequeño. La ciudad donde trabaja ofrece muchas oportunidades, mientras que el pueblo en el que viven sus abuelos tiene un ritmo más tranquilo."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U16-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-18','es3-vida-urbana-vs-vida-rural','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"El campo, que es más tranquilo, ofrece menos ___.","input":"bank"},{"prompt":"___, el campo es más relajante.","input":"bank"},{"prompt":"Los edificios, los cuales son modernos, mejoran la ___.","input":"bank"},{"prompt":"Describe un barrio donde hayas vivido o ___ hayas visitado.","input":"bank"},{"prompt":"Piensa en infraestructura, aislamiento o ___.","input":"bank"},{"prompt":"Creo que la ciudad es mejor ___...","input":"bank"},{"prompt":"¿Qué aspectos de la ___ podrían mejorar la vida urbana?","input":"bank"},{"prompt":"___, la ciudad ofrece más oportunidades.","input":"bank"},{"prompt":"¿Qué ___ ofrece mejor calidad de vida?","input":"bank"},{"prompt":"¿Qué tipo de ___ prefieres y por qué?","input":"bank"}],"wordbank":["En mi opinión","Que","Desde mi punto de vista","Vida rural","Oportunidades laborales","Comunidad","Porque","Acceso a servicios","Estilo de vida","Infraestructura"]}','{"items":[{"display":"Oportunidades laborales","answers":["Oportunidades laborales"]},{"display":"Desde mi punto de vista","answers":["Desde mi punto de vista"]},{"display":"Infraestructura","answers":["Infraestructura"]},{"display":"Que","answers":["Que"]},{"display":"Acceso a servicios","answers":["Acceso a servicios"]},{"display":"Porque","answers":["Porque"]},{"display":"Vida rural","answers":["Vida rural"]},{"display":"En mi opinión","answers":["En mi opinión"]},{"display":"Estilo de vida","answers":["Estilo de vida"]},{"display":"Comunidad","answers":["Comunidad"]}],"policy":{"accents":"strict"}}','published','L3-U16-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-19','es3-vida-urbana-vs-vida-rural','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Laura ___ hasta hoy.","input":"text","hint":"vivir"},{"prompt":"Actualmente, la ciudad ___.","input":"text","hint":"ofrecer"},{"prompt":"Los abuelos ___ desde hace años.","input":"text","hint":"vivir"},{"prompt":"Laura busca que el lugar ___ servicios y naturaleza.","input":"text","hint":"tener"},{"prompt":"Si el trabajo lo ___, Laura se mudaría.","input":"text","hint":"permitir"},{"prompt":"Laura ___ en ese caso.","input":"text","hint":"mudarse"},{"prompt":"Si tuviéramos opciones, nosotros ___.","input":"text","hint":"preferir"},{"prompt":"Este año, el pueblo ___.","input":"text","hint":"renovar"}]}','{"items":[{"display":"ha vivido","answers":["ha vivido"]},{"display":"ofrece","answers":["ofrece"]},{"display":"viven","answers":["viven"]},{"display":"tenga","answers":["tenga"]},{"display":"permitiera","answers":["permitiera"]},{"display":"se mudaría","answers":["se mudaría"]},{"display":"preferiríamos","answers":["preferiríamos"]},{"display":"ha sido renovado","answers":["ha sido renovado"]}],"policy":{"accents":"strict"}}','published','L3-U16-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-vida-urbana-vs-vida-rural-20','es3-vida-urbana-vs-vida-rural','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Cuántos días viajaba Mateo al principio?","input":"sentence"},{"prompt":"¿Qué propuso?","input":"sentence"},{"prompt":"¿Por qué aceptó la empresa el plan?","input":"sentence"},{"prompt":"¿Qué desventaja tiene el pueblo?","input":"sentence"},{"prompt":"¿Qué tipo de comunidad busca Mateo?","input":"sentence"}],"text":"Mateo vivía en un pueblo tranquilo, pero trabajaba para una empresa de la capital. Durante seis meses viajó tres días por semana y terminó agotado. Propuso asistir a la oficina solo una vez por semana y trabajar el resto desde casa. La empresa aceptó el plan porque definió objetivos claros y mantuvo reuniones breves con su equipo.\n\nEl pueblo en el que vive Mateo ofrece una buena calidad de vida y un entorno natural, pero tiene pocos servicios públicos. La capital, donde está la oficina, concentra oportunidades laborales, infraestructura y transporte público, aunque la densidad de población aumenta el ruido y el coste de la vivienda. Mateo busca un barrio que tenga conexión ferroviaria y espacios verdes. No quiere mudarse a un lugar que esté completamente aislado, ni desea que su estilo de vida dependa del coche. Si existiera una red de transporte más frecuente, muchas personas elegirían la vida rural sin renunciar al empleo urbano. Para él, la solución ideal es una comunidad que combine tranquilidad, servicios y movilidad.\n\nSu experiencia muestra que la oposición entre campo y ciudad no siempre es absoluta. Con infraestructura adecuada, trabajo remoto y transporte público, es posible crear formas de vida que aprovechen las oportunidades urbanas y la tranquilidad rural."}','{"items":[{"display":"Tres días por semana","answers":["Tres días por semana"]},{"display":"Ir a la oficina una vez por semana y trabajar el resto desde casa","answers":["Ir a la oficina una vez por semana y trabajar el resto desde casa"]},{"display":"Porque definió objetivos claros y mantuvo reuniones breves","answers":["Porque definió objetivos claros y mantuvo reuniones breves"]},{"display":"Tiene pocos servicios públicos","answers":["Tiene pocos servicios públicos"]},{"display":"Una comunidad que combine tranquilidad, servicios y movilidad","answers":["Una comunidad que combine tranquilidad, servicios y movilidad"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U16-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones','es-3','es-3-people','משפחה, דורות ומערכות יחסים','Familia, generaciones y relaciones','לדבר ולכתוב על הנושא „משפחה, דורות ומערכות יחסים“ בספרדית, תוך שימוש במבנים: Comparaciones, conectores y narración familiar.','derived','[{"he":"דקדוק בשימוש","target":"Comparaciones, conectores y narración familiar"},{"he":"אוצר מילים: משפחה, דורות ומערכות יחסים","target":"Familia, generaciones y relaciones"}]','["Comparaciones, conectores y narración familiar"]','{"rules":[],"examples":["Los abuelos llegaron y trabajaban muchas horas.","Sus hijos han elegido profesiones diferentes.","La familia, que vive unida, se apoya.","Aunque comparan sus decisiones, se respetan."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Ambicioso","he":"שאפתן"},{"term":"Apoyo","he":"תמיכה"},{"term":"Aunque","he":"למרות ש"},{"term":"Coherente","he":"עקבי"},{"term":"Competitivo","he":"תחרותי"},{"term":"Comprensión","he":"הבנה"},{"term":"Conflicto","he":"סכסוך / קונפליקט"},{"term":"Conservador","he":"שמרני"},{"term":"De mente abierta","he":"פתוח מחשבתית"},{"term":"Determinado","he":"נחוש"},{"term":"Dinámica","he":"דינמיקה"},{"term":"Equilibrado","he":"מאוזן"},{"term":"Estabilidad","he":"יציבות"},{"term":"Excesivo","he":"מוגזם"},{"term":"Exigente","he":"תובעני"},{"term":"Expectativa","he":"ציפייה"},{"term":"Flexible","he":"גמיש"},{"term":"Independencia","he":"עצמאות"},{"term":"Independiente","he":"עצמאי"},{"term":"Influencia","he":"השפעה"},{"term":"Influyente","he":"משפיע"},{"term":"Lealtad","he":"נאמנות"},{"term":"Libertad","he":"חופש"},{"term":"Mientras","he":"בעוד ש"},{"term":"Por lo tanto","he":"לכן"},{"term":"Presión","he":"לחץ"},{"term":"Protector","he":"מגונן"},{"term":"Puesto que","he":"מאחר ש"},{"term":"Relación","he":"מערכת יחסים"},{"term":"Reservado","he":"מופנם"},{"term":"Resiliente","he":"עמיד"},{"term":"Respeto","he":"כבוד"},{"term":"Responsable","he":"אחראי"},{"term":"Sin embargo","he":"למרות זאת / עם זאת"},{"term":"Solidario","he":"תומך"},{"term":"Testardo","he":"עקשן"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1173508478/familia-flash-cards/?funnelUUID=2a047176-a6fd-4d6c-a3af-2e707ff50e05"}]','published','workbook L3 unit 17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-01','es3-familia-generaciones-y-relaciones','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"מערכת יחסים ___","input":"text"},{"prompt":"עמיד ___","input":"text"},{"prompt":"עקבי ___","input":"text"},{"prompt":"מופנם ___","input":"text"},{"prompt":"משפיע ___","input":"text"},{"prompt":"תובעני ___","input":"text"}]}','{"items":[{"display":"Relación","answers":["Relación"]},{"display":"Resiliente","answers":["Resiliente"]},{"display":"Coherente","answers":["Coherente"]},{"display":"Reservado","answers":["Reservado"]},{"display":"Influyente","answers":["Influyente"]},{"display":"Exigente","answers":["Exigente"]}],"policy":{"accents":"lenient"}}','published','L3-U17-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-02','es3-familia-generaciones-y-relaciones','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Relación","Resiliente","Coherente","Reservado","Influyente","Exigente","Estabilidad","Solidario"],"right":[{"id":"A","text":"יציבות"},{"id":"B","text":"משפיע"},{"id":"C","text":"עמיד"},{"id":"D","text":"מופנם"},{"id":"E","text":"מערכת יחסים"},{"id":"F","text":"תובעני"},{"id":"G","text":"עקבי"},{"id":"H","text":"תומך"}]}','{"pairs":["E","C","G","D","B","F","A","H"],"policy":{"accents":"lenient"}}','published','L3-U17-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-03','es3-familia-generaciones-y-relaciones','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"מערכת יחסים","input":"choice","options":["Relación","Presión","Responsable"]},{"prompt":"עמיד","input":"choice","options":["Coherente","Resiliente","Competitivo"]},{"prompt":"עקבי","input":"choice","options":["Coherente","Dinámica","Mientras"]},{"prompt":"מופנם","input":"choice","options":["Reservado","Coherente","Conflicto"]},{"prompt":"משפיע","input":"choice","options":["Mientras","Influyente","Influencia"]},{"prompt":"תובעני","input":"choice","options":["Estabilidad","Exigente","Independiente"]}]}','{"items":[{"display":"Relación","choice":0},{"display":"Resiliente","choice":1},{"display":"Coherente","choice":0},{"display":"Reservado","choice":0},{"display":"Influyente","choice":1},{"display":"Exigente","choice":1}],"policy":{"accents":"lenient"}}','published','L3-U17-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-04','es3-familia-generaciones-y-relaciones','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"","input":"bank","inText":true},{"prompt":"עצמאות = ___","input":"bank"},{"prompt":"עמיד = ___","input":"bank"}],"wordbank":["Resiliente","relación","mientras","Aunque","Independencia","apoyo"],"text":"Tres generaciones de la familia Ruiz mantienen una {{1}} cercana. Los abuelos, que llegaron de otro país, trabajaban muchas horas, {{2}} que sus hijos han elegido profesiones diferentes. {{3}} a veces comparan sus decisiones, todos reconocen que el {{4}} familiar ha influido en sus caminos."}','{"items":[{"display":"relación","answers":["relación"]},{"display":"mientras","answers":["mientras"]},{"display":"Aunque","answers":["Aunque"]},{"display":"apoyo","answers":["apoyo"]},{"display":"Independencia","answers":["Independencia"]},{"display":"Resiliente","answers":["Resiliente"]}],"policy":{"accents":"strict"}}','published','L3-U17-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-05','es3-familia-generaciones-y-relaciones','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["tu","moderna","o","como","familia","tradicional","más","más","Describirías"]},{"prompt":"","input":"tokens","tokens":["en","decisiones","importantes","influye","Cómo","eso","las"]},{"prompt":"","input":"tokens","tokens":["por","Quién","qué","persona","sido","influyente","y","vida","tu","una","ha","en"]},{"prompt":"","input":"tokens","tokens":["dinámica","familia","la","tu","describirías","de","Cómo"]}]}','{"items":[{"display":"¿Describirías tu familia como más tradicional o más moderna?","answers":["¿Describirías tu familia como más tradicional o más moderna?"]},{"display":"¿Cómo influye eso en las decisiones importantes?","answers":["¿Cómo influye eso en las decisiones importantes?"]},{"display":"¿Quién ha sido una persona influyente en tu vida y por qué?","answers":["¿Quién ha sido una persona influyente en tu vida y por qué?"]},{"display":"¿Cómo describirías la dinámica de tu familia?","answers":["¿Cómo describirías la dinámica de tu familia?"]}],"policy":{"accents":"strict"}}','published','L3-U17-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-06','es3-familia-generaciones-y-relaciones','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Los abuelos llegaron y trabajaron muchas horas habitualmente.","input":"sentence"},{"prompt":"Sus hijos han eligido profesiones diferentes.","input":"sentence"},{"prompt":"La familia, que viven unida, se apoya.","input":"sentence"},{"prompt":"Aunque comparan sus decisiones, pero se respetan.","input":"sentence"}]}','{"items":[{"display":"Los abuelos llegaron y trabajaban muchas horas.","answers":["Los abuelos llegaron y trabajaban muchas horas."]},{"display":"Sus hijos han elegido profesiones diferentes.","answers":["Sus hijos han elegido profesiones diferentes."]},{"display":"La familia, que vive unida, se apoya.","answers":["La familia, que vive unida, se apoya."]},{"display":"Aunque comparan sus decisiones, se respetan.","answers":["Aunque comparan sus decisiones, se respetan."]}],"policy":{"accents":"strict"}}','published','L3-U17-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-07','es3-familia-generaciones-y-relaciones','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Los abuelos llegaron y trabajaron muchas horas habitualmente.","Los abuelos llegaron y trabajaban muchas horas."]},{"prompt":"","input":"choice","options":["Sus hijos han elegido profesiones diferentes.","Sus hijos han eligido profesiones diferentes."]},{"prompt":"","input":"choice","options":["La familia, que viven unida, se apoya.","La familia, que vive unida, se apoya."]},{"prompt":"","input":"choice","options":["Aunque comparan sus decisiones, pero se respetan.","Aunque comparan sus decisiones, se respetan."]}]}','{"items":[{"display":"Los abuelos llegaron y trabajaban muchas horas.","choice":1},{"display":"Sus hijos han eligido profesiones diferentes.","choice":1},{"display":"La familia, que vive unida, se apoya.","choice":1},{"display":"Aunque comparan sus decisiones, se respetan.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U17-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-08','es3-familia-generaciones-y-relaciones','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**los abuelos** · llegar · hace muchos años","input":"text"},{"prompt":"**ellos** · trabajar · habitualmente","input":"text"},{"prompt":"**sus hijos** · elegir · hasta ahora","input":"text"},{"prompt":"**yo** · recibir · si mi familia me apoyara","input":"text"}]}','{"items":[{"display":"llegaron","answers":["llegaron"]},{"display":"trabajaban","answers":["trabajaban"]},{"display":"han elegido","answers":["han elegido"]},{"display":"recibiría","answers":["recibiría"]}],"policy":{"accents":"strict"}}','published','L3-U17-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-09','es3-familia-generaciones-y-relaciones','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Describirías tu familia como más tradicional o más moderna?\n¿Cómo influye eso en las decisiones importantes?\n¿Quién ha sido una persona influyente en tu vida y por qué?\n¿Cómo describirías la dinámica de tu familia?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U17-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-10','es3-familia-generaciones-y-relaciones','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**los abuelos** · llegar · hace muchos años","input":"text"},{"prompt":"**ellos** · trabajar · habitualmente","input":"text"},{"prompt":"**sus hijos** · elegir · hasta ahora","input":"text"},{"prompt":"**yo** · recibir · si mi familia me apoyara","input":"text"},{"prompt":"**ella** · decidir · si hubiera tenido otra oportunidad","input":"text"},{"prompt":"**las generaciones** · apoyarse · actualmente","input":"text"},{"prompt":"**nosotros** · comparar · ayer","input":"text"},{"prompt":"**la relación** · fortalecer · con el tiempo","input":"text"}]}','{"items":[{"display":"llegaron","answers":["llegaron"]},{"display":"trabajaban","answers":["trabajaban"]},{"display":"han elegido","answers":["han elegido"]},{"display":"recibiría","answers":["recibiría"]},{"display":"habría decidido","answers":["habría decidido"]},{"display":"se apoyan","answers":["se apoyan"]},{"display":"comparamos","answers":["comparamos"]},{"display":"se ha fortalecido","answers":["se ha fortalecido"]}],"policy":{"accents":"strict"}}','published','L3-U17-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-11','es3-familia-generaciones-y-relaciones','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Cuántas generaciones aparecen?","input":"sentence"},{"prompt":"¿Cómo trabajaban los abuelos?","input":"sentence"},{"prompt":"¿Qué ha influido en sus caminos?","input":"sentence"}],"text":"Tres generaciones de la familia Ruiz mantienen una relación cercana. Los abuelos, que llegaron de otro país, trabajaban muchas horas, mientras que sus hijos han elegido profesiones diferentes. Aunque a veces comparan sus decisiones, todos reconocen que el apoyo familiar ha influido en sus caminos."}','{"items":[{"display":"Tres generaciones.","answers":["Tres generaciones."]},{"display":"Trabajaban muchas horas.","answers":["Trabajaban muchas horas."]},{"display":"El apoyo familiar.","answers":["El apoyo familiar."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U17-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-12','es3-familia-generaciones-y-relaciones','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Familia, generaciones y relaciones\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Tres generaciones de la familia Ruiz mantienen una relación cercana. Los abuelos, que llegaron de otro país, trabajaban muchas horas, mientras que sus hijos han elegido profesiones diferentes. Aunque a veces comparan sus decisiones, todos reconocen que el apoyo familiar ha influido en sus caminos."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U17-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-13','es3-familia-generaciones-y-relaciones','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: Trabajaban muchas horas."},{"id":"B","text":"Respuesta: Tres generaciones."},{"id":"C","text":"Pregunta: ¿Cuántas generaciones aparecen?"},{"id":"D","text":"Respuesta: El apoyo familiar."},{"id":"E","text":"Pregunta: ¿Qué ha influido en sus caminos?"},{"id":"F","text":"Pregunta: ¿Cómo trabajaban los abuelos?"}]}','{"order":["C","B","F","A","E","D"],"policy":{"accents":"strict"}}','published','L3-U17-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-14','es3-familia-generaciones-y-relaciones','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Tres generaciones de la familia Ruiz mantienen una relación cercana."},{"id":"B","text":"Aunque a veces comparan sus decisiones, todos reconocen que el apoyo familiar ha influido en sus caminos."},{"id":"C","text":"Los abuelos, que llegaron de otro país, trabajaban muchas horas, mientras que sus hijos han elegido profesiones diferentes."}]}','{"order":["A","C","B"],"policy":{"accents":"strict"}}','published','L3-U17-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-15','es3-familia-generaciones-y-relaciones','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre familia, generaciones y relaciones es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre familia, generaciones y relaciones es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U17-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-16','es3-familia-generaciones-y-relaciones','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"עקבי = ___","input":"text"},{"prompt":"מופנם = ___","input":"text"},{"prompt":"משפיע = ___","input":"text"},{"prompt":"תובעני = ___","input":"text"},{"prompt":"**la relación** · fortalecer · con el tiempo","input":"text"},{"prompt":"**nosotros** · comparar · ayer","input":"text"},{"prompt":"**las generaciones** · apoyarse · actualmente","input":"text"},{"prompt":"**ella** · decidir · si hubiera tenido otra oportunidad","input":"text"},{"prompt":"**yo** · recibir · si mi familia me apoyara","input":"text"},{"prompt":"**sus hijos** · elegir · hasta ahora","input":"text"}]}','{"items":[{"display":"Coherente","answers":["Coherente"],"policy":{"accents":"lenient"}},{"display":"Reservado","answers":["Reservado"],"policy":{"accents":"lenient"}},{"display":"Influyente","answers":["Influyente"],"policy":{"accents":"lenient"}},{"display":"Exigente","answers":["Exigente"],"policy":{"accents":"lenient"}},{"display":"se ha fortalecido","answers":["se ha fortalecido"]},{"display":"comparamos","answers":["comparamos"]},{"display":"se apoyan","answers":["se apoyan"]},{"display":"habría decidido","answers":["habría decidido"]},{"display":"recibiría","answers":["recibiría"]},{"display":"han elegido","answers":["han elegido"]}],"policy":{"accents":"strict"}}','published','L3-U17-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-17','es3-familia-generaciones-y-relaciones','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Tres generaciones de la familia Ruiz mantienen una relación cercana. Los abuelos, que llegaron de otro país, trabajaban muchas horas, mientras que sus hijos han elegido profesiones diferentes."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U17-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-18','es3-familia-generaciones-y-relaciones','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"La ___ personal debe tener prioridad.","input":"bank"},{"prompt":"La ___ familiar es el valor más importante.","input":"bank"},{"prompt":"¿Cómo describirías la ___ de tu familia?","input":"bank"},{"prompt":"“___ discutimos mucho, nos apoyamos en momentos difíciles.”","input":"bank"},{"prompt":"“Gracias al ejemplo de su madre, él se volvió más ___.”","input":"bank"},{"prompt":"עם זאת = ___","input":"bank"},{"prompt":"פתוח מחשבתית = ___","input":"bank"},{"prompt":"הבנה = ___","input":"bank"},{"prompt":"אחראי = ___","input":"bank"},{"prompt":"גמיש = ___","input":"bank"}],"wordbank":["Independencia","Flexible","Comprensión","Responsable","Independiente","Dinámica","Sin embargo","Lealtad","De mente abierta","Aunque"]}','{"items":[{"display":"Independencia","answers":["Independencia"]},{"display":"Lealtad","answers":["Lealtad"]},{"display":"Dinámica","answers":["Dinámica"]},{"display":"Aunque","answers":["Aunque"]},{"display":"Independiente","answers":["Independiente"]},{"display":"Sin embargo","answers":["Sin embargo"]},{"display":"De mente abierta","answers":["De mente abierta"]},{"display":"Comprensión","answers":["Comprensión"]},{"display":"Responsable","answers":["Responsable"]},{"display":"Flexible","answers":["Flexible"]}],"policy":{"accents":"strict"}}','published','L3-U17-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-19','es3-familia-generaciones-y-relaciones','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Los abuelos ___ hace muchos años.","input":"text","hint":"llegar"},{"prompt":"Ellos ___ habitualmente.","input":"text","hint":"trabajar"},{"prompt":"Sus hijos ___ hasta ahora.","input":"text","hint":"elegir"},{"prompt":"Si mi familia me apoyara, yo ___.","input":"text","hint":"recibir"},{"prompt":"Si hubiera tenido otra oportunidad, ella ___.","input":"text","hint":"decidir"},{"prompt":"Actualmente, las generaciones ___.","input":"text","hint":"apoyarse"},{"prompt":"Ayer, nosotros ___.","input":"text","hint":"comparar"},{"prompt":"La relación ___ con el tiempo.","input":"text","hint":"fortalecer"}]}','{"items":[{"display":"llegaron","answers":["llegaron"]},{"display":"trabajaban","answers":["trabajaban"]},{"display":"han elegido","answers":["han elegido"]},{"display":"recibiría","answers":["recibiría"]},{"display":"habría decidido","answers":["habría decidido"]},{"display":"se apoyan","answers":["se apoyan"]},{"display":"comparamos","answers":["comparamos"]},{"display":"se ha fortalecido","answers":["se ha fortalecido"]}],"policy":{"accents":"strict"}}','published','L3-U17-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-familia-generaciones-y-relaciones-20','es3-familia-generaciones-y-relaciones','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Cómo enseñó la abuela la receta?","input":"sentence"},{"prompt":"¿Por qué salió mal el primer intento?","input":"sentence"},{"prompt":"¿Qué descubrieron además de mejorar el plato?","input":"sentence"},{"prompt":"¿Quién quería medir todo con precisión?","input":"sentence"},{"prompt":"¿Qué mostró la conversación sobre las generaciones?","input":"sentence"}],"text":"La abuela de Clara enseñó a sus nietos una receta familiar por videollamada. El primer intento salió mal porque cada persona había interpretado las cantidades de manera distinta. Para la segunda prueba, escribieron los pasos y compararon las medidas. Además de mejorar el plato, descubrieron historias familiares que nunca habían escuchado.\n\nLa abuela era más conservadora que sus nietos en algunas costumbres, pero fue también la más flexible cuando decidieron adaptar la receta. Clara, que suele ser independiente y exigente, quería medir todo con precisión; su hermano, más espontáneo, prefería cocinar sin instrucciones. Sin embargo, ambos fueron solidarios cuando la abuela se cansó y repartieron las tareas. Mientras mezclaban los ingredientes, ella contó que su propia madre había sido una mujer resiliente y de mente abierta. La conversación mostró que las generaciones no son categorías simples: una persona puede ser reservada en un contexto y muy comunicativa en otro. Al final, el plato quedó más equilibrado y la relación familiar también.\n\nDesde ese día, la familia repite la videollamada una vez al mes. A veces cocinan y otras veces solo conversan. Lo importante es que el encuentro permite comparar experiencias y mantener un vínculo entre personas de edades y personalidades diferentes."}','{"items":[{"display":"Por videollamada","answers":["Por videollamada"]},{"display":"Porque interpretaron las cantidades de manera distinta","answers":["Porque interpretaron las cantidades de manera distinta"]},{"display":"Historias familiares","answers":["Historias familiares"]},{"display":"Clara","answers":["Clara"]},{"display":"Que las generaciones no son categorías simples","answers":["Que las generaciones no son categorías simples"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U17-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos','es-3','es-3-people','שפה אחת, עולמות רבים','Una lengua, muchos mundos','לדבר ולכתוב על הנושא „שפה אחת, עולמות רבים“ בספרדית, תוך שימוש במבנים: Cultura, variedades del español y tiempos del pasado.','derived','[{"he":"דקדוק בשימוש","target":"Cultura, variedades del español y tiempos del pasado"},{"he":"אוצר מילים: שפה אחת, עולמות רבים","target":"Una lengua, muchos mundos"}]','["Cultura, variedades del español y tiempos del pasado"]','{"rules":[],"examples":["Sofía ha viajado por varios países.","Antes de llegar solo había estudiado español neutro.","La guía explicó que las expresiones cambian según la región.","Sofía desea conocer más variedades."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Adaptación cultural","he":"הסתגלות תרבותית"},{"term":"Ambigüedad","he":"עמימות"},{"term":"Argumentación","he":"טיעון"},{"term":"Cercanía","he":"קרבה"},{"term":"Coincidir","he":"להסכים"},{"term":"Complejidad","he":"מורכבות"},{"term":"Connotación","he":"קונוטציה"},{"term":"Contexto social","he":"הקשר חברתי"},{"term":"Contradecir","he":"לסתור"},{"term":"Convivencia","he":"קיום-דו"},{"term":"Cuestionar","he":"להטיל ספק"},{"term":"Desigualdad","he":"שוויון-אי"},{"term":"Dialecto","he":"ניב"},{"term":"Discrepar","he":"לחלוק על"},{"term":"Diversidad lingüística","he":"גיוון לשוני"},{"term":"Enriquecedor","he":"מעשיר"},{"term":"Entonación","he":"אינטונציה"},{"term":"Estereotipo","he":"סטריאוטיפ"},{"term":"Fluidez","he":"שטף דיבור"},{"term":"Formalidad","he":"רשמיות"},{"term":"Integración","he":"השתלבות"},{"term":"Interculturalidad","he":"תרבותיות-בין"},{"term":"Interpretación","he":"פרשנות"},{"term":"Jerga","he":"סלנג"},{"term":"Malentendido","he":"הבנה-אי"},{"term":"Matiz","he":"ניואנס"},{"term":"Modismo","he":"ביטוי מקומי"},{"term":"Percepción","he":"תפיסה"},{"term":"Perspectiva","he":"נקודת מבט / נקודת מבטs"},{"term":"Persuasión","he":"שכנוע"},{"term":"Prejuicio","he":"דעה קדומה"},{"term":"Razonamiento","he":"חשיבה לוגית"},{"term":"Regionalismo","he":"אזוריות לשונית"},{"term":"Replantear","he":"לנסח מחדש"},{"term":"Sensibilidad cultural","he":"רגישות תרבותית"},{"term":"Variación lingüística","he":"שונות לשונית"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1177253962/una-lengua-muchos-mundos-flash-cards/?new"}]','published','workbook L3 unit 18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-01','es3-una-lengua-muchos-mundos','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"שטף דיבור ___","input":"text"},{"prompt":"ניואנס ___","input":"text"},{"prompt":"מעשיר ___","input":"text"},{"prompt":"שוויון-אי ___","input":"text"},{"prompt":"תרבותיות-בין ___","input":"text"},{"prompt":"קונוטציה ___","input":"text"}]}','{"items":[{"display":"Fluidez","answers":["Fluidez"]},{"display":"Matiz","answers":["Matiz"]},{"display":"Enriquecedor","answers":["Enriquecedor"]},{"display":"Desigualdad","answers":["Desigualdad"]},{"display":"Interculturalidad","answers":["Interculturalidad"]},{"display":"Connotación","answers":["Connotación"]}],"policy":{"accents":"lenient"}}','published','L3-U18-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-02','es3-una-lengua-muchos-mundos','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Fluidez","Matiz","Enriquecedor","Desigualdad","Interculturalidad","Connotación","Argumentación","Replantear"],"right":[{"id":"A","text":"טיעון"},{"id":"B","text":"שטף דיבור"},{"id":"C","text":"ניואנס"},{"id":"D","text":"מעשיר"},{"id":"E","text":"קונוטציה"},{"id":"F","text":"שוויון-אי"},{"id":"G","text":"לנסח מחדש"},{"id":"H","text":"תרבותיות-בין"}]}','{"pairs":["B","C","D","F","H","E","A","G"],"policy":{"accents":"lenient"}}','published','L3-U18-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-03','es3-una-lengua-muchos-mundos','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"שטף דיבור","input":"choice","options":["Fluidez","Prejuicio","Replantear"]},{"prompt":"ניואנס","input":"choice","options":["Adaptación cultural","Matiz","Cercanía"]},{"prompt":"מעשיר","input":"choice","options":["Persuasión","Enriquecedor","Jerga"]},{"prompt":"שוויון-אי","input":"choice","options":["Convivencia","Desigualdad","Entonación"]},{"prompt":"תרבותיות-בין","input":"choice","options":["Interculturalidad","Persuasión","Cuestionar"]},{"prompt":"קונוטציה","input":"choice","options":["Argumentación","Complejidad","Connotación"]}]}','{"items":[{"display":"Fluidez","choice":0},{"display":"Matiz","choice":1},{"display":"Enriquecedor","choice":1},{"display":"Desigualdad","choice":1},{"display":"Interculturalidad","choice":0},{"display":"Connotación","choice":2}],"policy":{"accents":"lenient"}}','published','L3-U18-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-04','es3-una-lengua-muchos-mundos','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"מעשיר = ___","input":"bank"},{"prompt":"חשיבה לוגית = ___","input":"bank"},{"prompt":"קרבה = ___","input":"bank"},{"prompt":"עמימות = ___","input":"bank"},{"prompt":"תרבותיות-בין = ___","input":"bank"},{"prompt":"מורכבות = ___","input":"bank"}],"wordbank":["Enriquecedor","Interculturalidad","Razonamiento","Complejidad","Cercanía","Ambigüedad"],"text":"Sofía ha viajado por varios países hispanohablantes y ha descubierto formas distintas de hablar. En Argentina oyó el voseo, aunque antes de llegar solo había estudiado español neutro. Una guía le explicó que las expresiones cambian según la región y Sofía desea conocer todavía más variedades."}','{"items":[{"display":"Enriquecedor","answers":["Enriquecedor"]},{"display":"Razonamiento","answers":["Razonamiento"]},{"display":"Cercanía","answers":["Cercanía"]},{"display":"Ambigüedad","answers":["Ambigüedad"]},{"display":"Interculturalidad","answers":["Interculturalidad"]},{"display":"Complejidad","answers":["Complejidad"]}],"policy":{"accents":"strict"}}','published','L3-U18-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-05','es3-una-lengua-muchos-mundos','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["te","ese","Por","qué","acento","cuesta"]},{"prompt":"","input":"tokens","tokens":["series","la","en","vida","has","real","escuchado","en","Lo","o"]},{"prompt":"","input":"tokens","tokens":["gustaría","mejor","Te","aprenderlo"]},{"prompt":"","input":"tokens","tokens":["vez","otro","alguna","una","persona","con","de","hispanohablante","Has","país","hablado"]}]}','{"items":[{"display":"¿Por qué te cuesta ese acento?","answers":["¿Por qué te cuesta ese acento?"]},{"display":"¿Lo has escuchado en la vida real o en series?","answers":["¿Lo has escuchado en la vida real o en series?"]},{"display":"¿Te gustaría aprenderlo mejor?","answers":["¿Te gustaría aprenderlo mejor?"]},{"display":"¿Has hablado alguna vez con una persona de otro país hispanohablante?","answers":["¿Has hablado alguna vez con una persona de otro país hispanohablante?"]}],"policy":{"accents":"strict"}}','published','L3-U18-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-06','es3-una-lengua-muchos-mundos','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Sofía ha viajé por varios países.","input":"sentence"},{"prompt":"Antes de llegar solo estudió ya español neutro.","input":"sentence"},{"prompt":"La guía explicó que las expresiones cambiaron según la región siempre.","input":"sentence"},{"prompt":"Sofía desea que conoce más variedades.","input":"sentence"}]}','{"items":[{"display":"Sofía ha viajado por varios países.","answers":["Sofía ha viajado por varios países."]},{"display":"Antes de llegar solo había estudiado español neutro.","answers":["Antes de llegar solo había estudiado español neutro."]},{"display":"La guía explicó que las expresiones cambian según la región.","answers":["La guía explicó que las expresiones cambian según la región."]},{"display":"Sofía desea conocer más variedades.","answers":["Sofía desea conocer más variedades."]}],"policy":{"accents":"strict"}}','published','L3-U18-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-07','es3-una-lengua-muchos-mundos','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Sofía ha viajado por varios países.","Sofía ha viajé por varios países."]},{"prompt":"","input":"choice","options":["Antes de llegar solo había estudiado español neutro.","Antes de llegar solo estudió ya español neutro."]},{"prompt":"","input":"choice","options":["La guía explicó que las expresiones cambian según la región.","La guía explicó que las expresiones cambiaron según la región siempre."]},{"prompt":"","input":"choice","options":["Sofía desea conocer más variedades.","Sofía desea que conoce más variedades."]}]}','{"items":[{"display":"Sofía ha viajé por varios países.","choice":1},{"display":"Antes de llegar solo estudió ya español neutro.","choice":1},{"display":"La guía explicó que las expresiones cambiaron según la región siempre.","choice":1},{"display":"Sofía desea que conoce más variedades.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U18-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-08','es3-una-lengua-muchos-mundos','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**Sofía** · viajar · hasta hoy","input":"text"},{"prompt":"**ella** · oír · en Argentina","input":"text"},{"prompt":"**Sofía** · estudiar · antes de llegar","input":"text"},{"prompt":"**la guía** · explicar · ayer","input":"text"}]}','{"items":[{"display":"ha viajado","answers":["ha viajado"]},{"display":"oyó","answers":["oyó"]},{"display":"había estudiado","answers":["había estudiado"]},{"display":"explicó","answers":["explicó"]}],"policy":{"accents":"strict"}}','published','L3-U18-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-09','es3-una-lengua-muchos-mundos','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Por qué te cuesta ese acento?\n¿Lo has escuchado en la vida real o en series?\n¿Te gustaría aprenderlo mejor?\n¿Has hablado alguna vez con una persona de otro país hispanohablante?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U18-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-10','es3-una-lengua-muchos-mundos','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**Sofía** · viajar · hasta hoy","input":"text"},{"prompt":"**ella** · oír · en Argentina","input":"text"},{"prompt":"**Sofía** · estudiar · antes de llegar","input":"text"},{"prompt":"**la guía** · explicar · ayer","input":"text"},{"prompt":"**las expresiones** · cambiar · según la región","input":"text"},{"prompt":"**yo** · conocer · si viajara más","input":"text"},{"prompt":"**nosotros** · entender · con más práctica","input":"text"},{"prompt":"**los acentos** · escuchar · esta semana","input":"text"}]}','{"items":[{"display":"ha viajado","answers":["ha viajado"]},{"display":"oyó","answers":["oyó"]},{"display":"había estudiado","answers":["había estudiado"]},{"display":"explicó","answers":["explicó"]},{"display":"cambian","answers":["cambian"]},{"display":"conocería","answers":["conocería"]},{"display":"entenderíamos","answers":["entenderíamos"]},{"display":"han sido escuchados","answers":["han sido escuchados"]}],"policy":{"accents":"strict"}}','published','L3-U18-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-11','es3-una-lengua-muchos-mundos','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué ha descubierto Sofía?","input":"sentence"},{"prompt":"¿Qué había estudiado antes de llegar?","input":"sentence"},{"prompt":"¿Qué desea conocer?","input":"sentence"}],"text":"Sofía ha viajado por varios países hispanohablantes y ha descubierto formas distintas de hablar. En Argentina oyó el voseo, aunque antes de llegar solo había estudiado español neutro. Una guía le explicó que las expresiones cambian según la región y Sofía desea conocer todavía más variedades."}','{"items":[{"display":"Formas distintas de hablar.","answers":["Formas distintas de hablar."]},{"display":"Español neutro.","answers":["Español neutro."]},{"display":"Más variedades del español.","answers":["Más variedades del español."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U18-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-12','es3-una-lengua-muchos-mundos','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Una lengua, muchos mundos\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Sofía ha viajado por varios países hispanohablantes y ha descubierto formas distintas de hablar. En Argentina oyó el voseo, aunque antes de llegar solo había estudiado español neutro. Una guía le explicó que las expresiones cambian según la región y Sofía desea conocer todavía más variedades."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U18-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-13','es3-una-lengua-muchos-mundos','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Qué desea conocer?"},{"id":"B","text":"Pregunta: ¿Qué ha descubierto Sofía?"},{"id":"C","text":"Respuesta: Formas distintas de hablar."},{"id":"D","text":"Respuesta: Español neutro."},{"id":"E","text":"Pregunta: ¿Qué había estudiado antes de llegar?"},{"id":"F","text":"Respuesta: Más variedades del español."}]}','{"order":["B","C","E","D","A","F"],"policy":{"accents":"strict"}}','published','L3-U18-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-14','es3-una-lengua-muchos-mundos','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Una guía le explicó que las expresiones cambian según la región y Sofía desea conocer todavía más variedades."},{"id":"B","text":"En Argentina oyó el voseo, aunque antes de llegar solo había estudiado español neutro."},{"id":"C","text":"Sofía ha viajado por varios países hispanohablantes y ha descubierto formas distintas de hablar."}]}','{"order":["C","B","A"],"policy":{"accents":"strict"}}','published','L3-U18-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-15','es3-una-lengua-muchos-mundos','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre una lengua, muchos mundos es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre una lengua, muchos mundos es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U18-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-16','es3-una-lengua-muchos-mundos','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"מעשיר = ___","input":"text"},{"prompt":"שוויון-אי = ___","input":"text"},{"prompt":"תרבותיות-בין = ___","input":"text"},{"prompt":"קונוטציה = ___","input":"text"},{"prompt":"**los acentos** · escuchar · esta semana","input":"text"},{"prompt":"**nosotros** · entender · con más práctica","input":"text"},{"prompt":"**yo** · conocer · si viajara más","input":"text"},{"prompt":"**las expresiones** · cambiar · según la región","input":"text"},{"prompt":"**la guía** · explicar · ayer","input":"text"},{"prompt":"**Sofía** · estudiar · antes de llegar","input":"text"}]}','{"items":[{"display":"Enriquecedor","answers":["Enriquecedor"],"policy":{"accents":"lenient"}},{"display":"Desigualdad","answers":["Desigualdad"],"policy":{"accents":"lenient"}},{"display":"Interculturalidad","answers":["Interculturalidad"],"policy":{"accents":"lenient"}},{"display":"Connotación","answers":["Connotación"],"policy":{"accents":"lenient"}},{"display":"han sido escuchados","answers":["han sido escuchados"]},{"display":"entenderíamos","answers":["entenderíamos"]},{"display":"conocería","answers":["conocería"]},{"display":"cambian","answers":["cambian"]},{"display":"explicó","answers":["explicó"]},{"display":"había estudiado","answers":["había estudiado"]}],"policy":{"accents":"strict"}}','published','L3-U18-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-17','es3-una-lengua-muchos-mundos','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Sofía ha viajado por varios países hispanohablantes y ha descubierto formas distintas de hablar. En Argentina oyó el voseo, aunque antes de llegar solo había estudiado español neutro."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U18-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-18','es3-una-lengua-muchos-mundos','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"קיום-דו = ___","input":"bank"},{"prompt":"רשמיות = ___","input":"bank"},{"prompt":"דעה קדומה = ___","input":"bank"},{"prompt":"הבנה-אי = ___","input":"bank"},{"prompt":"שכנוע = ___","input":"bank"},{"prompt":"לסתור = ___","input":"bank"},{"prompt":"הסתגלות תרבותית = ___","input":"bank"},{"prompt":"ביטוי מקומי = ___","input":"bank"},{"prompt":"אזוריות לשונית = ___","input":"bank"},{"prompt":"הקשר חברתי = ___","input":"bank"}],"wordbank":["Malentendido","Prejuicio","Convivencia","Persuasión","Contradecir","Modismo","Regionalismo","Adaptación cultural","Formalidad","Contexto social"]}','{"items":[{"display":"Convivencia","answers":["Convivencia"]},{"display":"Formalidad","answers":["Formalidad"]},{"display":"Prejuicio","answers":["Prejuicio"]},{"display":"Malentendido","answers":["Malentendido"]},{"display":"Persuasión","answers":["Persuasión"]},{"display":"Contradecir","answers":["Contradecir"]},{"display":"Adaptación cultural","answers":["Adaptación cultural"]},{"display":"Modismo","answers":["Modismo"]},{"display":"Regionalismo","answers":["Regionalismo"]},{"display":"Contexto social","answers":["Contexto social"]}],"policy":{"accents":"strict"}}','published','L3-U18-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-19','es3-una-lengua-muchos-mundos','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Sofía ___ hasta hoy.","input":"text","hint":"viajar"},{"prompt":"Ella ___ en Argentina.","input":"text","hint":"oír"},{"prompt":"Antes de llegar, Sofía ___.","input":"text","hint":"estudiar"},{"prompt":"Ayer, la guía ___.","input":"text","hint":"explicar"},{"prompt":"Las expresiones ___ según la región.","input":"text","hint":"cambiar"},{"prompt":"Si viajara más, yo ___.","input":"text","hint":"conocer"},{"prompt":"Nosotros ___ con más práctica.","input":"text","hint":"entender"},{"prompt":"Esta semana, los acentos ___.","input":"text","hint":"escuchar"}]}','{"items":[{"display":"ha viajado","answers":["ha viajado"]},{"display":"oyó","answers":["oyó"]},{"display":"había estudiado","answers":["había estudiado"]},{"display":"explicó","answers":["explicó"]},{"display":"cambian","answers":["cambian"]},{"display":"conocería","answers":["conocería"]},{"display":"entenderíamos","answers":["entenderíamos"]},{"display":"han sido escuchados","answers":["han sido escuchados"]}],"policy":{"accents":"strict"}}','published','L3-U18-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-una-lengua-muchos-mundos-20','es3-una-lengua-muchos-mundos','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Qué palabra oyó Sofía?","input":"sentence"},{"prompt":"¿Qué dos significados tenía?","input":"sentence"},{"prompt":"¿Qué hizo para comprenderla?","input":"sentence"},{"prompt":"¿Qué creía Sofía antes del intercambio?","input":"sentence"},{"prompt":"¿Cómo cambió su manera de escuchar?","input":"sentence"}],"text":"Durante un intercambio, Sofía oyó la palabra guagua en dos países. En uno se refería a un autobús y en otro a un bebé. En vez de pensar que una forma era incorrecta, preguntó por el contexto y anotó ejemplos. Comprendió que aprender una lengua también significa aceptar que una misma palabra puede contar historias regionales diferentes.\n\nAntes del intercambio, Sofía había estudiado un español bastante neutro y creía que hablar con fluidez significaba usar siempre las mismas palabras. En el viaje descubrió regionalismos, modismos, cambios de entonación y formas de jerga que expresaban matices distintos. Un compañero le explicó que su dialecto no era una versión incorrecta, sino el resultado de una historia cultural particular. La convivencia intercultural cambió su perspectiva: dejó de imitar un solo acento y empezó a escuchar con más atención. Cuando regresó, preparó una presentación sobre diversidad lingüística y advirtió que los estereotipos pueden impedirnos comprender la riqueza de los muchos mundos que existen dentro del español.\n\nPara Sofía, la fluidez ya no consiste en borrar su acento o conocer todos los modismos. Consiste en preguntar cuando no entiende, adaptar el registro y comunicarse con respeto. Esa actitud le permite participar en más comunidades hispanohablantes."}','{"items":[{"display":"Guagua","answers":["Guagua"]},{"display":"Autobús y bebé","answers":["Autobús y bebé"]},{"display":"Preguntó por el contexto y anotó ejemplos","answers":["Preguntó por el contexto y anotó ejemplos"]},{"display":"Que hablar con fluidez significaba usar siempre las mismas palabras","answers":["Que hablar con fluidez significaba usar siempre las mismas palabras"]},{"display":"Dejó de imitar un solo acento y escuchó con más atención","answers":["Dejó de imitar un solo acento y escuchó con más atención"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U18-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje','es-3','es-3-stories','הצבא והטיול הגדול','El ejército y el gran viaje','לדבר ולכתוב על הנושא „הצבא והטיול הגדול“ בספרדית, תוך שימוש במבנים: Verbos modales, hipótesis y experiencias personales.','derived','[{"he":"דקדוק בשימוש","target":"Verbos modales, hipótesis y experiencias personales"},{"he":"אוצר מילים: הצבא והטיול הגדול","target":"El ejército y el gran viaje"}]','["Verbos modales, hipótesis y experiencias personales"]','{"rules":[],"examples":["Amir terminó el servicio y después viajó durante ocho meses.","Antes de salir, ya había ahorrado dinero.","Si se hubiera quedado, no habría aprendido tanto.","El viaje cambió sus prioridades el año pasado."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Adaptación","he":"הסתגלות"},{"term":"Argumentar","he":"לטעון"},{"term":"Cohesión social","he":"לכידות חברתית"},{"term":"Consecuencia emocional","he":"השלכה רגשית"},{"term":"Contradecir","he":"לסתור"},{"term":"Crecimiento personal","he":"התפתחות אישית"},{"term":"Criticar","he":"לבקר"},{"term":"Cuestionar","he":"להטיל ספק"},{"term":"Desconectarse","he":"להתנתק"},{"term":"Desigualdad","he":"שוויון-אי"},{"term":"Enfrentarse","he":"להתמודד"},{"term":"Estereotipo","he":"סטריאוטיפ"},{"term":"Expectativa social","he":"ציפייה חברתית"},{"term":"Experiencia compartida","he":"חוויה משותפת"},{"term":"Identidad nacional","he":"זהות לאומית"},{"term":"Integración social","he":"השתלבות חברתית"},{"term":"Jerarquía","he":"היררכיה"},{"term":"Justificar","he":"לנמק / להצדיק / להצדיק"},{"term":"Libertad individual","he":"חופש אישי"},{"term":"Madurez emocional","he":"בגרות רגשית"},{"term":"Militarización","he":"מיליטריזציה"},{"term":"Obligatorio","he":"חובה"},{"term":"Patriotismo","he":"פטריוטיות"},{"term":"Perspectiva","he":"נקודת מבט / נקודת מבטs"},{"term":"Persuadir","he":"לשכנע"},{"term":"Presión social","he":"לחץ חברתי"},{"term":"Prestigioso","he":"יוקרתי"},{"term":"Procesar emociones","he":"לעבד רגשות"},{"term":"Reclutamiento","he":"גיוס"},{"term":"Reflexionar","he":"להרהר"},{"term":"Responsabilidad colectiva","he":"אחריות קולקטיבית"},{"term":"Sensibilidad","he":"רגישות"},{"term":"Sentido de pertenencia","he":"תחושת שייכות"},{"term":"Servicio nacional","he":"שירות לאומי"},{"term":"Transición","he":"מעבר"},{"term":"Unidad militar","he":"יחידה צבאית"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1177274224/el-ejercito-y-el-gran-viaje-flash-cards/?new"}]','published','workbook L3 unit 19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-01','es3-el-ejercito-y-el-gran-viaje','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"אחריות קולקטיבית ___","input":"text"},{"prompt":"לכידות חברתית ___","input":"text"},{"prompt":"רגישות ___","input":"text"},{"prompt":"גיוס ___","input":"text"},{"prompt":"השלכה רגשית ___","input":"text"},{"prompt":"לעבד רגשות ___","input":"text"}]}','{"items":[{"display":"Responsabilidad colectiva","answers":["Responsabilidad colectiva"]},{"display":"Cohesión social","answers":["Cohesión social"]},{"display":"Sensibilidad","answers":["Sensibilidad"]},{"display":"Reclutamiento","answers":["Reclutamiento"]},{"display":"Consecuencia emocional","answers":["Consecuencia emocional"]},{"display":"Procesar emociones","answers":["Procesar emociones"]}],"policy":{"accents":"lenient"}}','published','L3-U19-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-02','es3-el-ejercito-y-el-gran-viaje','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Responsabilidad colectiva","Cohesión social","Sensibilidad","Reclutamiento","Consecuencia emocional","Procesar emociones","Patriotismo","Experiencia compartida"],"right":[{"id":"A","text":"אחריות קולקטיבית"},{"id":"B","text":"לכידות חברתית"},{"id":"C","text":"פטריוטיות"},{"id":"D","text":"לעבד רגשות"},{"id":"E","text":"רגישות"},{"id":"F","text":"חוויה משותפת"},{"id":"G","text":"גיוס"},{"id":"H","text":"השלכה רגשית"}]}','{"pairs":["A","B","E","G","H","D","C","F"],"policy":{"accents":"lenient"}}','published','L3-U19-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-03','es3-el-ejercito-y-el-gran-viaje','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"אחריות קולקטיבית","input":"choice","options":["Responsabilidad colectiva","Justificar","Jerarquía"]},{"prompt":"לכידות חברתית","input":"choice","options":["Consecuencia emocional","Crecimiento personal","Cohesión social"]},{"prompt":"רגישות","input":"choice","options":["Desconectarse","Transición","Sensibilidad"]},{"prompt":"גיוס","input":"choice","options":["Argumentar","Reclutamiento","Experiencia compartida"]},{"prompt":"השלכה רגשית","input":"choice","options":["Consecuencia emocional","Sensibilidad","Militarización"]},{"prompt":"לעבד רגשות","input":"choice","options":["Servicio nacional","Cuestionar","Procesar emociones"]}]}','{"items":[{"display":"Responsabilidad colectiva","choice":0},{"display":"Cohesión social","choice":2},{"display":"Sensibilidad","choice":2},{"display":"Reclutamiento","choice":1},{"display":"Consecuencia emocional","choice":0},{"display":"Procesar emociones","choice":2}],"policy":{"accents":"lenient"}}','published','L3-U19-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-04','es3-el-ejercito-y-el-gran-viaje','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"חוויה משותפת = ___","input":"bank"},{"prompt":"לטעון = ___","input":"bank"},{"prompt":"להרהר = ___","input":"bank"},{"prompt":"להצדיק = ___","input":"bank"},{"prompt":"זהות לאומית = ___","input":"bank"},{"prompt":"לסתור = ___","input":"bank"}],"wordbank":["Reflexionar","Argumentar","Contradecir","Justificar","Identidad nacional","Experiencia compartida"],"text":"Amir terminó el servicio militar y después viajó durante ocho meses. Antes de salir, había ahorrado dinero y había planeado una ruta flexible. El viaje cambió sus prioridades; si se hubiera quedado en casa, no habría aprendido a tomar decisiones con tanta independencia."}','{"items":[{"display":"Experiencia compartida","answers":["Experiencia compartida"]},{"display":"Argumentar","answers":["Argumentar"]},{"display":"Reflexionar","answers":["Reflexionar"]},{"display":"Justificar","answers":["Justificar"]},{"display":"Identidad nacional","answers":["Identidad nacional"]},{"display":"Contradecir","answers":["Contradecir"]}],"policy":{"accents":"strict"}}','published','L3-U19-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-05','es3-el-ejercito-y-el-gran-viaje','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["puede","a","Qué","los","años","18","entrar","impacto","psicológico","tener","al","ejército"]},{"prompt":"","input":"tokens","tokens":["servicio","suelen","realistas","Crees","expectativas","antes","ser","del","que","las"]},{"prompt":"","input":"tokens","tokens":["Qué","experimentar","puede","internos","esta","persona","conflictos"]},{"prompt":"","input":"tokens","tokens":["experiencia","su","social","influye","familiar","o","el","entorno","Cómo","en"]}]}','{"items":[{"display":"¿Qué impacto psicológico puede tener entrar al ejército a los 18 años?","answers":["¿Qué impacto psicológico puede tener entrar al ejército a los 18 años?"]},{"display":"¿Crees que las expectativas antes del servicio suelen ser realistas?","answers":["¿Crees que las expectativas antes del servicio suelen ser realistas?"]},{"display":"¿Qué conflictos internos puede experimentar esta persona?","answers":["¿Qué conflictos internos puede experimentar esta persona?"]},{"display":"¿Cómo influye el entorno social o familiar en su experiencia?","answers":["¿Cómo influye el entorno social o familiar en su experiencia?"]}],"policy":{"accents":"strict"}}','published','L3-U19-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-06','es3-el-ejercito-y-el-gran-viaje','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"Amir terminó el servicio y después había viajado ocho meses.","input":"sentence"},{"prompt":"Antes de salir, ahorró ya dinero.","input":"sentence"},{"prompt":"Si se hubiera quedado, no aprendería entonces tanto.","input":"sentence"},{"prompt":"El viaje le ha cambiado sus prioridades el año pasado.","input":"sentence"}]}','{"items":[{"display":"Amir terminó el servicio y después viajó durante ocho meses.","answers":["Amir terminó el servicio y después viajó durante ocho meses."]},{"display":"Antes de salir, ya había ahorrado dinero.","answers":["Antes de salir, ya había ahorrado dinero."]},{"display":"Si se hubiera quedado, no habría aprendido tanto.","answers":["Si se hubiera quedado, no habría aprendido tanto."]},{"display":"El viaje cambió sus prioridades el año pasado.","answers":["El viaje cambió sus prioridades el año pasado."]}],"policy":{"accents":"strict"}}','published','L3-U19-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-07','es3-el-ejercito-y-el-gran-viaje','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["Amir terminó el servicio y después había viajado ocho meses.","Amir terminó el servicio y después viajó durante ocho meses."]},{"prompt":"","input":"choice","options":["Antes de salir, ya había ahorrado dinero.","Antes de salir, ahorró ya dinero."]},{"prompt":"","input":"choice","options":["Si se hubiera quedado, no habría aprendido tanto.","Si se hubiera quedado, no aprendería entonces tanto."]},{"prompt":"","input":"choice","options":["El viaje cambió sus prioridades el año pasado.","El viaje le ha cambiado sus prioridades el año pasado."]}]}','{"items":[{"display":"Amir terminó el servicio y después viajó durante ocho meses.","choice":1},{"display":"Antes de salir, ahorró ya dinero.","choice":1},{"display":"Si se hubiera quedado, no aprendería entonces tanto.","choice":1},{"display":"El viaje le ha cambiado sus prioridades el año pasado.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U19-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-08','es3-el-ejercito-y-el-gran-viaje','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**Amir** · terminar · antes del viaje","input":"text"},{"prompt":"**él** · viajar · después del servicio","input":"text"},{"prompt":"**Amir** · ahorrar · antes de salir","input":"text"},{"prompt":"**él** · planear · antes del viaje","input":"text"}]}','{"items":[{"display":"terminó","answers":["terminó"]},{"display":"viajó","answers":["viajó"]},{"display":"había ahorrado","answers":["había ahorrado"]},{"display":"había planeado","answers":["había planeado"]}],"policy":{"accents":"strict"}}','published','L3-U19-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-09','es3-el-ejercito-y-el-gran-viaje','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Por qué?\n¿Qué impacto psicológico puede tener entrar al ejército a los 18 años?\n¿Crees que las expectativas antes del servicio suelen ser realistas?\n¿Qué conflictos internos puede experimentar esta persona?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U19-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-10','es3-el-ejercito-y-el-gran-viaje','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**Amir** · terminar · antes del viaje","input":"text"},{"prompt":"**él** · viajar · después del servicio","input":"text"},{"prompt":"**Amir** · ahorrar · antes de salir","input":"text"},{"prompt":"**él** · planear · antes del viaje","input":"text"},{"prompt":"**el viaje** · cambiar · el año pasado","input":"text"},{"prompt":"**Amir** · quedarse · si no hubiera viajado","input":"text"},{"prompt":"**él** · aprender · en ese caso negativo","input":"text"},{"prompt":"**nosotros** · recomendar · actualmente","input":"text"}]}','{"items":[{"display":"terminó","answers":["terminó"]},{"display":"viajó","answers":["viajó"]},{"display":"había ahorrado","answers":["había ahorrado"]},{"display":"había planeado","answers":["había planeado"]},{"display":"cambió","answers":["cambió"]},{"display":"se habría quedado","answers":["se habría quedado"]},{"display":"no habría aprendido","answers":["no habría aprendido"]},{"display":"recomendamos","answers":["recomendamos"]}],"policy":{"accents":"strict"}}','published','L3-U19-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-11','es3-el-ejercito-y-el-gran-viaje','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué hizo Amir después del servicio?","input":"sentence"},{"prompt":"¿Qué había hecho antes de salir?","input":"sentence"},{"prompt":"¿Qué aprendió durante el viaje?","input":"sentence"}],"text":"Amir terminó el servicio militar y después viajó durante ocho meses. Antes de salir, había ahorrado dinero y había planeado una ruta flexible. El viaje cambió sus prioridades; si se hubiera quedado en casa, no habría aprendido a tomar decisiones con tanta independencia."}','{"items":[{"display":"Viajó durante ocho meses.","answers":["Viajó durante ocho meses."]},{"display":"Había ahorrado dinero y había planeado una ruta.","answers":["Había ahorrado dinero y había planeado una ruta."]},{"display":"A tomar decisiones con independencia.","answers":["A tomar decisiones con independencia."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U19-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-12','es3-el-ejercito-y-el-gran-viaje','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** El ejército y el gran viaje\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Amir terminó el servicio militar y después viajó durante ocho meses. Antes de salir, había ahorrado dinero y había planeado una ruta flexible. El viaje cambió sus prioridades; si se hubiera quedado en casa, no habría aprendido a tomar decisiones con tanta independencia."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U19-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-13','es3-el-ejercito-y-el-gran-viaje','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Respuesta: Viajó durante ocho meses."},{"id":"B","text":"Respuesta: Había ahorrado dinero y había planeado una ruta."},{"id":"C","text":"Pregunta: ¿Qué aprendió durante el viaje?"},{"id":"D","text":"Respuesta: A tomar decisiones con independencia."},{"id":"E","text":"Pregunta: ¿Qué había hecho antes de salir?"},{"id":"F","text":"Pregunta: ¿Qué hizo Amir después del servicio?"}]}','{"order":["F","A","E","B","C","D"],"policy":{"accents":"strict"}}','published','L3-U19-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-14','es3-el-ejercito-y-el-gran-viaje','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Antes de salir, había ahorrado dinero y había planeado una ruta flexible."},{"id":"B","text":"El viaje cambió sus prioridades; si se hubiera quedado en casa, no habría aprendido a tomar decisiones con tanta independencia."},{"id":"C","text":"Amir terminó el servicio militar y después viajó durante ocho meses."}]}','{"order":["C","A","B"],"policy":{"accents":"strict"}}','published','L3-U19-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-15','es3-el-ejercito-y-el-gran-viaje','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre el ejército y el gran viaje es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre el ejército y el gran viaje es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U19-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-16','es3-el-ejercito-y-el-gran-viaje','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"רגישות = ___","input":"text"},{"prompt":"גיוס = ___","input":"text"},{"prompt":"השלכה רגשית = ___","input":"text"},{"prompt":"לעבד רגשות = ___","input":"text"},{"prompt":"**nosotros** · recomendar · actualmente","input":"text"},{"prompt":"**él** · aprender · en ese caso negativo","input":"text"},{"prompt":"**Amir** · quedarse · si no hubiera viajado","input":"text"},{"prompt":"**el viaje** · cambiar · el año pasado","input":"text"},{"prompt":"**él** · planear · antes del viaje","input":"text"},{"prompt":"**Amir** · ahorrar · antes de salir","input":"text"}]}','{"items":[{"display":"Sensibilidad","answers":["Sensibilidad"],"policy":{"accents":"lenient"}},{"display":"Reclutamiento","answers":["Reclutamiento"],"policy":{"accents":"lenient"}},{"display":"Consecuencia emocional","answers":["Consecuencia emocional"],"policy":{"accents":"lenient"}},{"display":"Procesar emociones","answers":["Procesar emociones"],"policy":{"accents":"lenient"}},{"display":"recomendamos","answers":["recomendamos"]},{"display":"no habría aprendido","answers":["no habría aprendido"]},{"display":"se habría quedado","answers":["se habría quedado"]},{"display":"cambió","answers":["cambió"]},{"display":"había planeado","answers":["había planeado"]},{"display":"había ahorrado","answers":["había ahorrado"]}],"policy":{"accents":"strict"}}','published','L3-U19-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-17','es3-el-ejercito-y-el-gran-viaje','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Amir terminó el servicio militar y después viajó durante ocho meses. Antes de salir, había ahorrado dinero y había planeado una ruta flexible."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U19-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-18','es3-el-ejercito-y-el-gran-viaje','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"Grupo A: Debe defender el servicio militar ___.","input":"bank"},{"prompt":"¿Cómo influye esta etapa en la ___ hacia la vida adulta?","input":"bank"},{"prompt":"¿Qué diferencias existen entre patriotismo y ___?","input":"bank"},{"prompt":"¿Crees que el servicio militar acelera la ___?","input":"bank"},{"prompt":"ציפייה חברתית = ___","input":"bank"},{"prompt":"חופש אישי = ___","input":"bank"},{"prompt":"לשכנע = ___","input":"bank"},{"prompt":"השתלבות חברתית = ___","input":"bank"},{"prompt":"להתנתק = ___","input":"bank"},{"prompt":"זהות לאומית = ___","input":"bank"}],"wordbank":["Obligatorio","Presión social","Transición","Integración social","Libertad individual","Desconectarse","Madurez emocional","Expectativa social","Persuadir","Identidad nacional"]}','{"items":[{"display":"Obligatorio","answers":["Obligatorio"]},{"display":"Transición","answers":["Transición"]},{"display":"Presión social","answers":["Presión social"]},{"display":"Madurez emocional","answers":["Madurez emocional"]},{"display":"Expectativa social","answers":["Expectativa social"]},{"display":"Libertad individual","answers":["Libertad individual"]},{"display":"Persuadir","answers":["Persuadir"]},{"display":"Integración social","answers":["Integración social"]},{"display":"Desconectarse","answers":["Desconectarse"]},{"display":"Identidad nacional","answers":["Identidad nacional"]}],"policy":{"accents":"strict"}}','published','L3-U19-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-19','es3-el-ejercito-y-el-gran-viaje','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Antes del viaje, Amir ___.","input":"text","hint":"terminar"},{"prompt":"Él ___ después del servicio.","input":"text","hint":"viajar"},{"prompt":"Antes de salir, Amir ___.","input":"text","hint":"ahorrar"},{"prompt":"Antes del viaje, él ___.","input":"text","hint":"planear"},{"prompt":"El año pasado, el viaje ___.","input":"text","hint":"cambiar"},{"prompt":"Si no hubiera viajado, Amir ___.","input":"text","hint":"quedarse"},{"prompt":"Él ___ en ese caso negativo.","input":"text","hint":"aprender"},{"prompt":"Actualmente, nosotros ___.","input":"text","hint":"recomendar"}]}','{"items":[{"display":"terminó","answers":["terminó"]},{"display":"viajó","answers":["viajó"]},{"display":"había ahorrado","answers":["había ahorrado"]},{"display":"había planeado","answers":["había planeado"]},{"display":"cambió","answers":["cambió"]},{"display":"se habría quedado","answers":["se habría quedado"]},{"display":"no habría aprendido","answers":["no habría aprendido"]},{"display":"recomendamos","answers":["recomendamos"]}],"policy":{"accents":"strict"}}','published','L3-U19-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-el-ejercito-y-el-gran-viaje-20','es3-el-ejercito-y-el-gran-viaje','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Dónde trabajó Daniel?","input":"sentence"},{"prompt":"¿Qué perdió?","input":"sentence"},{"prompt":"¿Qué aprendió de la experiencia?","input":"sentence"},{"prompt":"¿Qué obligaciones tenía Daniel en el hostal?","input":"sentence"},{"prompt":"¿Qué visión podría haber mantenido si no hubiera viajado?","input":"sentence"}],"text":"Después del servicio militar, Daniel viajó por Sudamérica y trabajó unas semanas en un hostal. Un día perdió el pasaporte y tuvo que reorganizar toda la ruta. Contactó con el consulado, presentó una denuncia y recibió un documento provisional. La experiencia fue estresante, pero le enseñó a guardar copias digitales de sus documentos.\n\nDurante el viaje, Daniel tuvo que adaptarse a normas y responsabilidades muy diferentes de las del servicio. Podía cambiar de ruta, pero debía respetar los horarios del hostal y tenía que colaborar con viajeros de muchos países. Algunos amigos afirmaban que el reclutamiento obligatorio les había dado madurez emocional y cohesión social; otros criticaban la militarización y la presión social. Daniel piensa que ambas perspectivas deben ser escuchadas. Si no hubiera viajado después del ejército, quizá habría mantenido una visión más limitada de la identidad nacional. También cree que la integración social no debería depender de una sola experiencia y que la responsabilidad colectiva puede expresarse de muchas maneras.\n\nAl regresar, Daniel compartió su experiencia con jóvenes que estaban a punto de comenzar el servicio. No intentó decirles qué debían pensar. Prefirió presentar preguntas y mostrar que la madurez también implica revisar las propias opiniones."}','{"items":[{"display":"En un hostal","answers":["En un hostal"]},{"display":"El pasaporte","answers":["El pasaporte"]},{"display":"A guardar copias digitales de sus documentos","answers":["A guardar copias digitales de sus documentos"]},{"display":"Respetar los horarios y colaborar con otros viajeros","answers":["Respetar los horarios y colaborar con otros viajeros"]},{"display":"Una visión más limitada de la identidad nacional","answers":["Una visión más limitada de la identidad nacional"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U19-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina','es-3','es-3-people','מטבח ואוכל','Cocina','לדבר ולכתוב על הנושא „מטבח ואוכל“ בספרדית, תוך שימוש במבנים: Experiencias, recomendaciones, obligación y subjuntivo.','derived','[{"he":"דקדוק בשימוש","target":"Experiencias, recomendaciones, obligación y subjuntivo"},{"he":"אוצר מילים: מטבח ואוכל","target":"Cocina"}]','["Experiencias, recomendaciones, obligación y subjuntivo"]','{"rules":[],"examples":["La chef ha creado un menú nuevo.","Antes de abrir, ya había probado cada plato.","Los ingredientes son preparados localmente.","La chef recomienda que los clientes prueben el menú."],"tips":[],"mistakes":[],"examples_source":"corrections"}','[{"term":"Acogedor","he":"חמים / נעים"},{"term":"Adaptar un plato","he":"להתאים מנה"},{"term":"Ahumado","he":"מעושן"},{"term":"Artesanal","he":"עבודת יד / אומנותי"},{"term":"Casero","he":"ביתי"},{"term":"Condimentado","he":"מתובל"},{"term":"Cremoso","he":"קרמי"},{"term":"Crujiente","he":"פריך"},{"term":"Degustar","he":"להתענג על טעם / לטעום"},{"term":"Devolver un plato","he":"להחזיר מנה"},{"term":"El aroma","he":"הריח / הארומה"},{"term":"El desperdicio alimentario","he":"בזבוז מזון"},{"term":"El establecimiento","he":"המקום / העסק"},{"term":"El ingrediente","he":"המרכיב"},{"term":"El paladar","he":"החך"},{"term":"Exigente","he":"תובעני"},{"term":"Gourmet","he":"גורמה"},{"term":"Innovador","he":"חדשני"},{"term":"Inolvidable","he":"בלתי נשכח"},{"term":"La autenticidad","he":"אותנטיות"},{"term":"La cadena de restaurantes","he":"רשת מסעדות"},{"term":"La cocina fusión","he":"מטבח פיוז''ן"},{"term":"La comida callejera","he":"אוכל רחוב"},{"term":"La contaminación cruzada","he":"זיהום צולב"},{"term":"La especialidad","he":"ההתמחות / מנת הדגל"},{"term":"La experiencia gastronómica","he":"חוויה קולינרית"},{"term":"La gastronomía","he":"קולינריה / גסטרונומיה"},{"term":"La globalización","he":"גלובליזציה"},{"term":"La receta","he":"המתכון"},{"term":"La reseña","he":"ביקורת"},{"term":"La textura","he":"המרקם"},{"term":"Picante","he":"חריף"},{"term":"Recomendar","he":"להמליץ"},{"term":"Sobrevalorado","he":"מוערך יתר על המידה"},{"term":"Sofisticado","he":"מתוחכם"},{"term":"Tradicional","he":"מסורתי"}]','[]','[{"label":"כרטיסיות Quizlet של הנושא (אתר חיצוני)","url":"https://quizlet.com/br/1184518212/cocina-flash-cards/?new"}]','published','workbook L3 unit 20',20,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-01','es3-cocina','recall','vocab','שליפה מהזיכרון','כתבו בספרדית בלי להיעזר במילון. בדקו במשוב רק לאחר שסיימתם וסמנו מילה אחת לחזרה מחר.','auto','{"items":[{"prompt":"להתאים מנה ___","input":"text"},{"prompt":"בזבוז מזון ___","input":"text"},{"prompt":"קולינריה / גסטרונומיה ___","input":"text"},{"prompt":"זיהום צולב ___","input":"text"},{"prompt":"המתכון ___","input":"text"},{"prompt":"גלובליזציה ___","input":"text"}]}','{"items":[{"display":"Adaptar un plato","answers":["Adaptar un plato"]},{"display":"El desperdicio alimentario","answers":["El desperdicio alimentario"]},{"display":"La gastronomía","answers":["La gastronomía"]},{"display":"La contaminación cruzada","answers":["La contaminación cruzada"]},{"display":"La receta","answers":["La receta"]},{"display":"La globalización","answers":["La globalización"]}],"policy":{"accents":"lenient"}}','published','L3-U20-E1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-02','es3-cocina','match','vocab','התאמה מדויקת','התאימו בין הספרדית לעברית. כל אות משמשת פעם אחת.','auto','{"left":["Adaptar un plato","El desperdicio alimentario","La gastronomía","La contaminación cruzada","La receta","La globalización","La experiencia gastronómica","El ingrediente"],"right":[{"id":"A","text":"קולינריה / גסטרונומיה"},{"id":"B","text":"זיהום צולב"},{"id":"C","text":"המרכיב"},{"id":"D","text":"גלובליזציה"},{"id":"E","text":"להתאים מנה"},{"id":"F","text":"חוויה קולינרית"},{"id":"G","text":"המתכון"},{"id":"H","text":"בזבוז מזון"}]}','{"pairs":["E","H","A","B","G","D","F","C"],"policy":{"accents":"lenient"}}','published','L3-U20-E2',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-03','es3-cocina','choice','vocab','בחירה מהירה','בחרו את המילה המתאימה ביותר. בסיום השוו למשוב ותקנו כל תשובה שגויה.','auto','{"items":[{"prompt":"להתאים מנה","input":"choice","options":["El desperdicio alimentario","Sofisticado","Adaptar un plato"]},{"prompt":"בזבוז מזון","input":"choice","options":["La receta","El desperdicio alimentario","Exigente"]},{"prompt":"קולינריה / גסטרונומיה","input":"choice","options":["El establecimiento","Sobrevalorado","La gastronomía"]},{"prompt":"זיהום צולב","input":"choice","options":["La comida callejera","Ahumado","La contaminación cruzada"]},{"prompt":"המתכון","input":"choice","options":["Crujiente","La autenticidad","La receta"]},{"prompt":"גלובליזציה","input":"choice","options":["Ahumado","Crujiente","La globalización"]}]}','{"items":[{"display":"Adaptar un plato","choice":2},{"display":"El desperdicio alimentario","choice":1},{"display":"La gastronomía","choice":2},{"display":"La contaminación cruzada","choice":2},{"display":"La receta","choice":2},{"display":"La globalización","choice":2}],"policy":{"accents":"lenient"}}','published','L3-U20-E3',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-04','es3-cocina','bank','vocab','אוצר מילים בתוך הקשר','השלימו את קטע הקריאה מן המחסן. אם נוספו רמזים בעברית, כתבו לידם את המילה המתאימה בספרדית.','auto','{"items":[{"prompt":"להמליץ = ___","input":"bank"},{"prompt":"מתובל = ___","input":"bank"},{"prompt":"חמים / נעים = ___","input":"bank"},{"prompt":"להתענג על טעם / לטעום = ___","input":"bank"},{"prompt":"אותנטיות = ___","input":"bank"},{"prompt":"קולינריה / גסטרונומיה = ___","input":"bank"}],"wordbank":["Acogedor","La gastronomía","Recomendar","Condimentado","La autenticidad","Degustar"],"text":"Una chef ha creado un menú que combina recetas familiares con técnicas modernas. Antes de abrir el restaurante, había probado cada plato muchas veces. Los ingredientes son preparados localmente y la chef recomienda que los clientes prueben el menú de temporada."}','{"items":[{"display":"Recomendar","answers":["Recomendar"]},{"display":"Condimentado","answers":["Condimentado"]},{"display":"Acogedor","answers":["Acogedor"]},{"display":"Degustar","answers":["Degustar"]},{"display":"La autenticidad","answers":["La autenticidad"]},{"display":"La gastronomía","answers":["La gastronomía"]}],"policy":{"accents":"strict"}}','published','L3-U20-E4',3,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-05','es3-cocina','wordorder','grammar','מרכיבים את השאלה','סדרו את המילים לשאלה תקינה והוסיפו סימני שאלה. לאחר הבדיקה קראו כל שאלה בקול.','auto','{"items":[{"prompt":"","input":"tokens","tokens":["Qué","impedido","te","ha","hacerlo"]},{"prompt":"","input":"tokens","tokens":["difícil","más","Cuál","preparado","que","has","es","tu","en","receta","la","vida"]},{"prompt":"","input":"tokens","tokens":["Qué","a","has","volverás","probado","que","sabes","nunca","comer","y","comida"]},{"prompt":"","input":"tokens","tokens":["plato","de","nacional","Qué","considerarse","Israel","el","plato","podría"]}]}','{"items":[{"display":"¿Qué te ha impedido hacerlo?","answers":["¿Qué te ha impedido hacerlo?"]},{"display":"¿Cuál es la receta más difícil que has preparado en tu vida?","answers":["¿Cuál es la receta más difícil que has preparado en tu vida?"]},{"display":"¿Qué comida has probado y sabes que nunca volverás a comer?","answers":["¿Qué comida has probado y sabes que nunca volverás a comer?"]},{"display":"¿Qué plato podría considerarse el plato nacional de Israel?","answers":["¿Qué plato podría considerarse el plato nacional de Israel?"]}],"policy":{"accents":"strict"}}','published','L3-U20-E5',4,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-06','es3-cocina','correction','grammar','מרפאת שגיאות','בכל משפט יש שגיאה אחת מרכזית. מצאו אותה וכתבו גרסה מתוקנת. סמנו במשוב את המילה או המבנה שהשתנה.','auto','{"items":[{"prompt":"La chef ha creó un menú nuevo.","input":"sentence"},{"prompt":"Antes de abrir, probó ya cada plato.","input":"sentence"},{"prompt":"Los ingredientes son preparar localmente.","input":"sentence"},{"prompt":"La chef recomienda que los clientes prueban el menú.","input":"sentence"}]}','{"items":[{"display":"La chef ha creado un menú nuevo.","answers":["La chef ha creado un menú nuevo."]},{"display":"Antes de abrir, ya había probado cada plato.","answers":["Antes de abrir, ya había probado cada plato."]},{"display":"Los ingredientes son preparados localmente.","answers":["Los ingredientes son preparados localmente."]},{"display":"La chef recomienda que los clientes prueben el menú.","answers":["La chef recomienda que los clientes prueben el menú."]}],"policy":{"accents":"strict"}}','published','L3-U20-E6',5,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-07','es3-cocina','choice','grammar','מזהים את המשפט התקין','בכל זוג בחרו את המשפט התקין.','auto','{"items":[{"prompt":"","input":"choice","options":["La chef ha creado un menú nuevo.","La chef ha creó un menú nuevo."]},{"prompt":"","input":"choice","options":["Antes de abrir, probó ya cada plato.","Antes de abrir, ya había probado cada plato."]},{"prompt":"","input":"choice","options":["Los ingredientes son preparados localmente.","Los ingredientes son preparar localmente."]},{"prompt":"","input":"choice","options":["La chef recomienda que los clientes prueben el menú.","La chef recomienda que los clientes prueban el menú."]}]}','{"items":[{"display":"La chef ha creó un menú nuevo.","choice":1},{"display":"Antes de abrir, ya había probado cada plato.","choice":1},{"display":"Los ingredientes son preparar localmente.","choice":1},{"display":"La chef recomienda que los clientes prueban el menú.","choice":1}],"policy":{"accents":"strict"}}','published','L3-U20-E7',6,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-08','es3-cocina','conjugation','grammar','מטים את הפועל','כתבו בעצמכם את צורת הפועל המתאימה לנושא ולרמז הזמן.','auto','{"items":[{"prompt":"**la chef** · crear · este año","input":"text"},{"prompt":"**ella** · probar · antes de abrir","input":"text"},{"prompt":"**los ingredientes** · preparar · actualmente","input":"text"},{"prompt":"**los clientes** · probar · la chef recomienda que","input":"text"}]}','{"items":[{"display":"ha creado","answers":["ha creado"]},{"display":"había probado","answers":["había probado"]},{"display":"son preparados","answers":["son preparados"]},{"display":"prueben","answers":["prueben"]}],"policy":{"accents":"strict"}}','published','L3-U20-E7',7,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-09','es3-cocina','open','speaking','שאלות אישיות מודרכות','ענו לבד בספרדית. כתבו לפחות שני משפטים לכל שאלה: תשובה ישירה ועוד פרט, סיבה או דוגמה. לאחר מכן השתמשו ברשימת הבדיקה שבמשוב.','self','{"prompt":"¿Por qué?\n¿Cómo fue?\n¿Qué te ha impedido hacerlo?\n¿Cuál es la receta más difícil que has preparado en tu vida?","brief":""}','{"models":[],"criteria":"בכל תשובה יש פועל מוטה, תשובה ישירה ופרט נוסף. בדקו התאמה לזמן שבשאלה, סדר מילים וסימני פיסוק.\nModelo de estructura: En mi caso, ... . Esto es importante porque ... . Además, ... ."}','published','L3-U20-E8',8,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-10','es3-cocina','conjugation','grammar','מעבדת הטיית פעלים','הטו את הפועל לפי הנושא ולפי רמז הזמן או ההקשר. כתבו את כל המבנה, כולל כינוי חוזר או מילת עזר כשצריך.','auto','{"items":[{"prompt":"**la chef** · crear · este año","input":"text"},{"prompt":"**ella** · probar · antes de abrir","input":"text"},{"prompt":"**los ingredientes** · preparar · actualmente","input":"text"},{"prompt":"**los clientes** · probar · la chef recomienda que","input":"text"},{"prompt":"**un cliente** · pedir · ahora","input":"text"},{"prompt":"**yo** · recomendar · si me preguntaran","input":"text"},{"prompt":"**ellos** · devolver · ayer","input":"text"},{"prompt":"**el restaurante** · reconocer · este mes","input":"text"}]}','{"items":[{"display":"ha creado","answers":["ha creado"]},{"display":"había probado","answers":["había probado"]},{"display":"son preparados","answers":["son preparados"]},{"display":"prueben","answers":["prueben"]},{"display":"pide","answers":["pide"]},{"display":"recomendaría","answers":["recomendaría"]},{"display":"devolvieron","answers":["devolvieron"]},{"display":"ha sido reconocido","answers":["ha sido reconocido"]}],"policy":{"accents":"strict"}}','published','L3-U20-E9',9,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-11','es3-cocina','reading','reading','קריאה קצרה עם ראיות','קראו, ענו בספרדית וסמנו בטקסט את המילים שמוכיחות כל תשובה.','auto','{"items":[{"prompt":"¿Qué combina el menú?","input":"sentence"},{"prompt":"¿Qué había hecho la chef antes de abrir?","input":"sentence"},{"prompt":"¿Qué recomienda a los clientes?","input":"sentence"}],"text":"Una chef ha creado un menú que combina recetas familiares con técnicas modernas. Antes de abrir el restaurante, había probado cada plato muchas veces. Los ingredientes son preparados localmente y la chef recomienda que los clientes prueben el menú de temporada."}','{"items":[{"display":"Recetas familiares y técnicas modernas.","answers":["Recetas familiares y técnicas modernas."]},{"display":"Había probado cada plato muchas veces.","answers":["Había probado cada plato muchas veces."]},{"display":"Que prueben el menú de temporada.","answers":["Que prueben el menú de temporada."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U20-E10',10,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-12','es3-cocina','open','writing','כתיבה מודרכת','כתבו 70 עד 100 מילים. השתמשו בשש מילים מן המילון, בשני מקשרים ובמבנה הדקדוקי של הנושא. השוו לדוגמה ולרשימת הבדיקה שבמשוב.','self','{"prompt":"","brief":"**Tema:** Cocina\n**Conectores:** primero · después · sin embargo · por eso · al final"}','{"models":["Una chef ha creado un menú que combina recetas familiares con técnicas modernas. Antes de abrir el restaurante, había probado cada plato muchas veces. Los ingredientes son preparados localmente y la chef recomienda que los clientes prueben el menú de temporada."],"criteria":"70 עד 100 מילים, 6 מילות נושא, 2 מקשרים, מבנה הדקדוק של הנושא, פתיחה ברורה וסיום."}','published','L3-U20-E11',11,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-13','es3-cocina','order','communication','מסדרים דו־שיח','סדרו את שש השורות כך שכל שאלה תופיע לפני התשובה המתאימה. כתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Pregunta: ¿Qué había hecho la chef antes de abrir?"},{"id":"B","text":"Respuesta: Que prueben el menú de temporada."},{"id":"C","text":"Pregunta: ¿Qué recomienda a los clientes?"},{"id":"D","text":"Respuesta: Había probado cada plato muchas veces."},{"id":"E","text":"Pregunta: ¿Qué combina el menú?"},{"id":"F","text":"Respuesta: Recetas familiares y técnicas modernas."}]}','{"order":["E","F","A","D","C","B"],"policy":{"accents":"strict"}}','published','L3-U20-E12',12,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-14','es3-cocina','order','reading','בונים רצף','המשפטים התערבבו. סדרו אותם לפי הרצף ההגיוני של הטקסט וכתבו את רצף האותיות.','auto','{"lines":[{"id":"A","text":"Antes de abrir el restaurante, había probado cada plato muchas veces."},{"id":"B","text":"Una chef ha creado un menú que combina recetas familiares con técnicas modernas."},{"id":"C","text":"Los ingredientes son preparados localmente y la chef recomienda que los clientes prueben el menú de temporada."}]}','{"order":["B","A","C"],"policy":{"accents":"strict"}}','published','L3-U20-E13',13,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-15','es3-cocina','open','writing','עמדה אישית','החליטו אם אתם מסכימים או לא. כתבו חמישה משפטים לפי המבנה: עמדה, סיבה, דוגמה, הסתייגות ומסקנה. בדקו מול המודל.','self','{"prompt":"","brief":"Aprender sobre cocina es importante para usar el español en la vida real."}','{"models":["Creo que aprender sobre cocina es importante para usar el español en la vida real. porque me ayuda a comunicarme. Por ejemplo, puedo usar este tema en una conversación real. Sin embargo, necesito practicar más vocabulario. En conclusión, voy a repasar la unidad otra vez."],"criteria":"יש עמדה, porque, דוגמה, sin embargo ומסקנה."}','published','L3-U20-E14',14,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-16','es3-cocina','selftest','mixed','מבחן עצמי מורחב','פתרו בלי מילון: השלמות אוצר מילים והטיות פעלים. אם פחות משמונה תשובות נכונות, כדאי לחזור לשליפת המילים, לתיקון הטעויות ולהטיית הפעלים בנושא הזה.','auto','{"items":[{"prompt":"קולינריה / גסטרונומיה = ___","input":"text"},{"prompt":"זיהום צולב = ___","input":"text"},{"prompt":"המתכון = ___","input":"text"},{"prompt":"גלובליזציה = ___","input":"text"},{"prompt":"**el restaurante** · reconocer · este mes","input":"text"},{"prompt":"**ellos** · devolver · ayer","input":"text"},{"prompt":"**yo** · recomendar · si me preguntaran","input":"text"},{"prompt":"**un cliente** · pedir · ahora","input":"text"},{"prompt":"**los clientes** · probar · la chef recomienda que","input":"text"},{"prompt":"**los ingredientes** · preparar · actualmente","input":"text"}]}','{"items":[{"display":"La gastronomía","answers":["La gastronomía"],"policy":{"accents":"lenient"}},{"display":"La contaminación cruzada","answers":["La contaminación cruzada"],"policy":{"accents":"lenient"}},{"display":"La receta","answers":["La receta"],"policy":{"accents":"lenient"}},{"display":"La globalización","answers":["La globalización"],"policy":{"accents":"lenient"}},{"display":"ha sido reconocido","answers":["ha sido reconocido"]},{"display":"devolvieron","answers":["devolvieron"]},{"display":"recomendaría","answers":["recomendaría"]},{"display":"pide","answers":["pide"]},{"display":"prueben","answers":["prueben"]},{"display":"son preparados","answers":["son preparados"]}],"policy":{"accents":"strict"}}','published','L3-U20-E15',15,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-17','es3-cocina','open','writing','סיכום ובדיקה סופית','סכמו את קטע הקריאה בשלושה משפטים, ואז הוסיפו משפט אחד שמקשר את הנושא לחיים שלכם. בדקו לפי המודל והרשימה שבמשוב.','self','{"prompt":"","brief":""}','{"models":["Una chef ha creado un menú que combina recetas familiares con técnicas modernas. Antes de abrir el restaurante, había probado cada plato muchas veces."],"criteria":"3 משפטי סיכום נאמנים לטקסט, משפט אישי אחד, פעלים מוטים, סדר זמנים הגיוני ונקודה בסוף כל משפט."}','published','L3-U20-E16',16,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-18','es3-cocina','bank','vocab','אוצר מילים במחזור נוסף','השלימו את עשרת המשפטים בעזרת המחסן. אלה מילים מן השיעור שהופיעו פחות בתרגילים הקודמים. כל מילה משמשת פעם אחת.','auto','{"items":[{"prompt":"¿Los clientes deberían poder ___ en un restaurante?","input":"bank"},{"prompt":"La comida ___ debería ser más popular entre los jóvenes.","input":"bank"},{"prompt":"Creo que ___ israelí es increíble.","input":"bank"},{"prompt":"¿Los camareros deberían ___ platos a los clientes?","input":"bank"},{"prompt":"Este restaurante es más ___ que el otro.","input":"bank"},{"prompt":"עבודת יד / אומנותי = ___","input":"bank"},{"prompt":"המרקם = ___","input":"bank"},{"prompt":"ביתי = ___","input":"bank"},{"prompt":"המקום / העסק = ___","input":"bank"},{"prompt":"חדשני = ___","input":"bank"}],"wordbank":["Innovador","Tradicional","Recomendar","Acogedor","La comida callejera","Artesanal","Devolver un plato","El establecimiento","La textura","Casero"]}','{"items":[{"display":"Devolver un plato","answers":["Devolver un plato"]},{"display":"Tradicional","answers":["Tradicional"]},{"display":"La comida callejera","answers":["La comida callejera"]},{"display":"Recomendar","answers":["Recomendar"]},{"display":"Acogedor","answers":["Acogedor"]},{"display":"Artesanal","answers":["Artesanal"]},{"display":"La textura","answers":["La textura"]},{"display":"Casero","answers":["Casero"]},{"display":"El establecimiento","answers":["El establecimiento"]},{"display":"Innovador","answers":["Innovador"]}],"policy":{"accents":"strict"}}','published','L3-U20-E17',17,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-19','es3-cocina','conjugation','grammar','פעלים בתוך הקשר','השלימו כל משפט בצורה המתאימה של הפועל. קראו את המשפט כולו לפני הבחירה בזמן או במבנה.','auto','{"items":[{"prompt":"Este año, la chef ___.","input":"text","hint":"crear"},{"prompt":"Antes de abrir, ella ___.","input":"text","hint":"probar"},{"prompt":"Actualmente, los ingredientes ___.","input":"text","hint":"preparar"},{"prompt":"La chef recomienda que los clientes ___ el menú de temporada.","input":"text","hint":"probar"},{"prompt":"Un cliente ___ ahora.","input":"text","hint":"pedir"},{"prompt":"Si me preguntaran, yo ___.","input":"text","hint":"recomendar"},{"prompt":"Ayer, ellos ___.","input":"text","hint":"devolver"},{"prompt":"Este mes, el restaurante ___.","input":"text","hint":"reconocer"}]}','{"items":[{"display":"ha creado","answers":["ha creado"]},{"display":"había probado","answers":["había probado"]},{"display":"son preparados","answers":["son preparados"]},{"display":"prueben","answers":["prueben"]},{"display":"pide","answers":["pide"]},{"display":"recomendaría","answers":["recomendaría"]},{"display":"devolvieron","answers":["devolvieron"]},{"display":"ha sido reconocido","answers":["ha sido reconocido"]}],"policy":{"accents":"strict"}}','published','L3-U20-E18',18,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-cocina-20','es3-cocina','reading','reading','קריאה מסכמת · שאלות הבנה','קראו את הטקסט וענו בספרדית במשפט קצר.','auto','{"items":[{"prompt":"¿Qué preparó con las cáscaras?","input":"sentence"},{"prompt":"¿En qué convirtió el pan del día anterior?","input":"sentence"},{"prompt":"¿Por qué cambiaron de opinión los clientes?","input":"sentence"},{"prompt":"¿Qué recomienda la chef sobre los ingredientes?","input":"sentence"},{"prompt":"¿Qué prefiere que hagan los clientes?","input":"sentence"}],"text":"Una chef diseñó un menú para aprovechar ingredientes que normalmente se descartaban. Preparó caldo con cáscaras limpias, convirtió el pan del día anterior en migas crujientes y ofreció porciones de dos tamaños. Al principio algunos clientes desconfiaron, pero cambiaron de opinión cuando el personal explicó el proceso y les permitió probar una pequeña muestra.\n\nLa chef recomienda que los ingredientes sean frescos y que cada parte útil se aproveche antes de comprar más. Para preparar el menú, el equipo tiene que planificar las cantidades y debe conservar correctamente los alimentos. El resultado combina una cocina tradicional y casera con técnicas innovadoras: una salsa cremosa acompaña un plato picante, mientras que el pan artesanal aporta una textura crujiente. Algunos críticos lo consideraron demasiado sofisticado y dijeron que estaba sobrevalorado; otros describieron el restaurante como acogedor e inolvidable. La chef prefiere que los clientes prueben primero y opinen después. Insiste en que un menú sustentable no tiene que ser menos exigente ni menos gourmet.\n\nEl nuevo menú redujo los residuos y obligó al equipo a ser más creativo. Los clientes comenzaron a preguntar por el origen de los ingredientes y algunos intentaron aplicar las mismas ideas en casa. Para la chef, ese interés fue el mejor resultado."}','{"items":[{"display":"Caldo","answers":["Caldo"]},{"display":"En migas crujientes","answers":["En migas crujientes"]},{"display":"Porque el personal explicó el proceso y les permitió probar una muestra","answers":["Porque el personal explicó el proceso y les permitió probar una muestra"]},{"display":"Que sean frescos y que se aproveche cada parte útil","answers":["Que sean frescos y que se aproveche cada parte útil"]},{"display":"Que prueben primero y opinen después","answers":["Que prueben primero y opinen después"]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-U20-E19',19,1788220800000,1788220800000);
INSERT OR IGNORE INTO topics (id,level_id,cycle_id,title_he,title_target,objective,objective_source,skills,grammar,explanation,vocab,self_check,links,status,source_ref,sort,created_at,updated_at) VALUES ('es3-checkpoint-1','es-3','es-3-review','חזרה משולבת: נסיעות וחוויות · כסף וחיסכון · קריירה והתפתחות אישית · בינה מלאכותית','Repaso mixto: Viajes · Dinero y ahorros · Carrera y desarrollo personal · Inteligencia artificial','לחזור בערבוביה על אוצר מילים, פעלים וקריאה מכמה נושאים ברמה.','derived','[{"he":"שליפת אוצר מילים","target":"Vocabulario"},{"he":"פעלים בהקשר","target":"Verbos en contexto"}]','[]','{"rules":[],"examples":[],"tips":[],"mistakes":[]}','[]','[]','[]','published','workbook L3 checkpoint-1',120,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-checkpoint-1-01','es3-checkpoint-1','recall','vocab','שליפה מצטברת','כתבו בספרדית בלי להיעזר במילון. לאחר הבדיקה כתבו מחדש רק את המילים שלא נשלפו מיד.','auto','{"items":[{"prompt":"טיול = ___","input":"text"},{"prompt":"טיסה = ___","input":"text"},{"prompt":"להוציא כסף = ___","input":"text"},{"prompt":"הוצאות = ___","input":"text"},{"prompt":"עבודה = ___","input":"text"},{"prompt":"הצלחה = ___","input":"text"},{"prompt":"ללמוד = ___","input":"text"},{"prompt":"אנדרואיד = ___","input":"text"}]}','{"items":[{"display":"viaje","answers":["viaje"]},{"display":"vuelo","answers":["vuelo"]},{"display":"Gastar","answers":["Gastar"]},{"display":"Gastos","answers":["Gastos"]},{"display":"Trabajo","answers":["Trabajo"]},{"display":"Éxito","answers":["Éxito"]},{"display":"Aprender","answers":["Aprender"]},{"display":"Android","answers":["Android"]}],"policy":{"accents":"lenient"}}','published','L3-checkpoint-1',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-checkpoint-1-02','es3-checkpoint-1','conjugation','grammar','פעלים בהקשר','השלימו את הפועל לפי המשפט כולו. שימו לב ליחס בין זמן, תנאי וסבילות.','auto','{"items":[{"prompt":"Antes de reservar, Marta ___.","input":"text","hint":"comparar"},{"prompt":"Si hubiera controlado sus gastos, él ___.","input":"text","hint":"evitar"},{"prompt":"Mañana, yo ___.","input":"text","hint":"actualizar"},{"prompt":"Actualmente, los datos ___.","input":"text","hint":"analizar"},{"prompt":"Ayer, tú ___.","input":"text","hint":"llegar"},{"prompt":"El sistema ___ desde su lanzamiento.","input":"text","hint":"mejorar"}]}','{"items":[{"display":"había comparado","answers":["había comparado"]},{"display":"habría evitado","answers":["habría evitado"]},{"display":"actualizaré","answers":["actualizaré"]},{"display":"son analizados","answers":["son analizados"]},{"display":"llegaste","answers":["llegaste"]},{"display":"ha mejorado","answers":["ha mejorado"]}],"policy":{"accents":"strict"}}','published','L3-checkpoint-1',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-checkpoint-1-03','es3-checkpoint-1','reading','reading','קריאה והוכחה','קראו את הקטע, ענו בספרדית וסמנו את הראיה בטקסט.','auto','{"items":[{"prompt":"¿De qué ha regresado Clara?","input":"sentence"},{"prompt":"¿Qué había hecho antes de salir?","input":"sentence"},{"prompt":"¿Qué hará ahora?","input":"sentence"}],"text":"Clara ha regresado de un viaje y quiere organizar mejor sus próximos meses. Antes de salir había ahorrado, pero durante el viaje gastó más de lo previsto. Ahora actualizará su currículum y aprenderá a usar una herramienta de inteligencia artificial que protege sus datos."}','{"items":[{"display":"Ha regresado de un viaje.","answers":["Ha regresado de un viaje."]},{"display":"Había ahorrado.","answers":["Había ahorrado."]},{"display":"Actualizará su currículum y aprenderá a usar una herramienta de inteligencia artificial.","answers":["Actualizará su currículum y aprenderá a usar una herramienta de inteligencia artificial."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-checkpoint-1',2,1788220800000,1788220800000);
