INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-checkpoint-5-03','es3-checkpoint-5','reading','reading','קריאה והוכחה','קראו את הקטע, ענו בספרדית וסמנו את הראיה בטקסט.','auto','{"items":[{"prompt":"¿Por dónde viajó Amir?","input":"sentence"},{"prompt":"¿Qué descubrió durante el viaje?","input":"sentence"},{"prompt":"¿Qué creó al volver?","input":"sentence"}],"text":"Después del servicio, Amir emprendió un gran viaje por varios países hispanohablantes. Probó recetas regionales, escuchó acentos diferentes y anotó expresiones que nunca había estudiado. Al volver, creó un pequeño proyecto gastronómico que combina cocina, lengua e historias familiares."}','{"items":[{"display":"Por varios países hispanohablantes.","answers":["Por varios países hispanohablantes."]},{"display":"Recetas regionales, acentos diferentes y expresiones nuevas.","answers":["Recetas regionales, acentos diferentes y expresiones nuevas."]},{"display":"Un proyecto gastronómico que combina cocina, lengua e historias familiares.","answers":["Un proyecto gastronómico que combina cocina, lengua e historias familiares."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-checkpoint-5',2,1788220800000,1788220800000);
