INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-final-diagnostic-01','es3-final-diagnostic','recall','vocab','אוצר מילים','תרגמו לספרדית. נקודה אחת לכל תשובה מדויקת.','auto','{"items":[{"prompt":"מטען = ___","input":"text"},{"prompt":"חיים מקצועיים = ___","input":"text"},{"prompt":"מציאות חלופית = ___","input":"text"},{"prompt":"סטודנט / תלמיד = ___","input":"text"},{"prompt":"סגנון עקיף = ___","input":"text"},{"prompt":"רשתות חברתיות = ___","input":"text"},{"prompt":"מגוון ביולוגי = ___","input":"text"},{"prompt":"גיוון = ___","input":"text"},{"prompt":"עקשן = ___","input":"text"},{"prompt":"ציפייה חברתית = ___","input":"text"}]}','{"items":[{"display":"equipaje","answers":["equipaje"]},{"display":"Vida laboral","answers":["Vida laboral"]},{"display":"Realidad alternativa","answers":["Realidad alternativa"]},{"display":"estudiante","answers":["estudiante"]},{"display":"Estilo indirecto","answers":["Estilo indirecto"]},{"display":"Redes sociales","answers":["Redes sociales"]},{"display":"Biodiversidad","answers":["Biodiversidad"]},{"display":"Diversidad","answers":["Diversidad"]},{"display":"Testardo","answers":["Testardo"]},{"display":"Expectativa social","answers":["Expectativa social"]}],"policy":{"accents":"lenient"}}','published','L3-final-diagnostic',0,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-final-diagnostic-02','es3-final-diagnostic','conjugation','grammar','פעלים בהקשר','השלימו את צורת הפועל המתאימה. נקודה אחת לכל תשובה.','auto','{"items":[{"prompt":"Antes de reservar, Marta ___.","input":"text","hint":"comparar"},{"prompt":"Si trabajaran mejor, ellos ___.","input":"text","hint":"ascender"},{"prompt":"Si tuvieras otra oportunidad, tú ___.","input":"text","hint":"elegir"},{"prompt":"El cambio ___ con más inversión.","input":"text","hint":"ser"},{"prompt":"El gobierno ___ según la portavoz.","input":"text","hint":"anunciar"},{"prompt":"Mañana, la estrategia ___.","input":"text","hint":"evaluar"},{"prompt":"Mañana, la ley ___.","input":"text","hint":"aprobar"},{"prompt":"En aquella hipótesis irreal, su familia ___ antes.","input":"text","hint":"mudarse"},{"prompt":"Ellos ___ habitualmente.","input":"text","hint":"trabajar"},{"prompt":"Actualmente, nosotros ___.","input":"text","hint":"recomendar"}]}','{"items":[{"display":"había comparado","answers":["había comparado"]},{"display":"ascenderían","answers":["ascenderían"]},{"display":"elegirías","answers":["elegirías"]},{"display":"sería","answers":["sería"]},{"display":"anunciaría","answers":["anunciaría"]},{"display":"será evaluada","answers":["será evaluada"]},{"display":"debería aprobarse","answers":["debería aprobarse"]},{"display":"se hubiera mudado","answers":["se hubiera mudado"]},{"display":"trabajaban","answers":["trabajaban"]},{"display":"recomendamos","answers":["recomendamos"]}],"policy":{"accents":"strict"}}','published','L3-final-diagnostic',1,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-final-diagnostic-03','es3-final-diagnostic','correction','grammar','תיקון שגיאות','כתבו מחדש כל משפט בצורה תקינה.','auto','{"items":[{"prompt":"He viajé a Perú tres veces.","input":"sentence"},{"prompt":"Si podría mudarme, investigaría el océano.","input":"sentence"},{"prompt":"La portavoz dijo que el gobierno anunciará el plan al día siguiente.","input":"sentence"},{"prompt":"Se han instalar nuevos puntos de reciclaje.","input":"sentence"},{"prompt":"Los abuelos llegaron y trabajaron muchas horas habitualmente.","input":"sentence"}]}','{"items":[{"display":"He viajado a Perú tres veces.","answers":["He viajado a Perú tres veces."]},{"display":"Si pudiera mudarme, investigaría el océano.","answers":["Si pudiera mudarme, investigaría el océano."]},{"display":"La portavoz dijo que el gobierno anunciaría el plan al día siguiente.","answers":["La portavoz dijo que el gobierno anunciaría el plan al día siguiente."]},{"display":"Se han instalado nuevos puntos de reciclaje.","answers":["Se han instalado nuevos puntos de reciclaje."]},{"display":"Los abuelos llegaron y trabajaban muchas horas.","answers":["Los abuelos llegaron y trabajaban muchas horas."]}],"policy":{"accents":"strict"}}','published','L3-final-diagnostic',2,1788220800000,1788220800000);
INSERT OR IGNORE INTO exercises (id,topic_id,kind,skill,title,instructions,mode,body,key_json,status,source_ref,sort,created_at,updated_at) VALUES ('es3-final-diagnostic-04','es3-final-diagnostic','reading','reading','הבנת הנקרא','קראו וענו בספרדית במשפט מלא.','auto','{"items":[{"prompt":"¿Dónde trabajaba Valeria?","input":"sentence"},{"prompt":"¿Con qué había soñado?","input":"sentence"},{"prompt":"¿Cuándo aceptó el empleo remoto?","input":"sentence"},{"prompt":"¿En qué proyecto participa?","input":"sentence"},{"prompt":"¿Qué no habría descubierto si no hubiera tomado la decisión?","input":"sentence"}],"text":"Durante el último año, Valeria ha cambiado varias áreas de su vida. Antes trabajaba en una gran ciudad, pero había soñado con vivir cerca de la naturaleza. Después de ahorrar y comparar distintas opciones, aceptó un empleo remoto y se mudó a una comunidad pequeña. Allí participa en un proyecto educativo que usa tecnología responsable, organiza encuentros culturales y promueve hábitos sustentables. Si no hubiera tomado aquella decisión, no habría descubierto una forma de vida más tranquila ni habría conocido tantas historias diferentes."}','{"items":[{"display":"Trabajaba en una gran ciudad.","answers":["Trabajaba en una gran ciudad."]},{"display":"Había soñado con vivir cerca de la naturaleza.","answers":["Había soñado con vivir cerca de la naturaleza."]},{"display":"Después de ahorrar y comparar distintas opciones.","answers":["Después de ahorrar y comparar distintas opciones."]},{"display":"En un proyecto educativo que usa tecnología responsable.","answers":["En un proyecto educativo que usa tecnología responsable."]},{"display":"No habría descubierto una vida más tranquila ni habría conocido tantas historias diferentes.","answers":["No habría descubierto una vida más tranquila ni habría conocido tantas historias diferentes."]}],"policy":{"accents":"lenient","match":"content"}}','published','L3-final-diagnostic',3,1788220800000,1788220800000);
